DECLARE
  c jsonb := $cj$[{"title":"Я не держу зла","full_story":"Он разошёлся с ней так громко, что весь общий круг ждёт скандала, — а он на людях говорит одно: я не сержусь. Ночью приходит сон: она среди чужих огней, и на её сердце свернулась змея. Он понимает: её яд — не его вина, и не его дело. Вместо мести он совершает тихое: выкапывает могилу и хоронит туда своё чувство, целиком, без оговорок. Наутро он свободен — и это выглядит почти как жестокость.","hero_pov":"бросивший разборки человек, хоронящий чувство","central_conflict":"не держать зла, когда сердце разбито","emotional_arc":"от сдавленной обиды к холодной свободе после похорон любви","ending_direction":"любовь похоронена — человек уходит без гроша зла","hook_direction":"я не держу зла — и это труднее мести","genres":["Блюз","Классика"],"moods":["Уверенность","Боль"],"energy":"Низкая","themes":["прощение","Любовь"],"generator_brief":"Сдержанный блюз с одним роялем и лёгким тремоло: куплеты — спокойные, без надрыва, припев — тихая, стальная ясность.","generator_story":"После громкого разрыва он говорит одно: не сержусь. Ночью снится змея на её сердце — её яд не его дело. Вместо мести он хоронит чувство целиком — и наутро свободен, почти жестоко.","primary_genre":"Блюз","primary_mood":"Уверенность","primary_theme":"прощение","story_shelf":"Любовные сцены","conflict_key":"не-держать-зла-разбитым-сердцем","image_key":"змея-на-сердце-во-сне","turn_key":"хороню-любовь-заживо","hook_key":"я-не-держу-зла","sort_order":"1132","original_key":"heinrich-heine|ich-grolle-nicht","author_name":"Генрих Гейне","original_title":"Ich grolle nicht","original_language":"German","origin_country":"Германия","original_year":"1827","source_url":"https://de.wikisource.org/wiki/Lyrisches_Intermezzo","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1856.","music_adaptations":[],"source_synopsis":"Герой объявляет, что не держит зла на ушедшую возлюбленную, даже если сердце разрывается: он видел её во сне — с рядом обиженных и со змеёй на сердце. Свою вечную любовь он молча хоронит.","main_image":"змея на сердце любимой в ночном сне"},{"title":"Ночные птицы унесут","full_story":"Он ушёл в другую жизнь, оставив её ждать, и теперь слал ей письмо с ночными птицами: половина слов — покаяние, половина — счёт к ней. Он просит простить и тут же объясняет, что она была недостаточно терпеливой, будто это снимает с него половину вины. Птицы долетают до её окна, но ответа не будет: она читает упрёки между извинениями и закрывает ставни. Песня о человеке, который просит прощения так, что просит зря.","hero_pov":"бросивший семью муж, пишущий жене","central_conflict":"просить прощения и винить одним дыханием","emotional_arc":"от ночного порыва к горькому пониманию, что письмо бессильно","ending_direction":"ответа нет — ставни закрыты на его откровенность","hook_direction":"прости меня — я жду ответа","genres":["R&B","Классика"],"moods":["Уязвимость","Вина"],"energy":"Низкая","themes":["семья","Расставание"],"generator_brief":"Интимный R&B с приглушёнными клавишами и ночным городом в бэк-вокале: куплеты — шёпот оправданий, припев — двойной голос, извинение и упрёк в одном такте.","generator_story":"Он ушёл в другую жизнь и шлёт жене письмо с ночными птицами: просит прощения — и тут же упрекает, будто её нетерпение снимает половину вины. Она закрывает ставни: ответа не будет.","primary_genre":"R&B","primary_mood":"Уязвимость","primary_theme":"семья","story_shelf":"Любовные сцены","conflict_key":"письмо-измена-и-упрёк-пополам","image_key":"птицы-над-спящим-городом-с-письмом","turn_key":"просить-и-винить-одним-дыханием","hook_key":"прости-меня-я-жду-ответа","sort_order":"1133","original_key":"paul-verlaine|birds-in-the-night","author_name":"Поль Верлен","original_title":"Birds in the Night","original_language":"French","origin_country":"Франция","original_year":"1874","source_url":"https://fr.wikisource.org/wiki/Romances_sans_paroles","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1896.","music_adaptations":[],"source_synopsis":"Бросивший беременную жену поэт пишет ей из-за границы ночное письмо, в котором извинения перемешаны с упрёками: он просит прощения и тут же напоминает, что ей не хватило терпения. Ответа не приходит.","main_image":"ночные птицы несут письмо над спящим городом"},{"title":"Воротившись домой","full_story":"Год на чужой стороне выучил его молчать: он спускается с гор в свою долину, где колокола и дым те же, а он — нет. У ворот его узнают без вопросов, и голос матери оказывается главным переводчиком с языка его молчания. Он привёз мешок несказанных слов — о том, чего не хватало там, где он был, — и их никто не спросит, пока он сам не начнёт. Дом расшифровывает его тиши: за столом, при свече, самыми простыми словами.","hero_pov":"вернувшийся из дальнейшей командировки человек","central_conflict":"родина-встречает-молчание-привозных-слов","emotional_arc":"от усталости чужбины к тихому переводу себя на родной язык","ending_direction":"дом понимает его без вопросов — отдых вместо отчёта","hook_direction":"примите меня без отчёта","genres":["Соул","Классика"],"moods":["Надежда","Тепло"],"energy":"Средняя","themes":["дом","семья"],"generator_brief":"Тёплый соул с колокольным фоном и медленным басом: куплеты — шаги спускающейся дороги, припев — распахнутый дом, где понимают без слов.","generator_story":"Год на чужбине выучил его молчать: он спускается с гор в свою долину с мешком несказанных слов. У ворот узнают без вопросов, и за свечой дом переводит его тишину простыми словами.","primary_genre":"Соул","primary_mood":"Надежда","primary_theme":"дом","story_shelf":"Трагические истории","conflict_key":"гость-на-своей-родине","image_key":"материнский-голос-у-ворот","turn_key":"дом-переводит-его-молчание","hook_key":"примите-меня-без-отчёта","sort_order":"1134","original_key":"friedrich-hoelderlin|heimkunft","author_name":"Фридрих Гёльдерлин","original_title":"Heimkunft (An die Verwandten)","original_language":"German","origin_country":"Германия","original_year":"1801","source_url":"https://www.tha.de/~harsch/germanica/Chronologie/19Jh/Hoelderlin/hoe_0140.html","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1843.","music_adaptations":[],"source_synopsis":"Странник возвращается из сурового севера вниз, в родную долину: знакомые голоса, материнский голос у ворот. Он привёз с собой слова, которые никому не объяснить, — и родные должны помочь ему расшифровать то, что он принёс.","main_image":"материнский голос у ворот родной долины"},{"title":"Скрытая комната","full_story":"Мир зовёт его подарками, праздниками и чьими-то горями, а он просит оставить его в своей тайной комнате, где радость и боль принадлежат только ему. Он не враг людям: он любит землю тихо, издалека, и сам не знает, о чём иногда тоскует. Когда станет совсем тяжко, он выйдет, обнимет мир, как потерянного брата, и снова закроет дверь. Песня о праве спрятаться, чтобы остаться добрым.","hero_pov":"человек, закрытый от мира в своём углу","central_conflict":"мир стучится в скрытый угол","emotional_arc":"от чужих зовов к тихому владению своей радостью и болью","ending_direction":"один выход к людям — объятие — и снова своя комната","hook_direction":"оставь меня, мир — я дома","genres":["Блюз","Классика"],"moods":["Спокойствие","Нежность"],"energy":"Низкая","themes":["дом","самопринятие"],"generator_brief":"Тихий блюз без ударных: тёплый гул органа, дыхание вокала на грани шёпота, припев — как погашенная свеча в собственном окне.","generator_story":"Мир зовёт его подарками, а он просит оставить его в тайной комнате, где радость и боль — только его. Когда совсем тяжко, он выйдет, обнимет мир, как потерянного брата, и снова закроет дверь.","primary_genre":"Блюз","primary_mood":"Спокойствие","primary_theme":"дом","story_shelf":"Трагические истории","conflict_key":"мир-стучится-в-скрытый-угол","image_key":"тайная-комната-сердца","turn_key":"радость-и-боль-остаются-моими","hook_key":"оставь-меня-мир-я-дома","sort_order":"1135","original_key":"eduard-moerike|verborgenheit","author_name":"Эдуард Мёрике","original_title":"Verborgenheit","original_language":"German","origin_country":"Германия","original_year":"1832","source_url":"https://oxfordsong.org/song/verborgenheit","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1875.","music_adaptations":[],"source_synopsis":"Поэт просит мир оставить его в покое: не заманивать любовными дарами, дать сердцу одному владеть своей радостью и болью. Он едва сам понимает, о чём тоскует, но радость вспыхивает сквозь тяжесть — и это его личное, скрытое от чужих глаз.","main_image":"тайная комната сердца, куда не стучатся"},{"title":"Рыцарь на посту","full_story":"Над долиной на скале сидит старый рыцарь: борода вросла в камень, в зале до сих пор висит выцветший венок с праздника, которого уже не было. Внизу гремит чужая свадьба — вино, яркие скрипки, смех через двор. Молодой жених с невестой проезжают прямо мимо его окна с песней, и в этот миг старый скрипач внизу берёт мотив так таинственно и горько, что веселье на секунду темнеет. Песня о том, что над каждым нашим праздником стоит чей-то несбывшийся.","hero_pov":"гость свадьбы, заметивший замок на скале","central_conflict":"вечная вахта против живой свадьбы","emotional_arc":"от чужого веселья к горькой тени несбывшегося праздника","ending_direction":"свадьба проезжает мимо — пост не покинут и поныне","hook_direction":"он всё ещё на посту","genres":["Кантри","Фолк"],"moods":["Одиночество","Мечтательность"],"energy":"Низкая","themes":["ночь","память"],"generator_brief":"Балладное кантри с гулкой гитарой и далёкой скрипкой: куплеты — камень и дождь, припев — яркая свадьба, которая на мгновение темнеет от горького мотива.","generator_story":"Гость свадьбы замечает на скале замок: рыцарь с бородой, вросшей в камень, всё держит пост. Внизу гремит чужое веселье и проезжает мимо его окна — над каждым праздником стоит чей-то несбывшийся.","primary_genre":"Кантри","primary_mood":"Одиночество","primary_theme":"ночь","story_shelf":"Трагические истории","conflict_key":"вечная-вахта-против-живой-свадьбы","image_key":"окаменевший-рыцарь-на-скале","turn_key":"свадьба-проезжает-мимо-его-окна","hook_key":"он-всё-ещё-на-посту","sort_order":"1136","original_key":"joseph-freiherr-von-eichendorff|auf-einer-burg","author_name":"Йозеф фон Эйхендорф","original_title":"Auf einer Burg","original_language":"German","origin_country":"Германия","original_year":"1837","source_url":"https://oxfordsong.org/song/auf-einer-burg","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1857.","music_adaptations":[],"source_synopsis":"Старый рыцарь уснул на вахте в замке на скале и окаменел на сто лет: дождь проходит сквозь решётку, в зале висит давно выцветший цветочный венок. Внизу в долине гремит свадьба, и молодые с песней проезжают мимо его окна, а старый скрипач играет так таинственно и горько, что веселье темнеет.","main_image":"окаменевший рыцарь на вахте над чужой свадьбой"},{"title":"Полночный бал на озере","full_story":"В полночь с горы спускаются огни, и гладкое озеро вдруг распахивает зеркально-зелёные двери: водяные девы выходят на воду и кружат так, что не рождается ни единой ряби. Юноша за кустами засмотрелся слишком близко — и весь бал замирает: духи чувствуют живой взгляд. По дрожащей лестнице они уходят в подводное царство с гаснущими огнями, и озеро снова становится просто озером. Песня о том, что тайное празднично, пока его не раскрыли.","hero_pov":"юноша, подсмотревший тайный праздник","central_conflict":"любопытство против тайного праздника","emotional_arc":"от заворожённого восхищения к одинокой тишине после исчезновения","ending_direction":"праздник ушёл под воду — осталась чёрная гладь","hook_direction":"не выдавай себя — смотри","genres":["Кантри","Фолк"],"moods":["Ирония","Напряжение"],"energy":"Высокая","themes":["ночь","Природа"],"generator_brief":"Весёлая народная баллада с постукиваниями и свистом: куплеты — крадущиеся шаги и факельные огни, припев — вихрь танца, который вдруг обрывается тишиной.","generator_story":"В полночь озеро распахивает зелёные двери, и водяные девы кружат без единой ряби. Юноша засмотрелся слишком близко — бал замирает, духи уходят под воду: тайное празднично, пока не раскрыто.","primary_genre":"Кантри","primary_mood":"Ирония","primary_theme":"ночь","story_shelf":"Юмор: семейные драмы","conflict_key":"любопытство-против-тайного-праздника","image_key":"факельная-процессия-над-озером","turn_key":"подглядевший-остался-один","hook_key":"не-выдавай-себя-смотри","sort_order":"1137","original_key":"eduard-moerike|die-geister-am-mummelsee","author_name":"Эдуард Мёрике","original_title":"Die Geister am Mummelsee","original_language":"German","origin_country":"Германия","original_year":"1829","source_url":"https://www.tha.de/~harsch/germanica/Chronologie/19Jh/Moerike/moe_g38g.html","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1875.","music_adaptations":[],"source_synopsis":"В полночь с горы спускается факельная процессия, и озеро распахивает свои двери: русалки выходят на воду, скользят без ряби и танцуют, а затем ныряют по дрожащей лестнице в подводное царство с призрачными огнями. Увидев любопытного человека, духи исчезают.","main_image":"факельная процессия над гладким ночным озером"},{"title":"Карусель в Люксембургском саду","full_story":"Он стоит за оградой и смотрит, как кружит пёстрая карусель: кони, слоны, львы — и дети, взлетевшие на них, старше и меньше своих лет. Круг никуда не едет — и в этом всё счастье: музыка, ветер в лицо, смех наперерез. Музыка обрывается, дети спрыгивают на гравий, и парк выпускает их во взрослую землю. Он помнит, что и его так выпускали, — и всё же просит закружить ещё раз.","hero_pov":"взрослый за оградой детской карусели","central_conflict":"круг, который никуда не едет, против взрослой земли","emotional_arc":"от заворожённого счастья к выпуску из круга и просьбе о ещё одном обороте","ending_direction":"карусель остановилась — просят закружить ещё раз","hook_direction":"закружи меня, карусель","genres":["Джаз","Классика"],"moods":["Эйфория","Радость"],"energy":"Высокая","themes":["детство","Время"],"generator_brief":"Кружащийся джаз-вальс с карусельным шарманом: инструменты вращаются по кругу, припев разгоняется — и обрывается на середине оборота.","generator_story":"Взрослый смотрит за оградой, как дети взлетают на пёстрой карусели, — круг никуда не едет, и в этом всё счастье. Музыка обрывается, и он, помня, как его самого выпускали, просит закружить ещё раз.","primary_genre":"Джаз","primary_mood":"Эйфория","primary_theme":"детство","story_shelf":"Трагические истории","conflict_key":"круг-который-никуда-не-едет","image_key":"пёстрые-кони-на-карусели","turn_key":"музыка-обрывается-дети-на-земле","hook_key":"закружи-меня-карусель","sort_order":"1138","original_key":"rainer-maria-rilke|das-karussell","author_name":"Райнер Мария Рильке","original_title":"Das Karussell (Jardin du Luxembourg)","original_language":"German","origin_country":"Германия","original_year":"1906","source_url":"https://de.wikisource.org/wiki/Das_Karussell","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1926.","music_adaptations":[],"source_synopsis":"Наблюдатель смотрит, как в парижском саду кружит карусель: расписные кони, слоны и львы несут детей, весь круг идёт без цели. Музыка обрывается — дети спрыгивают, и парк возвращает их обычной земле.","main_image":"пёстрые кони на карусели в парижском саду"},{"title":"Под сиренью на закате","full_story":"Он включает старый мотив — тот самый, которому не нужно громких имён, — и садится у окна. Часы летят мимо, не жалея его бледного лба, и за звуком отворяется вечер детства: он стоит под сиренью, бледный, со сплетёнными руками, и ждёт любовь на закате — ту, что не пришла. Взрослые дни — длинные и блестящие, но то ожидание было длиннее всей его жизни. Песня просит ветер давних снов принести хотя бы ветку того дерева.","hero_pov":"взрослый человек у окна со старой мелодией","central_conflict":"взрослые часы против вечера детства","emotional_arc":"от музыкальной ностальгии к несостоявшемуся ожиданию под сиренью","ending_direction":"просить ветер давних снов принести ветку того дерева","hook_direction":"сыграй ещё раз — я тот мальчик","genres":["Джаз","Классика"],"moods":["Ностальгия","Мечтательность"],"energy":"Низкая","themes":["детство","Память"],"generator_brief":"Дымный джаз с ленивой фортепианной темой: куплеты — часы, летящие мимо окна, припев — вдруг открывшийся тёплый вечер детства под сиренью.","generator_story":"Он включает старый мотив и садится у окна: за звуком отворяется вечер детства — под сиренью он ждёт любовь на закате, ту, что не пришла. То ожидание оказалось длиннее всей его взрослой жизни.","primary_genre":"Джаз","primary_mood":"Ностальгия","primary_theme":"детство","story_shelf":"Трагические истории","conflict_key":"взрослые-часы-против-вечера-детства","image_key":"сирень-на-закате-и-сплетённые-руки","turn_key":"мелодия-открывает-тот-вечер","hook_key":"сыграй-ещё-раз-я-тот-мальчик","sort_order":"1139","original_key":"gerard-de-nerval|fantaisie","author_name":"Жерар де Нерваль","original_title":"Fantaisie","original_language":"French","origin_country":"Франция","original_year":"1832","source_url":"https://fr.wikisource.org/wiki/Fantaisie_(Nerval)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1855.","music_adaptations":[],"source_synopsis":"Есть один старинный мотив, за который поэт отдал бы всех великих композиторов: когда он садится у окна слушать его, часы летят мимо, и перед ним встаёт вечер детства — ожидание первой любви под сиренью на закате. Он зовёт ветер давних снов принести ему хотя бы ветку того дерева.","main_image":"сирень на закате и сплетённые руки ждущего мальчика"},{"title":"Предупреждение выстрелом","full_story":"Красные солдаты входят в трактир, пьют его вино и привязывают дочь хозяина к спусковому крючку мушкета: пусть её разбойник приедет за ней — и угодит в ловушку. Всю ночь она слушает дорогу, вплетая в ожидание его обещание вернуться лунной ночью. На рассвете она слышит дальний стук копыт — и жмёт на курок: выстрел будит всю глушь и кричит ему «беги». Он разворачивает коня в темноту, и этот выстрел остаётся между ними навсегда.","hero_pov":"дочь трактирщика, привязанная к спусковому крючку","central_conflict":"враги ставят её между любимым и петлёй","emotional_arc":"от бессонного ожидания к последнему выстрелу как крику «беги»","ending_direction":"он услышал и ушёл в темноту — выстрел остался между ними","hook_direction":"беги, мой разбойник, беги","genres":["Эпик-рок","Кантри"],"moods":["Драйв","Боль"],"energy":"Взрывная","themes":["ожидание","любовь"],"generator_brief":"Скачущий эпик-рок с топотом копыт в ритме: куплеты — напряжённая тишина комнаты, припев — выстрел, который открывает ему дорогу в темноту.","generator_story":"Солдаты привязывают дочь трактирщика к спусковому крючку: пусть разбойник приедет — и попадёт в ловушку. На рассвете она жмёт курок: выстрел предупреждает его, и конь уходит в темноту.","primary_genre":"Эпик-рок","primary_mood":"Драйв","primary_theme":"ожидание","story_shelf":"Трагические истории","conflict_key":"враги-в-комнате-любимой","image_key":"девушка-на-спусковом-крючке","turn_key":"выстрел-как-предупреждение","hook_key":"беги-мой-разбойник-беги","sort_order":"1140","original_key":"alfred-noyes|the-highwayman","author_name":"Альфред Нойес","original_title":"The Highwayman","original_language":"English","origin_country":"Великобритания","original_year":"1906","source_url":"https://en.wikisource.org/wiki/The_Highwayman","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1958.","music_adaptations":[],"source_synopsis":"Разбойник обещает дочери трактирщика вернуться к ней «пурпурной луной». Красные солдаты привязывают девушку к спусковому крючку мушкета, чтобы заманить его. Всю ночь она ждёт его стука копыт — и в последний момент сама жмёт на курок, чтобы выстрел разбудил глушь и увёл его от петли.","main_image":"девушка, привязанная к спусковому крючку, слушает дорогу"},{"title":"Старые корабли","full_story":"Он видел, как старые корабли идут спящими лебедями мимо деревни, которую до сих пор зовут Тир, — перегруженные своим свинцовым возрастом, глубоко осев в воду. Они возили шёлк и пряности, пережили пиратов и смену богов, а теперь плывут к скрытому солнцу, что окольцовывает Кипр огненным озером. Никто не хоронит корабли: они просто уходят в последний рейс с полным достоинством осадки. Песня о том, как красиво дорабатывать свой век.","hero_pov":"человек, стоявший на берегу у их последнего рейса","central_conflict":"отработанный век и последний красивый рейс","emotional_arc":"от тяжёлой осадки лет к достоинству ухода к скрытому солнцу","ending_direction":"старый корабль не тонет — он уходит спящим лебедем","hook_direction":"плыть как лебеди — до самого заката","genres":["Джаз","Классика"],"moods":["Ностальгия","Мечтательность"],"energy":"Низкая","themes":["работа","Время"],"generator_brief":"Раскачивающийся джаз с медными на горизонте: ритм — тяжёлая осадка корабля, припев — распрямление лебедя перед закатной водой.","generator_story":"Старые корабли идут мимо деревни спящими лебедями: пережили пиратов и смену богов, а теперь уходят к скрытому солнцу. Никто их не хоронит — они плывут в последний рейс с достоинством осадки.","primary_genre":"Джаз","primary_mood":"Ностальгия","primary_theme":"работа","story_shelf":"Трагические истории","conflict_key":"отработавший-век-и-последний-рейс","image_key":"корабли-спят-как-лебеди","turn_key":"плывут-к-скрытому-солнцу","hook_key":"плыть-как-лебеди","sort_order":"1141","original_key":"james-elroy-flecker|the-old-ships","author_name":"Джеймс Элрой Флекер","original_title":"The Old Ships","original_language":"English","origin_country":"Великобритания","original_year":"1913","source_url":"https://www.theguardian.com/books/booksblog/2009/aug/24/james-elroy-flecker-old-ships","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1915.","music_adaptations":[],"source_synopsis":"Поэт видел, как старые корабли идут спящими лебедями мимо деревни, которую до сих пор зовут Тир: перегруженные свинцовым возрастом, глубоко осев, они идут к скрытому солнцу, что окольцовывает Кипр огненным озером, — через порты, где начинались и кончались их века.","main_image":"старые корабли, спящие лебедями на тяжёлой воде"},{"title":"Уголок чужого поля","full_story":"Он просит не оплакивать его, если не вернётся: где бы ни упал, этот клочок земли навсегда станет его, а значит — кусочком дома. Его дыхание вольётся в чужой воздух, тело станет богатством, наследством, оставленным земле, которая вырастила его. Всё, чем наградила его жизнь, — свет рек, улыбки родных, невидимые простые мелочи — он отдаёт этому полю. Умереть, по его счёту, — значит вернуться.","hero_pov":"молодой солдат, предвидящий свою смерть","central_conflict":"чужая земля становится домом","emotional_arc":"от предчувствия смерти к спокойному завещанию себя земле","ending_direction":"умереть — значит вернуться в землю, которая всех выращивает","hook_direction":"если я умру — это мой дом","genres":["Соул","Классика"],"moods":["Вдохновение","Надежда"],"energy":"Средняя","themes":["дом","Потеря"],"generator_brief":"Светлый соул с хором и далёкими струнами: куплеты — ровное завещание без надрыва, припев — тёплый, как земля, принимающая своего.","generator_story":"Молодой солдат просит не оплакивать его: где бы ни упал, тот клочок земли станет его — кусочком дома. Всё, что дала жизнь, — свет рек и улыбки родных — он отдаёт полю: умереть значит вернуться.","primary_genre":"Соул","primary_mood":"Вдохновение","primary_theme":"дом","story_shelf":"Трагические истории","conflict_key":"чужая-земля-станет-домом","image_key":"горсть-земли-навсегда-английская","turn_key":"дыхание-вольётся-в-чужой-воздух","hook_key":"если-я-умру-это-мой-дом","sort_order":"1142","original_key":"rupert-brooke|the-soldier","author_name":"Руперт Брук","original_title":"The Soldier","original_language":"English","origin_country":"Великобритания","original_year":"1914","source_url":"https://en.wikisource.org/wiki/The_Soldier_(Brooke)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1915.","music_adaptations":[],"source_synopsis":"Молодой солдат просит: если я умру, думай только одно — где-то на чужом поле будет клочок земли, навсегда ставший его родиной. Его тело станет богатством, оставленным чужой земле, а все радости, что дала ему жизнь, он отдаёт её воздуху и рекам.","main_image":"горсть чужой земли, ставшая домом навсегда"},{"title":"Список любимых мелочей","full_story":"Он садится и честно перечисляет всё, чем жил: белые тарелки, чисто блестящие в синих полосках, мокрые волосы после купанья, холодные руки в тёплых руках, вишни, корицу, дождь по крыше, шёпот чужих лестниц. Список длиннее всякой биографии — и так он узнаёт, что жизнь его была великой любовью, а не чередой дел. Каждая мелочь успела стать частью его тела. Он завещает перечень тем, кто ещё не начал свой.","hero_pov":"человек, составивший перечень всего, что любил","central_conflict":"взрослые годы против детского изобилия мелочей","emotional_arc":"от перечисления к открытию: жизнь была великой любовью","ending_direction":"передать список тем, кто ещё не начал свой","hook_direction":"любить всё простое — и хватит","genres":["R&B","Фолк"],"moods":["Вдохновение","Нежность"],"energy":"Высокая","themes":["детство","Память"],"generator_brief":"Живой R&B со счётом в ритме: куплеты — перечисление, как голос бегущего списка, припев — распахнутая благодарность всем простым вещам сразу.","generator_story":"Он перечисляет всё, чем жил: тарелки в синих полосках, вишни, корицу, дождь по крыше. Список длиннее биографии — так он узнаёт, что жизнь была великой любовью, и завещает его тем, кто не начал свой.","primary_genre":"R&B","primary_mood":"Вдохновение","primary_theme":"детство","story_shelf":"Трагические истории","conflict_key":"взрослые-годы-против-детского-изобилия","image_key":"белые-тарелки-в-синих-полосках","turn_key":"перечисляю-и-снова-жив","hook_key":"любить-всё-простое","sort_order":"1143","original_key":"rupert-brooke|the-great-lover","author_name":"Руперт Брук","original_title":"The Great Lover","original_language":"English","origin_country":"Великобритания","original_year":"1914","source_url":"https://en.wikisource.org/wiki/The_Great_Lover","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1915.","music_adaptations":[],"source_synopsis":"Герой честно составляет перечень всего, что любил: белые тарелки в синих полосках, мокрые волосы после купанья, вишни, корица, дождь по крыше, холодные руки в тёплых руках. Список оказывается длиннее любой биографии — жизнь была великой любовью к мелочам.","main_image":"белые тарелки в синих полосках из списка любимых мелочей"},{"title":"Спасибо за заботу","full_story":"Он смотрит на штабных в тылу: гладкие, румяные, с двойными подбородками — пьют, гонят хмурых героев вверх по линии на смерть и скорбно читают списки: «потеряли в последнем деле». Каждое имя из окопа проходит через их руки как строка отчёта. Когда война кончится и молодость умрёт камнем, майор уковыляет домой и умрёт — в постели, с орденом на одеяле. Песня-ответ: спасибо вам, господа, за такую заботу.","hero_pov":"солдат, разглядывающий довольных тыловиков","central_conflict":"тыл против окопов","emotional_arc":"от едкой усмешки к ледяному финальному «спасибо»","ending_direction":"майор умрёт в постели — и это всё, что будет","hook_direction":"спасибо за заботу, майоры","genres":["Панк","Рэп"],"moods":["Злость","Ирония"],"energy":"Высокая","themes":["работа","Потеря"],"generator_brief":"Едкий панк с жёсткой декламацией и рваным ритмом: куплеты — перекличка штабных фраз, припев — ледяное «спасибо», пропетое на одной ноте.","generator_story":"Солдат смотрит на румяных тыловиков: они гонят хмурых героев на смерть и скорбно читают списки потерь. Когда война кончится, майор умрёт в своей постели — и ни один окоп его не коснётся.","primary_genre":"Панк","primary_mood":"Злость","primary_theme":"работа","story_shelf":"Трагические истории","conflict_key":"тыл-и-окоп","image_key":"гладкие-майоры-за-стаканом","turn_key":"умрёт-в-постели-с-орденом","hook_key":"спасибо-за-заботу-майоры","sort_order":"1144","original_key":"siegfried-sassoon|base-details","author_name":"Зигфрид Сассун","original_title":"Base Details","original_language":"English","origin_country":"Великобритания","original_year":"1917","source_url":"https://en.wikisource.org/wiki/Base_Details","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1967.","music_adaptations":[],"source_synopsis":"Сатира: если бы поэт был лысым, ярым и задыхающимся, он бы тоже жил в тылу со «шкарлетными майорами» — гонял хмурых героев на смерть, читал списки потерь и «выражал глубокую скорбь». А когда война кончится и молодость умрёт камнем, майор уковыляет домой и умрёт — в постели.","main_image":"гладкие майоры за стаканом в безопасном тылу"},{"title":"Ангел опоздал","full_story":"Старик ведёт сына через горы по приказу, который считает святым, и кладёт его на вязанку хвороста — ремни и пряжки стягивают ребёнка вместо барана. Ангел кричит из-за облака: не убий — вот баран гордыни, заколи его вместо мальчика. Но старик не останавливается: он верит своему праву больше, чем небу, и доводит нож до конца. Половина молодых Европы ложится на эту вязанку — один за другим.","hero_pov":"отец с ножом над сыном","central_conflict":"гордыня старших против жизни младших","emotional_arc":"от слепой клятвы к злому выбору, который не остановил даже ангел","ending_direction":"сын заколот — и с ним одно за другим всё молодое поколение","hook_direction":"не убивай — есть же баран","genres":["Метал","Эпик-рок"],"moods":["Боль","Напряжение"],"energy":"Взрывная","themes":["семья","Потеря"],"generator_brief":"Мрачный метал с библейской поступью: гулкие тамтамы как шаги по горам, припев — ангельский зов, который ломается о глухой рифф старика.","generator_story":"Старик кладёт сына на вязанку — ремни стягивают ребёнка вместо барана. Ангел кричит заколоть гордыню вместо мальчика, но отец верит своему праву больше неба: на вязанку ложится всё молодое поколение.","primary_genre":"Метал","primary_mood":"Боль","primary_theme":"семья","story_shelf":"Трагические истории","conflict_key":"гордыня-старших-против-жизни-младших","image_key":"сын-на-вязанке-хвороста","turn_key":"ангел-кричал-а-старик-довёл","hook_key":"не-убивай-есть-же-баран","sort_order":"1145","original_key":"wilfred-owen|the-parable-of-the-old-man-and-the-young","author_name":"Уилфред Оуэн","original_title":"The Parable of the Old Man and the Young","original_language":"English","origin_country":"Великобритания","original_year":"1920","source_url":"https://en.wikisource.org/wiki/The_Parable_of_the_Old_Man_and_the_Young","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1918.","music_adaptations":[],"source_synopsis":"Переписанная притча об Аврааме: старик ведёт сына через горы и кладёт его на вязанку хвороста вместо вьючного животного. Ангел зовёт не убивать — вот баран гордыни, убей его вместо мальчика, — но старик не останавливается и закалывает сына, а с ним и половину молодого поколения Европы.","main_image":"сын, связанный на вязанке хвороста, и нож старика"},{"title":"Крыса между линиями","full_story":"Тьма рушится — рассвет в окопах тот же, что был тысячи лет назад. На его руку прыгает крыса: она единственная здесь, кто свободно ходит между линиями, — зверь не знает, что это война, и не делит людей на своих. Он кормит её хлебом и понимает: вся здешняя свобода теперь у неё. Он срывает с бруствера красный мак и втыкает за ухо — маленький цветок растёт из человеческой крови. Потом снова вахта, но за ухом — красное.","hero_pov":"солдат на рассветной вахте","central_conflict":"свобода зверя против несвободы человека","emotional_arc":"от рассветного покоя к горькому дару себе","ending_direction":"мак за ухом — живое красное среди серого дня","hook_direction":"живое ходит где хочет","genres":["Метал","Кантри"],"moods":["Спокойствие","Напряжение"],"energy":"Средняя","themes":["работа","Память"],"generator_brief":"Тихий метал с чистой гитарой поверх гула: куплеты — рассветная вахта, припев — внезапная красная точка мака на сером фоне.","generator_story":"На рассвете на руку солдату прыгает крыса — единственная, кто ходит между линиями: зверь не знает, что это война. Он кормит её хлебом и втыкает красный мак за ухо — живое красное среди серого дня.","primary_genre":"Метал","primary_mood":"Спокойствие","primary_theme":"работа","story_shelf":"Люди и животные","conflict_key":"свобода-зверя-против-несвободы-человека","image_key":"крыса-перебегает-линии-огня","turn_key":"мак-за-ухом-как-знак-себе","hook_key":"живое-ходит-где-хочет","sort_order":"1146","original_key":"isaac-rosenberg|break-of-day-in-the-trenches","author_name":"Айзек Розенберг","original_title":"Break of Day in the Trenches","original_language":"English","origin_country":"Великобритания","original_year":"1916","source_url":"https://en.wikisource.org/wiki/Break_of_Day_in_the_Trenches","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1918.","music_adaptations":[],"source_synopsis":"На рассвете в окопах солдат кормит хлебом крысу — единственное живое существо, которое свободно перебегает линии, потому что не знает про войну. Он срывает с бруствера мак и втыкает себе за ухо: цветок, чьи корни — в человеческих жилах, — подарок самому себе на этот день.","main_image":"крыса, свободно перебегающая линии огня"},{"title":"Бог в килте","full_story":"Он сидит в кресле у тёмного парка и ждёт, когда зажгут огни: год назад он носил голубые шорты и собирал стадионы, а теперь с сожалением вспомнил, как ложился спать в холод. Записался он, потому что зал ревел, — ему сказали, что в килте он будет выглядеть как бог, и, может, ещё затем, чтобы Мэг заметила. Теперь девушки скользят взглядом мимо, как мимо странности, и только торжественный человек приносит ему фрукты и спрашивает о душе. Вся сверкающая жизнь случилась с ним год назад.","hero_pov":"безногий ветеран в кресле у парка","central_conflict":"вчерашний восторг против сегодняшней тишины","emotional_arc":"от памяти о реве стадиона к ледяному взгляду мимо","ending_direction":"мимо проходят — его счёт жизни закрыт год назад","hook_direction":"год назад я был богом","genres":["Блюз","Классика"],"moods":["Одиночество","Тоска"],"energy":"Низкая","themes":["семья","Потеря"],"generator_brief":"Тихий блюз с дальним смехом стадиона в фонограмме: куплеты — кресло и темнота, припев — вспышка годовой давности, которая тут же гаснет.","generator_story":"Безногий ветеран в кресле у парка: год назад собирал стадионы, теперь ради взгляда Мэг он в парадной колонне. Девушки скользят мимо, и лишь один человек приносит ему фрукты и спрашивает о душе.","primary_genre":"Блюз","primary_mood":"Одиночество","primary_theme":"семья","story_shelf":"Трагические истории","conflict_key":"вчерашний-восторг-против-сегодняшней-тишины","image_key":"кресло-у-парка-с-огнями","turn_key":"девушки-скользят-взглядом-мимо","hook_key":"год-назад-я-был-богом","sort_order":"1147","original_key":"wilfred-owen|disabled","author_name":"Уилфред Оуэн","original_title":"Disabled","original_language":"English","origin_country":"Великобритания","original_year":"1917","source_url":"https://en.wikisource.org/wiki/Disabled","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1918.","music_adaptations":[],"source_synopsis":"Безногий ветеран сидит в кресле и ждёт темноты: год назад он был молод, и зал аплодировал ему после футбола, а когда он записался в солдаты, ему обещали, что в килте он будет выглядеть как бог. Теперь девушки скользят взглядом мимо, его угощают фруктами и спрашивают о душе.","main_image":"кресло у парка, где зажигаются чужие огни"},{"title":"Дикая жена","full_story":"Он женился на ней, когда она была слишком молода, чтобы понять, что её спрашивают. Через три недели она ушла через окно — мужчины всей округи догнали её с фонарями и привели назад. Теперь она живёт в доме как дикий зверёк: пугается вздоха, спит в стороне, ловит мышей в амбаре среди ласточек. Он не трогает её — только смотрит и ждёт тепла, которого не будет, и осенью ночи длинные, и даже служанка знает, что рождество в доме пустое. Песня о том, как взять человека — и не получить его.","hero_pov":"фермер о своей убежавшей жене","central_conflict":"добытый человек остался диким","emotional_arc":"от упрямого ожидания к пониманию пустого дома","ending_direction":"она останется зверем в его доме — ожидание без ответа","hook_direction":"я жду — она бежит","genres":["Кантри","Фолк"],"moods":["Одиночество","Тоска"],"energy":"Высокая","themes":["ожидание","семья"],"generator_brief":"Сухое кантри с цоканьем копыт и тишиной между фразами: куплеты — бег по двору и амбар, припев — длинное осеннее ожидание у пустого стола.","generator_story":"Он женился на девочке, которая не поняла, что её спрашивают, — через три недели она ушла через окно, и её догнали с фонарями. Теперь она живёт диким зверьком, а фермер ждёт тепла, которого не будет.","primary_genre":"Кантри","primary_mood":"Одиночество","primary_theme":"ожидание","story_shelf":"Люди и животные","conflict_key":"добытый-человек-остался-диким","image_key":"дикая-жена-в-амбаре-с-мышами","turn_key":"рождество-пустое-без-неё","hook_key":"я-жду-она-бежит","sort_order":"1148","original_key":"charlotte-mew|the-farmers-bride","author_name":"Шарлотта Мью","original_title":"The Farmer's Bride","original_language":"English","origin_country":"Великобритания","original_year":"1916","source_url":"https://en.wikisource.org/wiki/The_Farmer%27s_Bride","rights_check":"Справочно: права не проверяются, идея не текст. Автор умерла в 1928.","music_adaptations":[],"source_synopsis":"Фермер рассказывает о молодой жене, которую выдали слишком рано: через три недели она убежала, мужчины с фонарями догнали её и вернули. Теперь она пуглива, как зайчонок и телушка, ловит мышей в амбаре среди ласточек, и фермер с тоской ждёт тепла, которого не будет.","main_image":"дикая жена, ловящая мышей в амбаре среди ласточек"},{"title":"Много жизни для дома","full_story":"Четыре стены у всех одинаковые, а дома получаются разные: нужен мешок солнца и тени, годы чаёв на плите, голоса на лестнице и детские рисунки на дверях холодильника. Надо уехать и голодать по нему издалека, чтобы понять, чем он пахнет. Надо любить каждый кирпич от подвала до крыши — и вот тогда дом есть, а не просто жильё. Песня о том, что дом — это количество жизни, вложенной внутрь.","hero_pov":"хозяин, у которого дом сделан жизнью","central_conflict":"четыре стены против живого дома","emotional_arc":"от бытовой суеты к пониманию, чем пахнет настоящий дом","ending_direction":"дом есть — потому что в него вложили годы","hook_direction":"это не стены — это мы","genres":["Кантри","Фолк"],"moods":["Тепло","Радость"],"energy":"Средняя","themes":["дом","семья"],"generator_brief":"Тёплое кантри с домашним ритмом и приглушённой пилой-гитарой: куплеты — бытовая перекличка, припев — общий хук для всей семьи.","generator_story":"Четыре стены у всех одинаковы, а дома разные: годы чаёв на плите, голоса на лестнице, рисунки на холодильнике. Надо уехать и голодать по нему издалека — дом есть там, куда вложил жизнь.","primary_genre":"Кантри","primary_mood":"Тепло","primary_theme":"дом","story_shelf":"Юмор: семейные драмы","conflict_key":"четыре-стены-и-живой-дом","image_key":"шаги-по-лестнице-и-чай-на-плите","turn_key":"дом-делается-жизнью-а-не-кирпичом","hook_key":"это-не-стены-это-мы","sort_order":"1149","original_key":"edgar-guest|home","author_name":"Эдгар Гест","original_title":"Home","original_language":"English","origin_country":"США","original_year":"1916","source_url":"https://poets.org/poem/home-4","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1959.","music_adaptations":[],"source_synopsis":"Четыре стены одинаковы у всех, а дом делается жизнью: нужен мешок солнца и тени, годы чаёв на плите, уходы и голод по нему издалека. Надо любить каждый кирпич от подвала до крыши — и тогда в доме будет дом.","main_image":"шаги по лестнице и чай на плите дома"},{"title":"Он сделал это","full_story":"Кто-то сказал ему, что это не может быть сделано, — он с усмешкой ответил, что узнает, только попробовав. Никто не сказал ему, что можно, — он сам начал, и хохоток его был громче всех предостережений. Он принялся за дело с песней, и слово «нельзя» осталось на месте, а дело — сделано. Песня о том, что «невозможно» — это чей-то испуг, а не закон.","hero_pov":"человек, взявшийся за невозможное","central_conflict":"невозможное против усмешки","emotional_arc":"от чужого «нельзя» к собственному сделанному","ending_direction":"дело сделано — «нельзя» осталось без работы","hook_direction":"нельзя — значит попробуем","genres":["Кантри","Фолк"],"moods":["Уверенность","Смелость"],"energy":"Высокая","themes":["работа","смелость"],"generator_brief":"Бодрое кантри с хохотком в аранжировке: куплеты — чей-то скепсис, припев — разгонающийся мотив человека, который начал петь посреди дела.","generator_story":"Ему сказали, что это невозможно, — он усмехнулся и начал сам, и хохоток его был громче всех предостережений. Взялся за дело с песней: «нельзя» осталось на месте, а дело — сделано.","primary_genre":"Кантри","primary_mood":"Уверенность","primary_theme":"работа","story_shelf":"Юмор: семейные драмы","conflict_key":"невозможное-против-усмешки","image_key":"человек-с-песней-над-делом","turn_key":"он-сделал-то-что-нельзя","hook_key":"нельзя-значит-попробуем","sort_order":"1150","original_key":"edgar-guest|it-couldnt-be-done","author_name":"Эдгар Гест","original_title":"It Couldn't Be Done","original_language":"English","origin_country":"США","original_year":"1919","source_url":"https://poets.org/poem/it-couldnt-be-done","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1959.","music_adaptations":[],"source_synopsis":"Кто-то сказал герою, что это не может быть сделано, — он усмехнулся: узнаем, только попробовав. Он принялся за дело с хохотком и песней и сделал то, что «не могло быть сделано».","main_image":"человек с песней на плечах невозможного дела"},{"title":"Полуночные шаги Линкольна","full_story":"В полночь над спящим Спрингфилдом он видит его сам: высокая фигура в старом пальто ходит по пустым улицам, опустив голову. Линкольн не спит, хоть мир уснул: он скорбит над новыми войнами, городами и горем, которых не было в его снах, и шаги его тяжелее всех колоколов. Житель городка засыпает под эти шаги и каждый раз обещает себе проснуться лучше. Песня о том, что совесть страны не умирает вместе с тем, кто её будил.","hero_pov":"житель ночного городка, встречающий призрака","central_conflict":"совесть, которая не спит, против мира, который уснул","emotional_arc":"от полуночного страха к тихому обещанию жить внимательнее","ending_direction":"шаги уводят к рассвету — обещание остаётся","hook_direction":"он всё ещё не спит","genres":["Эпик-рок","Фолк"],"moods":["Боль","Благородство"],"energy":"Высокая","themes":["ночь","память"],"generator_brief":"Тяжёлый эпик-рок с барабанами шагов: куплеты — пустые улицы и ветер, припев — горький, размеренный мотив того, кто идёт и не спит.","generator_story":"В полночь над спящим Спрингфилдом житель видит фигуру в старом пальто: Линкольн ходит пустыми улицами, и шаги его тяжелее колоколов. Городок засыпает под эти шаги — и обещает себе проснуться лучше.","primary_genre":"Эпик-рок","primary_mood":"Боль","primary_theme":"ночь","story_shelf":"Трагические истории","conflict_key":"совесть-которая-не-спит","image_key":"полночные-шаги-по-спрингфилду","turn_key":"сны-тяжелеют-над-новой-войной","hook_key":"он-всё-ещё-не-спит","sort_order":"1151","original_key":"vachel-lindsay|abraham-lincoln-walks-at-midnight","author_name":"Вачел Линдсей","original_title":"Abraham Lincoln Walks at Midnight (In Springfield)","original_language":"English","origin_country":"США","original_year":"1914","source_url":"https://en.wikisource.org/wiki/Abraham_Lincoln_Walks_at_Midnight","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1931.","music_adaptations":[],"source_synopsis":"В полночь над Спрингфилдом видят его: высокий, в старом пальто, Линкольн ходит по улицам, не спит и скорбит над миром, который не услышал его сна, — над новыми войнами и горем, которых не было в его времени.","main_image":"высокая фигура Линкольна в полуночных улицах"},{"title":"На кошачьих лапах","full_story":"Туман приходит в город на мягких кошачьих лапах: садится над портом и судами, глядит на молчащий город и уходит дальше, никого не разбудив. Никто не слышал его входа и выхода — только здания на минуту стали мягче. Песня о госте, который занимает весь город на короткое время — и оставляет его прежним. Кто умеет так приходить и уходить, тот умеет жить в большом мире.","hero_pov":"горожанин, увидевший приход тумана","central_conflict":"тишина приходит и уходит, не спрашивая","emotional_arc":"от мгновенного замирания города к спокойному прощанию без следа","ending_direction":"туман ушёл дальше — город остался прежним","hook_direction":"туман приходит на мягких лапах","genres":["Джаз","Эмбиент"],"moods":["Спокойствие","Мечтательность"],"energy":"Низкая","themes":["ночь","Город"],"generator_brief":"Тихий джаз с контрабасом, идущим на мягких лапах: куплеты — почти без ударных, припев — один длинный выдух и уход.","generator_story":"Город засыпает, когда туман скользит на кошачьих лапах: садится над портом, глядит на молчащий город и уходит дальше. Никто не слышал ни входа, ни выхода — только здания на минуту стали мягче.","primary_genre":"Джаз","primary_mood":"Спокойствие","primary_theme":"ночь","story_shelf":"Люди и животные","conflict_key":"тишина-приходит-и-уходит-не-спрашивая","image_key":"туман-на-кошачьих-лапах","turn_key":"сидит-молча-и-уплывает-дальше","hook_key":"туман-приходит-на-мягких-лапах","sort_order":"1152","original_key":"carl-sandburg|fog","author_name":"Карл Сандберг","original_title":"Fog","original_language":"English","origin_country":"США","original_year":"1916","source_url":"https://en.wikisource.org/wiki/Chicago_Poems/Fog","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1967.","music_adaptations":[],"source_synopsis":"Туман приходит в порт на кошачьих лапах: садится над гаванью и судами, глядит на молчащий город — и уходит дальше, никого не разбудив.","main_image":"туман на кошачьих лапах над портом"},{"title":"Мясник мира","full_story":"Ему приносят список грехов его города — и он соглашается со всем: да, он видел и это, и это. Но он также видел, как город поднимает голову и поёт, гордый тем, что живой, грубый и сильный, — и предлагает показать второй такой. Он отдает городу хулу и гордость в одном глотке: будь они прокляты — но ведь это работа живого сердца. Песня-ответ тому, кто стыдится своих улиц.","hero_pov":"житель города, отвечающий хулителям","central_conflict":"грязь города против его гордости","emotional_arc":"от признания всех грехов к вызывающей гордости живого","ending_direction":"город смеётся и работает — покажите второй такой","hook_direction":"это мой город — и он живой","genres":["Панк","Рэп"],"moods":["Протест","Уверенность"],"energy":"Взрывная","themes":["работа","Город"],"generator_brief":"Грубый панк-гимн с литыми барабанами: куплеты — перечень грехов на одной ноте, припев — вознесённый клич города с поднятыми плечами.","generator_story":"Ему приносят список грехов города — он соглашается со всем: видел и это, и это. Но видел и как город поднимает голову и поёт, гордый, что живой и сильный, — и предлагает показать второй такой.","primary_genre":"Панк","primary_mood":"Протест","primary_theme":"работа","story_shelf":"Трагические истории","conflict_key":"грязь-города-против-его-гордости","image_key":"город-с-большими-плечами","turn_key":"соглашаюсь-со-всем-и-горжусь","hook_key":"это-мой-город-и-он-живой","sort_order":"1153","original_key":"carl-sandburg|chicago","author_name":"Карл Сандберг","original_title":"Chicago","original_language":"English","origin_country":"США","original_year":"1916","source_url":"https://en.wikisource.org/wiki/Chicago_Poems/Chicago","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1967.","music_adaptations":[],"source_synopsis":"Хулители перечисляют городу грехи — свиноубойный мясник мира, город больших плеч, кривых сплетен — и голос горожанина соглашается со всем. Но он видел, как город поднимает голову и поёт, гордый своей грубой живой силой, и предлагает показать второй такой.","main_image":"город с большими плечами, смеющийся над списком своих грехов"},{"title":"Я — народ","full_story":"Он — народ, толпа, масса: тот, кто пашет, строит и кормит мир, оставаясь безымянным в чужих песнях. Все великие дела мира сделаны через него, а его забывают между войнами и праздниками. Ему обещали оратора за оратора — но его собственный голос ещё не прозвучал. Он предупреждает тихо: однажды масса набухнет под землёй и заговорит сама. Песня от лица тех, на ком всё стоит.","hero_pov":"голос безымянного большинства","central_conflict":"мир стоит на людях, которых не называют","emotional_arc":"от терпеливой работы к тихому предупреждению о собственном голосе","ending_direction":"масса однажды заговорит сама — и это будет её песня","hook_direction":"я — народ, и я всё накормлю","genres":["Соул","Рэп"],"moods":["Сила","Протест"],"energy":"Взрывная","themes":["поддержка","работа"],"generator_brief":"Мощный соул с хором на грани марша: куплеты — работа в ритме, припев — многоголосый, как толпа, которая вдруг взяла слово.","generator_story":"Безымянный работяга пашет, строит и кормит мир: все великие дела сделаны через него, а его забывают между войнами и праздниками. Однажды масса набухнет под землёй и заговорит сама.","primary_genre":"Соул","primary_mood":"Сила","primary_theme":"поддержка","story_shelf":"Трагические истории","conflict_key":"мир-стоит-на-людях-которых-не-называют","image_key":"рабочие-руки-под-всем-миром","turn_key":"масса-однажды-заговорит-сама","hook_key":"я-народ-и-я-всё-накормлю","sort_order":"1154","original_key":"carl-sandburg|i-am-the-people-the-mob","author_name":"Карл Сандберг","original_title":"I Am the People, the Mob","original_language":"English","origin_country":"США","original_year":"1916","source_url":"https://en.wikisource.org/wiki/Chicago_Poems/I_Am_the_People,_the_Mob","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1967.","music_adaptations":[],"source_synopsis":"Голос народа: я — народ, толпа, масса; вся великая работа мира сделана через меня, я работаю и вечно забываю. Моими ораторами называли любого, кто взял слово от моего имени, но мой голос ещё не сказан — однажды масса заговорит сама.","main_image":"рабочие руки, на которых держится весь мир"},{"title":"Меня уже не разбудишь","full_story":"Она говорит ему наперёд: когда меня не станет и апрель раскинет надо мной мокрые волосы дождя, ты можешь наклониться с разбитым сердцем — мне будет всё равно. Я буду покойна, как лиственные деревья под дождём, что клонят ветви, — и безмолвнее и холоднее, чем ты сейчас. Это не месть: это последняя ступень остывания, где нечего прощать и не за что держаться. Песня о той свободе, которая дороже всякой жалости.","hero_pov":"женщина, остывшая навсегда","central_conflict":"его поздняя жалость против её покоя","emotional_arc":"от многолетнего ожидания тепла к полной свободе от ответа","ending_direction":"она спит под апрелем — и никакое горе её не тронет","hook_direction":"меня уже не разбудишь","genres":["R&B","Классика"],"moods":["Освобождение","Спокойствие"],"energy":"Низкая","themes":["прощение","Расставание"],"generator_brief":"Медленный R&B на одном breathed-клавесине: куплеты — ровное, заранее написанное письмо, припев — полный выдох без остатка.","generator_story":"Она говорит ему наперёд: когда апрель раскинет надо мной дождь, наклоняйся с разбитым сердцем — мне будет всё равно. Это не месть, а последняя ступень остывания, где нечего прощать.","primary_genre":"R&B","primary_mood":"Освобождение","primary_theme":"прощение","story_shelf":"Любовные сцены","conflict_key":"его-поздняя-жалость-против-её-покоя","image_key":"апрель-с-мокрыми-волосами-дождя","turn_key":"она-покойнее-дерева-под-дождём","hook_key":"меня-уже-не-разбудишь","sort_order":"1155","original_key":"sara-teasdale|i-shall-not-care","author_name":"Сара Тисдейл","original_title":"I Shall Not Care","original_language":"English","origin_country":"США","original_year":"1915","source_url":"https://en.wikisource.org/wiki/I_Shall_Not_Care","rights_check":"Справочно: права не проверяются, идея не текст. Автор умерла в 1933.","music_adaptations":[],"source_synopsis":"Героиня говорит любимому наперёд: когда я умру и надо мной апрель раскинет мокрые волосы, ты можешь наклониться надо мной с разбитым сердцем — мне будет всё равно. Я буду покойна, как деревья под дождём, и безмолвнее и холоднее, чем ты сейчас.","main_image":"апрель расчёсывает над ней мокрые волосы дождя"},{"title":"Арфа, которая ткёт","full_story":"В холодной хижине двое голодают: мать и мальчик, и вся их утварь — неработающая арфа на стене. Ночью арфа начинает звучать и ткёт одна вещь за другой — шапку, плащ, золотое платье — из светящихся нитей, а мать работает рядом, не поднимая головы, до последней силы. К утру мальчик просыпается одетый в золото, а мать сидит в кресле навсегда тихая. Арфа всё ещё ткёт. Песня о заботе, которая дороже жизни той, кто заботится.","hero_pov":"сын, смотрящий на мать за работой","central_conflict":"голод против последней заботы","emotional_arc":"от зимней нужды к светлому золоту и молчанию в кресле","ending_direction":"мать отдала всё — арфа продолжает ткать","hook_direction":"мама ткёт мне новое платье","genres":["Соул","Баллада"],"moods":["Нежность","Светлая грусть"],"energy":"Низкая","themes":["поддержка","семья"],"generator_brief":"Колыбельный соул с арфой и одним дыханием хора: куплеты — стук голодной зимы, припев — нить золотого света, которая не обрывается.","generator_story":"В холодной хижине мать и сын голодают, и вся утварь — арфа на стене. Ночью арфа ткёт из светящихся нитей платье за платьем, мать работает рядом до последней силы — к утру она навсегда тихая в кресле.","primary_genre":"Соул","primary_mood":"Нежность","primary_theme":"поддержка","story_shelf":"Трагические истории","conflict_key":"голод-против-последней-заботы","image_key":"золотые-платья-из-арфы","turn_key":"арфа-ткёт-после-её-смерти","hook_key":"мама-ткёт-мне-новое-платье","sort_order":"1156","original_key":"edna-millay|the-ballad-of-the-harp-weaver","author_name":"Эдна Сент-Винсент Миллей","original_title":"The Ballad of the Harp-Weaver","original_language":"English","origin_country":"США","original_year":"1922","source_url":"https://en.wikisource.org/wiki/The_Ballad_of_the_Harp-Weaver","rights_check":"Справочно: права не проверяются, идея не текст. Автор умерла в 1950.","music_adaptations":[],"source_synopsis":"В холодной хижине мать и сын голодают. Ночью арфа на стене оживает и начинает ткать для мальчика — шапку, плащ, золотое платье — из светящихся нитей; мать работает вместе с ней до последнего. К утру мальчик просыпается в золоте, а мать сидит в кресле навсегда тихая — и арфа всё ещё ткёт.","main_image":"золотые платья, выходящие из ожившей арфы"},{"title":"Лето, которое кончилось","full_story":"Она не помнит имён, мест и причин — только сам факт: губы целовали её губы, руки лежали у неё под головой до утра. Ночью к окну прилетают незваные призраки прошлых летних ночей, и она не может грустить о них, как дерево не может грустить о птицах, которых не слышит. В ней теперь стоит зимнее дерево: птицы пели в нём — она знает, но тишина полная. Лето пело в ней недолго, и это сделало её просто взрослой.","hero_pov":"женщина, перебравшая поцелуи","central_conflict":"забытые поцелуи и забывшие губы","emotional_arc":"от ночных призраков лета к зимнему дереву без птиц","ending_direction":"лето пело в ней недолго — она приняла тишину как взрослость","hook_direction":"я помню, что забыла","genres":["Блюз","Классика"],"moods":["Одиночество","Грусть"],"energy":"Низкая","themes":["прощение","Память"],"generator_brief":"Медленный блюз с одинокой гитарой: куплеты — перечисление забытого, припев — зимнее окно, за которым дерево стоит молча.","generator_story":"Она не помнит имён — только губы, целовавшие её губы, и руки под головой до утра. Ночью прилетают призраки летних ночей, но в ней теперь зимнее дерево: птицы пели в нём, а тишина полная.","primary_genre":"Блюз","primary_mood":"Одиночество","primary_theme":"прощение","story_shelf":"Любовные сцены","conflict_key":"забытые-поцелуи-и-забывшие-губы","image_key":"зимнее-дерево-без-птиц","turn_key":"лето-пело-во-мне-недолго","hook_key":"я-помню-что-забыла","sort_order":"1157","original_key":"edna-millay|what-lips-my-lips-have-kissed","author_name":"Эдна Сент-Винсент Миллей","original_title":"What lips my lips have kissed, and where, and why","original_language":"English","origin_country":"США","original_year":"1921","source_url":"https://en.wikisource.org/wiki/Second_April","rights_check":"Справочно: права не проверяются, идея не текст. Автор умерла в 1950.","music_adaptations":[],"source_synopsis":"Героиня забыла, чьи губы целовала, где и зачем, и какие руки были у неё под головой до утра; к её окну прилетают незваные призраки прошлых летних ночей, но она не может грустить о них, как не может знать, кто из поцелуев был настоящим. В ней стоит зимнее дерево, в котором птицы пели, но она не слышит их.","main_image":"зимнее дерево, в котором уже не слышно птиц"},{"title":"Разорванный узор","full_story":"Она идёт по садовым дорожкам в жёстком парчовом платье: узор на ткани повторяет узор клумб, и оба держат её, как нитки держат шитьё. Год назад здесь она ждала его — живая, свободная под закатом. В письме сказано, что он не вернётся, и впервые она чувствует, как туго затянуты все узоры — платья, дома, поведения. Ей приказано идти по дорожке, воевать в мокром саду, оставаясь в пределах рисунка. Песня о женщине, которая хочет разорвать узор — и начать ходить прямо.","hero_pov":"женщина в саду с письмом о смерти","central_conflict":"узоры жизни против живого горя","emotional_arc":"от правильного шага по дорожке к желанию разорвать рисунок","ending_direction":"узор рвётся — впервые она идёт прямо","hook_direction":"узор мешает жить","genres":["R&B","Альтернативный рок"],"moods":["Тоска","Злость"],"energy":"Высокая","themes":["ожидание","Потеря"],"generator_brief":"Натянутый R&B с чеканным, корсетным ритмом: куплеты — правильный шаг по дорожке, припев — рваный, выходящий за размер узора.","generator_story":"Она идёт по садовым дорожкам в парчовом платье, чей узор повторяет клумбы. В письме — что он не вернётся: впервые она чувствует, как туго затянуты узоры её жизни, и хочет идти прямо.","primary_genre":"R&B","primary_mood":"Тоска","primary_theme":"ожидание","story_shelf":"Трагические истории","conflict_key":"узоры-жизни-против-живого-горя","image_key":"жёсткие-узоры-на-мятых-травах","turn_key":"письмо-обрывает-все-узоры","hook_key":"узор-мешает-жить","sort_order":"1158","original_key":"amy-lowell|patterns","author_name":"Эми Лоуэлл","original_title":"Patterns","original_language":"English","origin_country":"США","original_year":"1916","source_url":"https://www.poetryfoundation.org/poems/42987/patterns","rights_check":"Справочно: права не проверяются, идея не текст. Автор умерла в 1925.","music_adaptations":[],"source_synopsis":"Женщина в жёстком парчовом платье идёт по парадным дорожкам сада — узор ткани повторяет узор клумб, и оба держат её как нитки. Здесь она ждала любимого; в письме — что он погиб. Она впервые замечает, как туго затянуты все узоры её жизни, и должна идти воевать в мокром саду, оставаясь в пределах рисунка.","main_image":"жёсткие узоры платья на мятых травах сада"},{"title":"Привычный сон","full_story":"Он снова приходит в один и тот же сон: там ждёт женщина, которую он любит и которая любит его, — и каждый раз она не совсем та же и не совсем другая. Она понимает его без слов, и рядом с ней он — тот, кем не был ни дня наяву. Просыпаясь, он находит пустую комнату, где никто не ждёт от него этой нежности. Песня о человеке, чья единственная родная живёт за краем сна.","hero_pov":"мужчина, приходящий в один и тот же сон","central_conflict":"любовь во сне и пустота наяву","emotional_arc":"от ночного счастья к утренней пустой комнате","ending_direction":"сон остаётся единственным домом — до следующей ночи","hook_direction":"я тебя придумал во сне","genres":["Джаз","Синтвейв"],"moods":["Мечтательность","Тоска"],"energy":"Низкая","themes":["ночь","Любовь"],"generator_brief":"Ночной джаз с синтезаторным гулом: куплеты — перетекание одного сна в другой, припев — утренний обрыв, где гаснет вся нежность.","generator_story":"Он приходит в один и тот же сон: там ждёт женщина, которая понимает его без слов, и рядом с ней он — тот, кем не был ни дня наяву. Просыпаясь, находит пустую комнату, где никто не ждёт этой нежности.","primary_genre":"Джаз","primary_mood":"Мечтательность","primary_theme":"ночь","story_shelf":"Любовные сцены","conflict_key":"любовь-во-сне-и-пустота-наяву","image_key":"неизвестная-женщина-в-сне","turn_key":"она-новая-и-всё-та-же","hook_key":"я-тебя-придумал-во-сне","sort_order":"1159","original_key":"paul-verlaine|mon-reve-familier","author_name":"Поль Верлен","original_title":"Mon rêve familier","original_language":"French","origin_country":"Франция","original_year":"1866","source_url":"https://fr.wikisource.org/wiki/Mon_r%C3%AAve_familier","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1896.","music_adaptations":[],"source_synopsis":"Герой часто видит странный и глубокий сон: неизвестная женщина, которую он любит и которая любит его, — и каждый раз она не совсем та же и не совсем другая. Он любит её лучше всех живых, а просыпается в пустой комнате.","main_image":"неизвестная женщина, каждый раз другая и всё та же"},{"title":"Лебедь входит в воду","full_story":"Он тащится по жизни, как лебедь по земле: тяжело, с усилием, через всё несделанное, — и каждое движение выглядит неловко. Но приходит час, когда он опускается в свою воду, и вода принимает его под себя. Всё вдруг выходит лёгким и красивым: он скользит по чёрной глади, как человек, который наконец вошёл в свой час. Песня о том, что неуклюжесть — это просто не та стихия.","hero_pov":"неуклюжий на суше, graceful в своей воде","central_conflict":"тяжесть хождения против лёгкости своей воды","emotional_arc":"от изнуряющего труда к гладкому скольжению в своём часе","ending_direction":"в воде всё выходит красивым — надо только войти","hook_direction":"в свою воду — и всё станет лёгким","genres":["R&B","Эмбиент"],"moods":["Спокойствие","Уверенность"],"energy":"Низкая","themes":["работа","самопринятие"],"generator_brief":"Плавный R&B с глубоким басом, как вода, принимающая вес: куплеты — тяжёлый шаг, припев — скольжение, где всё вдруг выходит красиво.","generator_story":"Он тащится по жизни, как лебедь по земле: тяжело, через всё несделанное. Но приходит час, когда вода наконец принимает его — и всё выходит лёгким и красивым, как у человека, вошедшего в свой час.","primary_genre":"R&B","primary_mood":"Спокойствие","primary_theme":"работа","story_shelf":"Трагические истории","conflict_key":"тяжесть-хождения-против-лёгкости-воды","image_key":"лебедь-выходит-в-свою-воду","turn_key":"вода-приняла-его-под-себя","hook_key":"в-свою-воду-и-всё-лёгким","sort_order":"1160","original_key":"rainer-maria-rilke|der-schwan","author_name":"Райнер Мария Рильке","original_title":"Der Schwan","original_language":"German","origin_country":"Германия","original_year":"1907","source_url":"https://de.wikisource.org/wiki/Neue_Gedichte","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1926.","music_adaptations":[],"source_synopsis":"Лебедь на земле — неуклюжая тяжёлая ноша, тащащаяся через несделанное; но когда он опускается на воду и вода принимает его под себя, всё вдруг выходит лёгким и красивым — он скользит по чёрной глади, как человек, вошедший в свой час.","main_image":"лебедь, выходящий из неуклюжей ходьбы в скольжение по воде"},{"title":"Подвинь его к солнцу","full_story":"Они выносят его на снег к солнцу — тихо, бережно, как когда-то его мать будила этим же светом на домашнем дворе. Солнце трогало его щёки дома, будило и растапливало усталость, — а теперь не двигает даже лицо. Зёрна в глухой земле всегда вставали к теплу, и что-то будило глину в полях. Если даже солнце не разбудит, зачем вообще эта земля растила человека? Песня о последней заботе, которой некому отдаться.","hero_pov":"солдат, несущий погибшего друга к свету","central_conflict":"солнце, которое будило, и не будит","emotional_arc":"от бережной заботы к ледяному вопросу без ответа","ending_direction":"вопрос остаётся открытым — забота не принята","hook_direction":"подвиньте его к солнцу","genres":["Соул","Классика"],"moods":["Нежность","Уязвимость"],"energy":"Низкая","themes":["поддержка","Потеря"],"generator_brief":"Почти беззвучный соул: два голоса и утренний свет в аранжировке; куплеты — бережное движение, припев — один вопрос, оставленный в воздухе.","generator_story":"Солдаты выносят погибшего друга на снег к солнцу — бережно, как когда-то будила его мать. Дома солнце растапливало усталость, теперь не двигает даже лицо: последняя забота, которой некому отдаться.","primary_genre":"Соул","primary_mood":"Нежность","primary_theme":"поддержка","story_shelf":"Трагические истории","conflict_key":"солнце-которое-будило-и-не-будит","image_key":"погибший-друг-лицом-к-солнцу","turn_key":"зачем-земля-росла-высокой","hook_key":"подвиньте-его-к-солнцу","sort_order":"1161","original_key":"wilfred-owen|futility","author_name":"Уилфред Оуэн","original_title":"Futility","original_language":"English","origin_country":"Великобритания","original_year":"1918","source_url":"https://en.wikisource.org/wiki/Futility","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1918.","music_adaptations":[],"source_synopsis":"Солдаты выносят погибшего друга на снег к солнцу — тихо и бережно, как когда-то мать будила его этим же светом на ферме. Но солнце, которое всегда двигало семена и кровь, не шевелит даже его лицо; и возникает вопрос: зачем вообще глина росла высокой, если солнце будит не всё.","main_image":"погибший друг на снегу лицом к утреннему солнцу"},{"title":"Расписание отца","full_story":"Сын возвращается на лодку отца после провала в городе — вместе, говорит отец, выходить бесполезно, пока не выучишь сезоны. Тот ворчит, что в городе никто не учит порядку, и для каждой приметы поёт свою песню. В первую бурю сын молча затягивает песню раньше отца — и впервые чувствует, что море считает его своим.","hero_pov":"сын рыбака, вернувшийся из города","central_conflict":"городская спешка против морского расписания","emotional_arc":"от униженного возвращения к праву петь со своим","ending_direction":"буря стихает — теперь сын ведёт лодку сам","hook_direction":"у моря на каждый сезон своя песня","genres":["Хаус","Поп"],"moods":["Тепло","Надежда"],"energy":"Высокая","themes":["Возвращение","Семья"],"generator_brief":"Тёплый вечерний хаус с морским дыханием: мягкий бас-кик, шум прибоя в перкуссии, в куплетах приглушённый вокал, в финале хор из одной мелодии.","generator_story":"Сын возвращается на лодку отца после провала в городе — тот учит сезонам и песне на каждую примету. В первую бурю сын затягивает песню раньше отца — и море впервые считает его своим.","primary_genre":"Хаус","primary_mood":"Тепло","primary_theme":"Возвращение","story_shelf":"Юмор: семейные драмы","conflict_key":"городская-спешка-против-морского-расписания","image_key":"отцовский-календарь-песен","turn_key":"буря-учит-песню","hook_key":"у-моря-есть-расписание","sort_order":"1162","original_key":"yun-son-do|eobu-sasiga","author_name":"Юн Сон До","original_title":"어부사시가 (Песни рыбака о четырёх временах)","original_language":"Korean","origin_country":"Корея","original_year":"1651","source_url":"https://en.wikipedia.org/wiki/Yun_Seondo","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1671.","music_adaptations":[],"source_synopsis":"Цикл песен, где рыбак ведёт свой год по морю: каждой поре года — своя песня, свои приметы и свой порядок работы, от весенней отмели до зимнего льда. В песнях живёт не лирика, а точный календарь выживания: когда выходить, когда прятаться, когда ждать.","main_image":"отцовский календарь песен по сезонам моря"},{"title":"Пять друзей, которые не пишут в чат","full_story":"Команду дизайнер потерял за одну встречу: его проект разделили без него, чат замолчал. Он уезжает на месяц к реке и заводит список друзей, которые не выходят из сети: вода, валун, сосна, бамбук и луна над восточным холмом. В лунную ночь он замечает в воде своё отражение — шестого друга — и впервые за год смеётся вслух.","hero_pov":"человек после предательства команды","central_conflict":"человеческое предательство против верности без слов","emotional_arc":"от горечи и обиды к спокойной самодостаточности","ending_direction":"он находит шестого друга — себя — и перестаёт ждать чат","hook_direction":"покажи мне друга, который не уходит","genres":["Техно","Эмбиент"],"moods":["Спокойствие","Освобождение"],"energy":"Средняя","themes":["Дружба","Природа"],"generator_brief":"Гипнотическое минималь-техно: пульс реки в басу, звенящие панорамы сосны и бамбука, вокал почти шёпотом, нарастающий свет финала.","generator_story":"Проект разделили без него, чат смолк — дизайнер уезжает к реке и заводит друзей: вода, валун, сосна, луна. В лунную ночь он находит шестого друга — себя — и впервые за год смеётся.","primary_genre":"Техно","primary_mood":"Спокойствие","primary_theme":"Дружба","story_shelf":"Трагические истории","conflict_key":"предательство-против-верности-без-слов","image_key":"пять-друзей-которых-можно-пересчитать","turn_key":"шестой-друг-в-воде","hook_key":"кроме-пяти-не-нужно","sort_order":"1163","original_key":"yun-son-do|ouga","author_name":"Юн Сон До","original_title":"오우가 (Песня пяти друзей)","original_language":"Korean","origin_country":"Корея","original_year":"1642","source_url":"https://en.wikipedia.org/wiki/Yun_Seondo","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1671.","music_adaptations":[],"source_synopsis":"Сиджо, написанное после изгнания: поэт считает, сколько у него друзей, и называет пять — воду, камень, сосну, бамбук и луну. Ни один из них не предаст, не спросит о должности и не уйдёт.","main_image":"пять друзей, которых можно пересчитать: вода, камень, сосна, бамбук, луна"},{"title":"Лепестки на рельсах","full_story":"Он оставил всё и уезжает ночным поездом, а она знает: любой разговор превратит прощание в суд. Вместо разборок она берёт букет азалий на перрон и отправляет ему голосовое, где просит только не оборачиваться. Утром в переписке остаётся одно сообщение без обвинений — и он впервые едет не от неё, а с её разрешения.","hero_pov":"девушка, которая провожает без упрёка","central_conflict":"обида и право сказать всё против света на прощание","emotional_arc":"от сжимающей боли к почти лёгкому отпусканию","ending_direction":"поезд уходит, лепестки остаются на рельсах","hook_direction":"иди — я не стану грузом","genres":["Трэп","R&B"],"moods":["Освобождение","Нежность"],"energy":"Средняя","themes":["Расставание","Свобода"],"generator_brief":"Мелодичный ночной трэп: мягкий 808, воздушные синты, женский вокал на грани шёпота, дроп как выдох, а не взрыв.","generator_story":"Он уезжает ночным поездом, и любой разговор превратит прощание в суд. Вместо разборок она приносит на перрон букет азалий и голосом просит не оборачиваться — и он впервые едет с её разрешения.","primary_genre":"Трэп","primary_mood":"Освобождение","primary_theme":"Расставание","story_shelf":"Любовные сцены","conflict_key":"обида-против-света-на-прощание","image_key":"лепестки-на-рельсах","turn_key":"разрешение-вместо-разборок","hook_key":"не-стану-грузом","sort_order":"1164","original_key":"kim-so-wol|jindallae-kkot","author_name":"Ким Соволь","original_title":"진달래꽃 (Азалии)","original_language":"Korean","origin_country":"Корея","original_year":"1922","source_url":"https://en.wikipedia.org/wiki/Kim_So-wol","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1934.","music_adaptations":[],"source_synopsis":"Девушка провожает уезжающего возлюбленного: она не удерживает и не клянётся в мести. Она обещает собрать азалии на горе и осыпать ими его дорогу — мягко, светло, без упрёка.","main_image":"дорога уезжающего, устланная лепестками"},{"title":"Огни чужих кораблей","full_story":"Последняя ночь перед отъездом брата в другую страну — они с младшей сестрой сидят на бетонной кромке реки, как в детстве. Он показывает на огни барж и врёт, что это корабли в далёкие гавани, а она знает, что врёт, и не останавливает его. Через год она пишет ему из чужого аэропорта: здесь огни точно такие — значит, мы смотрим на одну луну.","hero_pov":"старший брат в последнюю летнюю ночь","central_conflict":"уезжающая взрослая дорога против летней ночи двоих","emotional_arc":"от неловкой выдумки к тёплому тайному договору","ending_direction":"письмо оттуда: огни такие же — луна общая","hook_direction":"эта же луна над нами","genres":["Латина","R&B"],"moods":["Тепло","Мечтательность"],"energy":"Средняя","themes":["Детство","Семья"],"generator_brief":"Летняя ночная латина с неспешным ритмом: тёплые браслеты перкуссии, городской шум вдалеке, два голоса — брат и сестра — поют почти в разговоре.","generator_story":"В последнюю летнюю ночь брат показывает сестре огни барж и врёт, что это корабли в дальние гавани. Через год письмо из чужого аэропорта: огни такие же — значит, луна у нас общая.","primary_genre":"Латина","primary_mood":"Тепло","primary_theme":"Детство","story_shelf":"Юмор: семейные драмы","conflict_key":"уезжающая-дорога-против-летней-ночи","image_key":"огни-чужих-кораблей","turn_key":"письмо-о-таких-же-огнях","hook_key":"та-же-луна-над-двумя","sort_order":"1165","original_key":"kim-so-wol|nammae-yeoreumbam","author_name":"Ким Соволь","original_title":"남매의 여름밤 (Летняя ночь брата и сестры)","original_language":"Korean","origin_country":"Корея","original_year":"1925","source_url":"https://en.wikipedia.org/wiki/Kim_So-wol","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1934.","music_adaptations":[],"source_synopsis":"Брат и сестра сидят на берегу летней ночью и смотрят на далёкие огни на воде. Брат объясняет младшей, что это корабли, идущие в другие страны, — и тем самым открывает ей целый мир за пределами двора.","main_image":"далёкие огни кораблей на тёмной воде"},{"title":"Красный знак","full_story":"На вечерней смене она носит красный цветок в волосах — так отвечает на его молчание, не говоря ни слова. Он несколько месяцев собирается с духом и репетирует признание в зеркале проходной, а в день, когда наконец решается, цветка в её волосах уже нет — на подоконнике лежит лепесток. Он берёт его и впервые говорит вслух.","hero_pov":"парень, который слишком долго молчал","central_conflict":"молчание и страх против красного знака в волосах","emotional_arc":"от робких попыток к решительному последнему шансу","ending_direction":"лепесток в его руке — слова наконец найдены","hook_direction":"пока цветок не упал — говори","genres":["Электропоп","Синтвейв"],"moods":["Любовь","Грусть"],"energy":"Средняя","themes":["Любовь","Выбор"],"generator_brief":"Нежный синт-электропоп с пульсирующим басом и зимним хором; в припеве один светящийся аккорд, как вспышка камелии.","generator_story":"Она отвечает на его молчание красным цветком в волосах. Он месяцами репетирует признание в зеркале проходной, а решившись — находит лишь лепесток на подоконнике. Он берёт его и впервые говорит вслух.","primary_genre":"Электропоп","primary_mood":"Любовь","primary_theme":"Любовь","story_shelf":"Любовные сцены","conflict_key":"молчание-против-красного-знака","image_key":"красный-цветок-в-волосах","turn_key":"лепесток-вместо-цветка","hook_key":"пока-цветок-не-упал","sort_order":"1166","original_key":"kim-so-wol|dongbaek-kkot","author_name":"Ким Соволь","original_title":"동백꽃 (Цветок камелии)","original_language":"Korean","origin_country":"Корея","original_year":"1925","source_url":"https://en.wikipedia.org/wiki/Kim_So-wol","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1934.","music_adaptations":[],"source_synopsis":"Девушка сравнивает свою любовь с цветком камелии: красный цветок на зимнем дереве, весь напоказ и весь на веру. Цветок держится на ветке молча — и падает целиком, не осыпаясь.","main_image":"красная камелия, которая падает целиком"},{"title":"Страница-ответ","full_story":"Разбирая квартиру умершей матери, дочь находит в шкафу тетрадь: молодая мама двадцати лет писала о чужой вине за свою жизнь и о мечте, которую семье было удобнее не замечать. Дочь читает всю ночь и впервые плачет по ней не от потери, а от того, что не прочла раньше. Утром она дописывает тетрадь страницей-ответом: твой талант теперь читают вслух.","hero_pov":"дочь, которая прочла мать слишком поздно","central_conflict":"дневник против молчания, которое было при жизни","emotional_arc":"от бытовой суеты уборки к горю и признанию","ending_direction":"тетрадь дописана ответом — молчание закрыто","hook_direction":"теперь я прочту тебя вслух","genres":["Хип-хоп","Соул"],"moods":["Вина","Светлая грусть"],"energy":"Низкая","themes":["примирение","Память"],"generator_brief":"Тихий бум-бэп с ржавой фортепианной петлёй: читка ровная и личная, припев почти разговором, в конце — старая запись маминого голоса без слов.","generator_story":"Разбирая квартиру матери, дочь находит тетрадь: мама писала о мечте, которую семье было удобнее не замечать. Дочь читает всю ночь — и плачет впервые не от потери, а от того, что не прочла раньше.","primary_genre":"Хип-хоп","primary_mood":"Вина","primary_theme":"примирение","story_shelf":"Трагические истории","conflict_key":"дневник-против-молчания-при-жизни","image_key":"тетрадь-с-платком-в-шкафу","turn_key":"страница-ответа","hook_key":"кто-прочтёт-меня","sort_order":"1167","original_key":"nguyen-du|doc-tieu-thanh-ky","author_name":"Нгуен Зу","original_title":"Độc Tiểu Thanh ký (Чтение дневника Тьеу Тхань)","original_language":"Vietnamese","origin_country":"Вьетнам","original_year":"1815","source_url":"https://en.wikipedia.org/wiki/Nguy%E1%BB%85n_D%C6%B0","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1820.","music_adaptations":[],"source_synopsis":"Поэт читает дневник умершей женщины, которую изводили за её талант, и плачет над тетрадью. В финале он задаёт себе вопрос, который останется висеть в воздухе: когда его не станет — кто заплачет по нему?","main_image":"старый дневник, найденный в шкафу между платков"},{"title":"Шарик в воде","full_story":"Накануне свадьбы по расчёту невесту учат быть безупречной: белая кофта, тихий голос, ноль лишних слов. У уличной торговки она слышит про шарик в воде — снаружи белый, внутри сладкий, и всё равно тает. В момент «да» она откладывает заученный сценарий и говорит свою речь: пусть тает, но по своей воде.","hero_pov":"невеста, которую учили быть безупречной","central_conflict":"безупречная форма против сладкого сердца внутри","emotional_arc":"от послушной репетиции к собственной речи вслух","ending_direction":"она тает — но остаётся целой: своя вода","hook_direction":"белая корка — не вся я","genres":["Рэп","Поп"],"moods":["Уверенность","Освобождение"],"energy":"Высокая","themes":["Примирение","самоценность"],"generator_brief":"Дерзкий фемин-рэп поверх лёгкого бита: щелчки рисовых шариков в перкуссии, уверенная читка с улыбкой, припев как поднятая бровь.","generator_story":"Невесту свадьбы по расчёту учат безупречности: белая кофта, тихий голос. У торговки она слышит про шарик в воде — белый снаружи, сладкий внутри, — и в момент «да» шепчет: пусть тает, но по своей воде.","primary_genre":"Рэп","primary_mood":"Уверенность","primary_theme":"Примирение","story_shelf":"Юмор: семейные драмы","conflict_key":"безупречность-против-сладкого-сердца","image_key":"белый-шарик-в-воде","turn_key":"своя-речь-вместо-сценария","hook_key":"тает-и-всё-равно-цел","sort_order":"1168","original_key":"ho-xuan-huong|banh-troi-nuoc","author_name":"Хо Сюан Хыонг","original_title":"Bánh trôi nước (Плавающий рисовый шарик)","original_language":"Vietnamese","origin_country":"Вьетнам","original_year":"","source_url":"https://en.wikipedia.org/wiki/H%E1%BB%93_Xu%C3%A2n_H%C6%B0%C6%A1ng","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1822.","music_adaptations":[],"source_synopsis":"Стихотворение о рисовом шарике, плавающем в воде: снаружи белый, внутри — сладкое сердце из пальмового сахара. Так и судьба женщины держит форму в чужих руках и тает.","main_image":"белый рисовый шарик, плавающий в воде"},{"title":"Перевал","full_story":"Пять лет они экономили друг друга: вежливый ужин, уборка по графику, разговоры о быте. Она достаёт старые велосипеды и тащит его на горный перевал — он возмущается до первого поворота, потом сопит и смеётся, как в молодости. На вершине, вытирая пот, они впервые за годы говорят друг другу правду — и едут вниз, разговаривая до темноты.","hero_pov":"женщина, которая вытаскивает пару из быта","central_conflict":"остывшая привычка против общего подъёма в гору","emotional_arc":"от ворчания и упрямства к смеху и близости","ending_direction":"закат на вершине — вниз едут другими людьми","hook_direction":"круче только вверх","genres":["Латина","Электропоп"],"moods":["Эйфория","Романтика"],"energy":"Высокая","themes":["Любовь","Дорога"],"generator_brief":"Кумбия-латина с нарастающим темпом подъёма: виниловые клавиши, хоровое «вверх!» в припеве, тормозные лупы и горный ветер в бридже.","generator_story":"Пять лет они экономили друг друга: вежливый ужин, уборка по графику. Она достаёт велосипеды и тащит его на перевал — он ворчит до первого поворота, а на вершине они впервые за годы говорят правду.","primary_genre":"Латина","primary_mood":"Эйфория","primary_theme":"Любовь","story_shelf":"Любовные сцены","conflict_key":"привычка-против-перевала","image_key":"двое-на-перевале-на-закате","turn_key":"наверху-снова-молодые","hook_key":"круче-только-вверх","sort_order":"1169","original_key":"ho-xuan-huong|deo-ba-dom","author_name":"Хо Сюан Хыонг","original_title":"Đèo Ba Dom (Перевал Ба-Дом)","original_language":"Vietnamese","origin_country":"Вьетнам","original_year":"","source_url":"https://en.wikipedia.org/wiki/H%E1%BB%93_Xu%C3%A2n_H%C6%B0%C6%A1ng","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1822.","music_adaptations":[],"source_synopsis":"Остроумное стихотворение о подъёме на крутой перевал: тяжело, потно, смешно — усилие и близость сплетены в одну дорогу. Вверх идут двое, и каждый шаг измеряется совместным смехом.","main_image":"крутой перевал на закате, двое с рюкзаками"},{"title":"Собаки у костра","full_story":"Группа браконьеров в предзимних горах выходит на тихого старика у костра — их собаки вдруг бросают след и ложатся к огню. Старик не сопротивляется и не читает лекций: он поёт им про их отцов, которые тоже были детьми в этих горах. К утру ружья стоят прислонённые к сосне, а четверо из группы остаются слушать вторую песню.","hero_pov":"старик-отшельник у костра","central_conflict":"ружья и азарт погони против тихой песни","emotional_arc":"от надвинувшейся угрозы к непонятной тишине и покою","ending_direction":"ружья у сосны, собаки спят, костёр догорает","hook_direction":"сядь к огню — оружие подождёт","genres":["Регги","Эмбиент"],"moods":["Спокойствие","Сила"],"energy":"Средняя","themes":["примирение","животные"],"generator_brief":"Медленный корневой регги: одна капля-ритм как дыхание костра, дальние горловые голоса, лай собак превращается в бэк-хор.","generator_story":"Браконьеры выходят на старика у костра — их собаки бросают след и ложатся к огню. Он поёт про отцов, бывших детьми в этих горах, и к утру ружья стоят у сосны, а четверо остаются слушать вторую песню.","primary_genre":"Регги","primary_mood":"Спокойствие","primary_theme":"примирение","story_shelf":"Люди и животные","conflict_key":"ружья-против-тихой-песни","image_key":"собаки-у-чужого-костра","turn_key":"ружья-прислонены-к-сосне","hook_key":"опусти-и-послушай","sort_order":"1170","original_key":"milarepa|song-of-the-hunters","author_name":"Миларепа","original_title":"Mi la'i mgur 'bum — Сто тысяч песен (песня охотникам)","original_language":"Tibetan","origin_country":"Тибет","original_year":"1100","source_url":"https://en.wikipedia.org/wiki/Milarepa","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1135.","music_adaptations":[],"source_synopsis":"Охотники с собаками гонят оленя и выходят к отшельнику в горах. Вместо сопротивления он поёт им о бренности и сострадании — и разгорячённые мужчины опускают луки, а собаки ложатся у его костра.","main_image":"ружья и собаки вокруг одинокого костра"},{"title":"Пепелище не отвечает","full_story":"Он едет в родной город с одним планом: найти тех, кто разорил семью, и забрать своё. На месте дома — дыра вместо двери, в очаге чужой мусор, о сестре никто не слышал. Вечером на фундаменте он начинает петь — сначала сквозь зубы, потом просто — и к третьему куплету злость остаётся за перевалом, а план мести сгорает быстрее дома.","hero_pov":"человек, который ехал мстить","central_conflict":"месть против непостоянства всего, включая злость","emotional_arc":"от собранной ярости к усталому освобождению","ending_direction":"он уходит с фундамента налегке, песня догорает с очагом","hook_direction":"пепел не держит кулак","genres":["Драм-н-бейс","Метал"],"moods":["Злость","Освобождение"],"energy":"Взрывная","themes":["Возвращение","Сила"],"generator_brief":"Мрачное эмбиент-интро взрывается в драм-н-бейс: ломаный брейк как сердцебиение ярости, к третьему дропу злость распадается в широкий чистый финал.","generator_story":"Он едет в родной город мстить — вместо дома дыра, о сестре никто не слышал. Вечером на фундаменте он начинает петь, и к третьему куплету план мести сгорает быстрее пепелища.","primary_genre":"Драм-н-бейс","primary_mood":"Освобождение","primary_theme":"Возвращение","story_shelf":"Трагические истории","conflict_key":"месть-против-пепелища","image_key":"дыра-вместо-двери-и-пепел","turn_key":"вместо-мести-первый-куплет","hook_key":"пепел-не-держит-кулак","sort_order":"1171","original_key":"milarepa|return-to-ruined-home","author_name":"Миларепа","original_title":"Mi la'i mgur 'bum — Сто тысяч песен (возвращение к разорённому дому)","original_language":"Tibetan","origin_country":"Тибет","original_year":"1100","source_url":"https://en.wikipedia.org/wiki/Milarepa","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1135.","music_adaptations":[],"source_synopsis":"Вернувшись после долгих лет к родному дому, отшельник находит его разорённым, а мать — умершей. Вместо отчаяния или мести он поёт о непостоянстве всего: и дом, и злость оказались временно.","main_image":"разорённый дом и дым над пустым очагом"},{"title":"Я выбираю апрель","full_story":"Мать пробивает дочь на «надёжное» место на консервном заводе и повторяет, что апрель — это грязь, непогода и ни одного гаранта. Дочь покупает автобусный билет до города на прослушивание и выходит из дома в самый мокрый апрель, напевая свою песню. На первой слякоти она ловит свой взгляд в витрине и понимает: правильное время то, которое выбираешь сама.","hero_pov":"семнадцатилетняя девушка из рыбацкого посёлка","central_conflict":"надёжная зима семьи против сырого апреля мечты","emotional_arc":"от семейного давления к лёгкой наглой решимости","ending_direction":"автобус уходит — апрель весь впереди","hook_direction":"выбираю апрель","genres":["Драм-н-бейс","Поп"],"moods":["Вдохновение","Драйв"],"energy":"Высокая","themes":["Город","смелость"],"generator_brief":"Весенний драм-н-бейс на полном газу: брейк как ливень, кручёный вокал, в припеве мажорный пробой — грязь под ногами, небо над головой.","generator_story":"Мать пробивает дочь на надёжное место: апрель — грязь и ни одного гаранта. Дочь покупает билет до прослушивания и выходит из дома в самый мокрый апрель — правильное время то, которое выбираешь сама.","primary_genre":"Драм-н-бейс","primary_mood":"Вдохновение","primary_theme":"Город","story_shelf":"Юмор: семейные драмы","conflict_key":"надёжная-зима-против-апреля","image_key":"грязный-апрель-на-снегу","turn_key":"взгляд-в-витрине-на-слякоти","hook_key":"выбираю-апрель","sort_order":"1172","original_key":"bjornson|jeg-velger-meg-april","author_name":"Бьёрнстьерне Бьёрнсон","original_title":"Jeg velger meg april (Я выбираю апрель)","original_language":"Norwegian","origin_country":"Норвегия","original_year":"1868","source_url":"https://en.wikipedia.org/wiki/Bj%C3%B8rnstjerne_Bj%C3%B8rnson","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1910.","music_adaptations":[],"source_synopsis":"Песня молодой девушки из приморского посёлка: она выбирает апрель — сырой, шумный, ненадёжный месяц — вместо спокойных, «правильных» времён года. Всё небезопасное для неё и есть настоящее.","main_image":"грязный апрель поверх снега у моря"},{"title":"Что за горой","full_story":"Он собирает чемоданы ради работы за океаном и всю ночь смотрит на горную кромку, гадая, что там — только снег, как говорил дед. В самолёте под крылом проплывают те же бесконечные снега, и вместо тоски он вдруг смеётся: снег тот же, значит и он тот же, просто теперь он смотрит сверху. Первое фото в новой стране он отправляет деду с подписью: за горой тоже есть горы.","hero_pov":"эмигрант в первом полёте за океан","central_conflict":"неизвестность за хребтом против корней под ногами","emotional_arc":"от тревожного гадания к смеху над страхом","ending_direction":"фото снегов деду: за горой тоже есть горы","hook_direction":"а вдруг там тот же снег","genres":["EDM","Поп"],"moods":["Надежда","Мечтательность"],"energy":"Средняя","themes":["Расставание","Дорога"],"generator_brief":"Стадионный EDM со стартом-разбегом: нарастающий сайд-чейн, голос над фортепиано, дроп в момент пролёта над хребтом — свет, а не страх.","generator_story":"Он уезжает за океан и всю ночь гадает, что за кромкой гор, — дед говорил: только снег. В самолёте под крылом — бесконечные снега, и вместо тоски он смеётся, шлёт деду фото: за горой тоже есть горы.","primary_genre":"EDM","primary_mood":"Надежда","primary_theme":"Расставание","story_shelf":"Любовные сцены","conflict_key":"снег-за-горой-против-неизвестности","image_key":"снежная-кромка-из-иллюминатора","turn_key":"тот-же-снег-под-крылом","hook_key":"что-там-за-горой","sort_order":"1173","original_key":"bjornson|over-de-hoje-fjelde","author_name":"Бьёрнстьерне Бьёрнсон","original_title":"Over de høje fjelde (Над высокими горами)","original_language":"Norwegian","origin_country":"Норвегия","original_year":"1859","source_url":"https://en.wikipedia.org/wiki/Bj%C3%B8rnstjerne_Bj%C3%B8rnson","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1910.","music_adaptations":[],"source_synopsis":"Песня о человеке, который смотрит на высокие горы и не может не спросить: а что там, за ними? Глазам виден один снег, но желание переехать через хребет сильнее всякого ответа.","main_image":"снежная кромка гор из иллюминатора"},{"title":"Море качает","full_story":"После похорон жены отставной капитан не может спать в тишине комнаты: тикают часы и давит пустота. Он возвращается к берегу, где провёл детство, и каждую ночь слушает, как вода укачивает причалы и клети. Первые настоящие сны приходят только там, на старой лавке у дюн, — море, как выясняется, качало его с рождения и не остановилось.","hero_pov":"старый капитан, потерявший половину себя","central_conflict":"тишина квартиры против качки, в которой прошла вся жизнь","emotional_arc":"от бессонницы и пустоты к доверию воде","ending_direction":"он засыпает на лавке у дюн — море качает","hook_direction":"мне качает с самого рождения","genres":["Регги","Баллада"],"moods":["Спокойствие","Тепло"],"energy":"Низкая","themes":["Детство","Море"],"generator_brief":"Колыбельный регги: качающийся медленный ритм, мягкий бас-кик, звук наката вместо перкуссии, почти шёпотный мужской вокал.","generator_story":"После похорон жены капитан не может спать в тишине: тикают часы, давит пустота. Он возвращается на берег детства и слушает, как вода укачивает причалы, — первые настоящие сны приходят на лавке у дюн.","primary_genre":"Регги","primary_mood":"Спокойствие","primary_theme":"Детство","story_shelf":"Трагические истории","conflict_key":"тишина-квартиры-против-прилива","image_key":"ночной-накат-под-окном","turn_key":"первые-сны-на-лавке-у-дюн","hook_key":"качает-с-рожденья","sort_order":"1174","original_key":"drachmann|jeg-horer-i-natten","author_name":"Хольгер Драхманн","original_title":"Jeg hører i Natten den vuggende Lyd (Я слышу в ночи колышущийся звук)","original_language":"Danish","origin_country":"Дания","original_year":"1877","source_url":"https://da.wikipedia.org/wiki/Holger_Drachmann","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1908.","music_adaptations":[],"source_synopsis":"Ночной монолог у моря: слушатель слышит в темноте качающийся звук водорослей и прибоя — море, которое качало его всю жизнь, от колыбели до седой бороды.","main_image":"ночной накат волны под окном"},{"title":"Неси свет","full_story":"Тихая девочка, которую три года никто не звал в компанию, внезапно выбрана Люсией — учительница говорит: «потому что умеешь молчать, не сбиваясь». Всю ночь она репетирует в тёмной кухне и боится огня, своих рук и чужих глаз. Утром она идёт первой по тёмному залу с венцом свечей, и к концу шествия её имя впервые скандирует весь зал.","hero_pov":"невидимка, ставшая светом в самой тёмной ночи","central_conflict":"страх чужих глаз против права нести свет","emotional_arc":"от ночного ужаса к медленному достоинству","ending_direction":"зал скандирует её имя — она доносит огонь не дрогнув","hook_direction":"неси свет — не торопись","genres":["Электропоп","Хаус"],"moods":["Нежность","Смелость"],"energy":"Высокая","themes":["Детство","Сцена"],"generator_brief":"Скандинавский электропоп с хором: холодные синты декабря, пульсация свечей в ритме, припев раскрывается как темнота перед огнём.","generator_story":"Тихую девочку, три года не званную в компанию, выбирают нести венец свечей. Всю ночь она репетирует в тёмной кухне, боясь огня и чужих глаз, — а утром зал скандирует её имя.","primary_genre":"Электропоп","primary_mood":"Нежность","primary_theme":"Детство","story_shelf":"Юмор: семейные драмы","conflict_key":"невидимка-против-свечей","image_key":"венец-свечей-в-тёмном-зале","turn_key":"зал-скандирует-имя","hook_key":"неси-свет-не-торопись","sort_order":"1175","original_key":"karlfeldt|lucia","author_name":"Эрик Аксель Карлфельдт","original_title":"Lucia (Лючия)","original_language":"Swedish","origin_country":"Швеция","original_year":"1898","source_url":"https://en.wikipedia.org/wiki/Erik_Axel_Karlfeldt","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1931.","music_adaptations":[],"source_synopsis":"Стихотворение о Лючии в белом с венцом свечей: в самую тёмную декабрьскую пору она входит со светом, и мрак отступает от одного её шага.","main_image":"венец свечей в тёмном школьном зале"},{"title":"Рифмач из шиномонтажа","full_story":"Портной из спального района пишет рифмы между заказами, и вся бригада делает из этого шоу: у нас свой поэт, штопает рифмы как штаны. Когда в квартале открывается вечер открытого микрофона, ребята тащат его на сцену — посмеяться. К третьей строфе зал перестаёт смеяться и начинает слушать: насмешка становится местной славой, а блокнот — общей гордостью.","hero_pov":"портной с блокнотом рифм в кармане","central_conflict":"чужие усмешки против гордости рифмача","emotional_arc":"от самоиронии и стеснения к спокойному достоинству","ending_direction":"зал слушает — насмешка стала уважением","hook_direction":"штопаю рифмы, как штаны","genres":["Хип-хоп","Фолк"],"moods":["Уверенность","Ирония"],"energy":"Высокая","themes":["Примирение","музыка"],"generator_brief":"Гибкий хип-хоп с акустикой: читка с деревенской ухмылкой, живой бас, припев-выкрик как разрыв шва — и смех, переходящий в хор.","generator_story":"Портной пишет рифмы между заказами, и бригада делает из этого шоу: у нас свой поэт. На открытом микрофоне к третьей строфе зал перестаёт смеяться — насмешка становится гордостью квартала.","primary_genre":"Хип-хоп","primary_mood":"Уверенность","primary_theme":"Примирение","story_shelf":"Юмор: семейные драмы","conflict_key":"чужие-усмешки-против-рифм","image_key":"блокнот-в-кармане-спецовки","turn_key":"зал-перестаёт-смеяться","hook_key":"штопаю-рифмы-как-штаны","sort_order":"1176","original_key":"karlfeldt|om-fridolin","author_name":"Эрик Аксель Карлфельдт","original_title":"Om Fridolin (О Фридолине)","original_language":"Swedish","origin_country":"Швеция","original_year":"1898","source_url":"https://en.wikipedia.org/wiki/Erik_Axel_Karlfeldt","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1931.","music_adaptations":[],"source_synopsis":"Фридолин — сельский портной и поэт в одном: днём он штопает чужие куртки, в кармане живёт своя книга рифм. Скромный ремесленник и гордый сочинитель в одном человеке.","main_image":"блокнот рифм в кармане рабочей спецовки"},{"title":"Река зовёт по имени","full_story":"У неё всё «правильно»: дом, муж, дети, и один лишь звонок из прошлого будит ночь — голос той жизни, где была свобода. Она идёт ночью к реке и стоит на мостках, и вода говорит с ней ласковее всего города. Из дома доносится детский крик «мама», и она поднимается с колен — но оставляет на мостках записку: научусь жить без утопления.","hero_pov":"мать, которую зовёт прежняя жизнь","central_conflict":"зов прежней свободы против детских голосов из дома","emotional_arc":"от усталой правильности к почти срыву и обратно","ending_direction":"она остаётся — но впервые честно называет свою цену","hook_direction":"вода всё ещё помнит моё имя","genres":["Драм-н-бейс","Трэп"],"moods":["Одиночество","Тоска"],"energy":"Взрывная","themes":["Расставание","Семья"],"generator_brief":"Тёмный ликвид-драм-н-бейс: подводный сабвуфер как зов реки, детский крик сэмплом на дропе, вокал мечется между водой и берегом.","generator_story":"У неё всё правильно: дом, муж, дети — и звонок из прошлого будит ночь голосом былой свободы. Она идёт ночью к реке, но детский крик «мама» возвращает её в дом — впервые честно назвав свою цену.","primary_genre":"Драм-н-бейс","primary_mood":"Одиночество","primary_theme":"Расставание","story_shelf":"Трагические истории","conflict_key":"прежняя-жизнь-против-детских-голосов","image_key":"река-зовёт-по-имени","turn_key":"детский-крик-из-дома","hook_key":"река-всё-помнит","sort_order":"1177","original_key":"anon-ballad|agnete-og-havmanden","author_name":"Аноним — датская народная баллада","original_title":"Agnete og havmanden (Агнете и водяной)","original_language":"Danish","origin_country":"Дания","original_year":"","source_url":"https://en.wikipedia.org/wiki/Agnete_and_the_Merman","rights_check":"Справочно: права не проверяются, идея не текст. Анонимная традиция, эпоха средневековье.","music_adaptations":[],"source_synopsis":"Баллада о замужней Агнете, матери детей: она слышит из реки зов водяного — её прежней страсти — и уходит под воду. Наверху плачут дети, и берег тянет её обратно из речной глубины.","main_image":"река, которая зовёт по имени"},{"title":"Холм у дороги","full_story":"Ночь перед свадьбой: жених едет через лес, и у придорожного клуба его останавливает незнакомка — музыка, золото, лёгкость без последствий. Он отказывается по-честному, один раз и в лицо, — и получает удар, который не виден, но ложится под сердце. Он добирается до невесты и всё рассказывает, а вместо отменённой свадьбы она зовёт гостей к его койке: я буду танцевать только с ним.","hero_pov":"жених, отказавшийся от лёгкой музыки","central_conflict":"соблазн без последствий против выбранного человека","emotional_arc":"от тёмного зова к честному отказу и страшной цене","ending_direction":"свадьба переезжает к его койке — верность переживает удар","hook_direction":"я танцую только с одной","genres":["Трэп","Драм-н-бейс"],"moods":["Напряжение","Любовь"],"energy":"Взрывная","themes":["Любовь","верность"],"generator_brief":"Тёмный трэп: гудящий 808 под дорогой, полусонные флейты, на дропе — удар в сердце без единого предупреждения.","generator_story":"Ночью перед свадьбой незнакомка зовёт жениха к лёгкости без последствий. Он отказывается в лицо — и получает удар под сердце, а невеста переносит праздник к его койке: её танец будет только его.","primary_genre":"Трэп","primary_mood":"Напряжение","primary_theme":"Любовь","story_shelf":"Любовные сцены","conflict_key":"соблазн-против-выбранной","image_key":"холм-с-музыкой-у-дороги","turn_key":"удар-который-не-виден","hook_key":"я-танцую-с-одной","sort_order":"1178","original_key":"anon-ballad|herr-oluf","author_name":"Аноним — датская народная баллада","original_title":"Herr Oluf (Господин Олуф)","original_language":"Danish","origin_country":"Дания","original_year":"","source_url":"https://en.wikipedia.org/wiki/Herr_Oluf","rights_check":"Справочно: права не проверяются, идея не текст. Анонимная традиция, эпоха средневековье.","music_adaptations":[],"source_synopsis":"Господин Олуф накануне свадьбы встречает у эльфийского холма дочь эльфийского короля: она зовёт его танцевать и предлагает золото. Он отказывается ради невесты — и получает удар, который не видно.","main_image":"холм с музыкой у ночной дороги"},{"title":"Двенадцать дней сна","full_story":"Дальнобойщик попадает в занос накануне Рождества и просыпается через двенадцать дней в больнице. Пока он лежал, к нему приходили сны: мост через огонь, дети, которым он годами не звонил, отец, ждущий один звонок. Проснувшись, он находит в телефоне список тех, кому должен был позвонить, и звонит по нему, не вставая с кровати, — один звонок за другим.","hero_pov":"человек, вернувшийся из длинного сна","central_conflict":"долги перед живыми против сна, где их видно всё","emotional_arc":"от густой вины к жадному исправлению","ending_direction":"Крещение, последний звонок — отец берёт трубку","hook_direction":"сон сказал, кому звонить","genres":["Техно","Эмбиент"],"moods":["Вина","Надежда"],"energy":"Высокая","themes":["Возвращение","прошлое"],"generator_brief":"Ритуальное гипнотехно: монотонный пульс как шаг по снегу, огненные подголоски на грани слышимости, дроп — пробуждение с полным светом.","generator_story":"Дальнобойщик просыпается после двенадцати дней сна: во сне явились дети, которым он годами не звонил, и отец, ждущий один звонок. Он находит в телефоне список и звонит, не вставая с кровати.","primary_genre":"Техно","primary_mood":"Вина","primary_theme":"Возвращение","story_shelf":"Трагические истории","conflict_key":"сон-против-недозвонённых-долгов","image_key":"рождественский-сон-моста","turn_key":"проснулся-с-списком-звонков","hook_key":"разбуди-меня-в-срок","sort_order":"1179","original_key":"anon-ballad|draumkvedet","author_name":"Аноним — норвежская народная баллада","original_title":"Draumkvedet (Песня сна)","original_language":"Norwegian","origin_country":"Норвегия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Draumkvedet","rights_check":"Справочно: права не проверяются, идея не текст. Анонимная традиция, эпоха средневековье.","music_adaptations":[],"source_synopsis":"Олаф Эстесон засыпает в сочельник по дороге в церковь и спит до Крещения. Во сне он видит мир за гробом — мосты, огонь и цену каждому поступку — и просыпается другим человеком.","main_image":"снежная дорога, на которой заснул на двенадцать дней"},{"title":"Скажи трижды","full_story":"Десять лет отношений стёрли «любимый» до бытового «эй». На мостике над каналом, где они когда-то боялись говорить, она внезапно говорит «милый» — трижды, как пароль из их первой зимы. Он сначала смеётся, потом отвечает третьим «милым» по правилам их игры — и к полуночи слова возвращаются новыми, с новой строкой правды после каждого повтора.","hero_pov":"человек, услышавший своё слово заново","central_conflict":"стёршиеся слова против ритуала, который их возвращает","emotional_arc":"от бытовой глухоты к заново слышимому теплу","ending_direction":"три слова на мосту — и по одному новому признанию за каждое","hook_direction":"три раза — чтобы стало заново","genres":["Хаус","Электропоп"],"moods":["Романтика","Тепло"],"energy":"Средняя","themes":["Город","Любовь"],"generator_brief":"Вечерний глубок-хаус над водой: качающиеся клавиши, три вокальных повтора как маятник, огни канала в мягком фильтре.","generator_story":"Десять лет стёрли «любимый» до бытового «эй». На мостике она говорит «милый» трижды — как пароль их первой зимы, — и к полуночи слова возвращаются новыми: по строке правды за каждый повтор.","primary_genre":"Хаус","primary_mood":"Романтика","primary_theme":"Город","story_shelf":"Любовные сцены","conflict_key":"стёршиеся-слова-против-ритуала","image_key":"три-слова-над-каналом","turn_key":"каждый-раз-новое-признание","hook_key":"скажи-трижды","sort_order":"1180","original_key":"hooft|mijn-lief-mijn-lief","author_name":"Питер Корнелис Хоофт","original_title":"Mijn lief, mijn lief, mijn lief (Милый, милый, милый)","original_language":"Dutch","origin_country":"Нидерланды","original_year":"1609","source_url":"https://en.wikipedia.org/wiki/Pieter_Corneliszoon_Hooft","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1647.","music_adaptations":[],"source_synopsis":"Сонет о возлюбленной, которая зовёт его «милый» трижды подряд, — и от повторения слово становится заново настоящим. Нежность сцены держится на одном маленьком слове, повторённом до тепла.","main_image":"три слова, сказанные над вечерним каналом"},{"title":"Дом из обломков","full_story":"Команда тралового судна застревает в арктическом заносе, радио молчит, и капитан принимает решение: строим. Из обломков кузова, ящиков и сломанного радара они поднимают хижину и заводят внутренние часы — дежурство, игры, сказки, последняя плитка шоколада по очереди. Когда вертолёт находит их, каждый прежде чем уйти обнимает хижину — она осталась стоять, а они улетели.","hero_pov":"член команды, выжившей во льдах","central_conflict":"полярная ночь против рук, которые строят из обломков","emotional_arc":"от паники и спора к безоговорочному братству","ending_direction":"спасение найдено — прощание с хижиной как с членом команды","hook_direction":"руки ещё тёплые — значит, строим","genres":["EDM","Рок"],"moods":["Сила","Тепло"],"energy":"Взрывная","themes":["Дружба","Сила"],"generator_brief":"Большой стадионный EDM со стальным ритмом: удары как забивание гвоздей, хор команды в припеве, финальный дроп — вертолётный винт.","generator_story":"Команда тральщика во льдах, капитан решает: строим. Из обломков они поднимают хижину, заводят свои часы — дежурство, сказки, последняя плитка. Прилетает вертолёт: каждый обнимает хижину на прощание.","primary_genre":"EDM","primary_mood":"Сила","primary_theme":"Дружба","story_shelf":"Трагические истории","conflict_key":"полярная-ночь-против-рук-из-обломков","image_key":"хижина-из-обломков","turn_key":"прощание-с-хижиной","hook_key":"строим-пока-дышим","sort_order":"1181","original_key":"tollens|overwintering-nova-zembla","author_name":"Хендрик Толленс","original_title":"Tafereel van de overwintering der Hollanders op Nova Zembla (Зимовье голландцев на Новой Земле)","original_language":"Dutch","origin_country":"Нидерланды","original_year":"1817","source_url":"https://en.wikipedia.org/wiki/Hendrik_Tollens","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1856.","music_adaptations":[],"source_synopsis":"Эпическая поэма о зимовке голландской команды во льдах Новой Земли: из обломков судна моряки строят «спасённый дом» и переживают полярную ночь ремеслом, часами и взаимной выручкой.","main_image":"хижина, построенная из обломков судна"},{"title":"Под липой","full_story":"Она — из общежития у завода, он — сын владельца, и весь кампус знает, кто кому «не подходит». Они встречаются в парке под старой липой, куда не доходит охрана, и смеются шёпотом. В один из вечеров она решает не прятаться: берёт его за руку посреди лужаек и ведёт к липе напоказ — пусть смотрят, эта радость её, и платит за неё она только смелостью.","hero_pov":"девушка, влюблённая «не в её круг»","central_conflict":"чужие взгляды против права быть видимой с ним","emotional_arc":"от шёпота и оглядок к гордой открытости","ending_direction":"вся трава нас видела — и пусть","hook_direction":"пусть весь луг смотрит","genres":["Хаус","Поп"],"moods":["Эйфория","Радость"],"energy":"Высокая","themes":["Любовь","смелость"],"generator_brief":"Солнечный глубок-хаус с шёпотным вокалом: травяная перкуссия, всплеск струн, в припеве один широкий мажорный аккорд липы.","generator_story":"Она — из общежития, он — сын владельца, и кампус знает, кто кому не подходит. Они встречаются шёпотом под липой — пока она не берёт его за руку и не ведёт напоказ, платя за радость только смелостью.","primary_genre":"Хаус","primary_mood":"Эйфория","primary_theme":"Любовь","story_shelf":"Любовные сцены","conflict_key":"чужие-взгляды-против-липы","image_key":"липа-одна-на-лугу","turn_key":"ведёт-его-за-руку-напоказ","hook_key":"вся-трава-нас-видела","sort_order":"1182","original_key":"walther|under-der-linden","author_name":"Вальтер фон дер Фогельвейде","original_title":"Under der linden (Под липой)","original_language":"German","origin_country":"Германия","original_year":"1200","source_url":"https://en.wikipedia.org/wiki/Walther_von_der_Vogelweide","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 1230.","music_adaptations":[],"source_synopsis":"Девушка из простых рассказывает о радостной тайной встрече с любимым под липой на лугу: пусть весь мир видит — она горда своей радостью, а не стыдится её.","main_image":"одна липа посреди луга"},{"title":"Три несовместимых","full_story":"Старый прораб вечером после сдачи района садится на бетонный блок и накидывает на голову куртку, как в детстве под одеялом. У него на салфетке три вещи, которые не помещаются в одну жизнь: приличие, свобода и настоящая любовь, — и он честно не находит комбинации. Он встаёт с камня и чинит первую попавшуюся лавку во дворе: мир не починить списком, зато лавка теперь стоит.","hero_pov":"старый строитель со списком на салфетке","central_conflict":"три несовместимых желания против маленького реального дела","emotional_arc":"от тупого перебора комбинаций к тёплому действию","ending_direction":"лавка починена — список остался на салфетке","hook_direction":"мир не починить списком","genres":["Рэп","Джаз"],"moods":["Мечтательность","Решимость"],"energy":"Средняя","themes":["примирение","Дом"],"generator_brief":"Ленивый ночной рэп с контрабасом: барабаны как капли дождя, полуречитатив из-под плаща, в финале один тёплый аккорд починенной лавки.","generator_story":"Старый прораб с салфеткой, где три вещи не помещаются в одну жизнь: приличие, свобода, любовь. Комбинации он честно не находит — встаёт с бетонного блока и чинит первую попавшуюся лавку во дворе.","primary_genre":"Рэп","primary_mood":"Мечтательность","primary_theme":"примирение","story_shelf":"Трагические истории","conflict_key":"три-несовместимых-против-малого-дела","image_key":"плащ-на-голове-на-камне","turn_key":"начать-с-одной-лавки","hook_key":"мир-начинается-с-камня","sort_order":"1183","original_key":"walther|ich-saz-uf-eime-steine","author_name":"Вальтер фон дер Фогельвейде","original_title":"Ich saz ûf eime steine (Я сел на камень)","original_language":"German","origin_country":"Германия","original_year":"1200","source_url":"https://en.wikipedia.org/wiki/Walther_von_der_Vogelweide","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 1230.","music_adaptations":[],"source_synopsis":"Поэт сидит на камне, накинув плащ на голову, и думает, как устроить жизнь, в которой соединяются три вещи сразу, — и не находит ответа. Мир не складывается в список.","main_image":"плащ на голове сидящего на камне"},{"title":"В тени голоса","full_story":"В чужом городе он теряет работу в один день и не отвечает маме три дня — голосовые от неё копятся, как тёплый дождь. На третьи сутки он включает её записи, засыпает под них и слышит её кухню: стол, масло, смех сестёр. Утром он покупает билет и записывает маме ответную песню: я вырос в тени твоего голоса — теперь моя тень тебе.","hero_pov":"сын в чужом городе, не ответивший маме","central_conflict":"чужой город и гордость против голоса, который держит","emotional_arc":"от провала и стыда к волне родного голоса и решению вернуться","ending_direction":"билет куплен — ответная песня отправлена","hook_direction":"я вырос в тени твоего голоса","genres":["Рэп","Соул"],"moods":["Тоска","Тепло"],"energy":"Средняя","themes":["Расставание","Семья"],"generator_brief":"Рэп-соул с африканским семплом: тёплый бас, голосовые от мамы вплетены в бэк, припев почти колыбелью на фоне чужого города.","generator_story":"В чужом городе он теряет работу и три дня не отвечает маме — голосовые копятся, как дождь. На третьи сутки он засыпает под её записи, слышит её кухню, а утром покупает билет и записывает ей песню.","primary_genre":"Рэп","primary_mood":"Тоска","primary_theme":"Расставание","story_shelf":"Любовные сцены","conflict_key":"чужой-город-против-голоса-матери","image_key":"голосовые-как-тёплый-дождь","turn_key":"билет-после-трёх-суток-тишины","hook_key":"в-тени-твоего-голоса","sort_order":"1184","original_key":"senghor|femme-noire","author_name":"Леопольд Седар Сенгор","original_title":"Femme noire (Чёрная женщина)","original_language":"French","origin_country":"Сенегал","original_year":"1945","source_url":"https://en.wikipedia.org/wiki/L%C3%A9opold_S%C3%A9dar_Senghor","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2001.","music_adaptations":[],"source_synopsis":"Ода чёрной женщине — сразу матери, любимой и родной земле: поэт в изгнании вызывает её из памяти и растёт в её тени, как в тени дерева.","main_image":"голосовое сообщение из дома посреди чужой ночи"},{"title":"Всё на берегу","full_story":"Он приезжает в деревню матери впервые после её похорон — с деловым костюмом, телефоном и инструкцией «быстро туда-обратно». На берегу её реки он вдруг снимает всё до последнего ключа и складывает на песок: костюм, часы, телефон. По пояс в воде он говорит вслух всё, что не успел, — и вода не поднимает волну, а просто держит. На берег он выходит пустым, впервые лёгким.","hero_pov":"сын, который наконец раздевается до правды","central_conflict":"городская броня против голой честности перед рекой","emotional_arc":"от деловой спешки к дрожи и полному покою","ending_direction":"он выходит из воды пустым — одежда остаётся на берегу","hook_direction":"стою нагим — и спокойно","genres":["Трэп","Эмбиент"],"moods":["Освобождение","Уязвимость"],"energy":"Взрывная","themes":["Возвращение","прошлое"],"generator_brief":"Ритуальный трэп с барабанами обряда: 808 как глубина реки, хоровые подголоски деревни, дроп в момент «вода держит» — тишина, а не взрыв.","generator_story":"Сын приезжает в деревню матери после похорон — костюм, телефон, спешка. На берегу её реки он снимает всё до последнего ключа и говорит воде вслух всё, что не успел: она не поднимает волну, а держит.","primary_genre":"Трэп","primary_mood":"Освобождение","primary_theme":"Возвращение","story_shelf":"Трагические истории","conflict_key":"броня-против-голой-реки","image_key":"одежда-сложена-на-берегу","turn_key":"вода-держит-а-не-волнуется","hook_key":"всё-на-берегу","sort_order":"1185","original_key":"okigbo|heavensgate","author_name":"Кристофер Окигбо","original_title":"Heavensgate (Врата небес)","original_language":"English","origin_country":"Нигерия","original_year":"1962","source_url":"https://en.wikipedia.org/wiki/Christopher_Okigbo","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1967.","music_adaptations":[],"source_synopsis":"Вступление к «Лабиринтам»: поэт стоит нагой перед матерью-рекой Идото и приносит ей себя как подношение — очищение через полную открытость.","main_image":"вся одежда сложена на берегу реки"},{"title":"Не экспонат","full_story":"Дед работает смотрителем в «этнографическом» музее своего же квартала: его юность — под стеклом с подписями для туристов. Внук снимает клип прямо в залах, и дед сначала стыдит его: мы не декорация. Но когда туристы фотографируют экспонаты на телефон, дед берёт у внука микрофон и записывает голосом то, чего нет ни на одной табличке. Клип выходит с дедовым голосом — музей меняет экспозицию, а квартал празднует у входа.","hero_pov":"внук-рэпер и дед-смотритель в одном музее","central_conflict":"культура под стеклом против культуры, которая живёт","emotional_arc":"от стыда и спора поколений к совместному голосу","ending_direction":"экспозиция меняется — голос живёт без стекла","hook_direction":"не снимайте нас — снимайте с нами","genres":["Хип-хоп","Фолк"],"moods":["Протест","Сила"],"energy":"Высокая","themes":["Примирение","Сцена"],"generator_brief":"Бум-бэп с афро-фолк семплами: дедов голос сэмплом в бриджах, читка внука с улицей в бэке, припев — половина зала, половина квартала.","generator_story":"Дед смотрит музей своего квартала, где его юность под стеклом с подписями для туристов. Внук снимает клип в залах — и дед записывает голосом то, чего нет ни на табличке: музей меняет экспозицию.","primary_genre":"Хип-хоп","primary_mood":"Протест","primary_theme":"Примирение","story_shelf":"Юмор: семейные драмы","conflict_key":"экспонат-против-живого-квартала","image_key":"витрина-с-живым-кварталом","turn_key":"дед-берёт-микрофон","hook_key":"мы-не-музей-мы-живые","sort_order":"1186","original_key":"osadebay|young-africas-plea","author_name":"Деннис Осадебай","original_title":"Young Africa's Plea (Мольба молодой Африки)","original_language":"English","origin_country":"Нигерия","original_year":"1952","source_url":"https://en.wikipedia.org/wiki/Dennis_Osadebay","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1994.","music_adaptations":[],"source_synopsis":"Молодая Африка просит: не сохраняйте наши обычаи как редкие диковинки для чужих историков — дайте культуре жить и расти самой, а не под стеклом.","main_image":"музейная витрина, за стеклом которой живой квартал"},{"title":"Признание через дождь","full_story":"В их чате нельзя говорить о чувствах прямо — старшие читают, да и сам он не умеет. Вместо признания он присылает ей картинки дождя над рисовыми полями и текст: дождь сегодня с твоего берега. Она догадывается и отвечает той же формой — про фрукт, который падает только к корню. Вся их любовь живёт в метафорах, пока однажды он не решает прислать пантун без второй части, где должен быть смысл.","hero_pov":"парень, влюблённый только намёками","central_conflict":"запрет прямых слов против необходимости сказать","emotional_arc":"от безопасных картинок к почти прямому шагу","ending_direction":"последний пантун прислан без смысла — смысл она дописывает сама","hook_direction":"дождь — это про тебя","genres":["Электропоп","Поп"],"moods":["Любовь","Ирония"],"energy":"Средняя","themes":["Любовь","Праздник"],"generator_brief":"Лёгкий тропический электропоп: дождевые капли в арпеджио, вокал чуть с прищуром, припев поёт намёк, а не слово.","generator_story":"В их чате нельзя говорить о чувствах: вместо признания он шлёт картинки дождя, она отвечает метафорой про фрукт у корня. Вся любовь живёт намёками — пока он не шлёт пантун без второй части.","primary_genre":"Электропоп","primary_mood":"Любовь","primary_theme":"Любовь","story_shelf":"Любовные сцены","conflict_key":"запрет-прямых-слов-против-признания","image_key":"четверостишие-с-дождём","turn_key":"пантун-без-второй-строки","hook_key":"скажу-цветком-скажу-дождём","sort_order":"1187","original_key":"anon-pantun|pantun","author_name":"Аноним — малайский пантун","original_title":"Pantun (традиция четверостиший)","original_language":"Malay","origin_country":"Малайзия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Pantun","rights_check":"Справочно: права не проверяются, идея не текст. Анонимная традиция, эпоха XV век.","music_adaptations":[],"source_synopsis":"Пантун говорит о главном через природу: первые строки — образ из мира, последние — настоящий смысл. Прямых слов традиция не оставляет: всё главное — через намёк.","main_image":"четверостишие, где дождь значит «скучаю»"},{"title":"Пантун-баттл на свадьбе","full_story":"Свадьба детей двух семей, которые двадцать лет судятся из-за дороги через поле. По традиции у микрофона начинается обмен пантунами: дяди с обеих сторон отвечают друг другу четверостишиями, и гости веселеют с каждым раундом. К пятому раунду острота уже не колет, а смешит, тёти обеих сторон хихикают в один голос — договор о дороге подписывают под общий смех и финальный пантун от молодожёнов.","hero_pov":"молодожёны, чья свадьба судит вражду семей","central_conflict":"двадцатилетняя вражда семей против рифм за микрофоном","emotional_arc":"от холодных столов к общему смеху и миру","ending_direction":"договор о дороге подписан под финальный пантун","hook_direction":"ответь острее — и будет мир","genres":["Латина","Поп"],"moods":["Радость","Ирония"],"energy":"Высокая","themes":["примирение","Праздник"],"generator_brief":"Свадебная кумбия с баттл-логикой: духовые на подъёме, перекличка двух голосов, каждый куплет — новый раунд, припев объединяет столы.","generator_story":"Свадьба детей семей, двадцать лет судящихся за дорогу: дяди обмениваются у микрофона четверостишиями, гости веселеют с каждым раундом. К пятому острота уже смешит — договор подписывают под общий смех.","primary_genre":"Латина","primary_mood":"Радость","primary_theme":"примирение","story_shelf":"Юмор: семейные драмы","conflict_key":"вражда-семей-против-рифм-на-микрофоне","image_key":"микрофон-между-столами","turn_key":"острота-становится-смехом","hook_key":"ответь-острее-и-мир","sort_order":"1188","original_key":"anon-pantun|pantun-berbalas","author_name":"Аноним — малайский пантун","original_title":"Pantun berbalas (обмен пантунами на свадьбе)","original_language":"Malay","origin_country":"Малайзия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Pantun","rights_check":"Справочно: права не проверяются, идея не текст. Анонимная традиция, эпоха XV век.","music_adaptations":[],"source_synopsis":"На малайской свадьбе две семьи обмениваются пантунами: острота отвечает остроте, и подарки переходят из рук в руки только после достойного ответа. Рифма здесь — вежливый поединок и мост между родами.","main_image":"микрофон переходит между столами двух семей"},{"title":"Коростель не умолкает","full_story":"Он вернулся в бабушкин дом разбирать вещи после похорон и не спит первую ночь: в ржи под окном не умолкает коростель — как будто зовёт по имени. В три ночи он выходит в поле в одной футболке, ложится в рожь и говорит вслух с тем, кого больше нет. К рассвету он засыпает на сеновале, впервые спокойно, — коростель всё кричит, но уже не тревожно, а рядом.","hero_pov":"внук в пустом бабушкином доме","central_conflict":"бессонница горя против зова ночного поля","emotional_arc":"от пустой бессонницы к разговору и сну","ending_direction":"рассвет, сеновал, крик коростеля стал спутником","hook_direction":"поле говорит со мной всю ночь","genres":["Регги","Лоу-фай"],"moods":["Одиночество","Спокойствие"],"energy":"Низкая","themes":["примирение","Природа"],"generator_brief":"Ночной лоу-фай регги: медленный ритм как качание ржи, стрекот коростеля в перкуссии, голос почти во сне, к финалу — один тёплый рассветный аккорд.","generator_story":"После похорон бабушки он не спит: в ржи под окном кричит коростель, будто зовёт по имени. В три ночи он ложится в рожь, говорит вслух с тем, кого больше нет, — к рассвету засыпает на сеновале.","primary_genre":"Регги","primary_mood":"Одиночество","primary_theme":"примирение","story_shelf":"Люди и животные","conflict_key":"бессонница-против-зова-коростеля","image_key":"луна-над-ржаным-полем","turn_key":"разговор-в-ржи-и-сон","hook_key":"коростель-всё-зовёт","sort_order":"1189","original_key":"eino-leino|nocturne","author_name":"Эйно Лейно","original_title":"Nocturne (Ноктюрн)","original_language":"Finnish","origin_country":"Финляндия","original_year":"1903","source_url":"https://en.wikipedia.org/wiki/Eino_Leino","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1926.","music_adaptations":[],"source_synopsis":"Летняя ночь: полная луна над ржаным полем, и коростель в ржи кричит всю ночь, не умолкая. Ночные голоса не дают спать — и в этой бессоннице мир звучит до дрожи.","main_image":"полная луна над ржаным полем и голос коростеля"},{"title":"Не стану долгом","full_story":"Её свадьбу решают за столом: брат проиграл свою дуэль и заплатил ею — выгодному жениху вдвое старше. Она не скандалит и не плачет напоказ: она пишет матери письмо, где прощает всех, кроме самой сделки, и уезжает к морю одна. Из приморского городка она присылает фото пустого берега и строку «я не долг и не вклад» — мать впервые слышит её голос без посредников.","hero_pov":"девушка, которую поставили в счёт сделки","central_conflict":"выгодная партия семьи против права не быть платой","emotional_arc":"от покорной тишины к холодному ясному выбору","ending_direction":"пустой берег и строка: я не долг","hook_direction":"меня не отдают в счёт","genres":["Драм-н-бейс","Синтвейв"],"moods":["Тоска","Освобождение"],"energy":"Средняя","themes":["Расставание","Свобода"],"generator_brief":"Ликвид-драм-н-бейс с северным холодом: подводные подушки сабвуфера как вода, голос девушки ровный и далёкий, дроп — шаг в открытое море.","generator_story":"Брат проиграл дуэль, и свадьба сестры стала платой — жених вдвое старше. Она прощает всех, кроме самой сделки, и уезжает к морю: оттуда прилетает фото пустого берега и строка «я не долг».","primary_genre":"Драм-н-бейс","primary_mood":"Освобождение","primary_theme":"Расставание","story_shelf":"Трагические истории","conflict_key":"сделка-семьи-против-своей-воды","image_key":"пустой-берег-вместо-свадьбы","turn_key":"письмо-с-фото-берега","hook_key":"не-стану-долгом","sort_order":"1190","original_key":"kalevala|aino","author_name":"Калевала (свод Элиаса Лённрота)","original_title":"Kalevala — Aino (Айно, руны 3–5)","original_language":"Finnish","origin_country":"Финляндия","original_year":"1835","source_url":"https://en.wikipedia.org/wiki/Kalevala","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1884.","music_adaptations":[],"source_synopsis":"Айно, сестра Йоухкайнена, отдана в жёны старику Вяйнямёйнену в уплату за проигранную борьбу. Девушка отказывается от такого брака, уходит странствовать и выбирает море — воду, в которой исчезает, оставив матери рыдание.","main_image":"девушка у моря вместо свадебного стола"},{"title":"Кантеле из щуки","full_story":"У молодого уличного музыканта крадут отцовскую гитару — вместе с ней как будто забрали право играть. Из того, что осталось — кастрюль, расстроенного пианино без четырёх клавиш и петель отцовской куртки — он собирает свой первый самодельный сет и выкладывает запись с балкона. К вечеру вся улица стоит во дворе слушать, а соседский пёс воёт точно в ноту: потеря стала инструментом со своим голосом.","hero_pov":"уличный музыкант, у которого украли гитару","central_conflict":"утрата инструмента против права заново звучать","emotional_arc":"от пустоты в руках к сборке нового звука из подручного","ending_direction":"вся улица слушает — пёс воёт в ноту","hook_direction":"из потери строим звук","genres":["EDM","Фолк"],"moods":["Вдохновение","Тепло"],"energy":"Высокая","themes":["Дружба","музыка"],"generator_brief":"Фолк-EDM с самодельным саундом: кастрюли как калимба, глубокий бас из гула щучьей челюсти, дроп — двор, который подхватывает мелодию хором.","generator_story":"У музыканта крадут отцовскую гитару — будто забрали право играть. Из кастрюль, расстроенного пианино и петель отцовской куртки он собирает сет: к вечеру вся улица слушает, а соседский пёс воёт в ноту.","primary_genre":"EDM","primary_mood":"Вдохновение","primary_theme":"Дружба","story_shelf":"Люди и животные","conflict_key":"утрата-инструмента-против-нового-звука","image_key":"инструмент-из-челюсти-щуки","turn_key":"вся-улица-пришла-слушать","hook_key":"из-потери-строим-звук","sort_order":"1191","original_key":"kalevala|kantele-pike","author_name":"Калевала (свод Элиаса Лённрота)","original_title":"Kalevala — kantele (Кантеле из щуки, руны 39–41)","original_language":"Finnish","origin_country":"Финляндия","original_year":"1835","source_url":"https://en.wikipedia.org/wiki/Kalevala","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1884.","music_adaptations":[],"source_synopsis":"Вяйнямёйнен теряет свою кантеле и делает новую из челюсти гигантской щуки. Когда он играет, вся природа приходит слушать: звери плачут, птицы замирают, и даже сам игрок заливается слезами.","main_image":"инструмент, сделанный из челюсти щуки"},{"title":"Портрет, который я забыл","full_story":"Он давно живёт один и почему-то не снимает с полки старый портрет ушедшей любимой. С каждым годом её лицо в памяти всё бледнее, и он уже не может по-настоящему вспомнить её улыбку. Ночью она приходит в сон прежней — и он впервые за годы просит не будить себя и вернуть хотя бы это.","hero_pov":"Мужчина, который остался один с памятью о ней","central_conflict":"Время стирает лицо любимой, а сон возвращает его","emotional_arc":"От притихшего забвения к отчаянной просьбе вернуть прошлое","ending_direction":"Он просит сон не заканчиваться — и засыпает с улыбкой","hook_direction":"Верни мне её лицо из сна","genres":["Баллада","Эмбиент"],"moods":["Грусть","Любовь"],"energy":"Низкая","themes":["память","прошлое"],"generator_brief":"Тихая ночная баллада с тёплой акустикой и редкими струнными; куплеты почти шёпотом, припев широким дыханием на грани сна.","generator_story":"Он давно один и не снимает с полки портрет ушедшей любимой: её лицо в памяти бледнеет, улыбку уже не вспомнить. Ночью она приходит в сон прежней — и он впервые за годы просит сон не заканчиваться.","primary_genre":"Баллада","primary_mood":"Грусть","primary_theme":"память","story_shelf":"Любовные сцены","conflict_key":"стёршееся-лицо-против-портрета","image_key":"сон-возвращённое-лицо","turn_key":"во-сне-она-возвращается","hook_key":"верни-лицо-из-сна","sort_order":"1192","original_key":"alexander-blok|o-doblestyah-o-podvigah-o-slave","author_name":"Александр Блок","original_title":"О доблестях, о подвигах, о славе","original_language":"Russian","origin_country":"Россия","original_year":"1908","source_url":"https://ru.wikisource.org/wiki/О_доблестях,_о_подвигах,_о_славе_(Блок)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1921.","music_adaptations":[],"source_synopsis":"Человек живёт один в пустой квартире с портретом ушедшей любимой, но годы стирают её черты из памяти. Однажды во сне она возвращается прежней — и он с мольбой просит вернуть ему хотя бы это видение.","main_image":"стёртый портрет на тёмной полке"},{"title":"Громко жить","full_story":"Герой в тяжёлое время решает не экономить себя: будить всех вокруг, любить без полутонов и записывать всё живое. Он знает, что легко сгореть, но выбирает жар. Припев песни — его клятва самому себе, произнесённая вслух каждый день.","hero_pov":"Человек, который решил не прятаться от жизни","central_conflict":"Страх сгореть против нежелания выживать вполсилы","emotional_arc":"От усталого мрака к дерзкой жажде жить на полную","ending_direction":"Он выходит в мрак улицы с огнём в груди","hook_direction":"Я хочу жить громко","genres":["Рок","Эпик-рок"],"moods":["Вдохновение","Эйфория"],"energy":"Взрывная","themes":["Мечта","Сила"],"generator_brief":"Взрывной рок с драйвовым ритмом и рваным куплетом; припев — выкрик-манифест поверх гитарной стены и барабанной тарахотки.","generator_story":"В тяжёлое время он решает не экономить себя: будить всех, любить без полутонов. Он знает цену сгоревшим, но выбирает жар — и каждый день повторяет себе клятву, выходя в мрак улиц с огнём в груди.","primary_genre":"Рок","primary_mood":"Вдохновение","primary_theme":"Мечта","story_shelf":"Трагические истории","conflict_key":"страх-против-полной-жизни","image_key":"громкое-сердце-в-беде","turn_key":"страх-отступает-перед-желанием","hook_key":"хочу-жить-на-полную","sort_order":"1193","original_key":"alexander-blok|o-ya-hochu-bezumno-zhit","author_name":"Александр Блок","original_title":"О, я хочу безумно жить","original_language":"Russian","origin_country":"Россия","original_year":"1914","source_url":"https://ru.wikisource.org/wiki/О,_я_хочу_безумно_жить_(Блок)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1921.","music_adaptations":[],"source_synopsis":"В разгар большой беды поэт бросает вызов унынию: он решает жить изо всех сил, одушевить мёртвое и воплотить несбывшееся. Для него страшна не смерть, а гаснущий ум и пустота вокруг.","main_image":"человек зажигает огонь посреди тёмной комнаты"},{"title":"Дом, где остаётся живое","full_story":"В городе, где закрываются театры и гаснут окна, герой приходит к старому дому поэта, как приходят к последнему родственнику. Ему важно, что внутри всё на своих местах: книги, портреты, живой свет. Он уходит обратно в мрак с обещанием носить это тепло в себе до конца.","hero_pov":"Голодный поэт в мёртвом городе","central_conflict":"Мёртвые дни вокруг против живого света культуры","emotional_arc":"От ледяного отчаяния к тихой уверенности в спасении","ending_direction":"Он уносит свет дома с собой в темноту","hook_direction":"Там, где свет — там живые","genres":["Эпик-рок","Баллада"],"moods":["Надежда","Благородство"],"energy":"Взрывная","themes":["память","дом"],"generator_brief":"Торжественный эпик-рок с органной подкладкой и оркестровым нарастанием; финал — взрыв хора из полной тишины.","generator_story":"В городе, где гаснут театры, голодный поэт приходит к старому дому поэта, как к последнему родственнику: книги, портреты, неугасимый огонь. Он уходит в мрак с обещанием носить это тепло до конца.","primary_genre":"Эпик-рок","primary_mood":"Надежда","primary_theme":"память","story_shelf":"Трагические истории","conflict_key":"умирающий-город-против-живого-дома","image_key":"свет-дома-как-прибежище","turn_key":"дом-отвечает-живым","hook_key":"где-нас-обступает-живое","sort_order":"1194","original_key":"alexander-blok|pushkinskomu-domu","author_name":"Александр Блок","original_title":"Пушкинскому Дому","original_language":"Russian","origin_country":"Россия","original_year":"1921","source_url":"https://ru.wikisource.org/wiki/Пушкинскому_Дому_(Блок)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1921.","music_adaptations":[],"source_synopsis":"Февраль 1921-го: умирающий город, сырые квартиры и голод. Поэт обращается к дому Пушкина как к месту, где культура остаётся живой и обступает человека теплом, как семья.","main_image":"свет из окна старого дома над тёмной водой"},{"title":"Глаза в колыбельной","full_story":"Она узнаёт новость ранним утром и не может произнести её вслух: муж завтракает, чайник шумит, дом требует обычности. Ночью она поёт малышу и впервые смотрит в глаза ребёнка — там он, живой. Так тайная любовь получает продолжение.","hero_pov":"Женщина, скрывающая горе в своей семье","central_conflict":"Скрытое горевание против обязательного обычного дня","emotional_arc":"От ледяного ужаса к тихому продолжению любви","ending_direction":"Колыбельная становится единственной правдой вечера","hook_direction":"У тебя его глаза","genres":["Баллада","Лоу-фай"],"moods":["Боль","Нежность"],"energy":"Низкая","themes":["память","семья"],"generator_brief":"Тихая лоу-баллада с хрустальными клавишами; куплеты почти шёпотом, припев держит одну нежную ноту боли.","generator_story":"Она узнаёт новость утром и не может произнести вслух — муж завтракает, дом требует обычности. Ночью, поя колыбельную, она впервые смотрит ребёнку в глаза: там он — тайная любовь получает продолжение.","primary_genre":"Баллада","primary_mood":"Боль","primary_theme":"память","story_shelf":"Трагические истории","conflict_key":"скрытое-горевание-против-обычного-дня","image_key":"серые-глаза-в-колыбельной","turn_key":"песня-ребёнку-вскрывает-тайну","hook_key":"у-тебя-его-глаза","sort_order":"1195","original_key":"anna-ahmatova|seroglazyy-korol","author_name":"Анна Ахматова","original_title":"Сероглазый король","original_language":"Russian","origin_country":"Россия","original_year":"1910","source_url":"https://ru.wikisource.org/wiki/Сероглазый_король_(Ахматова)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1966.","music_adaptations":[],"source_synopsis":"Женщина узнаёт о гибели возлюбленного — сероглазого короля её тайной любви. Дом живёт обычной жизнью, а она поёт новорождённому ребёнку, у которого такие же серые глаза.","main_image":"мать поёт над колыбелью, у младенца его глаза"},{"title":"Клятва на перроне","full_story":"Молодая мать провожает мужа и одновременно брата; она договаривается с другими женщинами не плакать при них. В момент, когда поезд трогается, гул перрона превращает прощание в присягу. Она впервые чувствует себя частью чего-то огромного.","hero_pov":"Женщина, остающаяся с детьми и домом","central_conflict":"Желание разрыдаться против принятой на себя клятвы","emotional_arc":"От паники проводов к твёрдому братству женщин","ending_direction":"Поезд уходит, а клятва остаётся стоять на перроне","hook_direction":"Мы клянемся — и держимся","genres":["Эпик-рок","Рок"],"moods":["Решимость","Смелость"],"energy":"Взрывная","themes":["дорога","семья"],"generator_brief":"Маршевый эпик-рок с барабанным ритмом-сердцем и женским хором в припеве; динамика от стука поездов к гимну.","generator_story":"Молодая мать провожает мужа и брата одним поездом — женщины договорились не плакать. Когда поезд трогается, гул перрона превращает прощание в присягу: она впервые чувствует себя частью огромного.","primary_genre":"Эпик-рок","primary_mood":"Решимость","primary_theme":"дорога","story_shelf":"Любовные сцены","conflict_key":"провод-без-слёз-против-плача","image_key":"перрон-и-женская-клятва","turn_key":"прощание-становится-присягой","hook_key":"мы-клянёмся-и-держимся","sort_order":"1196","original_key":"anna-ahmatova|klyatva","author_name":"Анна Ахматова","original_title":"Клятва","original_language":"Russian","origin_country":"Россия","original_year":"1941","source_url":"http://yro.narod.ru/bibliotheca/axmat.htm","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1966.","music_adaptations":[],"source_synopsis":"Первые дни войны: женщины у станций провожают сыновей и мужей. Вместо слёз они дают друг перед другом присягу — хранить детей, дом и землю.","main_image":"перрон, где женщины хором дают присягу"},{"title":"Слово как ребёнок","full_story":"Героиня собирает своих — тех, кто говорит на одном языке, — и объявляет общую задачу: не дать родной речи сгинуть. Каждая сцена песни — передача слова из рук в руки: бабушка, ребёнок, солдат, учитель. К финалу язык становится их общим младшим.","hero_pov":"Голос народа, отвечающий за свою речь","central_conflict":"Гроза, стирающая всё живое, против клятвы сохранить слово","emotional_arc":"От страха утраты к соборной уверенности","ending_direction":"Слово передано дальше — в новые руки","hook_direction":"Речь мы сохраним","genres":["Эпик-рок","Рок"],"moods":["Сила","Надежда"],"energy":"Высокая","themes":["память","голос"],"generator_brief":"Оркестровый эпик-рок с широким хором; ритм как единый шаг, припев — общая клятва в унисон.","generator_story":"Героиня собирает всех, кто говорит на одном языке, и ставит задачу: не дать родной речи сгинуть. Слово передают из рук в руки — бабушка, ребёнок, солдат, учитель, — язык становится их общим младшим.","primary_genre":"Эпик-рок","primary_mood":"Сила","primary_theme":"память","story_shelf":"Трагические истории","conflict_key":"беда-против-родного-слова","image_key":"слово-как-ребёнок-на-руках","turn_key":"присяга-родной-речи","hook_key":"сохраним-речь-назло-беде","sort_order":"1197","original_key":"anna-ahmatova|muzhestvo","author_name":"Анна Ахматова","original_title":"Мужество","original_language":"Russian","origin_country":"Россия","original_year":"1942","source_url":"http://yro.narod.ru/bibliotheca/axmat.htm","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1966.","music_adaptations":[],"source_synopsis":"В год страшной беды народ клянётся сберечь родную речь — великий язык, как сберегают ребёнка: чистым, свободным, своим. Слово объявляется живым существом, за которое отвечают все.","main_image":"руки, бережно несущие слово-ребёнка сквозь огонь"},{"title":"Каменное и живое","full_story":"Женщина держит в руках бумагу с приговором — она ждала его семнадцать месяцев и всё равно не готова. Память кричит, что мир кончился, но тело говорит: ты жива. Она убирает бумагу, поднимает голову и идёт дальше — у неё ещё есть, кому жить.","hero_pov":"Мать, получившая приговор и решившая выстоять","central_conflict":"Каменное слово против ещё живой груди","emotional_arc":"От разлома к упрямому решению жить","ending_direction":"Она выходит из зала ожидания под дождь — и не падает","hook_direction":"Справлюсь как-нибудь","genres":["Баллада","Эмбиент"],"moods":["Уязвимость","Сила"],"energy":"Низкая","themes":["прошлое","семья"],"generator_brief":"Минималистичная баллада: приглушённые клавишные, дыхание в микрофон, припев вполголоса на одной опорной ноте.","generator_story":"Женщина держит приговор, которого ждала семнадцать месяцев. Память кричит, что мир кончился, тело отвечает: ты жива — она выходит из зала под дождь, у неё ещё есть, кому жить.","primary_genre":"Баллада","primary_mood":"Уязвимость","primary_theme":"прошлое","story_shelf":"Трагические истории","conflict_key":"каменное-слово-на-живой-груди","image_key":"бумажка-приговора-в-руках","turn_key":"слово-не-ломает-мать","hook_key":"справлюсь-как-нибудь","sort_order":"1198","original_key":"anna-ahmatova|prigovor-rekviem","author_name":"Анна Ахматова","original_title":"Приговор (Из «Реквиема»)","original_language":"Russian","origin_country":"Россия","original_year":"1939","source_url":"https://vtoraya-literatura.com/pdf/akhmatova_requiem_samizdat__jpg.pdf","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1966.","music_adaptations":[],"source_synopsis":"Мать из многолетней очереди к тюрьме получает приговор сыну. Слово падает как камень на ещё живую грудь, но она решает: справлюсь как-нибудь — и остаётся стоять живой.","main_image":"каменное слово, упавшее на грудь"},{"title":"Двоеточие между нами","full_story":"Современная пара живёт на расстоянии: чужие города, видеозвонки, циферблаты в разных поясах. Героиня отказывается называть это разлукой — для неё пробел между ними лишь знак, который она сама ставит и сама снимает. Ночью она пишет так, будто они всё ещё дышат в такт.","hero_pov":"Девушка, влюблённая через континент","central_conflict":"Вёрсты и часы против двух рук, помнящих друг друга","emotional_arc":"От тоски разлуки к гордому обходу расстояния","ending_direction":"Она ставит двоеточие и продолжает письмо","hook_direction":"Вёрсты нас не разъединят","genres":["Инди-поп","Поп"],"moods":["Романтика","Тоска"],"energy":"Средняя","themes":["письмо","любовь"],"generator_brief":"Лёгкий инди-поп с пружинящим басом и пульсирующими клавишами; припев разговорный, почти с улыбкой.","generator_story":"Пара живёт на расстоянии: чужие города, видеозвонки. Героиня отказывается называть это разлукой — пробел между ними знак, который она сама ставит и снимает, — и пишет ночью, будто они дышат в такт.","primary_genre":"Инди-поп","primary_mood":"Романтика","primary_theme":"письмо","story_shelf":"Любовные сцены","conflict_key":"вёрсты-против-ручек-губ","image_key":"двоеточие-между-нами","turn_key":"руки-помнят-вопреки-вёрстам","hook_key":"рас-стояние-поперёк-сна","sort_order":"1199","original_key":"marina-tsvetaeva|ras-stoyanie-versty-mili","author_name":"Марина Цветаева","original_title":"Рас-стояние: вёрсты, мили","original_language":"Russian","origin_country":"Россия","original_year":"1922","source_url":"https://ru.wikisource.org/wiki/Рас-стояние:_версты,_мили_(Цветаева)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1941.","music_adaptations":[],"source_synopsis":"Влюблённых разведены вёрстами и часами: расстояние разрезало слово и расставило их по разным городам. Но любовь живёт не в километрах — руки и губы продолжают помнить друг друга.","main_image":"двоеточие между двумя словами"},{"title":"Родиться бы в ту эпоху","full_story":"Девушка, помешанная на чужом прошлом, живёт в наполовину вымышленном времени: старые фильмы, мундиры, письма. Живые молодые люди рядом кажутся ей скучными — вся её любовь ушла в историю. Однажды она ловит себя: чужую эпоху она повторить может, а прожить свою — ещё нет.","hero_pov":"Девушка, влюблённая в эпоху, где её не было","central_conflict":"Ностальгия по чужому прошлому против реальной жизни сейчас","emotional_arc":"От мечтательного бега назад к тихому выбору настоящего","ending_direction":"Она снимает чужой мундир мечты и выходит к живым","hook_direction":"Мне бы родиться тогда","genres":["Инди-поп","Баллада"],"moods":["Мечтательность","Тоска"],"energy":"Средняя","themes":["прошлое","Мечта"],"generator_brief":"Ретро-инди-поп с вальсовым раскачивом и духовой подкладкой; куплеты мечтательно, припев с ностальгическим порывом.","generator_story":"Девушка живёт в наполовину вымышленном прошлом: фильмы, письма, — а живые молодые люди кажутся скучными. Она ловит себя: чужую эпоху повторить можно, свою прожить ещё нет — и снимает мундир мечты.","primary_genre":"Инди-поп","primary_mood":"Мечтательность","primary_theme":"прошлое","story_shelf":"Любовные сцены","conflict_key":"поздняя-влюблённость-в-чужую-эпоху","image_key":"шинели-как-паруса","turn_key":"прошлое-становится-героем","hook_key":"родиться-бы-тогда","sort_order":"1200","original_key":"marina-tsvetaeva|generalam-dvenadcatogo-goda","author_name":"Марина Цветаева","original_title":"Генералам двенадцатого года","original_language":"Russian","origin_country":"Россия","original_year":"1913","source_url":"https://ru.wikisource.org/wiki/Генералам_двенадцатого_года_(Цветаева)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1941.","music_adaptations":[],"source_synopsis":"Героиня, родившаяся много позже героев 1812 года, влюблена в поколение, которое стало легендой: молодые офицеры со шлейфом славы. Она тоскует по эпохе, где её не было, как по несбывшемуся роману.","main_image":"широкие шинели прошлого, идущие в будущее"},{"title":"Квадрат чернил","full_story":"Женщина каждый вечер ходит мимо почты и знает, как выглядит счастье: маленький квадрат бумаги с парой слов от него. Она перечитывает старые письма, пока не приходит новое, и понимает, что держит в руках не бумагу, а жизнь. Война забирает всё, кроме этого квадрата.","hero_pov":"Женщина, ждущая письма с войны","central_conflict":"Большая смерть против крошечного квадрата письма","emotional_arc":"От изматывающего ожидания к обвалу счастья у почтового ящика","ending_direction":"Новое письмо приходит — она смеётся и плачет сразу","hook_direction":"Письмо важнее снарядов","genres":["Баллада","Поп"],"moods":["Надежда","Тревога"],"energy":"Средняя","themes":["письмо","ожидание"],"generator_brief":"Сдержанная баллада с тикающей перкуссией как ходом часов; припев раскрывается тёплыми струнными.","generator_story":"Каждый вечер женщина проходит мимо почты: её счастье — квадрат бумаги с парой слов от него. Война забирает всё вокруг, но новое письмо приходит — и она у ящика смеётся и плачет сразу.","primary_genre":"Баллада","primary_mood":"Надежда","primary_theme":"письмо","story_shelf":"Любовные сцены","conflict_key":"квадрат-письма-против-смерти","image_key":"лоскут-со-словом-внутри","turn_key":"письмо-оказывается-жизнью","hook_key":"ждём-квадрат-чернил","sort_order":"1201","original_key":"marina-tsvetaeva|pismo-1923","author_name":"Марина Цветаева","original_title":"Письмо","original_language":"Russian","origin_country":"Россия","original_year":"1923","source_url":"https://slova.org.ru/cvetaeva/pismo/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1941.","music_adaptations":[],"source_synopsis":"На войне ждут не вестей вообще, а конкретного письма — крошечного лоскута со словом внутри. Против большой смерти у человека один маленький квадрат чернил, и он весит больше снарядов.","main_image":"квадратный лоскут письма на столе"},{"title":"Играй громче, шарманка","full_story":"Эмигрант ловит себя на том, что больше не верит ни в рощи, ни в соловьёв: всё, что он помнит, звучит теперь чужим языком. Уличная музыкантша поёт его детство вразнобой и фальшиво, и он впервые не поправляет её. Он просто стоит под дождём и просит: играй громче — пусть хотя бы сказка не сдаётся.","hero_pov":"Изгнанник, который разучился верить","central_conflict":"Знание о неправде против желания, чтобы сказка жила","emotional_arc":"От горького скепсиса к приказу мечте звучать громче","ending_direction":"Шарманка становится громче, и дождь ей подпевает","hook_direction":"Играй громче — пусть будет неправда","genres":["Баллада","Лоу-фай"],"moods":["Мечтательность","Боль"],"energy":"Низкая","themes":["Мечта","прошлое"],"generator_brief":"Лоу-фай баллада с шарманочными клавишами и виниловым шорохом; припев — срывающийся приказ мечте звучать громче.","generator_story":"Эмигрант разучился верить в рощи и соловьёв. Под дождём уличная музыкантша фальшиво играет его детство — и он впервые не поправляет её, а просит играть громче, пока дождь не подпевает шарманке.","primary_genre":"Баллада","primary_mood":"Мечтательность","primary_theme":"Мечта","story_shelf":"Трагические истории","conflict_key":"знание-против-любимой-сказки","image_key":"шарманка-в-чужом-городе","turn_key":"сказку-просят-громче","hook_key":"играй-громче-сказку","sort_order":"1202","original_key":"vladislav-khodasevich|starik-i-devochka-gorbunya","author_name":"Владислав Ходасевич","original_title":"Старик и девочка-горбунья","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/hodasevich/starik_i_devochka_gorbunya/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1939.","music_adaptations":[],"source_synopsis":"В чужом дождливом городе шарманщица поёт сказку про несуществующие рощи и соловьёв. Прохожий знает, что всё это неправда и сказка обречена исчезнуть, — но именно поэтому просит шарманку звучать громче.","main_image":"шарманка в чужом городе под осенним дождём"},{"title":"Двор, где правили дети","full_story":"Взрослый герой застревает в рутине и вдруг вспоминает жаркий двор своего детства: гирлянды над головой, гармоника, игра в коронацию из занавесок. Он понимает, что тогда впервые правил своим миром — всерьёз, без скидки на возраст. Вечером он ищет в своём городе похожий двор и находит его у соседских детей.","hero_pov":"Взрослый, вернувшийся в свой детский двор","central_conflict":"Взрослая спешка против двора, где всё всерьёз","emotional_arc":"От выцветшей рутины к жаркому всплеску памяти","ending_direction":"Он садится на бордюр к детям и снова становится своим","hook_direction":"Верни меня в тот двор","genres":["Лоу-фай","Инди-поп"],"moods":["Ностальгия","Тепло"],"energy":"Средняя","themes":["Детство","дом"],"generator_brief":"Тёплый лоу-фай с уличными звуками двора и подрагивающей гармоникой; припев — почти детский напев хором.","generator_story":"Застрявший в рутине взрослый вспоминает двор детства: гармоника, коронация из занавесок. Вечером он находит похожий двор у соседских детей и садится на бордюр — снова свой.","primary_genre":"Лоу-фай","primary_mood":"Ностальгия","primary_theme":"Детство","story_shelf":"Юмор: семейные драмы","conflict_key":"взрослая-спешка-против-двора-детства","image_key":"коронация-из-занавесок","turn_key":"двор-принимает-взрослого","hook_key":"вернись-в-тот-двор","sort_order":"1203","original_key":"vladislav-khodasevich|ya-pomnyu-v-detstve-dushnyi-vecher","author_name":"Владислав Ходасевич","original_title":"Я помню в детстве душный летний вечер","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/hodasevich/ya_pomnju_v_detstve_dushnyi_letnii_vecher/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1939.","music_adaptations":[],"source_synopsis":"В душном дворе летнего вечера играет гармоника, дети устраивают собственную игру в коронацию из тряпок, взрослые живут своей тягучей жизнью. Для мальчика этот двор — первое царство, где всё всерьёз по-настоящему.","main_image":"двор с гармоникой и детской процессией"},{"title":"Наш примус на двоих","full_story":"Пара, у которой нет почти ничего, каждый вечер отстраивает на кухне своё государство: качает примус, режет хлеб, смеётся над громкой жизнью за окном. Внешний мир ярче и опаснее, но здесь можно говорить тихо о самом важном и быть собой. Дом держится именно на этих вечерах.","hero_pov":"Мужчина, у которого есть только эта кухня и она","central_conflict":"Нищета и громкий пугающий мир против тихой кухни на двоих","emotional_arc":"От защитной иронии к почти детской нежности","ending_direction":"Они гасят примус и остаются самыми богатыми","hook_direction":"Останься со мной на кухне","genres":["Лоу-фай","Джаз"],"moods":["Нежность","Ирония"],"energy":"Средняя","themes":["Риск","дом"],"generator_brief":"Лоу-фай с тёплым треском примуса, контрабасом и шёпотным вокалом; припев уютный, вполголоса.","generator_story":"Пара без гроша каждый вечер отстраивает на кухне своё государство: примус, хлеб, смех над громкой жизнью за окном. Погасив примус, они остаются самыми богатыми — дом держится на этих вечерах.","primary_genre":"Лоу-фай","primary_mood":"Нежность","primary_theme":"Риск","story_shelf":"Юмор: семейные драмы","conflict_key":"нищета-против-блестящей-жизни","image_key":"примус-и-каравай-на-кухне","turn_key":"бедность-оказывается-богатством","hook_key":"останься-на-кухне","sort_order":"1204","original_key":"osip-mandelstam|my-s-toboy-na-kuhne-posidim","author_name":"Осип Мандельштам","original_title":"Мы с тобой на кухне посидим","original_language":"Russian","origin_country":"Россия","original_year":"1931","source_url":"https://slova.org.ru/mandelshtam/my-s-toboj-na-kuhne-posidim/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1938.","music_adaptations":[],"source_synopsis":"В нищей кухне двое устраивают свой вечер: примус, каравай, сладкий запах керосина. На фоне пугающей эпохи этот разговор вполголоса — их крепость; блестящей жизни с витринами и шалями они предпочитают друг друга.","main_image":"примус и каравай на тесной кухне"},{"title":"Розы в чемодане","full_story":"Пожилой герой, много лет живущий далеко от дома, открывает старый чемодан и находит засушенные розы той весны. Он держит их как единственный багаж своей страны — ни родины, ни тех людей уже нет рядом. В финале он ставит их лепестки в новый горшок: пусть мёртвое цветёт в чужом окне, пока он ищет дорогу назад.","hero_pov":"Человек, у которого осталась память вместо дома","central_conflict":"Несбывшееся возвращение против живой памяти","emotional_arc":"От плавной горечи утрат к упрямому поиску дороги домой","ending_direction":"Розы снова стоят в воде — в чужом окне","hook_direction":"Розы юности всё свежи во мне","genres":["Инди-поп","Баллада"],"moods":["Ностальгия","Тоска"],"energy":"Низкая","themes":["прошлое","дом"],"generator_brief":"Медленный инди-поп с ретро-струнными и лёгким хрустом винила; припев размашистый, тоскующий.","generator_story":"Пожилой эмигрант находит в чемодане засушенные розы той весны — весь багаж оставленной страны. Он ставит их в воду в чужом окне: пусть мёртвое цветёт, пока он ищет дорогу назад.","primary_genre":"Инди-поп","primary_mood":"Ностальгия","primary_theme":"прошлое","story_shelf":"Любовные сцены","conflict_key":"память-эмигранта-против-несбывшегося-возвращения","image_key":"розы-воспоминаний-о-минувшем","turn_key":"розы-раскрываются-в-памяти","hook_key":"розы-юности-всё-свежи","sort_order":"1205","original_key":"igor-severyanin|klassicheskie-rozy","author_name":"Игорь Северянин","original_title":"Классические розы","original_language":"Russian","origin_country":"Россия","original_year":"1925","source_url":"https://ru.wikisource.org/wiki/Классические_розы_(Северянин)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1941.","music_adaptations":[],"source_synopsis":"Человек далеко от родного дома держит память о розах юности: прошло то время, когда всё было свежим и возможным. Розы воспоминаний остаются ему вместо страны, но он верит, что дорога назад ещё ищется.","main_image":"засушенные розы в старом чемодане"},{"title":"Бор пахнет моим детством","full_story":"Уставший от города отец везёт сына в лес, где сам был мальчиком, и заранее боится: вдруг место не признает его. Но бор встречает прежним жаром смолы и птичьим гулом, и отец впервые за годы слышит себя ребёнком. Он отдаёт сыну свои тропинки, как передают двор.","hero_pov":"Отец, вернувшийся в лес своего детства","central_conflict":"Городская рутина против леса, который помнит мальчиком","emotional_arc":"От неловкого вожатого к счастливому мальчику рядом с сыном","ending_direction":"Отец и сын идут одной тропинкой — теперь общей","hook_direction":"Лес помнит меня мальчонкой","genres":["Лоу-фай","Эмбиент"],"moods":["Тепло","Ностальгия"],"energy":"Низкая","themes":["Детство","Природа"],"generator_brief":"Прогулочный лоу-фай с лесными эмбиент-шумами и мягкой гитарой; припев ленивый, как шаг в жару.","generator_story":"Отец везёт сына в лес своего детства и боится, что место его не признает. Но бор встречает жаром смолы и птичьим гулом — и отец отдаёт сыну тропинки, как передают двор: теперь они общие.","primary_genre":"Лоу-фай","primary_mood":"Тепло","primary_theme":"Детство","story_shelf":"Юмор: семейные драмы","conflict_key":"рутина-против-леса-детства","image_key":"смолистый-жар-бора","turn_key":"лес-узнаёт-своего","hook_key":"лес-помнит-меня-мальчонкой","sort_order":"1206","original_key":"ivan-bunin|detstvo-1914","author_name":"Иван Бунин","original_title":"Детство","original_language":"Russian","origin_country":"Россия","original_year":"1914","source_url":"https://ru.wikisource.org/wiki/Детство_(Бунин)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1953.","music_adaptations":[],"source_synopsis":"Ребёнок бродит по жаркому сосновому бору: сухая смола пахнет счастьем, лес живёт своей большой жизнью вокруг маленького гостя. Это первое царство, в которое человек будет возвращаться всю жизнь.","main_image":"жаркий бор, пахнущий смолой"},{"title":"Последний гость лета","full_story":"Осенью, после громкого провала в жизни героя, в квартиру залетает замерзающий шмель — последний труженик лета. Герой греет его в ладонях и разговаривает с ним, как с равным: оба на последнем тепле. Он отпускает гостя на цветок в горшке и впервые за сезон чувствует, что сам ещё жив.","hero_pov":"Человек, спасающий последнего гостя лета","central_conflict":"Наступающая стужа против последнего живого гостя","emotional_arc":"От осенней пустоты к заботе, которая возвращает жизнь","ending_direction":"Шмель гудит на цветке — и в комнате снова лето","hook_direction":"Погуди, пока тепло","genres":["Инди-поп","Лоу-фай"],"moods":["Светлая грусть","Нежность"],"energy":"Средняя","themes":["Природа","прошлое"],"generator_brief":"Нежный инди-поп с гудящим синтезатором-шмелем и тёплой гитарой; припев на выдохе, почти шёпотом.","generator_story":"Осенью, после громкого провала, в квартиру героя залетает замерзающий шмель. Он греет гостя в ладонях — оба на последнем тепле — и, отпустив его на цветок, впервые за сезон чувствует, что сам ещё жив.","primary_genre":"Инди-поп","primary_mood":"Светлая грусть","primary_theme":"Природа","story_shelf":"Люди и животные","conflict_key":"конец-лета-против-последнего-гостя","image_key":"бархатный-шмель-на-подоконнике","turn_key":"гость-принимает-заботу","hook_key":"погуди-пока-тепло","sort_order":"1207","original_key":"ivan-bunin|posledniy-shmel","author_name":"Иван Бунин","original_title":"Последний шмель","original_language":"Russian","origin_country":"Россия","original_year":"1916","source_url":"https://ru.wikisource.org/wiki/Последний_шмель_(Бунин)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1953.","music_adaptations":[],"source_synopsis":"В последние жаркие дни озябший шмель забирается в человеческое жильё и гудит тоскливо рядом с человеком, будто тоскует вместе с ним. Человек приглашает гостя полетать и погудеть напоследок — поля опустели, и скоро ветер унесёт и его.","main_image":"бархатный шмель на подоконнике"},{"title":"Шар на вершине башни","full_story":"Команда рабочих получает заказ на башню вечности от владельца, который платит им рабством. Они строят честно — и втайне собирают внутри верхушки летучий шар. В ночь сдачи объекта вся команда поднимается в небо, и владелец остаётся с башней без людей. Так мечта становится чертежом.","hero_pov":"Мастер, ведущий команду на свободу","central_conflict":"Рабство у заказчика против тайного полёта всей команды","emotional_arc":"От каторжной покорности к ликованию взлёта","ending_direction":"Башня остаётся пустой — команда в небе","hook_direction":"Мы улетим на шаре","genres":["Эпик-рок","Рок"],"moods":["Сила","Смелость"],"energy":"Высокая","themes":["Мечта","Свобода"],"generator_brief":"Эпик-рок с грузным ритмом стройки в куплетах и парящим синтезаторным финалом; припев коллективный, как хор мастеров.","generator_story":"Команда строит башню вечности для владельца, платящего рабством. Кладя камни, они втайне собирают в верхушке летучий шар — в ночь сдачи вся команда взлетает, оставляя заказчику башню без людей.","primary_genre":"Эпик-рок","primary_mood":"Сила","primary_theme":"Мечта","story_shelf":"Трагические истории","conflict_key":"рабство-против-тайного-полёта","image_key":"шар-на-вершине-башни","turn_key":"башня-превращается-в-шар-полёта","hook_key":"мы-улетим-на-шаре","sort_order":"1208","original_key":"nikolay-zabolotskiy|stroiteli-1936","author_name":"Николай Заболоцкий","original_title":"Строители","original_language":"Russian","origin_country":"Россия","original_year":"1936","source_url":"https://wysotsky.com/0009/135.htm","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1958.","music_adaptations":[],"source_synopsis":"Пленные мастера строят хану башню-узилище и втайне превращают её вершину в летучий шар. Когда всё готово, зодчие поднимаются в небо и оставляют внизу своё рабство — башня становится крыльями.","main_image":"шар, поднимающийся с вершины башни"},{"title":"Уголок в чужом скворечнике","full_story":"Пенсионер, потерявший за год и жену, и работу, приходит в апреле к старой осине и просит скворца пустить его жить в скворечник — хотя бы углом. Птица не отвечает, но начинает петь, и старику впервые за зиму хочется жить громче. Он уносит домой птичью песню и записывает свои первые строки после долгой тишины.","hero_pov":"Старик, который просит у птицы уголок весны","central_conflict":"Молчащая старость против весеннего пения за двоих","emotional_arc":"От уединённой сухости к озорной надежде","ending_direction":"Старик снова поёт — неуклюже и во весь голос","hook_direction":"Дай мне уголок весны","genres":["Лоу-фай","Инди-поп"],"moods":["Надежда","Меланхолия"],"energy":"Средняя","themes":["Природа","прошлое"],"generator_brief":"Весёлый лоу-фай со свистом скворца в инструментале; куплет кружащий, припев с ручьевой искоркой.","generator_story":"Пенсионер, за год потерявший жену и работу, в апреле просит скворца пустить его в скворечник хотя бы углом. Птица молчит, но поёт — старик уносит песню домой и впервые за зиму записывает свои строки.","primary_genre":"Лоу-фай","primary_mood":"Надежда","primary_theme":"Природа","story_shelf":"Люди и животные","conflict_key":"старость-против-весеннего-пения","image_key":"скворец-в-старом-скворечнике","turn_key":"скворец-делится-уголком","hook_key":"дай-мне-уголок-весны","sort_order":"1209","original_key":"nikolay-zabolotskiy|ustupi-mne-skvorets-ugolok","author_name":"Николай Заболоцкий","original_title":"Уступи мне, скворец, уголок","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/zabolotskiy/ustupi_mne_skvorec/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1958.","music_adaptations":[],"source_synopsis":"Весной старик обращается к скворцу с необычной просьбой: пустить его в старый скворечник, отдать душу в залог за подснежники. Он бы и сам рад петь, да голос уже не тот — и он просит птицу начать серенаду за двоих.","main_image":"старый скворечник и скворец на осине"},{"title":"Клён не спорит с грозой","full_story":"Герой после удара судьбы перестаёт выходить из дома. Однажды в пустом осеннем дворе он смотрит на старый клён, согнутый ночной грозой: дерево не ропщет, дожидается росы и снова встаёт. Он приносит во двор табурет, кормит с руки воробьёв и понемногу выпрямляется вместе с клёном.","hero_pov":"Человек, выправляющийся вместе с клёном","central_conflict":"Гроза, пригибающая к земле, против упрямого выпрямления","emotional_arc":"От обиды на судьбу к спокойной мудрости дерева","ending_direction":"Клён стоит прямо — и герой тоже","hook_direction":"Выпрямлюсь, как этот клён","genres":["Эмбиент","Баллада"],"moods":["Спокойствие","Сила"],"energy":"Низкая","themes":["Природа","Сила"],"generator_brief":"Просторный эмбиент с осенними шумами и одинокой виолончелью; голос почти не двигается — как дерево.","generator_story":"После удара судьбы герой заперся дома, пока гроза не согнула старый клён. Тот не ропщет — ждёт росы и встаёт. Герой кормит во дворе воробьёв и понемногу выпрямляется вместе с клёном.","primary_genre":"Эмбиент","primary_mood":"Спокойствие","primary_theme":"Природа","story_shelf":"Люди и животные","conflict_key":"гроза-против-упрямого-древа","image_key":"клён-в-осеннем-дворе","turn_key":"изгиб-сменяется-выпрямлением","hook_key":"выпрямлюсь-как-клён","sort_order":"1210","original_key":"nikolay-zabolotskiy|osenniy-klen","author_name":"Николай Заболоцкий","original_title":"Осенний клён","original_language":"Russian","origin_country":"Россия","original_year":"1955","source_url":"https://slova.org.ru/zabolotskiy/osenniy_klen/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1958.","music_adaptations":[],"source_synopsis":"Осенний мир устроен разумно и населён — каждому своё место и свой срок. Клён показывает человеку, как держаться: пусть гроза склонит его до земли, он выпрямится снова, умудрённый земным разумом.","main_image":"осенний клён во дворе после грозы"},{"title":"Селёдка подаёт сигналы","full_story":"Мальчишка с золотыми руками решает, что все вещи вокруг живут своей тайной жизнью: пуговицы ползут, приборы намекают, ужин на тарелке моргает сигналами. Родители списывают всё на фантазию, пока он не переводит семье разговор селёдки — и за столом впервые не ругаются. Так умение слушать вещи чинит семью.","hero_pov":"Ребёнок, который слышит вещи","central_conflict":"Взрослый скепсис против говорящего мира вещей","emotional_arc":"От насмешек семьи к всеобщему озарению за столом","ending_direction":"За столом все прислушиваются к ужину — и смеются","hook_direction":"Вещи говорят со мной","genres":["Альтернативный рок","Лоу-фай"],"moods":["Радость","Ирония"],"energy":"Средняя","themes":["Детство","семья"],"generator_brief":"Абсурдистский альт-рок с лупами кухонных звуков и деревянной перкуссией; припев глуповатый и заразительный.","generator_story":"Мальчишка с золотыми руками уверен: вещи живут тайной жизнью, и ужин на тарелке моргает сигналами. Родители смеются, пока он не переводит семье разговор селёдки — и за столом впервые не ругаются.","primary_genre":"Альтернативный рок","primary_mood":"Радость","primary_theme":"Детство","story_shelf":"Юмор: семейные драмы","conflict_key":"обычный-мир-против-говорящих-вещей","image_key":"селёдка-подаёт-сигналы","turn_key":"герой-слышит-речь-вещей","hook_key":"вещи-говорят-со-мной","sort_order":"1211","original_key":"nikolay-oleynikov|ozarenie-1932","author_name":"Николай Олейников","original_title":"Озарение","original_language":"Russian","origin_country":"Россия","original_year":"1932","source_url":"https://ru-lyrics.livejournal.com/415569.html","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1937.","music_adaptations":[],"source_synopsis":"Герой открывает: все предметы что-то значат и подают знаки — хвост сообщает, прибор намекает, селёдка на тарелке сигналит тому, кто умеет смотреть. Обыденный мир оказывается разговорным.","main_image":"селёдка, подающая сигналы с тарелки"},{"title":"Пока ты ждёшь — я живой","full_story":"Разлука длится дольше всех прогнозов: друзья советуют ей жить дальше, письма редеют. Она держит правило — каждый вечер светить в окно и не верить плохим словам. Он проходит через то, чего не выжил никто из его отделения, и возвращается потому, что где-то горел свет.","hero_pov":"Солдат, который держится её ожидания","central_conflict":"Все смерти и чужие советы против одного ожидания","emotional_arc":"От отчаянного «жди» к неистребимой вере двоих","ending_direction":"Он возвращается — свет ещё горит","hook_direction":"Пока ты ждёшь — я живой","genres":["Поп","Баллада"],"moods":["Надежда","Любовь"],"energy":"Средняя","themes":["письмо","ожидание"],"generator_brief":"Большая поп-баллада с нарастающими струнными; куплеты сдержанные, припев широкий и поющий.","generator_story":"Разлука длится дольше прогнозов: письма редеют, друзья советуют ей жить дальше. Но она каждый вечер светит в окно — и он, пройдя то, чего не выжил никто из его отделения, возвращается на этот свет.","primary_genre":"Поп","primary_mood":"Надежда","primary_theme":"письмо","story_shelf":"Любовные сцены","conflict_key":"все-смерти-против-одного-ожидания","image_key":"окно-которое-ждёт","turn_key":"ожидание-работает-как-оберег","hook_key":"пока-ты-ждёшь-я-живой","sort_order":"1212","original_key":"konstantin-simonov|zhdi-menya-i-ya-vernus","author_name":"Константин Симонов","original_title":"Жди меня, и я вернусь","original_language":"Russian","origin_country":"Россия","original_year":"1941","source_url":"https://slova.org.ru/simonov/zhdi-menya-i-ya-vernus/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1979.","music_adaptations":[],"source_synopsis":"Солдат просит женщину ждать его — при любой вести, среди всех сомнений и чужих напоминаний, что пора забыть. Само её ожидание становится защитой: пока она ждёт, он невредим.","main_image":"женщина у окна, которая всегда оставляет свет"},{"title":"Дорога, что прощала нас","full_story":"Ветреный маршрут героя — столицы, вокзалы, командировки — вдруг стопорится на трассе под ливнем, где его подбирает дальнобойщик Алёша. Ночь напролёт они говорят не о неудачах, а о людях, которые их по-доброму пропускали: кассирша, грузчик, попутчица. К утру герой решает не сдаваться: с такой землёй проигрывать стыдно.","hero_pov":"Солдат, который учится любить землю на отступлении","central_conflict":"Тяжёлое отступление против растущей любви к земле","emotional_arc":"От стыда и грязи к тихому братству и силе","ending_direction":"Дорога разворачивается — они идут дальше вместе","hook_direction":"Спасибо тебе, дорога","genres":["Рок","Эпик-рок"],"moods":["Тепло","Смелость"],"energy":"Высокая","themes":["дорога","Дружба"],"generator_brief":"Дорожный рок с мокрым гитарным тремоло и стуком колёс в ритме; припев широкий, с мужским хором.","generator_story":"Под ливнем на трассе героя подбирает дальнобойщик Алёша — всю ночь они говорят не о неудачах, а о людях, пропускавших их по-доброму. К утру он решает не сдаваться: с такой землёй проигрывать стыдно.","primary_genre":"Рок","primary_mood":"Тепло","primary_theme":"дорога","story_shelf":"Трагические истории","conflict_key":"отступление-против-любви-к-земле","image_key":"женщины-с-крынками-на-обочине","turn_key":"отступление-открывает-любовь","hook_key":"спасибо-тебе-дорога","sort_order":"1213","original_key":"konstantin-simonov|ty-pomnish-alesha-dorogi-smolenschiny","author_name":"Константин Симонов","original_title":"Ты помнишь, Алёша, дороги Смоленщины","original_language":"Russian","origin_country":"Россия","original_year":"1941","source_url":"https://slova.org.ru/simonov/ty-pomnish-alesha-dorogi-smolenwiny/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1979.","music_adaptations":[],"source_synopsis":"Два солдата отступают по бесконечным мокрым дорогам и вспоминают не бои, а людей: усталых женщин с крынками, шепчущих «Господь вас спаси», деревни за деревнями. Отступление учит их любить землю сильнее страха.","main_image":"женщины с крынками на обочине дождливой дороги"},{"title":"Один раз наяву","full_story":"Ветеранка годами просыпается от одного и того же сна и молчит об этом. В новом коллективе ей досадно от красивых слов о войне — и однажды она срывается: рассказывает, как страшно один раз было наяву. Тишина после её слов честнее любых речей, и впервые её не трясёт.","hero_pov":"Женщина-солдат, знающая цену словам","central_conflict":"Правда о страхе против громкой лжи о войне","emotional_arc":"От ночных кошмаров к честному злому слову","ending_direction":"Она говорит правду вслух — и ночь впервые тихая","hook_direction":"Не страшно — значит не знаешь","genres":["Рок","Альтернативный рок"],"moods":["Злость","Уязвимость"],"energy":"Высокая","themes":["Риск","память"],"generator_brief":"Злой рок с сухими барабанами и рваной гитарой; куплет на грани срыва, припев — стиснутый крик.","generator_story":"Ветеранка годами молчит о ночном кошмаре. От красивых слов о войне она срывается и говорит, как страшно было один раз наяву, — и честная тишина после этого впервые оставляет её спокойной.","primary_genre":"Рок","primary_mood":"Злость","primary_theme":"Риск","story_shelf":"Трагические истории","conflict_key":"правда-войны-против-громких-речей","image_key":"тишина-после-рукопашной","turn_key":"страх-признаётся-вслух","hook_key":"не-страшно-говоришь-значит-не-знаешь","sort_order":"1214","original_key":"yuliya-drunina|ya-stolko-raz-vidala-rukopashnyy","author_name":"Юлия Друнина","original_title":"Я столько раз видала рукопашный...","original_language":"Russian","origin_country":"Россия","original_year":"1943","source_url":"https://slova.org.ru/drunina/ya-stol-ko-raz-vidala-rukopashnyj/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1998.","music_adaptations":[],"source_synopsis":"Военная медсестра признаётся: рукопашный бой она видела тысячу раз во сне и один раз наяву. Тому, кто говорит, что на войне не страшно, вовсе нечего сказать о войне.","main_image":"тишина после рукопашной в мокром поле"},{"title":"Ром, который молчит","full_story":"Молодые фронтовики собираются на кухне: разливают трофейный ром, и один молчит уже четвёртый час. Друзья не дожимают его — понимают, что он не историй ищет, а сверяет свою «там»шнюю жизнь с мирной. К ночи он наконец спрашивает: а что тут было без нас? — и начинается настоящий разговор.","hero_pov":"Фронтовик, который не может начать говорить","central_conflict":"Молчание о том, что было там, против вопросов тех, кто был здесь","emotional_arc":"От мёртвого застолья к живому разговору-признанию","ending_direction":"Он начинает рассказывать — и комната оживает","hook_direction":"Расскажи, что было там","genres":["Рок","Баллада"],"moods":["Одиночество","Грусть"],"energy":"Средняя","themes":["прошлое","Дружба"],"generator_brief":"Кабацкий рок-вальс с глухим контрабасом; припев на пределе тихого крика, куплеты — усталый монолог.","generator_story":"Молодые фронтовики пьют на кухне трофейный ром, и один молчит уже четвёртый час. Друзья не дожимают, и к ночи он сам спрашивает, что тут было без них, — с этого вопроса комната оживает.","primary_genre":"Рок","primary_mood":"Одиночество","primary_theme":"прошлое","story_shelf":"Трагические истории","conflict_key":"молчание-фронтовика-против-домашних-вопросов","image_key":"трофейный-ром-на-столе","turn_key":"вопрос-разбивает-молчание","hook_key":"расскажи-что-было-там","sort_order":"1215","original_key":"semyon-gudzenko|my-ne-ot-starosti-umrem","author_name":"Семён Гудзенко","original_title":"Мы не от старости умрём","original_language":"Russian","origin_country":"Россия","original_year":"1946","source_url":"https://slova.org.ru/gudzenko/my-ne-ot-starosti-umrem/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1991.","music_adaptations":[],"source_synopsis":"Вернувшиеся с войны пьют трофейный ром и молчат. Солдат, видевший столько городов, не рассказывает о них — он хочет знать, что было здесь, дома, пока они были там.","main_image":"трофейный ром на столе среди молчания"},{"title":"Весь мир — его дом","full_story":"Танкист возвращается к месту, где погиб его друг, и хочет найти хоть знак могилы. Ему объясняют: товарища положили прямо в землю, без погона и списка — в шар земной. Он стоит между скорбью и гордостью: друг теперь в каждом облаке и грозе. На выходе он насыпает горсть земли в коробку из-под гильз.","hero_pov":"Танкист, который ищет могилу друга","central_conflict":"Безвестная смерть против вечной земли-дома","emotional_arc":"От потерянного поиска к горькому величию простого солдата","ending_direction":"Он уносит горсть земли — друга с собой","hook_direction":"Земля теперь его дом","genres":["Эпик-рок","Баллада"],"moods":["Грусть","Сила"],"energy":"Высокая","themes":["память","дом"],"generator_brief":"Тяжёлый эпик-рок с медными и погружным басом; куплеты как шаги по земле, припев — космический разлёт.","generator_story":"Танкист ищет у места гибели друга хоть знак могилы, но товарища положили прямо в землю, без списка. Он насыпает на выходе горсть земли в коробку из-под гильз — друг теперь в каждом облаке и грозе.","primary_genre":"Эпик-рок","primary_mood":"Грусть","primary_theme":"память","story_shelf":"Трагические истории","conflict_key":"простой-солдат-против-забвения","image_key":"шар-земной-как-мавзолей","turn_key":"беззвание-становится-вечностью","hook_key":"земля-стала-ему-домом","sort_order":"1216","original_key":"sergey-orlov|ego-zaryli-v-shar-zemnoy","author_name":"Сергей Орлов","original_title":"Его зарыли в шар земной","original_language":"Russian","origin_country":"Россия","original_year":"1944","source_url":"https://slova.org.ru/orlov/ego-zaryli-v-shar-zemnoj/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1977.","music_adaptations":[],"source_synopsis":"Друзья хоронят простого солдата без званий и наград — в шар земной, как в мавзолей на миллион веков. Земля становится его домом: грозы и звёзды теперь рядом с ним.","main_image":"земля как мавзолей на миллион веков"},{"title":"Одна на всех","full_story":"Команда, собранная из тех, кто никогда не был победителем, идёт через весь путь: проигрыши, перелёты, чужие города. Каждый носит своё «не постоим» — и к финальной битве они впервые звучат в унисон: нужна одна победа, одна на всех. Победа достаётся не лучшему — тем, кто остался вместе.","hero_pov":"Капитан команды, идущей к финалу","central_conflict":"Цена пути против одной цели на всех","emotional_arc":"От разбросанных потерь к единому кулаку команды","ending_direction":"Ракета взлетает — они стоят вместе","hook_direction":"Одна победа на всех","genres":["Рок","Эпик-рок"],"moods":["Решимость","Драйв"],"energy":"Взрывная","themes":["дорога","команда"],"generator_brief":"Стадионный рок с марш-битом и хором-криком; припев сходит на один общий выдох «одна на всех».","generator_story":"Команда вечных проигравших идёт через поражения и чужие города, неся своё «не постоим». К финальной битве голоса впервые звучат в унисон — ракета взлетает: победа досталась тем, кто остался вместе.","primary_genre":"Рок","primary_mood":"Решимость","primary_theme":"дорога","story_shelf":"Трагические истории","conflict_key":"долгая-война-против-одной-цели","image_key":"путь-прошедших-городов","turn_key":"все-города-сходятся-в-цели","hook_key":"одна-на-всех-за-ценой","sort_order":"1217","original_key":"sergey-orlov|nam-nuzhna-odna-pobeda","author_name":"Сергей Орлов","original_title":"Нам нужна одна победа","original_language":"Russian","origin_country":"Россия","original_year":"1971","source_url":"https://ru.wikipedia.org/wiki/Нам_нужна_одна_победа","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1977.","music_adaptations":[],"source_synopsis":"Солдаты, которых война довела по городам и весям до финала, признаются: им нужна одна победа — одна на всех. Ракеты и пулемёты не пугают тех, кто за ценой не постоит.","main_image":"одна ракета над всей дорогой войны"},{"title":"Каждый вёз своё","full_story":"Трамвай осаждённого города становится живым вагоном-семьёй: санитарка делится сладким с мальчиком, старушка везёт подарок внуку, рабочий дремлет после смены. На маленькой остановке все молча берут свои свёртки и расходятся в сторону большой цели. Кондуктор объявляет не улицы, а дела: завод, госпиталь, застава.","hero_pov":"Кондуктор трамвая, который вёз всех","central_conflict":"Осаждённый город против упрямого будничного движения","emotional_arc":"От гнетущего холода к тихому братству вагона","ending_direction":"Вагон приходит к заставе — все выходят в сторону цели","hook_direction":"Каждый вёз своё дело","genres":["Эпик-рок","Рок"],"moods":["Сила","Надежда"],"energy":"Высокая","themes":["дорога","город"],"generator_brief":"Эпик-рок со стуком трамвайных колёс в ритм-секции; куплеты как остановки, припев — разгон города.","generator_story":"По осаждённому городу идёт трамвай-семья: санитарка делится сладким с мальчиком, старушка везёт подарок внуку. Кондуктор объявляет не улицы, а дела — завод, госпиталь, застава, — и все выходят к цели.","primary_genre":"Эпик-рок","primary_mood":"Сила","primary_theme":"дорога","story_shelf":"Трагические истории","conflict_key":"осаждённый-город-против-будничного-движения","image_key":"трамвай-с-фанерой-вместо-стёкол","turn_key":"будни-несут-город-в-бой","hook_key":"каждый-везёт-своё-дело","sort_order":"1218","original_key":"vera-inber|tramvay-idet-na-front","author_name":"Вера Инбер","original_title":"Трамвай идёт на фронт","original_language":"Russian","origin_country":"Россия","original_year":"1941","source_url":"https://slova.org.ru/inber/tramvaj-idet-na-front/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1972.","music_adaptations":[],"source_synopsis":"В осаждённом городе трамвай с фанерой вместо стёкол идёт к заставе: в него вливаются граждане — рабочий на оружейный завод, старушка с папиросами внуку-танкисту, санитарки, партизан с трофейным шлемом. Каждый везёт своё малое дело к большому.","main_image":"трамвай с фанерой вместо стёкол"},{"title":"Под чужим именем — до конца","full_story":"Современная девушка уезжает на опасное задание и представляется другим именем, чтобы в случае провала её семья осталась чиста. Письма домой подписаны этим именем, и мать годами отвечает незнакомке, догадываясь о правде. В финале мать впервые пишет: я всё знаю — приходи под своим именем.","hero_pov":"Девушка, которая ушла под чужим именем","central_conflict":"Защита родных через отказ от своего имени","emotional_arc":"От волевого молчания к тёплому громкому возврату","ending_direction":"Мать пишет, что знает всё, — и ждёт её под своим именем","hook_direction":"Под чужим именем — до конца","genres":["Баллада","Эпик-рок"],"moods":["Смелость","Грусть"],"energy":"Высокая","themes":["Риск","семья"],"generator_brief":"Баллада с военным барабанным проигрышем и чистым женским вокалом; припев — тихий героизм без пафоса.","generator_story":"Девушка уходит на опасное задание под вымышленным именем, чтобы при провале семья осталась чиста. Мать годами отвечает «незнакомке», а потом впервые пишет: я всё знаю — приходи под своим именем.","primary_genre":"Баллада","primary_mood":"Смелость","primary_theme":"Риск","story_shelf":"Трагические истории","conflict_key":"чужое-имя-против-страха","image_key":"двойное-имя-в-письме","turn_key":"правда-под-чужим-именем","hook_key":"под-чужим-именем-до-конца","sort_order":"1219","original_key":"margarita-aliger|zoya-poema","author_name":"Маргарита Алигер","original_title":"Зоя","original_language":"Russian","origin_country":"Россия","original_year":"1942","source_url":"https://pamyat1945.ucoz.ru/publ/margarita_aliger_poehma_zoja/1-1-0-16","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1992.","music_adaptations":[],"source_synopsis":"Обычная московская школьница добровольно уходит в отряд и называет себя чужим именем. Дом ждёт её под настоящим именем, а вести приходят под другим — защита близких стоит ей всего.","main_image":"двойное имя в последнем письме"},{"title":"Письма без обратного адреса","full_story":"Отец продолжает писать сыну сообщения на его старый номер и ходить по местам их общих маршрутов. Однажды на вокзале он помогает чужому парню найти дорогу — и узнаёт в нём манеру сына пожимать плечами. К концу он понимает: сын вернулся в мир через всех молодых, и писать можно уже не в никуда.","hero_pov":"Отец, который пишет сыну в никуда","central_conflict":"Пустота потери против голоса сына в живых","emotional_arc":"От слепого письма в пустоту к находке сына в других","ending_direction":"Он отдаёт чужому парню куртку сына — и впервые улыбается","hook_direction":"Пишу тебе как раньше","genres":["Баллада","Эмбиент"],"moods":["Боль","Надежда"],"energy":"Низкая","themes":["письмо","память"],"generator_brief":"Тихая баллада с эмбиент-шумами вокзала; куплеты как письмо вслух, припев — почти молитва.","generator_story":"Отец пишет сыну на старый номер и однажды на вокзале узнаёт в чужом парне его манеру пожимать плечами. Он отдаёт парню куртку сына — и впервые улыбается: сын вернулся в мир через всех молодых.","primary_genre":"Баллада","primary_mood":"Боль","primary_theme":"письмо","story_shelf":"Трагические истории","conflict_key":"пустая-комната-против-голоса-в-живых","image_key":"письма-без-обратного-адреса","turn_key":"голос-живёт-в-следующих","hook_key":"пишу-тебе-как-раньше","sort_order":"1220","original_key":"pavel-antokolskiy|syn-poema","author_name":"Павел Антокольский","original_title":"Сын","original_language":"Russian","origin_country":"Россия","original_year":"1943","source_url":"https://pub.wikireading.ru/76298","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1978.","music_adaptations":[],"source_synopsis":"Отец теряет сына на войне и не может разделить горе на части: дом пуст, вещи всё на местах. Но голос сына он начинает слышать в живых — в каждом молодом, кто идёт следом.","main_image":"письма без обратного адреса на столе"},{"title":"За тех, кто не как все","full_story":"Компания тридцатилетних собирается на прощальный ужин перед разъездами: один едет работать на север, другой уходит из отношений, третий перестаёт писать музыку. Они поднимают бокалы за непохожих — и внезапно чувствуют себя флибустьерами, которым всё ещё надоело устраиваться. Утром бригантина их мечты снова поднимает паруса.","hero_pov":"Друг, который поднимает тост за компанию","central_conflict":"Усталость от нормальной жизни против несбыточного моря","emotional_arc":"От прощального похмелья к эйфории несдавшихся","ending_direction":"Бокалы подняты — паруса их мечты снова в небе","hook_direction":"Пьём за непохожих","genres":["Рок","Инди-поп"],"moods":["Эйфория","Романтика"],"energy":"Высокая","themes":["Мечта","Дружба"],"generator_brief":"Морской рок-вальс с широкой гитарой и чеканкой бокалов в перкуссии; припев — тост, который поют все.","generator_story":"Три друга за прощальным ужином: один едет на север, другой уходит из отношений, третий бросил музыку. Тост за непохожих возвращает им дух флибустьеров — и бригантина их мечты снова поднимает паруса.","primary_genre":"Рок","primary_mood":"Эйфория","primary_theme":"Мечта","story_shelf":"Любовные сцены","conflict_key":"усталость-против-несбыточного-моря","image_key":"тост-за-непохожих","turn_key":"мечта-поднимает-бокал","hook_key":"за-тех-кто-не-как-все","sort_order":"1221","original_key":"pavel-kogan|brigantina","author_name":"Павел Коган","original_title":"Бригантина","original_language":"Russian","origin_country":"Россия","original_year":"1937","source_url":"https://slova.org.ru/kogan/brigantina/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1942.","music_adaptations":[],"source_synopsis":"Уставшие спорить и любить друзья поднимают бокалы за непохожих — и в флибустьерском дальнем море бригантина поднимает паруса. Это прощание с серебристой мечтой, которое звучит как встреча с ней.","main_image":"тост за непохожих под поднятыми парусами"},{"title":"Ни бури, ни ясного неба","full_story":"Команду и проект разорвал обвал рынка за одну ночь: инвесторы исчезли, сотрудники разбегаются, кто-то уже сдал ключи. Он остаётся без зонта — вычтен, невостребован — и идёт пешком через дождливый город, напевая себе под нос. Утром, оглянувшись на мокрый путь, он понимает: и крах, и обещанное «потом блеснёт» — одно и то же небо, просто идти надо своим шагом.","hero_pov":"основатель, который остался без зонта","central_conflict":"панический бег окружающих против медленного шага в дождь","emotional_arc":"от разбитости и хулы к ровному шагу и оглядке на штиль","ending_direction":"он оглядывается на пройденный дождь — ни бури, ни неба","hook_direction":"иду медленнее дождя","genres":["Техно","Эмбиент"],"moods":["Спокойствие","Уверенность"],"energy":"Средняя","themes":["примирение","Время"],"generator_brief":"Стадийное минималь-техно: ровный пульс как шаг под дождём, шум ливня в перкуссии, полушёпотная читка, в финале свет проступает без мажора.","generator_story":"За ночь обвал рынка развалил его проект: инвесторы исчезли, сотрудники разбегаются. Без зонта он идёт пешком сквозь дождь и понимает: крах и «потом блеснёт» — одно небо, лишь бы идти своим шагом.","primary_genre":"Техно","primary_mood":"Спокойствие","primary_theme":"примирение","story_shelf":"Трагические истории","conflict_key":"панический-бег-против-медленного-шага","image_key":"ливень-без-зонта","turn_key":"оглядка-на-дождливый-путь","hook_key":"иду-медленнее-дождя","sort_order":"1222","original_key":"su-shi|ding-feng-bo","author_name":"Су Ши","original_title":"定风波 (Не слушай дождя в лесу)","original_language":"Chinese","origin_country":"Китай","original_year":"1082","source_url":"https://en.wikipedia.org/wiki/Su_Shi","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1101.","music_adaptations":[],"source_synopsis":"Поэта в ссылке настигает в горах ливень: у спутников есть дождевики, они бегут и прячутся, у него ничего нет. Он идёт шагом и поёт; к концу пути оглядывается — и видит, что нет ни бури, ни ясного неба.","main_image":"ливень на горной тропе, человек идёт шагом, когда все бегут"},{"title":"Разговор во сне","full_story":"Десять лет вдовец не говорит о жене вслух: работа, сын, привычные обеды. В ночь на годовщину ему снится их квартира — она у маленького окна расчёсывает волосы, и он наконец начинает говорить, всё сразу, за один сон. Он просыпается до последнего слова, и до утра держит за подушкой телефон, в котором так и не решился удалить её голосовые.","hero_pov":"вдовец, который не договорил при жизни","central_conflict":"десять лет немоты против разговора, случившегося только во сне","emotional_arc":"от отточенного молчания к вине и несказанным словам","ending_direction":"утро забирает голос сна — голосовые остаются за подушкой","hook_direction":"скажи ей во сне","genres":["Электропоп","R&B"],"moods":["Вина","Нежность"],"energy":"Низкая","themes":["Расставание","Память"],"generator_brief":"Ночной электропоп-ноктюрн: приглушённый бас, один прозрачный синтетический колокольчик, вокал почти без дыхания, в бридже — звук расчёски.","generator_story":"Десять лет вдовец не говорит о жене вслух — пока во сне она не появляется у окна, и он не выговаривает всё сразу. Просыпается до последнего слова и до утра держит за подушкой телефон с её голосовыми.","primary_genre":"Электропоп","primary_mood":"Вина","primary_theme":"Расставание","story_shelf":"Трагические истории","conflict_key":"десять-лет-немоты-против-разговора-во-сне","image_key":"малое-окно-и-гребёнка","turn_key":"утро-забирает-голос","hook_key":"скажи-ей-во-сне","sort_order":"1223","original_key":"su-shi|jiangchengzi-meng","author_name":"Су Ши","original_title":"江城子·乙卯正月二十日夜记梦 (Запись сна в ночь на двадцатое)","original_language":"Chinese","origin_country":"Китай","original_year":"1075","source_url":"https://en.wikipedia.org/wiki/Su_Shi","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1101.","music_adaptations":[],"source_synopsis":"Десять лет после смерти жены: и живой, и умерший разлучены, слов не подобрать. Во сне он возвращается домой и видит её у маленького окна, расчёсывающей волосы; они смотрят друг на друга без слов — только слёзы.","main_image":"жена расчёсывает волосы у маленького окна во сне"},{"title":"Гусь на снегу","full_story":"Два брата-фрилансера через семь лет снова ночуют в том же придорожном мотеле, где когда-то писали на стене свои планы. Ремонт съел надписи, хозяин умер, новый администратор не знает их истории. Они не грустят вслух: в переписке брат шлёт фото следов птицы на свежем снегу с одной строкой — каждый след был наш, а полёт тоже.","hero_pov":"старший из двух братьев в дороге","central_conflict":"перекрашенные стены против общей ночи, которая всё ещё на двоих","emotional_arc":"от неловкой ностальгии к спокойному принятию следов","ending_direction":"фото следов на снегу: каждый след был наш, а полёт тоже","hook_direction":"каждый след — и полёт","genres":["Хип-хоп","Джаз"],"moods":["Меланхолия","Тепло"],"energy":"Средняя","themes":["Дружба","прошлое"],"generator_brief":"Тёплый джазовый хип-хоп: пыльная пианиная петля, снежный шорох в сэмплах, два голоса-брата читают почти в разговоре, припев как выдох в мороз.","generator_story":"Два брата через семь лет снова ночуют в мотеле, где писали на стене планы: ремонт съел надписи, хозяин умер. Они не грустят вслух — брат шлёт фото гусиных следов на снегу: и следы наши, и полёт.","primary_genre":"Хип-хоп","primary_mood":"Меланхолия","primary_theme":"Дружба","story_shelf":"Люди и животные","conflict_key":"перекрашенные-стены-против-общей-ночи","image_key":"следы-гуся-на-снегу","turn_key":"старик-уснул-навсегда","hook_key":"каждый-след-и-полёт","sort_order":"1224","original_key":"su-shi|mianchi-huaijiu","author_name":"Су Ши","original_title":"和子由渑池怀旧 (О Мяньчи — брату Цзыю)","original_language":"Chinese","origin_country":"Китай","original_year":"1061","source_url":"https://en.wikipedia.org/wiki/Su_Shi","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1101.","music_adaptations":[],"source_synopsis":"Братья снова ночуют в том же постоялом дворе на станции Мяньчи: старик, что их принимал, умер, стены перекрашены, их старые надписи стёрты. Жизнь — как дикий гусь, что ступил на снег: оставил след и улетел, а след — не счастье и не беда, просто след.","main_image":"следы дикого гуся на снегу"},{"title":"Феникс со шпильки","full_story":"Их развели в девятнадцать, потому что мать сказала: она мешает экзаменам. Через десять лет они сталкиваются в общем дворе, где когда-то жили: она молча ставит перед ним кофе, он молчит и уходит. Ночью он выкладывает песню о том дне — не называя имён, — а утром в комментариях появляется её ответ той же строфой, без имени.","hero_pov":"мужчина, которого развели силой чужого слова","central_conflict":"воля матери против стены шэньгюардского двора, где всё началось","emotional_arc":"от покорного молчания к публичной песне и её ответу","ending_direction":"её ответ той же строфой — имена так и не названы","hook_direction":"почему мы расстались молча","genres":["Трэп","Драм-н-бейс"],"moods":["Злость","Грусть"],"energy":"Взрывная","themes":["ссора","Расставание"],"generator_brief":"Тёмный мелодичный трэп: подрагивающие 808, смех матери сэмплом на подаче, шёпотная злость в куплетах, дроп — разбитая чашка.","generator_story":"В девятнадцать их развела его мать: она мешала экзаменам. Через десять лет они встречаются во дворе, ночью он выкладывает песню о том дне без имён — а утром в комментариях её ответ той же строфой.","primary_genre":"Трэп","primary_mood":"Злость","primary_theme":"ссора","story_shelf":"Трагические истории","conflict_key":"воля-матери-против-стены-шэньгюардского-двора","image_key":"надпись-на-старой-стене","turn_key":"её-ответ-на-мою-песню","hook_key":"почему-мы-расстались-молча","sort_order":"1225","original_key":"lu-you|chai-tou-feng","author_name":"Лу Ю","original_title":"钗头凤 (Феникс со шпильки)","original_language":"Chinese","origin_country":"Китай","original_year":"1155","source_url":"https://en.wikipedia.org/wiki/Lu_You","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1210.","music_adaptations":[],"source_synopsis":"Мать заставила поэта развестись с любимой женой. Годы спустя они случайно встречаются в саде Шэнь; она молча подаёт вино, он не может сказать ни слова и пишет на стене садовой стены своё стихотворение о печали. Она отвечает тем же размером — и оба сходят с ума от горя.","main_image":"надпись на старой стене сада, где их развели"},{"title":"Скажите на могиле","full_story":"Отец — старый слесарь, всю жизнь восстанавливавший семейную мастерскую, отнятую долгами, — просит сыновей об одном: когда мастерская снова заработает, придите к могиле и скажите. Годы спустя они расплачиваются с последним долгом, возвращают дом и идут всем составом к могиле — старший включёт у ворот их старый станок по видео. Номера никто не бросил: обет держат живым.","hero_pov":"сын, которому отец завещал вернуться с новостью","central_conflict":"смерть против дела, которое обещали завершить","emotional_arc":"от горя у постели к выдержанному семейному обету","ending_direction":"у могилы включают видео работающего станка — доклад принят","hook_direction":"доложите отцу в срок","genres":["EDM","Поп"],"moods":["Решимость","Надежда"],"energy":"Высокая","themes":["Возвращение","Семья"],"generator_brief":"Стадионный EDM с военным барабаном: вокал как клятва, нарастающий подъём к дропу «мы вернулись», в финале — детский голос произносит семейное слово.","generator_story":"Отец-слесарь, у которого долги отняли мастерскую, завещал: когда дом снова заработает — придите на могилу и скажите. Годы спустя сыновья возвращают её и докладывают по видео работающего станка.","primary_genre":"EDM","primary_mood":"Решимость","primary_theme":"Возвращение","story_shelf":"Трагические истории","conflict_key":"смерть-против-несовершённого-дела","image_key":"семейный-обет-у-могилы","turn_key":"сыновья-приходят-с-новостью","hook_key":"доложите-отцу-в-срок","sort_order":"1226","original_key":"lu-you|shi-er","author_name":"Лу Ю","original_title":"示儿 (Завещание сыновьям)","original_language":"Chinese","origin_country":"Китай","original_year":"1210","source_url":"https://en.wikipedia.org/wiki/Lu_You","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1210.","music_adaptations":[],"source_synopsis":"Умирая, поэт говорит сыновьям: я знал, что смерть опустошает всё, — но горюю, что не увижу, как страна объединится. Когда армия вернёт север, не забудьте на домашнем жертвенном обряде сказать об этом вашему отцу.","main_image":"семья у могилы с новостью, которую обещали донести"},{"title":"Мост из сорок","full_story":"У них свой ритм: она — лётчица на длинных рейсах, он — смотритель маяка, и вместо съёмной квартиры вместе они выбрали одну встречу в год, в один и тот же день, в одном и том же порту. Друзья уговаривают «наконец жить нормально», они пробуют съехаться — и едва не теряют друг друга в быту. Они возвращаются к мосту из сорок: их любовь живёт на расстоянии года, и им больше ничего не нужно.","hero_pov":"смотритель маяка, у которого любовь раз в год","central_conflict":"ежедневная близость против годового ритма встреч","emotional_arc":"от уступки уговорам к возвращению собственного ритма","ending_direction":"мост из сорок восстановлен: раз в год — как в первый","hook_direction":"раз в год — как в первый","genres":["Хаус","Поп"],"moods":["Романтика","Надежда"],"energy":"Высокая","themes":["Любовь","Риск"],"generator_brief":"Праздничный фестиваль-хаус: взлетающие клавиши, крик чаек сэмплом, припев как вернувшийся рейс, в бридже — тиканье года.","generator_story":"Лётчица и смотритель маяка вместо квартиры выбрали одну встречу в год в одном порту. Уговоры жить нормально почти губят их в быту — и они возвращаются к годовому ритму — им больше ничего не нужно.","primary_genre":"Хаус","primary_mood":"Романтика","primary_theme":"Любовь","story_shelf":"Любовные сцены","conflict_key":"ежедневная-близость-против-годового-ритма","image_key":"мост-из-сорок","turn_key":"совместная-жизнь-чуть-не-убила-мост","hook_key":"раз-в-год-как-в-первый","sort_order":"1227","original_key":"qin-guan|que-qiao-xian","author_name":"Цинь Гуань","original_title":"鹊桥仙 (Мост из сорок)","original_language":"Chinese","origin_country":"Китай","original_year":"1097","source_url":"https://en.wikipedia.org/wiki/Qin_Guan","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1100.","music_adaptations":[],"source_synopsis":"Небесные Пастух и Ткачиха разлучены Млечным Путём и встречаются раз в году по мосту из сорок в седьмой день седьмого месяца. Поэт говорит: если любовь настоящая и долгая — стоит ли требовать быть вместе каждый день?","main_image":"мост из сорок над бесконечным разлуком"},{"title":"Река уходит от горы","full_story":"Она двадцать лет жила в городке, встроенная в его ритм, — и вдруг уезжает одним чемоданом, без ссор и объяснений. Он стоит на туманной пристани и смотрит, как река, всегда окружавшая гору, спокойно несёт свои воды прочь — не из ненависти и не из страсти. Утром он находит её сообщение: река не уходит от горы, река идёт к морю — и впервые он отпускает, глядя на воду.","hero_pov":"тот, кто остался у горы, когда река ушла","central_conflict":"река против горы — она уходит не от него, а к морю","emotional_arc":"от растерянной обиды к тихому отпусканию","ending_direction":"туман редеет: он впервые отпускает, глядя на воду","hook_direction":"для кого ты утекаешь","genres":["Электропоп","Синтвейв"],"moods":["Тоска","Мечтательность"],"energy":"Средняя","themes":["Расставание","Природа"],"generator_brief":"Туманный синтвейв-электропоп: размытые подушки синтов, звук пара и воды, вокал на дальнем плане, в финале — один чистый рассветный аккорд.","generator_story":"Она двадцать лет жила в его городке и уезжает одним чемоданом без ссор. Утром он читает её строку: река не уходит от горы — река идёт к морю, — и впервые отпускает, глядя на воду.","primary_genre":"Электропоп","primary_mood":"Тоска","primary_theme":"Расставание","story_shelf":"Любовные сцены","conflict_key":"река-против-горы-она-оставляет","image_key":"туман-съедает-паромную-пристань","turn_key":"река-нашла-море","hook_key":"для-кого-ты-утекаешь","sort_order":"1228","original_key":"qin-guan|ta-suoxing","author_name":"Цинь Гуань","original_title":"踏莎行·郴州旅舍 (В дорожной хижине в Чэньчжоу)","original_language":"Chinese","origin_country":"Китай","original_year":"1097","source_url":"https://en.wikipedia.org/wiki/Qin_Guan","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1100.","music_adaptations":[],"source_synopsis":"В изгнании: туман поглотил башни, луна потеряла брод, breakpoint смотрят повсюду — и не найти. Река, которая всегда вилась вокруг горы, течёт прочь вниз, к далёким рекам, — и поэт спрашивает: для кого она это делает?","main_image":"туман, съедающий паромную пристань, и река, уходящая от горы"},{"title":"Когда я уходил, шумели ивы","full_story":"Контрактник возвращается из дальнего рейда одним рейсом на родину: когда уезжал, за окном был апрель и шумели ивы, на обратной дороге — январь и снег. Он едет в переполненном вагоне, глядя на свои армейские кроссовки, и не звонит — хочет с порога. Никто не встречает: он проходит последние кварталы сам, и снег всё быстрее — а у подъезда, в снегу, стоит его сын, выросший на голову.","hero_pov":"возвращающийся солдат без почётного эскорта","central_conflict":"долгая дорога против порога, где ждут","emotional_arc":"от омертвевшего терпения к живому шагу последних кварталов","ending_direction":"у подъезда в снегу — сын, выросший на голову","hook_direction":"помню ивы — теперь снег","genres":["Драм-н-бейс","Рок"],"moods":["Надежда","Драйв"],"energy":"Взрывная","themes":["Возвращение","смелость"],"generator_brief":"Маршевый драм-н-бейс: брейк как шаг на десятки километров, вокал хрипло ровный, дроп в момент «порог и снег», в финале — детский голос зовёт отца.","generator_story":"Контрактник едет из рейда домой: уезжал в апрель с шумом ив, возвращается в январский снег, не звоня — хочет с порога. Никто не встречает, и у подъезда в снегу он находит сына, выросшего на голову.","primary_genre":"Драм-н-бейс","primary_mood":"Надежда","primary_theme":"Возвращение","story_shelf":"Трагические истории","conflict_key":"поход-против-порога-дома","image_key":"ивы-при-уходе-снег-при-возврате","turn_key":"родной-порог-в-снегу","hook_key":"помню-ивы-теперь-снег","sort_order":"1229","original_key":"shijing|cai-wei","author_name":"Аноним — Ши-цзин","original_title":"采薇 (Собираем вики)","original_language":"Chinese","origin_country":"Китай","original_year":"","source_url":"https://en.wikipedia.org/wiki/Classic_of_Poetry","rights_check":"Справочно: права не проверяются, идея не текст. Анонимная традиция, эпоха I тысячелетие до н. э.","music_adaptations":[],"source_synopsis":"Солдат вспоминает свою службу: тогда, уходя, шумели ивы, теперь, возвращаясь, валит снег. Война не давала ни сесть, ни встать, ни письма; голодный, он собирал дикие вики — и никто не знает его горя.","main_image":"ивы при уходе и снег при возвращении"},{"title":"По ту сторону воды","full_story":"Он живёт в квартале у реки, а её мир — новый квартал на другом берегу: другие школы, другие подъезды, другие чаты. Каждый рассвет он ходит вдоль тростника и не решается перейти мост — будто вода между ними по колено, а вернее — по грудь. Однажды в тумане на середине моста он видит её силуэт — и она, глядя на его мокрые кеды, сама делает шаг к нему: вода всегда была не шириной, а страхом.","hero_pov":"парень, который ходит вдоль чужого берега","central_conflict":"вода против решимости перейти","emotional_arc":"от кружения в тростнике к одному общему шагу по мосту","ending_direction":"в тумане они встречаются на середине моста — она первая","hook_direction":"ты всегда за водой","genres":["Драм-н-бейс","Трэп"],"moods":["Тоска","Драйв"],"energy":"Высокая","themes":["Любовь","Город"],"generator_brief":"Текучий ликвид-драм-н-бейс: бас как течение, шёпот тростника в хай-хэтах, вокал с моста в туман, дроп — первый общий шаг.","generator_story":"Парень каждый рассвет бродит у тростника: на другом берегу она, и мост он не решается перейти. Однажды в тумане на середине моста он видит её силуэт — и она, заметив его мокрые кеды, шагает первой.","primary_genre":"Драм-н-бейс","primary_mood":"Тоска","primary_theme":"Любовь","story_shelf":"Любовные сцены","conflict_key":"вода-против-решимости-перейти","image_key":"тростник-и-туман-над-рекой","turn_key":"она-сама-делает-шаг","hook_key":"ты-всегда-за-водой","sort_order":"1230","original_key":"shijing|jian-jia","author_name":"Аноним — Ши-цзин","original_title":"蒹葭 (Тростник и камыши)","original_language":"Chinese","origin_country":"Китай","original_year":"","source_url":"https://en.wikipedia.org/wiki/Classic_of_Poetry","rights_check":"Справочно: права не проверяются, идея не текст. Анонимная традиция, эпоха I тысячелетие до н. э.","music_adaptations":[],"source_synopsis":"Тростник сер и густ, белая роса ещё не высохла. Тот, кого я люблю, — где-то за водой: иду вверх по течению — путь труден и долог; иду вниз — она словно в середине воды, всё время на другом берегу.","main_image":"тростник и туман над рекой, любимая всегда за водой"},{"title":"Тень в стакане воды","full_story":"Слесарь уезжает по вахте на север на год: дочка вцепляется в его куртку на таможне, жена стоит у выхода без слов. В общежитии он заводит привычку: каждый вечер снимает на видео стакан воды и говорит в камеру, что сегодня её тень была в воде. Домой он возвращается с двенадцатью месяцами таких видео — дочка смотрит их подряд вместо сказки.","hero_pov":"вахтовик, который пьёт воду и видит тени","central_conflict":"наряд на север против дочки, вцепившейся в куртку","emotional_arc":"от тяжёлого отъезда к водяной связи через весь год","ending_direction":"домой — с двенадцатью месяцами воды и теней","hook_direction":"даже вода помнит тебя","genres":["Трэп","Соул"],"moods":["Одиночество","Тепло"],"energy":"Средняя","themes":["Расставание","Семья"],"generator_brief":"Мелодичный трэп с хвойным холодом: мягкие 808 как шаги по снегу, капли воды в битах, полушёпотная читка в камеру, припев — детский голос в трубке.","generator_story":"Уезжая по вахте, слесарь каждый вечер снимает стакан воды на видео и говорит дочке, что её тень была в воде. Через год он возвращается с двенадцатью месяцами видео — дочка смотрит их вместо сказки.","primary_genre":"Трэп","primary_mood":"Одиночество","primary_theme":"Расставание","story_shelf":"Трагические истории","conflict_key":"наряд-на-север-против-дочки-за-куртку","image_key":"тень-жены-в-стакане-воды","turn_key":"год-разлуки-как-задание","hook_key":"даже-вода-помнит-тебя","sort_order":"1231","original_key":"man-yoshu|sakimori-uta","author_name":"Аноним — Манъёсю","original_title":"萬葉集·防人歌 (Man'yoshu — песни пограничных стражей)","original_language":"Japanese","origin_country":"Япония","original_year":"","source_url":"https://en.wikipedia.org/wiki/Man%27y%C5%8Dsh%C5%AB","rights_check":"Справочно: права не проверяются, идея не текст. Анонимная традиция, эпоха VIII век.","music_adaptations":[],"source_synopsis":"Сборник коротких песен простых пограничных стражей, уводимых в 755 году из восточных провинций на дальние заставы, и их семей. Страж пишет жене, что пьёт воду — и даже в воде видит её тень; другой оставляет детей, которые плачут, вцепившись в его одежду.","main_image":"тень жены в стакане воды"},{"title":"Лепестки в штиль","full_story":"Через год после краха его команды все настроения выровнялись: доход, спорт, спокойные обеды. И именно в самый тихий весенний день, когда ничего не происходит, у него дрожат руки — как лепестки, летящие без ветра. Он перестаёт бороться с штилем: берёт зонт-трость и идёт по аллее под падающими лепестками, разрешая себе дрожать ровно столько, сколько падают цветы.","hero_pov":"человек, у которого дрожат руки в штиль","central_conflict":"тихий день против беспокойного падения лепестков","emotional_arc":"от тревоги в покое к праву дрожать в штиль","ending_direction":"он идёт по аллее — дрожь и лепестки наконец в одном ритме","hook_direction":"в тишине падают цветы","genres":["Электропоп","Лоу-фай"],"moods":["Тревога","Освобождение"],"energy":"Средняя","themes":["примирение","Выбор"],"generator_brief":"Тонкий лоу-фай электропоп: дыхание штиля в падах, редкие капли лепестков на хай-хэтах, уязвимый вокал, финал — медленный отпуск штиля.","generator_story":"Через год после краха всё выровнялось, но в тихий весенний день у него дрожат руки, как лепестки без ветра. Он перестаёт бороться: идёт по аллее под лепестками и разрешает себе дрожать в их ритме.","primary_genre":"Электропоп","primary_mood":"Тревога","primary_theme":"примирение","story_shelf":"Трагические истории","conflict_key":"тихий-день-против-летающих-лепестков","image_key":"лепестки-без-ветра","turn_key":"штиль-перестал-пугать","hook_key":"в-тишине-падают-цветы","sort_order":"1232","original_key":"ki-no-tsurayuki|hana-no-chiru","author_name":"Ки-но Цураюки","original_title":"久方の光のどけき春の日に (Кокинсю, Тихий весенний день)","original_language":"Japanese","origin_country":"Япония","original_year":"","source_url":"https://en.wikipedia.org/wiki/Ki_no_Tsurayuki","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 945.","music_adaptations":[],"source_synopsis":"Стихотворение из антологии Кокинсю (905 год): в тихом свете безмятежного весеннего дня цветы вдруг осыпаются — почему их падение такое беспокойное, без волнения и без причины?","main_image":"лепестки, падающие в полный штиль"},{"title":"Тростник Нанивы","full_story":"После банкротства его не читают даже старые подписчики, она не отвечает месяц. Он пишет ей не о деньгах и не о правоте — только то, что даже если его сделают тростником, по колено в чужой воде, он всё равно хочет встречи. Ответ приходит одной строкой — адресом рынка Нанивы, где тростник свежий, — и он впервые за год выходит из дома с чистой головой.","hero_pov":"разорившийся человек, пишущий ей всё равно","central_conflict":"немой отказ против просьбы о встрече","emotional_arc":"от униженной нищеты к одному назначенному месту","ending_direction":"одна строка-адрес — и он выходит навстречу","hook_direction":"даже тростником желаю встречи","genres":["Хаус","R&B"],"moods":["Уязвимость","Надежда"],"energy":"Средняя","themes":["Любовь","самоценность"],"generator_brief":"Глубокий осака-хаус: влажный бас болота, редкий треск тростника в снэрах, тихий вокал без жалобы, финал — один тёплый аккорд выхода из дома.","generator_story":"Разорившийся герой пишет любимой: пусть его делают тростником в чужой воде, он всё равно хочет встречи. Ответ приходит одной строкой — адресом рынка Нанивы, — и он впервые за год выходит из дома.","primary_genre":"Хаус","primary_mood":"Уязвимость","primary_theme":"Любовь","story_shelf":"Любовные сцены","conflict_key":"немой-ответ-против-просьбы-о-встрече","image_key":"тростник-нанивы-по-колено-в-воде","turn_key":"одна-строка-ответа","hook_key":"даже-тростником-желаю-встречи","sort_order":"1233","original_key":"ki-no-tsurayuki|naniwa-ashi","author_name":"Ки-но Цураюки","original_title":"わびぬれば今はた同じ難波なる (Кокинсю, Тростник Нанивы)","original_language":"Japanese","origin_country":"Япония","original_year":"","source_url":"https://en.wikipedia.org/wiki/Ki_no_Tsurayuki","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 945.","music_adaptations":[],"source_synopsis":"Стихотворение из антологии Кокинсю (905 год): он так нищ и унижен, что теперь равен тростникам Нанивы; но даже если ему суждено стать тростником — он всё равно хочет увидеть её.","main_image":"тростник, по колено стоящий в болотной воде Нанивы"},{"title":"Бекасы поднимаются","full_story":"Бывший оператор, пять лет работающий с чужими бедами, убеждён: у него больше нет сердца, только чек-лист. В командировке на осеннем болоте он снимает стаю, и в момент, когда бекасы вдруг поднимаются из камыша на закате, — камера стоит, а он плачет в кадре. Он не вырезает этот дубль: своё возвращение к чувствам он оставляет в финальном ролике без комментариев.","hero_pov":"оператор, у которого якобы нет сердца","central_conflict":"выгоревшее сердце против крика поднимающихся бекасов","emotional_arc":"от защитного онемения к внезапной живой слезе","ending_direction":"неотретушированный дубль со слезами остаётся в ролике","hook_direction":"даже я это чувствую","genres":["Техно","Эмбиент"],"moods":["Спокойствие","Надежда"],"energy":"Низкая","themes":["Дружба","животные"],"generator_brief":"Холодное болотное техно: сухой пульс камыша, взлёт стаи сэмплом на брейке, ровный вокал, который ломается один раз — и на этом держится песня.","generator_story":"Оператор, пять лет снимающий чужие беды, уверен: вместо сердца — чек-лист. Но когда на закате бекасы поднимаются из камыша, он плачет в кадре — и оставляет этот дубль в ролике без комментариев.","primary_genre":"Техно","primary_mood":"Спокойствие","primary_theme":"Дружба","story_shelf":"Люди и животные","conflict_key":"выгоревшее-сердце-против-крика-бекасов","image_key":"бекасы-над-осенним-болотом","turn_key":"впервые-за-годы-чувствует","hook_key":"даже-я-это-чувствую","sort_order":"1234","original_key":"saigyo|shigi-tatsu-sawa","author_name":"Сайгю","original_title":"心なき身にもあはれは知られけり (Бекасы на осеннем болоте)","original_language":"Japanese","origin_country":"Япония","original_year":"","source_url":"https://en.wikipedia.org/wiki/Saigy%C5%8D","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1190.","music_adaptations":[],"source_synopsis":"У меня нет сердца — и всё же трогательное доходит до меня: осенний вечер на болоте, где поднимаются бекасы.","main_image":"бекасы, поднимающиеся из осеннего болота в сумерках"},{"title":"Дожить до вишни","full_story":"После тяжёлого диагноза он повторяет старое стихотворение про смерть весной под цветами — и договорился с собой: главное — не перележать эту вишню. Год, оставленный врачами, он живёт как ход до цветения: сажает сакуру во дворе, доучивает дочь японскому, доходит до моря. В полночь цветения он сидит под собственной вишней — и впервые желает не умереть вовремя, а увидеть, как она зацветёт снова.","hero_pov":"человек, который заключил союз с одной вишней","central_conflict":"желание умереть вовремя против весны, которая требует дожить","emotional_arc":"от договорённости со смертью к желанию ещё одной весны","ending_direction":"под зацветающей сакурой он впервые хочет увидеть следующую весну","hook_direction":"дожить до весны","genres":["Трэп","Эмбиент"],"moods":["Надежда","Уязвимость"],"energy":"Средняя","themes":["примирение","смелость"],"generator_brief":"Тихий эмбиент-трэп: лепестки на паде вместо хай-хэтов, лунный подголосок, шёпотная читка молитвы, финал — дыхание цветущей ветки без бита.","generator_story":"После тяжёлого диагноза герой живёт оставленный врачами год как ход до цветения: сажает сакуру, доходит до моря. Под собственной вишней он впервые хочет не умереть вовремя, а увидеть следующую весну.","primary_genre":"Трэп","primary_mood":"Надежда","primary_theme":"примирение","story_shelf":"Трагические истории","conflict_key":"желание-умереть-весной-против-весны","image_key":"цветущая-вишня-над-головой","turn_key":"до-вишни-надо-дожить","hook_key":"дожить-до-весны","sort_order":"1235","original_key":"saigyo|hana-no-shita-shinu","author_name":"Сайгю","original_title":"願はくは花の下にて春死なん (Умереть весной под цветами)","original_language":"Japanese","origin_country":"Япония","original_year":"","source_url":"https://en.wikipedia.org/wiki/Saigy%C5%8D","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1190.","music_adaptations":[],"source_synopsis":"Молитва поэта: пусть умру я весной, под цветами, в полнолуние второго месяца — так гласит легенда о его последнем желании.","main_image":"цветущая вишня над головой в полнолуние"},{"title":"Жалоба на сердце","full_story":"Он устраивает сердцу дневной разбор на скамейке: смерть, начальник, — одна, а ты болишь каждый день по новой, транжира. Сердце молчит, как всегда. Тогда он меняет тактику: вместо лекций ведёт сердце гулять — в парк, на рынок, на крышу, — и замечает, что меньше всего оно болит в движении. С этого дня их отношения официально называются «прогулка».","hero_pov":"человек, уставший жаловаться на собственное сердце","central_conflict":"ежедневная боль сердца против одной-единственной смерти","emotional_arc":"от язвительной лекции к ласковой совместной прогулке","ending_direction":"сердце болит меньше всего в движении — маршрут составлен","hook_direction":"смерть одна, а ты болишь ежедневно","genres":["Хип-хоп","Блюз"],"moods":["Ирония","Уязвимость"],"energy":"Средняя","themes":["ссора","дружба"],"generator_brief":"Блюзовый хип-хоп с ленивым свингом: читка-разговор с самим собой, стук сердца как драм-луп, в бридже сердцебиение замедляется — и песня идёт гулять.","generator_story":"Мужчина устраивает сердцу разбор на скамейке: смерть случается однажды, а ты болишь каждый день. Он меняет лекцию на прогулку — парк, рынок, крыша — и замечает: меньше всего сердце болит в движении.","primary_genre":"Хип-хоп","primary_mood":"Ирония","primary_theme":"ссора","story_shelf":"Юмор: семейные драмы","conflict_key":"ежедневная-боль-против-одной-смерти","image_key":"разговор-с-сердцем-на-скамейке","turn_key":"берёт-сердце-гулять","hook_key":"смерть-одна-а-ты-болишь-ежедневно","sort_order":"1236","original_key":"ghalib|dil-e-nadan","author_name":"Галиб","original_title":"دل ناداں تجھے ہوا کیا ہے (Dil-e-nadan tujhe hua kya hai, Глупое сердце)","original_language":"Urdu","origin_country":"Индия","original_year":"1841","source_url":"https://en.wikipedia.org/wiki/Ghalib","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1869.","music_adaptations":[],"source_synopsis":"Поэт обращается к своему глупому сердцу: смерть приходит однажды, зачем же ты болишь каждый день? Порицание сердца — его давняя тема, но здесь больше ласки, чем брани.","main_image":"разговор с сердцем на скамейке"},{"title":"Тысяча желаний","full_story":"После панической атаки в 41 он пишет тетрадь тысячи желаний — каждое, по его шутке, стоит целой жизни. Он выполняет их маленькие: объездить трамвайный круг с последней остановки, научиться свистеть, увидеть море в будний день. Вечер открытого микрофона становится списком вслух: зал дописывает его тетрадь своими желаниями, и к полуночи понятно — тысяча не кончается, и это лучшая новость.","hero_pov":"человек, впервые составляющий список желаний","central_conflict":"тетрадь желаний против отложенной жизни","emotional_arc":"от испуга за свою жизнь к радости неисчерпаемого списка","ending_direction":"зал дописывает тетрадь — тысяча не кончается, и это хорошо","hook_direction":"каждое желание стоит жизни","genres":["EDM","Поп"],"moods":["Вдохновение","Эйфория"],"energy":"Высокая","themes":["Сцена","Мечта"],"generator_brief":"Стадионный EDM с бумажным шорохом страниц: названия желаний читаются как барабанная дробь, дроп — «начать сегодня», финал — зал скандирует новые пункты.","generator_story":"После панической атаки мужчина заводит тетрадь тысячи желаний: трамвайный круг, свист, море в будний день. На открытом микрофоне зал дописывает его список — и тысяча не кончается, что только радует.","primary_genre":"EDM","primary_mood":"Вдохновение","primary_theme":"Сцена","story_shelf":"Трагические истории","conflict_key":"список-желаний-против-отложенной-жизни","image_key":"тетрадь-тысячи-желаний","turn_key":"зал-дописывает-список","hook_key":"каждое-желание-стоит-жизни","sort_order":"1237","original_key":"ghalib|hazaron-khwahishen","author_name":"Галиб","original_title":"Hazaron khwahishen aisi (Тысяча желаний)","original_language":"Urdu","origin_country":"Индия","original_year":"1841","source_url":"https://en.wikipedia.org/wiki/Ghalib","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1869.","music_adaptations":[],"source_synopsis":"Тысяча желаний, каждое из которых достойно того, чтобы умереть за него: многие исполнились — и всё равно их осталось слишком много. Даже пожалеть об исполненном — часть желания.","main_image":"тетрадь тысячи желаний"},{"title":"Страха нет","full_story":"Родня двадцать лет объясняет ей на семейных застольях, какой она «неудачница», и ждёт от неё тишины. На городском открытом микрофоне она вместо оправданий выходит с литанией: даже если весь мир против, даже если судят неправедно, даже если ночь без фонаря — страха нет. Куплет за куплетом зала перестаёт хихикать и подхватывает рефрен, а в последнем ряду встают её собственные родные.","hero_pov":"девочка, которую дома учили молчать","central_conflict":"насмешки родни против литании без страха","emotional_arc":"от семейной тишины к публичному бесстрашию","ending_direction":"родня встаёт и подпевает рефрен вместе с залом","hook_direction":"даже если весь мир против","genres":["Панк","Рок"],"moods":["Смелость","Протест"],"energy":"Высокая","themes":["Сцена","смелость"],"generator_brief":"Быстрый панк с народным пением: гитары как кулачный бой, рефрен «страха нет» скандирует зал, куплеты нарастают как список бед, финал — общий хор.","generator_story":"Родня двадцать лет стыдит её на застольях, но на микрофоне она вместо оправданий выводит литанию без страха — зал перестаёт хихикать и подхватывает рефрен, а в последнем ряду встают родные.","primary_genre":"Панк","primary_mood":"Смелость","primary_theme":"Сцена","story_shelf":"Юмор: семейные драмы","conflict_key":"насмешки-родни-против-литании-без-страха","image_key":"микрофон-против-целого-мира","turn_key":"родня-подпевает-в-зале","hook_key":"даже-если-весь-мир-против","sort_order":"1238","original_key":"bharati|achamillai","author_name":"Субрамания Бхарати","original_title":"அச்சமில்லை அச்சமில்லை (Achamillai achamillai, Страха нет)","original_language":"Tamil","origin_country":"Индия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Subramania_Bharati","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1921.","music_adaptations":[],"source_synopsis":"Литания бесстрашия: даже если весь мир встанет против меня, даже если судьи будут несправедливы, даже если... — страха нет, страха нет. Правда — наш союзник, и её именем снимается каждый страх.","main_image":"микрофон против целого мира"},{"title":"Кукушка поёт о прошлой жизни","full_story":"Вокалист, обожжённый индустрией, мечтает сбросить свою форму — стать просто птицей в сквере, без имени и лейбла. В сквере он встречает уличную певицу-«кукушку»: та поёт свою песню, и в ней он узнаёт свою прошлую жизнь — сцену, славу, падение. Он не подписывает её и не себя: он остаётся человеком и впервые за годы поёт свою честную песню в подземке, где кукушка — первая в зале.","hero_pov":"вокалист, который хотел стать птицей","central_conflict":"слава против простого пения кукушки","emotional_arc":"от мечты сбросить форму к возвращению своего голоса","ending_direction":"своя честная песня в подземке — кукушка первая в зале","hook_direction":"кукушка поёт о её прошлой жизни","genres":["Электропоп","Синтвейв"],"moods":["Мечтательность","Меланхолия"],"energy":"Средняя","themes":["Сцена","музыка"],"generator_brief":"Синтвейв-электропоп с птичьим тембром: писк кукушки в арпеджио, вокал в двух голосах — человеческий и птичий, финал — подземное эхо без реверберации.","generator_story":"Вокалист, обожжённый индустрией, мечтает стать просто птицей без имени. Уличная певица в сквере поёт о его ушедшей славе — и он впервые за годы поёт честную песню в подземке, где она первая в зале.","primary_genre":"Электропоп","primary_mood":"Мечтательность","primary_theme":"Сцена","story_shelf":"Люди и животные","conflict_key":"слава-против-пения-кукушки","image_key":"кукушка-в-городском-сквере","turn_key":"чужая-песня-возвращает-свою","hook_key":"слушай-кукушку-о-ней-самой","sort_order":"1239","original_key":"bharati|kuyil-pattu","author_name":"Субрамания Бхарати","original_title":"குயில் பாட்டு (Kuyil Pattu, Песня кукушки)","original_language":"Tamil","origin_country":"Индия","original_year":"1912","source_url":"https://en.wikipedia.org/wiki/Subramania_Bharati","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1921.","music_adaptations":[],"source_synopsis":"Поэт мечтает сбросить человеческую форму и стать кукушкой. Кукушка поёт ему и рассказывает историю своей прошлой жизни — так через её песню раскрывается судьба человеческой души.","main_image":"кукушка в городском сквере, поющая о прошлой жизни"},{"title":"Движущееся остаётся","full_story":"В их приходе собирают на мраморный храм: комитет сверяет списки, а дворник, который моет все эти залы двадцать лет, в долю не входит — зарплата не позволяет. Он выходит на собрание с одной ремаркой: у богатых — камень, у него — ноги-колонны, и стоящее падёт, а движущееся останется. Через год град ломает недостроенную башню комитета, а дворник всё так же ходит по этажам: его «храм» не сдвинулся ни на шаг.","hero_pov":"дворник, у которого тело — святилище","central_conflict":"мрамор богачей против тела труженика","emotional_arc":"от заочного стыда к спокойному достоинству работающего храма","ending_direction":"башня упала — дворник всё так же движется по этажам","hook_direction":"движущееся остаётся","genres":["Хаус","Фолк"],"moods":["Сила","Благородство"],"energy":"Высокая","themes":["Город","Сила"],"generator_brief":"Рабочий хаус с народным пением: шаги-кики как мытьё полов, ладонные хлопки комитета, вокал дворника ниже всех — и именно он держит тон.","generator_story":"На мраморный храм собирает приход, а дворник, моющий залы годами, в долю не входит: у богатых камень, у него ноги. Через год град ломает недостроенную башню, а дворник всё так же ходит по этажам.","primary_genre":"Хаус","primary_mood":"Сила","primary_theme":"Город","story_shelf":"Юмор: семейные драмы","conflict_key":"мрамор-богачей-против-тела-труженика","image_key":"рабочие-ноги-как-колонны","turn_key":"стоящее-упало-движущееся-осталось","hook_key":"движущееся-остаётся","sort_order":"1240","original_key":"basavanna|ullavaru-shivalaya","author_name":"Басаванна","original_title":"ಉಳ್ಳವರು ಶಿವಾಲಯವ ಮಾಡುವರು (вачана «Храм и тело»)","original_language":"Kannada","origin_country":"Индия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Basava","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 1167.","music_adaptations":[],"source_synopsis":"Богачи построят храмы — что делать бедному? У него нет камня: его ноги — колонны, тело — святилище, голова — золотой купол. Стоящее падёт, а движущееся останется навсегда.","main_image":"рабочие ноги как колонны храма"},{"title":"Нить жемчуга","full_story":"Сельский чат воюет месяц из-за того, кто виноват в размытой дороге: сотни сообщений, ноль действий. Старый ювелир выносит на сход вачану: слова — как жемчуг, их нанизывают на одну нить, и лишняя бусина ломает ожерелье. Он предлагает каждой стороне по одной фразе — и на этих двух фразах они за вечер чистят дорогу. С тех пор в чате правило: сначала нить, потом бусины.","hero_pov":"старый ювелир, который умеет нанизывать","central_conflict":"болтовня чата против нити жемчуга","emotional_arc":"от многоголосья и спора к одной нити и общему делу","ending_direction":"дорога вычищена за вечер — правило нити принято чатом","hook_direction":"слова как жемчуг","genres":["Хип-хоп","Фолк"],"moods":["Уверенность","Спокойствие"],"energy":"Средняя","themes":["ссора","Дружба"],"generator_brief":"Народный хип-хоп с щёлкающими жемчужинами в перкуссии: читка каждой стороны ровно по одной строфе, дед встаёт с вачаной, финал — совместная работа под ритм лопат.","generator_story":"Сельский чат месяц воюет из-за размытой дороги — сотни сообщений, ноль действий. Старый ювелир предлагает каждой стороне по одной фразе, как бусине на общей нити, — и за вечер дорога вычищена.","primary_genre":"Хип-хоп","primary_mood":"Уверенность","primary_theme":"ссора","story_shelf":"Юмор: семейные драмы","conflict_key":"болтовня-чата-против-нити-жемчуга","image_key":"жемчуг-на-одной-нити","turn_key":"разговор-закончился-делом","hook_key":"слова-как-жемчуг","sort_order":"1241","original_key":"basavanna|pearl-string","author_name":"Басаванна","original_title":"вачана о жемчужной нити слов","original_language":"Kannada","origin_country":"Индия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Basava","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 1167.","music_adaptations":[],"source_synopsis":"Учение Басаванны о речи: слова должны быть нанизаны на нить, как жемчуг, — каждое на своём месте, без лишних бусин; решает не слово, а дело.","main_image":"жемчуг, нанизанный на одну нить"},{"title":"Любовь дольше красоты","full_story":"Она любила его в двадцать — он ушёл в другой город и стал тем, кем стал; она прожила сорок лет своих и не рассказывала никому. Он находит её в шестьдесят с чем-то, седую, с садом, который она вырастила вместо него. Она не спрашивает, откуда он взялся, — спрашивает, той ли была красота, что она когда-то видела; и он отвечает, что красота теперь стоит во дворе и пахнет яблоками.","hero_pov":"мужчина, вернувшийся к той, что ждала всю жизнь молча","central_conflict":"сорок лет разлуки против встречи в старости","emotional_arc":"от горечи несказанного к спокойному воссоединению","ending_direction":"красота возвращается не молодостью — она стоит в саду и пахнет яблоками","hook_direction":"любовь пережила красоту","genres":["Драм-н-бейс","Классика"],"moods":["Любовь","Нежность"],"energy":"Высокая","themes":["Возвращение","Любовь"],"generator_brief":"Ликвид-драм-н-бейс с восточной струной: сантур над ломаным брейком, вокал двух возрастов в одном треке, дроп — ворота сада открываются.","generator_story":"Он находит в шестьдесят женщину, которую любил в двадцать: она седая, с садом, выращенным вместо него. На вопрос о былой красоте он отвечает: красота теперь стоит во дворе и пахнет яблоками.","primary_genre":"Драм-н-бейс","primary_mood":"Любовь","primary_theme":"Возвращение","story_shelf":"Любовные сцены","conflict_key":"сорок-лет-разлуки-против-старческой-встречи","image_key":"она-встречает-его-в-старости","turn_key":"красота-вернулась-не-молодостью","hook_key":"любовь-пережила-красоту","sort_order":"1242","original_key":"jami|yusuf-va-zulaikha","author_name":"Джами","original_title":"یوسف و زلیخا (Yusuf va Zulaykha, Юсуф и Зулейха)","original_language":"Persian","origin_country":"Персия","original_year":"1483","source_url":"https://en.wikipedia.org/wiki/Jami","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1492.","music_adaptations":[],"source_synopsis":"Зулейха в молодости любила Юсуфа страстно и безответно; через десятилетия потерь и слёз он возвращается к ней, когда она состарилась. Она спрашивает о красоте, которую когда-то видела, — и их любовь оказывается сильнее и её молодости, и его славы.","main_image":"старая женщина, встречающая возвращённого красавца"},{"title":"Кинжал для глаза","full_story":"После разрыва глаз ведёт себя как шпион: находит её в чужих сториз, в машинах на парковке, в похожих куртках. Сердце ведёт себя как архив: хранит всё, что глаз наглядел. Он в шутках грозит глазу кинжалом — выключает цветной режим на телефоне, уезжает в другой город, сносит аккаунты, — но сердце всё равно помнит. Перемирие наступает, когда он разрешает глазу смотреть на новое, а сердцу — помнить старое: архив работает, шпион уволен.","hero_pov":"человек, воюющий с собственным глазом","central_conflict":"глаз-шпион против сердца-хранителя","emotional_arc":"от яростной шуточной резни к перемирию двух органов","ending_direction":"глаз смотрит новое, сердце хранит старое — мир подписан","hook_direction":"закрой глаз — сердце всё равно помнит","genres":["Панк","Рэп"],"moods":["Злость","Ирония"],"energy":"Взрывная","themes":["ссора","Память"],"generator_brief":"Грязный весёлый панк: рваные гитары как спор двух органов, кричалка-вердикт, в бридже — секунда тишины и перемирие под один аккорд.","generator_story":"Глаз героя после разрыва — шпион: находит бывшую в сториз и похожих куртках, а сердце-архив всё хранит. Он уезжает и сносит аккаунты, пока не заключает перемирие: глазу — новое, сердцу — старое.","primary_genre":"Панк","primary_mood":"Злость","primary_theme":"ссора","story_shelf":"Юмор: семейные драмы","conflict_key":"глаз-шпион-против-сердца-хранителя","image_key":"кинжал-направленный-на-глаз","turn_key":"перемирие-глаза-и-сердца","hook_key":"закрой-глаз-сердце-всё-равно-помнит","sort_order":"1243","original_key":"baba-taher|z-dast-dide-o-del","author_name":"Баба Тахер","original_title":"ز دست دیده و دل هر دو فریاد (От глаза и сердца — крик)","original_language":"Persian","origin_country":"Персия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Baba_Taher","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер после 1055.","music_adaptations":[],"source_synopsis":"Дервишский двустиший-кватрейн: от глаза и сердца — крик обоих, ведь что ни увидит глаз, то запомнит сердце. Поэт грозит выковать стальной кинжал и поразить глаз, чтобы сердце стало свободным.","main_image":"кинжал, направленный на собственный глаз"},{"title":"Раньше, чем узнал слово","full_story":"Он сорок лет жил по инструкции: работа, спорт, две недели отпуска, — и никогда не использовал слово «любовь», потому что не знал его значения. На перроне провинциального вокзала он встречает лицо — и за одну зиму отдаёт и квартиру, и планы на пенсию, и привычную гордость. Все называют это безумием; он впервые проверяет слово в словаре — и отвечает, что влюбился раньше, чем узнал, что такое любовь, теперь знает.","hero_pov":"человек, который впервые применил слово «любовь»","central_conflict":"разумная жизнь по инструкции против любви, пришедшей раньше слова","emotional_arc":"от испуга перед собой к спокойному признанию","ending_direction":"он отдал всё и впервые знает значение слова","hook_direction":"полюбил раньше слова","genres":["Хаус","Соул"],"moods":["Любовь","Уязвимость"],"energy":"Средняя","themes":["Любовь","Выбор"],"generator_brief":"Тёплый соул-хаус: вокал поёт «раньше», чем слова успевают, клавиши как поезд на перроне, припев держится на одном повторяемом имени без фамилий.","generator_story":"Он сорок лет жил по инструкции и не знал слова «любовь». На перроне он встречает лицо и за одну зиму отдаёт квартиру и пенсию — все зовут его безумцем, но теперь он знает значение слова.","primary_genre":"Хаус","primary_mood":"Любовь","primary_theme":"Любовь","story_shelf":"Любовные сцены","conflict_key":"любовь-раньше-слова-о-любви","image_key":"лицо-на-перроне-за-которое-всё","turn_key":"впервые-знает-что-такое-любовь","hook_key":"полюбил-раньше-слова","sort_order":"1244","original_key":"baba-taher|rakht-didam","author_name":"Баба Тахер","original_title":"رخت دیدم و جان فدای رخت آمدم (Увидел лицо — отдал жизнь)","original_language":"Persian","origin_country":"Персия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Baba_Taher","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер после 1055.","music_adaptations":[],"source_synopsis":"Двустишие: я увидел твоё лицо — и отдал за него свою жизнь; я влюбился раньше, чем узнал, что такое любовь.","main_image":"лицо в толпе, за которое отдано всё"},{"title":"Сердце оплакало","full_story":"Он возвращается из длительного отъезда и узнаёт, что их двор — лавр, лавочка, белая лестница — снесён под парковку. Она не отвечает на его сообщения два года. Он публикует фотографию руин с текстом о том, что сердце оплакало красоту, созданную для мира, — и впервые за два года она отвечает: одной строкой о лавре, который ей приснился. Ответ не возвращает ничего, но парк сносят окончательно в его сердце — с лавром или без.","hero_pov":"человек, оплакивающий снесённое место встречи","central_conflict":"снесённый сад против её холодного молчания","emotional_arc":"от руин и тишины к единственной строке ответа","ending_direction":"её строка о приснившемся лавре — и парк в нём закрывается","hook_direction":"сердце оплакало сад","genres":["Трэп","Баллада"],"moods":["Грусть","Тепло"],"energy":"Высокая","themes":["Расставание","память"],"generator_brief":"Тёмная элегия-трэп: далёкие струны арфы над 808, шум сноса на подаче, вокал читает надгробную речь месту, а не человеку, — и это спасает от пафоса.","generator_story":"Их двор с лавром и белой лестницей снесли под парковку, она молчит два года. На фото руин она впервые отвечает строкой о приснившемся лавре — и парк в его сердце снесён окончательно.","primary_genre":"Трэп","primary_mood":"Грусть","primary_theme":"Расставание","story_shelf":"Трагические истории","conflict_key":"снесённый-сад-против-её-холода","image_key":"руины-сада-встреч","turn_key":"её-одна-строка-на-пост","hook_key":"сердце-оплакало-сад","sort_order":"1245","original_key":"ibn-zaydun|qad-naa-al-qalb","author_name":"Ибн Зейдун","original_title":"قد نعى القلب (Сердце оплакало)","original_language":"Arabic","origin_country":"Испания (Андалусия)","original_year":"","source_url":"https://en.wikipedia.org/wiki/Ibn_Zaydun","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1071.","music_adaptations":[],"source_synopsis":"Из кордовского заключения поэт пишет элегию о саде их встреч, разрушенном временем и ссорами, и оплакивает женщину, созданную для этого мира: сердце его оплакано её холодом.","main_image":"руины сада встреч, где теперь стоянка"},{"title":"Сердце на Востоке","full_story":"Он шеф-повар лучшего ресторана западной кухни, но каждую ночь его сердце пахнет другим: улицей, которую он не видел сорок лет. Еда у него не съедобна для него самого — все блюда выходят точными и безвкусными. В шестьдесят пять он закрывает ресторан, отдаёт пиджак и садится на первый Восточный рейс: в гавани он ест чужой уличный шаурму и впервые за сорок лет чувствует вкус.","hero_pov":"повар, у которого сердце восточнее меню","central_conflict":"адрес против сердца, которое дальше всех карт","emotional_arc":"от точной безвкусной жизни к первому вкусу на пути домой","ending_direction":"он плывёт на Восток и впервые чувствует вкус","hook_direction":"сердце уже там","genres":["Драм-н-бейс","Соул"],"moods":["Вдохновение","Тоска"],"energy":"Высокая","themes":["Возвращение","Дорога"],"generator_brief":"Морской драм-н-бейс: брейк как палуба под штормом, вокал шефа на грани смеха и слёз, дроп — отдача швартовых, в финале — вкус первого куска.","generator_story":"Шеф-повар готовит безвкусные для себя блюда: его сердце сорок лет пахнет улицей, которой нет рядом. В шестьдесят пять он закрывает ресторан и плывёт на Восток — и в гавани впервые чувствует вкус.","primary_genre":"Драм-н-бейс","primary_mood":"Вдохновение","primary_theme":"Возвращение","story_shelf":"Трагические истории","conflict_key":"адрес-против-сердца-на-востоке","image_key":"несъедобный-ужин-на-западе","turn_key":"в-шестьдесят-пять-плывёт-на-восток","hook_key":"сердце-уже-там","sort_order":"1246","original_key":"yehuda-halevi|libi-bamizrach","author_name":"Иегуда Галеви","original_title":"ליבי במזרח (Libi ba-mizrach, Сердце моё на Востоке)","original_language":"Hebrew","origin_country":"Испания (Андалусия)","original_year":"","source_url":"https://en.wikipedia.org/wiki/Judah_Halevi","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1141.","music_adaptations":[],"source_synopsis":"Моё сердце — на Востоке, а сам я на краю Запада: как мне найти вкус в еде, как исполнить мои обеты? Меня бы выпустили облака — но арабские слова, тоска по Сиону остаются со мной.","main_image":"несъедобный ужин на самом краю Запада"},{"title":"Дуэль за ночь поэта","full_story":"Ночной поэт-фрилансер сдает дедлайны в три часа утра, и в его баре давно два клана: клан вина (громкая муза, вечерние планы) и клан дымки (тихая задержка, утренние оправдания). Однажды они решают спор открыто: каждый рассказывает, что дал поэту, и кто он без него. Поэт выносит вердикт песней: оба — братья, но ночь принадлежит ему, и с этого вечера у него будильник в половине одиннадцатого.","hero_pov":"поэт, за ночь которого спорят двое","central_conflict":"вино против дымки за право владеть ночью поэта","emotional_arc":"от втянутости в чужой спор к собственному вердикту","ending_direction":"вердикт песней: ночь моя, будильник в половине одиннадцатого","hook_direction":"ночь моя — друзья подождут","genres":["Панк","Рок"],"moods":["Эйфория","Ирония"],"energy":"Взрывная","themes":["ссора","Дружба"],"generator_brief":"Барный панк-баттл: два вокала-соперника — гулкий и звонкий, крики зала на подачах, вердикт поэта в бридже — самый тихий и самый твёрдый куплет.","generator_story":"В баре ночного поэта два клана — вина и дымки — спорят, кому он принадлежит. Поэт выносит вердикт песней: оба братья, но ночь его, и с этого вечера его будильник звенит в половине одиннадцатого.","primary_genre":"Панк","primary_mood":"Эйфория","primary_theme":"Дружба","story_shelf":"Юмор: семейные драмы","conflict_key":"вино-против-дымки-за-ночь-поэта","image_key":"спор-вина-и-дыма-в-баре","turn_key":"поэт-выносит-вердикт","hook_key":"ночь-моя-друзья-подождут","sort_order":"1247","original_key":"fuzuli|beng-u-bade","author_name":"Физули","original_title":"بن و باده (Beng ü Bâde, Опий и вино)","original_language":"Turkish","origin_country":"Османская Турция","original_year":"1530","source_url":"https://en.wikipedia.org/wiki/Fuzuli_(poet)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1556.","music_adaptations":[],"source_synopsis":"Аллегорическая поэма-прения: Опий и Вино выступают как два героя-соперника и спорят о своих правах на поэта и на особое состояние души.","main_image":"бутылка и коробка в двух углах одного бара"},{"title":"Это была любовь","full_story":"Он продал квартиру, перевёлся на другой континент и выучил её язык в сорок лет — весь город считает его безумцем, разрушившим жизнь. Он отвечает на расспросы ровно: для него это не жертва. В день, когда они вместе поднимаются на её балкон, он находит старую фразу и наконец называет вещи их именами: тонуть — значит тонуть; это была любовь, и он бы сделал так же ещё раз.","hero_pov":"человек, которого весь город считал безумцем","central_conflict":"здравый смысл окружающих против добровольного тонущего","emotional_arc":"от колкости чужих вопросов к спокойному имени своему выбору","ending_direction":"он называет это любовью — и подтвердил бы ещё раз","hook_direction":"любовь — значит тонуть","genres":["EDM","Классика"],"moods":["Решимость","Драйв"],"energy":"Взрывная","themes":["Любовь","смелость"],"generator_brief":"Эпический EDM с одним струнным лупом: каждое «любовь значит...» — новая ступень подъёма, дроп — «и я бы снова», без фальш-эмоций, на ровной смелости.","generator_story":"Он продал квартиру, переехал на другой континент и выучил её язык в сорок — весь город зовёт его безумцем. Но на её балконе он называет вещи именами: это была любовь, и он бы повторил ещё раз.","primary_genre":"EDM","primary_mood":"Решимость","primary_theme":"Любовь","story_shelf":"Любовные сцены","conflict_key":"тонуть-добровольно-против-здравого-смысла","image_key":"человек-который-тонет-с-улыбкой","turn_key":"он-называет-это-не-жертвой","hook_key":"любовь-была-тонуть","sort_order":"1248","original_key":"fuzuli|ask-imis","author_name":"Физули","original_title":"عشق ایمیش (Aşk imiş, Это была любовь)","original_language":"Turkish","origin_country":"Османская Турция","original_year":"1535","source_url":"https://en.wikipedia.org/wiki/Fuzuli_(poet)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1556.","music_adaptations":[],"source_synopsis":"Вступительный газель поэмы о Лейли и Меджнуне: любовь — вот что есть в мире; любить — значит тонуть — так и утонуть; любить — значит гореть — так и сгореть.","main_image":"человек, который тонет с улыбкой"},{"title":"Постарел, как лис","full_story":"Он всю жизнь выкручивался: обманывал сроки, ловил конкурентов на словах, уходил от каждой ответственности как лис от охотника. В шестьдесят три, после случая с племянником, который перехитрил его же методом, он спускается в свой гараж-подвал и впервые сидит с собой без телефона. В темноте он ведёт счёт: сколько хитростей, сколько долгов, сколько несделанных звонков — и утром выходит наверх навестить всех, кого он обыграл.","hero_pov":"лис, который наконец пойман собой","central_conflict":"лисья хитрость против честного счёта","emotional_arc":"от привычной ловкости к ночной честности и возврату долгов","ending_direction":"он поднимается из подвала — навестить всех, кого обыграл","hook_direction":"старость догнала лиса","genres":["Техно","Эмбиент"],"moods":["Освобождение","Меланхолия"],"energy":"Низкая","themes":["примирение","Время"],"generator_brief":"Подвальное техно: сухой гул земли, редкие капли воды, голос-шёпот ведёт счёт хитростям; к финалу — шаги вверх по лестнице и первый свет.","generator_story":"Хитрец, всю жизнь уходивший от ответственности, в шестьдесят три сидит в гараже без телефона и впервые честно пересчитывает долги и несделанные звонки. Утром он выходит навестить всех, кого обыграл.","primary_genre":"Техно","primary_mood":"Освобождение","primary_theme":"примирение","story_shelf":"Трагические истории","conflict_key":"лисья-хитрость-против-честного-счёта","image_key":"подземная-келья-в-шестьдесят-три","turn_key":"лис-признаётся-себе","hook_key":"старость-догнала-лиса","sort_order":"1249","original_key":"yasawi|tulki-kartaygan","author_name":"Ахмед Ясави","original_title":"хикмет «Түлкілей қартайған» (Постарел, как лис)","original_language":"Turkic","origin_country":"Тюркская традиция","original_year":"","source_url":"https://en.wikipedia.org/wiki/Ahmad_Yasawi","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1166.","music_adaptations":[],"source_synopsis":"Хикмет о старости: поэт говорит, что постарел, как лис, — хитрость была его дорогой, и теперь, в шестьдесят три года, он уходит в подземную келью и считает жизнь честно.","main_image":"подземная келья в шестьдесят три"},{"title":"Мир — гостиница","full_story":"Двадцать лет он живёт по отелям и конференциям: чемодан всегда собран, домашние праздники он пропускает со словами «сейчас важнее проект». В чужом отеле на чужом дне рождения он вдруг видит, что все номера одинаковы, — и не помнит, какого цвета стены у его квартиры. Он оставляет чемодан в номере, отсылает семью голосовое с одним вопросом — что приготовить к ужину, — и впервые за годы спрашивает не о проекте.","hero_pov":"профессиональный жилец отелей","central_conflict":"чемодан, всегда собранный, против дома, который ждёт","emotional_arc":"от бесконечного транзита к выбору одного адреса","ending_direction":"чемодан остаётся в номере — он спрашивает, что приготовить к ужину","hook_direction":"мир лишь гостиница","genres":["Электропоп","Поп"],"moods":["Тепло","Надежда"],"energy":"Высокая","themes":["Город","Семья"],"generator_brief":"Дорожный электропоп: чемоданные колёса в ритме, объявление рейса сэмплом, голос семьи в припеве спрашивает про ужин — и бит становится домашним.","generator_story":"Двадцать лет живя по отелям, мужчина на чужом дне рождения понимает, что не помнит цвета стен своей квартиры. Он оставляет чемодан и впервые за годы спрашивает семью, что приготовить к ужину.","primary_genre":"Электропоп","primary_mood":"Тепло","primary_theme":"Город","story_shelf":"Юмор: семейные драмы","conflict_key":"чемодан-против-дома-который-ждёт","image_key":"номер-как-все-номера","turn_key":"чемодан-остался-в-номере","hook_key":"мир-лишь-гостиница","sort_order":"1250","original_key":"yasawi|world-as-inn","author_name":"Ахмед Ясави","original_title":"хикмет «Этот мир — гостиница»","original_language":"Turkic","origin_country":"Тюркская традиция","original_year":"","source_url":"https://en.wikipedia.org/wiki/Ahmad_Yasawi","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1166.","music_adaptations":[],"source_synopsis":"Хикмет о бренности: этот мир — временный приют, гостиница; тот, кто гонится за наживой, теряет главное, и готовиться нужно не к следующему номеру, а к дому.","main_image":"номер отеля, где все номера одинаковые"},{"title":"Внутри горы","full_story":"Он работает в компании восемь лет, сидит на тридцатом этаже и знает всё: процессы, интриги, бюджеты. Но каждый раз, когда улица спрашивает его о компании на встречах, он ловит себя: с каждого этажа и каждого квартала она выглядит по-разному, и целого он никогда не видел. Он берёт отгул, спускается на улицу и обходит здание пешком — с базара, с моста, из парка, — и впервые пишет правдивый пост о том, где он всё это время жил: внутри горы.","hero_pov":"человек, который восемь лет жил внутри горы","central_conflict":"вид изнутри против вида со стороны","emotional_arc":"от уверенности всевидящего к честному признанию слепоты","ending_direction":"обход здания пешком — первый правдивый пост","hook_direction":"чтобы увидеть — выйди","genres":["Техно","Инди-поп"],"moods":["Уверенность","Мечтательность"],"energy":"Высокая","themes":["Город","Выбор"],"generator_brief":"Стеклянное минималь-техно: эхо этажей в пэдах, шаги по периметру здания в ритме, уверенный вокал, который к финалу становится простым и уличным.","generator_story":"Восемь лет на тридцатом этаже не дали ему увидеть компанию целиком: с каждого квартала она выглядит по-разному. Он обходит здание пешком — с базара, с моста, из парка — и впервые пишет правдивый пост.","primary_genre":"Техно","primary_mood":"Уверенность","primary_theme":"Город","story_shelf":"Юмор: семейные драмы","conflict_key":"внутри-дела-против-вида-со-стороны","image_key":"башня-с-улицы-и-с-тридцатого","turn_key":"впервые-видит-башню-целиком","hook_key":"чтобы-увидеть-выйди","sort_order":"1251","original_key":"su-shi|ti-xi-lin-bi","author_name":"Су Ши","original_title":"题西林壁 (Надпись на стене Западного леса)","original_language":"Chinese","origin_country":"Китай","original_year":"1084","source_url":"https://en.wikipedia.org/wiki/Su_Shi","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1101.","music_adaptations":[],"source_synopsis":"Смотрю на гору с одного края — она хребет; смотрю с другого — вершина; с разных сторон — разные картины. Настоящего лица горы не узнать, потому что я сам внутри этой горы.","main_image":"башня с улицы и с тридцатого этажа"},{"title":"Цветок на самый конец осени","full_story":"В вымершем поле, где все цветы осыпались, он находит единственный синий цветок — горечавка распустилась под самыми заморозками, будто ей никто не сказал, что время прошло. Он стоит над ней и просит у неё не жизни, а манеры: расцветать в свой последний час так же спокойно. Пусть его последняя надежда будет как этот цветок — не паниковать перед уходом, а раскрыться к небу. Песня о том, что позднее цветение — самое честное.","hero_pov":"человек, который учится у цветка уходить","central_conflict":"поздний цветок и ранний страх","emotional_arc":"от осеннего замирания к спокойному цветению наперекор заморозкам","ending_direction":"расцвести в свой последний час — и уйти с открытым сердцем","hook_direction":"расцветаю — и ухожу","genres":["Соул","Классика"],"moods":["Вдохновение","Надежда"],"energy":"Низкая","themes":["расставание","Природа"],"generator_brief":"Тихий соул с одним роялем и тёплой струнной: куплеты — поздняя осень, припев распускается, как цветок, — светлый и несуетливый.","generator_story":"В вымершем осеннем поле герой находит синюю горечавку, распустившуюся под заморозками, будто не знавшую, что время прошло. Он просит у цветка манеры: расцветать в последний час спокойно, не паникуя.","primary_genre":"Соул","primary_mood":"Вдохновение","primary_theme":"расставание","story_shelf":"Трагические истории","conflict_key":"поздний-цветок-и-ранний-страх","image_key":"синяя-горечавка-под-заморозками","turn_key":"расцвести-в-свой-последний-час","hook_key":"расцветаю-и-ухожу","sort_order":"1252","original_key":"william-cullen-bryant|the-fringed-gentian","author_name":"Уильям Каллен Брайант","original_title":"To the Fringed Gentian","original_language":"English","origin_country":"США","original_year":"1832","source_url":"https://www.gutenberg.org/files/29700/29700-h/29700-h.htm","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1878.","music_adaptations":[],"source_synopsis":"Поздней осенью поэт встречает в поле цветок бахромчатой горечавки — единственный цветок, распустившийся, когда все остальные давно осыпались. Он молится о такой же кончине: чтобы сердце в последний час расцветало надеждой, глядя в небо, когда пора уходить.","main_image":"синяя горечавка, распустившаяся под первыми заморозками"},{"title":"Певец по имени Роберт","full_story":"Он прилетает в поле и с утра до вечера поёт своё имя на каждом суку — не для кого-то, а потому что песня у него одна и она хорошая. Весь луг отвечает ему летним теплом, и никто не просит его замолчать или петь по нотам. Осень срывает с полей золотые листья, и Роберт улетает петь в другое небо. Песня о том, что своё имя стоит петь громко, пока длится лето.","hero_pov":"птица-певец от первого лица","central_conflict":"песня как паспорт птицы","emotional_arc":"от беззастенчивой гордости пением к лёгкому прощанию с полем","ending_direction":"осень забирает певца на юг — поля помнят его мотив","hook_direction":"спой своё имя","genres":["Кантри","Фолк"],"moods":["Радость","Тепло"],"energy":"Высокая","themes":["сцена","природа"],"generator_brief":"Звонкое кантри со свистом и пересвистами в бридже: куплеты — птичья гордость в движении, припев — имя, пропетое три раза подряд.","generator_story":"Певчая птица Роберт с утра до вечера поёт своё имя на каждом суку — песня у него одна, и она хорошая. Осень срывает золотые листья, и он улетает петь в другое небо, оставляя лугу свой мотив.","primary_genre":"Кантри","primary_mood":"Радость","primary_theme":"сцена","story_shelf":"Люди и животные","conflict_key":"песня-как-паспорт-птицы","image_key":"птица-поющая-своё-имя","turn_key":"осень-забирает-певца-на-юг","hook_key":"спой-своё-имя","sort_order":"1253","original_key":"william-cullen-bryant|robert-of-lincoln","author_name":"Уильям Каллен Брайант","original_title":"Robert of Lincoln","original_language":"English","origin_country":"США","original_year":"1843","source_url":"https://www.gutenberg.org/files/29700/29700-h/29700-h.htm","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1878.","music_adaptations":[],"source_synopsis":"Весёлая песня от лица трупиала Роберта из Линкольна: он весь день поёт собственное имя и выдуманный мотив, гордится своим пением, а в конце лета — улетает на юг, оставляя поля пустыми.","main_image":"птица, поющая своё имя на каждом суку"},{"title":"Песня Чаттахучи","full_story":"Долины держат её за берега и просят остаться: холмы любили её так долго. Река отвечает им одной и той же песней на каждом изгибе: мой долг — бежать, разбиваться о пороги и добежать до моря. Она уходит из родных холмов не потому, что перестала их любить, — а потому что любовь без пути была бы стоячей водой. Песня о том, что у некоторых есть долг — течь до конца.","hero_pov":"река, говорящая с холмами","central_conflict":"долина просит реку остаться","emotional_arc":"от упрёка родных берегов к ясному долгу, проговорённому песней","ending_direction":"добежать до моря — пусть холмы хранят её песню","hook_direction":"беги, река, беги","genres":["R&B","Фолк"],"moods":["Драйв","Решимость"],"energy":"Высокая","themes":["расставание","Дорога"],"generator_brief":"Бегущий R&B с водным ритмом и речным басом: куплеты — изгибы и упрёки берегов, припев — поток без остановки, к морю.","generator_story":"Родные холмы просят реку остаться — они так долго её любили. Но река отвечает одной песней: её долг — бежать, разбиваться о пороги и добежать до моря, ведь любовь без пути была бы стоячей водой.","primary_genre":"R&B","primary_mood":"Драйв","primary_theme":"расставание","story_shelf":"Трагические истории","conflict_key":"долина-просит-реку-остаться","image_key":"река-отвечает-песней-из-холмов","turn_key":"мой-долг-добежать-до-моря","hook_key":"беги-река-беги","sort_order":"1254","original_key":"sidney-lanier|the-song-of-the-chattahoochee","author_name":"Сидни Ланье","original_title":"The Song of the Chattahoochee","original_language":"English","origin_country":"США","original_year":"1877","source_url":"https://en.wikisource.org/wiki/The_Song_of_the_Chattahoochee","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1881.","music_adaptations":[],"source_synopsis":"Река Чаттахучи отвечает долинам Хабершо и Холл, которые упрекают её за спешку: она оставляет холмы, которые любит, потому что у неё долг — бежать через ущелья и приплыть к морю.","main_image":"река, отвечающая упрекающим холмам своей песней"},{"title":"Оркестр против торговли","full_story":"Оркестр выходит на сцену города, где всё куплено, и каждый инструмент берёт слово: струны говорят о любви, которую стали считать товаром, медь — о золоте, которое заглушает голоса бедных. Флейта называет имена тех, кого торговля посчитала расходом. В финале скрипки говорят за всех: времени не хватает сердца — мы всё за любовь. Песня о том, что когда город теряет сердце, кто-то должен играть вместо него.","hero_pov":"оркестр, заговоривший с городом","central_conflict":"торговля голодает без сердца","emotional_arc":"от перечня городских ран к общему музыкальному приговору и утешению","ending_direction":"музыка отвечает городу тем, чего он лишился, — сердцем","hook_direction":"нам не хватает сердца","genres":["Джаз","Эпик-рок"],"moods":["Злость","Надежда"],"energy":"Высокая","themes":["город","музыка"],"generator_brief":"Большой джаз-оркестр: медь кричит о городе, флейта шепчет про бедных, припев собирается в широкий струнный аккорд, который громче денег.","generator_story":"В городе, где всё куплено, оркестр выходит на сцену: струны — о любви, ставшей товаром, медь — о глушащем бедных золоте, флейта — имена списанных в расход. Скрипки говорят за всех: мы всё за любовь.","primary_genre":"Джаз","primary_mood":"Злость","primary_theme":"город","story_shelf":"Трагические истории","conflict_key":"торговля-голодает-без-сердца","image_key":"оркестр-отвечает-городу","turn_key":"скрипки-сказали-мы-за-любовь","hook_key":"нам-не-хватает-сердца","sort_order":"1255","original_key":"sidney-lanier|the-symphony","author_name":"Сидни Ланье","original_title":"The Symphony","original_language":"English","origin_country":"США","original_year":"1875","source_url":"https://en.wikisource.org/wiki/The_Symphony","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1881.","music_adaptations":[],"source_synopsis":"Каждый инструмент оркестра говорит о социальной боли времени: струны о любви, медь о торговле и золоте, флейта о бедных. В финале скрипки выносят приговор времени, у которого не хватает сердца, — и музыка отвечает городу тем, чего ему не хватает.","main_image":"оркестр, отвечающий городу без сердца"},{"title":"Марши у Глинна","full_story":"Он возвращается на свои марши — к травяной полосе между морем и землёй, где небо огромное, а суете нет места. Полдень выжигает тени, вечер приносит прибой и золотые купола трав, ночь зажигает над болотами звёзды, как свечи. Он не ищет здесь ответов — здесь сам простор отвечает за него. Песня о возвращении в место, где мир становится домом и собором сразу.","hero_pov":"человек, вернувшийся в свой собор из травы","central_conflict":"солнце и прилив спорят за марши","emotional_arc":"от усталой дороги к огромному покою, который отвечает без слов","ending_direction":"между морем и землёй есть его дом — и он вернулся","hook_direction":"широкие марши зовут","genres":["Соул","Эмбиент"],"moods":["Спокойствие","Вдохновение"],"energy":"Низкая","themes":["Возвращение","Природа"],"generator_brief":"Широкий соул с прибоем в подложке: куплеты — полдень, вечер, ночь на маршах, припев — как небо, которое наконец распахнуто над головой.","generator_story":"Мужчина возвращается на марши — травяную полосу между морем и землёй: вечер приносит прибой и золотые травы, ночь зажигает звёзды, как свечи. Он не ищет ответов — простор отвечает за него.","primary_genre":"Соул","primary_mood":"Спокойствие","primary_theme":"Возвращение","story_shelf":"Трагические истории","conflict_key":"солнце-и-прилив-спорят-за-марши","image_key":"освещённые-марши-как-собор","turn_key":"меж-морем-и-землёй-есть-мой-дом","hook_key":"широкие-марши-зовут","sort_order":"1256","original_key":"sidney-lanier|the-marshes-of-glynn","author_name":"Сидни Ланье","original_title":"The Marshes of Glynn","original_language":"English","origin_country":"США","original_year":"1878","source_url":"https://en.wikisource.org/wiki/The_Marshes_of_Glynn","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1881.","music_adaptations":[],"source_synopsis":"Поэт приходит на широкие марши Глинна — к полосе трав между морем и землёй — и проживает с ними день: свет полудня, вечерний прибой, ночь со звёздами. Марши становятся для него собором, в котором он примиряется с жизнью и смертью.","main_image":"освещённые закатом марши как открытый собор"},{"title":"Отдайте корабль морю","full_story":"Приказ подписан: старый корабль, чьи доски помнят настоящие залпы, пойдёт на слом — как ненужное железо. Поэт встаёт у причала и кричит против бумаг: не трогайте её рваный флаг, не отдавайте гордость на растасовку чужим рукам. Лучше пусть она уйдёт в море со всей своей славой — под грозу, под волны, как воин, а не как хлам. Песня о том, что старую славу нельзя сдавать в утиль — её нужно вернуть её стихии.","hero_pov":"человек, протестующий против слома корабля","central_conflict":"списать корабль или вернуть морю","emotional_arc":"от бумажного приговора к крику, который вернул корабль морю","ending_direction":"корабль остаётся в море — слом отменён людским голосом","hook_direction":"не отдавайте её на слом","genres":["Эпик-рок","Метал"],"moods":["Смелость","Уверенность"],"energy":"Высокая","themes":["Возвращение","память"],"generator_brief":"Тяжёлый эпик-рок с боевым барабаном и медью: куплеты — бумажный приказ и причал, припев — крик, который громче ведомостей и волн.","generator_story":"Старый корабль, чьи доски помнят настоящие залпы, приговорён к слому — поэт встаёт у причала против бумаг. Лучше вернуть гордость морю под грозу, как воина: людской голос отменяет слом.","primary_genre":"Эпик-рок","primary_mood":"Смелость","primary_theme":"Возвращение","story_shelf":"Трагические истории","conflict_key":"списать-корабль-или-вернуть-морю","image_key":"рваный-флаг-над-старым-кораблём","turn_key":"лучше-уйти-в-море-чем-на-слом","hook_key":"не-отдавайте-её-на-слом","sort_order":"1257","original_key":"oliver-wendell-holmes|old-ironsides","author_name":"Оливер Уэнделл Холмс","original_title":"Old Ironsides","original_language":"English","origin_country":"США","original_year":"1830","source_url":"https://en.wikisource.org/wiki/Old_Ironsides","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1894.","music_adaptations":[],"source_synopsis":"Старый боевой корабль «Конститьюшн» собираются списать на слом, и поэт протестует: сорвите её рваный флаг — и лучше пусть она уйдёт под волны с грозой Господней, чем её растащат чужие руки. Стихотворение спасло корабль от разборки.","main_image":"рваный флаг над старым боевым кораблём"},{"title":"Строй палаты шире","full_story":"Выловленный наутилус лежит на столе разбитым, и по его спирали видно всю его жизнь: камера за камерой, каждая шире прежней, и ни одну он не жалел. Из тесной он уходил в просторную без оглядки — так он рос, пока не вырос окончательно. Поэт берёт с души то же обещание: не жить в отжившей камере, строить палаты шире и уходить без вздоха. Песня о том, что тесная прошлая жизнь — не дом, а этаж.","hero_pov":"человек, услышавший урок разбитой раковины","central_conflict":"перерасти свои стены","emotional_arc":"от тоски по тесному к решимости строить просторное","ending_direction":"оставить тесную камеру — и строить дворцы пошире","hook_direction":"строй себе дворцы попросторнее","genres":["R&B","Классика"],"moods":["Решимость","Мечтательность"],"energy":"Низкая","themes":["расставание","Время"],"generator_brief":"Глубокий R&B с морским гулом и медленным подъёмом: куплеты — камеры спирали, припев — просторный аккорд, в котором слышен океан.","generator_story":"Разбитый наутилус показывает всю жизнь: камера за камерой, каждая шире прежней. Поэт берёт с раковины обещание: не жить в отжившей камере, а строить палаты шире и уходить без вздоха.","primary_genre":"R&B","primary_mood":"Решимость","primary_theme":"расставание","story_shelf":"Трагические истории","conflict_key":"перерасти-свои-стены","image_key":"наутилус-строит-новую-камеру","turn_key":"оставь-тесную-камеру-построй-просторнее","hook_key":"строй-себе-дворцы-попросторнее","sort_order":"1258","original_key":"oliver-wendell-holmes|the-chambered-nautilus","author_name":"Оливер Уэнделл Холмс","original_title":"The Chambered Nautilus","original_language":"English","origin_country":"США","original_year":"1858","source_url":"https://en.wikisource.org/wiki/The_Chambered_Nautilus","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1894.","music_adaptations":[],"source_synopsis":"Разбитый раковинный наутилус рассказывает свою жизнь: он строил всё более широкие камеры и из каждой перебирался в новую, покидая прежнюю. Поэт берёт с души урок — строить себе всё более просторные палаты и оставлять тесные.","main_image":"спиральная раковина наутилуса с камерами-этажами"},{"title":"Зов по долинам","full_story":"Зов летит через горы и долины, и каждый слышит его по-своему: лесник бросает топор, пастух оставляет стадо, кузнец гасит горн. Никого не заставляют — просто зов доходит, и каждый встанет, потому что дома — за его спиной. Песня о кличе, который собирает разбросанных людей в один ряд: эй, кто в долине, кто на холме — пора.","hero_pov":"голос зова, летящего через горы","central_conflict":"зов через долины и холмы","emotional_arc":"от мирного труда к общему отклику на один клич","ending_direction":"вся долина встала по зову — ряды сомкнулись","hook_direction":"встаём по зову","genres":["Панк","Эпик-рок"],"moods":["Смелость","Драйв"],"energy":"Взрывная","themes":["Дружба","смелость"],"generator_brief":"Клич-панк с военным барабаном и хором: куплеты — перекличка долин и профессий, припев — общий отклик, как один шаг целой земли.","generator_story":"Один зов летит через горы и долины, и каждый откликается по-своему: лесник бросает топор, пастух оставляет стадо, кузнец гасит горн. Никого не заставляют — дома за спиной, и вся долина встаёт в ряд.","primary_genre":"Панк","primary_mood":"Смелость","primary_theme":"Дружба","story_shelf":"Трагические истории","conflict_key":"зов-через-долины-и-холмы","image_key":"лесник-бросает-топор","turn_key":"вся-долина-встаёт-по-зову","hook_key":"встаём-по-зову","sort_order":"1259","original_key":"henry-timrod|a-cry-to-arms","author_name":"Генри Тимрод","original_title":"A Cry to Arms","original_language":"English","origin_country":"США","original_year":"1861","source_url":"https://docsouth.unc.edu/southlit/timrod/timrod.html","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1867.","music_adaptations":[],"source_synopsis":"Ратный клич: эй, лесники горных склонов, эй, жители долин — зов летит через горы и реки, и вся земля встаёт по одному слову. Поэт кличет каждого — от кузнеца до поселенца — откликнуться и встать в ряды.","main_image":"лесник, бросающий топор по зову"},{"title":"Безымянные","full_story":"Дождь стучит по подоконнику, а за окном — ряд холмиков, под которыми лежат солдаты без имён: не их дома, не их семьи, никто не знает, кого оплакивать. Он не может вернуть им адреса и голоса — но может дать то, что дают незнакомцам: цветы, ухоженную траву и память, которая не требует имени. Песня о примирении с утратой, у которой нет даже фамилии.","hero_pov":"житель, живущий рядом с безымянными могилами","central_conflict":"дождь по подоконнику и безымянные могилы","emotional_arc":"от бессильного горя к тихому долгу перед незнакомыми","ending_direction":"цветы помнят тех, чьих имён никто не знает","hook_direction":"мы помним, не зная имени","genres":["Блюз","Соул"],"moods":["Светлая грусть","Благородство"],"energy":"Низкая","themes":["примирение","Память"],"generator_brief":"Дождливый блюз с дальним хором: куплеты — стук капель и перечисление того, чего у мёртвых нет, припев — цветы, положенные без имён.","generator_story":"За окном тянется ряд холмиков — солдаты без имён, и никто не знает, кого оплакивать. Житель рядом не вернёт им адреса, но приносит цветы и ухоженную траву — память, которой не нужна фамилия.","primary_genre":"Блюз","primary_mood":"Светлая грусть","primary_theme":"примирение","story_shelf":"Трагические истории","conflict_key":"дождь-по-подоконнику-и-безымянные-могилы","image_key":"могилы-без-имён-под-дождём","turn_key":"цветы-помнят-тех-кого-не-знаем","hook_key":"мы-помним-не-зная-имени","sort_order":"1260","original_key":"henry-timrod|the-unknown-dead","author_name":"Генри Тимрод","original_title":"The Unknown Dead","original_language":"English","origin_country":"США","original_year":"","source_url":"https://docsouth.unc.edu/southlit/timrod/timrod.html","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1867.","music_adaptations":[],"source_synopsis":"Дождь стучит по подоконнику, а под холмом лежат солдаты без имён: никто не знает их лиц, никто не пришёл по их адресам. Поэт обещает им то, что могут дать живые незнакомцам, — цветы, траву и память без имени.","main_image":"могилы без имён под осенним дождём"},{"title":"Первый снег в Мальдене","full_story":"Первый снег года идёт с самого заката: сосны надели горностай, поля побелели, и дочь на его коленях хлопает в ладоши. Он знает, что снег укрывает и один маленький холмик — там, где его Мейбл. Никто не произносит имени, но снег ложится и на неё, мягко, как прощение. Песня о горе, которое впервые начинает отпуска — под белым, тихим, равным для всех снегом.","hero_pov":"отец у окна с дочерью на коленях","central_conflict":"первый снег и детская могила","emotional_arc":"от безмолвного горя к тихому прощению под снегом","ending_direction":"снег укрывает всех одинаково — и боль впервые мягче","hook_direction":"пусть снег укроет боль","genres":["Соул","Классика"],"moods":["Нежность","Светлая грусть"],"energy":"Низкая","themes":["расставание","семья"],"generator_brief":"Очень тихий соул со снежным шёпотом в подложке: куплеты — окно и падающие хлопья, припев — мягкий, почти колыбельный, для всех сразу.","generator_story":"Первый снег идёт с заката: дочь на коленях у отца хлопает в ладоши, а он знает — снег укрывает и маленький холмик, где его Мейбл. Снег ложится и на неё, мягко, как прощение.","primary_genre":"Соул","primary_mood":"Нежность","primary_theme":"расставание","story_shelf":"Трагические истории","conflict_key":"первый-снег-и-детская-могила","image_key":"снег-мягко-ложится-на-холмик","turn_key":"снег-говорит-тише-всех-слов","hook_key":"пусть-снег-укроет-боль","sort_order":"1261","original_key":"james-russell-lowell|the-first-snowfall","author_name":"Джеймс Расселл Лоуэлл","original_title":"The First Snowfall","original_language":"English","origin_country":"США","original_year":"1847","source_url":"https://en.wikisource.org/wiki/The_First_Snowfall","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1891.","music_adaptations":[],"source_synopsis":"Отец смотрит с дочерью на первый снег года: он укрывает сосны, поля и — тихо, без названия — могилу его маленькой Мейбл. Снег говорит о прощении мягче всех слов, и горе на глазах становится тише.","main_image":"снег, мягко ложащийся на маленький холмик"},{"title":"Нищий у ворот","full_story":"Рыцарь собирается искать Грааль — драгоценную чашу в дальних странах, — а у его собственных ворот сидит нищий, просящий воды. По привычке величия он бросает ему золото, но тот не поднимает глаз: ему нужен хлеб. Рыцарь ломает свой ломоть, протягивает — и в грязном лице вдруг узнаёт то, ради чего ехал через мир. Песня о том, что святыня живёт не в чаше, а в том, чем ты поделился у своих ворот.","hero_pov":"рыцарь, вернувшийся взглядом к своим воротам","central_conflict":"золото против ломтя хлеба","emotional_arc":"от гордого поиска святыни к узнаванию её в нищем у порога","ending_direction":"король глядит из нищего — делишься тем, чем жив","hook_direction":"поделись — и увидишь","genres":["R&B","Фолк"],"moods":["Благородство","Радость"],"energy":"Высокая","themes":["примирение","верность"],"generator_brief":"Светлый R&B с хором и горном: куплеты — гордый сбор в путь, припев — простой ломоть хлеба, который оказывается больше всей славы.","generator_story":"Рыцарь собирается за дальним Граалем, а у его ворот нищий просит воды. Он бросает золото, но нищему нужен хлеб — и, протянув свой ломоть, рыцарь в грязном лице узнаёт то, ради чего ехал через мир.","primary_genre":"R&B","primary_mood":"Благородство","primary_theme":"примирение","story_shelf":"Трагические истории","conflict_key":"золото-против-ломтя-хлеба","image_key":"нищий-у-ворот-замка","turn_key":"король-глядит-из-нищего","hook_key":"поделись-и-увидишь","sort_order":"1262","original_key":"james-russell-lowell|the-vision-of-sir-launfal","author_name":"Джеймс Расселл Лоуэлл","original_title":"The Vision of Sir Launfal","original_language":"English","origin_country":"США","original_year":"1848","source_url":"https://poets.org/poem/vision-sir-launfal","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1891.","music_adaptations":[],"source_synopsis":"Гордый рыцарь Сэр Лонфаль ищет Святой Грааль и на пороге своего замка бросает золото нищему, который просит хоть капли воды. Протянув ему хлеб, он видит в нищем самого Христа — и понимает, что святая вечеря живёт в том, чем делишься с чужой нуждой.","main_image":"нищий у ворот замка и ломоть хлеба в рыцарской руке"},{"title":"Травля барсука","full_story":"В полночь выходит свора: собак и людей — выследить барсука, вытащить его из норы мешком и привезти в деревню на потеху. Весь день он дерётся — отчаянно и без злобы, как умеют только загнанные, — и весь день круг смеётся, подначивает и травит дальше. Кто-то в этом кругу молчит и не находит в себе голоса сказать «хватит» — и это молчание хуже собак. Песня о вине того, кто стоял рядом и промолчал.","hero_pov":"житель толпы, который молчал","central_conflict":"толпа травит — и никто не молвил","emotional_arc":"от обычного зрелища к омертвению и вине молчавшего","ending_direction":"молчание толпы хуже собак — больше не буду стоять в кругу","hook_direction":"я стоял и молчал","genres":["Метал","Панк"],"moods":["Вина","Злость"],"energy":"Взрывная","themes":["сцена","животные"],"generator_brief":"Дико-тяжёлый метал с хором толпы: куплеты — суета своры и смеха, припев — одинокий голос вины, который звучит тише всех.","generator_story":"В полночь свора выкуривает барсука из норы, и весь день он дерётся отчаянно и без злобы, пока круг смеётся. Один в этом кругу молчит и не находит голоса крикнуть «хватит» — и его молчание хуже собак.","primary_genre":"Метал","primary_mood":"Вина","primary_theme":"сцена","story_shelf":"Люди и животные","conflict_key":"толпа-травит-и-никто-не-молвил","image_key":"барсук-в-мешке-среди-собак","turn_key":"молчание-толпы-хуже-собак","hook_key":"я-стоял-и-молчал","sort_order":"1263","original_key":"john-clare|the-badger","author_name":"Джон Клэр","original_title":"The Badger","original_language":"English","origin_country":"Великобритания","original_year":"1821","source_url":"https://www.poeticous.com/john-clare/badger","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1864.","music_adaptations":[],"source_synopsis":"Ночью толпа собак и людей выслеживает барсука до норы, вытаскивает его мешком и приносит в деревню — и весь день травит его забавы ради. Барсук дерётся отчаянно и добродушно, пока не падает; поэт стоит в толпе и не находит в себе голоса сказать «хватит».","main_image":"барсук в мешке среди собак и круга людей"},{"title":"Соловьиное гнездо","full_story":"Он ведёт друга той самой тропой, где знает каждый куст, и просит идти тише: здесь, в ежевике, у соловья гнездо. Весь концерт мира сидит в этой колючей тени — и малейший шаг его оборвёт. Они стоят не дыша, и песня, зная, что её не выдадут, идёт по кругу, как вода. Песня о том, что тайное счастье живёт, пока его охраняют молчанием.","hero_pov":"проводник к тайному гнезду","central_conflict":"найти гнездо и не выдать","emotional_arc":"от тихой охоты за песней к благоговению и молчаливой охране","ending_direction":"знать — и молчать, чтобы песня продолжалась","hook_direction":"тише — она поёт","genres":["Джаз","Фолк"],"moods":["Нежность","Мечтательность"],"energy":"Низкая","themes":["Сцена","природа"],"generator_brief":"Тихий джаз с щётками и дальним соловьиным свистом: куплеты — шаги по лесу, всё тише, припев — почти беззвучный, как выдох в ежевику.","generator_story":"Проводник ведёт друга той самой тропой и просит идти тише: в ежевике у соловья гнездо — весь концерт мира в этой колючей тени. Они стоят не дыша, и тайное счастье живёт, пока его охраняют молчанием.","primary_genre":"Джаз","primary_mood":"Нежность","primary_theme":"Сцена","story_shelf":"Люди и животные","conflict_key":"найти-гнездо-и-не-выдать","image_key":"соловей-поёт-в-терновнике","turn_key":"знать-и-молчать-ради-песни","hook_key":"тише-она-поёт","sort_order":"1264","original_key":"john-clare|the-nightingales-nest","author_name":"Джон Клэр","original_title":"The Nightingale's Nest","original_language":"English","origin_country":"Великобритания","original_year":"","source_url":"https://en.wikisource.org/wiki/The_Nightingale%27s_Nest","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1864.","music_adaptations":[],"source_synopsis":"Поэт идёт по знакомому лесу искать соловьиное гнездо: он знает каждое дерево, находит укромное место в ежевике, где поёт птица, — и просит спутника идти тише и не дышать громко, чтобы не выдать тайну песни.","main_image":"соловей, поющий в скрытом гнезде в ежевике"},{"title":"Старый Граймс","full_story":"Пристань помнит всё: сколько учеников ушло с Граймсом в море и сколько вернулось без него. Город шепчется за спиной, но стучится в его дверь только за рыбой, и он молчит так же, как молчало море. Однажды он остаётся совсем один — без мальчишек, без доводов, с лодкой и собой. Песня о человеке, которого города хватило наказать одним только поворотом спины.","hero_pov":"рыбак, которого город отвернулся","central_conflict":"пристань знает все его грехи","emotional_arc":"от глухой упрямости к одному на одного с молчанием города","ending_direction":"город отвернулся — и он замолчал навсегда","hook_direction":"море всё считает","genres":["Блюз","Метал"],"moods":["Одиночество","Вина"],"energy":"Низкая","themes":["город","память"],"generator_brief":"Тяжёлый сырой блюз с гулом волн: куплеты — шёпот пристани и стук его двери, припев — морской счёт, который никому не перепроверить.","generator_story":"Пристань помнит, сколько учеников ушло с Граймсом в море и сколько вернулось без него. Город шепчется за спиной, но стучится лишь за рыбой — и однажды старик остаётся совсем один, с лодкой и собой.","primary_genre":"Блюз","primary_mood":"Одиночество","primary_theme":"город","story_shelf":"Трагические истории","conflict_key":"пристань-знает-все-его-грехи","image_key":"одинокая-лодка-без-ученика","turn_key":"город-отвернулся-и-он-замолчал","hook_key":"море-всё-считает","sort_order":"1265","original_key":"george-crabbe|the-borough-peter-grimes","author_name":"Джордж Краббе","original_title":"The Borough (Peter Grimes)","original_language":"English","origin_country":"Великобритания","original_year":"1810","source_url":"https://en.wikisource.org/wiki/The_Borough","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1832.","music_adaptations":[],"source_synopsis":"История рыбака Питера Граймса из портового городка: его ученики один за другим погибают в море при его жестокости, город шепчется, но не трогает его, и он остаётся один — с лодкой, молчанием и всей своей правдой о себе.","main_image":"одинокая лодка без ученика у ночного причала"},{"title":"Мамина рама","full_story":"Почта приносит ему портрет матери, умершей, когда он был ребёнком, — и рамка распахивается, как дверь в старую кухню. Оттуда идёт всё сразу: её голос у колыбели, руки, которые никогда не торопились, вечер, когда она читала молитву. Он хочет поцеловать раму, как её ладони, но пальцы встречают только прохладу холста. Песня о возвращении домой, где дом стал картиной.","hero_pov":"сын перед портретом матери","central_conflict":"портрет открывает старую кухню","emotional_arc":"от нежного узнавания к тёплой боли прикосновения к холсту","ending_direction":"дом вернулся на одно прикосновение — и остался в раме","hook_direction":"мама, я вспомнил всё","genres":["Соул","Баллада"],"moods":["Тепло","Светлая грусть"],"energy":"Низкая","themes":["Возвращение","семья"],"generator_brief":"Тёплый соул с домашним фортепиано: куплеты — распахнутая кухня детства, припев — прикосновение к холодному холсту и мягкий выдох.","generator_story":"Почта приносит сыну портрет матери, умершей в его детстве, — рамка распахивается, как дверь в старую кухню. Он хочет поцеловать её, как мамины ладони, но пальцы встречают только прохладу холста.","primary_genre":"Соул","primary_mood":"Тепло","primary_theme":"Возвращение","story_shelf":"Трагические истории","conflict_key":"портрет-открывает-старую-кухню","image_key":"мамин-портрет-на-стене","turn_key":"хочу-поцеловать-раму-как-её-руки","hook_key":"мама-я-вспомнил-всё","sort_order":"1266","original_key":"william-cowper|on-the-receipt-of-my-mothers-picture","author_name":"Уильям Каупер","original_title":"On the Receipt of My Mother's Picture","original_language":"English","origin_country":"Великобритания","original_year":"","source_url":"https://en.wikisource.org/wiki/On_the_Receipt_of_My_Mother%27s_Picture","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1800.","music_adaptations":[],"source_synopsis":"Поэту приносят портрет умершей матери, и рамка открывает ему целый мир детства: её голос, её руки, старую кухню и вечерние молитвы. Он хочет прикоснуться к картине как к её рукам — и не может ни оставить её, ни удержать прошлое.","main_image":"мамин портрет, распахнувший старую кухню"},{"title":"Надгробие Тини","full_story":"Он хоронит своего домашнего зайца и пишет ему надгробие, как человеку: ни одной гончей за всю жизнь, ни одного утра с росой на лапах. Тини оставался диким по характеру до конца — кусал за пальцы без злобы, требовал салат и боялся грозы. Восемь лет он правил ковром у камина, как своим лугом. Песня-эпитафия, в которой смех и нежность не спорят, а держатся за руки.","hero_pov":"хозяин, прощающийся с домашним зайцем","central_conflict":"эпитафия зайцу вместо плача","emotional_arc":"от шутливого перечня привычек к настоящей благодарности","ending_direction":"охотники ни разу не преследовали его — только мы его любили","hook_direction":"спи, мой заяц","genres":["Кантри","Фолк"],"moods":["Ирония","Тепло"],"energy":"Низкая","themes":["любовь","животные"],"generator_brief":"Тёплая кантри с усмешкой и мягкой скрипкой: куплеты — привычки зайца, как семейные байки, припев — искреннее надгробие, трогающее без пафоса.","generator_story":"Хозяин хоронит домашнего зайца и пишет надгробие, как человеку: ни одной гончей за всю жизнь, ни одного утра с росой на лапах. Тини кусал пальцы без злобы, требовал салат и правил ковром у камина.","primary_genre":"Кантри","primary_mood":"Ирония","primary_theme":"любовь","story_shelf":"Юмор: семейные драмы","conflict_key":"эпитафия-зайцу-вместо-плача","image_key":"домашний-заяц-у-петрушки","turn_key":"охотники-ни-разу-не-преследовали","hook_key":"спи-мой-заяц","sort_order":"1267","original_key":"william-cowper|epitaph-on-a-hare","author_name":"Уильям Каупер","original_title":"Epitaph on a Hare","original_language":"English","origin_country":"Великобритания","original_year":"","source_url":"https://www.poemhunter.com/poem/epitaph-on-a-hare/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1800.","music_adaptations":[],"source_synopsis":"Шутливо-нежная эпитафия домашнему зайцу Тини: его ни разу не преследовали гончие, он ел хлеб, молоко и листья салата, оставался диким по характеру, кусал хозяина без злобы и прожил восемь лет на ковре у камина.","main_image":"домашний заяц у петрушки на ковре у камина"},{"title":"Острова в море жизни","full_story":"Мы живём островами в бескрайнем море: голоса любимых доносятся через проливы — так близко, что слышно дыхание, и так далеко, что не достать рукой. Ночью вода поднимает между островами их же крики, и кажется, что ещё чуть-чуть — и берега сойдутся. Но между людьми стоит солёная разлучающая вода, и никто не отменит этого закона. Песня о любви, которая звучит через пролив всю ночь.","hero_pov":"человек на одном из островов жизни","central_conflict":"острова зовут друг друга через проливы","emotional_arc":"от почти слышной близости к покорности солёному закону моря","ending_direction":"любовь звучит через пролив — и этого пока хватит","hook_direction":"позови меня через море","genres":["Джаз","Синтвейв"],"moods":["Романтика","Тоска"],"energy":"Низкая","themes":["любовь","расставание"],"generator_brief":"Ночной джаз с волнами в басу и далёким вокалом: куплеты — два берега на расстоянии дыхания, припев — зов, который уносит вода.","generator_story":"Он на одном острове, она на другом: её голос доносится через пролив так близко, что слышно дыхание, и так далеко, что не достать рукой. Закон моря не отменить — и любовь звучит через пролив всю ночь.","primary_genre":"Джаз","primary_mood":"Романтика","primary_theme":"любовь","story_shelf":"Любовные сцены","conflict_key":"острова-зовут-друг-друга-через-проливы","image_key":"любовь-слышна-через-солёный-пролив","turn_key":"между-нами-чужой-море-закон","hook_key":"позови-меня-через-море","sort_order":"1268","original_key":"matthew-arnold|to-marguerite-continued","author_name":"Мэттью Арнольд","original_title":"To Marguerite: Continued","original_language":"English","origin_country":"Великобритания","original_year":"1852","source_url":"https://www.poetryfoundation.org/poems/43609/to-marguerite-continued","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1888.","music_adaptations":[],"source_synopsis":"Люди — миллионы островов в безбрежном море жизни: любовные голоса слышны через echoing проливы, но коснуться друг друга нельзя. Спрошенный, почему между ними солёная разлучающая вода, поэт отвечает: так распорядился закон жизни.","main_image":"любовь, слышная через солёный пролив между островами"},{"title":"Кукушка вместо голоса","full_story":"Он возвращается на их старые холмы, где они когда-то пели и спорили о песнях, — а друг давно уехал и умер вдали. Вяз на холме стоит, как стоял, и кукушка кричит из лета — тем самым мотивом, который у них был общим. Он решает: пусть птица поёт за него — и несёт этот голос в себе, пока может ходить по этим холмам. Песня о дружбе, которая научилась звучать через птиц.","hero_pov":"друг, бродящий по общим холмам","central_conflict":"кукушка вернулась — друг нет","emotional_arc":"от пустого холма к найденному общему мотиву в чужом голосе","ending_direction":"несу его песню в себе — кукушка поёт за двоих","hook_direction":"слышишь, кукушка — он здесь","genres":["Кантри","Фолк"],"moods":["Светлая грусть","Надежда"],"energy":"Низкая","themes":["Дружба","Память"],"generator_brief":"Простая кантри-элегия с акустикой и птичьим свистом в припеве: куплеты — холмы вдвоём и в одиночку, припев — кукушка, поющая за двоих.","generator_story":"Друг возвращается на старые холмы, где они пели и спорили о песнях, — а тот уехал и умер вдали. Кукушка кричит их общим мотивом: пусть птица поёт за двоих, пока он может ходить по этим холмам.","primary_genre":"Кантри","primary_mood":"Светлая грусть","primary_theme":"Дружба","story_shelf":"Трагические истории","conflict_key":"кукушка-вернулась-друг-нет","image_key":"вяз-у-порта-и-голос-кукушки","turn_key":"я-несу-его-голос-в-себе","hook_key":"слышишь-кукушка-он-здесь","sort_order":"1269","original_key":"matthew-arnold|thyrsis","author_name":"Мэттью Арнольд","original_title":"Thyrsis","original_language":"English","origin_country":"Великобритания","original_year":"1865","source_url":"https://en.wikisource.org/wiki/Thyrsis","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1888.","music_adaptations":[],"source_synopsis":"Элегия ушедшему другу: поэт ходит их старыми холмами, где когда-то пели вместе, и слышит кукушку — того, кто теперь поёт за двоих. Он отказывается верить, что голос друга умолк навсегда, и несёт его песню в себе.","main_image":"вяз над холмом и голос кукушки вместо друга"},{"title":"Ушёл к цыганам","full_story":"Двести лет назад студент оставил книги и город и ушёл учиться к цыганам — за знанием, которого не выдают дипломы. Город гремит внизу уже новое столетие, а пастухи всё ещё видят его на холмах: свежим, не стареющим, с одной нерешённой задачей в руках. Поэт не зовёт его назад — он просит не показываться нашему веку: тот устал и отравлен сомнением. Песня о человеке, который нашёл свою дорогу и не свернул.","hero_pov":"наблюдатель города, смотрящий на холмы","central_conflict":"город гремит — а он ушёл","emotional_arc":"от усталости городской гонки к тихой зависти прямому пути","ending_direction":"он всё ещё идёт свежим шагом — не показывайся нашему веку","hook_direction":"ищи свой ответ вдали","genres":["Кантри","Фолк"],"moods":["Освобождение","Мечтательность"],"energy":"Средняя","themes":["город","Дорога"],"generator_brief":"Свободное кантри с дальним горном: куплеты — гремящий город внизу, припев — холм, костёр и шаг, который не стареет.","generator_story":"Студент двести лет назад оставил книги и ушёл учиться к цыганам — за знанием, которого не выдают дипломы. Пастухи видят его на холмах не стареющим, и поэт не зовёт: наш век устал и отравлен сомнением.","primary_genre":"Кантри","primary_mood":"Освобождение","primary_theme":"город","story_shelf":"Трагические истории","conflict_key":"город-гремит-а-он-ушёл","image_key":"учёный-с-цыганским-костром","turn_key":"он-всё-ещё-идёт-свежим-шагом","hook_key":"ищи-свой-ответ-вдали","sort_order":"1270","original_key":"matthew-arnold|the-scholar-gipsy","author_name":"Мэттью Арнольд","original_title":"The Scholar-Gipsy","original_language":"English","origin_country":"Великобритания","original_year":"1853","source_url":"https://en.wikisource.org/wiki/The_Scholar-Gipsy","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1888.","music_adaptations":[],"source_synopsis":"Оксфордский студент давних лет устал от городской суеты, ушёл учиться к цыганам и стал легендой: пастухи до сих пор видят его на холмах — свежим, не стареющим, всё ищущим свой ответ. Поэт просит его не показываться нашему уставшему веку: тот отравлен сомнением.","main_image":"учёный с цыганским костром на холме над городом"},{"title":"Последний менестрель","full_story":"В новый блестящий зал приходит старик с арфой — последний из менестрелей, чьи песни кормили целые рода. Ему предлагают плату по нынешним ценам, и он отказывается: его песни не продаются, они вспоминаются. Он берёт струны только для тех, кто ещё помнит старую доблесть, и в его песне есть строка про человека с мёртвой душой — того, кто ни разу не сказал «это моя земля». Песня о гордости, которую не купишь.","hero_pov":"старый менестрель в чужом новом зале","central_conflict":"старик не поёт за деньги","emotional_arc":"от отказа от платы к песне, которая сильнее монет","ending_direction":"он поёт для тех, кто помнит, — и зал затихает","hook_direction":"старая песня не продаётся","genres":["Эпик-рок","Классика"],"moods":["Благородство","Решимость"],"energy":"Высокая","themes":["Сцена","Память"],"generator_brief":"Величественный эпик-рок с арфой и горном: куплеты — новый зал и старик с отказом, припев — песня, которая берёт зал молча и целиком.","generator_story":"Последний менестрель отказывается от платы: песни не продаются, они вспоминаются. Он играет для тех, кто помнит старую доблесть, — и в песне строка про человека, ни разу не сказавшего «это моя земля».","primary_genre":"Эпик-рок","primary_mood":"Благородство","primary_theme":"Сцена","story_shelf":"Трагические истории","conflict_key":"старик-не-поёт-за-деньги","image_key":"последний-менестрель-с-арфой","turn_key":"он-поёт-для-тех-кто-помнит","hook_key":"старая-песня-не-продаётся","sort_order":"1271","original_key":"walter-scott|the-lay-of-the-last-minstrel","author_name":"Вальтер Скотт","original_title":"The Lay of the Last Minstrel","original_language":"English","origin_country":"Шотландия","original_year":"1805","source_url":"https://en.wikisource.org/wiki/The_Lay_of_the_Last_Minstrel","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1832.","music_adaptations":[],"source_synopsis":"Последний старый менестрель приходит в замок герцогини и отказывается петь за современные деньги: его песня — из другого мира, про старую доблесть и древнюю родину. Знаменитый отрывок: нет человека с мёртвой душой, если он хоть раз не сказал «это моя родная земля».","main_image":"последний менестрель с арфой в чужом новом зале"},{"title":"Канун Иванова дня","full_story":"Каждый канун Иванова дня в башне гаснет свет — и к её окну приходит рыцарь, хотя она знает, что он давно из мёртвых. Их тайные встречи случались при живом бароне, и вот пришла ночь правды: призрак называет свою судьбу — он был убит рукой её мужа. Он оставляет ей на запястье клеймо-ожог, как печать их любви и её вины. Песня о любви, которая держит слово даже из-под земли.","hero_pov":"дама, встречающая мёртвого рыцаря","central_conflict":"полночные встречи в башне и тайна гостя","emotional_arc":"от запретного ожидания к правде призрака и покаянию","ending_direction":"призрак назвал убийцу — она уходит в монастырь","hook_direction":"в полночь он приходит снова","genres":["Метал","Баллада"],"moods":["Напряжение","Романтика"],"energy":"Высокая","themes":["любовь","прошлое"],"generator_brief":"Мрачный метал с балладной гитарой и полночным колоколом: куплеты — скрип двери и маяк, припев — признание призрака, ровное и страшное.","generator_story":"Каждый канун Иванова дня к окну башни приходит рыцарь, которого дама давно похоронила. Призрак называет своего убийцу — её мужа, — оставляет на её запястье клеймо-ожог, и она уходит в монастырь.","primary_genre":"Метал","primary_mood":"Напряжение","primary_theme":"любовь","story_shelf":"Трагические истории","conflict_key":"полночные-встречи-в-башне-и-тайна-гостя","image_key":"рыцарь-в-окне-башни-в-полночь","turn_key":"её-гость-давно-из-мёртвых","hook_key":"в-полночь-он-приходит-снова","sort_order":"1272","original_key":"walter-scott|the-eve-of-st-john","author_name":"Вальтер Скотт","original_title":"The Eve of St. John","original_language":"English","origin_country":"Шотландия","original_year":"","source_url":"https://www.poemhunter.com/poem/the-eve-of-st-john/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1832.","music_adaptations":[],"source_synopsis":"Готическая баллада: барон Смейлхолма узнаёт от пажа, что его жена тайно встречается с рыцарем у маяка в канун Иванова дня. Рыцарь давно убит — самим бароном, — и его призрак приходит на свидание, открывает правду и оставляет даме ожог-клеймо на запястье. Она уходит в монастырь, барон — в молчание.","main_image":"рыцарь в окне башни в полночь на маяке"},{"title":"Запри дверь, Ларистон","full_story":"Ночь, и через границу идёт рейд: запирай двери, зажги тревогу — чужие копыта уже на склоне, вдовы плачут в дверях. Но у этой земли есть свои: родня с соседних долин слышит клич и берёт холм раньше врага. Их рёв встаёт над Ларистоном, и рейд ломается о общий крик. Песня о том, что дверь держится, пока за ней — свои.","hero_pov":"голос дома, зовущий своих","central_conflict":"рейд через границу и родня скачет","emotional_arc":"от страха осаждённого дома к рёву пришедших своих","ending_direction":"наши приехали раньше врага — дверь устояла","hook_direction":"запирай дверь — мы едем раньше","genres":["Панк","Рок"],"moods":["Смелость","Напряжение"],"energy":"Взрывная","themes":["Дружба","дом"],"generator_brief":"Скачущий панк с галопом ударных и хором-кличем: куплеты — тревога осаждённого дома, припев — рёв своих на холме.","generator_story":"Ночью через границу идёт рейд: чужие копыта на склоне, вдовы плачут в дверях. Но родня с соседних долин слышит клич и берёт холм раньше врага — рёв встаёт над Ларистоном, и рейд ломается о общий крик.","primary_genre":"Панк","primary_mood":"Смелость","primary_theme":"Дружба","story_shelf":"Трагические истории","conflict_key":"рейд-через-границу-и-родня-скачет","image_key":"запри-дверь-кони-на-холме","turn_key":"наши-всё-равно-приехали","hook_key":"запирай-дверь-мы-едем-раньше","sort_order":"1273","original_key":"james-hogg|lock-the-door-lariston","author_name":"Джеймс Хогг","original_title":"Lock the Door, Lariston","original_language":"English","origin_country":"Шотландия","original_year":"","source_url":"https://genius.com/The-corries-lock-the-door-lariston-lyrics","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1835.","music_adaptations":[],"source_synopsis":"Пограничная баллада-клич: враги идут через границу на Ларистон — запирайте двери, вдовы плачут, семьи бегут. Но за холмами уже скачет родня и соседи: их клич слышен раньше вражьих копыт.","main_image":"кони родни на холме раньше вражьих копыт"},{"title":"Мокрый парус","full_story":"Мокрый парус, бегущее море, ветер, который гнёт крепкую мачту, — и корабль уходит от берега, как птица, не оглядываясь на пристань. Здесь, в солёном ветре, его песня выходит честнее всех разговоров на суше. Пусть берег зовёт уютом — у моря свой зов, и он громче. Песня о расставании, которое не грустит, потому что уезжает к своему.","hero_pov":"моряк на полном ходу","central_conflict":"берег зовёт — а парус уже наполнен","emotional_arc":"от приливной радости выхода к спокойному «море дороже»","ending_direction":"море дороже любого причала — пусть берег подождёт","hook_direction":"полный ход — и ветер в спину","genres":["Эпик-рок","Кантри"],"moods":["Эйфория","Драйв"],"energy":"Взрывная","themes":["расставание","Море"],"generator_brief":"Разгоняющийся эпик-рок с морским ветром в гитарах: куплеты — снасти и мачта, припев — полный ход, на котором смеётся вся команда.","generator_story":"Корабль уходит от пристани, как птица: ветер гнёт крепкую мачту, и в солёном ветре песня честнее разговоров на суше. Пусть берег зовёт уютом — у моря свой зов, и это расставание не грустит.","primary_genre":"Эпик-рок","primary_mood":"Эйфория","primary_theme":"расставание","story_shelf":"Любовные сцены","conflict_key":"берег-зовёт-а-парус-уже-наполнен","image_key":"мокрый-парус-и-быстрый-ветер","turn_key":"море-дороже-любого-причала","hook_key":"полный-ход-и-ветер-в-спину","sort_order":"1274","original_key":"allan-cunningham|a-wet-sheet-and-a-flowing-sea","author_name":"Аллан Каннингем","original_title":"A Wet Sheet and a Flowing Sea","original_language":"English","origin_country":"Шотландия","original_year":"","source_url":"https://digitalcommons.conncoll.edu/sheetmusic/330","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1842.","music_adaptations":[],"source_synopsis":"Морская песня радости: мокрый парус, быстрый попутный ветер, гнущийся крепкий рангоут — и корабль бежит от берега, как птица. Моряку милее такая дорога, чем любой берег: пусть ветер поёт в снастях, пока берег остаётся за кормой.","main_image":"мокрый парус и быстрый ветер за кормой"},{"title":"Домой, в свой край","full_story":"Он далеко от своего края и знает единственное слово, которое не стареет: домой, домой, домой. Даже жаворонок, говорит он, поймёт этот зов — пусть споёт его через все холмы до родной долины. Дома цветок ещё в бутоне, лист ещё на дереве — всё ждёт его возвращения, и ничто чужое его не заменит. Песня о возвращении, которое начинается с одного повторяемого слова.","hero_pov":"странник, зовущий себя домой","central_conflict":"жаворонок знает дорогу домой","emotional_arc":"от глухой тоски чужбины к живой надежде на голос жаворонка","ending_direction":"пой, жаворонок — я иду домой, в свой край","hook_direction":"домой, домой, в свой край","genres":["Кантри","Фолк"],"moods":["Тоска","Надежда"],"energy":"Средняя","themes":["Возвращение","дом"],"generator_brief":"Простая кантри с жаворонковым свистом: куплеты — даль чужбины, припев — повторяемое слово «домой», которое расцветает в припеве.","generator_story":"Странник далеко от своего края и знает одно слово, которое не стареет: домой. Он просит жаворонка спеть этот зов через холмы до родной долины, где цветок ещё в бутоне и лист ещё на дереве — всё ждёт.","primary_genre":"Кантри","primary_mood":"Тоска","primary_theme":"Возвращение","story_shelf":"Трагические истории","conflict_key":"жаворонок-знает-дорогу-домой","image_key":"жаворонок-поёт-меня-домой","turn_key":"пой-жаворонок-я-иду","hook_key":"домой-домой-в-свой-край","sort_order":"1275","original_key":"allan-cunningham|hame-hame-hame","author_name":"Аллан Каннингем","original_title":"Hame, Hame, Hame","original_language":"English","origin_country":"Шотландия","original_year":"","source_url":"https://en.wikisource.org/wiki/The_Book_of_Scottish_Song/Hame,_hame,_hame","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1842.","music_adaptations":[],"source_synopsis":"Песня тоски по дому: «домой, домой, домой, в мой родный край» — даже жаворонок поймёт его зов и споёт его домой. Цветы в бутонах и листья на деревьях зовут человека на родину, откуда его увезла жизнь.","main_image":"жаворонок, поющий странника домой"},{"title":"Вечная доброта","full_story":"Он не притворяется знающим: пусть спорят о небе богословы, а он признаёт своё «не знаю». Но через все бури и сомнения он держится одного — доброта существует, и она не обманет. Этого мало для теорий и достаточно для жизни: идти, делать доброе и не бояться последнего берега. Песня о вере без чертежей, но с твёрдым полом.","hero_pov":"человек с честным «не знаю» и твёрдым «но»","central_conflict":"сомнение и доверие доброте","emotional_arc":"от честного незнания к спокойному доводу, на котором можно стоять","ending_direction":"не зная ответов, он идёт дальше — доброта есть","hook_direction":"доброта всё-таки есть","genres":["Соул","Классика"],"moods":["Надежда","Спокойствие"],"energy":"Низкая","themes":["примирение","Поиск себя"],"generator_brief":"Спокойный соул с органом и одним честным голосом: куплеты — перечисление своего незнания, припев — тихая, несокрушимая уверенность в доброте.","generator_story":"Пусть о небе спорят богословы — он честно признаёт «не знаю». Но через все бури держится одного: доброта есть и не обманет, и этого достаточно, чтобы идти и делать доброе, не боясь последнего берега.","primary_genre":"Соул","primary_mood":"Надежда","primary_theme":"примирение","story_shelf":"Трагические истории","conflict_key":"сомнение-и-доверие-доброте","image_key":"пусть-незнаемое-будет-добрым","turn_key":"не-зная-ответа-я-доверяюсь","hook_key":"доброта-всё-таки-есть","sort_order":"1276","original_key":"john-greenleaf-whittier|the-eternal-goodness","author_name":"Джон Гринлиф Уиттьер","original_title":"The Eternal Goodness","original_language":"English","origin_country":"США","original_year":"1867","source_url":"https://en.wikisource.org/wiki/The_Eternal_Goodness","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1892.","music_adaptations":[],"source_synopsis":"Поэт честно признаёт: он не знает, что ждёт после, не видит небесных чертогов и не понимает всех путей. Но одно он знает твёрдо — вечная Доброта есть, и она сильнее его сомнений; этого достаточно, чтобы идти дальше.","main_image":"незнаемое небо над уверенной добротой"},{"title":"Ложная тревога","full_story":"Полночь, шум у плетня — и вся деревня на ногах: мужики с вилами, фонари, собаки, шёпот и общий грохот осторожных шагов через луг. Врагов нет: страх расступается, и пустой луг стоит под луной, полный вооружённых соседей. Домой возвращаются, посмеиваясь друг над другом, — но каждый знает, что придёт по первому крику снова. Песня о тревоге, которая ошиблась, а дружба — нет.","hero_pov":"один из вооружённых соседей","central_conflict":"ночная тревога оказалась пустой","emotional_arc":"от общего страха к общему смеху на обратной дороге","ending_direction":"тревога ошиблась — а деревня собралась и держится вместе","hook_direction":"пусть тревога — зато мы вместе","genres":["Кантри","Фолк"],"moods":["Радость","Ирония"],"energy":"Высокая","themes":["Дружба","семья"],"generator_brief":"Весёлое кантри с крадущимся ритмом и фонарями в аранжировке: куплеты — осторожный грохот всей деревни, припев — общий смех на обратной дороге.","generator_story":"Полночный шум поднимает деревню: мужики с вилами крадутся через луг — а врагов нет, только пустой луг под луной. Домой возвращаются, посмеиваясь друг над другом, но по первому крику придут снова.","primary_genre":"Кантри","primary_mood":"Радость","primary_theme":"Дружба","story_shelf":"Юмор: семейные драмы","conflict_key":"ночная-тревога-оказалась-пустой","image_key":"вооружённые-соседи-на-пустом-лугу","turn_key":"вся-деревня-встала-ради-страха","hook_key":"пусть-тревога-зато-мы-вместе","sort_order":"1277","original_key":"william-cowper|the-needless-alarm","author_name":"Уильям Каупер","original_title":"The Needless Alarm","original_language":"English","origin_country":"Великобритания","original_year":"1785","source_url":"https://en.wikisource.org/wiki/Poetical_Works_of_William_Cowper","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1800.","music_adaptations":[],"source_synopsis":"Комическая деревенская история: ночью слышен шум, тревога поднимает всю округу — вооружённые мужики с фонарями и вилами крадутся через поле на воров. Воры оказывается плодом страха, и вооружённая процессия возвращается, посмеиваясь, но — все вместе.","main_image":"вооружённые соседи на пустом лугу с фонарями"},{"title":"Моя Мэри","full_story":"Двадцать лет прошло с их первого знакомства: его рука дрожит над бумагой, её глаза тускнеют, и старость уже стучится к обоим. Но он перечитывает годы и не находит в своей любви ни усталости, ни убывания — она растёт вместе с ними, как дерево с домом. Пусть тело слабеет: у него есть последнее богатство, и оно не стареет. Песня о любви, которая выдержала собственное старение.","hero_pov":"стареющий мужчина к своей Мэри","central_conflict":"двадцать лет и убывающие силы","emotional_arc":"от горькой инвентаризации лет к росту любви вопреки времени","ending_direction":"тела слабеют — любовь остаётся последним и главным богатством","hook_direction":"моя Мэри","genres":["R&B","Соул"],"moods":["Любовь","Нежность"],"energy":"Низкая","themes":["любовь","Время"],"generator_brief":"Тихий R&B со старым пианино: куплеты — инвентаризация прожитых лет, припев — одно имя, пропетое как целая жизнь.","generator_story":"Двадцать лет спустя он пишет Мэри дрожащей рукой: старость стучится к обоим. Но в прожитых годах он не находит в любви ни усталости, ни убывания — она растёт с ними, как дерево с домом.","primary_genre":"R&B","primary_mood":"Любовь","primary_theme":"любовь","story_shelf":"Любовные сцены","conflict_key":"двадцать-лет-и-убывающие-силы","image_key":"её-руки-и-никнущее-перо","turn_key":"любовь-старше-наших-лет","hook_key":"моя-мэри","sort_order":"1278","original_key":"william-cowper|to-mary","author_name":"Уильям Каупер","original_title":"To Mary","original_language":"English","origin_country":"Великобритания","original_year":"1791","source_url":"https://en.wikisource.org/wiki/To_Mary","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1800.","music_adaptations":[],"source_synopsis":"Двадцать лет прошли с первой встречи, и оба уже не те: вяли его силы, тускнеют её глаза, приходит старость с её болезнями. Но любовь в нём не убывает — она растёт вместе с ними и остаётся его последним богатством.","main_image":"её руки и его никнущее перо после двадцати лет"},{"title":"За тех, кто молчал","full_story":"Город горюет о певцах: их лиры сломаны, их песни остались — есть что вспоминать и кому аплодировать посмертно. Но рядом лежат те, у кого не было ни песни, ни имени: они несли свой крест молча, без венца, и никто им не сыграл отходную красноречиво. Он решает спеть за них — за всех, кто молчал, пока жил. Песня — сцена, которую им так и не дали.","hero_pov":"голос за тех, у кого не было голоса","central_conflict":"память певцам и тишина молчавшим","emotional_arc":"от привычного горевания по знаменитым к долгу перед безгласными","ending_direction":"наша песня — сцена, которую им не дали при жизни","hook_direction":"мы споём за тех, кто молчал","genres":["Блюз","Классика"],"moods":["Грусть","Благородство"],"energy":"Низкая","themes":["Сцена","Память"],"generator_brief":"Строгий блюз с одним вокалом и тёмным органом: куплеты — сломанные лиры знаменитых, припев — тихая сцена для безымянных.","generator_story":"Город горюет о певцах — их песни остались, им аплодируют посмертно, — но рядом те, кто нёс крест молча, без песни и имени. Он решает спеть за них: это сцена, которую им не дали при жизни.","primary_genre":"Блюз","primary_mood":"Грусть","primary_theme":"Сцена","story_shelf":"Трагические истории","conflict_key":"память-певцам-и-тишина-молчавшим","image_key":"крест-без-венца-славы","turn_key":"плачем-не-по-певцам-а-по-немым","hook_key":"мы-споём-за-тех-кто-молчал","sort_order":"1279","original_key":"oliver-wendell-holmes|the-voiceless","author_name":"Оливер Уэнделл Холмс","original_title":"The Voiceless","original_language":"English","origin_country":"США","original_year":"1858","source_url":"https://en.wikisource.org/wiki/The_Voiceless","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1894.","music_adaptations":[],"source_synopsis":"Мы считаем сломанные лиры умерших певцов и горюем о них, — но плачьте не только о них: плачьте о безгласных, кто понёс свой крест без венца славы, кто молчал, не оставив ни песни, ни имени.","main_image":"крест без венца славы на безымянной могиле"},{"title":"Посадите яблоню","full_story":"Весь дом выходит сажать яблоню: яма, корни, первый полив — и каждый знает, что делает это не для себя. Весна будет возвращаться к этому дереву годами: птицы сядут на ветви, дети вырастут, а яблоки будут зреть уже при внуках. Дерево переживёт и посадивших, и их споры, и их праздники — и будет каждый год возвращать дом к жизни. Песня о самом тихом способе остаться.","hero_pov":"человек, сажающий дерево для будущих рук","central_conflict":"посадить для тех, кого не знаем","emotional_arc":"от семейного обряда к спокойному счастью остаться в плодах","ending_direction":"дерево будет жить после нас — и каждый год возвращать весну","hook_direction":"сажай — дерево переживёт нас","genres":["Кантри","Фолк"],"moods":["Тепло","Радость"],"energy":"Низкая","themes":["Возвращение","семья"],"generator_brief":"Тёплая семейная кантри с лёгкой скрипкой: куплеты — яма, корни, первый полив, припев — весна, которая будет возвращаться уже без них.","generator_story":"Весь дом выходит сажать яблоню — яма, корни, первый полив — и каждый знает: это не для себя. Дерево переживёт посадивших, их споры и праздники: птицы сядут на ветви, а яблоки созреют уже при внуках.","primary_genre":"Кантри","primary_mood":"Тепло","primary_theme":"Возвращение","story_shelf":"Юмор: семейные драмы","conflict_key":"посадить-для-тех-кого-не-знаем","image_key":"молодая-яблоня-у-дома","turn_key":"дерево-будет-жить-после-нас","hook_key":"сажай-дерево-переживёт-нас","sort_order":"1280","original_key":"william-cullen-bryant|the-planting-of-the-apple-tree","author_name":"Уильям Каллен Брайант","original_title":"The Planting of the Apple-Tree","original_language":"English","origin_country":"США","original_year":"1842","source_url":"https://www.gutenberg.org/files/29700/29700-h/29700-h.htm","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1878.","music_adaptations":[],"source_synopsis":"Домашний обряд: семья сажает яблоню у дома, зная, что весна будет возвращаться к ней годами, что птицы сядут на её ветви, что внуки будут есть её яблоки, когда сажавших не будет.","main_image":"молодая яблоня у дома, посаженная всей семьёй"},{"title":"Приглашение в вечность","full_story":"Он зовёт её идти с ним — не в рай и не в сказку, а в долину глубокой тени, где путь потерял себя и солнце забыло этот день. Сам он не знает ни своего имени, ни своих берегов: его даже имя отвергло. Но одному в такой темноте нельзя — и он протягивает руку, не обещая ничего, кроме того, что рядом будет кто-то. Песня о приглашении, честном до дрожи.","hero_pov":"потерявший себя, зовущий спутника","central_conflict":"звать в потерянную долину","emotional_arc":"от неловкого, страшного зова к единственной честной просьбе о рядом","ending_direction":"путь потерян, но рядом кто-то — и этого достаточно","hook_direction":"пойдёшь со мной туда?","genres":["Метал","Альтернатива"],"moods":["Тревога","Уязвимость"],"energy":"Низкая","themes":["расставание","Поиск себя"],"generator_brief":"Гулкий метал с чистым голосом поверх мрака: куплеты — потерянная долина без солнца, припев — протянутая рука и вопрос без обещаний.","generator_story":"Он зовёт спутника в долину глубокой тени, где путь потерян, а сам не знает даже своего имени. Одному в такой темноте нельзя: он протягивает руку, не обещая ничего, кроме того, что рядом будет кто-то.","primary_genre":"Метал","primary_mood":"Тревога","primary_theme":"расставание","story_shelf":"Трагические истории","conflict_key":"звать-в-потерянную-долину","image_key":"долина-где-солнце-забыло-день","turn_key":"путь-потерян-но-рядом-кто-то","hook_key":"пойдёшь-со-мной-туда","sort_order":"1281","original_key":"john-clare|an-invite-to-eternity","author_name":"Джон Клэр","original_title":"An Invite to Eternity","original_language":"English","origin_country":"Великобритания","original_year":"","source_url":"https://poets.org/poem/invite-eternity","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1864.","music_adaptations":[],"source_synopsis":"Странный зов девице: пойдёшь со мной в долину глубокой тени, где путь потерян, солнце забыло день и нет ни жизни, ни света? Говорящий сам не знает, кто он и где, — его даже имя отвергло, — но ему нужен кто-то рядом в этой темноте.","main_image":"долина, где солнце забыло день"},{"title":"Вернусь на перевал","full_story":"Опытный проводник уходит с последнего маршрута: возраст и равнинная жизнь требуют спокойствия. Внизу его ждёт уют, но горы провожают его молча, как старые друзья, которым обещают вернуться. Он уезжает, не оглядываясь, — потому что знает: перевал помнит его и будет ждать.","hero_pov":"Проводник, уходящий с последнего маршрута","central_conflict":"Равнинная жизнь тянет вниз, горы зовут назад","emotional_arc":"От горького расставания к тихому обещанию вернуться","ending_direction":"Он уезжает — и знает, что вернётся на перевал","hook_direction":"Я вернусь на перевал","genres":["Баллада","Рок"],"moods":["Тоска","Сила"],"energy":"Средняя","themes":["расставание","дом"],"generator_brief":"Широкая гитарная баллада с горным эхом в перкуссии; куплеты — шаг вниз по склону, припев — взгляд вверх.","generator_story":"Старый проводник уходит с последнего маршрута: возраст и равнина требуют покоя. Горы провожают его молча, как старые друзья, которым обещают вернуться, — он уезжает, зная, что перевал будет ждать.","primary_genre":"Баллада","primary_mood":"Тоска","primary_theme":"расставание","story_shelf":"Любовные сцены","conflict_key":"долина-тянет-горы-зовут","image_key":"прощальный-взгляд-на-вершины","turn_key":"горы-прощаются-до-срока","hook_key":"вернусь-на-перевал","sort_order":"1282","original_key":"vladimir-vysockiy|proschhanie-s-gorami","author_name":"Владимир Высоцкий","original_title":"Прощание с горами","original_language":"Russian","origin_country":"Россия","original_year":"1966","source_url":"https://wysotsky.com/1049.htm","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1980.","music_adaptations":[],"source_synopsis":"Альпинист возвращается с гор в городскую суету и понимает, что расставание с вершинами — не прощание навсегда, а лишь до срока. Горы остаются его настоящим домом, куда он обещает вернуться.","main_image":"долина внизу и вершины, оставшиеся за спиной"},{"title":"Письмо из ниоткуда","full_story":"После разрыва он продолжает писать письма, которые не отправляет: даты придуманы, города стёрты, обратный адрес не существует. Однажды он находит стопку у себя на антресолях и понимает, что все эти годы писал не ей, а себе. Последнее письмо он всё-таки опускает в ящик — без адреса.","hero_pov":"Человек, пишущий письма без адреса","central_conflict":"Расставание без адреса против любви, которая дошла","emotional_arc":"От отчаянной переписки с пустотой к тихому освобождению","ending_direction":"Он опускает последнее письмо в ящик и уходит свободным","hook_direction":"Пишу тебе в никуда","genres":["Инди-поп","Эмбиент"],"moods":["Одиночество","Тоска"],"energy":"Низкая","themes":["расставание","письмо"],"generator_brief":"Разряженный инди-поп с шумом типографской машинки и редким пионовым клавишным; припев — почти произносится.","generator_story":"После разрыва он годами пишет неотправленные письма с придуманными датами. Найдя стопку на антресолях, он понимает, что писал не ей, а себе, — и последнее письмо всё-таки опускает в ящик без адреса.","primary_genre":"Инди-поп","primary_mood":"Одиночество","primary_theme":"расставание","story_shelf":"Любовные сцены","conflict_key":"расставание-без-адреса","image_key":"мартовское-письмо-в-никуда","turn_key":"письмо-без-адреса-продолжается","hook_key":"пишу-тебе-никуда","sort_order":"1283","original_key":"iosif-brodskiy|niotkuda-s-lyubovyu","author_name":"Иосиф Бродский","original_title":"Ниоткуда с любовью","original_language":"Russian","origin_country":"Россия","original_year":"1962","source_url":"https://ru.wikipedia.org/wiki/Бродский,_Иосиф_Александрович","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1996.","music_adaptations":[],"source_synopsis":"Человек отправляет письмо с невозможной датой и отсутствующим адресом: расставание дошло до того, что и отправитель, и адресат остались вне всякой географии. Любовь — единственное, что дошло.","main_image":"конверт без адреса на пустом столе"},{"title":"Пёс ждёт у двери","full_story":"После её ухода в доме остались только хозяин и его старый пёс — и оба каждый вечер ходят к одной и той же двери. Они не разговаривают, но делят ожидание пополам, как делили хлеб. Однажды пёс первым отходит от двери и ложится у ног хозяина — и человек решает, что завтра откроет дверь не для неё.","hero_pov":"Хозяин, который ждёт вместе с псом","central_conflict":"Общее ожидание ушедшей против жизни, которая продолжается","emotional_arc":"От глухого ожидания к первому шагу в новую жизнь","ending_direction":"Пёс отходит от двери первым — и человек открывает её новому","hook_direction":"Мы ждём вместе","genres":["Баллада","Фолк"],"moods":["Нежность","Одиночество"],"energy":"Низкая","themes":["расставание","животные"],"generator_brief":"Тихая баллада с шерстяным шумом записи и редкой виолончелью; припев — вздох двоих в унисон.","generator_story":"После её ухода хозяин и старый пёс каждый вечер ходят к одной двери, деля ожидание пополам. Однажды пёс первым отходит и ложится у ног человека — и тот решает: завтра откроет дверь не для неё.","primary_genre":"Баллада","primary_mood":"Нежность","primary_theme":"расставание","story_shelf":"Люди и животные","conflict_key":"обе-ждут-ушедшую","image_key":"пёс-у-стеклянной-двери","turn_key":"дверь-открывается-новому","hook_key":"мы-ждём-вместе","sort_order":"1284","original_key":"evgeniy-evtushenko|moej-sobake","author_name":"Евгений Евтушенко","original_title":"Моей собаке","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/evtushenko/moey-sobake/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2017.","music_adaptations":[],"source_synopsis":"Пёс уткнулся носом в стекло и ждёт кого-то; хозяин кладёт руку в его шерсть и понимает, что ждёт того же. Когда-то здесь жила женщина, которая была ему не то сестрой, не то женой, не то дочерью, — теперь их двое без неё.","main_image":"пёс у стеклянной двери с чёрным носом на стекле"},{"title":"Номер, который я не стёр","full_story":"Они разошлись громко и давно, но она оставила его номер в телефоне — не как память, а как последнюю дверь. Каждый вечер она доводит палец до кнопки вызова и убирает. В финале она стирает номер не с обидой, а с благодарностью — и в ту же ночь впервые звонит он.","hero_pov":"Женщина, оставившая последний шанс","central_conflict":"Горечь разрыва против последнего сохранённого номера","emotional_arc":"От навязчивой надежды к тихому прощению","ending_direction":"Она стирает номер — и ночью звонит он","hook_direction":"Перезвони хотя бы во сне","genres":["Поп","Баллада"],"moods":["Тревога","Надежда"],"energy":"Высокая","themes":["расставание","любовь"],"generator_brief":"Проникновенный поп с электропиано и паузами, как гудки ожидания; припев — повторяющаяся мольба.","generator_story":"После громкого разрыва она хранит его номер как последнюю дверь: каждый вечер палец доходит до кнопки вызова и убирается. Она стирает номер с благодарностью — и в ту же ночь впервые звонит он.","primary_genre":"Поп","primary_mood":"Тревога","primary_theme":"расставание","story_shelf":"Любовные сцены","conflict_key":"разрыв-без-объяснений","image_key":"телефон-на-вытянутой-надежде","turn_key":"телефон-остаётся-на-надежде","hook_key":"перезвони-мне","sort_order":"1285","original_key":"robert-rozhdestvenskiy|pozvoni-mne-pozvoni","author_name":"Роберт Рождественский","original_title":"Позвони мне, позвони","original_language":"Russian","origin_country":"Россия","original_year":"1978","source_url":"https://ru.wikipedia.org/wiki/Позвони_мне,_позвони","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1994.","music_adaptations":[],"source_synopsis":"Героиня, потеряв любимого, просит его хотя бы позвонить — объяснить, почему всё так случилось. Один звонок для неё — шанс вернуть прошлое или хотя бы проститься.","main_image":"телефон, вытянутый в надежде на линии"},{"title":"Самая простая","full_story":"Он — путешественник, у которого за плечами сотни маршрутов и обещаний, и все они «самые». Однажды он возвращает из всех списков слово «самое» и произносит его вслух один раз — про неё. Она смеётся: из всех его экспедиций это самая короткая — до её окна.","hero_pov":"Путешественник, выбирающий самое важное слово","central_conflict":"Жажда маршрутов против единственности одного человека","emotional_arc":"От разбросанных «самых» к единственной","ending_direction":"Он закрывает карту и стучит в её окно","hook_direction":"Ты — самая простая моя","genres":["Баллада","Фолк"],"moods":["Любовь","Нежность"],"energy":"Высокая","themes":["любовь","дорога"],"generator_brief":"Тёплая акустическая баллада с ритмом шагов и редкой губной гармошкой; припев — простое признание в упор.","generator_story":"Путешественник с сотнями маршрутов раздаёт слово «самый» всем экспедициям — пока однажды не произнесёт его вслух один раз, про неё. Она смеётся: из всех путешествий это самое короткое — до её окна.","primary_genre":"Баллада","primary_mood":"Любовь","primary_theme":"любовь","story_shelf":"Любовные сцены","conflict_key":"одно-сравнение-сильнее-всех","image_key":"луна-весна-сосна-одна","turn_key":"простые-сравнения-строят-любовь","hook_key":"самая-простая-и-самая-нужная","sort_order":"1286","original_key":"yuriy-vizbor|ty-u-menya-odna","author_name":"Юрий Визбор","original_title":"Ты у меня одна","original_language":"Russian","origin_country":"Россия","original_year":"1964","source_url":"https://ru.wikipedia.org/wiki/Визбор,_Юрий_Иосифович","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1984.","music_adaptations":[],"source_synopsis":"Любовь объясняется через самые простые сравнения: как луна в ночи, как весна в году, как сосна в степи. За нарочитой простотой — предельная нежность и верность одному человеку.","main_image":"простые вещи, в которых читается она одна"},{"title":"Печурка на двоих","full_story":"Он пишет ей письмо при слабом огне: в их домике из четырёх досок тепло только от одной мысли — она где-то дышит тем же воздухом. Смерть стоит за спиной ближе, чем она, но он не соглашается с ней на слово. В финале он дописывает письмо и называет своё расстояние до неё — впервые не в вёрстах, а в днях.","hero_pov":"Солдат, пишущий жене при огне","central_conflict":"Близкая смерть против далёкого, но обязательного пути к ней","emotional_arc":"От озябшего отчаяния к тихой клятве дойти","ending_direction":"Он называет расстояние до неё в днях и складывает письмо","hook_direction":"Дойду через всё тепло","genres":["Фолк","Баллада"],"moods":["Любовь","Грусть"],"energy":"Низкая","themes":["любовь","письмо"],"generator_brief":"Тёплый фолк с треском поленьев в ритме; куплеты — шёпотом, припев — обещание, произнесённое в упор.","generator_story":"Солдат пишет жене при слабом огне в домике из четырёх досок: смерть за спиной ближе, чем она, но он с ней не соглашается. В финале он впервые измеряет расстояние до любимой не вёрстами, а днями.","primary_genre":"Фолк","primary_mood":"Любовь","primary_theme":"любовь","story_shelf":"Любовные сцены","conflict_key":"дойти-к-тебе-против-нельзя","image_key":"письмо-при-огне-землянки","turn_key":"письмо-у-печурки-обещает-дойти","hook_key":"дойду-через-любовь","sort_order":"1287","original_key":"aleksey-surkov|v-zemlyanke","author_name":"Алексей Сурков","original_title":"В землянке","original_language":"Russian","origin_country":"Россия","original_year":"1941","source_url":"https://ru.wikipedia.org/wiki/Сурков,_Алексей_Александрович","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1983.","music_adaptations":[],"source_synopsis":"Солдат у огня землянки пишет жене: тепло в этом доме — от их близости, а не от печки. До неё далеко, смерть близко, и всё-таки он обещает дойти.","main_image":"огонь в печурке и письмо, идущее к ней"},{"title":"Песня летит через реку","full_story":"Городская хор выбирает главную песню лета, и двадцатилетняя поёт её так, что весь двор замирает. Ей кажется, что голос полетит и долетит до того, кого она ждёт. Когда он вернётся и первым спросит, что это была за песня, она ответит: это была ты.","hero_pov":"Девушка, поющая через реку и границы","central_conflict":"Границы и расстояния против песни, которая летит","emotional_arc":"От стеснительного куплета к смелому полёту голоса","ending_direction":"Он вернулся — и песня оказалась про них двоих","hook_direction":"Пусть услышит далёкий","genres":["Поп","Фолк"],"moods":["Романтика","Любовь"],"energy":"Высокая","themes":["любовь","ожидание"],"generator_brief":"Светлая поп-песня с широким летним звучанием, гитарой в руку и голосом, летящим в куплетах выше и выше.","generator_story":"Двадцатилетняя так поёт главную песню лета, что весь двор замирает: пусть голос долетит до того, кого она ждёт. Когда он возвращается и спрашивает, что это была за песня, она отвечает: это была ты.","primary_genre":"Поп","primary_mood":"Романтика","primary_theme":"любовь","story_shelf":"Любовные сцены","conflict_key":"песня-связывает-берега","image_key":"девушка-поёт-у-реки","turn_key":"песня-перелетает-через-реку","hook_key":"пусть-услышит-далёкий","sort_order":"1288","original_key":"mihail-isakovskiy|katyusha","author_name":"Михаил Исаковский","original_title":"Катюша","original_language":"Russian","origin_country":"Россия","original_year":"1938","source_url":"https://ru.wikipedia.org/wiki/Катюша_(песня)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1973.","music_adaptations":[],"source_synopsis":"Девушка выходит на высокий берег и поёт песню о том, кто на дальнем пограничье хранит родные просторы. Песня летит к нему через реки и поля — и вместе с ней летят её любовь и вера в ответ.","main_image":"девушка поёт на высоком берегу крутом"},{"title":"Море роз для неё","full_story":"Он был живописцем в маленьком порту и любил певицу с балкона. Чтобы повторить её голос красками, он продал дом, мастерскую и саму свою картину — и выложил перед её окном миллион алых роз. Корабль уплыл с ней и с её аплодисментами, а он остался у моря роз и закрасил свою боль синим — так он стал тем, кто рисует море.","hero_pov":"Художник, отдающий всё за один жест","central_conflict":"Всё, что у него было, против одного мгновения для неё","emotional_arc":"От отчаянного порыва к синему покою у моря","ending_direction":"Он остаётся с морем роз — и начинает писать новое","hook_direction":"Море роз помнит его","genres":["Баллада","Поп"],"moods":["Боль","Романтика"],"energy":"Высокая","themes":["любовь","Мечта"],"generator_brief":"Большая баллада-легенда с морской волной в аранжировке; куплеты — рассказ, припев — вслепую яркий.","generator_story":"Портовый живописец продаёт дом и мастерскую, чтобы повторить красками голос певицы, — и выкладывает перед её окном миллион алых роз. Корабль уплывает с ней, а он остаётся закрашивать свою боль синим.","primary_genre":"Баллада","primary_mood":"Боль","primary_theme":"любовь","story_shelf":"Трагические истории","conflict_key":"всё-продано-ради-роз","image_key":"миллион-роз-под-окном","turn_key":"море-роз-остаётся-художнику","hook_key":"море-роз-помнит-его","sort_order":"1289","original_key":"andrey-voznesenskiy|million-alyh-roz","author_name":"Андрей Вознесенский","original_title":"Миллион алых роз","original_language":"Russian","origin_country":"Россия","original_year":"1982","source_url":"https://ru.wikipedia.org/wiki/Миллион_алых_роз","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2010.","music_adaptations":[],"source_synopsis":"Бедный художник продал свою картину и всё, что имел, чтобы устлать перед окном возлюбленной миллион алых роз. Увидев море цветов, она уплыла с богатым капитаном, — а художник остался один с морем.","main_image":"миллион алых роз под окном на рассвете"},{"title":"Воскресная перепалка","full_story":"Каждое воскресенье Иван и Зиновий собираются у экрана — и каждое воскресенье ссорятся из-за всего на свете: судьи, зарплаты, порядка в доме. Жены уже не вмешиваются: так положено, так пережито, так держится их союз. В финале матча оба молча гремят посудой — и обоим ясно, что без этих скандалов они пропали бы.","hero_pov":"Один из двух друзей, которые всегда ругаются","central_conflict":"Вечная перепалка против дружбы, которую она держит","emotional_arc":"От пиратского азартного гвалта к молчаливому согласию","ending_direction":"Матч кончился — они уже договорились на следующий","hook_direction":"Ругаемся до утра","genres":["Рок","Шансон"],"moods":["Ирония","Драйв"],"energy":"Взрывная","themes":["ссора","Дружба"],"generator_brief":"Дерзкий рок-дуэт с перепалкой двух голосов и стуком посуды в перкуссии; припев — выкрики наперебой.","generator_story":"Воскресеньями Иван и Зиновий ссорятся у экрана из-за всего: судьи, зарплаты, порядок. Жёны не вмешиваются — так держится их союз, и когда матч кончается, они уже договорились на следующую перепалку.","primary_genre":"Рок","primary_mood":"Ирония","primary_theme":"ссора","story_shelf":"Юмор: семейные драмы","conflict_key":"ссора-друзей-у-экрана","image_key":"телевизор-вино-и-друзья","turn_key":"перепалка-держит-дружбу","hook_key":"ругаемся-до-утра","sort_order":"1290","original_key":"vladimir-vysockiy|dialog-u-televizora","author_name":"Владимир Высоцкий","original_title":"Диалог у телевизора","original_language":"Russian","origin_country":"Россия","original_year":"1973","source_url":"https://wysotsky.com/1049.htm","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1980.","music_adaptations":[],"source_synopsis":"Двое друзей смотрят трансляцию матча и перебраниваются из-за каждой мелочи: от комментатора до воды в газировке. Их воскресная ссора — ритуал, который держит дружбу крепче любых признаний.","main_image":"два друга, экран и бутылки у ног"},{"title":"Ночь, когда пели петухи","full_story":"Пара, которая годами спит рядом чужими, не разговаривает с утра до ночи. Однажды во дворе всю ночь кричат петухи — так надрывно, что оба не спят и слушают. Утром она впервые за годы спрашивает: тебе тоже не спалось? — и этот вопрос оказывается началом длинного разговора.","hero_pov":"Мужчина из остывшей пары","central_conflict":"Сонное отчуждение против одного неожиданного вопроса","emotional_arc":"От чужой постели к первому общему разговору","ending_direction":"Они говорят до утра — про петухов и про себя","hook_direction":"Поговорим, как петухи","genres":["Шансон","Баллада"],"moods":["Грусть","Ирония"],"energy":"Низкая","themes":["ссора","примирение"],"generator_brief":"Дворовая баллада-шансон с петушиными выкриками в бридже; куплеты — усталые, припев — с первой искрой тепла.","generator_story":"Пара годами спит рядом чужими — пока петухи во дворе не кричат всю ночь так, что оба не спят и слушают. Утром она впервые за годы спрашивает, не спалось ли ему, и вопрос растёт в длинный разговор.","primary_genre":"Шансон","primary_mood":"Грусть","primary_theme":"ссора","story_shelf":"Юмор: семейные драмы","conflict_key":"спать-рядом-чужими","image_key":"петухи-читают-стихи","turn_key":"петухи-начинают-разговор","hook_key":"поговорим-как-петухи","sort_order":"1291","original_key":"bulat-okudzhava|vsyu-noch-krichali-petuhi","author_name":"Булат Окуджава","original_title":"Всю ночь кричали петухи","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/okudzhava/vsyu-noch-krichali-petuhi/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1997.","music_adaptations":[],"source_synopsis":"Всю ночь кричали петухи, как будто читали новые стихи, и в этом крике была горечь тех, кто входит в дом постылым и гладит, глядя в потолок, чужих и нелюбимых.","main_image":"петухи читают стихи в тёмном дворе"},{"title":"Спор с собственной совестью","full_story":"Удачливый жилец по имени Ты-Же-Знаешь весь вечер объясняет себе, что спрашивать нечего и всё у него по закону. Совесть садится напротив и молчит — и от этого молчания веселый монолог трещит по швам. К ночи он впервые отвечает вслух вместо неё и не может уснуть.","hero_pov":"Обыватель, спорящий со своей совестью","central_conflict":"Самооправдание против молчащей совести","emotional_arc":"От весёлой отмазки к бессонной честности","ending_direction":"Он отвечает за совесть сам — и теряет сон","hook_direction":"Что-ж-тут-спрашивать","genres":["Шансон","Панк"],"moods":["Ирония","Злость"],"energy":"Средняя","themes":["ссора","Выбор"],"generator_brief":"Ухмыляющийся шансон-монолог с грязноватой гитарой; припев — самодовольный, бридж — обрывается в тишину.","generator_story":"Удачливый обыватель весь вечер объясняет себе, что всё по закону, а совесть молчит напротив. От этого молчания весёлый монолог трещит по швам — к ночи он впервые отвечает вслух за неё и теряет сон.","primary_genre":"Шансон","primary_mood":"Ирония","primary_theme":"ссора","story_shelf":"Юмор: семейные драмы","conflict_key":"совесть-стучится-обывателю","image_key":"резиновый-треугольник-на-столе","turn_key":"совесть-не-отвечает-на-отмазки","hook_key":"совесть-не-даёт-уснуть","sort_order":"1292","original_key":"aleksandr-galich|krasnyy-treugolnik","author_name":"Александр Галич","original_title":"Красный треугольник","original_language":"Russian","origin_country":"Россия","original_year":"1962","source_url":"https://ru.wikipedia.org/wiki/Галич,_Александр_Аркадьевич","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1977.","music_adaptations":[],"source_synopsis":"Сатирический монолог обывателя-приспособленца, который с ироническим самооправданием объясняет, почему живёт именно так и ни в чём не виноват.","main_image":"человек, спорящий с собственной совестью"},{"title":"Свой, не свой","full_story":"Команда поднимается, когда руководитель зависает над обрывом, и старший задаёт единственный вопрос: был он своим — пойдёшь? Двое молчат, один разматывает верёвку. Внизу выясняется, что молчавших никто не ждёт даже к чаю, а спустившийся обретает не награду, а имя «друг» — навсегда.","hero_pov":"Тот, кто разматывает верёвку","central_conflict":"Секунда выбора против всей будущей дружбы","emotional_arc":"От ледяного вопроса к жаркому праву зваться другом","ending_direction":"Молчавшие остаются одни — спустившиеся получают друга","hook_direction":"Пойдёшь выручать — свой","genres":["Рок","Эпик-рок"],"moods":["Смелость","Сила"],"energy":"Взрывная","themes":["дружба","смелость"],"generator_brief":"Крутой горный рок с тикающим ритмом подъёма и паузой вопроса; припев — резкий, как щелчок карабина.","generator_story":"Когда руководитель зависает над обрывом, старший спрашивает команду: был он своим — пойдёшь? Двое молчат, один разматывает верёвку — и на дне он получает не награду, а имя «друг» на всю жизнь.","primary_genre":"Рок","primary_mood":"Смелость","primary_theme":"дружба","story_shelf":"Трагические истории","conflict_key":"проверка-друга-в-пропасти","image_key":"одна-верёвка-на-склоне","turn_key":"проверка-в-горах-выносит-приговор","hook_key":"пойдёшь-выручать","sort_order":"1293","original_key":"vladimir-vysockiy|pesnya-o-druge","author_name":"Владимир Высоцкий","original_title":"Песня о друге","original_language":"Russian","origin_country":"Россия","original_year":"1966","source_url":"https://wysotsky.com/1049.htm","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1980.","music_adaptations":[],"source_synopsis":"В горах пал товарищ, и группе предлагают узнать: если он был своим, пойдёшь выручать. Тот, кто дважды ошибся в людях, остаётся в мире без друзей.","main_image":"одна верёвка на склоне между двумя людьми"},{"title":"Тройное всё же","full_story":"Дед трижды в год собирает у карты бывших дорог и называет имена тех, кто остался молодым. Внучка доказывает ему, что он не виноват, и он соглашается — и всё равно произносит своё «всё же» трижды. В конце она впервые повторяет за ним это слово, и дед впервые улыбается.","hero_pov":"Ветеран у карты своих дорог","central_conflict":"Логика прощения против повторяющегося «всё же»","emotional_arc":"От stubbornly вины к передаче памяти внуку","ending_direction":"Внучка повторяет его «всё же» — и он улыбается","hook_direction":"Помню — не отведя лица","genres":["Баллада","Эмбиент"],"moods":["Вина","Грусть"],"energy":"Низкая","themes":["дружба","память"],"generator_brief":"Почти шёпотная баллада с редким фортепиано и долгими паузами; каждая строка припева повторяется трижды.","generator_story":"Ветеран называет у карты своих дорог имена погибших. Внучка доказывает, что он не виноват, он соглашается — и всё равно трижды произносит «всё же», пока она однажды не повторяет это слово за ним.","primary_genre":"Баллада","primary_mood":"Вина","primary_theme":"дружба","story_shelf":"Трагические истории","conflict_key":"не-вина-и-не-забвение","image_key":"имена-без-лиц-на-карте","turn_key":"тройное-всё-же-становится-клятвой","hook_key":"спасибо-что-жили","sort_order":"1294","original_key":"aleksandr-tvardovskiy|ya-znayu-nikakoy-moey-viny","author_name":"Александр Твардовский","original_title":"Я знаю, никакой моей вины","original_language":"Russian","origin_country":"Россия","original_year":"1966","source_url":"https://slova.org.ru/tvardovskiy/ya-znayu-nikakoy-moej-viny/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1971.","music_adaptations":[],"source_synopsis":"Ветеран знает: никакой его вины в том, что другие не пришли с войны. Но он не может не повторять одно и то же слово — память тех, кто не вернулся, живёт в нём вопреки всякой логике.","main_image":"имена без лиц на старой карте дорог"},{"title":"Друг, который снится","full_story":"Они не разговаривают пять лет из-за того, что разошлись в разные лагеря жизни. Ему снится старая лестница, крик-исповедь и друг, который кричит не на него, а на общий призрак. Проснувшись, он набирает знакомый номер первым — и не знает, снимут ли трубку.","hero_pov":"Человек, решившийся набрать номер первым","central_conflict":"Бытовая вражда против дружбы, которая снится","emotional_arc":"От гордого молчания к дрожащему набору номера","ending_direction":"Гудки идут — он не убирает трубку","hook_direction":"Наберу номер первым","genres":["Баллада","Инди-поп"],"moods":["Боль","Ностальгия"],"energy":"Низкая","themes":["дружба","прошлое"],"generator_brief":"Сонная инди-баллада с приглушённым шумом подъезда и дрожащим вокалом; припев — один вопрос без ответа.","generator_story":"Пять лет друзья не разговаривают, разойдясь по лагерям, — пока ему не снится старая лестница и друг, кричащий на общий призрак. Проснувшись, он набирает знакомый номер и не знает, снимут ли трубку.","primary_genre":"Баллада","primary_mood":"Боль","primary_theme":"дружба","story_shelf":"Трагические истории","conflict_key":"друг-стал-врагом","image_key":"сон-на-тёмной-лестнице","turn_key":"друг-во-сне-возвращает-имя","hook_key":"наберу-номер-первым","sort_order":"1295","original_key":"evgeniy-evtushenko|staryy-drug","author_name":"Евгений Евтушенко","original_title":"Старый друг","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/evtushenko/staryj-drug/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2017.","music_adaptations":[],"source_synopsis":"Поэту снится старый друг, который стал врагом, — но снится не врагом, а тем же самым другом, с криком-исповедью у стен старой лестницы.","main_image":"сон на тёмной лестнице, где они ещё друзья"},{"title":"Вахта памяти живого","full_story":"После похорон последнего из их костра ветеран раскладывает на столе фотографии: ему поручено быть связным между двумя поколениями. Он заводит тетрадь, где записывает за каждым ушедшим его песню, шутку и слово. Финал — он выходит на рассветное построение одно, но не один: за спиной стоит вся его часть.","hero_pov":"Живой солдат, принявший вахту памяти","central_conflict":"Уходящая рота друзей против вахты, которую надо держать","emotional_arc":"От прощальных вёрст к светлому строю за спиной","ending_direction":"Он построен в одиночку — но не один","hook_direction":"Приму вахту за них","genres":["Баллада","Эпик-рок"],"moods":["Грусть","Сила"],"energy":"Низкая","themes":["дружба","память"],"generator_brief":"Сдержанная баллада с маршевым эхом на дальнем плане; куплеты — как перекличка, припев — один голос за строй.","generator_story":"После похорон последнего из их костра ветеран заводит тетрадь, записывая за каждым ушедшим песню, шутку и слово. На рассветное построение он выходит один, но не один: за спиной стоит вся его часть.","primary_genre":"Баллада","primary_mood":"Грусть","primary_theme":"дружба","story_shelf":"Трагические истории","conflict_key":"уходят-один-за-другим","image_key":"фотографии-друзей-у-окна","turn_key":"вахта-памяти-переходит-к-живым","hook_key":"приму-вахту-за-них","sort_order":"1296","original_key":"mihail-dudin|eshche-odin-odnopolchanin","author_name":"Михаил Дудин","original_title":"Ещё один однополчанин","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/dudin/ewe-odin-odnopolchanin/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1994.","music_adaptations":[],"source_synopsis":"Уходит ещё один однополчанин — в дорогу вечности, к оставленному поколению, к друзьям любви и чести. Живой остаётся держать рубеж и быть надеждой мёртвых и живых.","main_image":"фотографии друзей у окна живого солдата"},{"title":"Моя улица не сдаётся","full_story":"В его любимом дворе встали заборы и краны, и объявили новое название. Каждый вечер он приходит к забору и рассказывает новому двору, какие здесь были окна и голоса. Финал — табличку всё-таки вешают, но двор отвечает ему запахом сирени из-под бетона.","hero_pov":"Житель, который разговаривает с улицей","central_conflict":"Перестройка и переименование против любви к своей улице","emotional_arc":"От горькой хроники сноса к тихой победе двора","ending_direction":"Сирень из-под бетона отвечает вместо таблички","hook_direction":"Улица не сдаётся","genres":["Шансон","Фолк"],"moods":["Любовь","Ностальгия"],"energy":"Высокая","themes":["город","прошлое"],"generator_brief":"Дворовая шансон-песня с ритмом шагов по асфальту и тёплой семиструнной гитарой; припев — гордо и нежно.","generator_story":"В любимом дворе встали заборы и краны, объявили новое название, но каждый вечер он приходит к забору рассказывать, какие были окна и голоса. Табличку вешают — а двор отвечает сиренью из-под бетона.","primary_genre":"Шансон","primary_mood":"Любовь","primary_theme":"город","story_shelf":"Любовные сцены","conflict_key":"снос-против-любви-к-улице","image_key":"двор-за-строительным-забором","turn_key":"улица-остаётся-отечеством","hook_key":"улица-не-сдаётся","sort_order":"1297","original_key":"bulat-okudzhava|pesenka-ob-arbate","author_name":"Булат Окуджава","original_title":"Песенка об Арбате","original_language":"Russian","origin_country":"Россия","original_year":"1959","source_url":"https://slova.org.ru/okudzhava/pesenka-ob-arbate/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1997.","music_adaptations":[],"source_synopsis":"Человек обращается к своей улице как к живому существу: она и радость, и беда, и религия, и отечество — её невозможно пройти до конца и от её любви не излечиться.","main_image":"улица детства за строительным забором"},{"title":"Синий салон для потерпевших","full_story":"Ночной троллейбус приходит на конечную как добрый зверь: кондуктор знает пассажиров по глазам, а не по билетам. Здесь плачут в кулак и выходят на рассвете человечнее. Финал — у двери машины водитель оставляет свободное место с табличкой «для потерпевших крушенье» — и оно всегда занято.","hero_pov":"Водитель ночного троллейбуса","central_conflict":"Ночное крушенье людей против салона, который подбирает всех","emotional_arc":"От мокрых плеч пассажиров к рассветной человечности","ending_direction":"Рассвет — салон пуст, и это его победа","hook_direction":"Троллейбус подберёт всех","genres":["Шансон","Джаз"],"moods":["Одиночество","Надежда"],"energy":"Низкая","themes":["город","поддержка"],"generator_brief":"Ночной лоу-шансон с гулом троллейбуса в басу и редкими струнными; припев — как объявление остановки.","generator_story":"Ночной троллейбус приходит на конечную как добрый зверь: здесь плачут в кулак и выходят на рассвете человечнее. У двери водитель оставляет место для потерпевших крушенье — и оно всегда занято.","primary_genre":"Шансон","primary_mood":"Одиночество","primary_theme":"город","story_shelf":"Люди и животные","conflict_key":"ночное-крушенье-против-салона","image_key":"синий-салон-на-пустой-улице","turn_key":"салон-рассвета-лечит-пассажиров","hook_key":"троллейбус-подберёт-всех","sort_order":"1298","original_key":"bulat-okudzhava|polnochnyy-trolleibus","author_name":"Булат Окуджава","original_title":"Полночный троллейбус","original_language":"Russian","origin_country":"Россия","original_year":"1963","source_url":"https://slova.org.ru/okudzhava/polnochnyj-trollejbus/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1997.","music_adaptations":[],"source_synopsis":"Когда человеку невмочь пересилить беду, он садится в полночный троллейбус — он верши по бульварам круженье, чтоб всех подобрать, потерпевших в ночи крушенье.","main_image":"синий салон на пустой ночной улице"},{"title":"Билет в город Да","full_story":"Герой годами ездит в командировку в город Нет, где диваны из фальши, а каждый портрет глядит подозрительно. Его семья живёт в городе Да, и билеты туда он покупает, как лотерейные. Финал — он сдает обратный билет в Нет без объяснений и впервые поёт в вагоне во весь голос.","hero_pov":"Человек, мечущийся между двумя городами","central_conflict":"Город Нет с его запретами против города Да","emotional_arc":"От натянутых нервов к крику освобождения в вагоне","ending_direction":"Он сдаёт обратный билет и поёт в весь вагон","hook_direction":"Билет в город Да","genres":["Альтернативный рок","Рок"],"moods":["Протест","Напряжение"],"energy":"Взрывная","themes":["город","Выбор"],"generator_brief":"Дерзкий альт-рок с поездным ритмом и пульсирующей басовой линией «нет-нет-нет»; припев — выкрик «да».","generator_story":"Герой годами ездит в командировки в город Нет, где диваны из фальши, а семья его живёт в городе Да. Однажды он сдаёт обратный билет без объяснений и впервые поёт в вагоне во весь голос.","primary_genre":"Альтернативный рок","primary_mood":"Протест","primary_theme":"город","story_shelf":"Трагические истории","conflict_key":"город-нет-против-города-да","image_key":"поезд-между-двумя-городами","turn_key":"билет-куплен-в-город-да","hook_key":"билет-в-город-да","sort_order":"1299","original_key":"evgeniy-evtushenko|dva-goroda","author_name":"Евгений Евтушенко","original_title":"Два города","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/evtushenko/dva-goroda/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2017.","music_adaptations":[],"source_synopsis":"Человек, как поезд, мечется между городом Нет — натёртым, испуганным, где всё отвечает «нет-нет-нет», — и городом Да. Нервы натянуты между ними, как провода.","main_image":"поезд, летящий между двумя городами"},{"title":"Сшито с городом","full_story":"Старик перебирает на скамейке всё, что сшилось с его городом: первый шёпот, первый бой, кровь друзей, седину. Он мог бы уехать к сыну за границу комфорта, но остаётся — потому что верность до конца не отводит лица. В финале он идёт по своему маршруту и здоровается с каждым углом по имени.","hero_pov":"Старик, оставшийся со своим городом","central_conflict":"Комфорт отъезда против верности всему прожитому","emotional_arc":"От тихой инвентаризации жизни к гордой верности","ending_direction":"Он здоровается с каждым углом по имени","hook_direction":"Город и я — навек","genres":["Баллада","Шансон"],"moods":["Ностальгия","Сила"],"energy":"Высокая","themes":["город","Время"],"generator_brief":"Поток-баллада с городскими шумами и нарастающей струнной волной; припев — перечисление жизни, как маршрут.","generator_story":"Старик перебирает на скамейке всё, что сшилось с городом: первый шёпот, первый бой, кровь друзей. Он мог бы уехать к сыну в комфорт, но остаётся и здоровается с каждым углом по имени.","primary_genre":"Баллада","primary_mood":"Ностальгия","primary_theme":"город","story_shelf":"Любовные сцены","conflict_key":"жизнь-навек-связана-с-городом","image_key":"седина-на-городском-ветру","turn_key":"жизнь-сошита-с-городом","hook_key":"город-и-я-навек","sort_order":"1300","original_key":"mihail-dudin|vse-s-etim-gorodom-navek","author_name":"Михаил Дудин","original_title":"Всё с этим городом навек","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/dudin/vse-s-etim-gorodom-navek/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1994.","music_adaptations":[],"source_synopsis":"Всё с этим городом навек — и песня, и душа, и черствый хлеб, и чёрный снег, любовь, тоска, печаль и смех; вся жизнь человека сшита с городом, и верность до конца не отведёт лица от совести.","main_image":"седина на городском ветру"},{"title":"Договоримся о тайне","full_story":"Пара на грани развода проводит последнюю ночь переговоров: она требует понять всё до конца, он боится, что понимание убьёт нежность. Они придумывают правило — у каждого остаётся одна комната тайны, и это не ложь, а берег. Утром они впервые за год завтракают молча и легко.","hero_pov":"Мужчина, договаривающийся о гранях близости","central_conflict":"Всеобщее понимание против права на тайну двоих","emotional_arc":"От судебной ночи к нежному договору","ending_direction":"Они оставляют друг другу тайну — как общий берег","hook_direction":"Оставлю тебе тайну","genres":["Инди-поп","Баллада"],"moods":["Нежность","Мечтательность"],"energy":"Низкая","themes":["примирение","любовь"],"generator_brief":"Тонкий инди-поп с воздушными клавишами и почти шёпотным диалогом двух голосов в припеве.","generator_story":"Пара на грани развода оставляет каждому по одной комнате тайны — не ложь, а берег, — потому что полная понятность убила бы нежность. Утром они впервые за год завтракают молча и легко.","primary_genre":"Инди-поп","primary_mood":"Нежность","primary_theme":"примирение","story_shelf":"Любовные сцены","conflict_key":"понимание-против-тайны","image_key":"две-чашки-на-одном-столе","turn_key":"тайна-оставлена-как-сад","hook_key":"оставлю-тебе-тайну","sort_order":"1301","original_key":"evgeniy-evtushenko|ne-ponimat-drug-druga-strashno","author_name":"Евгений Евтушенко","original_title":"Не понимать друг друга страшно","original_language":"Russian","origin_country":"Россия","original_year":"1956","source_url":"https://slova.org.ru/evtushenko/ne-ponimat-drug-druga-strashno/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2017.","music_adaptations":[],"source_synopsis":"Не понимать друг друга страшно — не понимать и обнимать; но так же страшно во всём друг друга понимать. Душу нежную можно оскорбить непониманьем и убить пониманьем.","main_image":"две чашки на одном столе и тонкая грань между ними"},{"title":"Страна, которая всегда рядом","full_story":"Мужчина уезжает искать «страну получше» — где всё уже готово и никого не надо ждать. На каждом перекрёстке ему обещают, что она за следующим поворотом, и только письма от жены читаются как настоящие новости. Он возвращается на исходный двор и понимает: та страна — это его двор, в который он вложил свои руки.","hero_pov":"Странник, вернувшийся к своему двору","central_conflict":"Мечта о стране готового счастья против двора, построенного руками","emotional_arc":"От бродячей мечты к крепкому возвращению","ending_direction":"Он распрягает коня — и берётся за своё","hook_direction":"Страна оказалась домом","genres":["Фолк","Рок"],"moods":["Мечтательность","Вдохновение"],"energy":"Высокая","themes":["примирение","дом"],"generator_brief":"Фолк-марш с дорогой в ритме и раздольной гармонью; куплеты — перекрёстки, припев — возвращение на родной двор.","generator_story":"Мужчина уезжает искать страну, где всё готово и ждать никого не надо, — а настоящими новостями остаются письма жены. Он возвращается на свой двор и понимает: та страна построена его руками.","primary_genre":"Фолк","primary_mood":"Мечтательность","primary_theme":"примирение","story_shelf":"Любовные сцены","conflict_key":"поиски-лучшего-против-своего","image_key":"конь-и-странник-на-перекрёстке","turn_key":"все-дороги-ведут-к-дому","hook_key":"страна-оказалась-домом","sort_order":"1302","original_key":"aleksandr-tvardovskiy|strana-muraviya","author_name":"Александр Твардовский","original_title":"Страна Муравия","original_language":"Russian","origin_country":"Россия","original_year":"1936","source_url":"https://slova.org.ru/tvardovskiy/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1971.","music_adaptations":[],"source_synopsis":"Крестьянин со своим конём уходит искать сказочную страну всеобщего счастья и вольной жизни. Дорога приводит его назад — в родную деревню, где его ждут дом и своя земля.","main_image":"странник с конём на перекрёстке дорог"},{"title":"Продли дорогу","full_story":"Жизнь героя несётся галопом: сделки, смерти друзей, любимые станции мимо. Однажды он попадает на скакунов, которых не останавливает ни узда, ни просьба, — и тогда он перестаёт бороться за тормоза и начинает умолять о скорости чуть меньше максимальной. Финал — кони слушают его первый раз: он едет шагом и видит лица.","hero_pov":"Всадник, умоляющий коней о времени","central_conflict":"Бешеный галоп жизни против мольбы продлить дорогу","emotional_arc":"От лихого азарта к мудрому шагу","ending_direction":"Кони впервые слушают — он видит лица мимо","hook_direction":"Продли мне дорогу","genres":["Рок","Эпик-рок"],"moods":["Драйв","Тоска"],"energy":"Взрывная","themes":["примирение","Время"],"generator_brief":"Бешеный рок-галоп с топотом копыт в барабанах; припев — умоляющий крик на полном ходу, бридж — внезапный шаг.","generator_story":"Жизнь несётся галопом — сделки, смерти друзей, любимые станции мимо, — и всадник умоляет скакунов о скорости чуть меньше максимальной. Кони впервые слушают: он едет шагом и наконец видит лица.","primary_genre":"Рок","primary_mood":"Драйв","primary_theme":"примирение","story_shelf":"Люди и животные","conflict_key":"скачка-против-просьбы-о-паузе","image_key":"кони-по-краю-пропасти","turn_key":"мольба-о-замедлении","hook_key":"продли-мне-дорогу","sort_order":"1303","original_key":"vladimir-vysockiy|koni-privredlivye","author_name":"Владимир Высоцкий","original_title":"Кони привередливые","original_language":"Russian","origin_country":"Россия","original_year":"1972","source_url":"https://wysotsky.com/1049.htm","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1980.","music_adaptations":[],"source_synopsis":"Всадник несётся вдоль обрыва по-над пропастью на взбесившихся конях и умоляет их чуть помедленнее — хоть немного продлить свой путь. Он просит не о спасении, а о времени.","main_image":"кони по краю пропасти на бешеном скаку"},{"title":"Косточка для нового дома","full_story":"Переезжая в дом, где он не проживёт и десятилетия, мужчина первым делом сажает у порога виноградную косточку. Сосед смеётся: ему не съесть этот виноград. Он отвечает, что сажает не для себя — и через годы его уже взрослые дети, приехав к этому дому, едят виноград и не знают, кто его посадил.","hero_pov":"Человек, сажающий косточку не для себя","central_conflict":"Смех соседей против веры в жизнь длиннее человека","emotional_arc":"От насмешки к тихому круговороту любви","ending_direction":"Дети едят виноград с его лозы, не зная имени","hook_direction":"Чтобы любить и сажать","genres":["Фолк","Баллада"],"moods":["Надежда","Нежность"],"energy":"Низкая","themes":["примирение","дом"],"generator_brief":"Тёплый фолк с южной струнной перкуссией и лёгкой винной тёплостью в голосе; припев — как тост за жизнь.","generator_story":"Переезжая в дом, где не проживёт и десятилетия, мужчина сажает у порога виноградную косточку — сосед смеётся. Через годы к дому приезжают взрослые дети и едят виноград, не зная, кто его посадил.","primary_genre":"Фолк","primary_mood":"Надежда","primary_theme":"примирение","story_shelf":"Любовные сцены","conflict_key":"сажать-зная-что-не-увидишь","image_key":"росток-у-нового-дома","turn_key":"косточка-сажается-для-других","hook_key":"чтобы-любить-и-сажать","sort_order":"1304","original_key":"bulat-okudzhava|vinogradnuyu-kostochku","author_name":"Булат Окуджава","original_title":"Виноградную косточку","original_language":"Russian","origin_country":"Россия","original_year":"1958","source_url":"https://slova.org.ru/okudzhava/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1997.","music_adaptations":[],"source_synopsis":"Человек сажает виноградную косточку в тёплую землю, целует лозу, срывает гроздья, созывает друзей — и настраивает сердце на любовь. Иначе — зачем на земле живёт человек?","main_image":"росток у нового дома"},{"title":"Вальс в рабочих башмаках","full_story":"Ночной паром везёт переселенцев на Камчатку: мерзлотовед, портовые парни, семья с узлами. Кто-то включает старый вальс, и вместо прощальных слёз палуба начинает танцевать в бахилах и кедах. Два незнакомых человека, танцуя, договариваются встретиться на другом берегу — и вальс становится их первым общим домом.","hero_pov":"Пассажир парома, танцующий в башмаках","central_conflict":"Прощание с большой землёй против вальса на переправе","emotional_arc":"От узлов и распродаж к кружащей палубе","ending_direction":"Паром подходит — вальс продолжается на новом берегу","hook_direction":"Вальс на переправе","genres":["Поп-рок","Инди-поп"],"moods":["Романтика","Мечтательность"],"energy":"Средняя","themes":["Танец","дорога"],"generator_brief":"Качающийся поп-рок-вальс со стуком волн и гудком парома в переходе; припев — кружение всей палубы.","generator_story":"На ночном пароме кто-то включает старый вальс — и вместо прощальных слёз палуба переселенцев танцует в бахилах и кедах. Двое незнакомых договариваются о встрече на новом берегу: вальс стал их домом.","primary_genre":"Поп-рок","primary_mood":"Романтика","primary_theme":"Танец","story_shelf":"Любовные сцены","conflict_key":"прощание-с-большой-землёй","image_key":"танец-в-рабочих-башмаках","turn_key":"вальс-знакомит-на-переправе","hook_key":"вальс-на-переправе","sort_order":"1305","original_key":"evgeniy-evtushenko|val-s-na-palube","author_name":"Евгений Евтушенко","original_title":"Вальс на палубе","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/evtushenko/val-s-na-palube/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2017.","music_adaptations":[],"source_synopsis":"На пароме, идущем на Камчатку, спят грузовики и краны, а на палубе танцуют вальс бахилы и кеды — все едут в крайний край, и никто не спрашивает «вы куда?», только «кем вы?».","main_image":"танец в рабочих башмаках на ночном пароме"},{"title":"Вальсок из детства","full_story":"На юбилее родственника взрослые держатся солидно, пока старая пластинка не ставит ту самую мелодию детства. Сначала все смеются, потом дядя с усами первым выходит в круг, и зал вспоминает, как танцевали в детстве, — ногами, руками и сердцем. В конце самый серьёзный гость произносит тост: отдай моё — и танец продолжают все.","hero_pov":"Гость праздника, первый вышедший в круг","central_conflict":"Взрослая солидность против танца, который требуют вернуть","emotional_arc":"От смущённых усмешек к общему кружению","ending_direction":"Самый серьёзный гость произносит тост — и танец продолжают все","hook_direction":"Отдай мне мальчишество","genres":["Шансон","Фолк"],"moods":["Ностальгия","Уверенность"],"energy":"Средняя","themes":["Танец","Детство"],"generator_brief":"Задорный шансон-вальсок с бабушкиной пластинкой в интро и стуком ладоней; припев — требование, которое все поддерживают.","generator_story":"На юбилее взрослые солидны, пока старая пластинка не ставит мелодию детства: дядя с усами первым выходит в круг, за ним весь зал. В конце самый серьёзный гость просит тостом вернуть мальчишество.","primary_genre":"Шансон","primary_mood":"Ностальгия","primary_theme":"Танец","story_shelf":"Юмор: семейные драмы","conflict_key":"детство-требует-своё","image_key":"вальсок-на-семейном-празднике","turn_key":"взрослые-танцуют-детство","hook_key":"отдай-мне-мальчишество","sort_order":"1306","original_key":"aleksandr-galich|staratelskiy-valsok","author_name":"Александр Галич","original_title":"Старательский вальсок","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://www.culture.ru/poems/3470/staratelskii-valsok","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1977.","music_adaptations":[],"source_synopsis":"Взрослые давно не платят мальчишеству дань и не ищут сказочные клады, но где-то в глубине им обещан их старательский вальсок — потерянный танец юности, который просится назад: отдай моё.","main_image":"вальсок на семейном празднике"},{"title":"Медленный вальс при свечах","full_story":"Выпускной вечер догорает по минутам, и объявляют последний вальс. Пара, которая весь год робела, решает не слышать гудок: их танец длится дольше объявленного, и сторож выключает не свет. На утро у обоих остаются свече на подоконнике и правило — при сейчас значит сейчас.","hero_pov":"Выпускник, не слышащий гудка","central_conflict":"Объявленный конец вечера против танца, который не кончается","emotional_arc":"От робких рук к свободе при сейчас","ending_direction":"Сторож гасит свет — танец продолжается в темноте","hook_direction":"Останемся на медленно","genres":["Поп-рок","Рок"],"moods":["Освобождение","Эйфория"],"energy":"Взрывная","themes":["Танец","любовь"],"generator_brief":"Вальсирующий поп-рок с живыми свечами-огоньками в звуке; куплеты — на цыпочках, припев — распахнутый вихрь.","generator_story":"На выпускном объявляют медленный вальс, и робевшая пара решает не слышать гудок: их танец дольше положенного, сторож гасит не свет. Утром у обоих свечи на подоконнике и правило — сейчас значит сейчас.","primary_genre":"Поп-рок","primary_mood":"Освобождение","primary_theme":"Танец","story_shelf":"Любовные сцены","conflict_key":"гудок-против-танца","image_key":"свечи-и-медленный-вальс","turn_key":"гудок-остаётся-за-дверью","hook_key":"остаёмся-на-медленно","sort_order":"1307","original_key":"andrey-voznesenskiy|val-s-pri-svechah","author_name":"Андрей Вознесенский","original_title":"Вальс при свечах","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/voznesenskiy/val-s-pri-svechah/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 2010.","music_adaptations":[],"source_synopsis":"Юность советует: любите при свечах, танцуйте до гудка, живите при сейчас. Царей можно искать-свистеть — дворцы сминаемы, а плечи всё свежи и несменяемы.","main_image":"свечи и медленный вальс на выпускном"},{"title":"Комната, в которой всё есть","full_story":"Человек с тревогой расписывает себе запреты: не выходи, не ешь незнакомого, не звони. Комната превращается в крепость, где он король и пленник одновременно. Когда из-за аварии гаснет свет и интернет, он впервые вынужден открыть дверь — и обнаруживает во дворе полных соседей, которые ждали его годами.","hero_pov":"Король и пленник одной комнаты","central_conflict":"Наклеенные запреты против мира за дверью","emotional_arc":"От fortress отчаяния к стыдливо-смешному освобождению","ending_direction":"Он открывает дверь сам — во двор выходят все","hook_direction":"Открою дверь сам","genres":["Альтернативный рок","Панк"],"moods":["Ирония","Тревога"],"energy":"Высокая","themes":["дом","Сила"],"generator_brief":"Нервный альт-рок с клик-клак часов и шёпотом инструкций в канале; припев — перечень запретов, ускоряющийся до срыва.","generator_story":"Тревожный человек расписывает запреты — не выходить, не звонить — и комната становится крепостью: он король и пленник. Когда авария гасит свет, он открывает дверь — во дворе годами ждали живые соседи.","primary_genre":"Альтернативный рок","primary_mood":"Ирония","primary_theme":"дом","story_shelf":"Юмор: семейные драмы","conflict_key":"страхи-против-открытой-двери","image_key":"стены-с-наклеенными-запретами","turn_key":"запреты-снимаются-самим-героем","hook_key":"открою-дверь-сам","sort_order":"1308","original_key":"iosif-brodskiy|ne-vyhodi-iz-komnaty","author_name":"Иосиф Бродский","original_title":"Не выходи из комнаты","original_language":"Russian","origin_country":"Россия","original_year":"1970","source_url":"https://ru.wikipedia.org/wiki/Бродский,_Иосиф_Александрович","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1996.","music_adaptations":[],"source_synopsis":"Абсурдная инструкция самому себе: не выходи из комнаты, не совершай ошибок, не сгибайся. Комната кажется защитой от всего мира, но мир без неё всё равно огромен.","main_image":"стены с наклеенными запретами"},{"title":"Кухня, где живёт всё живое","full_story":"После ссоры герой приезжает мириться к бабушке и попадает в её кухню, где пахнет супом и воском. Он не умеет говорить о важном, поэтому просто моет посуду, а бабушка рассказывает про соседей. К ночи он понимает, что всё святое — здесь: в чугунке, в занавеске, в общем молчании — и ссора растворяется сама.","hero_pov":"Внук, моющий посуду в бабушкиной кухне","central_conflict":"Городская ссора против дома, где всё освящено простотой","emotional_arc":"От неловкого молчания к тихому присутствию","ending_direction":"Он засыпает у печи — дом цел, и он тоже","hook_direction":"Всё живое на кухне","genres":["Фолк","Баллада"],"moods":["Тепло","Надежда"],"energy":"Низкая","themes":["дом","примирение"],"generator_brief":"Деревенский фолк с теплом печи в басах и скрипом половиц в ритме; голос — как рассказ у окна.","generator_story":"После ссоры внук приезжает к бабушке и не находит слов о важном — просто моет посуду, пока она рассказывает про соседей. К ночи ссора растворяется сама: всё святое здесь, на кухне с запахом супа.","primary_genre":"Фолк","primary_mood":"Тепло","primary_theme":"дом","story_shelf":"Любовные сцены","conflict_key":"насмешники-против-повсеместного-чуда","image_key":"пар-над-чугункой","turn_key":"посуда-освящает-дом","hook_key":"всё-живое-на-кухне","sort_order":"1309","original_key":"iosif-brodskiy|v-derevne-bog-zhivet","author_name":"Иосиф Бродский","original_title":"В деревне Бог живёт не по углам","original_language":"Russian","origin_country":"Россия","original_year":"1964","source_url":"https://math.berkeley.edu/~giventh/verse/countryside.pdf","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1996.","music_adaptations":[],"source_synopsis":"В деревне Бог живёт не по углам, как думают насмешники, а всюду: он освящает кровлю и посуду и честно делит двери пополам. Святое место — не алтарь, а вся простая изба с её чугункой и занавесками.","main_image":"пар над чугункой на деревенской кухне"},{"title":"Царство не для неё","full_story":"Герою предлагают остаться в сказочном подводном царстве с вечными россыпями — только без неё. Он перебирает все чудеса и находит в каждом отсутствие её голоса. В финале он отдаёт царство обратно морю и строит на берегу обычный дом, где самое богатое — её шаги на лестнице.","hero_pov":"Моряк, отказавшийся от царства","central_conflict":"Сказочные чудеса против простого дома с ней","emotional_arc":"От соблазна россыпей к тихой ясности выбора","ending_direction":"Он отдаёт царство морю и стучит топором на берегу","hook_direction":"Променяю царство на дом","genres":["Баллада","Рок"],"moods":["Любовь","Романтика"],"energy":"Средняя","themes":["дом","любовь"],"generator_brief":"Баллада-сказ с морской глубиной в звуке и обветренным голосом; куплеты — россыпи чудес, припев — дом на горе.","generator_story":"Моряку предлагают подводное царство — только без неё. Он перебирает чудеса и в каждом слышит отсутствие её голоса, отдаёт царство морю и строит дом, где самое богатое — её шаги на лестнице.","primary_genre":"Баллада","primary_mood":"Любовь","primary_theme":"дом","story_shelf":"Любовные сцены","conflict_key":"чудеса-против-простого-дома","image_key":"хрустальный-дом-над-морем","turn_key":"подводное-царство-променено","hook_key":"променяю-царство-на-дом","sort_order":"1310","original_key":"vladimir-vysockiy|dom-hrustalnyy","author_name":"Владимир Высоцкий","original_title":"Дом хрустальный","original_language":"Russian","origin_country":"Россия","original_year":"1967","source_url":"https://wysotsky.com/1049.htm","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1980.","music_adaptations":[],"source_synopsis":"Герой попал в подводное царство морского царя, где родники серебряные и золотые россыпи, — но ради любимой готов отказаться от всех чудес: хрустальный дом на горе — для неё.","main_image":"хрустальный дом над морем"},{"title":"Возвращение без улыбок","full_story":"Человек, которого судьба вынесла из страны и семьи, пишет домой письма с одной темой — когда я вернусь. Он заранее просит близких не смеяться над его съеденными городами и странными привычками: пусть лучше встретят молча. Финал — на пороге его действительно никто не смеётся: дома открывают дверь до стука.","hero_pov":"Изгнанник на пороге возвращения","central_conflict":"Годы изгнания против дома, который ждёт без улыбок","emotional_arc":"От выстраданных писем к тихому порогу","ending_direction":"Дверь открывают до стука — и он входит молча","hook_direction":"Встреть меня без смеха","genres":["Шансон","Баллада"],"moods":["Тоска","Надежда"],"energy":"Низкая","themes":["дом","расставание"],"generator_brief":"Пронзительный шансон с редкой гитарой и долгим эхом вокала; куплеты — письма, припев — порог.","generator_story":"Изгнанник пишет домой письма с одной темой — когда вернусь, — и просит не смеяться над съеденными городами и привычками. На пороге никто не смеётся: дверь открывают до стука, и он входит молча.","primary_genre":"Шансон","primary_mood":"Тоска","primary_theme":"дом","story_shelf":"Трагические истории","conflict_key":"изгнание-против-возвращения","image_key":"дорога-домой-через-годы","turn_key":"дверь-встречает-молча","hook_key":"встреть-меня-без-смеха","sort_order":"1311","original_key":"aleksandr-galich|kogda-ya-vernus","author_name":"Александр Галич","original_title":"Когда я вернусь","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://vtoraya-literatura.com/pdf/galich_kogda_ya_vernus_polnoe_sobranie_stikhov_i_pesen_1981__ocr.pdf","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1977.","music_adaptations":[],"source_synopsis":"Изгнанник всю жизнь носит с собой мечту о возвращении и просит близких: ты не смейся, когда я вернусь. Дорога домой — единственная, которую нельзя переписать заново.","main_image":"дорога домой через годы"},{"title":"Пустые танцы Ауберна","full_story":"Он возвращается на родную площадь и не находит никого: богатство соседних усадеб выдавило деревню, люди разъехались за море, двери школы и таверны заколочены. В голове у него всё ещё играет прежняя жизнь — вечера под развесистым дубом, смех, пары, кружившие в танце до темноты. Теперь танцы остались только в его памяти, а зелень заросла. Песня о танцах, которые живы, пока их кто-то помнит.","hero_pov":"вернувшийся односельчанин на опустевшей площади","central_conflict":"золото выжимает деревню","emotional_arc":"от тёплого воспоминания танцев к пустоте, которую уже не заполнить","ending_direction":"танцы остались в памяти одного человека — и умерли с ним","hook_direction":"поле помнит наши танцы","genres":["Блюз","Фолк"],"moods":["Одиночество","Тоска"],"energy":"Низкая","themes":["город","Танец"],"generator_brief":"Тихий блюз с деревенской скрипкой вдали: куплеты — заросшая площадь и закрытые двери, припев — ожившие в памяти танцы под дубом.","generator_story":"Вернувшись на родную площадь, он не находит никого: золото соседних усадеб выдавило деревню за море. Остались танцы в его памяти — пары под дубом, кружившие до темноты, — живые, пока их кто-то помнит.","primary_genre":"Блюз","primary_mood":"Одиночество","primary_theme":"город","story_shelf":"Трагические истории","conflict_key":"золото-выжимает-деревню","image_key":"одичавшая-площадь-ауберна","turn_key":"танцы-остались-только-в-памяти","hook_key":"поле-помнит-наши-танцы","sort_order":"1312","original_key":"oliver-goldsmith|the-deserted-village","author_name":"Оливер Голдсмит","original_title":"The Deserted Village","original_language":"English","origin_country":"Великобритания","original_year":"1770","source_url":"https://en.wikisource.org/wiki/The_Deserted_Village","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1774.","music_adaptations":[],"source_synopsis":"Поэт возвращается в родную деревню Ауберн и находит её опустевшей: богатство окрестных усадеб выжало крестьян, жители разъехались за море, школа и таверна закрылись. В памяти поэта деревня живёт прежней жизнью — молодые танцы под развесистым дубом, праздники, шумные вечера, — которой больше нет.","main_image":"одичавшая деревенская площадь, где когда-то танцевала молодёжь"},{"title":"Отшельник в дикой чаще","full_story":"Он ушёл от людей в дикую чаще — потерял любовь и решил, что никому больше не нужен. Странницы одна за другой находят его хижину: сначала он рассказывает свою беду, потом приходит она и рассказывает свою — о пропавшем женихе. Отшельник встаёт и обнимает гостью; она отталкивает незнакомца — и узнаёт голос. Песня о том, что отчаяние двоих может спрятаться в одной хижине — и выйти оттуда руками друг друга.","hero_pov":"пропавший жених, живущий как отшельник","central_conflict":"отчаяние встречает отчаяние","emotional_arc":"от двойного горя к узнаванию голоса и воссоединению","ending_direction":"отшельник раскрыл себя — двое выходят из чащи вместе","hook_direction":"я тот, кого ты ищешь","genres":["Кантри","Баллада"],"moods":["Радость","Надежда"],"energy":"Низкая","themes":["примирение","любовь"],"generator_brief":"Пасторальная баллада с акустикой и ночным сверчком: куплеты — две исповеди в хижине, припев — узнанный голос, который меняет всё.","generator_story":"Потеряв любовь, он ушёл отшельником в чащу, пока хижину не находит странница с бедой о пропавшем женихе. Она отталкивает обнявшего незнакомца — и узнаёт голос: двое отчаяний выходят из чащи вместе.","primary_genre":"Кантри","primary_mood":"Радость","primary_theme":"примирение","story_shelf":"Любовные сцены","conflict_key":"отчаяние-встречает-отчаяние","image_key":"отшельник-который-оказался-женихом","turn_key":"отшельник-раскрывает-себя","hook_key":"я-тот-кого-ты-ищешь","sort_order":"1313","original_key":"oliver-goldsmith|the-hermit","author_name":"Оливер Голдсмит","original_title":"The Hermit (Edwin and Angelina)","original_language":"English","origin_country":"Великобритания","original_year":"1765","source_url":"https://en.wikisource.org/wiki/The_Hermit","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1774.","music_adaptations":[],"source_synopsis":"Баллада: юноша Эдвин блуждает по дикой чаще в отчаянии по потерянной Анжелине и находит приют у отшельника. Затем приходит и сама Анжелина, рассказывая отшельнику о потерянной любви, — и отшельник обнимает её: он и есть Эдвин. Влюблённые воссоединяются.","main_image":"отшельник в хижине, который оказывается её пропавшим женихом"},{"title":"Кошка и золотые рыбки","full_story":"Любимица дома Селима вышла на прогулку вдоль ванны с золотыми рыбками — и дважды наклонилась за блеском. Второй раз край оказался скользким: она падает в воду, восемь раз поднимает лапы-гребла — и тонет, не позвав на помощь. Друзья напрасно бросаются с крючками и вёдрами: гордые не кричат о спасении. Песня-мораль: не всё золото стоит воды.","hero_pov":"рассказчик у ванны с рыбками","central_conflict":"роскошь топит любимицу","emotional_arc":"от лёгкой красоты к комической трагедии и морали","ending_direction":"гордые не просят спасения — это и есть их финал","hook_direction":"не всё золото стоит воды","genres":["Джаз","Классика"],"moods":["Ирония","Грусть"],"energy":"Средняя","themes":["сцена","животные"],"generator_brief":"Изысканный джаз с насмешливой скрипкой: куплеты — кошачий променад по краю ванны, припев — восемь лап и тишина вместо крика о помощи.","generator_story":"Кошка — любимица дома Селима — тянется за блеском золотых рыбок, и скользкий край ванны её топит: она восемь раз поднимает лапы и тонет, не позвав на помощь. Гордые не кричат о спасении.","primary_genre":"Джаз","primary_mood":"Ирония","primary_theme":"сцена","story_shelf":"Люди и животные","conflict_key":"роскошь-топит-любимицу","image_key":"кошка-над-золотыми-рыбками","turn_key":"тонет-не-позвав-на-помощь","hook_key":"не-всё-золото-стоит-воды","sort_order":"1314","original_key":"thomas-gray|ode-on-the-death-of-a-favourite-cat","author_name":"Томас Грей","original_title":"Ode on the Death of a Favourite Cat, Drowned in a Tub of Gold Fishes","original_language":"English","origin_country":"Великобритания","original_year":"1748","source_url":"https://en.wikisource.org/wiki/Ode_on_the_Death_of_a_Favourite_Cat,_Drowned_in_a_Tub_of_Gold_Fishes","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1771.","music_adaptations":[],"source_synopsis":"Шутливая ода-трагедия: любимица Селима идёт по краю ванны с золотыми рыбками, дважды падает и тонет — не позвав на помощь. Мораль: у кого золотая удочка в глазах, тот рискует; что кошке до рыб, то и человеку до зла.","main_image":"кошка над ванной с золотыми рыбками"},{"title":"Последний бард Уэльса","full_story":"Король с армией входит в завоёванную долину — и на утёсе стоит последний бард Уэльса: его собратья убиты, но его не уничтожили. Он поёт в лицо королю: песня вызывает из гор духов древних вождей, предрекает завоевателям гибель и позор, а спасённых — венчает правдой. Договорив, он шагает с утёса в реку — песня остаётся над страной. Песня о голосе, который сильнее армии и смерти.","hero_pov":"последний бард на краю скалы","central_conflict":"последний бард против двора-завоевателя","emotional_arc":"от одиночного вызова к проклятию, которое переживает прыжок","ending_direction":"прыжок в реку — песня остаётся над Уэльсом","hook_direction":"пока пою — страна жива","genres":["Метал","Эпик-рок"],"moods":["Злость","Грусть"],"energy":"Взрывная","themes":["сцена","смелость"],"generator_brief":"Мощный метал с арфой в интро и оркестровым штормом: куплеты — духи гор и приговор королю, финал — тишина после шага с утёса.","generator_story":"На утёсе завоёванной долины последний бард Уэльса поёт в лицо королю: песня зовёт духов древних вождей и предрекает захватчикам позор. Договорив, он шагает с утёса в реку — песня остаётся над страной.","primary_genre":"Метал","primary_mood":"Злость","primary_theme":"сцена","story_shelf":"Трагические истории","conflict_key":"последний-бард-против-двора","image_key":"бард-на-краю-скалы","turn_key":"песня-вызывает-призраков-с-гор","hook_key":"пока-пою-страна-жива","sort_order":"1315","original_key":"thomas-gray|the-bard","author_name":"Томас Грей","original_title":"The Bard. A Pindaric Ode","original_language":"English","origin_country":"Великобритания","original_year":"1757","source_url":"https://en.wikisource.org/wiki/The_Bard","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1771.","music_adaptations":[],"source_synopsis":"Последний валлийский бард стоит на краю скалы над армией Эдуарда, уничтожившей бардов, и поёт проклятие королю: песня вызывает духов древних героев, предрекает гибель завоевателям и венчает спасённых. Договорив, он бросается с утёса в реку.","main_image":"бард на краю скалы, поющий проклятие над армией"},{"title":"Молчание друга весной","full_story":"Утро сияет так же, как всегда: солнце встало для всех, жаворонки поют, поля цветут. Для него всё это звучит глухо — его друг умер молодым, и радости мира перестали разговаривать с ним. Слёзы — единственный дар, который он может принести памяти, и он приносит их без стыда. Песня о том, как весна продолжает петь для всех, кроме одного.","hero_pov":"переживший друга юноша","central_conflict":"весна цветёт — а друг умолк","emotional_arc":"от сияющего утра к тишине, в которой звучит только память","ending_direction":"все радости молчат о нём — слёзы честнее","hook_direction":"весна — и ты молчишь","genres":["R&B","Классика"],"moods":["Одиночество","Грусть"],"energy":"Низкая","themes":["дружба","Потеря"],"generator_brief":"Тихий R&B с сияющим мажором, который специально не совпадает с текстом: куплеты — цветущее утро, припев — глухая тишина для одного.","generator_story":"Утро сияет — жаворонки поют, поля цветут, — но для него всё глухо: друг умер молодым. Радости мира перестали с ним разговаривать, и слёзы — единственный дар памяти, который он приносит без стыда.","primary_genre":"R&B","primary_mood":"Одиночество","primary_theme":"дружба","story_shelf":"Трагические истории","conflict_key":"весна-цветёт-а-друг-умолк","image_key":"цветущее-утро-без-него","turn_key":"все-радости-молчат-о-нём","hook_key":"весна-и-ты-молчишь","sort_order":"1316","original_key":"thomas-gray|sonnet-on-the-death-of-mr-richard-west","author_name":"Томас Грей","original_title":"Sonnet on the Death of Mr. Richard West","original_language":"English","origin_country":"Великобритания","original_year":"1742","source_url":"https://en.wikisource.org/wiki/Sonnet_on_the_Death_of_Mr_Richard_West","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1771.","music_adaptations":[],"source_synopsis":"Сонет на смерть молодого друга Ричарда Уэста: утро сияет, солнце встаёт для всех, птицы поют и цветы распускаются — но для поэта всё беззвучно, потому что друга нет. Только слёзы честнее радостей.","main_image":"цветущее утро, в котором друга больше нет"},{"title":"Мальчики у Темзы","full_story":"С далёкого холма он смотрит на поля Этона: мальчики играют у реки, смеются, гоняют мяч — и не знают, что за каждой их забавой уже поджидает своя взрослая боль. Река несёт их весёлые крики вниз, а скорби выстроились молча в стороне. Он не хочет предупреждать — пусть неведение продлится ещё немного. Песня о последнем лете перед первой настоящей бедой.","hero_pov":"взрослый, глядящий на школу с холма","central_conflict":"играющие дети и ждущие боли","emotional_arc":"от светлой дали детства к молчаливой тревоге о будущем","ending_direction":"пусть играют — мы подождём","hook_direction":"пусть играют, пока играют","genres":["Джаз","Классика"],"moods":["Мечтательность","Напряжение"],"energy":"Средняя","themes":["город","детство"],"generator_brief":"Мечтательный джаз с шумом реки вдали: куплеты — игры мальчиков на поле, припев — взрослый взгляд с холма, который всё знает.","generator_story":"С холма взрослый смотрит на мальчиков у реки: они смеются, гоняют мяч, не зная, что за каждой забавой поджидает взрослая боль. Он не хочет предупреждать — пусть неведение продлится, скорби подождут.","primary_genre":"Джаз","primary_mood":"Мечтательность","primary_theme":"город","story_shelf":"Трагические истории","conflict_key":"играющие-дети-и-ждущие-боли","image_key":"мальчики-на-тамзенском-поле","turn_key":"за-игрой-поджидают-скорби","hook_key":"пусть-играют-пока-играют","sort_order":"1317","original_key":"thomas-gray|ode-on-a-distant-prospect-of-eton-college","author_name":"Томас Грей","original_title":"Ode on a Distant Prospect of Eton College","original_language":"English","origin_country":"Великобритания","original_year":"1747","source_url":"https://en.wikisource.org/wiki/Ode_on_a_Distant_Prospect_of_Eton_College","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1771.","music_adaptations":[],"source_synopsis":"Издалека поэт смотрит на школьные поля Этона, где мальчики играют у Темзы, — и знает, что за каждой игрой уже поджидают свои скорби: будущее не скажет им, какие беды ждут. Он просит время оставить их в неведении ещё немного.","main_image":"мальчики на тамзенском поле, видимые с далёкого холма"},{"title":"Сад в её лице","full_story":"В её лице разбит сад: розы на щеках, белые лилии, жемчужные глаза, а на губах — вишни, до которых никому нельзя дотянуться. Стражи сада не дремлют: ни ангелы, ни смельчаки не войдут, пока сами вишни не крикнут, что поспели. Он готов ждать у ограды сколько нужно — потому что ключ один, и он у неё. Песня о закрытом саде, который открывается только её словом.","hero_pov":"поклонник у ограды лица-сада","central_conflict":"в её лице — запрещённый сад","emotional_arc":"от восхищённой карты сада к терпеливому ожиданию её слова","ending_direction":"сад откроет она сама — и только она","hook_direction":"сад откроет она сама","genres":["R&B","Классика"],"moods":["Романтика","Любовь"],"energy":"Средняя","themes":["любовь","ожидание"],"generator_brief":"Чувственный R&B с садовыми переливами: куплеты — карта сада на её лице, припев — вишни, которые кричат «спелые» только её голосом.","generator_story":"В её лице разбит сад: розы на щеках, белые лилии, вишни на губах. Ни ангелы, ни смельчаки не войдут, пока вишни не крикнут, что поспели, — и он готов ждать у ограды, ведь ключ один, у неё.","primary_genre":"R&B","primary_mood":"Романтика","primary_theme":"любовь","story_shelf":"Любовные сцены","conflict_key":"в-её-лице-запрещённый-сад","image_key":"вишни-на-губах-и-розы-на-щёках","turn_key":"никто-не-войдёт-пока-она-сама-не-скажет","hook_key":"сад-откроет-она-сама","sort_order":"1318","original_key":"thomas-campion|there-is-a-garden-in-her-face","author_name":"Томас Кэмпион","original_title":"There is a Garden in Her Face","original_language":"English","origin_country":"Великобритания","original_year":"1617","source_url":"https://www.poemhunter.com/poem/there-is-a-garden-in-her-face/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1620.","music_adaptations":[],"source_synopsis":"Песня-картина: в её лице растёт сад — розы на щеках, белые лилии лба, жемчуг и вишни губ. Никто не может войти в этот сад и сорвать вишни, пока они сами не крикнут «черри-райп» — только её слово открывает сад.","main_image":"сад в её лице с вишнями губ, которые сами кричат «спелые»"},{"title":"Лютня Коринны","full_story":"Когда Коринна берёт лютню и поёт о радости, инструмент оживает и отвечает ей голос за голос. Когда она поёт о горе — струны рвутся под её пальцами. И тогда рвётся то, что внутри него: его сердце настроено точно в тон её лютни. Он просит её не петь о горе — не рви ни своих струн, ни моих. Песня о человеке, настроенном в тона любимой.","hero_pov":"слушатель, настроенный в тон её лютни","central_conflict":"её песня рвёт струны в его груди","emotional_arc":"от оживающей радости к рваным струнам и просьбе о доброй песне","ending_direction":"пой о добром — и мы оба зазвучим целыми","hook_direction":"не пой о горе — струны рвутся","genres":["Джаз","Классика"],"moods":["Вдохновение","Нежность"],"energy":"Высокая","themes":["сцена","музыка"],"generator_brief":"Лютневый джаз-дуэт: куплеты — живой ответ инструмента её голосу, припев — момент, когда струны рвутся в двух руках сразу.","generator_story":"Когда Коринна поёт о радости, лютня оживает, но горькая песня лопает струны. Сердце слушателя настроено в тон её лютни и рвётся вместе с ними, — он просит петь о добром, чтобы оба зазвучали целыми.","primary_genre":"Джаз","primary_mood":"Вдохновение","primary_theme":"сцена","story_shelf":"Любовные сцены","conflict_key":"её-песня-рвёт-струны-в-его-груди","image_key":"лютня-отвечает-коринне","turn_key":"страсть-и-плачь-рвут-струны-дважды","hook_key":"не-пой-о-горе-струны-рвутся","sort_order":"1319","original_key":"thomas-campion|when-to-her-lute-corinna-sings","author_name":"Томас Кэмпион","original_title":"When to Her Lute Corinna Sings","original_language":"English","origin_country":"Великобритания","original_year":"1601","source_url":"https://www.poemhunter.com/poem/when-to-her-lute-corinna-sings/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1620.","music_adaptations":[],"source_synopsis":"Когда Коринна поёт под лютню, инструмент отвечает и оживает; когда она поёт о печали — струны рвутся, и в сердце слушателя рвутся свои. Он просит её не петь о горе: не рви ни своих струн, ни моих.","main_image":"лютня, отвечающая голосу Коринны"},{"title":"Пусть зима — мы танцуем","full_story":"Зимние ночи становятся длиннее, буря бьёт в башни, и по всей стране гаснут окна. А в его доме начинается ответ: камины пылают, чаши переполнены, песни идут одна за другой — и он объявляет танец. Пусть ночь тянет свои часы — мы растянем веселье до рассвета. Песня-вызов самому тёмному времени года.","hero_pov":"хозяин зимнего пира","central_conflict":"долгая ночь и огонь в очаге","emotional_arc":"от наступающей темноты к разгорающемуся празднику","ending_direction":"ночь длиннее — значит, мы танцуем дольше","hook_direction":"пусть зима, пусть — танцуем","genres":["Панк","Джаз"],"moods":["Эйфория","Тепло"],"energy":"Взрывная","themes":["Танец","Праздник"],"generator_brief":"Разгульный панк-пир с кельтской скрипкой: куплеты — storm в башни и длинные часы, припев — камин, вино и приказ «пусть начнётся танец».","generator_story":"Зимние ночи длиннее, буря бьёт в башни, по стране гаснут окна — а в его доме пылают камины, переполнены чаши, и он объявляет танец. Пусть ночь тянет свои часы: они растянут веселье до рассвета.","primary_genre":"Панк","primary_mood":"Эйфория","primary_theme":"Танец","story_shelf":"Юмор: семейные драмы","conflict_key":"долгая-ночь-и-огонь-в-очаге","image_key":"камин-вино-и-танцы-до-утра","turn_key":"пусть-длиннее-ночь-мы-ответили-танцем","hook_key":"пусть-зима-мы-танцуем","sort_order":"1320","original_key":"thomas-campion|now-winter-nights-enlarge","author_name":"Томас Кэмпион","original_title":"Now Winter Nights Enlarge","original_language":"English","origin_country":"Великобритания","original_year":"","source_url":"https://poets.org/poem/now-winter-nights-enlarge","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1620.","music_adaptations":[],"source_synopsis":"Зимние ночи длинны, бури бьют в башни — и на это есть ответ: пусть пылают камины, пусть переливается вино, пусть поют и танцуют. Холод и сумерки получают в ответ огонь, песни и танец до утра.","main_image":"камин, вино и танцы против длинной зимней ночи"},{"title":"Приглашение на ужин","full_story":"Он приглашает друга на простой ужин: оливки, салат, мutton, сыр и канарское вино, — и обещает, что вечер будет без пьяных скандалов и без слов, за которые утром станет стыдно. За столом читают Вергилия вслух и говорят обо всём свободно. А чтобы друг точно пришёл, он признаётся честно: я расскажу про побольше блюд и немножко совру — только приходи. Песня о дружбе, ради которой можно чуть-чуть приврать.","hero_pov":"хозяин скромного честного стола","central_conflict":"скромный стол и честный разговор","emotional_arc":"от скромного приглашения к тёплому признанию в белой лжи ради друга","ending_direction":"пусть соврёт о блюдах — лишь бы друг пришёл к честному столу","hook_direction":"сегодня ужин только для тебя","genres":["Соул","Кантри"],"moods":["Тепло","Радость"],"energy":"Высокая","themes":["дружба","дом"],"generator_brief":"Тёплый соул с домашним ритмом и смехом в бэках: куплеты — меню и правила вечера, припев — признание, что хозяин немножко приврал ради гостя.","generator_story":"Хозяин скромного ужина зовёт друга на оливки, сыр и канарское вино, обещая вечер без скандалов, а за столом — Вергилия вслух. Чтобы друг точно пришёл, он признаётся: про блюда он немножко соврёт.","primary_genre":"Соул","primary_mood":"Тепло","primary_theme":"дружба","story_shelf":"Юмор: семейные драмы","conflict_key":"скромный-стол-и-честный-разговор","image_key":"канарское-вино-и-вергилий-вслух","turn_key":"я-преувеличу-лишь-бы-ты-пришёл","hook_key":"сегодня-ужин-только-для-тебя","sort_order":"1321","original_key":"ben-jonson|inviting-a-friend-to-supper","author_name":"Бен Джонсон","original_title":"Inviting a Friend to Supper","original_language":"English","origin_country":"Великобритания","original_year":"1616","source_url":"https://www.poemhunter.com/poem/inviting-a-friend-to-supper/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1637.","music_adaptations":[],"source_synopsis":"Приглашение другу на ужин: скромная еда, хорошее канарское вино, чтение Вергилия и Тацита вслух, свободный разговор — и обещание: никакого пьяного буйства, никаких слов, о которых утром будет стыдно. А чтобы гость точно пришёл, хозяин признаётся, что немножко преувеличит меню.","main_image":"канарское вино и Вергилий вслух за скромным столом"},{"title":"Прощай, моя лучшая строка","full_story":"Ему было семь лет — и он был лучшим, что отец написал в жизни. Отец прощается коротко, как прощаются со своим лучшим произведением: ты был моей лучшей строкой, и сейчас я положу тебя в землю. Он клянётся страшной клятвой: больше никогда не любить ничего так сильно, чтобы потеря рвала пополам. Песня о родительской любви, которая стыдится собственной силы.","hero_pov":"отец над могилой сына","central_conflict":"лучшее произведение отца похоронено им самим","emotional_arc":"от прощания к страшной клятве не любить слишком сильно","ending_direction":"любить впредь — так, чтобы потеря не рвала пополам","hook_direction":"прощай, моя лучшая строка","genres":["Блюз","Классика"],"moods":["Грусть","Любовь"],"energy":"Низкая","themes":["расставание","семья"],"generator_brief":"Голый блюз без ударных: один голос, одно пианино; припев — клятва, произнесённая так ровно, что слышно, как она ломается.","generator_story":"Отец хоронит семилетнего сына — лучшее, что он создал в жизни, — и прощается, как прощаются с лучшим произведением. Он клянётся: больше никогда не любить так сильно, чтобы потеря рвала пополам.","primary_genre":"Блюз","primary_mood":"Грусть","primary_theme":"расставание","story_shelf":"Трагические истории","conflict_key":"лучшее-произведение-отца-похоронено","image_key":"сын-как-строка-отца","turn_key":"клятва-не-любить-слишком-сильно","hook_key":"прощай-моя-лучшая-строка","sort_order":"1322","original_key":"ben-jonson|on-my-first-son","author_name":"Бен Джонсон","original_title":"On My First Son","original_language":"English","origin_country":"Великобритания","original_year":"1616","source_url":"https://en.wikisource.org/wiki/On_My_First_Son","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1637.","music_adaptations":[],"source_synopsis":"Эпитафия умершему маленькому сыну: прощай, ребёнок всех радостей — моя лучшая «поэма»; отец клянётся впредь любить так, чтобы не нравиться сильному слишком.","main_image":"сын — лучшая строка отца"},{"title":"Шёпот за занавесом","full_story":"Он был самым маленьким в труппе королевы — мальчик, который играл стариков лучше стариков, и зал знал его голос раньше имён. Смерть пришла до его первой большой роли, и занавес, который обещал ему целую сцену, закрылся сам. Автора просят плакать вместе с театром: сцене не хватило ровно одного человека. Песня об актёре, чей единственный спектакль — его жизнь.","hero_pov":"театральный автор, прощающийся с мальчиком-актёром","central_conflict":"маленький актёр ушёл со сцены навсегда","emotional_arc":"от памяти о его ролях к пустому занавесу, который не выпустит никого","ending_direction":"сцена потеряла лучшего — шёпот за занавесом остался","hook_direction":"он ушёл — а занавес молчит","genres":["Джаз","Классика"],"moods":["Нежность","Светлая грусть"],"energy":"Низкая","themes":["сцена","Потеря"],"generator_brief":"Театральный джаз со шёпотом кулис: куплеты — мальчик, игравший стариков, припев — закрытый занавес, за которым уже никого нет.","generator_story":"Мальчик — самый маленький в труппе королевы — играл стариков лучше стариков, но умер до первой большой роли. Занавес закрылся сам: сцене не хватило одного человека, а его голос зал знал раньше имён.","primary_genre":"Джаз","primary_mood":"Нежность","primary_theme":"сцена","story_shelf":"Трагические истории","conflict_key":"маленький-актёр-ушёл-со-сцены","image_key":"мальчик-игравший-стариков","turn_key":"смерть-забрала-лучшего-игрока","hook_key":"он-ушёл-а-занавес-молчит","sort_order":"1323","original_key":"ben-jonson|epitaph-on-s-p-a-child","author_name":"Бен Джонсон","original_title":"Epitaph on S. P., a Child of Queen Elizabeth's Chapel","original_language":"English","origin_country":"Великобритания","original_year":"1616","source_url":"https://www.poemhunter.com/poem/epitaph-on-s-p-a-child-of-queen-elizabeth-s-chapel/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1637.","music_adaptations":[],"source_synopsis":"Эпитафия мальчику-актёру детской труппы королевы: он умер до того, как смог выйти в большие роли, — и сама сцена потеряла лучшего своего маленького игрока. Читателя просят плакать вместе со сценой.","main_image":"мальчик-актёр, которого занавес больше не выпустит"},{"title":"Гляди в сердце и пиши","full_story":"Он хочет выиграть её внимание стихами и делает всё по учебнику: изучает чужие удачные приёмы, гоняет рифмы, кусает тр jMenuItemckoe перо — и строки выходят мёртвыми. Отчаявшись, он слышит голос музы: дурачок — гляди в своё сердце и пиши. Вся техника не стоит одной правды из груди. Песня о моменте, когда приёмы сдаются настоящему.","hero_pov":"поэт, застрявший между приёмами и правдой","central_conflict":"изученные приёмы против живого сердца","emotional_arc":"от книжной возни к одному резкому слову музы","ending_direction":"гляди в сердце и пиши — остальное приложится","hook_direction":"гляди в сердце и пиши","genres":["Соул","Классика"],"moods":["Вдохновение","Романтика"],"energy":"Средняя","themes":["любовь","призвание"],"generator_brief":"Душевный соул с бумажным шелестом и пером в ритме: куплеты — книжная возня и мёртвые строки, припев — короткий голос музы, который сносит всё.","generator_story":"Поэт, добиваясь её внимания, гоняет рифмы по учебнику — но строки выходят мёртвыми. Отчаявшись, он слышит голос музы: вся техника не стоит одной правды из груди — пиши сердцем, остальное приложится.","primary_genre":"Соул","primary_mood":"Вдохновение","primary_theme":"любовь","story_shelf":"Любовные сцены","conflict_key":"изученные-приёмы-против-живого-сердца","image_key":"муза-говорит-гляди-в-сердце","turn_key":"глупец-гляди-в-сердце-и-пиши","hook_key":"гляди-в-сердце-и-пиши","sort_order":"1324","original_key":"philip-sidney|astrophil-and-stella-1","author_name":"Филип Сидни","original_title":"Astrophil and Stella, Sonnet 1 (Loving in truth...)","original_language":"English","origin_country":"Великобритания","original_year":"1591","source_url":"https://www.poetryfoundation.org/poems/45152/astrophil-and-stella-1-loving-in-truth-and-fain-in-verse-my-love-to-show","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1586.","music_adaptations":[],"source_synopsis":"Поэт изучает чужие приёмы, изобретает, перечитывает свои строки, чтобы слагами стихов выиграть внимание любимой, — и мучится. Пока муза не говорит ему резко: дурачок, гляди в своё сердце и пиши.","main_image":"муза, говорящая поэту: гляди в сердце и пиши"},{"title":"Отпусти меня, любовь","full_story":"Он говорит с любовью как с гостем, которого пора отпустить: ты дошла только до праха, а я вырос из твоих границ. Он велит своему уму копить то, что не ржавеет, и складывать крылья — от всего, что увядает. Прощай, мир: твои грабли не собирают того, что дольше sorrow. Песня о расставании с самой любовью ради роста.","hero_pov":"человек, отпускающий земную любовь","central_conflict":"любовь до праха и рост в вечное","emotional_arc":"от прощания с земным к спокойному взлёту над ржавеющим","ending_direction":"отпустить всё, что увядает, — и идти выше","hook_direction":"отпусти меня, любовь","genres":["Метал","Классика"],"moods":["Освобождение","Сила"],"energy":"Низкая","themes":["расставание","свобода"],"generator_brief":"Строгий метал с колокольным чистым голосом: куплеты — прощание с ржавеющим, припев — складывающиеся крылья и подъём над миром.","generator_story":"Он прощается с любовью как с гостем, чья власть кончилась: она дошла лишь до праха, а он вырос за её границами. Уму он велит копить то, что не ржавеет, и отпустить всё, что увядает, — и идти выше.","primary_genre":"Метал","primary_mood":"Освобождение","primary_theme":"расставание","story_shelf":"Трагические истории","conflict_key":"любовь-до-праха-и-рост-в-вечное","image_key":"ржавчина-и-крылья","turn_key":"отпускаю-всё-что-ржавеет","hook_key":"отпусти-меня-любовь","sort_order":"1325","original_key":"philip-sidney|leave-me-o-love","author_name":"Филип Сидни","original_title":"Leave me, O Love, which reachest but to dust","original_language":"English","origin_country":"Великобритания","original_year":"1591","source_url":"https://www.poetryfoundation.org/poems/45167/leave-me-o-love-which-reachest-but-to-dust","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1586.","music_adaptations":[],"source_synopsis":"Сонет-отречение: поэт велит земной любви, которая доходит только до праха, оставить его — и велит своему уму стремиться к тому, что не ржавеет. Всё, что увядает, приносит лишь увядающее удовольствие; прощай, мир.","main_image":"крылья, складывающие прах, ради ржавчины, которой нет"},{"title":"Последний поцелуй Купидона","full_story":"Они решают расстаться по-взрослому: раз помощи нет — поцелуем и разойтись, пожать руки навсегда, отменить все обеты, угасить страсть и веру. Любовь лежит при смерти, и они стоят у её одра как свидетели. Но в самый последний момент он оставляет дверь: если ты захочешь, когда все его похоронят, — последним поцелуем ты можешь поднять его из смерти в жизнь. Песня о расставании, в котором спрятано «ещё не всё».","hero_pov":"человек у одра умирающей любви","central_conflict":"рукопожатие навсегда и последний поцелуй","emotional_arc":"от церемонии расставания к открытой двери воскресения","ending_direction":"все его похоронили — а ты ещё можешь поднять","hook_direction":"поцелуй — и он оживёт","genres":["R&B","Классика"],"moods":["Уязвимость","Надежда"],"energy":"Низкая","themes":["примирение","любовь"],"generator_brief":"Тихий R&B у постели: куплеты — церемония отмены обетов, припев — почти шёпот, в котором спрятана возможность всё вернуть.","generator_story":"Двое расстаются по-взрослому: рукопожатие навсегда, обеты отменены, любовь лежит при смерти. Но он оставляет дверь: последним поцелуем у её одра любовь ещё можно поднять из смерти в жизнь.","primary_genre":"R&B","primary_mood":"Уязвимость","primary_theme":"примирение","story_shelf":"Любовные сцены","conflict_key":"рукопожатие-навсегда-и-последний-поцелуй","image_key":"умирающая-любовь-на-подушках","turn_key":"последний-поцелуй-может-воскресить","hook_key":"поцелуй-и-он-оживёт","sort_order":"1326","original_key":"michael-drayton|since-theres-no-help","author_name":"Майкл Дрейтон","original_title":"Idea, Sonnet 61 (Since there's no help...)","original_language":"English","origin_country":"Великобритания","original_year":"1619","source_url":"https://www.poemhunter.com/poem/sonnet-lxi-since-there-s-no-help/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1631.","music_adaptations":[],"source_synopsis":"Последний сонет о конце любви: раз помощи нет — поцелуем расстанемся, пожмём руки навсегда, отменим все обеты. Любовь лежит при смерти — но в последних строках остаётся дверь: если ты захочешь, когда все его уже похоронили, ты можешь поднять его из смерти в жизнь последним поцелуем.","main_image":"умирающая любовь на подушках и последний поцелуй"},{"title":"Паруса в Виргинию","full_story":"Он провожает флот, который плывёт строить новую жизнь на чужом берегу: храбрые сердца, ваше имя — ваша работа, и работа эта — океан. Пусть ветер наполнит паруса и бог донесёт вас целыми до земли, где ещё нет ни дорог, ни имён. Песня о людях, которые ушли делать дело, на которое решились.","hero_pov":"провожающий флот на новом деле","central_conflict":"героические сердца и дальняя земля","emotional_arc":"от прощания на причале к напутствию, которое звучит как благословение","ending_direction":"ветер донесёт их — работа начнётся на другом берегу","hook_direction":"в путь — за новым берегом","genres":["Эпик-рок","Фолк"],"moods":["Смелость","Драйв"],"energy":"Высокая","themes":["работа","Дорога"],"generator_brief":"Величественный эпик-рок с парусным ритмом и хором: куплеты — напутствие на причале, припев — паруса, которые берут ветер и уходят.","generator_story":"Он провожает флот к земле, где ещё нет ни дорог, ни имён: ваше имя — ваша работа, а работа — океан. Прощание — как благословение: пусть ветер наполнит паруса и донесёт вас целыми до другого берега.","primary_genre":"Эпик-рок","primary_mood":"Смелость","primary_theme":"работа","story_shelf":"Трагические истории","conflict_key":"героические-сердца-и-дальняя-земля","image_key":"паруса-на-девственный-берег","turn_key":"работа-начнётся-на-другом-берегу","hook_key":"в-путь-за-новым-берегом","sort_order":"1327","original_key":"michael-drayton|to-the-virginian-voyage","author_name":"Майкл Дрейтон","original_title":"To the Virginian Voyage","original_language":"English","origin_country":"Великобритания","original_year":"1606","source_url":"https://en.wikisource.org/wiki/To_the_Virginian_Voyage","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1631.","music_adaptations":[],"source_synopsis":"Напутствие отплывающим в Виргинию: храбрые сердца, достойные своей страны, — ваше дело переплыть океан и положить начало новому миру; да приведёт вас бог безопасно к девственному берегу.","main_image":"паруса, идущие к девственному берегу"},{"title":"Загнанный олень сдался","full_story":"Он гонялся за ней долго — глазами, словами, надеждами, — и вот зверь измучен и покорился: она сама возвращается к нему, как загнанный олень к охотнику. Он опускает оружие: война кончилась не победой, а тем, что она пришла сама. Песня о примирении, которое начинается с опущенных рук.","hero_pov":"охотник, опустивший оружие перед пришедшей самой","central_conflict":"загнанный олень и опущенная рука","emotional_arc":"от долгой погони к тишине, в которую она вернулась сама","ending_direction":"война любви кончилась не победой, а её приходом","hook_direction":"она подошла сама","genres":["Кантри","Классика"],"moods":["Нежность","Радость"],"energy":"Средняя","themes":["примирение","любовь"],"generator_brief":"Пасторальное кантри с ровной погоней в куплетах: припев — полная тишина, опущенное оружие и шаги, идущие к нему сами.","generator_story":"Он долго гонялся за ней глазами, словами и надеждами — и зверь сдался: она возвращается к нему сама, как загнанный олень к охотнику. Он опускает оружие: война кончилась не победой, а её приходом.","primary_genre":"Кантри","primary_mood":"Нежность","primary_theme":"примирение","story_shelf":"Любовные сцены","conflict_key":"загнанный-олень-и-опущенная-рука","image_key":"олень-возвращается-к-охотнику","turn_key":"война-любви-кончилась-сдачей","hook_key":"она-подошла-сама","sort_order":"1328","original_key":"edmund-spenser|amoretti-67","author_name":"Эдмунд Спенсер","original_title":"Amoretti, Sonnet 67 (Lyke as a huntsman...)","original_language":"English","origin_country":"Великобритания","original_year":"1595","source_url":"https://www.poemhunter.com/edmund-spenser/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1599.","music_adaptations":[],"source_synopsis":"Аллегория любви как охоты: охотник после изнурительной погони наконец измучил оленя, и зверь, покорившись, возвращается к нему сам. Так и возлюбленная, устав от войны глаз и слов, сама отдаётся — и охотник откладывает оружие.","main_image":"загнанный олень, возвращающийся к опустившему ружьё охотнику"},{"title":"Звезда над штормом","full_story":"Его несёт по широкому океану — шторм за штормом, тоска за тоской, — и звёзды спрятались за облаками. Но одна звезда светит сквозь мрак: её взгляд, к которому он держит курс, когда всё остальное скрыто. Корабль трещит, но не сворачивает: за штормом обещана радость. Песня о человеке, который ведёт судно по одной-единственной звезде.","hero_pov":"рулевой корабля в шторме","central_conflict":"шторм и звезда её глаз","emotional_arc":"от слепого бунта волн к твёрдому курсу на единственный свет","ending_direction":"сквозь мрак — с надеждой на тихую радость за штормом","hook_direction":"смотри на мою звезду","genres":["Эпик-рок","Классика"],"moods":["Уверенность","Надежда"],"energy":"Высокая","themes":["любовь","Море"],"generator_brief":"Морской эпик-рок с рёвом волн и пробивающейся звездой в аранжировке: куплеты — штормы, припев — один неподвижный свет над мачтой.","generator_story":"Шторм за штормом несёт его корабль по океану, звёзды спрятались за облаками — и только её взгляд светит сквозь мрак. Корабль трещит, но не сворачивает с курса: за штормом обещана тихая радость.","primary_genre":"Эпик-рок","primary_mood":"Уверенность","primary_theme":"любовь","story_shelf":"Любовные сцены","conflict_key":"шторм-и-звезда-её-глаз","image_key":"корабль-мчится-мимо-звезды","turn_key":"звезда-руководит-сквозь-печаль","hook_key":"смотри-на-мою-звезду","sort_order":"1329","original_key":"edmund-spenser|amoretti-34","author_name":"Эдмунд Спенсер","original_title":"Amoretti, Sonnet 34 (Lyke as a ship...)","original_language":"English","origin_country":"Великобритания","original_year":"1595","source_url":"https://www.poemhunter.com/edmund-spenser/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1599.","music_adaptations":[],"source_synopsis":"Корабль несётся через широкий океан, гонимый штормами и печалями, — звёзды прячутся в облаках. Но в небе светит одна звезда, вид её глаз, — и корабль держит курс на неё сквозь мрак с надеждой на радость.","main_image":"корабль в шторме, держащий курс на одну звезду"},{"title":"Улисс и сирена","full_story":"Сирена поёт ему про покой: оставь вёсла, у меня любовь без труда, а честь — мнение чужих людей. Он отвечает без единой верёвки: без труда радость не стоит ничего, благородные утешаются опасностью, а нечестный мир хуже честной войны. Сирена сдаётся: я не могу победить — я должна быть завоёванной. Песня-дуэль о том, что покой не покупает сильных.","hero_pov":"Улисс, отвечающий сирене на её песню","central_conflict":"сирина зовёт к покою — он выбирает труд","emotional_arc":"от сладкого соблазна к твёрдому отказу и капитуляции сирены","ending_direction":"покой не купит сильных — она должна быть завоёванной","hook_direction":"покой меня не купит","genres":["Панк","Классика"],"moods":["Уверенность","Смелость"],"energy":"Взрывная","themes":["работа","смелость"],"generator_brief":"Дуэт-поединок: сладкий вокал сирены против ровного грубого голоса Улисса; без верёвок и воска — только слова, которыми он её побеждает.","generator_story":"Сирена поёт Улиссу про покой: оставь вёсла, любовь без труда. Он отвечает без верёвок: без труда радость ничего не стоит, а нечестный мир хуже честной войны — и сирена сдаётся, чтобы быть завоёванной.","primary_genre":"Панк","primary_mood":"Уверенность","primary_theme":"работа","story_shelf":"Трагические истории","conflict_key":"сирина-зовёт-к-покою-он-выбирает-труд","image_key":"улисс-несвязанный-отвечает-сирене","turn_key":"труд-даёт-цену-радости","hook_key":"покой-меня-не-купит","sort_order":"1330","original_key":"samuel-daniel|ulysses-and-the-siren","author_name":"Сэмюэл Даниэль","original_title":"Ulysses and the Siren","original_language":"English","origin_country":"Великобритания","original_year":"","source_url":"https://www.poemhunter.com/poem/ulysses-and-the-siren/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1619.","music_adaptations":[],"source_synopsis":"Поющая пьеса-диалог: сирена обещает Улиссу покой, лёгкость и любовь без труда — честь, мол, лишь мнение чужих. Улисс отвечает: труд даёт цену радости, благородные находят утешение в опасности, а нечестный мир лучше купить покоем. В конце сирена признаёт: я должна быть завоёванной, я не могу победить.","main_image":"Улисс, отвечающий сирене без единой верёвки"},{"title":"Усыпитель горя","full_story":"Он устал от горя так, что молит о сне как о последнем лекарстве: успокоитель забот, сын чёрной ночи, брат смерти — приди и закрой мои глаза. Он просит не будить его днём: пусть дневное презрение пройдёт мимо спящего, и ты уведи меня туда, где мне не будет стыдно, что я живу без ответа. Песня о сне, который единственный не задаёт вопросов.","hero_pov":"безответно любящий, молящийся о сне","central_conflict":"сон как единственное лекарство горя","emotional_arc":"от измотанной мольбы к благодарной темноте без вопросов","ending_direction":"сон уводит туда, где не стыдно жить без ответа","hook_direction":"дай уснуть хоть до утра","genres":["R&B","Классика"],"moods":["Тоска","Уязвимость"],"energy":"Низкая","themes":["расставание","сцена"],"generator_brief":"Колыбельный R&B без барабанов: куплеты — мольба ко сну с именами его родни, припев — тихая темнота, в которой никто не задаёт вопросов.","generator_story":"Безответно любящий просит ночь усыпить его горе: приди, брат смерти, закрой мои глаза и не буди днём. Сон — единственный, кто не задаёт вопросов: он уводит туда, где не стыдно жить без ответа.","primary_genre":"R&B","primary_mood":"Тоска","primary_theme":"расставание","story_shelf":"Трагические истории","conflict_key":"сон-как-единственное-лекарство-горя","image_key":"сон-сын-чёрной-ночи","turn_key":"укрой-меня-от-дневного-презрения","hook_key":"дай-уснуть-хоть-до-утра","sort_order":"1331","original_key":"samuel-daniel|care-charmer-sleep","author_name":"Сэмюэл Даниэль","original_title":"Delia, Sonnet 45 (Care-charmer Sleep...)","original_language":"English","origin_country":"Великобритания","original_year":"1592","source_url":"https://www.poemhunter.com/poem/delia-xlv-care-charmer-sleep-son-of-the-sable-ni/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1619.","music_adaptations":[],"source_synopsis":"Сонет-мольба ко сну: успокоитель забот, сын чёрной ночи, брат смерти — приди и закрой глаза уставшему от горя. Пусть дневное презрение не коснётся спящего, а ты, сон, уведи меня туда, где не стыдно быть безответным.","main_image":"сон, сын чёрной ночи, над уставшим от горя"},{"title":"Королева мая","full_story":"Один день в году деревня делает девушку королевой: венок, ленты, хоровод от площади до леса — и она правит ровно сутки. Весь майский день деревня живёт как один голос: музыка, танцы, смех, феи в тени деревьев. Королева знает, что завтра снова будет простой девчонкой, — но сегодня танцы не кончаются. Песня о деревне, которая раз в год делает одну из своих королевой.","hero_pov":"королева мая на один день","central_conflict":"деревня выбирает королеву мая","emotional_arc":"от выбора и венка к танцам, которые не кончаются до темноты","ending_direction":"править сутки — и снова стать своей в хороводе","hook_direction":"королева мая — наша","genres":["Кантри","Фолк"],"moods":["Эйфория","Радость"],"energy":"Высокая","themes":["Танец","Праздник"],"generator_brief":"Майский деревенский кантри-пир: куплеты — выбор королевы и венок, припев — хоровод, который несёт всю деревню как одну реку.","generator_story":"Раз в год деревня делает девушку королевой на сутки: венок, ленты, хоровод от площади до леса. Завтра она снова станет простой девчонкой, но сегодня танцы и смех не кончаются до темноты.","primary_genre":"Кантри","primary_mood":"Эйфория","primary_theme":"Танец","story_shelf":"Юмор: семейные драмы","conflict_key":"деревня-выбирает-королеву-мая","image_key":"венок-мая-на-голове-девушки","turn_key":"деревня-танцует-вокруг-своей-королевы","hook_key":"королева-мая-наша","sort_order":"1332","original_key":"george-darley|sylvia-or-the-may-queen","author_name":"Джордж Дарли","original_title":"Sylvia; or, The May Queen","original_language":"English","origin_country":"Ирландия","original_year":"1827","source_url":"https://archive.org/details/poemsoflategeorg00darl","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1846.","music_adaptations":[],"source_synopsis":"Лирическая драма-маска про деревенский день мая: сельчане выбирают королеву мая, венчают её венком, вся деревня танцует майские танцы в лесу и на лугу — полу сказка, полу лесной праздник с музыкой и хороводами.","main_image":"венок мая на голове деревенской королевы"},{"title":"Вечерняя песнь дев моря","full_story":"Полночь и отлив зовут морских дев домой: «троуп домой» — в тихие гроты и пещеры, где нет ни ветра, ни людей. Они уходят с поверхности, подражая звукам умирающих волн, — и море закрывается над ними, как дверь. Песня о том, как целый народ уходит домой, напевая, чтобы никто не заметил.","hero_pov":"голос моря, зовущий дев домой","central_conflict":"полночь зовёт морских дев домой","emotional_arc":"от вечернего зова к бесшумному уходу под закрывающееся море","ending_direction":"море закрылось над ними — их песня осталась на поверхности","hook_direction":"троуп домой, девы моря","genres":["Соул","Эмбиент"],"moods":["Спокойствие","Мечтательность"],"energy":"Низкая","themes":["расставание","Море"],"generator_brief":"Глубокий соул-эмбиент с песней-эхом: куплеты — отлив и зов домой, припев — имитация волн голосами, которые уходят под закрывающуюся воду.","generator_story":"В полночь морские девы уходят домой — в тихие гроты, где нет ни ветра, ни людей: они подражают умирающим волнам, и море закрывается над ними, как дверь. Их песня остаётся на поверхности.","primary_genre":"Соул","primary_mood":"Спокойствие","primary_theme":"расставание","story_shelf":"Трагические истории","conflict_key":"полночь-зовёт-морских-дев-домой","image_key":"русалки-троупятся-в-пещеры","turn_key":"море-поёт-им-вечерню","hook_key":"троуп-домой-девы-моря","sort_order":"1333","original_key":"george-darley|the-mermaidens-vesper-hymn","author_name":"Джордж Дарли","original_title":"The Mermaidens' Vesper-Hymn","original_language":"English","origin_country":"Ирландия","original_year":"1837","source_url":"https://www.poemhunter.com/poem/the-mermaidens-vesper-hymn/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1846.","music_adaptations":[],"source_synopsis":"Вечерняя песнь морских дев: полночь и отлив зовут их домой — «троуп домой» — в тихие гроты и пещеры; русалки уходят с поверхности, подражая звукам умирающих волн, обратно в своё подводное царство.","main_image":"русалки, уходящие с песней в подводные пещеры"},{"title":"Блеск ярма над пашней","full_story":"Он сидит на поваленном грозой вязе и смотрит, как пахарь ведёт упряжку: лошади блестят ярмом, борозда идёт ровно. Они разговаривают о погоде и войне — друг пахаря убит во Франции через два дня после прибытия, тем самым снегопад, что свалил этот вяз. Из леса выходят и уходят влюблённые парочки, жизнь продолжается между вестями о смерти. Песня о работе, которая не останавливается ни при каких вестях.","hero_pov":"наблюдатель на упавшем вязе","central_conflict":"пахарь работает — а война забирает друзей","emotional_arc":"от мирной картины пашни к войне под ней и обратно к борозде","ending_direction":"плуг заканчивает борозду — при всех вестях о смерти","hook_direction":"борозда длиннее войны","genres":["Кантри","Фолк"],"moods":["Спокойствие","Тревога"],"energy":"Средняя","themes":["работа","Потеря"],"generator_brief":"Тихое кантри со скрипом упряжи и далёким громом войны: куплеты — разговор на борозде, припев — блеск ярма, который не гаснет ни при каких вестях.","generator_story":"Он смотрит с упавшего вяза, как пахарь ведёт упряжку в блестящем ярме: их друг убит во Франции два дня спустя после прибытия. Влюблённые идут из лесу, а плуг при любых вестях заканчивает борозду.","primary_genre":"Кантри","primary_mood":"Спокойствие","primary_theme":"работа","story_shelf":"Люди и животные","conflict_key":"пахарь-работает-а-война-забирает-друзей","image_key":"блеск-ярма-над-пашней","turn_key":"плуг-заканчивает-борозду-при-всех-вестях","hook_key":"борозда-длиннее-войны","sort_order":"1334","original_key":"edward-thomas|as-the-teams-head-brass","author_name":"Эдвард Томас","original_title":"As the Team's Head-Brass","original_language":"English","origin_country":"Великобритания","original_year":"1916","source_url":"https://www.poemhunter.com/poem/as-the-team-s-head-brass/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1917.","music_adaptations":[],"source_synopsis":"Поэт сидит на упавшем вязе и смотрит, как пахарь с упряжкой проводит последнюю борозду; они говорят о погоде и войне — друг пахаря убит во Франции через два дня после прибытия. Парочки проходят в лес; плуг заканчивает борозду при всех вестях о войне.","main_image":"блеск ярма упряжки над пашней на фоне войны"},{"title":"Сестра нового стиля","full_story":"Каждый день в палату входит она: ясные глаза, светлое лицо — и что-то в ней тает быстрее, чем у всех, будто закат, который почти прошёл. Работа забирает её по капле — ночи, смены, чужие боли — а она всё входит той же походкой. Палата светлеет от её входа и не спрашивает, во что это ей обходится. Песня о работе, которая светит, съедая работника.","hero_pov":"смотрящий на сестру из палаты","central_conflict":"молодая сестра отдаёт себя и тает","emotional_arc":"от восхищения её входом к горькому знанию, во что даётся свет","ending_direction":"она светит палате — закат почти прошёл, а она всё входит","hook_direction":"она входит — и палата светлеет","genres":["Соул","Классика"],"moods":["Нежность","Сила"],"energy":"Низкая","themes":["работа","Потеря"],"generator_brief":"Тихий соул с ровным ритмом смен: куплеты — её вход в палату день за днём, припев — закат, который светит, уже почти пройдя.","generator_story":"Каждое утро молодая медсестра появляется в палате, и та светлеет от её ясного лица. Но ночи, смены и чужие боли тают в ней по капле, как закат, — и никто не спрашивает, во что ей обходится этот свет.","primary_genre":"Соул","primary_mood":"Нежность","primary_theme":"работа","story_shelf":"Трагические истории","conflict_key":"молодая-сестра-отдаёт-себя-и-тает","image_key":"ясноглазая-сестра-в-палате","turn_key":"закат-почти-прошедший-и-всё-ещё-светит","hook_key":"она-входит-и-палата-светлеет","sort_order":"1335","original_key":"william-ernest-henley|staff-nurse-new-style","author_name":"Уильям Эрнест Хенли","original_title":"Staff-Nurse: New Style","original_language":"English","origin_country":"Великобритания","original_year":"1875","source_url":"https://www.poemhunter.com/poem/staff-nurse-new-style/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1903.","music_adaptations":[],"source_synopsis":"Портрет молодой больничной сестры «нового стиля»: ясноглазая, светлая лицом, но быстро увядающая до осени девичьего заката. Она входит в палату день за днём — как сладкий закат, почти прошедший, и всё ещё светящий.","main_image":"ясноглазая сестра, входящая в палату день за днём"},{"title":"Лондонские волюнтари","full_story":"Он слушает город как инструмент: колокола Сент-Маргарет наигрывают старые невинные мотеты, а под ними гудит лавка, грохочет очередь, течёт река людей. Город — большой орган, на котором играют тысячи рук сразу, и в его аккордах есть и молитвы, и торговля, и чужие улыбки. Песня о том, что у столицы есть своя музыка — надо только встать и слушать.","hero_pov":"слушатель города-органа","central_conflict":"колокола и гул города перекликаются","emotional_arc":"от уличного шума к музыке, в которой город звучит целяком","ending_direction":"город играет сам — надо только встать и слушать","hook_direction":"слушай город — он играет","genres":["Джаз","Классика"],"moods":["Драйв","Грусть"],"energy":"Высокая","themes":["город","музыка"],"generator_brief":"Городской джаз с колоколами и органным гулом: куплеты — улицы и очередь, припев — аккорд, в котором молитвы и торговля звучат вместе.","generator_story":"Он слушает город как орган: колокола Сент-Маргарет наигрывают старые мотеты, под ними гудит лавка и течёт река людей. Город играют тысячи рук сразу — надо только встать и слушать его музыку.","primary_genre":"Джаз","primary_mood":"Драйв","primary_theme":"город","story_shelf":"Трагические истории","conflict_key":"колокола-и-гул-города-перекликаются","image_key":"сент-маргарет-колокола-над-лондоном","turn_key":"город-звучит-как-большой-инструмент","hook_key":"слушай-город-он-играет","sort_order":"1336","original_key":"william-ernest-henley|london-voluntaries","author_name":"Уильям Эрнест Хенли","original_title":"London Voluntaries","original_language":"English","origin_country":"Великобритания","original_year":"1893","source_url":"https://www.poemhunter.com/william-ernest-henley/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1903.","music_adaptations":[],"source_synopsis":"Серия музыкальных эскизов Лондона: колокола Сент-Маргарет звучат над улицами, город гудит и течёт как большой орган, — у столицы есть собственная музыка, в которой слышны и старые молитвы, и новый гул тысяч людей.","main_image":"колокола Сент-Маргарет над гулким Лондоном"},{"title":"Птицы за решёткой","full_story":"Через решётку он смотрит на птиц: они порхают, строят, поют, любят без спроса — весь их день устроен без разрешения. Он перечисляет их волю с горькой точностью человека, у которого осталась одна воля — смотреть. Между ним и небом только прутья, но и через прутья видно, как устроена свобода. Песня о птицах, которые стали учебником несвободного.","hero_pov":"узник у решётки, смотрящий на птиц","central_conflict":"птицы свободны — он за решёткой","emotional_arc":"от горького перечня чужой воли к тихому знанию, как выглядит свобода","ending_direction":"у птиц — небо, у него — окно, и он всё запомнил","hook_direction":"у птиц — небо, у меня — окно","genres":["Метал","Фолк"],"moods":["Тревога","Мечтательность"],"energy":"Высокая","themes":["расставание","свобода"],"generator_brief":"Тягучий метал с птичьим свистом вдалеке: куплеты — перечень птичьей воли за решёткой, припев — рваный, как стук сердца у окна.","generator_story":"Узник смотрит через решётку на птиц: те порхают, строят, поют и любят без спроса — их день устроен без разрешения. У него осталась одна воля — смотреть, и он запоминает, как устроена свобода.","primary_genre":"Метал","primary_mood":"Тревога","primary_theme":"расставание","story_shelf":"Люди и животные","conflict_key":"птицы-свободны-он-за-решёткой","image_key":"птицы-порхают-мимо-решётки","turn_key":"он-завидует-даже-вороне","hook_key":"у-птиц-небо-у-меня-окно","sort_order":"1337","original_key":"william-morris|in-prison","author_name":"Уильям Моррис","original_title":"In Prison","original_language":"English","origin_country":"Великобритания","original_year":"1858","source_url":"https://www.poeticous.com/william-morris/in-prison","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1896.","music_adaptations":[],"source_synopsis":"Монолог узника (по мотивам Вийона): через решётку он видит свободных птиц — ласточек, скворцов — и с горькой иронией перечисляет их волю. Они летают, строят, поют — а он заперт; вся его свобода — смотреть.","main_image":"свободные птицы порхают мимо решётки"},{"title":"Позорная смерть","full_story":"Четверо стоят у смертного одра и вспоминают ночь, когда они бесчестно убили рыцаря — впятером на одного, ночью, без суда. Они знают: у убитого есть братья, и братья не прощают позорных смертей. И вот они возвращаются — по двое, по трое, молча, — и месть приходит ровно той же дорогой, что и убийство. Песня о вине, которая разучилась оправдываться.","hero_pov":"один из четырёх, ждущий мести","central_conflict":"четверо вспоминают своё злодейство","emotional_arc":"от воспоминания убийства к мести, приехавшей той же дорогой","ending_direction":"братья жертвы вернулись — никто не скроется от позора","hook_direction":"братья едут — никому не скрыться","genres":["Панк","Метал"],"moods":["Вина","Злость"],"energy":"Взрывная","themes":["дружба","Потеря"],"generator_brief":"Мрачный панк с топотом прибывающих коней: куплеты — исповедь четверых у одра, припев — месть, которая приезжает ровно той же ночью.","generator_story":"Четверо вспоминают, как впятером на одного, ночью и без суда, убили рыцаря — у того есть братья, не прощающие позорных смертей. Месть приходит той же дорогой, что убийство: по двое, по трое, молча.","primary_genre":"Панк","primary_mood":"Вина","primary_theme":"дружба","story_shelf":"Трагические истории","conflict_key":"четверо-вспоминают-своё-злодейство","image_key":"четверо-у-смертного-одра","turn_key":"братья-жертвы-вернулись-за-местью","hook_key":"братья-едут-никому-не-скрыться","sort_order":"1338","original_key":"william-morris|shameful-death","author_name":"Уильям Моррис","original_title":"Shameful Death","original_language":"English","origin_country":"Великобритания","original_year":"1858","source_url":"https://www.poeticous.com/william-morris/shameful-death","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1896.","music_adaptations":[],"source_synopsis":"Четверо men стоят у смертного одра и вспоминают, как бесчестно убили рыцаря — брата другого рыцаря; убийцы ждут расплаты. Возвращаются братья жертвы и вершат мрачную месть — позорная смерть получает свой ответ.","main_image":"четверо у смертного одра в ожидании мести"},{"title":"Летний рассвет","full_story":"Он просит её, не открывая глаз: помолись одним словом за меня между сомкнутыми губами, подумай обо мне одну мысль под звёздами. Летняя ночь тает с каждым вдохом, и утро уже скользит в окно — скоро темнота, которая позволяла им быть такими близкими, отпустит их в разные миры дня. Песня о последних минутах ночной близости перед её приходом.","hero_pov":"любовник на границе ночи и утра","central_conflict":"рассвет выгоняет из ночной близости","emotional_arc":"от последней ночной просьбы к свету, который всё разделит","ending_direction":"ночь ушла — осталась молитва, сказанная в темноте","hook_direction":"помолись за меня до рассвета","genres":["R&B","Классика"],"moods":["Любовь","Нежность"],"energy":"Низкая","themes":["любовь","Ночь"],"generator_brief":"Шёпотный R&B с рассветным светом в подложке: куплеты — одна просьба между сомкнутыми губами, припев — утро, входящее в окно.","generator_story":"Не открывая глаз, он просит её подумать о нём одной мыслью под звёздами. Летняя ночь тает с каждым вдохом, утро скользит в окно — темнота, позволявшая им быть близкими, отпустит их в разные миры дня.","primary_genre":"R&B","primary_mood":"Любовь","primary_theme":"любовь","story_shelf":"Любовные сцены","conflict_key":"рассвет-выгоняет-из-ночной-близости","image_key":"летняя-ночь-тает-в-утро","turn_key":"одна-мольба-одна-мысль-до-света","hook_key":"помолись-за-меня-до-рассвета","sort_order":"1339","original_key":"william-morris|summer-dawn","author_name":"Уильям Моррис","original_title":"Summer Dawn","original_language":"English","origin_country":"Великобритания","original_year":"1856","source_url":"https://www.poeticous.com/william-morris/summer-dawn-pray-but-one-prayer-for-me-twixt-thy-closed-lips","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1896.","music_adaptations":[],"source_synopsis":"Ночной любовник просит спящую любимую: помолись за меня одним между сомкнутыми губами, подумай обо мне одну мысль под звёздами — летняя ночь тает, и утренний свет выскальзывает в комнату. Любовь ночи уходит вместе с темнотой.","main_image":"летняя ночь, тающая в утренний свет над спящей любимой"},{"title":"Пойманная радость","full_story":"На границе летних сумерек и рассвета они поймали пролетавшее настроение и крикнули ему: остановись, останься. Настроение остановилось — и умерло у них в руках, как птица, которую посадили в клетку. Радость живёт ровно до тех пор, пока её не пытаются удержать. Песня о двоих, которые научились отпускать, чтобы что-то оставалось.","hero_pov":"один из двоих, поймавших и упустивших радость","central_conflict":"поймать настроение и не удержать","emotional_arc":"от крика «останься» к мёртвой птице в руках и горькому знанию","ending_direction":"радость не живёт в неволе — отпусти, и она вернётся летать","hook_direction":"радость не живёт в неволе","genres":["Блюз","Синтвейв"],"moods":["Мечтательность","Грусть"],"energy":"Низкая","themes":["расставание","Мечта"],"generator_brief":"Сумеречный блюз с птичьим свистом и одним разбитым аккордом: куплеты — ловля пролетающего настроения, припев — мёртвая птица в руках.","generator_story":"На границе сумерек двое поймали настроение и крикнули: останься. Оно остановилось — и умерло у них в руках, как птица в клетке. Радость живёт только на воле: отпусти — и она вернётся летать.","primary_genre":"Блюз","primary_mood":"Мечтательность","primary_theme":"расставание","story_shelf":"Трагические истории","conflict_key":"поймать-настроение-и-не-удержать","image_key":"пойманная-птица-радости-умирает","turn_key":"настроение-умерло-как-пойманная-птица","hook_key":"радость-не-живёт-в-неволе","sort_order":"1340","original_key":"william-ernest-henley|between-the-dusk-of-a-summer-night","author_name":"Уильям Эрнест Хенли","original_title":"Between the Dusk of a Summer Night","original_language":"English","origin_country":"Великобритания","original_year":"","source_url":"https://rpo.library.utoronto.ca/poems/between-dusk-summer-night","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1903.","music_adaptations":[],"source_synopsis":"Двое на границе летних сумерек и рассвета поймали пролетавшее настроение и велели ему остановиться — но пойманная радость умирает в руках, как птица в неволе. О том, что радость живёт, пока её не ловят.","main_image":"пойманное настроение, умирающее как птица в руках"},{"title":"Песни свадебного дня","full_story":"Один день от рассвета до ночи — и весь день звучит: муза будит невесту, девки поют, нимфы рвут цветы, мальчишки несут зелья, толпа ведёт её к венцу с песней. Венчание, пир, танцы — и всё это один день, собранный в одну песню, чтобы он не потерялся. Ночь благословляет молодых и просит у неба детей. Песня о том, как песня держит целый день.","hero_pov":"жених, поющий день своей свадьбы","central_conflict":"свадьба от рассвета до ночи","emotional_arc":"от утреннего будильника для невесты к благословению ночи","ending_direction":"весь день уложен в песню — и ночь благословляет двоих","hook_direction":"пой — невеста идёт","genres":["Эпик-рок","Фолк"],"moods":["Эйфория","Романтика"],"energy":"Высокая","themes":["Танец","семья"],"generator_brief":"Свадебный эпик-рок от утренней свирели до ночного хора: куплеты — будильник невесты, венчание, пир и танцы, припев — благословение ночи.","generator_story":"Жених поёт свой свадебный день от рассвета до ночи: муза будит невесту, девки поют, нимфы рвут цветы, толпа ведёт её к венцу с песней. Ночь благословляет молодых и просит у неба детей.","primary_genre":"Эпик-рок","primary_mood":"Эйфория","primary_theme":"Танец","story_shelf":"Любовные сцены","conflict_key":"свадьба-от-рассвета-до-ночи","image_key":"невеста-и-песни-всего-дня","turn_key":"весь-день-вели-её-к-венцу","hook_key":"пой-невеста-идёт","sort_order":"1341","original_key":"edmund-spenser|epithalamion","author_name":"Эдмунд Спенсер","original_title":"Epithalamion","original_language":"English","origin_country":"Великобритания","original_year":"1595","source_url":"https://en.wikisource.org/wiki/Epithalamion","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1599.","music_adaptations":[],"source_synopsis":"Песня целого свадебного дня: с рассвета музы будят невесту, музыканты играют, нимфы собирают цветы, мальчики поют, толпа ведёт её к храму, венчание, пир, танцы — и день заканчивается благословением ночи и молением о детях.","main_image":"невеста, которую весь день ведут песнями к венцу"},{"title":"Александрия, которой не было","full_story":"Обычный офисный человек на сеансе регрессивной терапии вдруг «вспоминает» пышную жизнь в великом старом городе: море, палестра, ночная пляска, запахи портовых улиц. Он возвращается туда каждую неделю, и коллеги замечают, что он стал моложе глазами. В финале он решает: пусть Александрия была сном — но жить он теперь будет по её правилам, то есть красиво.","hero_pov":"Человек, который вспомнил другую свою жизнь","central_conflict":"Скучная настоящая жизнь против пышной «воспомненной» Александрии, и надо решить, какая из них настоящая.","emotional_arc":"От серых будней к возвращению себе красоты и смелости","ending_direction":"Поворот: Александрию он больше не ищет — он привозит её правила в свою жизнь","hook_direction":"Вспомни свою Александрию","genres":["Джаз","Поп"],"moods":["Мечтательность","Драйв"],"energy":"Высокая","themes":["сцена","ночь"],"generator_brief":"Пышный джаз-вальс с восточными перкуссиями и саксофоном; куплеты — как прогулка по городу, припев — раскрывается морем.","generator_story":"Офисный человек на сеансе терапии «вспоминает» пышную жизнь в Александрии: море, ночная пляска, запахи портовых улиц. Пусть она была сном — жить он теперь будет по её правилам, то есть красиво.","primary_genre":"Джаз","primary_mood":"Мечтательность","primary_theme":"сцена","story_shelf":"Любовные сцены","conflict_key":"прошлая-жизнь-как-сон","image_key":"танцовщица-осу-в-тёмном-квартале","turn_key":"сон-александрии-становится-правилом","hook_key":"вспомни-свою-александрию","sort_order":"1342","original_key":"mihail-kuzmin|iz-aleksandriyskih-pesen","author_name":"Михаил Кузмин","original_title":"Из «Александрийских песен»","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/kuzmin/iz_aleksandriyskih_pesen/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1936.","music_adaptations":[],"source_synopsis":"Герой вспоминает, будто жил в великой Александрии под именем Евлогий: катался по зелёному морю, ходил в палестру и в тёмные кварталы, смотрел, как танцовщица пляшет «осу», и слышал лай собак издалека. И вся эта пышная жизнь — словно не во сне ли.","main_image":"танцовщица «осу» в тёмном квартале великого города"},{"title":"Проповедь на похоронах льва","full_story":"Корпорация хоронит «великого основателя», и лучший оратор с самого низа карьерной лестницы произносит речь, в которой тирания названа заботой. Молодая сотрудница слушает и впервые записывает, что говорилось на самом деле. Поворот: через год её список читают вслух на общей встрече — и оратор аплодирует, не узнав свою речь.","hero_pov":"Сотрудница, которая слушает и записывает правду","central_conflict":"Пышная лесть, которая забирает зал, против одного тихого протокола правды.","emotional_arc":"От неловкого смеха к тихому торжеству правды","ending_direction":"Поворот: через год список правды читают вслух — и хвалитель аплодирует, не узнав свою речь","hook_direction":"Хвалить — молча","genres":["Метал","Джаз"],"moods":["Ирония","Злость"],"energy":"Высокая","themes":["сцена","музыка"],"generator_brief":"Тяжёлый металлический речитатив с «церковным» органным бриджем и саркастичным женским голосом поверх хора.","generator_story":"На похоронах основателя оратор называет тиранию заботой, и молодая сотрудница записывает, что говорилось на самом деле. Через год её список читают вслух — хвалитель аплодирует, не узнав своей речи.","primary_genre":"Метал","primary_mood":"Ирония","primary_theme":"сцена","story_shelf":"Юмор: семейные драмы","conflict_key":"лесть-на-похоронах-самодура","image_key":"лиса-проповедник-у-гроба-льва","turn_key":"список-правды-читают-вслух","hook_key":"хвалить-молча","sort_order":"1343","original_key":"denis-fonvizin|lisica-kaznodey","author_name":"Денис Фонвизин","original_title":"Лисица-казнодей","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://ru.wikipedia.org/wiki/Фонвизин,_Денис_Иванович","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1792.","music_adaptations":[],"source_synopsis":"Лиса-проповедник произносит надгробные хвалебные речи умершему льву, царю зверей-самодуру, и всё звериное окружение состязается в славословии. Басня высмеивает придворную лесть, которая переживает и тирана, и правду.","main_image":"лиса-проповедник у гроба льва"},{"title":"Танец на канате","full_story":"Артист варьете после падения год не выходит на канат: страховка стала его тюрьмой. В ночь большого бенефиса он снимает страховку — не ради гонорара, а чтобы снова почувствовать свет над собой и бездну под собой. Поворот: он начинает танцевать медленнее, чем когда-либо, — и зал впервые замирает не от страха, а от красоты.","hero_pov":"Канатоходец, вернувшийся после падения","central_conflict":"Страх и страховка против смысла его искусства, живущего только над пропастью.","emotional_arc":"От прилипших к страховке рук к медленному свободному танцу","ending_direction":"Поворот: без страховки он танцует медленнее всех — и зал замирает от красоты, не от страха","hook_direction":"Танцуй на канате","genres":["Эпик-рок","Джаз"],"moods":["Уверенность","Сила"],"energy":"Высокая","themes":["сцена","Риск"],"generator_brief":"Эпик-рок с высоким Vox-напряжением: струнный тремор каната в струнных, зал замирает в бридже, финал — медленный и свободный.","generator_story":"Канатоходец год не выходил на канат — страховка стала его тюрьмой. В ночь бенефиса он снимает её ради света над собой и бездны под собой и танцует медленнее всех: зал замирает от красоты.","primary_genre":"Эпик-рок","primary_mood":"Уверенность","primary_theme":"сцена","story_shelf":"Трагические истории","conflict_key":"бездна-под-ногами-свет-в-глазах","image_key":"канат-над-пропастью","turn_key":"страховка-снята-танец-медленнее","hook_key":"танцуй-на-канате","sort_order":"1344","original_key":"georgiy-ivanov|kanatnyy-plyasun","author_name":"Георгий Иванов","original_title":"Канатный плясун","original_language":"Russian","origin_country":"Россия","original_year":"1914","source_url":"https://ru.wikipedia.org/wiki/Иванов,_Георгий_Владимирович","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1958.","music_adaptations":[],"source_synopsis":"Лирический герой — канатоходец, танцующий над пропастью: ницшеанский образ поэта, который живёт на грани гибели, между бездной внизу и светом вверху, и превращает этот баланс в искусство.","main_image":"канат над пропастью, посередине — плясун"},{"title":"Спор любви и долга","full_story":"Два современных певца запускают дуэт-диспут в прямом эфире: один — о любви как единственном деле жизни, второй — о служении, которое дороже свиданий. Подписчики делятся на два лагеря, и ссора грозит стать войной фанатов. Поворот: в финальном куплете оба поют чужую строфу по своим нотам — и спор превращается в один общий голос.","hero_pov":"Один из двух певцов-спорщиков","central_conflict":"Любовь как главное дело жизни против служения, которое кажется важнее, — в открытом дуэте двух друзей.","emotional_arc":"От азартной пикировки к признанию правоты обоих","ending_direction":"Поворот: финальную строфу поют по чужим нотам — и спор становится общим голосом","hook_direction":"Поём одну правду на двоих","genres":["Рок","Джаз"],"moods":["Романтика","Уверенность"],"energy":"Взрывная","themes":["любовь","музыка"],"generator_brief":"Дуэт-баттл двух голосов с торгующей ритм-секцией; куплеты — перекличка, финал — общий унисон поверх обеих мелодий.","generator_story":"Два певца спорят дуэтом: один поёт о любви как главном деле жизни, второй — о служении дороже свиданий. В финальном куплете оба поют чужую строфу по своим нотам — и спор становится общим голосом.","primary_genre":"Рок","primary_mood":"Романтика","primary_theme":"любовь","story_shelf":"Любовные сцены","conflict_key":"любовь-против-долга-в-дуэте","image_key":"два-голоса-через-века","turn_key":"чужая-строфа-по-своим-нотам","hook_key":"поём-одну-правду-на-двоих","sort_order":"1345","original_key":"mikhail-lomonosov|razgovor-s-anakreonom","author_name":"Михаил Ломоносов","original_title":"Разговор с Анакреоном","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://ru.wikisource.org/wiki/Разговор_с_Анакреоном_(Ломоносов)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1765.","music_adaptations":[],"source_synopsis":"Ломоносов переводит строфы Анакреона и отвечает на каждую своей: древний певец воспевает любовь, вино и радость, русский поэт спорит о долге, славе и том, чья лира важнее.","main_image":"два голоса через века: чаша и лира"},{"title":"Черепаха плывёт к волнам","full_story":"Человек, который год ухаживал за умирающей мамой, боится не её конца, а своей паники. В её разговорах о «тихих волнах» он начинает слышать не страх, а покой — и в последнюю ночь впервые просто держит её руку. Поворот: после ухода он заводит черепаху и каждое утро смотрит, как она плывёт, — горе не исчезло, но перестало кричать.","hero_pov":"Сын, который учится не паниковать у её кровати","central_conflict":"Паника перед концом против тихого покоя, который мама сама называет волнами.","emotional_arc":"От сжатого страха к спокойной руке в её руке","ending_direction":"Поворот: после ухода черепаха в аквариуме делает горе тихим — оно не исчезло, но перестало кричать","hook_direction":"Поплыли без страха","genres":["Эмбиент","Баллада"],"moods":["Спокойствие","Нежность"],"energy":"Низкая","themes":["Примирение","море"],"generator_brief":"Медленный эмбиент с волнами-педалями и редкой флейтой; голос почти не поднимается выше разговора.","generator_story":"Сын боится не конца умирающей мамы, а своей паники: в её разговорах о тихих волнах он слышит покой и в последнюю ночь просто держит её руку. После ухода он заводит черепаху — и горе перестаёт кричать.","primary_genre":"Эмбиент","primary_mood":"Спокойствие","primary_theme":"Примирение","story_shelf":"Люди и животные","conflict_key":"смерть-как-тихие-волны","image_key":"черепаха-плывёт-к-берегу","turn_key":"рука-в-её-руке-в-последнюю-ночь","hook_key":"поплыли-без-страха","sort_order":"1346","original_key":"fedor-sologub|cherepaha","author_name":"Фёдор Сологуб","original_title":"Черепаха","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/sologub/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1927.","music_adaptations":[],"source_synopsis":"Смерть у Сологуба — как прибрежные пенистые волны: неторопливая черепаха плывёт к тому берегу без страха, и в этом плавании есть утешение и свет, а не ужас.","main_image":"черепаха, неторопливо плывущая к берегу"},{"title":"Моя осень","full_story":"Человек, у которого «обвалился» год — работа, здоровье, отношения, — уезжает в осеннюю деревню и каждый день записывает, как умирает лето. Он ждёт тоски, а находит порядок: всё увядает по расписанию и всё вернётся. Поворот: в последний день он перестаёт чинить свою осень и впервые слышит в ней не финал, а подготовку к новому кругу.","hero_pov":"Человек, живущий свою осень в деревне","central_conflict":"Желание вернуть лето против закона круговорота, по которому увядает и человек, и природа.","emotional_arc":"От сопротивления увяданию к мирному доверию кругу","ending_direction":"Поворот: он перестаёт чинить свою осень — и слышит в ней подготовку к новому кругу","hook_direction":"Прими свою осень","genres":["Джаз","Эмбиент"],"moods":["Светлая грусть","Меланхолия"],"energy":"Низкая","themes":["Примирение","природа"],"generator_brief":"Осенний джаз-ноктюрн: приглушённое фортепиано, тернистый саксофон, шорох листвы вместо перкуссии.","generator_story":"После обвала года — работа, здоровье, отношения — он уезжает в осеннюю деревню и вместо тоски находит порядок: всё увядает по расписанию. Он перестаёт чинить свою осень и слышит в ней новый круг.","primary_genre":"Джаз","primary_mood":"Светлая грусть","primary_theme":"Примирение","story_shelf":"Трагические истории","conflict_key":"осень-природы-осень-жизни","image_key":"седые-туманы-в-долине","turn_key":"перестал-чинить-свою-осень","hook_key":"прими-свою-осень","sort_order":"1347","original_key":"nikolay-karamzin|osen","author_name":"Николай Карамзин","original_title":"Осень","original_language":"Russian","origin_country":"Россия","original_year":"1789","source_url":"https://rustih.ru/nikolaj-karamzin-osen","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1826.","music_adaptations":[],"source_synopsis":"Карамзин описывает увядание природы осенью — ветры в дубраве, седые туманы в долине — и переводит взгляд на «осень жизни» человека, размышляя о старении, времени и вечном круговороте.","main_image":"седые туманы в тихой долине"},{"title":"Смерть придёт по-простому","full_story":"Тяжело больной человек переделывает квартиру в «красивую смерть»: свечи, музыка, роботы-колокольчики. Ночью он слышит во дворе обычный лай собаки и вдруг понимает, что конец будет не торжественным, а бытовым — и это почти утешение. Поворот: наутро он просит родных просто завтракать с ним при открытом окне, без всей этой режиссуры.","hero_pov":"Больной, который отменил режиссуру своего конца","central_conflict":"Красивая, отрежиссированная смерть против простой, бытовой правды последнего времени.","emotional_arc":"От экзальтированной подготовки к будничному покою","ending_direction":"Поворот: он просит просто завтракать с ним при открытом окне — и быт становится последним утешением","hook_direction":"Придёт по-простому","genres":["Лоу-фай","Эмбиент"],"moods":["Уязвимость","Спокойствие"],"energy":"Низкая","themes":["Примирение","ночь"],"generator_brief":"Лоу-фай с лаем собаки и проезжающим автомобилем в фоне — намеренно бытовое, без пафоса; голос усталый и ясный.","generator_story":"Больной устроил в квартире «красивую смерть» — свечи, музыку. Ночной лай собаки говорит: конец будет бытовым, и это почти утешение. Наутро он отменяет режиссуру и просит завтракать при открытом окне.","primary_genre":"Лоу-фай","primary_mood":"Уязвимость","primary_theme":"Примирение","story_shelf":"Трагические истории","conflict_key":"смерть-придёт-без-музыки","image_key":"паук-заткал-молитвенник","turn_key":"режиссура-отменена-окно-открыто","hook_key":"придёт-по-простому","sort_order":"1348","original_key":"sofya-parnok|pauk-zatkal-moy-temnyy-skladen","author_name":"Софья Парнок","original_title":"Паук заткал мой темный складень...","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/parnok/paukzatkalmoj/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1933.","music_adaptations":[],"source_synopsis":"Паук заткал тёмный складень с иконами, все молитвы мертвы, измученная голова никнет к подушке. И героиня знает: когда смерть придёт за ней, она придёт не музыкой, не ароматом и не демоном — а просто завоет пс во дворе или взвизгнет австрияка-автомобиль.","main_image":"паук заткал тёмный складень с иконами"},{"title":"Согласный круг","full_story":"Три родных брата не разговаривают после дележа наследства и встречаются впервые за годы — на реставрации иконы, которую оставила им мать. Пока каждый чистит свой угол, они ссорятся из-за кистей и лака. Поворот: закончив, они выносят икону на свет и обнаруживают, что руки трёх ангелов на столе образуют круг — и молча садятся чай из одной чашки.","hero_pov":"Средний брат, который начал реставрацию","central_conflict":"Наследственная ссора и разобщённость против «согласного круга», который держит их общий дом.","emotional_arc":"От перекрёстных претензий к тишине одной чашки","ending_direction":"Поворот: вынеся икону на свет, они видят круг из рук ангелов — и садятся пить чай из одной чашки","hook_direction":"Встань в согласный круг","genres":["Эмбиент","Фолк"],"moods":["Нежность","Надежда"],"energy":"Низкая","themes":["Примирение","дружба"],"generator_brief":"Тихий эмбиент с русским хором-подкладкой и свечным тёплым светом; без ударных — только дыхание и звоны.","generator_story":"Братья, не говорившие после дележа наследства, сходятся на реставрации иконы матери и ссорятся из-за кистей. Закончив, выносят её на свет: руки трёх ангелов образуют круг — и пьют чай из одной чашки.","primary_genre":"Эмбиент","primary_mood":"Нежность","primary_theme":"Примирение","story_shelf":"Любовные сцены","conflict_key":"разобщённость-против-согласного-круга","image_key":"три-ангела-за-одним-столом","turn_key":"круг-из-рук-ангелов-на-свету","hook_key":"встань-в-согласный-круг","sort_order":"1349","original_key":"vyacheslav-ivanov|troitsa","author_name":"Вячеслав Иванов","original_title":"Троица","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://ru.wikipedia.org/wiki/Иванов,_Вячеслав_Иванович","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1949.","music_adaptations":[],"source_synopsis":"Икона Рублёва «Троица» прочитывается как три Ангела за одной трапезой — образ единства в любви и «согласного круга», который преодолевает разобщённость мира и становится пророчеством о единении.","main_image":"три ангела за одним столом"},{"title":"Чем утешаемся под солнцем","full_story":"Друг детства, развёлся и спивается, шлёт другу в ночи сообщение: «всё лучшее было тогда». Тот отвечает не мотивационными лекциями, а списком мелочей, которые можно сделать уже сегодня: звонок, рыбалка, забытый общий анекдот. Поворот: ночью он приезжает не с речами, а с удочками — и впервые за год друг смеётся раньше него.","hero_pov":"Друг, который отвечает письмом на письмо","central_conflict":"Отчаяние друга по ушедшей молодости против простого утешения: страдать меньше — и делить это с кем-то.","emotional_arc":"От ночного «всё прошло» к утреннему смеху над старым анекдотом","ending_direction":"Поворот: вместо речей друг приезжает с удочками — и смеётся первым","hook_direction":"Меньше страдать — больше жить","genres":["Джаз","Поп"],"moods":["Тепло","Надежда"],"energy":"Средняя","themes":["дружба","Время"],"generator_brief":"Тёплый джаз-дуэт двух голосов с бродвейским раскачивом; припев — как ответное письмо, произнесённое вслух.","generator_story":"Спивающийся друг шлёт ночью: «всё лучшее было тогда». Тот отвечает не речами, а списком на сегодня — звонок, рыбалка, общий анекдот — и приезжает с удочками: друг впервые за год смеётся раньше него.","primary_genre":"Джаз","primary_mood":"Тепло","primary_theme":"дружба","story_shelf":"Любовные сцены","conflict_key":"друг-в-отчаянии-против-утешения","image_key":"письмо-двух-поэтов-под-солнцем","turn_key":"приехал-с-удочками-а-не-с-речами","hook_key":"менее-страдать-больше-жить","sort_order":"1350","original_key":"nikolay-karamzin|poslanie-k-dmitrievu","author_name":"Николай Карамзин","original_title":"Послание к Дмитриеву","original_language":"Russian","origin_country":"Россия","original_year":"1794","source_url":"https://rustih.ru/nikolaj-karamzin-poslanie-k-dmitrievu","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1826.","music_adaptations":[],"source_synopsis":"Карамзин отвечает другу-поэту, жалующемуся на скоротечность счастливой молодости: искать блаженства нам не должно, но должно — менее страдать; а утешиться под солнцем можно любовью и дружбой.","main_image":"письмо двух поэтов под одним солнцем"},{"title":"Черпать воздух в саду","full_story":"Два бывших соученика, ставшие начальниками и соседями по гаражу, договорились «потренироваться» в стиле бизнес-коучей: цели, KPI, разбор ошибок. Через месяц они сжигают этот план и вместо него заводят правило — раз в неделю идти в старый ботанический сад и просто дышать. Поворот: лучшие решения года оба принимают именно там, а не на планёрках.","hero_pov":"Один из двух друзей на еженедельной прогулке","central_conflict":"Культ эффективности и разбор ошибок против простого ритуала дышать с другом в саду.","emotional_arc":"От планёрки с KPI к прогулке, которая работает лучше плана","ending_direction":"Поворот: все главные решения года принимаются в саду, а не на планёрках","hook_direction":"Черпай воздух со мной","genres":["Кантри","Фолк"],"moods":["Радость","Нежность"],"energy":"Средняя","themes":["дружба","природа"],"generator_brief":"Деревенский кантри-вальс с акустикой и птицами в интро; два голоса, шагающие в одном темпе.","generator_story":"Два друга-начальника месяц «тренируются» с KPI и разбором ошибок, потом сжигают план: раз в неделю — в старый ботанический сад просто дышать. Лучшие решения года оба принимают там, а не на планёрках.","primary_genre":"Кантри","primary_mood":"Радость","primary_theme":"дружба","story_shelf":"Любовные сцены","conflict_key":"душный-город-против-сада-с-другом","image_key":"прогулка-за-воздухом-в-сад","turn_key":"план-сожжён-осталось-дышать","hook_key":"черпи-воздух-со-мной","sort_order":"1351","original_key":"gavrila-derzhavin|drugu","author_name":"Гаврила Державин","original_title":"Другу","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://ru.wikisource.org/wiki/Другу_(Державин)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1816.","music_adaptations":[],"source_synopsis":"Анакреонтическое послание: поэт зовёт друга идти в сад «черпать воздух» — благовонный, свежий, среди милых друзей и простых радостей, вместо парадных забот и суеты.","main_image":"прогулка за воздухом в благовонном саду"},{"title":"Город из песка","full_story":"На детском дворе три непримиримых «врага» — лидер, одиночка и новичок — получают по тачке и общее задание построить город из песка. Каждый сначала строит свою улицу, и город не сходится. Поворот: после первого «наводнения» из лейки они соединяют улицы в один город и подписывают его всеми тремя именами — по алфавиту, без споров о первом.","hero_pov":"Новичок на дворе, получивший тачку","central_conflict":"Три лидера и три отдельные улицы против общего города, который не сложится без соседей.","emotional_arc":"От пограничной войны территорий к подписи втроём","ending_direction":"Поворот: после наводнения улицы соединяются — город подписан всеми тремя именами по алфавиту","hook_direction":"Город строим вместе","genres":["Лоу-фай","Фолк"],"moods":["Радость","Нежность"],"energy":"Низкая","themes":["дружба","детство"],"generator_brief":"Дворовый лоу-фай со скрипом тачек, детским хлопаньем и тёплым гулом лета; припев — как считалка на три имени.","generator_story":"Лидер, одиночка и новичок строят город из песка — каждый свою улицу, город не сходится. После «наводнения» из лейки улицы соединяют в один и подписывают всеми тремя именами по алфавиту.","primary_genre":"Лоу-фай","primary_mood":"Радость","primary_theme":"дружба","story_shelf":"Юмор: семейные драмы","conflict_key":"тачки-против-одиночек","image_key":"песочный-город-и-три-тачки","turn_key":"наводнение-соединяет-улицы","hook_key":"город-строим-вместе","sort_order":"1352","original_key":"poliksena-solovyova|deti-tachki-i-pesok","author_name":"Поликсена Соловьёва","original_title":"Дети, тачки и песок","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://ru.wikipedia.org/wiki/Соловьёва,_Поликсена_Сергеевна","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1924.","music_adaptations":[],"source_synopsis":"Детское стихотворение поэтессы и художницы Поликсены Соловьёвой: дети с тачками и песком устраивают свою большую и важную работу — игру, в которой у каждого есть своё дело.","main_image":"песочный город и три тачки"},{"title":"Дружба в рифму","full_story":"Два коллеги в унылой конторе спасаются единственным способом: обмениваются записками с рифмованными колкостями по внутренним документам. Начальство перехватывает одну записку — и требует объяснительную. Поворот: вместо объяснения они приносят начальнику совместную оду о нём, написанную в их игре, — и получают перевод в отдел, где разрешают смеяться.","hero_pov":"Автор записок в отделе без смеха","central_conflict":"Казённая серьёзность конторы против дружеской стихотворной игры, которая держит двух людей.","emotional_arc":"От тайной переписки к открытому праву на смех","ending_direction":"Поворот: вместо объяснительной они приносят начальнику оду — и переводятся в отдел, где разрешают смеяться","hook_direction":"Ответь мне рифмой","genres":["Лоу-фай","Джаз"],"moods":["Ирония","Тепло"],"energy":"Средняя","themes":["дружба","письмо"],"generator_brief":"Игривый лоу-фай с печатной машинкой в перкуссии и двумя переговаривающимися голосами; припев — рифмованный перепихон.","generator_story":"Два коллеги спасаются от казённой скуки рифмованными колкостями на служебных бумагах. Перехваченная записка грозит объяснительной — они приносят начальнику оду и получают отдел, где можно смеяться.","primary_genre":"Лоу-фай","primary_mood":"Ирония","primary_theme":"дружба","story_shelf":"Юмор: семейные драмы","conflict_key":"казённая-скука-против-дружеской-игры","image_key":"шутка-в-стихах-через-должность","turn_key":"объяснительная-заменена-одой","hook_key":"ответь-мне-рифмой","sort_order":"1353","original_key":"gavrila-derzhavin|khrapovickomu","author_name":"Гаврила Державин","original_title":"Храповицкому","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://ru.wikisource.org/wiki/Анакреонтические_песни_(Державин)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1816.","music_adaptations":[],"source_synopsis":"Шутливое послание другу Храповицкому — чиновнику и собутыльнику по перу: «дружбы знаки», стихотворная игра, обмен шутками и нелепостями между двумя служащими людьми, которые умели смеяться среди казёнщины.","main_image":"шутка в стихах, отправленная через служебный коридор"},{"title":"Не гаси лампу","full_story":"Она встречается с ним только в темноте по договору — «так надо», и это её устраивает, пока подруги не убеждают: «любить вслепую — значит терять жизнь». Ночью она включает фонарь и теряет его навсегда. Поворот: годы спустя, научившись доверять вслепую, она встречает нового — и фонарь остаётся на полке как памятник уроку.","hero_pov":"Она, потерявшая его из-за света","central_conflict":"Доверие вслепую против любопытства, подогретого подругами, — и цена вопроса «а какой он на самом деле?».","emotional_arc":"От спокойного тайного счастья к потере и зрелому доверу","ending_direction":"Поворот: новый союз она строит вслепую — фонарь лежит на полке как памятник уроку","hook_direction":"Не включай свет","genres":["Фолк","Рок"],"moods":["Любовь","Вина"],"energy":"Высокая","themes":["любовь","Выбор"],"generator_brief":"Ночная фолк-баллада со свечным светом и тёплым мужским голосом из темноты; припев — её мольба не включать свет.","generator_story":"Она встречает его только в темноте, пока подруги не убеждают: любить вслепую — терять жизнь. Включённый ночью фонарь стоит ей его навсегда — новый союз она строит вслепую, а фонарь остаётся на полке.","primary_genre":"Фолк","primary_mood":"Любовь","primary_theme":"любовь","story_shelf":"Любовные сцены","conflict_key":"доверие-против-любопытства","image_key":"капля-масла-на-невидимом-госте","turn_key":"фонарь-остаётся-на-полке","hook_key":"не-включай-свет","sort_order":"1354","original_key":"ippolit-bogdanovich|dushenka","author_name":"Ипполит Богданович","original_title":"Душенька","original_language":"Russian","origin_country":"Россия","original_year":"1778","source_url":"https://ru.wikisource.org/wiki/Душенька_(Богданович)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1803.","music_adaptations":[],"source_synopsis":"Поэма о Душеньке: её ночью тайно посещает возлюбленный, которого запрещено видеть при свете. Сёстры подговаривают её припрятать лампу; капля масла падает на невидимого гостя, он сгорает и исчезает, — и Душенька отправляется искать его по свету.","main_image":"капля масла на невидимом госте"},{"title":"Сердце без измены","full_story":"Ей предлагают «новую жизнь» и объясняют, что многолюбие — это свобода. Она соглашается попробовать и удивляет всех: она не запрещает себе знакомства, они просто не случаются — сердце не откликается второй раз. Поворот: бывший приходит проверить «свободу» и застывает у её двери, услышав из-за неё ту же старую пластинку — одна волна на всю жизнь.","hero_pov":"Женщина, у которой любовь случилась однажды","central_conflict":"Мода на многолюбие и «свободу» против сердца, в котором волна вскипела один раз и больше не повторится.","emotional_arc":"От любопытной пробы к тихой несокрушимости одной волны","ending_direction":"Поворот: бывший у двери слышит ту же старую пластинку — и понимает, что свобода была не про неё","hook_direction":"Одна волна на всю жизнь","genres":["Джаз","Баллада"],"moods":["Любовь","Сила"],"energy":"Низкая","themes":["любовь","Время"],"generator_brief":"Медленный ночной джаз с длинной волной саксофона и тёплым контрабасом; голос спокойный, без надрыва.","generator_story":"Ей предлагают многолюбие как свободу, но знакомства не случаются: сердце второй раз не откликается. Бывший приходит проверить «свободу» и застывает у двери, услышав за ней ту же старую пластинку.","primary_genre":"Джаз","primary_mood":"Любовь","primary_theme":"любовь","story_shelf":"Любовные сцены","conflict_key":"измена-невозможна-любовь-одна","image_key":"волна-вскипает-пеной-один-раз","turn_key":"бывший-у-двери-слышит-пластинку","hook_key":"одна-волна-на-всю-жизнь","sort_order":"1355","original_key":"zinaida-gippius|lyubov-odna","author_name":"Зинаида Гиппиус","original_title":"Любовь — одна","original_language":"Russian","origin_country":"Россия","original_year":"1896","source_url":"https://pishi-stihi.ru/lyubov-odna-gippius.html","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1945.","music_adaptations":[],"source_synopsis":"Гиппиус утверждает: волна вскипает пеной единый раз, и сердце не может жить изменой — измены нет, потому что любовь одна, как смерть одна: однообразная, пустынная и от этого сильная.","main_image":"волна, вскипевшая пеной единый раз"},{"title":"Ждали не того","full_story":"На летней даче два соседних домика: она год готовится к свиданию с бывшим, он — с новой знакомой, и оба так заняты ожиданием, что не видят друг друга, хотя заборы соприкасаются. Поворот: в один вечер оба получают отмену — и впервые выходят на общий луг, где паслись барашки. Никто не отменяет встречу на следующий день.","hero_pov":"Она — с венком на соседнем лугу","central_conflict":"Оба поглощены ожиданием недоступных людей и не видят друг друга через смежный забор.","emotional_arc":"От выстроенных ожиданий к случайному общему лугу","ending_direction":"Поворот: обе встречи отменяются в один вечер — и следующая назначается друг другу","hook_direction":"Посмотри, кто рядом","genres":["Кантри","Фолк"],"moods":["Романтика","Ирония"],"energy":"Средняя","themes":["любовь","ожидание"],"generator_brief":"Летний кантри-двухшаг с балалайкой-духами и двумя голосами, поющими из разных домиков; припев — один луг на двоих.","generator_story":"На даче два соседних домика: она готовится к свиданию с бывшим, он — с новой знакомой, и оба не видят друг друга через смежный забор. Обе встречи отменяются — и следующую они назначают друг другу.","primary_genre":"Кантри","primary_mood":"Романтика","primary_theme":"любовь","story_shelf":"Юмор: семейные драмы","conflict_key":"каждый-ждёт-чужое-счастье","image_key":"венок-и-фиалки-для-других","turn_key":"две-отмены-в-один-вечер","hook_key":"посмотри-кто-рядом","sort_order":"1356","original_key":"fedor-sologub|v-lugu-paslis-barashki","author_name":"Фёдор Сологуб","original_title":"В лугу паслись барашки...","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/sologub/v_lugu_paslis_barashki/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1927.","music_adaptations":[],"source_synopsis":"Пасторальная песенка-перекрёсток: Филис в лугу плетёт венок и ждёт Сильвандра, а Сильвандр в роще рвёт фиалки для Лизы черноокой — каждый ждёт не того, кто ждёт его.","main_image":"венок и фиалки, адресованные другим"},{"title":"Марш в птичьем горле","full_story":"Праправнук героя разбирает прадедовский архив и находит дневник, где сказано: снегирь, живший в доме, «запел колено военного марша» в день гибели командира. Скептик, он ставит эксперимент — находит запись того марша и включает дома птице. Поворот: попугай молчит, а соседский снегирь за окном — подхватывает, и скептик впервые плачет не от ностальгии, а от попадания.","hero_pov":"Скептик-праправнук у отцовского архива","central_conflict":"Насмешливый эксперимент против памяти, которая живёт в горле птицы, а не в архивах.","emotional_arc":"От холодной проверки к слезам узнавания","ending_direction":"Поворот: попугай молчит, а снегирь за окном подхватывает марш — скептик плачет от попадания","hook_direction":"Спой мне его марш","genres":["Фолк","Джаз"],"moods":["Боль","Сила"],"energy":"Низкая","themes":["голос","память"],"generator_brief":"Тихая фолк-баллада со свистом снегиря в интро и военным барабаном, приходящим издалека; без пафоса — только узнавание.","generator_story":"Праправнук находит в прадедовском дневнике: снегирь запел марш в день гибели командира. Скептик проверяет: попугай молчит, а снегирь за окном подхватывает марш — и он впервые плачет от попадания.","primary_genre":"Фолк","primary_mood":"Боль","primary_theme":"голос","story_shelf":"Люди и животные","conflict_key":"птичий-голос-против-забвения-героя","image_key":"снегирь-поёт-марш","turn_key":"попугай-молчит-снегирь-подхватывает","hook_key":"спой-мне-его-марш","sort_order":"1357","original_key":"gavrila-derzhavin|snegir","author_name":"Гаврила Державин","original_title":"Снегирь","original_language":"Russian","origin_country":"Россия","original_year":"1800","source_url":"https://ru.wikisource.org/wiki/Снегирь_(Державин)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1816.","music_adaptations":[],"source_synopsis":"Эпитафия Суворову: после известия о смерти полководца певчий снегирь, живший в доме поэта, запел военное колено марша. Поэт просит птичку пропеть тот марш, под который герой шёл в бой.","main_image":"снегирь поёт марш в доме скорбящего поэта"},{"title":"Пой мне о пропавшем","full_story":"После потери друга человек не может говорить о нём: все разговоры заканчиваются раньше слов. Он находит соловья в саду их общего детства и ходит туда слушать — птица поёт то, что он не выговаривает. Поворот: он записывает пение на телефон и отправляет родным друга с одной строкой — «здесь он ещё поёт», и впервые говорит о друге вслух.","hero_pov":"Человек, потерявший дар говорить о друге","central_conflict":"Немота горя против соловьиной песни, которая озвучивает невыговоренное.","emotional_arc":"От молчания у ветки к первому вслух сказанному имени","ending_direction":"Поворот: запись соловья уходит родным друга со строкой «здесь он ещё поёт»","hook_direction":"Пой мне о пропавшем","genres":["Джаз","Фолк"],"moods":["Тоска","Нежность"],"energy":"Низкая","themes":["голос","Потеря"],"generator_brief":"Джаз-элегия со свистом соловья вместо соло и мягкой щёткой по тарелке; голос — сдержанный рассказ у ветки.","generator_story":"После потери друга разговоры о нём обрываются раньше слов. Он слушает соловья в саду их общего детства — птица поёт невыговоренное, — и отправляет запись родным друга со строкой «здесь он ещё поёт».","primary_genre":"Джаз","primary_mood":"Тоска","primary_theme":"голос","story_shelf":"Люди и животные","conflict_key":"скорбь-и-песня-соловья","image_key":"соловей-на-ветке-у-сада-детства","turn_key":"запись-уходит-родным-друга","hook_key":"пой-мне-о-пропавшем","sort_order":"1358","original_key":"nikolay-karamzin|k-solovyu","author_name":"Николай Карамзин","original_title":"К соловью","original_language":"Russian","origin_country":"Россия","original_year":"1793","source_url":"https://rustih.ru/nikolaj-karamzin-k-solovyu","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1826.","music_adaptations":[],"source_synopsis":"Элегия-обращение к соловью: «о любезный соловей» — поэт просит птицу петь, и её песня становится голосом скорби и памяти о утраченном.","main_image":"соловей на ветке над скучающим садом"},{"title":"Не верь лёгким стихам","full_story":"Начинающий поэт за один вечер делает вирусную верлибру и мгновенную аудиторию — и тут же получает письмо от старого мастера: «приманная лёгкость». Оскорбившись, он идёт к нему за разоблачением зависти. Поворот: мастер заставляет его переписать ту же верлибру сто раз вслух — и на сотый раз поэт впервые слышит, где стих кончается, а начинается твит.","hero_pov":"Молодой поэт между хайпом и ремеслом","central_conflict":"Быстрая лёгкость, которая даёт аудиторию, против медленного труда, который даёт стих.","emotional_arc":"От оскорблённой гордости к сто раз сказанной правде","ending_direction":"Поворот: на сотом чтении вслух он слышит границу твига и стиха — и оставляет себе труд","hook_direction":"Не верь быстрым ответам","genres":["Рок","Метал"],"moods":["Протест","Уверенность"],"energy":"Взрывная","themes":["голос","призвание"],"generator_brief":"Злой рок-манифест с тикающим метрономом и шёпотом «приманной лёгкости» в левом канале; припев — удар правды.","generator_story":"Молодой поэт делает вирусную верлибру и получает от мастера письмо: «приманная лёгкость». Он идёт разоблачать зависть, но мастер заставляет сто раз читать её вслух — до границы между твигом и стихом.","primary_genre":"Рок","primary_mood":"Протест","primary_theme":"голос","story_shelf":"Трагические истории","conflict_key":"лёгкость-искуситель-против-труда","image_key":"стих-как-приманка-для-простых","turn_key":"сотое-чтение-вслух","hook_key":"не-верь-быстрым-ответам","sort_order":"1359","original_key":"zinaida-gippius|svobodnyy-stih","author_name":"Зинаида Гиппиус","original_title":"Свободный стих","original_language":"Russian","origin_country":"Россия","original_year":"1901","source_url":"https://www.culture.ru/literature/poems/author-zinaida-gippius","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1945.","music_adaptations":[],"source_synopsis":"Предостережение молодым поэтам: свободный стих зовёт и влечёт приманной лёгкостью, сулит быстрые ответы и соблазняет ленивых, малых и простых — а подлинная поэзия требует труда и глубины.","main_image":"стих-приманка для торопливых"},{"title":"Три струны и одна дочка","full_story":"Отец умершей дочки боится трогать её комнату, но однажды из шкафа выпадает её балалайка. Он не умеет играть — учится по памяти её фальшивых аккордов, и соседи впервые за год слышат музыку из его окон. Поворот: на годовщину он выходит играть к её школьному двору — и играет фальшиво нарочно, потому что «она так же играла».","hero_pov":"Отец с её балалайкой в руках","central_conflict":"Страх трогать память против единственного способа слышать дочку — взять её инструмент.","emotional_arc":"От замершего шкафа к фальшивому аккорду на школьном дворе","ending_direction":"Поворот: он играет нарочно фальшиво — «так же, как она», и двор подпевает","hook_direction":"Поиграй мне, Раечка","genres":["Фолк","Кантри"],"moods":["Грусть","Тепло"],"energy":"Низкая","themes":["голос","семья"],"generator_brief":"Три струны балалайки в записи с проседающей интонацией; куплеты — говорком, припев — почти колыбельная.","generator_story":"Из шкафа погибшей дочери выпадает балалайка. Отец, не умея играть, учится по памяти её фальшивых аккордов, а на годовщину выходит к школьному двору и играет фальшиво нарочно — так же, как играла она.","primary_genre":"Фолк","primary_mood":"Грусть","primary_theme":"голос","story_shelf":"Трагические истории","conflict_key":"голос-дочки-в-трёх-струнах","image_key":"балалайка-вместо-колыбельной","turn_key":"нарочно-фальшивые-аккорды","hook_key":"поиграй-мне-раечка","sort_order":"1360","original_key":"fedor-sologub|balalayka","author_name":"Фёдор Сологуб","original_title":"Балалайка...","original_language":"Russian","origin_country":"Россия","original_year":"1902","source_url":"https://slova.org.ru/sologub/balalajkamoja/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1927.","music_adaptations":[],"source_synopsis":"Простая песенка-жалоба: у старика была дочка Раечка — жила, цвела, умерла; теперь он не пьёт и не плачет, а берёт балалайку, потому что в её трёх струнах живёт память о дочери.","main_image":"балалайка вместо колыбельной в пустом доме"},{"title":"Бездна без счёта","full_story":"Астроном-любитель в разгар личного краха поднимается на крышу с телескопом, чтобы хоть раз «посчитать» свою жизнь до конца. Счёт рушится на первой звезде: число не сходится, дна нет. Поворот: крах не уменьшается, но рядом с бездной становится правильного размера — и он спускается с крыши, чтобы утром начать разбирать завал по одному.","hero_pov":"Астроном-любитель на ночной крыше","central_conflict":"Желание досчитать свою жизнь до конца против бездны, в которой число и дно не существуют.","emotional_arc":"От судорожного счёта к правильному размеру своих бед","ending_direction":"Поворот: крах остался, но стал правильного размера — утром он разбирает завал по одному","hook_direction":"Смотри в бездну без страха","genres":["Эмбиент","Джаз"],"moods":["Мечтательность","Смелость"],"energy":"Средняя","themes":["Природа","Время"],"generator_brief":"Космический эмбиент с настоящими записями ночного города и редким фортепиано, отсчитывающим несчитаемое.","generator_story":"Астроном-любитель поднимается на крышу посчитать жизнь до конца — счёт рушится на первой звезде, дна нет. Зато крах рядом с бездной становится правильного размера: утром он разберёт завал по одному.","primary_genre":"Эмбиент","primary_mood":"Мечтательность","primary_theme":"Природа","story_shelf":"Любовные сцены","conflict_key":"бездна-звёзд-против-человеческого-счёта","image_key":"бездна-полная-звёзд","turn_key":"крах-стал-правильного-размера","hook_key":"смотри-в-бездну-без-страха","sort_order":"1361","original_key":"mikhail-lomonosov|vechernee-razmyshlenie","author_name":"Михаил Ломоносов","original_title":"Вечернее размышление о Божием величестве","original_language":"Russian","origin_country":"Россия","original_year":"1743","source_url":"https://ru.wikisource.org/wiki/Вечернее_размышление_о_Божием_величестве_(Ломоносов)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1765.","music_adaptations":[],"source_synopsis":"Ночная ода-размышление: взглянув в небо, поэт видит бездну, звёзд полна, — звёздам числа нет, бездне дна; перед этой бездной человек задаёт великие вопросы о мире и своём месте в нём.","main_image":"бездна, полная звёзд, над ночной землёй"},{"title":"Слава тонет в водопаде","full_story":"Три бывших одноклассника возвращаются в родное ущелье, где когда-то кляли друг другу славу, — теперь один почти известен, второй при деньгах, третий просто живёт у водопада. На гудении воды они впервые читают вслух свои старые клятвы. Поворот: гул глотает все имена одинаково — и третий, единственный, кто остался здесь жить, оказывается тем, кто помнит всех троих наизусть.","hero_pov":"Тот, кто остался жить у водопада","central_conflict":"Гонка за громкой славой против вечного гула, который глотает любые имена одинаково.","emotional_arc":"От сравнения успехов к пониманию, что помнит — не слава, а тот, кто остался","ending_direction":"Поворот: гул глотает имена — и «никем» оказывается тем, кто хранит всех троих наизусть","hook_direction":"Слышу в громе его","genres":["Эпик-рок","Рок"],"moods":["Сила","Грусть"],"energy":"Взрывная","themes":["Природа","Потеря"],"generator_brief":"Гремящий эпик-рок с настоящим водопадным гулом в основе; три голоса перебивают друг друга, пока не остаётся один рассказчик.","generator_story":"Три одноклассника возвращаются в ущелье, где клялись славой: один почти известен, второй при деньгах, третий живёт у водопада. Гул глотает имена одинаково — и оставшийся помнит всех троих наизусть.","primary_genre":"Эпик-рок","primary_mood":"Сила","primary_theme":"Природа","story_shelf":"Трагические истории","conflict_key":"гром-природы-против-тонущей-славы","image_key":"гремящий-водопад-и-имена","turn_key":"третий-помнит-всех-наизусть","hook_key":"слышу-в-громе-его","sort_order":"1362","original_key":"gavrila-derzhavin|vodopad","author_name":"Гаврила Державин","original_title":"Водопад","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://ru.wikisource.org/wiki/Водопад_(Державин)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1816.","music_adaptations":[],"source_synopsis":"Гремящий водопад для Державина — образ громкой судьбы: как водопад гремит и падает, так тонет и человеческая слава; рядом с вечной силой воды любые имена — недолгий шум.","main_image":"гремящий водопад, у которого звучат имена"},{"title":"Осторожно: лягушки","full_story":"Рассерженный начальник после увольнения идёт через дождь по парку и вдруг видит под ногами дорожку из лягушек, по которой ежедневно торопится на работу. Он впервые обходит её — и опаздывает в последний день, освободив утро. Поворот: через месяц он возвращается в этот парк уже как экскурсовод для детей — «смотрите под ноги: здесь чьи-то дорожки».","hero_pov":"Человек, который обошёл лягушачью дорожку","central_conflict":"Торопливая ярость уволенного против мокрой дорожки, на которой живут другие.","emotional_arc":"От мокрой ярости к бережному шагу и новому делу","ending_direction":"Поворот: через месяц он водит детей по тому же парку учить смотреть под ноги","hook_direction":"Ступай осторожно","genres":["Лоу-фай","Фолк"],"moods":["Ирония","Нежность"],"energy":"Низкая","themes":["Природа","животные"],"generator_brief":"Дождевой лоу-фай с настоящим кваканьем в ритме и скрипом ботинок; голос — ворчливый, а потом удивлённо-тихий.","generator_story":"Уволенный идёт через парк и видит лягушачью дорожку, по которой торопился на работу каждый день, — впервые обходит её. Месяц спустя водит детей: смотрите под ноги, здесь чьи-то дорожки.","primary_genre":"Лоу-фай","primary_mood":"Ирония","primary_theme":"Природа","story_shelf":"Люди и животные","conflict_key":"дорожка-мокрая-против-лягушачьих-жизней","image_key":"лягушки-по-мокрой-дорожке","turn_key":"увольнение-освобождает-утро","hook_key":"ступай-осторожно","sort_order":"1363","original_key":"fedor-sologub|ah-lyagushki-po-dorozhke","author_name":"Фёдор Сологуб","original_title":"Ах, лягушки по дорожке...","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/sologub/ah_lyagushki/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1927.","music_adaptations":[],"source_synopsis":"Пастушка бежит по мокрой дорожке и боится наступить на лягушек, вытянувших ножки: «хоть лягушки ей не жалко — ведь лягушка не фиалка», но скользкий хруст под ногой заставляет её падать и царапать руки о кусты.","main_image":"лягушки, вытянувшие ножки, по мокрой дорожке"},{"title":"Кот и мышь одного четверга","full_story":"Малыш, который боится засыпать, придумывает с папой систему: ночь — это чёрный кот, а день — серенькая мышь, которую кот отпускает погулять по утрам. Родители играют вместе, пока бессонница не становится их общей сказкой. Поворот: в детском саду малыш объясняет систему другим страшащимся — и воспитательница записывает её на доске как официальную правила комнаты.","hero_pov":"Малыш, придумавший правила для ночи","central_conflict":"Страх темноты против игры, в которой ночь и день становятся зверятами, а не угрозами.","emotional_arc":"От страхов под одеялом к officiальной сказке всей группы","ending_direction":"Поворот: его сказку записывают на доске — и другие страшащиеся засыпают под неё","hook_direction":"Поймай свой день","genres":["Кантри","Лоу-фай"],"moods":["Мечтательность","Радость"],"energy":"Низкая","themes":["Природа","детство"],"generator_brief":"Колыбельный кантри с мяуканьем и писком в перкуссии, папой-рассказчиком и детским хором на бридже.","generator_story":"Малыш, боящийся темноты, придумывает с папой сказку: ночь — чёрный кот, день — серенькая мышь, которую кот отпускает поутру. В детском саду правило записывают на доске — и вся группа засыпает.","primary_genre":"Кантри","primary_mood":"Мечтательность","primary_theme":"Природа","story_shelf":"Люди и животные","conflict_key":"ночь-кот-день-мышь","image_key":"чёрный-кот-и-серая-мышь-дня","turn_key":"сказка-малыши-становится-правилами-группы","hook_key":"поймай-свой-день","sort_order":"1364","original_key":"poliksena-solovyova|chetverg","author_name":"Поликсена Соловьёва","original_title":"Четверг","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://ru.wikipedia.org/wiki/Соловьёва,_Поликсена_Сергеевна","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1924.","music_adaptations":[],"source_synopsis":"Детское стихотворение Поликсены Соловьёвой: ночь зимой — как чёрный кот, день — как серенькая мышь; мир, в котором время суток описано через живых зверят.","main_image":"чёрный кот ночи и серенькая мышь дня"},{"title":"Между звёздами и землёй","full_story":"Хирург, который сегодня спас человека и вчера потерял, впервые не спит после смены и записывает обе истины: он бог для спасённого и червь для того, кого не успел. Пациенты и коллеги ждут от него одного пафоса — героического или виноватого. Поворот: он вывешивает в операционной обе таблички — «ты бог» и «ты червь» — и начинает учить интернов держать обе правды сразу.","hero_pov":"Хирург между спасением и потерей","central_conflict":"Величие человека-спасителя против его ничтожества перед смертью — и попытка жить с обеими правдами.","emotional_arc":"От бешеного маятника к прямой спине с двумя табличками","ending_direction":"Поворот: обе таблички висят в операционной — интернов учат держать обе правды сразу","hook_direction":"И червь, и бог","genres":["Метал","Эпик-рок"],"moods":["Уверенность","Эйфория"],"energy":"Взрывная","themes":["самопринятие","Сила"],"generator_brief":"Космический метал с органным пафосом и переходом от рёва «я бог» к шёпоту «я червь» в одном куплете.","generator_story":"Хирург, вчера потерявший пациента, а сегодня спасший человека, не спит: для спасённого он бог, для неспасённого — червь. В операционной он вывешивает обе таблички и учит интернов держать обе правды.","primary_genre":"Метал","primary_mood":"Уверенность","primary_theme":"самопринятие","story_shelf":"Трагические истории","conflict_key":"червь-и-бог-в-одной-груди","image_key":"человек-между-звёздами-и-землёй","turn_key":"две-таблички-в-операционной","hook_key":"и-червь-и-бог","sort_order":"1365","original_key":"gavrila-derzhavin|bog","author_name":"Гаврила Державин","original_title":"Бог","original_language":"Russian","origin_country":"Россия","original_year":"1784","source_url":"https://ru.wikisource.org/wiki/Бог_(Державин)","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1816.","music_adaptations":[],"source_synopsis":"Великая ода: человек — царь и раб, червь и Бог одновременно; он венец природы и её ничтожество, и через это противоречие поэт идёт к Творцу, себе подобному величию.","main_image":"человек между звёздами и землёй"},{"title":"Три ответа на крыльце","full_story":"Уволенный топ-менеджер возвращается в отчий дом и спрашивает живущих там трёх — отца, брата и соседа — «а ты зачем живёшь?». Первый отвечает про обед, второй про рыбалку, третий честно: не ведаю, делаю, что велели. Поворот: их простые ответы оказываются честнее его корпоративной миссии на визитке — и он переписывает резюме их словами.","hero_pov":"Барин, задающий вопрос с крыльца","central_conflict":"Разучившаяся отвечать «успешная» жизнь против трёх простых честных ответов о смысле.","emotional_arc":"От пафосного вопроса к стыдливому заимствованию правды","ending_direction":"Поворот: он переписывает своё резюме словами отца, брата и соседа","hook_direction":"А ты зачем живёшь","genres":["Джаз","Фолк"],"moods":["Ирония","Радость"],"energy":"Высокая","themes":["самопринятие","Выбор"],"generator_brief":"Дворовый джаз с крылечным стуком и тремя разыми голосами-персонажами; припев — общий вопрос, который не отпускает.","generator_story":"Уволенный топ-менеджер спрашивает на крыльце, зачем живут отец, брат и сосед. Ответы про обед, рыбалку и честное «не ведаю» оказываются честнее миссии на визитке — и он переписывает резюме их словами.","primary_genre":"Джаз","primary_mood":"Ирония","primary_theme":"самопринятие","story_shelf":"Юмор: семейные драмы","conflict_key":"вопрос-о-смысле-три-смешных-ответа","image_key":"барин-и-три-слуги-на-крыльце","turn_key":"резюме-переписано-их-словами","hook_key":"а-ты-зачем-живёшь","sort_order":"1366","original_key":"denis-fonvizin|poslanie-k-slugam-moim","author_name":"Денис Фонвизин","original_title":"Послание к слугам моим Шумилову, Ваньке и Петрушке","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://ru.wikisource.org/wiki/Послание_к_слугам_моим_Шумилову,_Ваньке_и_Петрушке","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1792.","music_adaptations":[],"source_synopsis":"Сатирический диалог: барин спрашивает трёх слуг, зачем Бог создал их на свет. Шумилов думает о каше, Ванька — об охотничьих забавах, Петрушка честно отвечает: зачем я — не ведаю, делаешь, что приказано.","main_image":"барин и три слуги на крыльце"},{"title":"Ворона знала себя","full_story":"Шарма-агент обещает нестоличной певице «кухни-стадионы» за отказ от собственного репертуара. Она слушает лесть десять минут — и отвечает его же словами из басни: знаю я себя. Поворот: через год его «новые звёзды» растворяются, а её концерт в районном зале идёт по доверенности от тех, кто пришёл «за своим».","hero_pov":"Певица, знающая свой голос","central_conflict":"Лесть продюсера против точного знания себя, которое дороже любых стадионов.","emotional_arc":"От соблазнительного предложения к спокойному отказу и своему залу","ending_direction":"Поворот: через год его звёзды исчезают — её районный зал полон тех, кто пришёл за своим","hook_direction":"Знаю я себя","genres":["Кантри","Джаз"],"moods":["Уверенность","Ирония"],"energy":"Высокая","themes":["самопринятие","животные"],"generator_brief":"Джазовая пикировка с лисьим саксофоном и уверенной вокальной линии вороны; финал — зал, поющий её репертуар.","generator_story":"Агент обещает певице «кухни-стадионы» за отказ от репертуара — она отвечает словами басни: ворона знает себя. Через год его новые звёзды растворяются, а её районный зал полон тех, кто пришёл за своим.","primary_genre":"Кантри","primary_mood":"Уверенность","primary_theme":"самопринятие","story_shelf":"Люди и животные","conflict_key":"лесть-против-знания-себя","image_key":"ворона-с-сыром-на-дубе","turn_key":"его-звёзды-тают-её-зал-полон","hook_key":"знаю-я-себя","sort_order":"1367","original_key":"aleksandr-sumarokov|vorona-i-lisa","author_name":"Александр Сумароков","original_title":"Ворона и Лиса","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://pishi-stihi.ru/vorona-i-lisa-sumarokov.html","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1777.","music_adaptations":[],"source_synopsis":"Басня до Крылова: лиса льстит вороне с сыром — а у Сумарокова ворона не клюёт на лесть и отвечает: «Ты мне льстить напрасно; знаю я себя», — держа сыр в клюве.","main_image":"ворона с сыром на дубе, не поддающаяся лести"},{"title":"Творец без кумиров","full_story":"Художник-самоучка после отказа галереи («нет школы, нет кумиров») запирается на год и строит собственный мир на стенах квартиры. Друзья тащат его «подучиться правильно» — он отвечает, что у него нет никого выше своей мечты. Поворот: галерея сама стучится, увидев фото из окна соседа, — и он соглашается продать стены, но не правду их происхождения.","hero_pov":"Художник, который не открыл никому своей природы","central_conflict":"Рабский ежедневный труд без признания против соблазна признать чужих кумиров и получить школу.","emotional_arc":"От тёмного упорства к светлой сделке без сдачи себя","ending_direction":"Поворот: он продаёт картины, но оставляет себе право не открывать никому свою природу","hook_direction":"Мой мир во мне","genres":["Рок","Метал"],"moods":["Одиночество","Уверенность"],"energy":"Высокая","themes":["самопринятие","призвание"],"generator_brief":"Гордый рок с ночным гулом города и одинокой гитарой вместо хора; припев — тихий, как признание бога самому себе.","generator_story":"Художник-самоучка после отказа галереи год строит свой мир на стенах квартиры — без школы и кумиров. Когда галерея сама стучится, он соглашается продать стены, но никому не открывает их природу.","primary_genre":"Рок","primary_mood":"Одиночество","primary_theme":"самопринятие","story_shelf":"Трагические истории","conflict_key":"рабский-труд-против-божественного-мира","image_key":"творец-в-ночи-без-кумиров","turn_key":"продаёт-стены-но-не-правду","hook_key":"мой-мир-во-мне","sort_order":"1368","original_key":"fedor-sologub|ya-bog-tainstvennogo-mira","author_name":"Фёдор Сологуб","original_title":"Я — бог таинственного мира...","original_language":"Russian","origin_country":"Россия","original_year":"1896","source_url":"https://slova.org.ru/sologub/jabog/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1927.","music_adaptations":[],"source_synopsis":"Поэт заявляет: я — бог таинственного мира, весь мир в одних моих мечтах; не сотворю себе кумира ни на земле, ни в небесах, своей божественной природы не открою никому — тружусь, как раб, а для свободы зову ночь и тьму.","main_image":"творец в ночи без кумиров"},{"title":"Верни им вольность","full_story":"Потомок крепостной семьи читает в архиве оду, которую его предок-поэт писал двести с лишним лет назад и боялся печатать сорок лет. Он решает закончить её дело: записывает истории своих земляков на видео и вывозит их в столицу. Поворот: премьера фильма проходит в зале, где сидят потомки и того указа, и те и другие аплодируют стоя — ода наконец допета чужими голосами.","hero_pov":"Потомок, дописывающий чужую оду","central_conflict":"Страх и умолчание сорока лет против гнева, который должен быть допет чужими голосами.","emotional_arc":"От архивной тишины к стоячей овации двух враждебных залов","ending_direction":"Поворот: ода допета — потомки кандалов и вольности аплодируют стоя в одном зале","hook_direction":"Верни им вольность","genres":["Рок","Эпик-рок"],"moods":["Злость","Вдохновение"],"energy":"Взрывная","themes":["спасение","свобода"],"generator_brief":"Протестный рок-гимн с настоящими оковами в перкуссии и хором, который подхватывает оду на чужом языке поколений.","generator_story":"Потомок крепостных находит оду предка, которую тот сорок лет боялся печатать, и снимает истории земляков. На премьере потомки кандалов и вольности аплодируют стоя — ода допета чужими голосами.","primary_genre":"Рок","primary_mood":"Злость","primary_theme":"спасение","story_shelf":"Трагические истории","conflict_key":"указ-о-кандалах-против-гнева-поэта","image_key":"оковы-на-свободных-руках","turn_key":"ода-допета-чужими-голосами","hook_key":"верни-им-вольность","sort_order":"1369","original_key":"vasily-kapnist|oda-na-rabstvo","author_name":"Василий Капнист","original_title":"Ода на рабство","original_language":"Russian","origin_country":"Россия","original_year":"1783","source_url":"http://az.lib.ru/k/kapnist_w_w/text_0030.shtml","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1823.","music_adaptations":[],"source_synopsis":"Гневная ода, написанная в ответ на указ о закрепощении крестьян: поэт скорбит и негодует, видя, как свободных людей одевают в кандалы, и зовёт восстановить вольность. Написана в 1783-м, напечатана только в 1806-м.","main_image":"оковы на свободных руках"},{"title":"Крылья отрастут к весне","full_story":"Влюблённых разводят обстоятельства: запрет семьи, работа за границей, всё «на два года». Каждый строит клетку, чтобы пережить разлуку, — и вместо этого бережёт по одному крылу. Поворот: весной они встречаются без торжества, у будки с ключами, и первым делом открывают свою собственную клетку — в которой всё это время жил не они, а их страх.","hero_pov":"Один из двоих, отращивающих крылья","central_conflict":"Обстоятельства, построившие клетку на два года, против крыльев, которые растут вопреки прутьям.","emotional_arc":"От терпеливой дрессуры страха к весеннему взлёту вдвоём","ending_direction":"Поворот: у будки с ключами они открывают клетку не друг другу — а своему страху","hook_direction":"Весна откроет клетку","genres":["Эпик-рок","Фолк"],"moods":["Освобождение","Надежда"],"energy":"Высокая","themes":["спасение","любовь"],"generator_brief":"Парящий эпик-рок с ростом крыльев в аранжировке: от клеточного тиканья к полному взлёту духовых на финале.","generator_story":"Влюблённых разводят на два года — каждый строит клетку, чтобы пережить разлуку, и бережёт по одному крылу. Весной они встречаются у будки с ключами и открывают клетку не друг другу — а своему страху.","primary_genre":"Эпик-рок","primary_mood":"Освобождение","primary_theme":"спасение","story_shelf":"Любовные сцены","conflict_key":"клетка-против-весны","image_key":"амур-с-отрастающими-крыльями","turn_key":"клетка-открыта-страху-а-не-люди","hook_key":"весна-откроет-клетку","sort_order":"1370","original_key":"fedor-sologub|skoro-krylya-otrastut","author_name":"Фёдор Сологуб","original_title":"Скоро крылья отрастут...","original_language":"Russian","origin_country":"Россия","original_year":"","source_url":"https://slova.org.ru/sologub/skoro_kriliya_otrastut/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1927.","music_adaptations":[],"source_synopsis":"Песня о пленённом Амуре: прутья клетки не разбить соловью или робкой кенке, но Амура полонить разве могут эти стенки? Придёт весна — и проснувшийся от сна Амур улетит из клетки.","main_image":"Амур с отрастающими крыльями в клетке"},{"title":"Рассвет после долгой ночи","full_story":"Ночь, в которую они едва не потеряли друг друга — ссора, дверь, полупустая улица, — тянется до пяти утра. В пять оба возвращаются: он — на крышу, она — на балкон, и видят друг друга первыми в свете зари, когда звёзды побледнели. Поворот: они не спят — они встречают рассвет молча, и первая фраза «как легко дышать» произносится одновременно обоими.","hero_pov":"Один из двоих на рассветной крыше","central_conflict":"Ночь, чуть не разделившая их навсегда, против рассвета, который они встречают с двух сторон одного двора.","emotional_arc":"От хлопнувшей двери к одновременной фразе на двоих","ending_direction":"Поворот: «как легко дышать» говорят оба сразу — и ночь впервые становится их общей","hook_direction":"Ночь позади — дышим","genres":["Эмбиент","Джаз"],"moods":["Надежда","Нежность"],"energy":"Низкая","themes":["спасение","ночь"],"generator_brief":"Рассветный эмбиент с зеленеющим небом в синтезаторах и двумя голосами, произносящими одну фразу в унисон.","generator_story":"Ночь после ссоры тянется до пяти утра. В пять оба возвращаются: он на крышу, она на балкон — и молча встречают рассвет, одновременно сказав: «как легко дышать». Ночь впервые становится их общей.","primary_genre":"Эмбиент","primary_mood":"Надежда","primary_theme":"спасение","story_shelf":"Любовные сцены","conflict_key":"долгая-ночь-против-грядущего-солнца","image_key":"бледное-лицо-в-свете-зари","turn_key":"одна-фраза-сказана-обоими","hook_key":"ночь-позади-дышим","sort_order":"1371","original_key":"mihail-kuzmin|utro","author_name":"Михаил Кузмин","original_title":"Утро","original_language":"Russian","origin_country":"Россия","original_year":"1907","source_url":"https://slova.org.ru/kuzmin/utro_zvezdi/","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1936.","music_adaptations":[],"source_synopsis":"Рассветная зарисовка: звёзды побледнели, небо зеленеет, ветер поднят, — как легко дышать после долгой ночи и чада свечей; и как бледно лицо любимого в свете грядущего солнца.","main_image":"бледное лицо любимого в свете зари"},{"title":"Запах речки с родины","full_story":"Обедневший певец из диаспоры поёт на корпоративном ужине для уехавших — не о деньгах, а о запахе речки, где все выросли. Зал сначала шутит, потом замолкает; к третьему куплету половина комнаты звонит мамам, кто-то бронирует билеты. Хозяин вечера молча расплачивается и уезжает первым — не в свой офис, а в свой город.","hero_pov":"певец, чья песня разворачивает людей назад","central_conflict":"Успешная чужая жизнь против дома, который не звал: песня делает выбор за людей, потому что запах воды сильнее карьеры.","emotional_arc":"от светского ужина к тишине и общему повороту домой","ending_direction":"Хозяин вечера платит и уезжает первым — не в офис, а в родной город; певец остаётся петь пустому залу и смеётся: песня сделала своё.","hook_direction":"запах речки зовёт домой","genres":["Регги","Соул"],"moods":["Тепло","Мечтательность"],"energy":"Средняя","themes":["голос","Природа"],"generator_brief":"Тёплый корневой регги: качающий бас как вода реки, гитарные проигрыши, усталый голос — песня, от которой зал разворачивается домой.","generator_story":"Певец на ужине уехавших земляков поёт не о деньгах, а о запахе речки, где все выросли. Зал замолкает, половина звонит мамам, а хозяин вечера платит и уезжает первым — не в офис, а в родной город.","primary_genre":"Регги","primary_mood":"Тепло","primary_theme":"голос","story_shelf":"Трагические истории","conflict_key":"успех-чужого-города-против-запаха-речки","image_key":"песня-разворачивающая-караван","turn_key":"хозяин-уезжает-первым","hook_key":"запах-речки-зовёт-домой","sort_order":"1372","original_key":"rudaki|bo-ye-muliyan","author_name":"Рудаки","original_title":"Бӯи ҷӯи Мӯлиён (Запах реки Мулиён)","original_language":"Persian","origin_country":"Таджикистан","original_year":"","source_url":"https://en.wikipedia.org/wiki/Rudaki","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 941.","music_adaptations":[],"source_synopsis":"Отец персидской поэзии спел в свите эмира о речке Мулиён — о запахе родной воды и памяти о друге. По легенде, эмир, год не бывший в Бухаре, повернул коня домой, не успев даже обуться.","main_image":"песня, которая разворачивает караван назад"},{"title":"Стойка из трости","full_story":"Семидесятилетний сварщик теряет зрение и стесняется трости: во двор с ней не выйти, соседи увидят. Внучка вешает на его старую трость провод и держатель — превращает её в стойку для домашнего караоке. Он выходит с ней к гостям как с инструментом и поёт первый раз за двадцать лет; трость больше не стыд — опора и микрофон в одном.","hero_pov":"дед, который стеснялся трости","central_conflict":"Стыд старения против права выйти во двор: трость либо позор, либо инструмент — он выбирает инструмент.","emotional_arc":"от запертой гордости к выходу на свет с тростью-стойкой","ending_direction":"Он поёт гостям впервые за двадцать лет — трость стоит в центре комнаты как микрофонная стойка, и стыд кончается.","hook_direction":"опора — это тоже инструмент","genres":["Электропоп","Баллада"],"moods":["Нежность","Уверенность"],"energy":"Средняя","themes":["самопринятие","семья"],"generator_brief":"Тёплый электропоп с лёгкими духовыми: мерный стук трости в ритме, дедовский голос с хрипотцой, припев — как выход из подъезда на солнце.","generator_story":"Сварщик теряет зрение и стесняется трости — внучка вешает на неё провод, превращая в стойку для караоке. Он выходит с ней к гостям как с инструментом и поёт впервые за двадцать лет: стыд кончился.","primary_genre":"Электропоп","primary_mood":"Нежность","primary_theme":"самопринятие","story_shelf":"Юмор: семейные драмы","conflict_key":"стыд-трости-против-выхода-во-двор","image_key":"трость-с-держателем-микрофона","turn_key":"поёт-впервые-за-двадцать-лет","hook_key":"опора-тоже-инструмент","sort_order":"1373","original_key":"rudaki|shikoyat-az-piri","author_name":"Рудаки","original_title":"Шикоят аз пири (Жалоба на старость)","original_language":"Persian","origin_country":"Таджикистан","original_year":"","source_url":"https://en.wikipedia.org/wiki/Rudaki","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 941.","music_adaptations":[],"source_synopsis":"Достоверное стихотворение слепого Рудаки о старости: он перечисляет, каким был и каким стал, — сила ушла, зубы не жуют, без трости не сделать шага; старость он называет в лицо, без тоски.","main_image":"трость вместо позора — микрофонная стойка"},{"title":"Письмо к кувшину","full_story":"Отец и сын в ссоре пять лет. Отец не звонит, а присылает ящик винограда своего последнего урожая — и письмо-инструкцию: дави, запирай, жди. Сын выполняет шаги весь год, не отвечая. Вино готово к дню, когда отца не становится; на первой дегустации сын читает письмо вслух гостям и первым поднимает кубок в сторону сада — ссора закончилась, инструкция оказалась письмом о том, как жить дальше.","hero_pov":"сын, который делал вино по письму молчащего отца","central_conflict":"Пять лет молчания против инструкции, оставленной без объяснений: отец учит делом, сын должен понять сам или не понять никогда.","emotional_arc":"от немой обиды к пониманию и общему кубку","ending_direction":"На дегустации сын читает письмо вслух и поднимает первый кубок в сторону отцовского сада — молчание закончилось, вино получилось.","hook_direction":"сначала расти — потом выдержи","genres":["Хаус","Поп"],"moods":["Вина","Надежда"],"energy":"Средняя","themes":["Риск","Семья"],"generator_brief":"Тёплый домашний хаус: шуршание листьев в перкуссии, ровный голос сына, в финале — звон кубков и хриплое «за сад» всем составом.","generator_story":"Отец не звонит сыну и шлёт ящик винограда с инструкцией: дави, запирай, жди. Вино готово к дню, когда отца не стало: на дегустации сын читает письмо и поднимает кубок в сторону отцовского сада.","primary_genre":"Хаус","primary_mood":"Вина","primary_theme":"Риск","story_shelf":"Юмор: семейные драмы","conflict_key":"молчание-отца-против-инструкции-в-подарке","image_key":"письмо-привязанное-к-кувшину","turn_key":"вино-готово-к-дню-прощания","hook_key":"сначала-расти-потом-выдержи","sort_order":"1374","original_key":"rudaki|modar-e-may","author_name":"Рудаки","original_title":"Мадар-е мая (Мать вина)","original_language":"Persian","origin_country":"Таджикистан","original_year":"","source_url":"https://en.wikipedia.org/wiki/Rudaki","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 941.","music_adaptations":[],"source_synopsis":"Целиком сохранившаяся касыда 933 года — послание, приложенное к дарственному кувшину с вином: шутовская инструкция, как из винограда делают вино — сперва раздавить «мать», потом запереть «дитя» до срока.","main_image":"письмо-инструкция, привязанное к кувшину"},{"title":"Элегия, написанная заранее","full_story":"Он выгорел так, что чувствует себя уже умершим, и пишет себе некролог — честный, без героизма. Вешает его в рамку над столом и живёт дальше: каждое утро читает, кого «похоронил», и замечает, что дышит. Через год дописывает внизу строчку: «ошибся — этот ещё жив», и рамка становится не надгробием, а дверью.","hero_pov":"человек, похоронивший себя заранее","central_conflict":"Ощущение внутренней смерти против факта живого дыхания: он проверяет свой некролог каждое утро на правду.","emotional_arc":"от выгоревшей пустоты к лёгкости живого","ending_direction":"Через год он дописывает «ошибся — этот ещё жив» — надгробие становится дверью, и он выходит.","hook_direction":"ещё жив — и это не ошибка","genres":["Синтвейв","Эмбиент"],"moods":["Спокойствие","Освобождение"],"energy":"Средняя","themes":["самопринятие","Память"],"generator_brief":"Ретро-синтвейв с тёплым хромированным пэдом: голос читает некролог ровно, в финале один живой аккорд и включённый свет.","generator_story":"Выгоревший до ощущения собственной смерти, он пишет себе некролог и вешает в рамку. Каждое утро он проверяет его на правду — через год дописывает внизу: ошибся, этот жив. Рамка становится дверью.","primary_genre":"Синтвейв","primary_mood":"Спокойствие","primary_theme":"самопринятие","story_shelf":"Трагические истории","conflict_key":"внутренняя-смерть-против-живого-дыхания","image_key":"некролог-в-рамке-над-столом","turn_key":"ошибся-этот-ещё-жив","hook_key":"ещё-жив-и-не-ошибка","sort_order":"1375","original_key":"al-maarri|self-elegy","author_name":"Абу аль-Аля аль-Маарри","original_title":"Сам себе элегия","original_language":"Arabic","origin_country":"Сирия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Al-Ma%CA%BFarri","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1057.","music_adaptations":[],"source_synopsis":"Слепой поэт-философ написал себе элегию заранее — попрощался с собой при жизни, как с чужим покойником, и жил дальше налегке.","main_image":"некролог, написанный собственной рукой заранее"},{"title":"Пленник двух темниц","full_story":"Незрячий с детства парень запирается дома: люди жалеют, улица пугает. Он осваивает звукорежиссуру на слух и сводит треки для соседских групп в своей «темнице». Когда один из треков выстреливает, студия зовёт его к себе — его «затвор» оказывается профессией, а слепота — способностью слышать то, что зрячие проглядели.","hero_pov":"незрячий звукорежиссёр","central_conflict":"Две темницы — слепота и запертая комната — против слуха, который точнее зрения: он делает из темницы рабочее место.","emotional_arc":"от жалости к себе к профессиональной силе","ending_direction":"Его трек выходит с пометкой «сведено на слух» — темница становится самой светлой комнатой города.","hook_direction":"я слышу то, чего не видите","genres":["Техно","Эмбиент"],"moods":["Одиночество","Сила"],"energy":"Низкая","themes":["голос","самопринятие"],"generator_brief":"Сухое минимал-техно: микшерные щелчки как ориентиры на ощупь, чистый вокал без жалобы, финал — открывшаяся дверь с уличным шумом.","generator_story":"Незрячий с детства парень сводит треки соседским группам на слух, не выходя из дома. Когда один выстреливает, студия зовёт его к себе: то, чего зрячие проглядели, выходит с пометкой «сведено на слух».","primary_genre":"Техно","primary_mood":"Одиночество","primary_theme":"голос","story_shelf":"Трагические истории","conflict_key":"две-темницы-против-точного-слуха","image_key":"микшер-на-ощупь","turn_key":"трек-с-пометкой-сведено-на-слух","hook_key":"слышу-чего-не-видите","sort_order":"1376","original_key":"al-maarri|two-prisons","author_name":"Абу аль-Аля аль-Маарри","original_title":"Диван аль-Маарри (строки о двух темницах)","original_language":"Arabic","origin_country":"Сирия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Al-Ma%CA%BFarri","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1057.","music_adaptations":[],"source_synopsis":"Ослепший в детстве и добровольно затворившийся поэт называл себя пленником двух темниц — слепоты и уединения; при этом его стихи слышала вся арабская земля.","main_image":"микшер на ощупь, звук вместо света"},{"title":"Плакальщик и терпеливый","full_story":"Умер их общий друг: один рыдает открыто все сорок дней, второй «держится» и делает всё правильно. На ночном дежурстве у дома терпеливый ломается в четыре утра — и рыдающий обнимает его первым: терпение тоже плачет, просто позже. Они договариваются горевать вслух — и сорок дней заканчиваются не графиком, а общим завтраком.","hero_pov":"тот, кто держался и сломался","central_conflict":"Держаться правильно против рыдать открыто: терпение оказывается отложенным плачем, и тот, кто молчал, ломается первым.","emotional_arc":"от соревнования в стойкости к общему горю вслух","ending_direction":"В четыре утра терпеливый плачет, рыдающий обнимает его первым — сорок дней заканчиваются общим завтраком, а не графиком.","hook_direction":"терпение тоже плачет","genres":["Трэп","Баллада"],"moods":["Грусть","Нежность"],"energy":"Средняя","themes":["Примирение","Память"],"generator_brief":"Ночной трэп-баллада: приглушённые 808 как сдержанное дыхание, два голоса — ровный и срывающийся, финал на одном дыхании без бита.","generator_story":"Над умершим другом один рыдает все сорок дней, второй держится. В четыре утра на дежурстве терпеливый ломается — и рыдающий обнимает его первым: сорок дней кончаются общим завтраком, а не графиком.","primary_genre":"Трэп","primary_mood":"Грусть","primary_theme":"Примирение","story_shelf":"Трагические истории","conflict_key":"держаться-правильно-против-рыдать-открыто","image_key":"ночное-дежурство-у-дома-друга","turn_key":"терпеливый-ломается-в-четыре-утра","hook_key":"терпение-тоже-плачет","sort_order":"1377","original_key":"al-maarri|to-you-who-weep","author_name":"Абу аль-Аля аль-Маарри","original_title":"«Тебе, рыдающий, не лучше ль терпеливо…» (из Лузумийята)","original_language":"Arabic","origin_country":"Сирия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Al-Ma%CA%BFarri","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1057.","music_adaptations":[],"source_synopsis":"Поэт обращается к рыдающему: не лучше ли терпеливо? — стих о двух способах нести горе.","main_image":"двое друзей на ночном дежурстве у дома друга"},{"title":"Своя строка","full_story":"Рэпера наняли написать трек для свадьбы медиамагната — список хвалебных тезисов приложен. Он пишет всё как заказано, но в бридже вставляет одну строчку про девушку из охраны, единственную честную в этом зале. Трек выкладывают, заказчик доволен; через год из всего трека цитируют только бридж — и строка про неё переживает свадьбу.","hero_pov":"бард на заказе","central_conflict":"Заказная хвала против своей строки: вставить правду в чужой праздник — риск потерять оплату, молчать — потерять себя.","emotional_arc":"от ремесленного конформизма к тихой правде в бридже","ending_direction":"Через год цитируют только бридж про неё — заказ забыт, строка осталась, и она первая пишет ему: спасибо.","hook_direction":"из всего трека помнят бридж","genres":["Трэп","Джаз"],"moods":["Уверенность","Ирония"],"energy":"Высокая","themes":["Риск","Сцена"],"generator_brief":"Свадебный заказной трэп с джазовой подкладкой: пафосные куплеты под список тезисов и один живой бридж, где бит приоткрывается и дышит.","generator_story":"Рэпер пишет заказной хвалебный трек для свадьбы медиамагната, но в бридже вставляет честную строку про девушку из охраны. Через год цитируют только бридж — и она первой пишет ему спасибо.","primary_genre":"Трэп","primary_mood":"Уверенность","primary_theme":"Риск","story_shelf":"Юмор: семейные драмы","conflict_key":"заказная-хвала-против-своей-строки","image_key":"список-тезисов-от-заказчика","turn_key":"цитируют-только-бридж","hook_key":"из-всего-трека-помнят-бридж","sort_order":"1378","original_key":"al-asha|lamiyya","author_name":"аль-Аша","original_title":"Ламийя","original_language":"Arabic","origin_country":"Аравия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Al-A%27sha","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 629.","music_adaptations":[],"source_synopsis":"Большая касыда доисламского барда: заказные похвалы вождям и пиры — а в самой личной части стихи о Хурайре, которую он любил; веками позже из всего панегирика цитируют её строчки.","main_image":"своя строка внутри чужого заказа"},{"title":"Первый в подъезде","full_story":"Он первым в подъезде начал петь «неофициально»: гитара на лестнице, куплеты не по правилам, соседи из окон. Через пять лет в подъезде свой лейбл и тридцать клонов его стиля — его самого никто не помнит. На юбилее подъезда ведущий перечисляет «отцов сцены» и пропускает его; он выходит с гитарой последним и играет куплет, по которому все вспоминают, чьи это были аккорды.","hero_pov":"основатель жанра, которого забыли","central_conflict":"Быть первым против быть забытым: жанр скопировали до неузнаваемости, и доказать авторство можно только сыграв.","emotional_arc":"от безымянности к тихому признанию на юбилее","ending_direction":"Он играет последний куплет — зал подпевает аккорды, которых не знал, что знает его.","hook_direction":"эти аккорды были мои","genres":["Регги","Фолк"],"moods":["Ирония","Уверенность"],"energy":"Средняя","themes":["сцена","Память"],"generator_brief":"Подъездный регги-фолк: качающая гитара на лестнице, свист из окон, куплет-история и финал, где зал впервые узнаёт свои же аккорды.","generator_story":"Он первым пел в подъезде с гитарой — теперь там лейбл и тридцать клонов его стиля, а его забыли. На юбилее он выходит последним и играет куплет, по которому зал вспоминает, чьи это аккорды.","primary_genre":"Регги","primary_mood":"Ирония","primary_theme":"сцена","story_shelf":"Юмор: семейные драмы","conflict_key":"быть-первым-против-быть-забытым","image_key":"гитара-на-лестнице-подъезда","turn_key":"зал-подпевает-чужие-аккорды","hook_key":"эти-аккорды-были-мои","sort_order":"1379","original_key":"al-asha|khamriyyat","author_name":"аль-Аша","original_title":"Хамрийят аль-Аши (винные стихи)","original_language":"Arabic","origin_country":"Аравия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Al-A%27sha","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 629.","music_adaptations":[],"source_synopsis":"Основатель «винной» поэзии Аравии: он первым воспел пирушку так, что после него жанр пели все, а имя основателя стёрлось.","main_image":"гитара на лестнице подъезда, с которой всё началось"},{"title":"Видимая","full_story":"Она работает в чужом доме, где её не видят: стирка, посуда, тишина. Подъездный певец, для которого она готовит, пишет про неё песню — не тайную, а публичную, с её смехом в сэмпле. Песня разлетается по району, и впервые она слышит своё имя из чужих ртов — не «ней», а по имени. Она снимает свой первый сторис: себя, на фоне кухни, лицом к камере.","hero_pov":"девушка, которую наконец назвали по имени","central_conflict":"Невидимость в чужом доме против песни, которая делает её видимой: остаться «ней» или стать собой с именем.","emotional_arc":"от невидимой работы к первому лицу к камере","ending_direction":"Она выкладывает первый сторис с лицом к камере — и в комментариях район называет её по имени.","hook_direction":"назови меня по имени","genres":["Хаус","Соул"],"moods":["Освобождение","Нежность"],"energy":"Средняя","themes":["самопринятие","голос"],"generator_brief":"Тёплый соул-хаус: кухонная перкуссия, её смех сэмплом в бридже, вокал девушки появляется только в финале — первый раз во весь голос.","generator_story":"Девушка в чужом доме невидима: стирка, посуда, тишина. Подъездный певец выпускает песню с её смехом в сэмпле — и район впервые зовёт её по имени. Она снимает первый сторис — себя, лицом к камере.","primary_genre":"Хаус","primary_mood":"Освобождение","primary_theme":"самопринятие","story_shelf":"Любовные сцены","conflict_key":"невидимость-в-чужом-доме-против-песни","image_key":"первый-сторис-с-лицом-к-камере","turn_key":"район-называет-по-имени","hook_key":"назови-меня-по-имени","sort_order":"1380","original_key":"al-asha|hurayra","author_name":"аль-Аша","original_title":"Стихи Хурайре (из Дивана аль-Аши)","original_language":"Arabic","origin_country":"Аравия","original_year":"","source_url":"https://en.wikipedia.org/wiki/Al-A%27sha","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 629.","music_adaptations":[],"source_synopsis":"Любовные стихи барда к Хурайре — невидимой для двора служанке: он пел о ней открыто, когда о таких было не принято говорить, и его стихи делали её видимой.","main_image":"девушка, впервые смотрящая в камеру"},{"title":"Чайки третьей зимы","full_story":"Она — капитан портового терминала; его лучший друг пропадает без вести на северной вахте, и он рвётся искать. Она не запрещает: сама покупает ему билет и правит их общим делом. Третья зима: она встречает паромы, кормит чаек, которые прилетают с каждым судном, и не пропускает ни одной вахты. Его паром входит в тумане — и она узнаёт его по тому, как чайки встают над водой.","hero_pov":"женщина, которая правит и ждёт","central_conflict":"Право удержать против права отпустить: она сама открывает ему дорогу и несёт ответственность за обе жизни.","emotional_arc":"от безмолвной выдержки к встрече в тумане","ending_direction":"Его паром входит в тумане — чайки встают над водой, и она узнаёт его раньше гудка.","hook_direction":"я встречу — приплывёшь","genres":["Синтвейв","Поп"],"moods":["Романтика","Надежда"],"energy":"Средняя","themes":["море","семья"],"generator_brief":"Портовый синтвейв: неоновые огни кранов, гул парома в басу, крик чаек сэмплом, вокал женщины ровный и ждущий — до финального тумана.","generator_story":"Она отпускает любимого искать пропавшего на вахте друга и остаётся править их общим делом. Третья зима она встречает паромы — и в тумане узнаёт его по чайкам, вставшим над водой.","primary_genre":"Синтвейв","primary_mood":"Романтика","primary_theme":"море","story_shelf":"Люди и животные","conflict_key":"удержать-против-отпустить-самой","image_key":"чайки-над-паромом-в-тумане","turn_key":"узнаёт-по-чайкам","hook_key":"я-встречу-приплывёшь","sort_order":"1381","original_key":"rustaveli|tinatin","author_name":"Шота Руставели","original_title":"Витязь в тигровой шкуре (Тинатин)","original_language":"Georgian","origin_country":"Грузия","original_year":"","source_url":"https://en.wikipedia.org/wiki/The_Knight_in_the_Panther%27s_Skin","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 1216.","music_adaptations":[],"source_synopsis":"Фрагмент поэмы: царица Тинатин сама отпускает Автандила искать Тариэла — не удерживает и не запрещает, а правит царством и ждёт его возвращения.","main_image":"пирс, где встречают каждый паром среди чаек"},{"title":"Крепость на воде","full_story":"Современную Нестан заперли в приморском пансионе «для поправки» — родня оформила за наследство, телефон забрали. Она выучила расписание отливов: раз в сутки камни обнажаются, и ворота к пляжу сторож закрывают «на всякий случай». Брат и подруга приходят в отлив на резиновой лодке с фонарём — и она не бежит тайком: проходит мимо сторожа с чемоданом, как соседка на рассвете, и садится в лодку.","hero_pov":"девушка, которая выучила отливы","central_conflict":"Крепость на воде против расписания отливов: сторожа ждут ночную погоню, а её план — уйти днём, как соседка, потому что побег строится не на бегстве, а на праве выйти.","emotional_arc":"от запертого счёта приливов к свободному выходу при людях","ending_direction":"В отлив она проходит мимо сторожа с чемоданом и садится в лодку друзей — погони нет, потому что побег был не ночью, а на рассвете.","hook_direction":"отлив знает мой шаг","genres":["Драм-н-бейс","Синтвейв"],"moods":["Драйв","Смелость"],"energy":"Взрывная","themes":["море","Свобода"],"generator_brief":"Штормовой драм-н-бейс: брейк как накат волн, сирена пансиона сэмплом, в дропе — тишина отлива и шаги по камням.","generator_story":"Запертая роднёй в пансионе за наследство, она выучивает отливы. В отлив она проходит мимо сторожа с чемоданом, как соседка на рассвете, и садится в лодку друзей — побег не тайный, а при людях.","primary_genre":"Драм-н-бейс","primary_mood":"Драйв","primary_theme":"море","story_shelf":"Трагические истории","conflict_key":"крепость-на-воде-против-расписания-отливов","image_key":"лодка-в-отлив-с-фонарём","turn_key":"побег-днём-как-у-соседки","hook_key":"отлив-знает-мой-шаг","sort_order":"1382","original_key":"rustaveli|nestan-gvirgvani","author_name":"Шота Руставели","original_title":"Витязь в тигровой шкуре (Нестан-Дареджани)","original_language":"Georgian","origin_country":"Грузия","original_year":"","source_url":"https://en.wikipedia.org/wiki/The_Knight_in_the_Panther%27s_Skin","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 1216.","music_adaptations":[],"source_synopsis":"Эпизод поэмы: Нестан-Дареджани заперта в морской крепости; вызволение её с моря — кульминация странствий рыцарей.","main_image":"лодка в отливе с одним фонарём"},{"title":"Львёнка узнаёт лев","full_story":"Новичок — сын организатора вечера — выходит на районный опен-мик с визиткой: лейблы, курсы, регалии. Зал вежливо скучает. Следом выходит молчаливая девушка и поёт без представления — зал встаёт не ей, а «своей». Ведущий отменяет баллы навсегда: с этого вечера на сцене одно правило — представляться не нужно; мать-организатор первая аплодирует не сыну.","hero_pov":"человек с визиткой против человека без","central_conflict":"Доказывать, что ты свой, против быть узнанным без слов: презентация проигрывает одному куплету, и зал это решает сам.","emotional_arc":"от неловкой презентации к правилу без баллов","ending_direction":"Ведущий рвёт табло баллов — сцена признаёт своих по глазам, и новичок рвёт визитку первым.","hook_direction":"своих узнают по глазам","genres":["EDM","Поп"],"moods":["Эйфория","Уверенность"],"energy":"Высокая","themes":["сцена","Дружба"],"generator_brief":"ДК-вечерний EDM: тёплый бас, аплодисменты в ритме, куплет без представления и финал, где ведущий рвёт табло баллов.","generator_story":"Новичок с визиткой — лейблы, курсы, регалии — скучен залу, а молчаливая девушка без представления заставляет его встать. Ведущий отменяет баллы: представляться не нужно — и новичок рвёт визитку.","primary_genre":"EDM","primary_mood":"Эйфория","primary_theme":"сцена","story_shelf":"Юмор: семейные драмы","conflict_key":"визитка-против-одного-куплета","image_key":"правило-без-баллов","turn_key":"ведущий-отменяет-баллы","hook_key":"своих-узнают-по-глазам","sort_order":"1383","original_key":"rustaveli|prologue","author_name":"Шота Руставели","original_title":"Витязь в тигровой шкуре (пролог)","original_language":"Georgian","origin_country":"Грузия","original_year":"","source_url":"https://en.wikipedia.org/wiki/The_Knight_in_the_Panther%27s_Skin","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 1216.","music_adaptations":[],"source_synopsis":"Пролог поэмы: лев узнаёт львёнка — свои узнают своих; равных не надо доказывать, их надо узнавать.","main_image":"опен-мик в доме культуры, где своих узнают по глазам"},{"title":"Голос вне дворца","full_story":"Вокалист ресторана частного клуба влюблён в дочь владельца; её отец увольняет его «по-тихому», без скандала. Он уходит в церковный хор пригорода — и впервые поёт без заказа и чаевых. Прихожане не знают его прошлой славы; на летнем празднике двора он возвращается с хором на сцену клуба — уже как гость — и поёт так, что бывший хозяин встаёт.","hero_pov":"певец, который нашёл голос вне дворца","central_conflict":"Дворец и чаевые против голоса без заказа: его выгнали за любовь, а лучший голос остался только там, где не платят.","emotional_arc":"от тихого увольнения к возвращению гостем, которому аплодируют","ending_direction":"Он возвращается на дворцовую сцену с хором как гость — бывший хозяин встаёт первым, и это не победа, а мир.","hook_direction":"мой голос — не для чаевых","genres":["Драм-н-бейс","Соул"],"moods":["Благородство","Грусть"],"energy":"Высокая","themes":["голос","Выбор"],"generator_brief":"Гордый драм-н-бейс с хором: ломаный брейк под церковное эхо, вокал от шёпота к полноте, финал — общий голос двора без обиды.","generator_story":"Вокалиста клуба увольняют за любовь к дочери владельца. Он уходит в церковный хор — впервые поёт без чаевых, а летом возвращается на клубную сцену гостем так, что хозяин встаёт: не победа, а мир.","primary_genre":"Драм-н-бейс","primary_mood":"Благородство","primary_theme":"голос","story_shelf":"Трагические истории","conflict_key":"дворец-и-чаевые-против-голоса-без-заказа","image_key":"хор-пригорода-возвращается-гостем","turn_key":"бывший-хозяин-встаёт-первым","hook_key":"мой-голос-не-для-чаевых","sort_order":"1384","original_key":"sayat-nova|court-exile","author_name":"Саят-Нова","original_title":"Песни из Давтяновской тетради (изгнание из двора)","original_language":"Armenian","origin_country":"Армения","original_year":"","source_url":"https://en.wikipedia.org/wiki/Sayat-Nova","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1795.","music_adaptations":[],"source_synopsis":"Придворный ашуг, певший при дворе Ираклия II, был изгнан из дворца (по одной из версий — из-за любви к царевне Анне) и сменил кяманчу на крест — стал священником; его песни сохранила Давтяновская тетрадь.","main_image":"голос, который стал лучше вне дворца"},{"title":"Семь ворот Насими","full_story":"Имя казнённого век назад поэта вычищено из школьной программы, книги изъяты. Учительница литературы не может читать его на уроке — и выходит в подземный переход с кружкой и бумажными строфами: «семь ворот распахнулись». К ней присоединяются бывшие ученики с лупами; вечер в переходе становится ежемесячным — строфы передают по памяти, пока издательство не возвращает книгу в печать.","hero_pov":"учительница, которая читает вне программы","central_conflict":"Запрещённая память против живой передачи по памяти: строфы нельзя изъять из тех, кто их знает наизусть.","emotional_arc":"от тихой невозможности к ежемесячному вечеру и возврату книги","ending_direction":"Книга возвращается в печать — последний вечер в переходе заканчивают чтением уже по напечатанной странице.","hook_direction":"семь ворот распахнулись","genres":["Электропоп","Рэп"],"moods":["Протест","Вдохновение"],"energy":"Высокая","themes":["голос","Память"],"generator_brief":"Электропоп-реквием с рэп-лупами: ученические голоса по памяти, метрошное эхо, финал — шорох свежей печатной страницы вместо бита.","generator_story":"Имя казнённого поэта вычищено из программы, книги изъяты. Учительница читает его строфы в подземном переходе, к ней присоединяются бывшие ученики — вечера идут, пока книгу не возвращают в печать.","primary_genre":"Электропоп","primary_mood":"Протест","primary_theme":"голос","story_shelf":"Трагические истории","conflict_key":"изъятая-книга-против-памяти-подземного-перехода","image_key":"кружка-и-бумажные-строфы","turn_key":"книга-возвращается-в-печать","hook_key":"семь-ворот-распахнулись","sort_order":"1385","original_key":"sayat-nova|nasimi-songs","author_name":"Саят-Нова","original_title":"Песни Насими (обращения Саят-Новы к Насими)","original_language":"Armenian","origin_country":"Армения","original_year":"","source_url":"https://en.wikipedia.org/wiki/Sayat-Nova","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1795.","music_adaptations":[],"source_synopsis":"Ашуг посвящает песни легендарному Насими — поэту-мученику, казнённому за свои взгляды; в его строках Насими — бессмертный дух, «семь ворот» которого распахнуты навстречу.","main_image":"вечер запрещённых строф в подземном переходе"},{"title":"Двор на трёх языках","full_story":"В доме на границе трёх кварталов вечная война чатов: каждый квартал уверен в своей правоте. Внук старого двора собирает всех на общий вечер и поёт песни прадеда — на всех трёх языках по куплету, без перевода. Первый куплет понимают все, второй — половина, к третьему уже никто не поправляет: они подпевают чужими буквами. Ссора о холодной воде заканчивается общим ремонтом.","hero_pov":"внук, который поёт на всех языках двора","central_conflict":"Три правых квартала против одной песни: непонятный куплет становится общим, если его подпевать, а не переводить.","emotional_arc":"от спора о правоте к общему подпеванию чужими буквами","ending_direction":"Ссора о воде кончается общим ремонтом — вечер повторяют каждый месяц, куплеты так и не переводят.","hook_direction":"подпевай чужими буквами","genres":["Регги","Поп"],"moods":["Радость","Тепло"],"energy":"Высокая","themes":["Примирение","Дружба"],"generator_brief":"Дворовый регги с тремя языками в одном куплете: разнобой акцентов в бэке, песня-мост, финал — все подпевают, не понимая слов, и это работает.","generator_story":"Три враждующих квартала собирает внук старого двора: песни прадеда на трёх языках, по куплету без перевода. К третьему подпевают все, не разбирая букв, а ссора о воде кончается общим ремонтом.","primary_genre":"Регги","primary_mood":"Радость","primary_theme":"Примирение","story_shelf":"Юмор: семейные драмы","conflict_key":"три-правых-квартала-против-одной-песни","image_key":"куплеты-без-перевода","turn_key":"подпевают-чужими-буквами","hook_key":"подпевай-чужими-буквами","sort_order":"1386","original_key":"sayat-nova|multilingual-songs","author_name":"Саят-Нова","original_title":"Полиязычные песни Саят-Новы (из Давтяновской тетради)","original_language":"Armenian","origin_country":"Армения","original_year":"","source_url":"https://en.wikipedia.org/wiki/Sayat-Nova","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1795.","music_adaptations":[],"source_synopsis":"Ашуг писал и пел на армянском, грузинском и азербайджанском — его песни переходили с языка на язык внутри одного куплета и соединяли слушателей разных улиц Тифлиса.","main_image":"двор, где спорят на трёх языках"},{"title":"Тысяча лошадей","full_story":"После краха семейного фонда он стал курьером и каждый день крутится среди чужих «тысяч лошадей»: кроссоверы, доставка для доставщиков. Ночами он пишет в заметках столбцы-протесты — списки несправедливости без имён. Однажды он не отправляет их в сеть, а читает вслух на кухне ночного общежития курьеров — и столбцы превращаются в общую кассу взаимопомощи: у тебя нет — у нас есть.","hero_pov":"курьер, который пишет протест вместо жалобы","central_conflict":"Тысяча лошадей одному против ничего другому: он переводит яростный список в общую кассу — негодование становится взаимопомощью.","emotional_arc":"от ночной злости к общей кассе на кухне","ending_direction":"Его столбцы читают вслух всем общежитием — касса открыта, и «ничего» перестаёт быть приговором.","hook_direction":"у тебя нет — у нас есть","genres":["Трэп","Рэп"],"moods":["Злость","Сила"],"energy":"Взрывная","themes":["Риск","поддержка"],"generator_brief":"Разрывной трэп-рэп: читка-список несправедливости, 808 как шаги по лестнице, дроп — звон монет в общую кассу вместо злости.","generator_story":"Разорившийся наследник фонда работает курьером и ночами пишет списки несправедливости — без имён. Вместо сети он читает их на кухне общежития, и злые столбцы превращаются в общую кассу взаимопомощи.","primary_genre":"Трэп","primary_mood":"Злость","primary_theme":"Риск","story_shelf":"Трагические истории","conflict_key":"тысяча-лошадей-одному-против-ничего","image_key":"столбцы-протеста-в-заметках","turn_key":"столбцы-становятся-кассой","hook_key":"у-тебя-нет-у-нас-есть","sort_order":"1387","original_key":"frik|gangat","author_name":"Фрик","original_title":"Гангат (Жалоба)","original_language":"Armenian","origin_country":"Армения","original_year":"","source_url":"https://en.wikipedia.org/wiki/Frik","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 1310.","music_adaptations":[],"source_synopsis":"Средневековый армянский поэт, разорённый при монголах, жалуется: мир даёт одному тысячу лошадей, а другому не оставляет ничего; его протест — один из первых голосов социального негодования.","main_image":"курьер среди чужих тысяч лошадей"},{"title":"Песня до падения","full_story":"В юности он был наследником и писал только весёлые песни о любви — они до сих пор крутятся на свадьбах их рода. После краха он не может их слушать: тот юноша умер. На свадьбе двоюродной сестры диджей ставит его песню, и он выходит к микрофону не с протестом, а с новым куплетом: старый припев остаётся, новый куплет — про то, что радость не про деньги. Два Фрика допевают друг в друге.","hero_pov":"человек, который дописывает куплет своей юности","central_conflict":"Тот весёлый юноша против нынешнего разорённого: стыд старых песен против права дописать куплет, а не отменить молодость.","emotional_arc":"от стыда перед собой к продолжению собственной песни","ending_direction":"Старый припев поёт зал, новый куплет — он; две половины жизни складываются в одну песню без ссоры.","hook_direction":"допиши куплет — не отменяй песню","genres":["Хаус","Поп"],"moods":["Светлая грусть","Надежда"],"energy":"Низкая","themes":["Примирение","Память"],"generator_brief":"Ретро-хаус с семейным свадебным сэмплом: старый весёлый припев и новый приглушённый куплет, встречающиеся в последнем бридже без драмы.","generator_story":"В юности он писал весёлые песни о любви, после краха не может их слушать. На свадьбе сестры он дописывает старой песне куплет про радость без денег — и две половины жизни складываются в одну.","primary_genre":"Хаус","primary_mood":"Светлая грусть","primary_theme":"Примирение","story_shelf":"Трагические истории","conflict_key":"стыд-старых-песен-против-нового-куплета","image_key":"свадьба-двоюродной-сестры","turn_key":"два-фрика-в-одной-песне","hook_key":"допиши-куплет-не-отменяй","sort_order":"1388","original_key":"frik|early-lyric","author_name":"Фрик","original_title":"Любовные стихи Фрика (ранняя лирика)","original_language":"Armenian","origin_country":"Армения","original_year":"","source_url":"https://en.wikipedia.org/wiki/Frik","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 1310.","music_adaptations":[],"source_synopsis":"До разорения Фрик писал о любви и радости — весёлые, светлые стихи молодости; после потери состояния его голос изменился навсегда.","main_image":"старая весёлая песня, которую не узнаёт её автор"},{"title":"Список оставшегося","full_story":"Он самовольно уехал без отпуска — на прощание с умирающим учителем — и вернулся под дело: подписка, камера, замороженный счёт. В камере он составляет список оставшегося: слух (слышит дождь), память (все слова учителя), рука (пишет). На допросе вместо оправдания он читает список вслух; дело закрывают, и он выходит с тем же списком — теперь он читает его каждое утро как молитву.","hero_pov":"узник, который составлял инвентарь себя","central_conflict":"Всё отнятое против списка того, что не отняли: его спасает не оправдание, а точный учёт остатка.","emotional_arc":"от потерянности к спокойному учёту и выходу","ending_direction":"Дело закрывают, и он выходит с тем же списком — каждое утро он читает его как молитву вместо обиды.","hook_direction":"отняли всё — не всё","genres":["Техно","Эмбиент"],"moods":["Меланхолия","Сила"],"energy":"Низкая","themes":["спасение","Выбор"],"generator_brief":"Подвальное техно: сухой пульс камеры, капли воды в метрономе, ровная читка списка — каждый пункт оставшегося входит с новым слоем звука.","generator_story":"Он уехал без отпуска проститься с умирающим учителем — и попал в камеру. Там он составляет список того, что не отняли: слух, память, рука. На допросе вместо оправдания он читает его — дело закрывают.","primary_genre":"Техно","primary_mood":"Меланхолия","primary_theme":"спасение","story_shelf":"Трагические истории","conflict_key":"всё-отняли-против-списка-остатка","image_key":"инвентарь-себя-на-обрывке","turn_key":"читает-список-на-допросе","hook_key":"отняли-всё-не-всё","sort_order":"1389","original_key":"khagani|habsia","author_name":"Хагани Ширвани","original_title":"Хабсия (Заточение)","original_language":"Persian","origin_country":"Азербайджан","original_year":"1158","source_url":"https://en.wikipedia.org/wiki/Khaqani","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1199.","music_adaptations":[],"source_synopsis":"Вернувшись из самовольного путешествия, придворный поэт попал в заточение; в темнице он написал «Хабсию» — о том, что при нём осталось: мысль, память и слово.","main_image":"список того, что не отняли"},{"title":"Птицы в цехах","full_story":"Экскурсовод водит школьников по руинам гигантского тракторного завода: царские кабинеты, парадные плакаты, ворота для парадов. Между остановками он показывает не плакаты, а скворечники: в цехах гнездятся скворцы, вода течёт по рельсам, берёза проросла сквозь кассу. Дети спрашивают, что пережило империю, — он отвечает пением в цехе: власть кончилась, птицы нет.","hero_pov":"экскурсовод руин, который показывает скворечники","central_conflict":"Империя плакатов против жизни в руинах: что пережило власть — выясняется не рассказом, а пением птиц в цехе.","emotional_arc":"от пафоса величия к тихой очевидности живого","ending_direction":"Школьники уходят, запомнив не парадные ворота, а скворцов в цехе — экскурсию переименовывают в «Птицы в цехах».","hook_direction":"власть кончилась — птицы нет","genres":["Синтвейв","Эмбиент"],"moods":["Мечтательность","Сила"],"energy":"Средняя","themes":["Природа","Память"],"generator_brief":"Ржавый синтвейв: гул пустого цеха, капли по рельсам, птичий свист в хай-хэтах, вокал экскурсовода почти шёпотом — и один скворцовый хор.","generator_story":"Экскурсовод водит школьников по руинам завода и показывает не плакаты, а скворечники в цехах: скворцы гнездятся, берёза проросла сквозь кассу. На вопрос, что пережило империю, он отвечает пением птиц.","primary_genre":"Синтвейв","primary_mood":"Мечтательность","primary_theme":"Природа","story_shelf":"Люди и животные","conflict_key":"империя-плакатов-против-жизни-в-руинах","image_key":"скворечники-в-цехах","turn_key":"экскурсия-переименована-в-птиц","hook_key":"власть-кончилась-птицы-нет","sort_order":"1390","original_key":"khagani|ruins-of-madain","author_name":"Хагани Ширвани","original_title":"Развалины Мадаина","original_language":"Persian","origin_country":"Азербайджан","original_year":"","source_url":"https://en.wikipedia.org/wiki/Khaqani","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1199.","music_adaptations":[],"source_synopsis":"После посещения руин древней столицы Сасанидов поэт пишет философскую касыду о бренности власти и славы: города падают, слова остаются.","main_image":"птицы в цехах мёртвого завода"},{"title":"Своё зеркало","full_story":"Он тридцать лет полирует чужие витрины — магазины, банки, салоны: весь город видит себя в его работу. Дома у него висит зеркальце матери — мутное, без полировки. После её смерти он решается: чистит собственное зеркало по всем правилам ремесла — и впервые за тридцать лет долго смотрит на своё лицо, не брезгуя морщинами. Витрины по-прежнему его, но это зеркало — тоже.","hero_pov":"стекольщик, который полировал всех, кроме себя","central_conflict":"Полировать чужие отражения против очистить своё: он обязан увидеть себя, и ремесло впервые поворачивается домой.","emotional_arc":"от бегущего взгляда к долгому спокойному взгляду на себя","ending_direction":"Он вешает очищенное материнское зеркало у входа в мастерскую: клиенты видят в нём себя, он — себя.","hook_direction":"своё зеркало — тоже работа","genres":["Хаус","Джаз"],"moods":["Надежда","Спокойствие"],"energy":"Средняя","themes":["самопринятие","прошлое"],"generator_brief":"Мягкий джазовый хаус: влажные клавиши полировки, ткань по стеклу в перкуссии, тёплый вокал стекольщика — финал на одном взгляде в зеркало.","generator_story":"Тридцать лет стекольщик полировал чужие витрины — весь город видит себя в его работу. После смерти матери он чистит её мутное зеркальце и впервые долго смотрит на своё лицо, не брезгуя морщинами.","primary_genre":"Хаус","primary_mood":"Надежда","primary_theme":"самопринятие","story_shelf":"Трагические истории","conflict_key":"чужие-витрины-против-своего-зеркала","image_key":"мутное-материнское-зеркальце","turn_key":"чистит-зеркало-по-правилам-ремесла","hook_key":"своё-зеркало-тоже-работа","sort_order":"1391","original_key":"khagani|mirror-of-soul","author_name":"Хагани Ширвани","original_title":"Зеркало души","original_language":"Persian","origin_country":"Азербайджан","original_year":"","source_url":"https://en.wikipedia.org/wiki/Khaqani","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1199.","music_adaptations":[],"source_synopsis":"Философское стихотворение Хагани о зеркале души: чтобы увидеть себя, нужно сначала очистить своё зеркало.","main_image":"витринное стекло и одно мутное материнское зеркало"},{"title":"Хлеб для квартала","full_story":"Его ресторан с одной звездой лопнул в долгах — повара разошлись, зал пуст. Долги не дают открыть новое; он печёт хлеб в отцовской печи и раздаёт соседям за любую цену, включая «потом». Через полгода очередь за хлебом длиннее, чем была очередь за устрицами, а сосед-должник возвращает старый долг не деньгами, а дровами для печи. Звёзды не вернулись — хлеб вернулся.","hero_pov":"шеф, который стал пекарем квартала","central_conflict":"Погоня за славой против простого хлеба: долг не даёт вернуть ресторан, а квартал кормится — и кормит его в ответ.","emotional_arc":"от пустого зала к длинной очереди и возвращённым дровам","ending_direction":"Сосед возвращает старый долг дровами — печь горит, и он понимает: хлеб и есть ресторан.","hook_direction":"хлеб и есть ресторан","genres":["Техно","Фолк"],"moods":["Тепло","Уверенность"],"energy":"Средняя","themes":["спасение","Дом"],"generator_brief":"Печной техно: сухой пульс поднимающейся опары, хлопки муки в перкуссии, усталый тёплый вокал — финал на треске дров и звон дверного колокольчика.","generator_story":"Ресторан шефа лопнул в долгах — он печёт хлеб в отцовской печи и раздаёт соседям, беря и «потом». Очередь за хлебом длиннее былой за устрицами, а сосед-должник возвращает старый долг дровами для печи.","primary_genre":"Техно","primary_mood":"Тепло","primary_theme":"спасение","story_shelf":"Юмор: семейные драмы","conflict_key":"звезда-ресторана-против-хлеба-квартала","image_key":"очередь-за-горячим-хлебом","turn_key":"сосед-возвращает-долг-дровами","hook_key":"хлеб-и-есть-ресторан","sort_order":"1392","original_key":"khagani|about-bread","author_name":"Хагани Ширвани","original_title":"О хлебе","original_language":"Persian","origin_country":"Азербайджан","original_year":"","source_url":"https://en.wikipedia.org/wiki/Khaqani","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1199.","music_adaptations":[],"source_synopsis":"Философское стихотворение Хагани о хлебе — самом простом и самом необходимом: без него не держится никакая слава.","main_image":"очередь за горячим хлебом вместо ресторанных звёзд"},{"title":"Тридцать птиц","full_story":"Тридцать незнакомых участников чата «найди наставника» отправляются в совместную экспедицию искать легендарного тренера, который, по слухам, «собирает человека». Через год дорог, ссор и взаимной выручки они доходят до его адреса — там пусто, только зеркало. В зеркале — их тридцать: они и есть тот, кого искали, сложившись в одну команду.","hero_pov":"один из тридцати, дошедших до адреса","central_conflict":"Поиск великого наставника против открытия, что наставник — это они сами, сложившиеся вместе.","emotional_arc":"от веры в чужого гуру к самооткрытию в общем зеркале","ending_direction":"На пустом адресе — зеркало, и в нём тридцать их: поиск закончен, наставник собран из самих искателей.","hook_direction":"тридцать птиц — один царь","genres":["Драм-н-бейс","Классика"],"moods":["Вдохновение","Драйв"],"energy":"Высокая","themes":["Природа","Поиск себя"],"generator_brief":"Взлетающий драм-н-бейс: стая крыльев в брейках, год дороги сжат в один подъём, дроп — пустой адрес и зеркало, где их тридцать.","generator_story":"Тридцать незнакомцев идут искать легендарного тренера, который собирает человека. Через год дорог и ссор на адресе пусто — только зеркало: в нём тридцать их, и наставник собран из самих искателей.","primary_genre":"Драм-н-бейс","primary_mood":"Вдохновение","primary_theme":"Природа","story_shelf":"Люди и животные","conflict_key":"поиск-гуру-против-зеркала-в-конце","image_key":"тридцать-в-одном-зеркале","turn_key":"наставник-собран-из-искателей","hook_key":"тридцать-птиц-один-царь","sort_order":"1393","original_key":"navoi|lison-ut-teyr","author_name":"Алишер Навои","original_title":"Лисон ут-тейр (Язык птиц)","original_language":"Uzbek","origin_country":"Узбекистан","original_year":"1485","source_url":"https://en.wikipedia.org/wiki/Alisher_Navoi","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1501.","music_adaptations":[],"source_synopsis":"Маснави Навои: птицы всей земли идут в поиск своего царя Симурга — и из тридцати птиц, добравшихся до цели, складывается сам Симург: «си морг» — тридцать птиц.","main_image":"тридцать птиц складываются в одну"},{"title":"Стена до горизонта","full_story":"Инженер посёлка у лесного массива продаёт машину и строит минерализованную полосу и дамбу «против огня из соседнего региона» — посёлок зовёт это безумием: «у нас не горело никогда». Летом огонь приходит ровно по прогнозу: дамба и полоса останавливают стену огня на краю посёлка. Вечером те, кто смеялся, приносят ему лопаты — расширять на север.","hero_pov":"инженер, которого смеяли до пожара","central_conflict":"Смешное строительство против реальной стены огня: он работает год под смех и один вечер под благодарность.","emotional_arc":"от одиночной стройки в насмешках к общим лопатам","ending_direction":"Посёлок приносит лопаты — стену расширяют всем составом, пока не горит.","hook_direction":"строй пока не горит","genres":["EDM","Рок"],"moods":["Решимость","Сила"],"energy":"Взрывная","themes":["спасение","смелость"],"generator_brief":"Стадионный EDM: удары лопат как бочка, нарастающая стена звука на подъёме, дроп — встреча огня и полосы на краю посёлка.","generator_story":"Инженер строит дамбу и полосу против лесного огня, посёлок смеётся: здесь не горело никогда. Летом огонь приходит ровно по прогнозу и встаёт на краю посёлка — вечером насмешники приносят ему лопаты.","primary_genre":"EDM","primary_mood":"Решимость","primary_theme":"спасение","story_shelf":"Трагические истории","conflict_key":"смешная-дамба-против-стены-огня","image_key":"минерализованная-полоса-до-горизонта","turn_key":"смеявшиеся-приносят-лопаты","hook_key":"строй-пока-не-горит","sort_order":"1394","original_key":"navoi|sadd-i-iskandari","author_name":"Алишер Навои","original_title":"Садд-и Искандари (Стена Искандера)","original_language":"Uzbek","origin_country":"Узбекистан","original_year":"1485","source_url":"https://en.wikipedia.org/wiki/Alisher_Navoi","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1501.","music_adaptations":[],"source_synopsis":"Часть Хамсы Навои: Искандер строит железную стену до горизонта против северного нашествия, о котором никто не верит, пока оно не приходит.","main_image":"минерализованная полоса до горизонта"},{"title":"Как меня б ты ни терзала","full_story":"Тенор, которого критики десять лет терзали за «слишком старомодный» голос, ушёл в аранжировки для других. На юбилее учителя он выходит из зала на сцену без предупреждения и поёт эту газель — в старомодном звучании, ни на йоту не уступив. Зал встаёт, включая критиков в третьем ряду. Он не отвечает на рецензии: просто записывает альбом своим голосом.","hero_pov":"тенор, который вернулся без оправданий","central_conflict":"Десять лет терзаний критиков против голоса, который не изменил ни на йоту: отвечать рецензиями или выйти и спеть.","emotional_arc":"от ухода в чужие аранжировки к возвращению своим голосом","ending_direction":"Зал встаёт, включая критиков — он записывает альбом своим голосом, не сказав ни слова о прошлом.","hook_direction":"пою своим голосом","genres":["Электропоп","Классика"],"moods":["Любовь","Уверенность"],"energy":"Высокая","themes":["сцена","смелость"],"generator_brief":"Оркестровый электропоп: старомодная мелодия над свежим басом, тенор без единой поправки, финал — стоячий зал на длинной ноте.","generator_story":"Тенора десять лет терзали за старомодный голос — ушёл в аранжировки. На юбилее учителя он выходит и поёт ту же газель, ни на йоту не уступив: зал встаёт с критиками, и он записывает альбом под себя.","primary_genre":"Электропоп","primary_mood":"Любовь","primary_theme":"сцена","story_shelf":"Любовные сцены","conflict_key":"терзания-критиков-против-своего-голоса","image_key":"юбилей-учителя","turn_key":"зал-встаёт-включая-критиков","hook_key":"пою-своим-голосом","sort_order":"1395","original_key":"navoi|ghazal-torment","author_name":"Алишер Навои","original_title":"«Как меня б ты ни терзала…» (из цикла «Редкости юности»)","original_language":"Uzbek","origin_country":"Узбекистан","original_year":"","source_url":"https://en.wikipedia.org/wiki/Alisher_Navoi","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер в 1501.","music_adaptations":[],"source_synopsis":"Газель из дивана: как бы ты меня ни терзала — я готов, мой скорбный дух; любовь, которая держится вопреки всему.","main_image":"юбилей учителя и пустая сцена"},{"title":"Сей цветы","full_story":"После ночной драки двух половин двора — стёкла, вражда, разобранный турник — тихий старик появляется на пятачке с лопатой и сеет цветы на месте драки. Каждое утро поливает при всех; никто не решается ступить. Через лето пятачок цветёт, и дракать больше негде: мальчишки поливают, обе половины двора ставят общую скамейку. Турник возвращают — уже на цветочной клумбе.","hero_pov":"старик, который сеет на месте драки","central_conflict":"Место драки против места цветения: не наказание и не перемирие, а ежедневное действие, которому нельзя помешать и нельзя не помочь.","emotional_arc":"от вражды и стёкол к общему поливу","ending_direction":"Турник возвращают на клумбу — дракать больше негде, и обе половины двора поливают из одной бочки.","hook_direction":"сей цветы — станет сад","genres":["Регги","Фолк"],"moods":["Радость","Тепло"],"energy":"Высокая","themes":["Природа","Примирение"],"generator_brief":"Дворовый регги: лейка и лопата в перкуссии, пение птиц над клумбой, стариковский куплет и общий хор двух половин двора в финале.","generator_story":"После драки двух половин двора тихий старик сеет цветы на месте драки. Через лето пятачок цветёт и драться негде: мальчишки поливают, обе половины ставят общую скамейку, турник возвращают на клумбу.","primary_genre":"Регги","primary_mood":"Радость","primary_theme":"Природа","story_shelf":"Юмор: семейные драмы","conflict_key":"место-драки-против-места-цветения","image_key":"цветник-на-разбитом-турнике","turn_key":"турник-возвращают-на-клумбу","hook_key":"сей-цветы-станет-сад","sort_order":"1396","original_key":"rahman-baba|sow-flowers","author_name":"Рахман Баба","original_title":"Сей цветы (из Дивана Рахман Бабы)","original_language":"Pashto","origin_country":"Афганистан","original_year":"","source_url":"https://en.wikipedia.org/wiki/Rahman_Baba","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 1706.","music_adaptations":[],"source_synopsis":"Знаменитый стих суфийского поэта: я — влюблённый, и я живу любовью; сей цветы, чтобы всё вокруг стало садом.","main_image":"цветник на месте драки во дворе"},{"title":"Переправа для двоих","full_story":"Два брата не говорили десять лет: старший остался на острове с отцовским домом, младший уехал. Младший возвращается ночью, когда последний паром ушёл, — и идёт через дамбу с одним фонарём: вода с двух сторон, ветер, три километра. На середине моста навстречу идёт старший со своим фонарём: он тоже не спал и услышал от шкипера. Они сходятся в свете двух фонарей и идут к дому вместе.","hero_pov":"младший брат на ночной дамбе","central_conflict":"Десять лет молчания против ночного пути: паром ушёл — идти пешком по воде с фонарём или ждать ещё десять лет.","emotional_arc":"от ночного одиночного шага к встрече в двух фонарях","ending_direction":"На середине дамбы навстречу выходит старший с фонарём — оба услышали друг друга через шкипера, и остаток пути они проходят вместе.","hook_direction":"путь любви освещает","genres":["Синтвейв","Эмбиент"],"moods":["Смелость","Тепло"],"energy":"Средняя","themes":["море","Примирение"],"generator_brief":"Ночной синтвейв: вода в стерео по бокам, ветер в басу, шаги на дамбе в ритме — финал, где два фонаря сливаются в один свет.","generator_story":"Два брата не говорили десять лет. Младший возвращается ночью, когда паром ушёл, и идёт по дамбе с одним фонарём — навстречу выходит старший со своим: он тоже не спал. Остаток пути они проходят вместе.","primary_genre":"Синтвейв","primary_mood":"Смелость","primary_theme":"море","story_shelf":"Любовные сцены","conflict_key":"ушедший-паром-против-ночной-дамбы","image_key":"два-фонаря-на-середине-дамбы","turn_key":"старший-идёт-навстречу","hook_key":"путь-любви-освещает","sort_order":"1397","original_key":"rahman-baba|path-of-love","author_name":"Рахман Баба","original_title":"Путь любви (из Дивана Рахман Бабы)","original_language":"Pashto","origin_country":"Афганистан","original_year":"","source_url":"https://en.wikipedia.org/wiki/Rahman_Baba","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 1706.","music_adaptations":[],"source_synopsis":"Стих суфийского поэта: когда я иду по пути любви, он освещает мой путь — путь любви Божьей.","main_image":"два фонаря на середине ночной дамбы"},{"title":"Песни вместо наследства","full_story":"Три брата делят отцовский дом и двор, вражда доходит до отмены общего обеда. Средний, который всегда пел, уходит жить к другу и пишет песни — не обвинительные, а дворовые: про турник, про отцовский кувшин, про то, как старший чинил крышу. На годовом сходе вместо суда он поёт эти три песни; к третьей старший и младший спорят уже не о долях, а о том, кто из них был в какой песне первым куплетом.","hero_pov":"средний брат, который пел вместо судейства","central_conflict":"Доля в доме против доли в песне: он отказывается судить и заставляет братьев узнать себя в куплетах.","emotional_arc":"от отменённого обеда к спору, кто из братьев в какой песне","ending_direction":"Обед восстанавливают по ту же сторону стола — братья просят песню про себя на следующий год.","hook_direction":"узнай себя в куплете","genres":["Электропоп","Фолк"],"moods":["Уверенность","Тепло"],"energy":"Высокая","themes":["Примирение","Семья"],"generator_brief":"Семейный электропоп-фолк: три куплета — три брата, каждый узнаёт себя не с той стороны, как ждал; припев двора подхватывает всех троих.","generator_story":"Братья делят дом до отмены общего обеда. Средний пишет дворовые песни про турник, кувшин и чинилку крыши — на сходе вместо суда он поёт их, и братья спорят, кто в какой песне был первым куплетом.","primary_genre":"Электропоп","primary_mood":"Уверенность","primary_theme":"Примирение","story_shelf":"Юмор: семейные драмы","conflict_key":"доля-в-доме-против-доли-в-песне","image_key":"годовой-сход-вместо-суда","turn_key":"спор-о-первых-куплетах","hook_key":"узнай-себя-в-куплете","sort_order":"1398","original_key":"rahman-baba|songs-after-feud","author_name":"Рахман Баба","original_title":"Диван Рахман Бабы (песни после ссоры братьев)","original_language":"Pashto","origin_country":"Афганистан","original_year":"","source_url":"https://en.wikipedia.org/wiki/Rahman_Baba","rights_check":"Справочно: права не проверяются, идея не текст. Автор умер около 1706.","music_adaptations":[],"source_synopsis":"После тяжёлой ссоры между братьями Рахман Баба ушёл от мирских споров — и писал стихи, которые в народе стали песнями; в пашто его называют голосом мира, любви и смирения.","main_image":"годовой сход двора, где третий брат поёт вместо судейства"},{"title":"Никто не вернётся","full_story":"На 80-летие бабушки семья сняла пароход: половина гостей плачет заранее — «может, последний раз». Арфист-каверщик вместо траурных песен играет старинную плясовую и поёт: никто не возвращается оттуда — так пируйте сегодня. К середине вечера плачущие танцуют с бабушкой, и «может последний» превращается в «запланируем следующий».","hero_pov":"арфист, который превращает прощание в пир","central_conflict":"Слёзы «последнего раза» против песни о том, что никто не вернётся: единственный способ не терять время — пировать сейчас, вместе с тем, кто ещё здесь.","emotional_arc":"от заранее горюющей семьи к заказу ещё часа хода","ending_direction":"Бабушка заказывает капитану ещё час — «может, последний раз» переписывается в «запланируем следующий» на обратном берегу.","hook_direction":"пируйте — никто не вернётся","genres":["EDM","Джаз"],"moods":["Эйфория","Нежность"],"energy":"Высокая","themes":["сцена","Время"],"generator_brief":"Пароходный EDM с арфой: нарастающий бит по течению, слёзы сэмплом превращаются в хлопки, дроп — заказ ещё одного часа хода.","generator_story":"На пароходе бабушкиного юбилея гости плачут заранее — вдруг последний раз. Арфист вместо траурных песен играет плясовую: оплакивать наперёд — значит терять день. К вечеру плачущие танцуют с бабушкой.","primary_genre":"EDM","primary_mood":"Эйфория","primary_theme":"сцена","story_shelf":"Трагические истории","conflict_key":"слёзы-последнего-раза-против-пира-сейчас","image_key":"юбилейный-пароход-в-сумерках","turn_key":"бабушка-заказывает-ещё-час","hook_key":"пируйте-никто-не-вернётся","sort_order":"1399","original_key":"anon-egypt|song-of-the-harper","author_name":"Аноним — Древний Египет","original_title":"Песнь арфиста (Папирус Харрис 500)","original_language":"Ancient Egyptian","origin_country":"Древний Египет","original_year":"","source_url":"https://en.wikipedia.org/wiki/Song_of_the_Harper","rights_check":"Справочно: права не проверяются, идея не текст. Анонимная традиция, эпоха XIII век до н. э.","music_adaptations":[],"source_synopsis":"Песнь арфиста на пиру: никто не возвращается оттуда, из страны вечности; поэтому веселитесь, не уставайте праздновать — таково завещание прежних царей.","main_image":"юбилейный пароход в сумерках"},{"title":"Птица на карнизе","full_story":"Ночь на мосту: он стоит и перебирает причины. Телефон вибрирует — его душа, как в старом тексте, спорит с ним: кто будет пить твой чай, кто прочитает твои бумажки? Птица на карнизе не улетает — сидит, как сидела бы его душа. К рассвету он спускается по лестнице вдоль реки — не вниз, а вдоль: идёт к круглосуточной, пьёт чай, и птица перелетает следом.","hero_pov":"человек, которого переубедила его же душа","central_conflict":"Все причины уйти против птицы на карнизе, которая не улетает: спор длится до рассвета — и выигрывает тот, кто остаётся.","emotional_arc":"от перебирания причин к чаю в круглосуточной вдоль реки","ending_direction":"Он спускается вдоль реки к круглосуточной и пьёт чай — птица с карниза перелетает следом, спор окончен её упорством.","hook_direction":"птица не улетела — и я","genres":["Техно","Эмбиент"],"moods":["Уязвимость","Надежда"],"energy":"Низкая","themes":["спасение","Ночь"],"generator_brief":"Минимал-техно на грани тишины: вода в левом канале, город в правом, один голос — и второй голос-птица, который спорит до рассвета и остаётся.","generator_story":"Ночь на мосту: он перебирает причины, а душа спорит — кто будет пить твой чай, кто прочитает твои бумажки? Рядом не улетает птица. К рассвету он пьёт чай в круглосуточной, и она перелетает следом.","primary_genre":"Техно","primary_mood":"Уязвимость","primary_theme":"спасение","story_shelf":"Трагические истории","conflict_key":"список-причин-против-птицы-на-карнизе","image_key":"птица-на-карнизе-над-ночной-рекой","turn_key":"чай-в-круглосуточной-вдоль-реки","hook_key":"птица-не-улетела-и-я","sort_order":"1400","original_key":"anon-egypt|dialogue-with-ba","author_name":"Аноним — Древний Египет","original_title":"Беседа разочарованного с душой (Папирус Берлин 3024)","original_language":"Ancient Egyptian","origin_country":"Древний Египет","original_year":"","source_url":"https://en.wikipedia.org/wiki/Dialogue_of_a_Man_with_His_Ba","rights_check":"Справочно: права не проверяются, идея не текст. Анонимная традиция, эпоха II тысячелетие до н. э.","music_adaptations":[],"source_synopsis":"Древнейший текст о человеке на краю: он хочет уйти из жизни, а его душа-Ба, которую изображали птицей, спорит с ним — жить и смотреть; их беседа кончается тем, что человек слушает свою птицу.","main_image":"птица на карнизе над ночной рекой"},{"title":"Когда придёт вода","full_story":"После засушливого сезона город на реке живёт на привозной воде. По радио передают: паводок пошёл. Половина города выходит на берег ночью — не по объявлению, а по привычке дедов: воду надо встречать стоя. Когда тёмная волна доходит до камней, город включает свет и поёт — кто гимн, кто просто кричит; рыбаки запускают сети. Утром город умывается той водой и мирится с соседями через мост.","hero_pov":"горожанин, который встречает воду стоя","central_conflict":"Привозная сухая скудость против волны, которую не видели год: встретить воду стоя или спать — город выбирает берег.","emotional_arc":"от привозных бутылок к общему гимну на тёмной волне","ending_direction":"Утром город умывается новой водой и мирится через мост — волна соединила берега, пока горел свет.","hook_direction":"встречай воду стоя","genres":["Драм-н-бейс","Классика"],"moods":["Вдохновение","Радость"],"energy":"Взрывная","themes":["Природа","Праздник"],"generator_brief":"Гипнотическое техно-паводок: слой воды нарастает как прилив, хор города входит с волной, дроп — тёмная вода доходит до камней под общий свет.","generator_story":"Год на привозной воде — по радио: паводок пошёл. Ночью половина города выходит на берег, как выходили деды: воду встречают стоя. Утром город умывается той водой и мирится с соседями через мост.","primary_genre":"Драм-н-бейс","primary_mood":"Вдохновение","primary_theme":"Природа","story_shelf":"Трагические истории","conflict_key":"привозная-вода-против-волны-года","image_key":"город-на-берегу-встречает-волну","turn_key":"утро-мирится-через-мост","hook_key":"встречай-воду-стоя","sort_order":"1401","original_key":"anon-egypt|hymn-to-the-nile","author_name":"Аноним — Древний Египет","original_title":"Гимн Нилу","original_language":"Ancient Egyptian","origin_country":"Древний Египет","original_year":"","source_url":"https://en.wikipedia.org/wiki/Hymn_to_the_Nile","rights_check":"Справочно: права не проверяются, идея не текст. Анонимная традиция, эпоха II тысячелетие до н. э.","music_adaptations":[],"source_synopsis":"Анонимный гимн приветствует разлив Нила: вода приходит к сухой земле, кормит стада и людей, и люди славят реку, которую не видели год.","main_image":"город на сухом берегу встречает волну стоя"}]$cj$;
  rec jsonb; v_id uuid; n int := 0;
BEGIN
  FOR rec IN SELECT * FROM jsonb_array_elements(c) LOOP
    IF EXISTS (SELECT 1 FROM song_idea_sources WHERE original_key = rec->>'original_key') THEN
      CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM song_ideas WHERE editorial_status = 'accepted' AND lower(trim(title)) = lower(trim(rec->>'title'))) THEN
      RAISE EXCEPTION 'SYNC DUB title=% (%)', rec->>'title', rec->>'original_key';
    END IF;
    IF EXISTS (SELECT 1 FROM song_ideas WHERE editorial_status = 'accepted' AND (lower(conflict_key) = lower(rec->>'conflict_key') OR lower(image_key) = lower(rec->>'image_key') OR lower(hook_key) = lower(rec->>'hook_key'))) THEN
      RAISE EXCEPTION 'SYNC DUB semantic=%', rec->>'original_key';
    END IF;
    INSERT INTO song_ideas (title, full_story, hero_pov, central_conflict, emotional_arc, ending_direction, hook_direction,
      genres, moods, energy, themes, generator_brief, generator_story, primary_genre, primary_mood, primary_theme,
      story_shelf, conflict_key, image_key, turn_key, hook_key, editorial_status, is_published, sort_order)
    VALUES (
      rec->>'title', rec->>'full_story', rec->>'hero_pov', rec->>'central_conflict', rec->>'emotional_arc',
      rec->>'ending_direction', rec->>'hook_direction',
      ARRAY(SELECT jsonb_array_elements_text(rec->'genres')),
      ARRAY(SELECT jsonb_array_elements_text(rec->'moods')),
      rec->>'energy',
      ARRAY(SELECT jsonb_array_elements_text(rec->'themes')),
      rec->>'generator_brief', rec->>'generator_story',
      rec->>'primary_genre', rec->>'primary_mood', rec->>'primary_theme',
      rec->>'story_shelf', rec->>'conflict_key', rec->>'image_key', rec->>'turn_key', rec->>'hook_key',
      'accepted', false, (rec->>'sort_order')::int)
    RETURNING id INTO v_id;
    INSERT INTO song_idea_sources (idea_id, original_key, author_name, original_title, original_language,
      origin_country, original_year, source_url, rights_check, music_adaptations, source_synopsis, main_image, editorial_status)
    VALUES (v_id, rec->>'original_key', rec->>'author_name', rec->>'original_title', rec->>'original_language',
      nullif(rec->>'origin_country', ''), nullif(rec->>'original_year', '')::int,
      rec->>'source_url', rec->>'rights_check', COALESCE(rec->'music_adaptations', '[]'::jsonb),
      rec->>'source_synopsis', rec->>'main_image', 'accepted');
    UPDATE song_ideas SET is_published = true WHERE id = v_id;
    n := n + 1;
  END LOOP;
  RAISE NOTICE 'SYNC inserted %', n;
END
$sync$;

UPDATE song_ideas AS i
SET generator_story = v.brief
FROM (VALUES ($cj${"1":"Ночной водитель подсаживает пассажира и узнаёт в нём себя постаревшего. До рассвета он решает, повторит ли старую ошибку, — и в финале сворачивает с привычного маршрута к дому.","2":"После расставания героиня замечает, что пустая квартира перестала повторять её слова. Она учится говорить вслух то, что раньше прятала, — и квартира снова возвращает ей голос.","3":"Парень возвращается в родной город и идёт по дворам, где всё стало чужим, — и понимает: чужим стал не город, а он сам. Он оставляет ключ от старого подъезда и идёт дальше.","4":"Взрослая дочь годами хранит не отправленное отцу письмо. В его юбилей она не пишет, а приезжает и читает его вслух — отец молча обнимает её после последней строки.","5":"Двое подростков тайком выращивают растения на крыше торгового центра. Когда её закрывают, они устраивают там последнюю ночную вечеринку, а наутро раздают семена незнакомцам.","6":"Музыкант перед выступлением на несколько минут теряет слух. В этой тишине он вспоминает, зачем начал писать песни, — и выходит к публике, начиная с одного честного аккорда.","7":"Старый рыбак каждый год отпускает одну пойманную рыбу в память о брате. В этот раз рядом племянник, который не знает истории, — и в финале сам выпускает рыбу в воду.","8":"Девушка записывает голосовые человеку, который давно не отвечает. Однажды после сигнала она слышит собственный голос — и оставляет последнее сообщение себе, на завтра.","9":"Молодой матрос на застрявшем во льдах корабле первым предлагает рискованный путь через шторм, пока капитан скрывает страх. На рассвете судно выходит к чистой воде.","10":"Пара после тяжёлой ссоры случайно слышит песню их первого свидания и танцует среди немытой посуды — не решив всех проблем, но решив остаться. Утром они моют посуду и смеются.","11":"Одинокий кузнец поднимает детей после смерти жены: работа не заменяет горе, но помогает семье жить дальше. Услышав, как поёт дочь, он впервые говорит ей, что её голос возвращает дому свет.","12":"Отец ночью застаёт сына, окружившего себя маленькими сокровищами, чтобы не бояться после наказания, — и понимает, что его гнев оказался больше проступка. Утром он сам начинает разговор.","13":"Суровый вдовец просит лучшего друга говорить с девушкой от его имени. Она слышит чужие слова и мягко возвращает посланника к его собственным чувствам — и друг впервые говорит о себе.","14":"После отказа герой просит любимую не возвращаться, а провести с ним один последний вечер. За поездку он перестаёт торговаться с её решением — и на последнем повороте отпускает её руку.","15":"Моряк после долгого отсутствия возвращается домой и узнаёт, что у любимой новая семья. Он выбирает её покой вместо права на прошлое и уходит, не разрушив дом, который считал своим.","16":"Две подруги встречаются после долгой разлуки: одна безупречно успешна в шёлковом пальто. Разговор раскрывает цену её блеска — подруги расходятся без простых ответов, но и без осуждения.","17":"Хозяин берёт щенка, зная, что придётся прощаться, и проживает дружбу внимательно: прогулки, ожидание у двери, обычные дни. Спустя годы он идёт на привычную прогулку — с благодарностью, без надрыва.","18":"Собака бросается в воду и спасает ребёнка, пока взрослые спорят, кто должен рисковать. После спасения люди видят в ней объект для опытов — очевидец уводит её домой, чтобы защитить спасителя.","19":"Мимо девушки проносится чужая свобода, и она впервые видит: окружающие уже написали за неё тяжёлый сценарий. Она не бежит за чужой каретой, а делает первый шаг в свою сторону.","20":"Молодую женщину бросают, а окружающие вместо помощи делают её виноватой. Она проходит через стыд и одиночество, находит поддержку и сохраняет себя и ребёнка — вопреки чужому приговору.","21":"Тихий партнёр годами исполняет всё растущие запросы любимого и понимает: близость не купить. У моря он впервые говорит честное «хватит» и выбирает взаимность вместо новых требований.","22":"Молодая художница годами видит мир только через экран, пока не решается выйти в город и прожить свою историю сама. Она покидает мастерскую, сохранив свой голос.","23":"Чтобы успеть на свадьбу сестры, герой просит друга поручиться за него перед опасным правителем — друг остаётся заложником обещания. Герой успевает вернуться вовремя и спасти обоих.","24":"Девушка ждёт обещанного человека, а он всё переносит путь, пока не понимает цену промедления. Она закрывает дверь на рассвете и идёт дальше.","25":"Двое бывших встречаются в парке, где когда-то были счастливы, но она уже не чувствует связи. Ему остаётся принять: сохранить можно лишь своё воспоминание, — и он уходит без ответа.","26":"Девушка не уходит от любимого в самую тяжёлую ночь, когда давление извне меняет его до неузнаваемости, хотя боится его перемен. На рассвете они остаются вместе по собственному выбору.","27":"Двое влюблённых выдвигают друг другу невозможные условия — проверяют чувства, как экзамен. В финале они отменяют условия и начинают говорить честно.","28":"Капитан получает приказ вывести корабль в опасный сезон и выбирает между служебным долгом и жизнью команды. Он отказывается вести судно в шторм и принимает последствия.","29":"Мать доверяет сыну ночное поручение и, потеряв его из виду, учится видеть не страх, а его самостоятельность. Сын возвращается домой своим спокойным маршрутом.","30":"Герой случайно разрушает убежище мыши перед самой зимой и впервые замечает последствия своей спешки. Без оправданий он строит для неё новое безопасное укрытие.","31":"Герой после тяжёлой ошибки хочет всё исправить одним великодушным жестом, но понимает: уважение к чужой воле дороже. Он принимает отказ и начинает менять себя делами.","32":"Ребёнок воображает, что сопровождает маму в опасном путешествии, и становится её защитником. На деле он находит простой способ быть нужным — и провожает маму домой.","33":"Город годами пользуется работой музыканта, а потом отказывается платить. Тогда он превращает их обещание в песню, которую слышат все, — и город признаёт долг.","34":"Два начинающих артиста хвалят друг друга на людях, пока случайный слушатель не называет их взаимную рекламу тем, чем она является. После неловкости они показывают результат, а не просят похвалы.","35":"Дочь берёт на себя семейную обязанность отца и годами скрывает себя ради семьи. Она возвращается домой, чтобы жить под собственным именем, и сама рассказывает свою историю.","36":"Женщина разбирает старую переписку и решает не хранить отношения как музей. Человек рядом понимает, что слишком долго молчал о разрыве, — и они отпускают эту историю без обещания примирения.","37":"Жена не соглашается с неизбежной утратой и проходит через трудный разговор, чтобы вернуть семье право на будущее. Семья встречает утро вместе.","38":"Старшая сестра пытается спасти родную от разрушительной зависимости, не осуждая её, и идёт ради этого навстречу опасности. Она возвращает сестре опору и остаётся рядом.","39":"Талантливая девушка принимает тяжёлое решение ради спасения семьи, но не отдаёт другим права распоряжаться её будущим. В финале она возвращает себе право выбирать следующий шаг.","40":"Влюблённых разлучают семьи и статус, но каждый сохраняет свой голос, чтобы любовь не стала зависимостью. Героиня выбирает жить и говорить от собственного имени.","41":"Героиня отвечает человеку, который требует близости и одновременно осуждает её за согласие. Она отказывается жить по его двойным правилам и уходит из разговора, не приняв чужую вину.","42":"Мужчина скрывает от любимой своё высокое положение, надеясь быть выбранным без титула, но тайна лишает её честного выбора. Она требует правду прежде, чем говорить о будущем.","43":"Молодой артист изучает историю влиятельного человека, от которого остались лишь самовосхваление и пустой памятник, — и отказывается повторять его путь, создавая работу для людей, а не памятник себе.","44":"Двое упускают взаимное чувство, потому что каждый заранее решает за другого, какую жизнь тому выбирать. Спустя годы они перестают винить друг друга за молчание.","45":"Отец готовит идеальный семейный выезд, но теряет контроль, и праздник превращается в комический хаос. Он учится смеяться над собой — дома историю превращают в любимую семейную легенду.","46":"Герой не решается написать той, с кем потерял связь, и приходит к собаке друга. Животное становится свидетелем его вины — и герой отправляет честное сообщение, не требуя ответа.","47":"Отец отдаёт последнее, чтобы сын начал свою жизнь, но понимает: выборы взрослого ребёнка нельзя прожить за него. Он оставляет недостроенную стену как знак открытой двери.","48":"Свободный, но голодный странник получает предложение комфортной жизни и почти соглашается, пока не замечает цену этой безопасности. Он уходит в неизвестность, сохранив право выбирать путь.","49":"Катастрофа разлучает влюблённых, и годы поисков проверяют, переживёт ли любовь исчезновение прежнего мира. Героиня находит не прошлое, а право продолжить путь.","50":"Когда героине по-настоящему нужна помощь, каждый из её приятелей передаёт её следующему. Она спасается сама и, поняв разницу между аудиторией и друзьями, перестаёт гнаться за количеством связей.","51":"Женщина выбирает жизнь в мире людей и оставляет семью между двумя несовместимыми берегами. Отец перестаёт звать её назад, принимает её выбор и заботится о детях.","52":"Подросток вынужден работать вместо учёбы, но находит друзей и записывает их мечты — превращает эти записи в повод потребовать перемен. В финале подростки вместе требуют возможности учиться.","53":"После неудачного похода муж оказывается далеко от дома, а жена превращает бессильное ожидание в сильный голос, который зовёт его обратно. Её голос становится для него знаком дороги домой.","54":"Семья едва сводит концы с концами, но, узнав, что у соседей остались дети без взрослых, решается дать им дом. В финале у огня оказывается достаточно места для всех.","55":"Отец, чьих дочерей унизили, выбирает не месть, а публичную справедливость — чтобы вернуть им достоинство и свободу. В финале дочери сами решают своё будущее.","56":"Герой долго просит близкого человека о честном ответе и получает лишь равнодушие. Вместо мести он прекращает односторонние попытки заслужить любовь.","57":"Мастер годами строит безупречную повозку — и в обычный день она распадается разом. Он перестаёт чинить образ совершенства и делает вещь, которой можно пользоваться и ошибаться.","58":"Ради выгоды герой убирает предупреждающий колокол с опасного места, а потом понимает, что рискует чужими жизнями. Он спешит вернуть предупреждение, пока чужой корабль не попал в опасность.","59":"В шторм команда теряет уверенность, пока дочь капитана не возвращает отцу способность действовать и доверять людям. К рассвету корабль входит в гавань — отец слышит в дочери опору, а не страх.","60":"Артист попадает туда, где его уязвимость принимают за слабость и приходят посмеяться. Он перестаёт доказывать свою ценность таким зрителям и находит команду, в которой может быть собой.","61":"Герой выполняет опасное требование любимой и понимает: любовь не строится на риске ради чужого одобрения. Он возвращает символ испытания и выбирает отношения без экзаменов.","62":"Герой после долгих лет несвободы получает право выбирать, но обнаруживает, что страх остался внутри. Его первая победа — выйти к людям и рассказать правду, шагнув к новой жизни.","63":"Молодой рыбак тайком переплывает реку ночью ради встречи с любимой, но оба понимают: любовь не должна превращать близкого в постоянный риск. Они договариваются встречаться днём и говорить открыто.","64":"Ослика все считают смешным и ненужным, но он помнит момент, когда именно его спокойный шаг оказался важен для всех. Он перестаёт ждать одобрения и идёт своим путём, зная себе цену.","65":"Молодой человек клянётся в верности, но при первом искушении нарушает слово. Он сам признаёт обман, не требует прощения и оставляет любимой право уйти без давления.","66":"Самоуверенный герой покупает велосипед, не собираясь учиться, но неуправляемая поездка учит его смеяться над собой. Он возвращается к друзьям и начинает заново, уже без хвастовства.","67":"Лидер команды уверен, что спасёт матч в одиночку, но проваливает решающий момент. Вместо поиска виноватых он слушает команду и возвращается к тренировкам вместе со всеми.","68":"Молодого всадника считают неопытным для трудной погони, но он с пони выбирает опасный путь и возвращает потерянный табун. В финале он приходит не за славой, а поблагодарить пони за общий риск.","69":"На празднике двух враждующих семей двое влюблённых тихо договариваются уехать — строить отношения без чужой войны. Они уходят, чтобы написать свою собственную историю.","70":"Робкий парень долго не решается заговорить с девушкой, пока зимний вечер не даёт ему смелости на один честный шаг. Он не прячется за окном, а стучит в её дверь и начинает разговор.","71":"Разношёрстная команда ищет то, чего никто не видел, но страхи и нелепые привычки мешают идти. В пути они становятся настоящей командой и понимают: сами оказались тем, ради чего вышли.","72":"Во время аварии молодой член команды ждёт недостижимого приказа от близкого человека. Он понимает: ответственность — вовремя подать сигнал, и выводит людей в безопасность до того, как станет поздно.","73":"На вечеринке чужой розыгрыш с личной вещью героини превращается в соревнование за статус. Она останавливает спектакль и уходит не побеждённой, а услышанной — с правом решать, что считается шуткой.","74":"Жители общего дома молчали о ночной угрозе, пока незнакомец не остался с ними до утра. Его спокойствие возвращает смелость: утром свет горит как знак, что люди больше не поодиночке.","75":"Оставшаяся одна героиня встречает спутника, которого сначала боится; дорога учит её доверять не обещаниям, а поступкам. Она идёт рядом, научившись не быть со страхом один на один.","76":"Поэт возвращается в город юности, к подъезду, где жила любимая актриса, — но дверь открывает чужая жизнь: её здесь больше нет. Он уходит с улицы — память осталась единственным адресом любви.","77":"Честный поэт с берегов, где растут пальмы, готовится к последнему сроку: перед смертью вылить из груди все стихи. Он прощается с друзьями и врагами без обиды, оставляя всем братское объятие.","78":"Рассказчик мучительно подбирает по нотам, а соседка Малинди не знает и нотной грамоты — но стоит ей запеть, заслушались бы ангелы. Музыка принадлежит тому, кто поёт сердцем.","79":"Идёт война, но будет ласковый дождь: ласточки промчатся над опустевшими крышами, лягушки запоют, сливы зацветут — и ни птица, ни дерево не вспомнят о людях. Весна, которой всё равно, придёт снова.","80":"Титан прикован к скале: орёл клюёт его печень, гремит гром — но он не подчиняется и не проклинает. Дар людям обошёлся в вечную муку, но в молчании у него больше силы, чем во всех громах.","81":"Мужчины Англии, вы пашете, ткёте и стрижёте, а богатство собирают те, кто не работал: вы носите золото на чужие пиры. Продолжать кормить угнетателей — значит копать себе могилу.","82":"Герой смотрит на любимую — чистую, милую, с золотыми волосами — и на сердце становится грустно. Вместо признания он молит Бога сохранить её такой красивой и чистой навсегда.","83":"Уставший путник выходит один на ночную дорогу: звёзды говорят друг с другом, и только ему не спится. Он ждёт не счастья, а покоя — уснуть последним сном под тёмным дубом, где шумят сосны.","84":"Герой зовёт выйти из душных комнат на открытую дорогу: всё нужное несёшь с собой, а цель есть в каждом шаге. Вся прошлая жизнь была тем же путём — его просто не замечали.","85":"Кот и сова плывут в зелёном чёлне: сова играет на гитаре под звёздами, и кот берёт её в жёны. На краю света они танцуют при луне — самая странная свадьба оказывается самой счастливой.","86":"Взрослый вспоминает, как больная постель превращалась в страну: холмы из подушек, оловянные армии, флоты на простынях, города из стульев. Чем меньше мир вокруг, тем больше вселенная внутри.","87":"Героиня перечисляет, как любит: до глубины души, в тихих ежедневных заботах, на солнце и при свечах. Счёт любви уходит за всякий предел — если Бог даст, она полюбит ещё сильнее после смерти.","88":"Один из двух голубей, живших в согласии, улетает искать счастье в чужих краях — и по пути его ждут ястреб, буря и силки. Он возвращается к другу, который ждал у окна, и понимает: счастье было рядом.","89":"Герой ведёт свою Печаль как спутницу по вечерней улице и ставит её рядом с собой на балкон, смотреть на толпы. Боль не прогоняют — её приручают: вечер становится свидетелем страдающего сердца.","90":"В закатный час герой видит птицу, упорно летящую через темнеющую даль, — мимо охотника за холмом и близкой бури. В её полёте он понимает: и его ведёт через одиночество к своему берегу.","91":"Герой идёт искать луга, где гулял мальчишкой, но находит чужие изгороди: рощи с орехами срублены, ручьи с пескарями пересохли. Лето юности жило в этих полях — теперь оно живёт только в нём.","92":"В ночь на Хэллоуин девушки гадают о судьбе: рвут капусту, ставят блюдца — и вскрикивают от каждого знака. А рядом влюблённые превращают гадание в повод взять за руку: судьбу предсказывает смех.","93":"Три королевских корабля уходят в море на весёлый день, и капитан видит морскую деву: она предсказывает судну не вернуться. Но экипаж только радуется — плохая примета ещё не значит плохой день.","94":"Герой заговорщицки признаётся: я — Никто, и если ты тоже — нас пара, только молчи, выдадут. Кем-то быть утомительно — весь день квакать имя болоту, а у Никто есть тишина и свой человек.","95":"Этруски идут на Рим, и трое держат узкий мост через Тибр, чтобы дать время разрушить его. Хораций прикрывает друзей до конца и под стрелами бросается в реку — Рим спасён.","96":"За окном буря и снежные вихри, а взрослый баловень судьбы просит старую няню выпить и спеть ему песню про синицу за морем. Им и грустно, и весело: буря не войдёт в дом, где вместе грустят.","97":"Героиня честно рада расставанию: ни письмом, ни снегом, ни зноем она его не выручит. Но интонация выдаёт: свобода выстрадана, и руки холодеют, хотя решение принято.","98":"Сын пишет матери: не буди во мне мечту о возвращении — пережито слишком много, в голове кипят волны шума. Он просит её не учить его жить, как раньше: прежним домой он уже не вернётся.","99":"Герой утверждает: не любовь та, что меняется с обстоятельствами или отступает перед тем, кто хочет её отнять. Настоящее чувство не игрушка времени — оно тянется до Судного дня.","100":"Каждый вечер в душный ресторан приходит незнакомка — в траурной шляпе и шелках, дыша древними поверьями. Пьяный наблюдатель принимает её за видение: сон, от которого можно сойти с ума.","101":"Путник после целого дня пути останавливается перед безмолвием: над вершинами покой, в лесу молчат птицы. Ему остаётся немного подождать — и покой ночи станет его сном.","102":"Старый мореход исповедуется свадебному гостю: выстрел в альбатроса накликал на корабль штиль и гибель команды. Теперь он вечно странствует и рассказывает это — слушателю становится легче.","103":"Скорбящий в полночном кабинете задаёт ворону вопросы о Ленор, а птица на бюсте Паллады отвечает всегда одним и тем же. Тень ворона ложится на пол — и душа уже не вырвется из неё.","104":"Герой проводит бессонные безумные ночи — вздохи беззвучны, речи невнятны, — но принимает всё от любви: и мученья, и счастье. Никто не страдал так, как он, — и никто не был так счастлив.","105":"Герой глядит на тигра в лесах ночи и спрашивает невидимого творца: какая рука решилась выковать этот пугающий облик? Тот, кто создал ягнёнка, создал и тигра.","106":"Поезд неслышно стоит на жаркой пустой станции, пассажиры дремлют, и чёрный дрозд поёт, будто перечисляет все деревни вокруг. Это мгновение остановки стало вечным воспоминанием.","107":"На шумном балу герой случайно замечает её: тайна покрывает черты, печальные глаза лучисто цветут, голос звучит отдалённо, как поцелуй вдали. Одна случайная встреча становится судьбой.","108":"Герой признаётся: ради любви он готов отдать жизнь, но ради свободы — и саму любовь, ведь вкусившему свободу не жить в оковах. Его выбор — не предательство, а высшая цена.","109":"Бледный рыцарь помнит даму с дикими глазами, увлёкшую его в эльфийский грот, и сон о плене у безжалостной красавицы. Он очнулся на холодном холме — и теперь одиноко бродит.","110":"За окном тучи без конца, дождь льётся, мокнет чахлая рябина — сердце ребёнка ещё просит света и тепла. Но он уже ждёт зиму: снег забелит поля, и полетят сани.","111":"Отец перечисляет сыну испытания: сохранять голову, когда все теряют и винят; доверять себе, когда все сомневаются; встречать Триумф и Катастрофу одинаково. Выдержавший все «если» — хозяин Земли.","112":"Бывший заключённый вспоминает сокамерника, молившегося перед казнью за убийство любимой: каждый убивает то, что любит — трус поцелуем, смелый мечом. Ближе всех к Богу тот, кто взглянул на свою вину.","113":"Герой решается не сказать любимой ничего и не осмелится даже намекнуть, что он молча твердит. Слова бессильны — за него шепчут дрожащие осенние листья, и молчание говорит громче.","114":"Герой благодарит Бога за пёстрые вещи: небо в пятнах, розовые точки на форели, каштаны в огне, крылья зябликов. Красота мира — в разноцветности и перемене, и хвала тому, кто неизменен.","115":"Молодая пара всю ночь катается на пароме с корзиной яблок и слив, а на рассвете раздаёт всё — старушке, дедушке, нищим. Домой они возвращаются ни с чем, но с целой ночью в памяти.","116":"Мудрец за чашей вина напоминает: кувшин был глиной на могиле пировавших до нас, а существует только глоток настоящего. Пей мгновенье, но помни: ты из той же глины.","117":"Герой заявляет: никакая земная буря не поколеблет его веру, ведь смерть — лишь бессмертная сила любви. Пусть рушатся сотворённые вселенные — в его душе нет трусости.","118":"Юный Лохинвар влетает в зал, где идёт свадьба его возлюбленной, и приглашает невесту на танец. Пока они кружатся, у ворот оседлана лошадь — молодые ускакали, и их никто не догнал.","119":"Утром снег ложится на поля мягкими подушками, берёзы у дома стоят в инее, тихие и белые. Холодная пора становится праздником: стране радостно встречать зиму, как хозяйку.","120":"Усталый герой просит мечту прийти хотя бы на ночь: в его днях каждый шаг — по камню. Утром он снова уйдёт в серость, но с огоньком мечты в груди — она не спасает, но греет.","121":"Горожанин, добрый как хлеб, выжил после укуса взбесившейся собаки — а собака умерла. Народ дивится чуду: вот теперь видно, что не всякий укус убивает и не всякий праведник прав.","122":"Мальчик Джим вырвался из рук няни и вбежал в вольер льва — лев съел его целиком, от обуви до курточки. До конца жизни няня твердит: слушайтесь няню, иначе лев съест и ботинки, и курточку.","123":"Спешащий горожанин ловит себя: некогда увидеть, как коровы жуют на лугу и ручей блестит сквозь листву. Он приносит приговор своей жизни: полная забот жизнь без часа на созерцание — бедная жизнь.","124":"Преследуемый всадник выносит коня к краю пропасти: позади погоня, впереди — обрыв. Он признаёт в животном не средство спасения, а равного спутника — и они прыгают, чтобы перелететь вместе.","125":"Горожанин среди серых мостовых мечтает уйти на озёрный остров: хижина из глины и прутьев, девять рядов фасоли, улей пчёл. С этим берегом он не расстаётся: стоит прислушаться к сердцу — и он уже там.","126":"Дочь получает знак, что близкому грозит беда, — спасать его придётся через помощь того, кому она не привыкла доверять. Она выбирает действие вместо ожидания и ставит всё на этот единственный шанс.","127":"Сердце героя плачет вместе с городом от какого-то дождя без причины — ни измены, ни печали не было. Он принимает эту боль без названия: она просто идёт, как дождь, и не всякой боли нужна причина.","128":"Птицы носили весточки между влюблёнными, пока чужая игра не отняла у них дом. В разлуке женщина проверяет не романтические слова, а верность — и находит путь обратно не по карте, а по верности.","129":"Слушатель города слышит, как каждый поёт своё: плотник — меряя доску, швея — у машины, матрос — на палубе. К утру отдельные песни срастаются в общий хор из тех, кто поёт своё.","130":"Лидер команды тянет с призывом союзников, боясь показаться слабым. Когда становится ясно, что одному не справиться, он признаёт: просьба о помощи — не поражение — и подаёт сигнал, пока не поздно.","131":"Во сне по стране маршируют Маски — Страх, Лицемерие и Анархия — и зовут законы служить себе. Народу отвечают: вас много, их мало — стройтесь, как пчёлы, и удар отскочит от стойкого молчания.","132":"Пожилая хозяйка делит последнюю еду с незнакомыми гостями, хотя у неё с мужем почти ничего нет. В скромном доме забота оказывается дороже достатка — пара понимает цену своего простого счастья.","133":"Героиня признаёт: балету её не учили, на носках не станцевать, — но душа её танцует невидимо за окнами дома. Загляни кто — спросил бы, где учили такой технике: лучший танец не виден глазу.","134":"Вернувшийся после долгих лет странник входит в дом — и первым его узнаёт старый пёс, ждавший все эти годы. Мгновение встречи вмещает годы разлуки, и герой решает: больше не откладывать близость.","135":"Герой скорбит по тихой деве-фиалке у серого камня, которую не знал никто и любили лишь немногие. Она умерла — мир не заметил потери, но для него вся разница: погасла единственная звезда.","136":"Жена проводит с мужем последний спокойный вечер перед вынужденной разлукой: до рассвета нужно сказать всё главное. Не обещают невозможного — вместо громкой клятвы остаётся честный разговор.","137":"Герой смотрит на город вдали, куда говорят уходят враждовавшие, чтобы стать добрыми и помириться. Оттуда его вражда кажется пылью на дороге, которую ветер стирает, — и обиды теряют вес.","138":"Девушка влюбляется в пленника башни и вопреки запрету семьи сама ищет способ его спасти. Она находит ключ к свободе — и открывает этой дверью не только его камеру, но и свою.","139":"Девяностолетняя Барбара Фричи выставляет в окно последний уцелевший флаг города при входе мародёров. Приказ стрелять командир отменяет — а старушка умирает, унеся флаг из-под огня как наследство.","140":"Разрозненная стая ищет вожака, который разом решит все её проблемы. Дорога отсеивает любителей готовых ответов: оставшиеся возвращаются не с новым правителем, а с умением отвечать друг за друга.","141":"Поэт просит Селию утолить его жажду одним взглядом вместо вина. Возвращённая чаша дышала ею — он пил бессмертие; теперь достаточно вздохнуть на её венок, и любимая всюду с ним.","142":"Матери, давно потерявшей сыновей, даётся одна последняя ночь для разговора и прощания. Утром она отпускает гостей — выбирает не забвение, а жизнь с памятью, где сыновьям остаётся их место в доме.","143":"Шестьсот кавалеристов по ошибочному приказу несутся в долину смерти: пушки справа, слева и в лоб — никто не ропщет. Прорвались и вернулись не все — их чтят за то, что долг исполнен до конца.","144":"Соперничество превращает близость младшей сестры со старшей в тайну и предательство. Но правду не заставить молчать: скрипка сыграет её вслух — и тайна перестанет принадлежать той, кто её прятал.","145":"Рассказчик среди жары перечисляет лето: цветы, шмели, знойные росы, пыльца, солнце — и слово «умри». Он принимает всё разом: лето — это жизнь, где цветение и конец идут рядом, и в этом нет грусти.","146":"Мать расспрашивает вернувшегося после опасной встречи сына — простые вопросы открывают страшную правду. Разговор дома становится местом, где сын перестаёт скрывать страх и не остаётся с бедой один.","147":"Отец в кабинете слышит топот маленьких ног: три дочки врываются, забираются на колени и шепчут, что замок Змей-башни взят в осаду. Правитель сдаётся без боя — и это счастливейшая его победа.","148":"Ученик запускает механизм, чтобы разом избавиться от скучной работы, — помощник выходит из-под контроля. Вместо того чтобы прятать ошибку, он останавливает хаос и начинает заново, зная цену контроля.","149":"Народное предостережение: в полночь эльфы опускают колокол для некрещёных — украденная старушка Триша умерла на десятую ночь, и её привидение теперь танцует с ними. Дети, не открывайте ночью окон.","150":"Молодого ныряльщика толпа снова толкает рисковать жизнью ради чужого восхищения. Он понимает: смелость — не бесконечно доказывать себя, а вовремя отказаться — и уходит, сохранив право на свой риск.","151":"Изгнанник за морем представляет апрель дома: груша у забора за ночь брызнула пыльцой, жёлтые цветы проснулись с соком, поют соловьи. Его поля цветут далеко — но внутри него они цветут громче всего.","152":"Созерцатель слышит в полусонном ночном лесу беззвучные шаги: лунные лучи скользят между стволов — эльфы выходят на поляны. Ни звука, кроме шёпота ветра в листьях: ночью оживает то, чего не видно днём.","153":"Сын, которого ложь и чужие интриги разлучили с семьёй, растёт далеко от дома и ищет путь к правде. Море приносит весть о родных — и он возвращает семье правду, не отвечая ложью на ложь.","154":"Герой на вечерней реке помнит с детства: розовый отблеск за тёмным лесом, пар над блестящей водой. Тихий вечер рождает вполголоса песню о тёплом чувстве, которое светит без пламени и не сгорает.","155":"Героя-неудачника, которого все считают случайным и слабым, выручает незаметный маленький конь. Вместе они проходят испытания, где статус ничего не решает, и герой больше не прячет честного друга.","156":"Герой понимает птицу в клетке: в ясный день она бьётся грудью о жестокие прутья и молит небо о свободе. Её песня — не радость, а мольба из раненого сердца, которая поднимается к небу.","157":"Старший в команде рассказывает молодым о дне, когда остались только взаимная опора и ответственность друг за друга. Его история не о славе, а о памяти, переданной дальше без громких обещаний.","158":"Герой издали смотрит на деревню детства: хрущи жужжат над вишнями, пахари идут на вечерю, мать ждёт семью. Картинка живёт без него — дом ярче в памяти, чем в реальности, и вернуться нельзя.","159":"Юноша ловит первый взгляд девушки — и кровь вокруг сердца остывает, мир перевернулся. Чувство — цветок, который нельзя сорвать: первая любовь не умеет говорить, только чувствовать.","160":"Капитаны ведут корабли сквозь штормы и мимо базальтовых скал, оставляя позади женщин, ждущих у камина. Кого не убило море — тому море теперь дом: кто выбрал путь, выбрал не возвращение.","161":"Гитара начинает плакать — и её невозможно умолить: она плачет монотонно, как вода по ветру, за любовь, которая не понимает окон. Пять струн пускают свои чёрные стрелы прямо в сердце.","162":"Молодость просит крыльев, чтобы подняться над мёртвыми долями и кричащими путями, где старые не пойдут. Кто один — гора, кто вместе — пламя: юных держит дружба, и на ней они сильны.","163":"Герой сидит на пне там, где стояли тополя: ни тени, ни зелени, ни песни дрозда, а река течёт без деревьев. Он чувствует себя срубленным наполовину: приятели ушли — и его день тоже кончается.","164":"Экипаж Джамбли плывёт через двадцать морей в гигантском решете, вопреки вердикту «вы утонете». Шторм им нипочём — и через сорок лет они триумфально возвращаются домой в новом решете.","165":"Старый друг вспоминает, как они вдвоём бегали по склону и рвали ромашки, пока между ними не встали дороги и моря. Разлука не стёрла дружбу: он протягивает руку и зовёт выпить за прошлое.","166":"Одинокий парус белеет в тумане моря: счастья он не ищет и от счастья не бежит. Волны играют, мачта гнётся — но парусу подавай шторм, как будто покой живёт в бурях.","167":"Герой в осеннем саду находит последнюю розу лета, оставшуюся среди увядших подружек. Он не может бросить её увядать одной: дружба гибнет, когда её не разделяют, — и он идёт делить её участь.","168":"Герой понимает: любимая не принадлежит дневному свету — в её красоте всё из снов, а голос звучит как музыка ночной воды. Её можно вспоминать только во сне — она звезда ночная, и пусть день завидует.","169":"Уходящий герой не берёт с любимой ни слёз, ни обещаний — он оставляет ей только благословение и светлую дорогу. Его любовь оказалась сильной на отпускание: держать не осмелилась — пожелала счастья.","170":"Детское сердце ловит тарарах ласточек, вернувшихся после долгой зимы: они уже вьют гнездо, и дождик им не помеха. Ребёнок слушает птиц у окна и ждёт минуты, когда можно бежать в просыпающееся поле.","171":"Герой на мосту Мирабо слушает Сену: вода и любовь текут под ним, не остановить, хотя руки ещё сцеплены лицом к лицу. Дни уходят, часы звонят — он остаётся на месте и принимает, как устроено время.","172":"Мы молимся о коротких днях: пройти через темноту, не отняв у соседа хлеба, помогая слабому и простив врага. Просьба одна — пусть сердце не станет камнем в озлобленном мире.","173":"Сын полковника догоняет через пустыню конокрада Камала, и тот, стреляв первым, не убивает — признаёт в юноше равного. Двое сильных лицом к лицу стирают границу между Востоком и Западом.","174":"Герой годами жил без божества, без вдохновения и слёз, пока шумная суета не заслонила от него её голос. Новая встреча пробуждает душу: сердце бьётся, и всё воскресло — жизнь, любовь, вдохновение.","175":"Путник слушает в осеннем поле, как роща золотая отговорила берёзовым языком, а журавли пролетели, не жалея ни о ком. Он тоже не жалеет ни лет, ни души: каждый в мире странник — и это нормально.","176":"Героиня слышит в душе птицу с перьями, которая поёт без слов и не смолкает даже в самый сильный шторм. В холодных краях и странных морях она ни разу, в любом горе, не попросила крошки.","177":"Герой с усмешкой перебирает поэтические штампы: её глаза не солнце, коралл краснее губ, снег белее груди. Но он клянётся: живая любимая дороже всех идеальных сравнений.","178":"Герой в разлуке думает о любимой с восхода солнца до вечерней росы: тень её образа приходит к нему, как луч и звёздный свет в ночи. Он слышит рядом её дыхание — любимая с ним, даже когда далеко.","179":"Ассирийская армия катится на Галилею волной: копья блестят звёздами на воде. За одну ночь невидимое дыхание сносит всё войско — к утру конь с открытой пастью стоит над мёртвым седоком.","180":"Воин кладёт щит и меч у реки и обещает себе путь мира вместо войны. У воды всё меняется: впервые слышно собственное сердце — и герой надевает платье мира.","181":"Швея одной иглой шьёт рубашку до самого солнца, и каждая строчка смочена слезой: лето сменила зима, а работа не кончается. Жизнь съедена строчками — тело в рубашке, и больше ничего.","182":"Дед Каспар рассказывает внукам о славе знаменитой битвы, пока Питеркин не поднимает в траве череп. На вопрос девочки, зачем была битва, дед может ответить лишь одно: была победа — и всё.","183":"Герой плеснет краской в карту будней: на блюде студня проступают скулы океана, жестяная рыба зовёт новыми губами. А скучному обеду — дерзкий вызов: сыграть ночную мелодию на водосточной трубе.","184":"Наблюдатель встречает старого знакомого в марте: тело дрожит, крашеный парик, друзья его поколения высечены в камне. Но душа держит его, как последний листок, который гнётся — и не отпускает ветку.","185":"Герой видит на конюшне, как девушку стегают кнутом, а она молчит: ни слезы, ни стона — только терпеливое достоинство в глазах. Это молчание становится его музой, которая учит не покоряться.","186":"Юноша спорит с тем, кто зовёт жизнь пустым сном: могила не цель, душа не пепел, сердце бьётся только в настоящем. Его ответ — трудиться и ждать, оставляя следы на песках времени для идущих следом.","187":"Герой отпускает горькие думы побродить по Украине, но знает: там сироты у заросших хат и никто их не встретит. Думам остаются курганы и днепровские просторы — в опустевший дом возвращаться незачем.","188":"Старик за тарелкой супа рассказывает, как их корабль разбился и команда, ставшая роднёй, осталась на льдине без еды. Голод привёл к страшной сделке: выжил он один — и говорит об этом с чёрным юмором.","189":"На зелёном холме звенят голоса играющих детей, а седые деды под дубом смеются, вспоминая свою зелень. Вечером дети уходят домой — но холм один и тот же: на нём когда-то звучали голоса всех поколений.","190":"Герой ждёт любимую под сосной у дороги: каждая тень и каждая поступь — не она ли? Ожидание растянуло время до годов, но он счастлив уже от него — за ожиданием стоит встреча.","191":"Голос девушки в церковном хоре обещает отраду всем усталым и всем, чьи корабли ушли в море, — и луч сверкает на белом платье. Но старик у входа плачет: он знает, что эта мечта уйдёт в тёмные поля.","192":"Девочка Матильда однажды крикнула ложный «пожар» — приехала команда, огня не было, и её наказали. Когда беда случилась всерьёз, однажды солгавшей не поверили — и пламя взяло дом.","193":"Рыцарь Тоггенбург теряет любимую: дева уходит в монастырь — и он селится в хижине у подножия её горы. Каждый день он поднимает глаза к террасе, ждёт её взгляда — так молча и верно проходит вся жизнь.","194":"Юный менестрель идёт на войну с мечом, неся арфу лентой на плече, — и падает в бою. Перед смертью он ломает арфу, чтобы её звуки не достались врагу, и душа улетает вместе с последним звоном.","195":"Герой клянётся: его сердце взлетает при виде радуги — так было в детстве, так есть сейчас, и пусть так будет в старости. Он хочет, чтобы все дни соединяла благодать: ребёнок в нём — отец взрослого.","196":"Ямщик слушает в дороге колокольчик под дугой: в унылом звоне — и радость, и печаль пути. Каждая нота звучит как голос той, кого он любил, — он просит колокольчик не молчать и петь, с ним легче ехать.","197":"Герой-часовой клянётся любимой: пусть царит день или тишина ночи — его душа стоит на страже, не зная отдыха. У любви нет дня и ночи: всё, что он любит, в ней, и этот пост — навеки её.","198":"Герой верит товарищам: придёт день, когда не останется ни господина, ни слуги и никто не съест чужой труд. Смехотворцам он отвечает: сколько раз «нельзя» оборачивалось «можно» — работайте и ждите.","199":"Рассказчик не может забыть сказку о Лорелей: в сумерках над Рейном она гребёт золотые волосы и поёт на вершине. Заглядевшись на неё, лодочник пропускает рифы — и волны съедают его лодку.","200":"Рассказчик встречает первое утро зимы: природа одета в пух, поле — как чистый лист, леса в шапках, река стоит под стеклом. Детство просыпается разом — салазки, горки, смех: пришла хозяйка праздника.","201":"Маршевый призыв друзьям: вперёд, без страха и сомнений, на подвиг доблестный — не стыдиться былого и не оглядываться. Смелые свергают горы, гонимые верой — тому сияет звезда.","202":"Осенний лес стоит в золотом уборе: листья — ковёр под ногами, холодное солнце светит сквозь них, птицы улетели, ветер спит. Но это не похороны, а прощальный бал — красота не горюет.","203":"Человек на сцене мира сменяет роли: воющий младенец, неохотный школьник, вздыхающий влюблённый, солдат с клятвами, судья, старик. Последняя сцена возвращает детство — без зубов, без глаз, без всего.","204":"Герой, изнемогший в тёмном лесу, встречает серафима: тот открывает ему очи, наполняет уши звоном и ставит пылающий уголь вместо трепетного сердца. Пророку велено нести слово, разжигающее сердца.","205":"Героиня из вечности вспоминает поездку в карете, где попутчиком оказалась сама Смерть, никуда не спешившая. Мимо школы, полей и заката карета довезла до дома-насыпи — и века кажутся короче того дня.","206":"Новобранец спрашивает, почему бьют барабаны, — так положено: Дэнни Дивер убил товарища, его несут в последний путь. Полк молчит у виселицы, и сержант даёт урок: закрой рот, бойся — так было всегда.","207":"Отчаявшийся человек в метеорную метель несёт небу, задыхаясь, свои «жемчужины» и молит: пусть обязательно будет звезда. Он плачет и целует руку — веря, что небо светит тем, кто не может без него.","208":"Тринадцатилетний пастух пасёт овечек за селом босиком, когда мимо проходит юная девушка. Он не знает ни слова, но всем телом понимает: первая любовь окликнула его из детства.","209":"Раненный в груди офицер лежит в жаркой долине Дагестана и видит сон: дома пир, а девушка на родине вдруг слышит разговор о его смерти. Она ещё не знает правды — но её во сне обдаёт холодом.","210":"Старый Одиссей скучает на троне: его дух не стареет вместе с экипажем, а за аркой опыта сверкают невиданные миры. Он зовёт спутников отдать концы и снова уйти в море, чтобы искать и не сдаваться.","211":"Матрос мольбой будит отца-капитана: страшный рейс окончен, приз добыт, порт близко, звенят колокола. Но на палубе капитан остался мёртвым — корабль пришвартован, и его губы бледны и неподвижны.","212":"Герой ходит в сияющем утреннем саду, где цветы шепчут ему оправдания за любимого и смеются, звенят, кружатся в танце. Он не может решить: правду ли говорят цветы — или это его собственный сон.","213":"Ночь любви рассказана без глаголов: шёпот и трели соловья, серебро сонного ручья, тени и волшебные изменения любимого лица. К утру — пурпур розы, янтарный отблеск и поцелуи под первой зарёй.","214":"Герой молит дикий западный ветер: тот уносит листья, как призраки, и разносит семена до весны. Он просит быть листом, облаком, волной — петь тростником сквозь кровь на шипах жизни.","215":"Поэт просыпается из сна о Ксанаду, где дворец стоит над пещерной рекой, а девушка поёт под арфу. Мелодия ушла с пробуждением: воскресив её, поэт поднял бы дворец прямо в небо на всеобщий ужас.","216":"Созерцатель встречает женщину, в чьём лице соединились лучшее тьмы и света — она несравнима, как безоблачная звёздная ночь. Мягкий свет на щеке и брови выдаёт чистое сердце и невинную любовь.","217":"Герой сравнивает любимую с красной розой июня и клянётся любить, пока моря не высохнут и солнце не расплавит камни. Это прощание на время: он обещает вернуться через десять тысяч миль.","218":"Герой гуляет по ночному городу и в каждом лице читает горе: в криках, детском плаче и вздохах солдата слышны оковы, выкованные разумом. В полночь он слышит, как проклятие падает на младенца в слезах.","219":"Созерцатель обращается к родной земле как к жене над ленивой рекой и стогами в степи: их путь долог, бой не кончается. Степная кобылица мнёт ковыль — он не первый слез на этом поле и не последний.","220":"Ночь уходит: звёзды гаснут, огненные полосы вспыхивают в облаках, туман течёт по чёрным бороздам, слышен вздох зябка. Солнце поднимается с высоты — и мир благодарит новый день.","221":"Герой в туманном седом утре нехотя вспоминает былое: забытые лица, страстные речи, взгляды, что ловили так жадно. Прошлое видно, но вернуться нельзя — оно тает, как этот туман, не оставляя следов.","222":"Рассказчик любуется первой майской грозой: молодой гром резвится в голубом небе, брызжет дождик, солнце золотит нити, поток бежит с горы. Весенняя земля шумит и смеётся вместе с раскатами.","223":"Герой проповедует жизнь без половинчатости: любить — до потери головы, грозить — всерьёз, рубить — сплеча, признавать ошибки — честно. Всё или ничего: жизнь коротка — живи красиво.","224":"Гонец мчит ночью с доброй вестью из Гента в Ахен: кони падают один за другим — сначала у Дирка, потом у Януса, его конь добегает. Весть объявлена, но гонцу уже не говорить: в сердце звенят копыта.","225":"Старый скиталец всю жизнь ищет девушку, которой стала пойманная форель: она назвала его по имени и исчезла. Он обещает взять её руку, пройти через длинную траву и сорвать луну и солнце, как яблоки.","226":"Утка мечтает о дальних дорогах и просит кенгуру научить её скакать, но тот уверен: дело в её холодных ногах. Утка достаёт носки и шарф, садится в сумку — и вместе они трижды огибают земной шар.","227":"В полночь разносится трубный сигнал, и со всех сторон съезжаются павшие солдаты — с полей, из морей и гор. Император едет вдоль рядов и каждому спрашивает о службе: мёртвый строй стоит вечно.","228":"Герой видит любимую душу как пейзаж: маскарады танцуют под лютню, чуть печальные за причудливыми костюмами. Луна грустит над статуями, и фонтаны рыдают великой струёй в мраморе.","229":"Мальчик с картой во сне видит азиатские пески, пальмы и Китай, города, где рычит лев, и попугаев. Со своей книгой странствий он клянётся: вырастет — и все эти земли ждут его.","230":"Весёлая Стрекоза пропела всё лето и не заметила прихода зимы: поле помертвело, просить негде кроме Муравья. Он не пускает попрыгунью до весны и отправляет певицу танцевать вместо песни.","231":"Герой в зрелости прощается с молодостью без жалоб: сердце тронуто холодком, дух бродячий греет всё реже, страна берёзового ситца больше не заманивает. Он спокоен — всё проходит, как тают цветы в дым.","232":"Туманный город превращён в жёлтую акварель: омнибус ползёт, как бабочка, толпа скользит маленькой точкой, мосты тонут в зелёной мгле. Туман здесь — художник: он переписывает улицы, пряча лица.","233":"Солдат мёрзнет в туманном Лондоне и вспоминает Бирму: жаркое солнце, звон колокольчиков, пряный ветер и летающие рыбы над дорогой на Мандалай. Он клянётся вернуться туда, где теплее, чем в реальности.","234":"Герой будит красавицу морозным утром: вчера злилась вьюга, а нынче снег лежит коврами под голубыми небесами. Вместо тёплой лежанки ждёт бег коня по снегу — надо успеть показать ей северные берега.","235":"Поэт отказывается сравнивать любимую с летним днём: май треплется бурями, а лето слишком коротко. Её вечное лето не увянет — строки, что живут, пока люди дышат, дарят её красоте бессмертие.","236":"Юноша стоит перед выбором после пощёчины, полученной отцом от графа: месть или любовь к дочери обидчика. Он выбирает честь и побеждает в дуэли — любовь прощает его, но не сразу: такова цена.","237":"Жизнь человека рассказана звоном: серебряные бубенцы сулят веселье, золотые — свадьбу, бронзовые — пожар и тревогу, железные — похороны. Четыре звона — от саней до вечности: время слышно в металле.","238":"Шкипер из Глостера берёт дочь на последнее плавание и при урагане привязывает её к мачте — чтобы не смыло. Судно разбивается: девочку находят у берега замёрзшей, с распущенными волосами по ветру.","239":"Герой шепчет при первых лучах: не трогай спящую — утро так сладко, и в её сне живёт тихая радость. Любовь умеет ждать: подойдёт время — она проснётся сама и улыбнётся тебе.","240":"Герой знает правду и отметает старые истины: все мы в пути, но любовь сильнее смерти. Под вечерним небом, где летят тополя, это знание звучит тихо и непоколебимо.","241":"Лирический герой пришёл в мир, чтобы увидеть Солнце, горы, море и пёстрые долины, и сводит все миры в единый взор — хозяин увиденного. Пробудившись из мрачного сна, он любит весь мир.","242":"В бурю всю ночь слышен стук копыт: невидимый всадник скачет мимо окон спящих, и никто не знает куда. Но всякий ребёнок, слушающий ветер, знает — всадник рядом: в ветре есть свои всадники.","243":"Отец предостерегает юношу от лесного чудовища, но тот берёт меч и идёт в чащу. Тварь с огненными глазами вылетает — и падает мёртвой у ног героя. Сын возвращается с головой, и отец славит храбрость.","244":"Отец мчится через ночь с сыном, а ребёнок дрожит: лесной царь зовёт его и сулит дочерей-золото. Отец твердит про туман и ивы и гонит коня быстрее. У дома в его руках мёртвый младенец — царь забрал.","245":"Гробницы, мумии и кости молчат — только слову дана жизнь. На мировом погосте звучат одни письмена, и всё живое в нас живёт в словах. Бессмертно лишь слово: оно переживёт тела.","246":"Герой останавливается в горной долине: девушка одна жнёт и поёт, и никто не слышал её песни — о старых горестях или простом знакомом. Он слушает неподвижно, и мелодия звучит в нём ещё долго.","247":"Герой обращается к осени, которая заклинает солнцем плоды: грозди винограда, яблоки, орехи. Где песни весны? Не тужи — у осени свой оркестр: рой мошек, сверчки, блеющие ягнята, свист робина.","248":"Герой ночью идёт к любимой: лунный полумесяц, лодка скользит в залив, миля тёплого запаха моря и три поля до её окна. Спичка вспыхивает, сердце стучит — и голос тише шёпота: она здесь.","249":"Герой просит любимую любить его не за улыбку, взгляд и мягкость речи — всё это изменится, — а за любовь саму по себе: она не стареет и не меняется. Люби меня так — и я тебя.","250":"Наставник отучает героя жить прошлым и будущим: вчерашние беды не вернуть, завтрашние не предугадать — вера верна, напейся сегодняшним. Есть только этот день, и в нём вся жизнь.","251":"Ночной Днепр ревёт и стонет, сердитый ветер завывает, бледная луна глядит из-за тучи. Думы героя разлетаются по миру — и никто их не слышит, только ветер да луна. Так и мысли не находят пристанища.","252":"Герой обращается к любимому: небо, море и поля соединились в нём одном, и где бы тот ни был — там родина и вся жизнь. Весь мир уместился в одном человеке.","253":"Удалой косарь с весёлым лицом режет траву под корень: шире шаг, шире взмах — и всё летит от размаха. Работа для него — как удаль: режь не жалей, отдых впереди.","254":"Старая жена вспоминает чёрные локоны мужа Джона и видит его седую голову — и благословляет её: они прошли вместе всю жизнь и дойдут до конца рука в руку.","255":"Смерть стоит за спиной героя и шепчет про вечность, а он затыкает уши: будет жить по-своему — любить, трудиться, смеяться. Смерть умеет ждать, а он не торопится.","256":"Герой обращается к холодному кинжалу в ножнах: был невинным, как свет звезды, но однажды пущенным в дело навсегда остался острым и метким. Хранители не спят — оружие ждёт своего часа.","257":"Герой видит грустный взгляд любимой — и утешает: далёко на озере Чад бродит дивный жираф, который расскажет сказки о чёрной деве и царе дельфинов. От сказок о далёком её слёзы высохнут.","258":"Герой ловит мгновение праздника: искристый острый вкус экзотических плодов в игристом вине, лучи апреля, трепет юности — он весь в нём. Есть минуты, когда весь мир ощущается так: вкусно и остро.","259":"Перед сном герою приходят тени прошлого: старые друзья снова молоды, смех и песни оживают в памяти. Как свет далёкой звезды — красиво и больно, и сердце плачет о временах, которые не вернутся.","260":"Дикий ручей несётся с высоты, пенится и кувыркается в петле ущелья, и герой боится, что приручённый мир не оставит диких мест. Пусть останутся грязь и дикость — где их любит болото.","261":"Бессонный герой среди ночи читает список кораблей, что поднялся над Элладой, как журавлиный клин, и спрашивает: не будь Елены, зачем вам Троя? И слушать некому — чёрное море гудит у изголовья.","262":"Ночью маленькая смелая лодка везёт принца через море на Скай от погони: на островах рыдают жёны, волна молчит. Он уплыл навсегда — и лодка, прошедшая сквозь ночь, осталась жить в песне.","263":"Герой принимает себя целиком: тело и душа, свет и тьма — не делит себя на хорошее и плохое и потому способен вместить любые толпы. Трава и небо — его: кто уважает себя, уважает всех.","264":"Герой оплакивает отверженность и завидует чужой удаче — но мысль о любимой, как жаворонок на рассвете, взлетает от мрачной земли и поёт. Теперь он так богат, что не поменялся бы с королями.","265":"Герой с иронией следит, как под бременем часа телега катится по рытвинам и колеям: утром лениво под гору, в полдень ровно и трусливо, в ночь покорно. Остановится только у последнего ночлега.","266":"Герой-богомолец смотрит на родную землю: хаты в ризах образа, пахнет яблоком и мёдом, за околицей гудит пляс. Когда святая рать зовёт обменять отчизну на рай, он отказывается — родина дороже рая.","267":"Вечерами в соседнем доме горят жёлтые окна, и молот стучит в чёрные спины запертым лязгом. Стоящих у окон посчитали, согнули и назвали цену — все они пойдут и умрут. Окна молча глядят вслед.","268":"Наставник советует прятать чувства и мечты: пусть встают и заходят в душе безмолвно, как звёзды, — сказанное вслух искажает, наружный шум оглушает. В душе целый мир: умей в нём жить — и молчи.","269":"Мать поёт колыбельную младенцу при месяце ясном: вырастешь лихим казаком — пойдёшь воевать, а мама будет ждать тебя домой. Но сейчас пусть спит — пусть приснится речка и родная сторона.","270":"Одинокий герой, как облако, встречает у озера толпу нарциссов: тысячи голов качаются, цветы танцуют на ветру. Теперь в пустой задумчивости зрелище вспыхивает в душе — и сердце танцует с нарциссами.","271":"Ровный протяжный вечерний звон навевает герою юность и родное поле: он спрашивает, где дни, когда всё было радостным. Много воды утекло — туда, где звенел колокол, он уже не вернётся.","272":"На закате герой смотрит на сельское кладбище со скромными могилами: может, здесь спят те, кто бился за свободу или умел молчать. Учёности у них не было — но они были людьми. Величие не в имени.","273":"Герой вспоминает день первой встречи, когда солнце померкло от скорби: он покорился на глазах у Лауры и не защищался. Время будто остановилось и пошло заново — и плен любви ему по нраву.","274":"Пловец борется с лютым волнением нелюдимого моря: ветер бешено свистит, но он не дрогнул и держит курс на далёкий берег. Смелый не боится урагана — достигнет цели или утонет со славой.","275":"Герой спрашивает маленького ягнёнка: кто дал тебе жизнь, мягкую шерсть и нежный голос? Ответ тих: кроткий создатель сам назвал себя ягнёнком и стал ребёнком. Я — ребёнок, ты — ягнёнок: мы — Его имя.","276":"Любимая прощается тихо: их любовь не зависит от глаз и прикосновений — это золото, которое не рвётся, а тянется в тончайший воздух. Две души — как ножки циркуля: одна всегда возвращается к другой.","277":"Герой убеждает любимую: в мире всё сливается — фонтаны с рекой, волны обнимают друг друга, солнце целует землю. Только они двое разлучены, и это против самой природы.","278":"Певица Мигон вспоминает край, где растут мирт и лавр, и просит покровителя увезти её туда: горы светятся, дорога ведёт к дому, где её знают и любят. Дом — там, где её покой и любимый человек.","279":"Наставник даёт юному поэту три завета: жить только будущим, никому не сочувствовать, поклоняться одному искусству. Выполнивший всё падёт побеждённым и умрёт — лишь тогда постигнет поэта.","280":"Герой признаётся кроткой родине в любви за серые избы, печные трубы, поля и туманы — за печаль, а не за красоту. Он любит её больную, как сын любит мать: принимает всю — и дороги, и боль.","281":"Под тенью дерева журчит ручей: пастушка вяжет чулок, пастух играет на свирели, никто не спешит. День тянется как год, год как век — и счастье в том, что всё происходит вовремя.","282":"Змея пришла к колодцу героя и пила из его чаши. Голос требовал убить, но он был восхищён гостем, пришедшим первым, — и всё же бросил в неё бревно. Раскаяние: прости меня, я был плохим гостем.","283":"Путник едет через глухую степь с курганами и могилами: конь храпит, ямщик молчит, ветер воет, вдали воют волки. Скучно и одиноко ехать — но дорога всё лежит вперёд: терпение и тишина.","284":"Ослепший герой скорбит на середине пути: свет потрачен, талант умер во мне. Терпение возражает на вопрос, требует ли Бог дневного труда: даже тот, кто стоит и ждёт, — служит.","285":"Герой пишет имя любимой на берегу, волна стирает — снова пишет, снова стёрла. Она смеётся: смертному не сохранить смертное. Спор решает стих: имя будет жить в строке, и смерть покорится славе.","286":"Лунная ночь как поцелуй неба с землёй: ветер пробегает по полянам, колосья мягко качаются, лес шумит, звёзды мерцают. Душа героя, узнав дорогу, уплывает домой сквозь колосья и звёзды.","287":"У цыганского костра герой призывает сжечь сердце: две гитары, ни о чём не жалей — люби так, чтобы хрустнуло, играй так, чтобы плакали. Завтра не будет: сегодня — только костёр и гитары.","288":"Герой поднимает свой народ: отечество зовёт, клянемся не терпеть рабство ни на море, ни на суше. Лучше погибнет само имя мадьяра, чем останется в рабстве — такова их клятва.","289":"Герой мечтает о стране, где голова поднята высоко, знание свободно, слова идут из глубины истины, а ясный поток разума не утонул в мёртвых привычках. Пусть страна однажды проснётся такой.","290":"В тёмной роще герой качается на проклятых качелях: вверх — звёзды, вниз — болото. Страх падения против веселья на самом краю: держись и не смотри вниз. Кто кружит — тот и живёт.","291":"Гнев на друга сказал — прошёл; гнев на врага молчал — и тот рос, политый страхами и слезами, пока не вызрело блестящее яблоко. Враг увидел сияние и пришёл ночью — утром лежит под деревом мёртвый.","292":"Корабль рассказывает: команда погибла, он спускался по рекам безразличия без страхов и границ, видел небеса, расколотые молниями. Он уплыл в поэму моря — звёзды навсегда остались в его парусах.","293":"Юноша с лозунгом идёт через перевал: старик предостерегает, женщина зовёт греться в хижину, дух-дева сулит любовь. К утру нашли его мёртвым на снегу вершины — и голос с неба повторяет его лозунг.","294":"Рассказчица из-за черты слышит тишину после последнего вздоха — и жужжание мушки, которая заслоняет ей свет. Заплаканные глаза вытерлись, окно отказалось показывать: смерть прервана будничной мушкой.","295":"Диакон построил тележку так, чтобы ни одна часть не износилась раньше другой, — сто лет она ездила без ремонта. В столетний день оси, колёса и спицы развалились разом, без остатка: диакон был прав.","296":"Герой не хочет украшать дом множеством картин старинных мастеров — одна в углу: любимая, простая и святая, как Мадонна. Всё богатство — один образ, и он просит исполнить его последние ожидания.","297":"На севере одинокая сосна дремлет на голой вершине в снежной ризе. Ей снится пустыня на восходе солнца, где на горючем утёсе так же одиноко растёт прекрасная пальма: одиночество тянется к одиночеству.","298":"Певец славит греческие острова, где вечное лето и родился певец Аполлона, и спрашивает героев: где ваши марши и мечи? Слава ушла, но песня осталась — лира ещё зазвучит, и герои вернутся.","299":"Герой собирает то, что остаётся после ухода: дрожащая в памяти музыка, запах фиалок, листья розы на ложе любимой. И сама любовь остановится — уснуть в мысли о тебе.","300":"Герой обращается к яркой звезде: хотел бы быть столь же стойким — но не одиноко висеть в ночи. Его вечность — на груди любимой, в её нежном дыхании: жить так вечно или умереть вот так.","301":"Герой мечтает о диких ночах с любимой: пусть море бушует и ветер не может его расстроить — он в гавани, и сердце не пустует. Дикие ночи станут их роскошью: страсть нашла пристань.","302":"Умирающий прощается с берегом: пусть отплытие будет тихим, без стонов, — прилив высок и уносит за мель, в безграничное. Он просит не грустить о часе отлива: верит, что взглянет в лицо своему кормчему.","303":"Когда зацвела сирень и большая звезда рано упала с неба, герой оплакал любимого капитана и нёс цветущий куст на его гроб. Сирень расцветает каждую весну — и каждая вспоминает ему упавшую звезду.","304":"Герой бросает вызов смерти: страх — это туман в лицо, пусть буря гремит, он дерётся. Он дважды жил — второй раз ради любимой, и за туманом чувствует её руки и глаза: их ждёт встреча.","305":"Герой обращается к старости любимой: когда у огня возьмёшь книгу, вспомни — многие любили твою красоту, но один любил душу и печали стареющего лица. Он вздохнёт: любовь ушла и блуждает над звёздами.","306":"В день праздника народ молится Богу отцов под знамёнами: далёкие флоты растаяли, владыки капиталов и войн уходят один за другим. Остаётся трезвая молитва: оставь нам твоё смирение и память о себе.","307":"Арфа, звучавшая в залах Тары в славные дни свободы, теперь висит молча в забытом чертоге — как душа и как свобода, которую забыли. Слава умолкает, но сердце помнит её звучание.","308":"Морж и плотник приглашают устриц на прогулку и сладко болтают об обуви, кораблях, капусте и королях — пока одна за другой устрицы не исчезают у них за ужином. Морж благодарит за вкусную беседу.","309":"Гимн морякам Англии: гремят орудия, флаг гордо взвивается в час победы, корабли из английского дуба несут стальные сердца матросов. Пока под килем живая волна, морская слава вечна.","310":"Певец на пиру воинов поднимает круговую чашу: друзья, вы живы — пейте! Но тихо напоминает, что время придёт и для них: павшие ждут. Воины пьют и молчат о будущем.","311":"Табачный дым вычесал воздух, комната кружится кренделями — но герой кричит ей: всё равно люблю. Дождь не высушил ничего, кроме сердца. Если ей мучительно и она уйдёт — он всё равно крикнет о любви.","312":"Природа — храм, где живые колонны выдают смутные слова, и человек проходит лес символов. Запахи свежие, как детская кожа, сладкие, как гобой, зелёные, как луга: запах отвечает цвету, цвет — звуку.","313":"Отвергнутый герой жалуется: он дарил любимой алмазы и кольца, а она была безжалостна. Он всё же верит — однажды она полюбит и вспомнит его.","314":"Мать провожает сына Дэнни: трубы зовут его через ущелье, лето ушло, цветы умирают — он должен уйти, она остаётся. Но она будет ждать его и в жару, и в стужу: дом ждёт всегда.","315":"Атаману мало спалось, и приснилось: вороной конь разыгрался, расплясался и разрезал ему грудь. Проснувшись, атаман понял — сон пророческий. Судьба предупреждена, но бой неминуем.","316":"Беглый каторжник вышел к священному Байкалу и узнаёт родные края за волнами: поплыву — и увидюсь с матерью. Мороз и туман не пугают, путь короток — даже море можно переплыть ради дома.","317":"Осуждённый прощается с другом на берегах Лох-Ломонда: ты пойдёшь низкой дорогой домой, я — высокой, и обгоню тебя. Погибший придёт в родные края раньше живого, а любовь навсегда останется здесь.","318":"Герой вдали тоскует по голосу реки Шенандоа и по её дочери, которую любит, но плавучие реки уносят его прочь, в чужие края. Любовь остаётся на берегу, а он плывёт навсегда.","319":"Весёлый герой идёт с банджо на колене из Алабамы в Луизиану к настоящей любви: весь день лил дождь, но песни делают дорогу праздником. Он просит Сюзанну не грустить — банджо уже поёт.","320":"Спасённый герой исповедуется: дивная благодать нашла его потерянным и слепым — теперь видит, и страх, которому благодать учила сердце, исчез. Через опасности, труды и ловушки она приведёт его домой.","321":"Скитаясь даже весело среди пышных дворцов, герой тоскует по своей хижине с голубями и пчёлами у окон, где он гулял ребёнком. Ни дворцы, ни веселье не заменят простой родной хижины.","322":"Герой вспоминает свидание в ясеневой роще: глаза любимой светились, улыбка была как рассвет. Теперь роща шумит — и в её шелесте он слышит её голос: прошлое возвращается на мгновение.","323":"Герой утешает обманутого жизнью: не печалься, не сердись — в день уныния смирись, день веселья настанет. Всё скоротечно: уныние пройдёт, и пройденное станет милым.","324":"Голубой пожар заметался, позабылись родимые дали: герой впервые говорит о любви. Был как запущенный сад, шутом и наслаждением, — но готов отречься от прежнего себя, лишь бы она не видела его старым.","325":"Герой одинок — некому руку подать: желанья напрасны, лучшие годы проходят, страсти иссякнут при слове рассудка. Жизнь — пустая глупая шутка, а время выбирает лучших — и губит их.","326":"Герой встречает давнюю знакомую — и всё былое оживает в отжившем сердце: время золотое обнимает его, как весна. Как в поздней осени вдруг вспыхивает мартовское тепло — так веет жизни юной силой.","327":"Герой стоит в майской ночи: молодые листья ещё не заслоняют звёзд, и чем темнее вокруг, тем ярче небо. Так и жизнь: чем старше человек, тем яснее видны его звёзды.","328":"Дорогу через лес закрыли — дождь и ветер стёрли её, осталась тропинка, которую помнят кони. Но в летнем вечере ещё слышны шаги идущих: дороги исчезают, а шаги по ним слышны до сих пор.","329":"Герой вспоминает расставание в тишине и слезах: она забыла клятву, он помнит её, и имя любимой гремит колоколом, сжимая сердце. Если встретятся спустя годы — он встретит её тишиною и слезами.","330":"Герой ждёт любимую: алый лепесток и лилия уснули, вечер слился с тишиной, поднимается сияющая звезда. Пусть сойдёт из своих небес — его душа, как та звезда, молча сойдёт к ней сквозь снег.","331":"Тихий паук на крошечном уступе бросает нити в бесконечное пространство, чтобы когда-нибудь что-то соединить. Так и одинокая душа героя бросает свои нити в пустоту — и мост когда-нибудь соединится.","332":"Мать укачивает ребёнка: сладкие сны складывают улыбку на его лице, сонные вздохи и тайные слёзы истекают — она тайно целует плачущее лицо. Улыбка малыша — тайна любви, у колыбели стоит ангел.","333":"Юноша любит девушку, которая выбрала другого; тот любит другую — и она выходит замуж за юношу от скуки. Старая история: единственный счастливый тот, кто не любит, — а тот, кто любит, платит крестом.","334":"Поэт боится умереть, пока перо не выжало всего богатства — книг, что станут звёздами на небе мыслей. Он смотрит на лицо любимой и понимает: не успею. Тогда слава и любовь обесценились до ничтожества.","335":"Старик карабкался на последние ступени мира: друзья ушли, как летние гости, — ни радости, ни дружбы, ни любви не осталось. Он стоит на последних ступенях с одним вопросом: где всё, что было.","336":"Герой на мосту встречает утренний Лондон: город, одетый в красоту, молчит — корабли, башни и купола блестят в бездымном воздухе, река течёт по своей воле. В тишине дремлют даже самые могучие сердца.","337":"Герой зовёт любимую в страну, похожую на неё: солнечные туманные города, влажный блеск, везде порядок и красота. Там можно любить не спеша, любить и умереть — в достатке, тишине и радости жизни.","338":"Герой приносит любимой скромный дар: фрукты — чтобы укусить, цветы — чтобы нюхать, листья — чтобы писать. А сердце, которое бьёт только для неё, пусть останется целым: оно самое хрупкое.","339":"Герой предостерегает возлюбленную: в её глазах растёт священное дерево, листья полны печальных напевов, а в зеркале — дерево разрушения, где всё сломано. Пусть выбирает глаза, а не зеркало.","340":"Герой перечисляет прекрасное — влюблённое вино, хлеб, любимая женщина — и спрашивает, зачем ему грудь и рука. Есть шестое чувство: оно бьётся, как зверь в неволе, и ждёт того, кто его освободит.","341":"Герой уверяет, что тоска по родине давно разоблачена: ему всё равно, где быть одиноким. Но на дороге вдруг встаёт куст рябины — и вся уверенность рассыпается: родина позвала, и он вернётся.","342":"Герой возвращается в город, знакомый до слёз, до желёз, и глотает рыбий жир речных фонарей. Он ещё не хочет умирать: в городе есть адреса, где его ждут мертвецы. Живой звук бьёт в ухо: готов ко всему.","343":"Герой видит сокола в утреннем свете: он правит крылом, как конь ходит в волне воздуха, и внутри него пылает укрытый жар. Изумление сменяет восхищение: красота — в движении.","344":"Роза больна: невидимый червь летал ночью в воющей буре и нашёл её постель алой радости. Его тёмная тайная нежность изнутри точит цветок — незаметно и неотвратимо.","345":"Герой сжимает горсть золотого песка среди рёва прибоя: крупицы выскальзывают сквозь пальцы, и он плачет — неужели нельзя удержать ни одной? Вся жизнь вокруг — сон, который снится внутри другого сна.","346":"Герой просит землю быть лёгкой к умершей сестре: пусть тонкий снег ляжет на неё и травы не тронут волосы. Она бледна, как лилия, с нежным голосом и чистым сердцем — вся красота мира потеряла её.","347":"Герой мчится на коне сквозь ночь и туман к любимой: у окна горит свет, встреча — как весна. Но рассвет разлучает их, и он клянётся вернуться: душа остаётся с ней всегда.","348":"Расписные ладьи идут по Волге: атаман Разин держит княжну в руках, но дружина требует — волна слышит только атамана. Он бросает её в волны, и лодки идут дальше: свобода дороже любви — цена вольницы.","349":"Волна гонит следующую к берегу — минуты сменяются: человек взлетает к зениту славы, потом время выкапывает борозды на его лбу. Красота беззащитна — герой верит, что его стих устоит, пока люди дышат.","350":"Осень жизни героя: на голых ветвях, где пели птицы, дрожит последний жёлтый лист, и за этим вечером придёт тёмная смерть. Возлюбленная видит это — и любит его тем крепче, что скоро придётся оставить.","351":"Умирающий просит любимую не оплакивать его дольше колокольного звона: мир жесток, она ещё вздохнёт, и память о нём лишь подгонит вздохи. Он просит отпустить его имя — чтобы она жила без вины.","352":"Герой считает часы, пока меркнет день: фиалки умирают, чёрные локоны седеют, летние клумбы опустели. Красота беззащитна — только потомство стихов может противостоять времени, отдав его на суд.","353":"Герой — раб часовой службы любимой: ждёт, когда она пожелает, не смея жаловаться на горечь ожидания. Первый упрёк сказан: жалок тот, кто не смеет показать, как гнетёт его рабство.","354":"Герой противопоставляет чужие гордости свою: одни хвалят родом, другие умом, третьи конями и соколами, — а у него есть только она. Любовь дороже родства, ума и соколов вместе, и забирает его целиком.","355":"Герой перечисляет беды: нищета в богатом костюме, доброта за решёткой, власть пирует, правда объявлена глупостью. Он так устал, что хотел бы умереть, — но остаётся ради любимой, единственной правды.","356":"Герой следит за солнцем славы: с востока идёт прекрасный свет, восход юности встречают приветствиями. На закате толпа кривит глаза и смотрит без уважения — слава уходит так же, как пришла.","357":"Разлука с любимой — зима: то, что прежде несло плоды, качает голые ветви, и герой смотрит на своё лето издалека. Даже в разгар июня на всё ложатся зимние тени — она есть всё тёмное в его календаре.","358":"Герой встречает друга и не находит в его лице ни часа времени: юность держится в пяти зимах, ведь годы прячутся во взгляде, а не в морщинах. Он просит друга не стареть, пока сердце отстаёт от цифр.","359":"Двадцатилетнему герою осталось шестьдесят весен. Он видит вишню, цветущую ветвями вдоль по снегу, и решает не откладывать: идёт в лес смотреть цветение, пока есть чем дышать.","360":"В двадцать один герой не стал слушать мудреца: отдавай драгоценности за перья, но сердце не отдавай никому. Теперь он знает цену: сердце отдано слишком рано, и вздохи с болью — расплата.","361":"Изгнанник слышит воздух родной страны — голубые горы, золотые фермы, шум ручьёв, — но окна и дороги туда больше нет. Счастливые дни остались на той стороне, и он никогда их не увидит.","362":"Погибший парень из могилы спрашивает друга: вспашут ли поле, где он лежал, забьют ли мяч, как раньше. Друг отвечает: всё продолжается — только мёртвому это уже не нужно.","363":"Он вспоминает поле, где они тайно целовались среди сухих папоротников. Теперь листы падают так же, но её шагов рядом нет — осень продолжается, только уже не для двоих.","364":"В голове героя идут собственные похороны: скорбящие топают, барабаны бьют всё тише, а рассудок сидит в тишине. Люди поднимают ящик, мир зазвонил колоколом — и доска с его знанием разбивается.","365":"Побеждённый умирает на чужом берегу, а победный крик доносится до него громче, чем до сегодняшних победителей с флагом в руках. Сладость успеха известна только тому, кто сам его так и не достиг.","366":"Мальчик кланялся тонкому серому соседу в траве — змее, что выстреливает из-под ноги. Но однажды, когда он потянулся к траве, рядом никого не было: в ветре билась кость, и ботинки заскользили.","367":"После большого горя герой живёт механически: ноги как камни, вопрос и любовь — деревянные. Всё собранное в углу снова станет каменным — так снег в конце дня отдаёт себя дыханию.","368":"Родитель учит детей правде, как смотрят на солнце: не в упор, а через слабое сияние и косой свет. Истина приходит к людям наклонно — яркая молния не объясняет, а ослепляет глаз.","369":"Влюблённый ругает рассвет: дворники вышли, школьники проснулись, а солнце разбудило любимую. Он требует время назад — пусть мир живёт по её расписанию: любовь делает день королями.","370":"Он просыпается рядом с любимой и понимает: все прежние удовольствия были призраками. Мир может замереть: впервые открылась настоящая любовь, где разница между ними — не смерть, а свет.","371":"Герой бросает вызов смерти: не гордись — ты раб судьбы, королей и отчаянных людей, а взятых тобой не свергла. После короткого сна ждёт вечное пробуждение — а она кончится, как сон.","372":"Друг оплакивает молодого пастуха, утонувшего в день, когда за ним шли музы: та же вода несёт чужие яхты, но забрала певца, плывшего тянуть за руку тонущего. Его песня теперь допевается за него.","373":"Влюблённый мягко уговаривает любимую: время бежит, врать о завтра не стоит. Вечер уже здесь, но тем красивее сад, что готов к зиме, — он берёт её ладонь в свою, пока время ещё пишет на песке.","374":"В пустыне растёт один анчар — дерево смерти, чей яд по каплям стекает в почву. Владыка посылает раба за смолой, и тот умирает у порога. Природа запретила свой яд — человек раздаёт его людям сам.","375":"Корабль с хором пловцов-певцов шёл по роще волн, пока буря не забрала всех: лишь одного выбросило на берег. Спасённый поёт гимн тайне, которая его вынесла, — один голос вместо целого хора.","376":"Ямщик потерял дорогу в метельной ночи: поле бесконечное, луна безмолвна, конь выдохся. Вихрь крутит его по кругу, ветер кричит то ли бесами, то ли вороньём, — силы заставляют ехать в никуда.","377":"Он признаётся: любовь ещё не совсем угасла, но он не позволит себе тревожить любимую. Он желает ей полюбить другого так же искренно, без права на ответ, как умел любить только лучший друг в мире.","378":"Мелкий чиновник после наводнения шепчет медному императору угрозу — и бежит в панике: ему чудится, что бронзовый исполин пустился следом по ночным улицам. Пустой остров не помнит, где он лежит.","379":"Старый цыган говорит: жена ушла к другому, и он не стал мстить — любовь без свободы мертва. Герой не может так: под луной он режет любовника своей жены, и табор уходит, оставляя его одного.","380":"Юноша, выросший в монастыре, сбегает в грозу и живёт три дня: поле, грузинка у ручья, бой с барсом. Умирая, он просит похоронить его там, где слышен ветер, — три дня свободы были дольше всей жизни.","381":"Поэт прощается со страной рабов и господ, с голубыми мундирами и доносчиками. Он прячет себя в горах Кавказа, откуда ни шпионы, ни обида не достанут его чувство, — и уходит туда, не оглядываясь.","382":"Офицер пишет любимой письмо с войны: бой у речки Валерик, двадцать шесть погибших с тупым укором в глазах. В конце — признание: я вам больше не любим, но счастье было так возможно.","383":"Три пальмы в пустыне ропщут на бога: зачем цвести, если всё вокруг мёртво? Бог отвечает караваном: путники срубают стволы для костра, и к утру от пальм остаются лишь пепел и тень на песке.","384":"Казбек и Эльбрус спорят, кому владычить: один гордится вечными снегами, другой — дорогой через свой склон. Горы перерекаются, а внизу живут и умирают люди, которым нет дела до их гордости.","385":"Дама бросает перчатку в клетку к леопардам: кто поднимет — получит её любовь. Рыцарь спускается меж зверей, поднимает перчатку — и возвращает ей в лицо: он не примет любви ценой чужой жизни.","386":"Светлана ночью гадает у зеркала, и ночной гость увозит её метелью к избушке, где из гроба встаёт жених-мертвец. Но под утро она просыпается дома: жених живой, страшная ночь была лишь сном.","387":"Ягнёнок пьёт, а волк кричит, что тот мутит воду, — ягнёнок отвечает: вода течёт от него вниз. Волк выдумывает вины, пока виноватым не объявится само желание пить, и ягнёнка съедают без суда.","388":"Когда в товарищах согласья нет, на лад их дело не пойдёт: лебедь рвётся в облака, рак пятится назад, щука тянет в воду. Трое взялись за один воз без плана — и воз до сих пор стоит на месте.","389":"Старая мартышка купила пять очков и вертит их: на хвост, на нос, на лоб — зрение не проясняется. Она объявляет, что люди её обманули, и бьёт стёкла о камень, не спросив, как держать вещь.","390":"Демьян сажает соседа Фоку за стол и подставляет третью миску ухи: ешь ещё, тебе же легко. Фока бросается домой, а хозяин кричит вдогонку, что гость его не уважил. Забота силой тяжелее её отсутствия.","391":"Вдовец остался с младенцем, но зима забирает дочь, потом и его самого. Мороз-воевода красуется над голой деревней — и вдова выходит в поле лицом к лицу со стужей: не пугай ты меня, я всё перенесла.","392":"К парадному подъезду приходят крестьяне за защитой, но швейцар не пускает просителей. Поэт кричит вслед: не ходите к окнам сильных — зовите героя, который не боится заступиться перед вельможей.","393":"Герой смотрит на фонтан, чья струя рвётся в небо и падает о пыль, — и узнаёт свою мысль: она бьёт вверх, к божественному, но камень закона не пускает её, и она возвращается в свой канал.","394":"Последняя любовь встречает закат: тёплая ночь, лунная тень, угасание. Он не скорбит — он просит душу помочь телу и перед самым концом загореться дважды, ярче, чем когда-либо.","395":"Он приходит к любимой с утренним приветом: солнце светит, вся зелень сияет, и все северные берёзы смотрят в её окно. Весь лес шепчет — и он хочет, чтобы и его душа звенела и сияла этим же утром.","396":"В лунном саду она пела о любви и дальней стороне, и в голосе её были слёзы первой нежности, которую он забыл. Взгляд в ту ночь изменил всю его жизнь — он до сих пор помнит её песню и печаль.","397":"Ночь революции: двенадцать красногвардейцев идут и стреляют, позади остаются поп, барыня и буржуй. Впереди колонны в белизне шагает фигура с венком из роз — но они не видят, кто ведёт их.","398":"Поэт возвращается в деревню юности и встречает первую любовь — Анну, но между ними война и разлука. Годы спустя она пишет ему с чужого берега: муж убит, а она всё ещё помнит того мальчика.","399":"Уставший путник добирается до постели, но тело просит сна, а голова снова выходит в путь: мысли шаг за шагом проходят ночное расстояние до любимой и стучатся к ней. Во тьме её лицо видно яснее всего.","400":"Любимый снова не пришёл — как солнце, за которым встало облако. Она не плачет и не называет это изменой: ушедшее за тучу солнце так же горячо, и утро вернётся прежним, как только облако пройдёт.","401":"Глаз и сердце героя никак не поделят любимую: каждый говорит — она для меня. Они зовут свидетелем мысль и идут на суд: делить нечего — глаз получает её образ, сердце — её любовь.","402":"Поэт обещает любимой: ни царские памятники, ни каменные гробницы не переживут этих строк. Время выметет всё мечом, но каждое новое чтение вернёт её имя — и внуки внуков найдут её жизнь в песне.","403":"Он — раб своей любви и не просит свободы: пусть бог запретит ему упрекать любимую за опоздания. Он готов ждать любые часы, не спрашивая, где она была, — ожидание стало его правдой и его страданием.","404":"Он отпускает любимую: она слишком дорога, чтобы называть её своей, — сам дар любви оказался кредитом, который пора вернуть. Он подписывает прощание, но во сне всё ещё слышит звон.","405":"Он видит, как любимая поднимется на ту ступень, где он поседеет, и берётся за перо: написанные слова останутся зелёными, когда их волосы станут белыми. Так песня встаёт между любовью и старостью.","406":"Поэт пишет завещание накануне смерти: тело — земле, где ей будет лучше, дух оставляет себе, а любимой — строки. Он просит не хоронить жизнь целиком: частица его будет возвращаться в каждом чтении.","407":"Их любовь уже не кричит, как в первые дни: она умолкла, чтобы не звучать дёшево, и стала слышнее в тишине. Он больше не говорит слов — молчание стало их самым громким признанием.","408":"Он отменяет предсказания: смерть, которой пугали его любовь, оказалась ложью — небесные сферы молчат, луна не дала знака. Его строка теперь сама закон: они с любимой переживут и смерть, и забвение.","409":"Скиталец умоляет не говорить, что сердце его изменило: она — его дом и вселенная, покинуть её — значит покинуть себя. Даже вдали он носил её образ, как капля воды носит океан, — теперь он дома.","410":"Он прощает любимую её вину, потому что сам однажды обидел её и знает цену боли. Пусть их вины гасят друг друга, как два огня, — он шлёт слёзы прощения и получает слёзы в ответ.","411":"Пожилая пара врёт красиво: она клянётся, что он всё ещё молод, а он делает вид, что верит. Каждый знает правду, и обоим это удобно — лучший день их любви тот, где враньё мило обоим.","412":"Хозяйка бежит по двору за курицей и не слышит плачущего у порога ребёнка. Муж смотрит с завистью и просит поймать его когда-нибудь так же, как ту птицу, — а пока его сердце плачет, как младенец.","413":"Его любовь — болезнь, и разум-врач бессилен: рецепт не признаёт ни одного лекарства. Он брошен, но всё ещё хочет её и знает: это безумие — его приговор, от которого не выписывают.","414":"Он укоряет свою душу за заботу о теле: зачем кормить стены, теряя внутренний дом? Пусть тленная связь износится — он готов обменять всё богатство на вечное, выкупив время, пока оно ещё продаётся.","415":"Человек на перепутье спрашивает себя: что благороднее — терпеть удары судьбы молча или подняться против моря бед? Мы терпим знакомое зло, потому что боимся неведомого.","416":"Узнав о смерти жены, он говорит как наизусть: дни ползут малыми шагами изо дня в день, все вчерашние светили глупцам дорогу в могилу. Он тушит свечу: жизнь — рассказ, где слова не значат ничего.","417":"Перед страшным делом ему мерещится клинок, нацеленный рукоятью в его руку, — образ ума, который зовёт идти. Земля дремлет, ведьмы служат своей госпоже — и он делает шаг, о котором звенит тишина.","418":"Король стоит у пролома и поднимает своих: ещё раз, друзья, или заткнём рвы нашими мёртвыми. Он учит их перенимать у псов ярость и обещает стыд без шрама в праздник — малое братство войдёт в легенду.","419":"Кассий будит самоуважение друга: мы смирились до возраста, Брут, и в этом вся наша слабость. Чем этот Цезарь величавее тебя самого? Дерзкий вопрос двух друзей меняет судьбу Рима.","420":"Человек, которого учили быть чужим, говорит купцам: разве я не глаза, не руки, не чувства? Меня тем же мечом ранят и тем же лечат — а если обидите, не отомстим ли? Так презрение оборачивается силой.","421":"Волшебник прощается со своим театром: башни тают, палаты исчезают, великий шар отыгран и не оставляет опоры. Человек соткан, как сон, — духи уже сняли декорации, и вечер здесь прощается.","422":"Свергнутый полководец собирает войско у огненного озера: трон во тьме лучше службы в раю, ведь здесь у него свободная воля. Кому служить, он решает сам — и объявляет тьму своей страной.","423":"Змей находит Еву у единственного запретного дерева и превращает запрет в лестницу: он обещает ей стать богиней. Рука, которая сама этого захотела, срывает плод — и знание она подарит поцелуем.","424":"Изгнанные из сада поднимаются на холм: дверь закрыта, перед ней стоит ангел. Они вытирают слёзы и берутся за руки — сада больше нет, но есть они сами, и их дорога теперь одна на двоих.","425":"Войско врага бьёт защитников по одному в день, и юный воин выходит к броду один: если он упадёт, за спиной — дом, стада и весь народ. Он держит брод один, и этот день станет легендой.","426":"Дейрдре возвращается с телом убитого любимого: король-убийца ждёт её под своей крышей. Она оглядывается на свободные горы, обещает вернуться камнем и садится в колесницу — идти больше некуда.","427":"Старый моряк вспоминает зимние гребли в ледяной воде, когда волны били его о скалы. Но в тёплые залы он не вернётся: страна на горизонте — вечность, и он отпускает землю, не думая о золоте.","428":"Раненый Гуннар оглядывается на родной склон — поля, луга, река так красивы, что он не поедет за море. Он возвращается в дом, где ждут враги, и принимает последний бой: земля держит сильнее страха.","429":"Вечером нянька зовёт детей с луга домой: солнце село, пора в укрытие. Дети кричат, что будут играть, пока есть свет, — и, послушав их смех громче ветра, она улыбается и разрешает ещё поиграть.","430":"Мать стонет, отец плачет, а новорождённый выскользнул в мир кричащим. Его запелёнают, как паутинкой, — он дёргает руками, прыщает с рук в тень и сердито лежит: первый бунт объявлен пелёнкам.","431":"Взрослый возвращается к саду детства и видит часовню там, где был зелёный луг: ворота закрыты, над дверью запрет, гробницы вместо грядок, священники в чёрном. Цветы и радость заросли сорняками.","432":"Летним днём он случайно задевает муху и думает: мы с ней одно. Она живёт без мысли о смерти, а он думает — и потому живёт ярче. Пусть танцует и пьёт каждый день, пока весёлая рука не ослепла.","433":"Мать сажает сына под дубом и объясняет: мы рождены под жарким солнцем и вынесли его жар, — ангелы радуются, что мальчик выжил в зное. Он терпеливо ждёт дня, когда любовь снимет тень с земли.","434":"Дева Тэль расспрашивает лилию, облако и червя, зачем жить, если всему конец. Цветок отвечает, что даже мимолётная жизнь напоена любовью, — но она плачет, боится и бежит, не решившись жить.","435":"Природа обещала вырастить девочку госпожой долин: три года она росла вольной, как газель, тихой красотой леса. Но укрытие опоздало, и Люси не стало — остался камень у тропы и тишина в долине.","436":"Он спал духом и не чувствовал тревоги: она казалась ему чем-то, чего не коснутся годы. Теперь она неподвижна, и он понимает: она срослась с вращением земли, её слух и зрение отошли камням.","437":"Когда-то луга и ручьи были ему райской одеждой, земля сияла славой и свежестью сна. Теперь он знает: дети слышат разговор земли, а взрослые теряют его, — но след света ещё мелькает в обычной траве.","438":"Мальчик крадёт лодку и ночью гордо гребёт по озеру, пока впереди не встаёт огромная гора — чёрная, в воде, тёмной как сон. Он бросает лодку и бежит домой, а те же образы приходят к нему и после.","439":"Кристабель выходит за стены замка помолиться и в роще находит незнакомку, просящую защиты. Она приводит гостью в дом, но молитва матери не отводит зло: та спит в замке, и никто не знает её правды.","440":"Он смотрит на ночное небо, где старая луна держит юную в лапках, но не чувствует надвигающейся грозы. Красоту он видит, а звука не слышит, как глядящий на сон, — и шлёт песню той, чей голос вернётся.","441":"Зимней ночью у камина спит его ребёнок, и отец мечтает, чтобы вырос он среди горных озёр, где вечный язык природы растит мудрую душу. Пока малыш спит, отец благодарен за тишину и огонь в очаге.","442":"Юноша смотрит с палубы на отдаляющийся берег: парус наполняется ветром, рядом наёмные моряки, а на земле кучка друзей. Он будет странником вдали, но сердце оставит здесь — свобода стала его страной.","443":"Горный дух зовёт Манфреда забыться в небесных водах, но он отказывается: он умрёт на своей вершине, как жил. Он не раб ни духам, ни смерти, ни искуплению — и умирает, не отдав свою душу никому.","444":"Корабль уходит под воду, остаток команды садится в шлюпку: хлеб кончился, вода — тоже, а море просто ждёт. Один моряк держится живым и выталкивается на берег один — как глоток воздуха в шторме.","445":"Дочь пирата находит выброшенного морем чужестранца: они не знают языка друг друга, но любовь пришла сама, и островок — целая вселенная. Отец возвращается с грузом рабов — счастье кончается барабаном.","446":"Прикованный к скале отказывается от войны: месть — та же цепь, и он помнит слова любви, сказанные в день, когда держал боль молча. Цепи сходят сами, как тень, — мир начинается заново, без тиранов.","447":"Друзья идут оплакивать молодого поэта: скорби поднимаются, озеро слышит, а сонное море не отвечает. Но он растворился в вечном огне, из которого сделаны звёзды, — его имя завещано вечности.","448":"Путник идёт через ущелье, где река выла, как зверь, и выходит к горе выше облаков. Никто не говорит за неё: человек приходит и уходит, а ледяные вершины живут вне времени — он уносит образ вечности.","449":"Птица несётся с земли в небо, как облако огня, и поёт о том, чего поэт не знал, — он не находит сравнения. Он просит научить его мыслить так, чтобы люди слушали его строки, как её песню в сумерках.","450":"Старый Сатурн сидит в молчании среди камней: его трон заняли другие боги, и Теа плачет рядом. Он просит не говорить вслух того, что оба знают: величие нельзя ни забыть, ни вернуть.","451":"Она любит юношу и прячет тайну своего происхождения, свадьба уже идёт — но старый мудрец приходит и смотрит ей в глаза. Тайна рушится: она исчезает на глазах у всех, и любовь остаётся без правды.","452":"Братья считают слугу недостойным невесты и убивают его в лесу. Изабелла приносит домой горшок с базиликом и ухаживает за ним, пока братья не крадут его, — и она засыхает от горя вместе с цветком.","453":"Пастух видит во сне богиню и больше не может любить земных девушек: он идёт под землю, через восторг и бездну. В финале он узнаёт — богиня его снов и та простая девушка, что ждала рядом, одна любовь.","454":"Старый царь ночью идёт в стан врага за телом сына: он целует руки убийцы, и оба плачут — один о сыне, другой об отце. Враг отдаёт тело и обещает покой: горе нашло общий язык там, где нет его у войн.","455":"Он и его люди заперты в пещере чудовища, съедающего двоих за ночь. Он напаивает гиганта вином и прячет имя за словом «никто»: соседи не приходят на крик, и он выводит людей под шкурами баранов.","456":"Птицеголовые девы поют так сладко, что моряки сворачивают с пути и гибнут. Он закрывает уши людям воском, себя велит привязать к мачте — и единственный выслушивает её и выживает.","457":"Он сидит рядом с ней и слушает её речь, а я смотрю издалека и не могу дышать: голос — шелест цветов, огонь бежит под кожей, уши гудят. Я ближе к смерти, чем сама жизнь: чужое счастье меня сжигает.","458":"Боги создали первую женщину как подарок-ловушку: каждый дал ей свой дар — красоту и хитрость. Она приподняла крышку кувшина, и зло разлетелось по земле — под крышкой осталась одна надежда.","459":"Элейн полюбила рыцаря с её алым рукавом, а когда он уехал, перестала есть и попросила положить её в лодку с письмом. Лодку понесло к чужому замку, где рыцарь читает её письмо — но её уже не вернуть.","460":"Королева, чей мир пал из-за её любви, прячется в монастырь: корона легла на землю, а она падает к ногам короля — нищая, недостойная. Он прощает её и уходит, и покаяние заменяют ей королевство.","461":"Он просит колокол вылететь в ночь: пусть уйдут ложь, распри и война, а новое время придёт, как волны на берег, — с памятью о тех, кого он любит и кто ушёл. Он провожает год и друга.","462":"Он любит соседку и слышит её голос в саду, как звон, — но деньги её семьи и статус кричат против него. Рассудок мечется между любовью и злобой — и он готовится переступить забор из собственных мыслей.","463":"Хозяин открывает занавес с портретом покойной жены: она улыбалась не только ему, и он приказал остановить улыбку. Теперь она живёт в раме, а он собирает новую свадьбу и отдаёт приказы всему миру.","464":"Она приходит к нему сквозь бурю: разводит огонь, кладёт голову ему на плечо. Он думает, как сделать вечер вечным, — и решает не отпускать её домой: она останется с ним, какой была в этот вечер.","465":"Художник, у которого всё получается, говорит с женой в сумерках: её прихоти съели деньги, а его безошибочность не оставила душе места в картинах. Он смотрит на чужие ошибки и просит её остаться.","466":"Епископ умирает и командует племянникам дизайн собственной гробницы: камень с яшмой, фигурки святых — и величавее, чем у соседа. Он не думает о душе — смерть становится предметом торга за престиж.","467":"Он стоит с любимой у окна и слушает гальку, которую волны возвращают ночью: в море он слышит ноту грусти. Мир красив, но в нём нет радости — он просит её быть верной: их любовь останется берегом.","468":"Философ живёт на вулкане: людям не слышно его, а боги не отвечают. Спуститься — значит жить как все и умереть как все, и он решает закончить разговор сам: шаг к жерлу — последний аргумент.","469":"В саду Прозерпины нет солнца и слёз: все плачущие складывают боль у подножия цветов. Он просит о тихом поле, где призраки дышат спокойно, — ни вины, ни награды, только отдых, где легче спать.","470":"Он прощается с той, кого любил до того, как узнал мир: время переехало их историю, как поезд через поле, и встреча не вернёт былого. Он благодарит и просит забыть его имя — в сердце две пустые двери.","471":"Дева у небесной решётки смотрит вниз с тремя лилиями в руке и просит Бога пустить к ней любимого. Её слова падают вниз, как птицы, — а он на земле слышит их как голос ветра и не знает, чей это зов.","472":"Он идёт с опущенной головой сквозь ветер и садится в траве: глаза открыты, но видят только неё. Когда ветер стихает, в памяти остаётся одна деталь — три чашечки травы, больше он ничего не помнит.","473":"Он стоит на опушке, где зимние кусты — призраки, и весь пейзаж поёт прощание веку. Люди ушли в дома, а дрозд вылетает на тёмный склон и поёт радостную песню — так, будто знает то, чего не знает он.","474":"Пока на верфи поднимают зеркальные стёкла, в холодной глубине растёт айсберг — единая пара кораблю. Их ведёт сила, которой всё равно, кому жить, и человек узнаёт, кто ждал его в тёмной воде.","475":"Они рисовали дом с кухней, свечами, чаем и песнями, смеялись над мелкими бедами. Десятилетия спустя во дворе не слышно смеха, ветер гуляет по садам — только каменные вазы помнят, как дом звал гостей.","476":"Мёртвая спрашивает, кто копает её могилу: муж, враг, сосед? Все отвечают, что не они — у каждого своя жизнь. Из-под земли выглядывает щенок: он копает кости, чтобы лечь на них, и ей становится тепло.","477":"Город носил его на плечах, когда он выиграл забег, — теперь несёт к могиле. Он ушёл на пике: рекорд останется его, старость стёрла бы имя. Он остался в памяти победителем навсегда.","478":"Они лежали в траве, и она говорила, что колокола на холме звонят для их свадьбы. Зимой они поженились, а после снегопада её не стало: зимний звон звучит прощанием, и он лежит на их холме, не вставая.","479":"Пьяному философу бросают: твои стихи — солод и хмель, а жить как ты — пьянство. Он отвечает, что злая правда нуждается в приправе, и рассказывает о мальчике, умершем от горькой истории: легче станет.","480":"Он прощается с домом — амбар, стог, дерево могут остаться: он убил отца и просит брата увести коня, пока не пришёл закон. Сам он уходит туда, где живут те, кто не вернётся.","481":"Солдат помнит водоноса, что таскал воду на жаре и вытаскивал раненых из-под пуль до собственной гибели. Он признаёт: водонос был лучше любого из них, и он надеется встретить его среди павших.","482":"Солдат идёт в бесконечном строю: счёт миль потерян, нет ни спешки, ни покоя — только шаг. Кто так не маршировал, не знает худшей из пыток, а он шагает дальше: сапоги не останавливаются.","483":"Душа без единого поступка стучится в небесные врата — отказ: ни добра, ни зла. Внизу тоже отказ: там нужны свои дела. Пустого высылают родиться заново — прожить жизнь, о которой есть что рассказать.","484":"Отец расспывает всех о сыне, которого съел туман над водой. Мать верит в возвращение — правду ей он не скажет. Но если сын погиб за других, цена не гасит свет: отец продолжает спрашивать и ждать.","485":"Глашатай просит барабаны бить так громко, чтобы они врывались в спальные дома и будили город, глуша скрипача и оратора: в них нет вежливости, только ритм. И вот барабаны уже гремят над всей улицей.","486":"Пожилой перевязчик идёт вдоль палаты после боя: наклоняется к каждому раненому, как к сыну, помнит имена, успокаивает мальчиков. Прошли годы — и он всё ещё спускается в ту палату во сне.","487":"Пассажир парома обращается к тем, кто поедет им через сто лет: я стоял здесь и смотрел на ту же воду. Расстояние между нами меньше, чем кажется, — река уже связала нас, и берег у нас общий.","488":"Солдат всю ночь стоит дозором над телом товарища и говорит с ним, как с живым. Утром он укладывает друга в землю: их служба кончилась — одна ночь и одна могила на двоих, и он уходит с рассветом один.","489":"Мальчик под луной слышит с берега спор двух птиц о воде и памяти — из пены выходит слово, которое просит себя исполнить. Он вырастает в певца и поёт слово, которое море попросило вынести.","490":"В пустом небе два орла сцепляются когтями, замыкают крылья в кольцо, падают, не разрывая хватки, и пропадают в облаках — наблюдатель снизу догадывается: любовь в вышине работает без свидетелей.","491":"Хозяйка души закрыла дверь перед толпой претендентов: император в седле на пороге ждёт напрасно, чужие фамилии вычеркнуты разом. Дверь откроется один-единственный раз — и то не для толпы.","492":"Наблюдатель смотрит, как птица на дорожке съедает червя, пьёт каплю росы, отпрыгивает на стенку и смотрит на него изумлёнными глазами — а потом запевает и разлетается пучком перьев в воздухе.","493":"Наблюдатель зимних сумерек встречает косой свет, который давит, как тяжесть соборных нот: это печать неба, оставляющая рубцы, где печали нет слова. Вечер подходит — и тяжесть становится воздухом.","494":"Ружьё рассказывает, как стояло в углу, пока не нашло хозяина: теперь они выезжают вдвоём, как одно тело, и говорят за двоих. Оно останется с ним до последнего дня — и не переживёт его.","495":"Погребённый за красоту разговорился через стенку с тем, кто пал за правду. Пока мох не закрыл оба имени, они спорят и сходятся: их спор остаётся под камнем навсегда.","496":"После прощания в доме идёт тихая уборка: вещи разбирают по рукам, сердце чистят, а любовь прячут в углы — на хранение памяти. Работа не для чужих глаз: собрать то, чего больше нет.","497":"Он не может жить с любимой — её будут обслуживать, как хозяйку неба, — и не может без неё. Он готов закрыть глаза, лишь бы не видеть её старости, и выбирает смерть как единственный честный порог.","498":"Он ставит жизни простую планку: остановить хоть одно сердце от боли или вернуть птенцу гнездо — и жизнь не зря. Как робин, плетущий своё гнездо, он спасает одно сердце и находит в этом смысл.","499":"Садовник ловит взглядом колибри: зелёная искра промелькивает по тропе сада мимо цветов и шмеля — и исчезает к вечеру, как река, вскрывшаяся на утро. Ещё сутки сад её ищет.","500":"Дети королевства у моря любили так, что им завидовали ангелы, — но ветер принёс холод и унёс её в гробницу у берега. Теперь он каждую ночь лежит у её могилы: эта любовь старше любого ветра.","501":"Над гробом Леноры он кричит толпе, что оплакивать её не станет: она ушла из мира порока к славе, где ждут Бог и любимый. Пусть грешные плачут — для него она святая у трона, и она ждёт его.","502":"Слушатель помнит дворец, где пел хор вестников царя Разума, — пока власть не захватили духи в масках. Теперь у окон глаза без света, и вместо гармонии дворец глухо смеётся без слов.","503":"Отцы спрашивают невесту, готова ли уйти из отчего дома, — она отвечает спокойно: пойдёт, как по реке, в его селение среди диких роз и малины. Она выходит в его мир с открытым сердцем, без драмы.","504":"В сумерках над городом путник уходит вместе с приливом — и не вернётся: утро наступит без него, и он не скажет, куда ушёл. Останется только след на песке, который море сотрёт к рассвету.","505":"Король Роберт возомнил себя выше всех — духи посадили его в клетку на потеху двору. Он терпит насмешки, молится про себя — и ангел возвращает королевство: теперь он правит смиренно и умирает монахом.","506":"Брошенный хозяином конь изголодался и сам дёргает колокол правосудия, куда идёт судья по любому обидчику. Толпа сбегается на звон, и суд обязывает хозяина кормить коня до последнего дня.","507":"Потомок ставит камень на мосту, где разгорелся бой: тихий выстрел оттуда никто не заметил, но его эхо раскатилось по всему свету. Он завещает: оставить их флаг на мосту, пока стоит камень.","508":"В их доме был обычай: обо всём важном сказать пчёлам. Он забыл сказать пчёлам о смерти жены — пчёлы вянут, улей затихает. Он идёт в сад, плачет, произносит слово — и дом снова оживает.","509":"Городские женщины ловят капитана, бросившего когда-то тонущий экипаж, и везут его в телеге по улицам под стишки. Мокрый старик слушает каждый стих: город учит его, что люди не бывают дешёвыми.","510":"В осаждённом городе сквозь жаркий вечер слышны волынки — не их строй, но знакомый. Осаждённый первым узнаёт своих: не ищите знамён, это наши. Звук приближается — стена перестаёт быть тюрьмой.","511":"В чёрной ночи он благодарит богов за несломленную душу: под ударами случая не сжался, не кричал, хоть голова в крови. Годы угроз его не сломят — он выходит из ночи непобеждённым, капитан своей души.","512":"Моряк просит выкопать ему могилу под звёздным небом: свет — с севера, дождь — с запада, тьма — к закату. Он рад был всему, что любил, и даже под камнем будет просыпаться в рассветной тишине.","513":"Ребёнок дружит с тенью: она бегает с ним, смеётся с ним — тощая, как леденец, или огромная королевская. Однажды утром тени нет: она ушла с другими лучами, но вернётся, когда проснётся солнце.","514":"Всадник стучится ночью в дверь башни — ответа нет: фантомные слушатели слышат его из тишины. Он кричит обещание в пустоту и уезжает на коне, а тишина остаётся шептать воздуху о прошедших гостях.","515":"Луна медленно обходит спящий город и оставляет серебро всюду: у башмаков, птиц, окошек, лапок мыши, на море и скалах. Даже собака в подворотне и кот под деревом — всё серебрится, пока город спит.","516":"Он не может не вернуться к морю: просит высокий корабль и звезду, ведущую вперёд, — прилив зовёт, ветер бьёт, как нож. От бродячей жизни до крика чаек он снова идёт к морю, как шёл всегда.","517":"Гребец идёт с галерами в рассветное море, пока короли молчат и ждут знака: барабаны, знамёна, ветер и дым собираются в одну волну. Перед боем гребцы слышат звон — флот бьёт первым и побеждает.","518":"Путник любит пьяную английскую дорогу: она сплетает поле с рынком, храмы с виселицами, ведёт одних в тюрьму, других под знамёна. Вечером она приводит всех домой — но обязательно своим маршрутом.","519":"Она танцевала таранеллу в гостинице под Падуей — весь двор требовал продолжения. Теперь зал пуст, у двери мухи, ветер листает меню, и только стены помнят её каблуки: так больше не танцует никто.","520":"Солдат видит в снах газовую атаку: человек кричит и тонет в известковом море, хрипя в маске. Услышав этот хрип, он запрещает детям повторять старую ложь, которой приукрашивают войну.","521":"Поэт на фронте ищет обряд, которого нет: молодых косят без счёта, колокола молчат — гул снарядов заменяет отходную. Дома их занавесом станут свечи, бледные лица девушек и медленные вечера.","522":"Солдат вырывается из ямы боя в туннель, где спит война. Раненый узнаёт его: я тот враг, что пал от твоей руки. В темноте они стоят рядом, и враг протягивает руку — прощение пришло там, где войны нет.","523":"Килмени ушла за ягодами и пропала на семь лет: духи унесли её в страну, где нет зла и лжи. Она вернулась, рассказала всё — и в тот же вечер ушла из дома навсегда, оставив людям только песню.","524":"Старый вождь идёт на Иври и заранее разрешает свою смерть: паду — знамя идёт дальше без остановки. Он падает — колонна прорывает линию: приказ не умер вместе с командиром, и знамя проходит Иври.","525":"Коробейник идёт с лотком снов: забытое лицо, дождь в старом городе, несостоявшийся разговор. Сны дёшевы — люди боятся вспоминать, чего им не хватает, — и он уходит дальше с почти пустым лотком.","526":"Певец венчает победителя колесниц: вода — лучшая из вещей, победа — вершина желаний. Как Пелоп, которому боги вернули плечо, герой не прячет дар, а выходит на гонку против смерти — на виду у всех.","527":"Девушку, замеченную богом, превратили в корову, и за ней гонится овод. Прикованный рассказывает ей всю дорогу — какие земли ждут её потомков, — и она идёт дальше, зная: однажды род освободится.","528":"Брата запретили хоронить — она ночью трижды сыплет землю на его тело. Стража хватает её, царь грозит смертью, но она отвечает: закон выше людского, — и идёт в каменный мешок, не поменяв слова.","529":"Он бросил её ради чужой короны и выгоняет с детьми — хотя она спасла ему жизнь. Она сначала просит, потом решает: свадебный дар станет огнём, и она уезжает в колеснице деда, оставив ему пепел свадьбы.","530":"Павшая королева слушает, как победители делят её детей: дочь — в чужой дом, сына — без похорон. Она больше не королева — она вода, помнящая, что была рекой, и уносит город в себе.","531":"Одноглазый гигант поёт с берега нимфе: снежная и сладкая, как молоко его стада, — хватает молока, плодов и единственного глаза. Поёт, как мальчик под окном, но она не выходит — и он заводит снова.","532":"Богиня плачет над любимым охотником: его убил клык кабана, и кровь на траве оборачивается розами. Она просит землю помнить его в цветах каждый год — так рождается весенний плач, ставший песней.","533":"Влюблённый говорит ей: будем жить и любить, а ворчливых стариков пусть судят копейки. У нас один короткий день и одна долгая ночь — пусть будут тысячи поцелуев, и счёт потеряется, чтобы не сглазить.","534":"Она просыпается на пустом берегу: парус любимого уже точка на горизонте, а она ещё верила вчерашнему сну. Она кричит с камня в море — остров молчит, но её имя останется на звёздном венке.","535":"Он плывёт через моря к брату — и опаздывает: тот уже мёртв. На чужой земле он приносит последний дар и молча говорит над могилой и встречу, и прощание — всё, что брат уже не услышит.","536":"В снежный день он зовёт друга отогреться вином у очага, а ветер и волны оставить богу. И девушку просит бросить танцы: снежная гора ждёт её улыбки больше, чем храм.","537":"Поэт сравнивает возвращающиеся весны и людей, которые не возвращаются: Эвридика и Тантал ушли навсегда, и реку нельзя переплыть дважды. Осталось одно — пить вино сегодня и помнить, что мы пыль.","538":"Певец вымолил у подземных богов жену — песня сдвинула даже слёзные реки. Условие: до выхода к свету не смотреть назад. У края он не выдержал — она растворилась, и он вернулся к земле один.","539":"Королева дала ему город, флот и постель — а он ночью уплыл, сказав, что зовёт судьба. Она проклинает его род, сжигает его одежду и оружие и уходит в огонь, оставив проклятие, которое вырастет в войну.","540":"Мастер, презиравший живых женщин, вырезал из кости девушку красивее всех: говорил с ней и укладывал в постель. На праздник любви он просит себе жену — и при первом поцелуе статуя оживает.","541":"Нимфа, умеющая лишь повторять чужие слова, влюбилась в юношу — а он оттолкнул её и был наказан: увидел в воде отражение и остался у пруда навсегда. Она выцвела в скалы — в лесах осталось только эхо.","542":"Она умоляла мужа остаться: ей снилась буря, но он поплыл к оракулу — и волны забрали корабль. Боги сжалились: оба стали зимородками, летающими вместе над тихой водой, и штиль моряки зовут их именем.","543":"Один друг при всех жалуется: Фаустина меня не любит. Другой отвечает ему стихом: она называет тебя болтуном, ты её — лгуньей, и оба правы. Так живут соседи, которые слишком много говорят друг о друге.","544":"Бедняк объясняет другу, почему уезжает из столицы: повозки гремят всю ночь, богачи толкаются локтями, крыши рушатся, пожары едят кварталы. В деревне хоть тихо — можно жить и умереть на своём месте.","545":"Старик взвешивает, что оставить после себя: имущество умрёт, глупый копит и прячется — у мудрого остаётся слово. Он выбирает доброе имя вместо золота: песня о человеке переживёт и костёр, и пепел.","546":"Слуга влюблённого бога едет с мечом и конём в ледяные пределы сватать великаншу. Золото и яблоки она отвергает — тогда он произносит слово страшнее меча, и она соглашается прийти через девять ночей.","547":"Старуху спрашивают, кого она любила больше, — ответ ровный: со всеми четырьмя мужьями обращалась хорошо, но тому, кого полюбила сильнее всех, принесла больше зла. Одной фразой закрыта целая жизнь.","548":"Король встречает в лесу чужого короля и предлагает год поменяться местами — в чужом облике и чужой стране. Он живёт как друг, побеждает его врага, потом облик возвращается — а дружба остаётся.","549":"Влюблённая в столичного гостя девушка решается на неслыханный шаг: первая пишет ему письмо. Ночи напролёт ждёт ответа, гордость смешивается с тревогой — душа открыта первой, и она теперь уязвима.","550":"Над его другом смеются на балу — и он вызывает на дуэль равнодушного светского человека. Зависть и гордость сильнее дружбы: выстрел почти не целясь, друг падает — вместо триумфа пустота и вечная вина.","551":"Вернувшийся герой встречает её — замужней, спокойной, недосягаемой — и пишет письма, где честность выше приличий. Она отвечает отказом, но отказ стыдится себя: любовь жива, а счастье опоздало.","552":"Молодая дочь уходит из дома к старому гетману — врагу своего отца. Гетман выбирает власть: её отца казнят за заговор, и она сходит с ума, пряча любовь в забытьи, где отец ещё жив и казни не было.","553":"В свадебную ночь невесту уносят из запертых покоев, и жених идёт по следу — сквозь поле, лес и гору, где ждут бой с чародеем. Она верит, что за ней придут, и никакая гора его не остановит.","554":"Жених находит пленницу в логове чародея: колдовство врага держится на длинной бороде. Три дня он не отпускает её, пока меч не срубает магию, — враг умирает, и заслон между влюблёнными падает.","555":"Князю накануне битвы является видение: вечное царство и память в молитвах — или недолгая земная власть. Он выбирает вечное, часть войска уходит к врагу: битва проиграна, но имя осталось в песнях.","556":"К юной душе приходит тёмный гость и спорит с её порывами: радости скорбят, обязательства лгут, прекрасное — дань моде. Ничего не отнимая, он вытравливает веру в её ответы — и нечем жить.","557":"На прощание возлюбленный дарит ей талисман: от измен и бурь он не спасёт, но убережёт от слёз разлуки и лжи в пути. Она едет сквозь штормы и молву, и в трудные минуты вещь говорит: где-то её ждут.","558":"Выпускник собирает друзей юности в осенний день: одни погибли, один в изгнании, иные не приехали. Он чокается с пустым стулом — кто не с ними телом, тот с ними душой, и гимн звучит как молитва.","559":"Путник едет ночью через холмы под тихой луной: сердце щемит, но это не потеря — в нём снова родилась далёкая простая любовь. Всё, чем он скорбит, — всё, чем он жив, и грусть становится нежностью.","560":"Герой вспоминает небо дальнего края и женщину, которую там любил, — живую, будто правящую дыханием моря. Разлука всех разлучила, но в памяти она правит его снами, и он поёт ей надгробную песнь.","561":"Он прощается с пьяными годами обманутой юности и решает жить заново: слова о жизни и надежде возвращают силу. Впереди горе, но пусть страдание усложнит жизнь, не сломав её, — и печаль обретёт весну.","562":"Толпа требует у поэта пользы — пусть приносит выгоду, как сапожник обувь. Поэт отвечает: мещанин ценит вес и полезность, а небесное скрыто от сытых глаз, — и он уходит от толпы, храня свой смысл.","563":"Ссыльный думает о старой няне: она далёко, но проживает его тоску — одним ветром веет из обеих хижин. Он обещает ей чай за городом и долгий разговор у лампы, когда часы доведут до встречи.","564":"Ночью сквозь туман скрипит колесо, ямщик молчит, одинокий колокольчик мрачит путь. Впереди дремучий лес и домик старушки с дырявой стеной — путник утешает себя: скучно сегодня, зато завтра к милой.","565":"В забытой книге герой находит сухой цветок: кто его сорвал — знакомая рука или чужая, и живы ли ещё те, кто читал книгу тогда? Цветок хранит след того лета, а его свидетели неизвестны.","566":"Хозяин старых стен видит выцветшие цветы и фото гостей и приносит в жертву памяти юность, печали, любовь и дальние края. Пусть время расточит краски — взамен он не отдаст ничего, пока память горит.","567":"Дух падения находит Тамару, оплакивающую жениха, и соблазняет её отвергнутым раем. Она соглашается на его любовь — и после первого поцелуя её сердце останавливается: зло отнимает то, что полюбило.","568":"Царский боец обесчестил его жену — купец вызывает обидчика на кулачный бой за святое имя, ценою жизни. Победа обрекает его на казнь, но он наказывает братьям похоронить его честно и беречь жену.","569":"Дубовый листок, оторванный грозой и занесённый в тёплый край, просит пальму о приюте: я беден и одинок. Она отвечает — держись своего корня, — и листок падает в песок: одиночество сильнее просьбы.","570":"Золотое облачко ночевало на груди старого утёса, а утром умчалось играть над синим небом. Утёсу остался мокрый след от короткой ночи, которую не вернуть, — и он один ждёт нового ненастья.","571":"Из страны вечного льда прилетает дерзкий молодой великан с воинственным шумом. Старый исполин встаёт навстречу и бьёт в его шапку — сила пришельца рушится грудой, и горы возвращаются к покою.","572":"Он не может объяснить, за что любит родную сторону: ни слава, ни вера, ни долг ни при чём. Ему дороги полевые колеи, дым над выжженной стернёй и пара белеющих берёз — то, что говорит без слов.","573":"Воин, сотрясавший мир, умер на далёком острове — кошмар народов для одних, утраченный герой для других. Теперь только песня хранит имя и решает: останется он победителем или болью человечества.","574":"В ночь на святой праздник сквозь зимний туман плывёт чёрный корабль: на мостике тень павшего императора, не верящего в смерть империи. Призрачная команда идёт мимо живых островов — её никто не ждёт.","575":"Арестант слышит за стеной песню соседа о родной стороне, белых вершинах и качающихся горах. Четыре стены остаются, но он уже уехал в этой песне: свобода начинается с чужой песни о свободной земле.","576":"Отец разлучил дочь знатного рода с бедным певцом: юношу изгнали, он умер на чужбине, она не пережила разлуки. Над их могилами поставили эолову арфу — и ветер в струнах соединяет голоса влюблённых.","577":"Девушку венчают не с тем, кого она ждала: избранник погиб в походе. Она упрекает судьбу — и в полночь гроб раскрывается: мёртвый зовёт её знакомым голосом, и она идёт за ним, оставив живого жениха.","578":"Продавший душу громобой получает последний шанс: три ночи бодрствовать над двенадцатью спящими девами. Мимо летят соблазны, видения и голоса грехов — он держится до утра, и сделка с тьмой рушится.","579":"Рыбаки приютили Ундину как дочь, рыцарь повенчался с ней — но лесная чаровница спорит за его сердце, а водный мир зовёт обратно. Ундина исчезает в речных струях, оставив рыцаря между двумя мирами.","580":"Граф взошёл на престол, погубив юного племянника, — и по ночам его зовёт голос, требуя обещанного. Пока он держится власти, возмездие приходит изнутри: престол есть — покоя нет.","581":"Ворона на ели держит сыр, а лисица снизу хвалит: какие перья, какой нос, какой голос — спой, госпожа! Ворона каркнула от гордости — сыр упал, лисица ушла с добычей, и лесть оказалась голодной.","582":"Лягушки утомились без начальства и попросили бога послать им царя: сначала он уронил им осину — слишком тихую. Вторым пришла цапля с голодной должностью — просьба исполнена, и о воле больше не спорят.","583":"Свинья наелась жёлудей под дубом и подгрызла его корни. Дрозд объясняет: дерево кормит тебя, — она грубит: пусть сохнет. Связи между дубом и брюхом она не видит — рушится её собственная кормушка.","584":"Соловей запел — и всё вокруг замерло, а осёл благосклонно замечает: неплохо, но журавль и петух спели бы лучше. Соловей молча улетает далеко: лучший ответ такому судье — замолчать самому.","585":"Волк ночью пробрался на псарню и оказался в западне: щётки, дубины, злые гончие. Он предлагает мир и службу, но псарь не ведёт переговоров — слишком хорошо знает серого, — и спускает собак.","586":"По городу везут слона, и моська носится вокруг него, лает и кричит, что ничего не боится. Подруга замечает: слон на лай не отвечает. Моська горда: пусть думают, что она смела, — репутация стоит шума.","587":"Обоз с горшками спускается с крутой горы: старый конь советует молодым беречь груз, они смеются и летят вниз. Горшки бьются, и старый конь прав: что спустил с горы, тому труднее обратно подняться.","588":"Механик-самоучка клянётся открыть секрет запертого ларчика: щупает, крутит, обходит механизм с трёх сторон. Слушатели советуют просто открыть его. Самоуверенность упрямее подсказок — ларчик заперт.","589":"Петух роет навозную кучу и находит жемчужное зерно — но не умеет оценить: голодному полезнее ячмень, пусть жемчуг берёт тот, кто умеет ценить. Мудрость остаётся лежать там, где её не ценят.","590":"Мужики ищут счастливую женщину, и Матрёна отвечает: счастье есть, но никто его не разделит. Она рассказывает жизнь за чужим столом, потерю детей, тоску — годы держат её только терпение.","591":"Семинарист Гриша, ночуя в поле, слагает песни о материнской доле и о Руси — с верой, что народ исцелится правдой и трудом. Он не ждёт славы: песня летит впереди тех, кто её услышит.","592":"Путник едет по чугунной дороге и во сне видит строителей: одни умерли от жара, другие от истощения, а их труд присвоили чиновники. Дорога готова, имена стёрты — он просит показать живые поля страны.","593":"В половодье дед Мазай плывёт через затопленный лес: поднимает веники с зайцами, подбирает поодиночке, везёт всех сухими в избу и выкармливает до спада воды. Весной он отпускает их на волю.","594":"Мальчик везёт воду и воображает себя ямщиком: подбадривает лошадку песенкой, воз и упряжь у него как настоящие. Прохожий наградил его за выдумку — и дорога стала праздником, хоть вода осталась водой.","595":"Вернувшийся из отлучки муж узнаёт об измене и в гневе губит любовника — суд решит его судьбу. Но весенний зелёный шум берёт за душу: он не губит семью зазря, отдаёт суду правду и живёт дальше.","596":"Зима-чародейка очаровала лес: она обнимает могучие сосны, вяжет им лёгкие пуховые цепи — лес не умирает под снегом, а спит и видит её до весны. Зима не убивает, а укутывает, и лес благодарно ждёт.","597":"В начале осени есть короткая пора: день стоит хрустальный, лучи не гнут паутину, поле пустеет, а воздух ещё дышит пьяным теплом. Он запоминает эту передышку перед ненастьем целиком.","598":"Он отказывается измерять страну линейкой и рассудком: у неё свои сажени, свои шаги и своя судьба. Расчёт бессилен перед живым и непредсказуемым — смирение перед необъяснимым тоже форма любви.","599":"На чужбине он заходит в лютеранский храм: пока идёт молитва, там светло — вера держит душу. С концом службы свет уходит — чужая вера напоминает ему о его собственной пустоте.","600":"Днём драгоценная завеса покрывает бездну, и людям светлее; ночью она спадает — мир остаётся один с тёмной глубиной. Он слышит голос бездны и чувствует себя на краю: днём покой, ночью — правда.","601":"Под луной море трепещет и блестит: волны не боятся ни темноты, ни глубины. Мечтатель на берегу, влюблённый в эту стихию, хочет жить так же свободно — и уносит в душе приливы звёздного моря.","602":"Спящий спрашивает ночной ветер, отчего тот воет безумно: в шуме то глухой смех, то говор. Ветер не отвечает, но он слушает до утра — в вое буря, тоска и любовь к мгновению.","603":"Над жаркой нивой зреет рожь, и весь мир звенит от пчелиной жары. Влюблённый ждёт в поле не урожая, а её: пусть придёт и станет живой его милой — чувство зреет вместе с хлебом.","604":"Влюблённый раскладывает одно летнее утро на предметы: синий свод, птиц, иву, речные вёрсты, гнездо и зерно. Всё это — одно мгновение, в котором живёт любовь: утро и радость — одно слово: она.","605":"Над лугом мечтатель завидует бабочке, живущей одним мгновением — на цветке и в воздухе. Ей незачем стенять о коротком веке: нет прошлых лет, где скучали, — есть теперешний час, и он цветёт.","606":"Мечтатель видит под облаками воздушный город: лестницы среди башен, крылья крыш — родину своей души, куда он приходит во снах. Пока он несёт земное бремя, город ждёт наверху его встречи.","607":"Заключённой снится её молодость: окно за решёткой, койка в полутьме, и с койки смотрят её пустые глаза. Она не знает, когда сможет снова любить: судьба ещё не сказала, когда кончится срок.","608":"Ребёнок из колыбели спрашивает: отчего месяц бледен и одинок? Взрослый отвечает: месяц — странник ночи, солнце — труженик дня. Малыш засыпает, и вопрос, кому из них теплее, остаётся без ответа.","609":"Осенью под окном пустеет гнездо ласточек: солома обветрилась, птенцов не слышно. Смотрящий из окна помнит лето, когда в нём пели пять головок, — теперь оно хранит весь их семейный год.","610":"Морской царь заманивает пахаря Ивана в подводное царство: чем жив человек? Ответ — паханьем: Иван не берёт ни дочери царя, ни богатств и с помощью дочери бежит к родной меже, за плуг.","611":"Сгорбленный ветрами дуб лежит и корится: жизнь кончена, молодым под его тенью не сдобровать. Поросль отвечает: без старых стволов зелени не вырасти — падай так, чтобы кормить нас.","612":"Пахарь поёт за сохой: везёт он не только соху, но и любовь. Песню слышит та, что нравилась давно, и откликается: конь бежит быстрей, соха легче, полдень с любимой по следу плуга короче.","613":"Ухарь-купец с ярмарки решает удивить деревню гульбой: высыпает всё нажитое, угощает и зазывает девушек. К ночи вместо пира — ссоры и туман, а утром купец скромен: деревня выстояла, кошелёк пуст.","614":"Потерявший дом и семью бурлак тянет ладью по волжскому песку — остались ремень и рваная обувь. Он помнит, что умел петь, не знает, где сила, где бездна, и идёт дальше: идти некуда.","615":"По дороге гонят этап: кантонисты, рекруты, осуждённые под конвоем — им махали из окон, словам не верят. Один вспоминает ночной подъём; песня идущих не о свободе, а о том, что их видят.","616":"Гроза отгремела, и мир проснулся свежим: капли блестят на листве, синеет даль, пахнет мокрой травой. Вышедший в просвет прохожий дышит свободно: страшное час назад стало чистым.","617":"Ребёнок просыпается в зимнем утре деревни: печка пылает, снег блестит, его зовут кататься. Он несётся с горы по гладкой дорожке, а к вечеру вернётся к огню — деревня останется домом навсегда.","618":"В человеке спорят счастье и память: он ловит радость настоящего, а память отвечает лицами и песнями прошлого. Спор не решён: живёт он настоящим, а домом остаётся память.","619":"У руин судьбы герой находит последний оплот: надежду — мечту, которая не обманывает, пока жива. Из неё он строит щит против печали: не всё потеряно, пока есть о чём мечтать.","620":"Ночью пара гнедых тянет карету по городу, вспоминая юность, когда они слушали жизнь пассажиров. Теперь их судит усталость: вместе со старым кучером они всю ночь везут и себя, и город.","621":"Тройка мчится: пыль из-под копыт, песня ямщика, колокольчик переливается то смехом, то плачем. Пассажир упивается ездой — и вдруг понимает: несётся не только дорога, так же мчится жизнь.","622":"У опушки в домике живёт седой старик-лесник: он один, но рад каждому гостю. Гость вспоминает весну, проведённую там, и хочет вернуться — старик ждёт его у окна, как ждут родных.","623":"Студент за столом поёт гимн веселью: вино и молодость против скуки и седины, пока юность горит — беги за радостью. Песня переживает его: сначала про вино, потом про свободу.","624":"У моря паж слушает, как королева играет Шопена в башне, и влюбляется через музыку. Ночь грозы сближает их, наутро она уходит — и его соната остаётся петь о ней.","625":"Поэт выходит в огромный зал и объявляет себя гением — не похвальба, а постановка себя в мир с дерзостью, с которой начинаются новые голоса. Заявка принята: у новых голосов теперь есть пример.","626":"Художник дремлет между сном и явью: в тумане неба всплывают тени образов, которых ещё нет. Он спускается в это несозданное и приносит оттуда живой образ, что ждал воплощения.","627":"Каменщик кладёт стену крепости, где рубят головы, и молчит, когда вождь спрашивает, чья это тюрьма: стена растёт на костях. Работа держит его сильнее правды — совесть растёт внутри стены.","628":"Мечтатель на тёмной башне ловит мерцание: тени дней, что прошли, и тех, что не наступили. Чем выше, тем яснее контур, но тени ускользают — он снова тянется: счастье всегда чуть выше.","629":"На заре по саду порхает белая пташка — белее всех райских птиц и пугливее всех: падает ниц с ветки и воздыхает. Робкий человек узнаёт в ней своё чувство, которое боится взлететь.","630":"Друг ушёл к той, ради которой предал и дружбу, и любовь. Под мглой над холодной водой оставшемуся открывается страшная ясность: теперь их двое, а он один, — и он идёт в пустой дом, где остался дождь.","631":"Осенний лес горит лиловым, золотым и багряным, но стоит светлой пустотой: птиц не слышно, листья как узор. Осень украшает уход, и в тишине слышна последняя музыка лета.","632":"Путешественник уходит в далёкий край, где течёт Замбези: слушает предания племён, ночует в лодках, идёт сквозь травы, где гуляют страусы и туманы. Он ищет не золото — край, где небо ближе.","633":"Прощаясь со всем, что любил, — ночные часы, лебеди на пруду, сушащаяся гречиха, — он знает: счастье лишь обрывок пути. Но в прощании есть мастерство, и он им овладел.","634":"Маленький сын спрашивает отца, что такое хорошо и что такое плохо. Отец не читает проповедь, а рисует пары: грязнуля — чистый, трус — смельчак, — и с этого утра мир делится на два цвета.","635":"Дети и взрослые выбирают дело жизни: инженер строит, врач лечит, лётчик летит, лишних нет. Ответ бодрый: выбирай дело по нраву и работай с радостью — мир ждёт того, кто выбрал.","636":"Честный человек перечисляет, что любит: не украшения и должности, а парк, дожди, близких и работу — другую работу. Любовь — способ жить: любить, пока ноги идут, работать, пока руки не опустились.","637":"Судно носит имя механика Нетте: бандиты потребовали почту, он отказался выдать её и погиб, защищая письма простых людей. Теперь корабль несёт его имя из порта в порт — верность не утонула.","638":"Проситель у окошка держится за паспорт, как за кровь: чиновники вежливы к чужим, к нему — с пренебрежением. Он выходит из приёмной с гордостью, которую не забрать никакими улыбками.","639":"Женщина у зеркала видит трёх себя: ту, что смотрит, ту, что смотрится, и ту, что будет. За спиной гасит свечу тень бабушки — и в мгновение между зеркалами она встречает себя во всей глубине времени.","640":"Крестьянин смотрит на свою избу и видит космос: дым над трубой — небесная лазурь, в окне — звёзды и лунные тропы. Дом равен вселенной, если в нём живёт душа.","641":"В окнах бревенчатых домов застыло прошлое: лица, свет и тоска прежних поколений смотрят на прохожего. Он понимает: его собственная жизнь однажды отразится в таких же окнах для будущих глаз.","642":"Поэт говорит с Кавказом о человеческой горе: у подножия текут реки слёз порабощённых народов. Он зовёт огонь и молот покарать поработителей — горы стоят, но свобода всё равно придёт.","643":"Поэту снится империя: вельможи в мехах на тронах, рынки, где продают людей, солдафонская шкура вместо совести. Он ходит по сну, похожему на правду, и просыпается: сон оказался точнее документов.","644":"Девушка ждала любимого под тополем, узнала об измене и ушла из мира — на могиле вырос стройный тополь. Он машет ветками над рекой, как она махала рукой, и всё ждёт того, кто не вернулся.","645":"Девушка тайком ходила к тому, за кого не выходила замуж, — слухи свели и любовь, и доброе имя. Теперь о ней шепчет вся улица, и она платит одиночеством за любовь, которую выбрала сама.","646":"Девушка с внебрачным младенцем идёт работать в богатую хату и узнаёт в хозяйке собственную мать — но молчит о правде. Она остаётся служить рядом с родными, которые её не знают.","647":"Чумаки выезжают с возами и волами в дальний шлях за солью: броды, хворь, грабёж, стужа — не все вернутся. Но каждый год парни снова запрягают волов: без соли не выживет жизнь.","648":"Мавка, лесная душа, полюбила Лукаша, но два мира не пускают их друг к другу. Она жертвует собой ради его музыки — становится деревом, и его свирель поёт её голосом.","649":"Боль сдавливает душу, и всё кричит: упади, не борись, — но согбенная душа отвечает: нет, свет я найду сама. Она пронесёт искру через отчаяние, потому что отказывается гаснуть.","650":"Русалка ради человека покинула водяной мир, но её любовь без души пугает сильнее, чем манит. Он бежит, река забирает его, и она возвращается в воду — без боли и без любви.","651":"Тёмная ночь накрыла спящих; не спит только страж, ждущий предрассветных огней, что прорежут тьму. Он зовёт всех держать фонари до утра — рассвет близок.","652":"Его не убили ни тюрьмы, ни каторга: дух, рвущийся к бою за волю, не сломлен. Он выстроит палаты из алмазных скал, сзовёт гнев народный — и ведёт живых дальше.","653":"Тадеуш застаёт в саду Зосю — застенчивую девочку за цветами, и неловкий разговор перерастает в первую влюблённость. Семейные распри придут потом, но сад уже запомнил их вечер.","654":"За обедом у подкомория повара дерутся за свои коронные блюда: старая литовская кухня против новомодных манер. Спор кончается мирно — паны сыты и при своих мнениях за одним столом.","655":"Старый музыкант Янкель играет на дульцимере историю без слов: спор ляхов и Литвы, война двенадцатого года, панихида и радость свободы. Гости молчат: музыка сказала то, чего не сумел оратор.","656":"Ночью в часовне жрец кормит огнём тени умерших: одна не может оторваться от жилья, где страдала, другая просит воды, третья — призрак ребёнка. Мёртвым нужна не месть, а участие живых.","657":"Юноша под чужим именем входит в рыцарский орден и становится великим магистром, чтобы изнутри вести его к поражениям. Оставленная возлюбленная узнаёт правду — обе жертвы оборачиваются гибелью.","658":"Перед походом за свободу поэт пишет родным с чужого берега: пусть не ищут его могилу и не зовут мать. Скажите ей: он так любил родину, что умер далеко, — лишь бы другие вернулись.","659":"Изгнанник издалека мечтает о доме любимой, где она ждёт его под ясным небом. Он завещает: когда её не станет, пусть очаг останется её — новое поколение не займёт этот дом.","660":"Мать забирает дочь с младенцем от водяного мужа, и женщины спорят, кому держать ребёнка. За спором его не замечают в купели — а водяной уже за дверью: секунда упущена навсегда.","661":"Мать в сердцах грозит ребёнку полудницей — и та приходит: высокая, белая, с языком как у горного потока. Она прижимает малыша, но к полудню держит пустоту: сказанное слово сбылось.","662":"Ночью к девушке приходит мёртвый жених: сплести за три ночи свадебные сорочки, последнюю из стали. Нити нет к сроку, он требует её кровь — она поднимает крест и оставляет его во тьме.","663":"Мачеха посылает падчерицу к старой ведьме: за доброту та возвращается с золотом. Родная дочь идёт с высокомерием — получает жабью кожу и стыд, и на свадьбе правда о невесте звучит вслух.","664":"Девушка утром идёт на пустое поле рвать землянику, а к ней подъезжает наёмник с дурными намерениями. Мать находит её на землянике — поле опустело, урок остался всей деревне.","665":"Муж тайно следует за женой и видит, как она идёт по воде к священной вербе — её второму дому. Он срубает дерево, и в ту же ночь жена умирает: любимую можно только отпускать.","666":"Умирающая девушка просит похоронить её в лесу — над могилой расцветает белая лилия. Господин забирает цветок к себе, но чужую волю не приручить: лилия увядает на чужом окне.","667":"Бунтарь Вилем стоит на эшафоте за убийство человека, погубившего его брошенную возлюбленную Ярмилу, — она уже ушла в воду. Судьба забрала обоих, и весна цветёт над рекой, где теперь двое.","668":"Поэт в дальних краях пишет далёкой Марине: ни моря, ни годы, ни лихие вести не изменят его сердца. Разлука закаляет любовь — она его солнце в походах, и он обещает вернуться.","669":"Злая мачеха гонит пастушка Янчи из деревни, прочь от любимой Илушку. Через тёмный лес, страну великанов и туманное царство верное сердце приводит его к победам — и к ней.","670":"Сентябрь развёл лето и зиму: сады цветут в долине, а на вершинах лёг снег. Поэт просит любимую не смотреть в глаза зиме — любить его, пока горит его жизнь.","671":"Крестьянский сын Миклош Тольди, сильный как медведь, побеждает рыцарей, смеющихся над его происхождением, и выходит на королевский двор. Он открывает своё имя — и король делает его рыцарем.","672":"Король Буда делит власть с братом под кровной клятвой, но гордость доводит братьев до войны. Побеждённый в битве, он умирает и вверяет брату дочь и народ — тому, кого считал врагом.","673":"Чонгор идёт в страну снов за Тюндой — феей человеческой крови: духи-сновидцы и обманные залы не останавливают его. Он выбирает живую любовь вместо вечной игры мечты, и сон отступает.","674":"Голос рода обращается к народу: не умирай ни здесь, ни на чужбине — честно жить и честно умереть, вот вся суть. Кто остаётся верен родине даже в беде, того беда не лишит имени.","675":"Мать узнаёт по знакам, что сын погиб на реке мёртвых, и идёт к чёрной воде с граблями. Она собирает его тело со дна и молится — сын оживает: любовь матери сильнее смерти.","676":"Кузнец Ильмаринен куёт мельницу Сампо: одна сторона мелет муку, другая — соль, третья — деньги, пока из огня не выходит крылатая мельница, крутящаяся сама, — со славой и бедой в жерновах.","677":"Куллерво, выросший рабом у врагов, погубивших его семью, вырывается из ярма и находит родовые мечи. Месть свершена — но некому радоваться: счастье так и не вернулось.","678":"Певец и кузнец вырывают у севера волшебную мельницу Сампо, но погоня раздробляет её на осколки, падающие в море. С тех пор море носит богатство, а берег — счастье песни.","679":"Свен Дуфва, сильный, но медлительный солдатский сын, не осилил ни письма, ни счёта — знает одно: держать позицию. У моста он встречает волну врагов один и погибает, удерживая место.","680":"Лотта идёт за войском с котлом и перевязочными лентами: кормит, лечит, штопает бойцов. Когда её не стало, солдаты оплакивали её как родную — армия потеряла то, что не заменит пушка.","681":"Братья выдают Ингеборгу старому королю; Фритьоф отказывается убить спящего соперника и уходит в морские походы. Умирающий король возвращает ему невесту и королевство: верность дождалась.","682":"Терье Виген грёб через шторм за мукой для голодающих детей — получил тюрьму, потерял дом и жену. Годы спустя он спасает тонущий корабль и не мстит узнанному капитану: человек выше обиды.","683":"Старик вспоминает деревенские скрипки и вечера на косогоре — лето пляса, когда время, музыка и молодость сошлись в одной точке. Теперь он держит то лето как самое точное своё счастье.","684":"Он подводит гордый итог своей жизни: хотя были боли и зимы, жизнь светла, прекрасна и радостна. Он не позволит написать на могиле ни слова о сожалении — смерть не отменяет прожитого.","685":"Горный богатырь Муса осадил город и требует дань — на бой выходит лишь Марко Кралевич. Он изматывает Мусу и метает нож, когда тот отвернулся: город свободен от дани.","686":"Раненый герой истекает кровью в дубраве: солнце горюет над ним, дубы склоняют кроны, как братья. Враги добили тело, но не песню — о нём поют весной, когда зеленеют поля за Дунаем.","687":"Молящийся просит у Бога не долгих лет и не сладкой жизни, а силы для себя и своего народа — умереть, но не подчиняться. Единственная награда: стать тем, кто защитит родину.","688":"Автандил находит в скале Тариэла в барсовой шкуре — тот плачет о украденной Нестан, оставшись один во всём мире. Исповедь чужаку запускает поход: спасение начинается с чужого плеча.","689":"Автандил, любимец двора, где ждёт его Тинатин, слышит историю скорбящего рыцаря: помочь незнакомцу дороже собственного счастья. Он тайно уезжает, теряя любовь и место, — и находит зрелость.","690":"Обиженный судьбой князь Придон остаётся верен друзьям: открывает, где спрятана Нестан, и ведёт союзников через вражеские земли. Он возвращается со славой, которую никто не обещал.","691":"Крылатый конь Мерани зовёт человека в полёт через горы, моря и города, не спрашивая согласия. Тело в полёте гибнет, но душа летит дальше: взлетевший не живёт в конюшне.","692":"Алуда подстреливает оленя с невиданными рогами — голос с неба упрекает: убил красоту. Второй олень на опушке, и охотник опускает ружьё: деревня зовёт трусом, а он уходит из леса человеком.","693":"Сироту Давида растят вдали от Сасуна, пока море не дарит юноше коня — и с ним своё имя и свой народ. Теперь у Сасуна есть защитник, который помнит, чей он сын.","694":"Мср Мелик приводит войско за данью к Сасуну — Давид выходит против него с молотом. Бой от утра до заката, и последний удар возносит тирана в небо: дань кончилась.","695":"Кикос слышит вой жены и решает, что она умерла от горя, — но деревня уже оплакивает его самого. Слух растёт быстрее правды, и живого Кикоса одевают покойником, чтобы избежать позора.","696":"Пёс приносит коту шкуру на шапку, а кот сшивает её себе; пёс зовёт волка и медведя наказать плута, но кот пугает их из чулана, как гроза. Обида пережила и обман, и обманщиков.","697":"Старейшины дают Саро слово дружбы брату Ануш — и свадьба влюблённых отменяется: Ануш выдают за другого, и Саро уходит с горы. Горе не оставляет выбора и ей — гора принимает обоих.","698":"Слепой поэт Абул Ала понимает мир лучше зрячих: власть и мораль рыщут за славой и кровью, а он одинок в правоте против века. Слепота освободила его от лжи — и осталась тенью на всю жизнь.","699":"Старый вдовец Бооз засыпает после жатвы, не веря, что счастье придёт, — а юная Руфь с его поля ночует у скирды и не сводит с него глаз. Утром в доме, полном памяти, проснётся новая нежность.","700":"Паломник берёт посох и уходит на два дня: небо и золотые поля, что любили они двое, мешают дороге. Никто не должен знать его цель — маленькая могила той, кого он не смог удержать.","701":"Каин убил Авеля и бежит: строит города, возводит башню до неба. Но внутри башни на него смотрят глаза, видимые сквозь камень, — совесть идёт с ним, как слепец, которого не прогнать.","702":"Над спящей страной нарастает ночь: шёпот, потом гул, вой и крылья тысяч джиннов, пока стены не дрожат. Стихия так же медленно отступает — мир оглушён, но жив: гром был и минул.","703":"Осаждающие предлагают рыцарю Аймерилло корону за башню — он отвечает: слово королю дороже корон. Враги поджигают опоры, и пламя поднимается по лестницам вместе с песней о верности.","704":"Когда-то семья жила под одной крышей: разговоры до полуночи, праздник каждого имени, смех в коридорах. Теперь в тихом доме брат называет вслух имена ушедших — им отвечает память.","705":"Он возвращается на берег озера, где провёл с Эльвирой последний сезон любви: вода та же, голоса нет, и он просит озеро хранить их вечер — вернуть хотя бы звук лодки.","706":"Смотрящий на закат с холма видит: всё вокруг живёт и оживёт снова, кроме него, оставшегося без любимой. Он просит ветер укрыть его, но остаётся один посреди цветущей долины.","707":"В мае поэт болен жизнью и молчит, пока муза не заплачет жемчужинами о его невзгодах. Их спор о полной и пустой чаше кончается рассветом, где боль стала песней.","708":"Каждый декабрь к поэту приходит безымянный странник в чёрном плаще с закрытыми глазами. Он шёл за поэтом сквозь друзей и падения — не добрый и не злой, тихий голос одиночества.","709":"Денди Хассан покупает на рынке испанку Намуну, похищенную пиратами, и три дня играет в щедрость — потом продаёт её, не оглянувшись. Холодное сердце, покупающее людей, остаётся пустым.","710":"Старый маркиз смотрит на пальму с голубями и видит себя мальчиком на первом балу, девушку — с жемчужинами в глазах. Любовь возвращается в старое сердце, как в гнездо.","711":"Рыцарь потерял всё: лира чёрная, звезда мёртвая, крест выцветший, имя утеряно — он бродит среди развалин. Его спасает принцесса из призрачного замка: в её свете он находит своё имя.","712":"Он променял бы всё на мелодию своей итальянской юности — Россини, Моцарт и Вебер в один голос. Тот одинокий рассвет, что жил в груди, остаётся в сердце нотой, недоступной обмену.","713":"Он возвращается в долину детства к трём женщинам: Адриенне, чей образ унёс пожар, живой Сильвии и призраку Аурелии. Все три — одна тень юности, и звезда над долиной остаётся с ним.","714":"Фавн просыпается в полуденной тишине: обнимал ли он нимф или это было во сне? Свирель зовёт их из листвы, но они ускользают — и он сворачивается в воспоминание до звёзд.","715":"В цветущей долине, где ручей и солнце, в траве лежит юный солдат — бледный, тихий, укрывшийся небом. Природа убаюкивает его последней песней: его война кончилась.","716":"Летним вечером он идёт по шоссе: пшеница шумит, ботинки новые, он молчит — но любит сильнее, чем когда-либо говорил. Он уйдёт далеко, счастливый, и природа впустит его с улыбкой.","717":"Летний рассвет пробегает по холмам: обнимает цветы, растормошивает школу. Бегущий за ним человек встречает его у ворот весны и бросает ветку в море — теперь они одно целое.","718":"Вздохи осенних скрипок ранят сердце: колокол, ветер, листья. Тот, кто слушает, помнит себя ребёнком с веснушками, а видит лишь туман — и качается, как лист, с тихой песней об ушедшем.","719":"Узник из окна видит лишь клочок неба и дерево — тишина лучше всех голосов. Он спрашивает смотрящего сверху: что ты видишь во мне? — и чувствует: с ним не всё кончено.","720":"Молящийся просит у Бога не бури, а скромного: маленький дом, огонь, немного лета на зиму. Когда придёт последний вечер, он выйдет ему навстречу, как в добрую сказку о доме.","721":"Наскучивший мир герой покидает на корабле с холостыми моряками, но за каждым берегом с весёлым именем ждёт та же тоска. Под конец голоса зовут его в глубину — плыть, не спрашивая, небо там или ад.","722":"Герой опускается лицом в чёрные волосы любимой и уплывает: мачты, маяки, запахи дальних берегов. В тёмных водах этой гривы он находит лазурный порт — и засыпает в гавани, которую она и есть.","723":"Низкое небо давит на город, как крышка котла, и герой зовёт в помощь всё живое: зелёный луг, колодцы, колокольный звон. Но в сердце уже стоит лагерем чёрный флаг похоронной думы.","724":"Герой помнит прежнюю жизнь под мраморными колоннадами: закаты красили бирюзовое море, слуги одевали его в роскошь. Теперь он скитается — тоску по той тишине не лечат ни корабли, ни вина.","725":"Герой ловит в гремящем городе один взгляд: гордая женщина в трауре, рука на маленьком стане. За этот взгляд он успевает полюбить и потерять — навсегда, так и не узнав её имени.","726":"Полдень жарит, вода шепчет рыболову у берега, и из волн поднимается русалка: сулит тёплые воды, покой и свободу. Он тянется к ней — и море берёт своё: больше рыболова никто не видит.","727":"Юноша заночевал в доме отца невесты, ночью приходит та, кого обещали в юности: она боится света и не пьёт вина — мёртвая пришла за данным ей словом. Утром юношу находят мёртвым в объятиях пепла.","728":"Гретхен не находит покоя за прялкой: руки обязаны работать, а сердце уже не здесь — оно ищет его поцелуй и взгляд. Стук колеса становится стуком сердца: покой потерян, пока он не вернётся.","729":"Мальчик спешит сорвать дикую розу, и она грозит: уколю — шип будет вспоминаться вечно. Он срывает её всё равно, и роза молча терпит боль: счастье, отданное добровольно, не жалуется.","730":"С новой любовью герой расцветает: мир пылает цветами, что было тяжёлым камнем — стало лёгким пёрышком. Он бросает старую сумку забот и бежит навстречу чувству: мир снова юн — и он с ним.","731":"Старый король Туле пьёт каждый вечер из золотого кубка — подарка умершей любимой — и плачет. Умирая, он бросает кубок в море: её дар должен уйти с ним, а не к наследникам.","732":"Поэта, что шёл через лес на праздник, убивают без свидетелей; умирающий зовёт журавлей — стая летит над убийцами. Позже в театре птицы выходят на сцену, и страх выдаёт убийц раньше слов.","733":"Мастер льёт металл в форму колокола, и пока металл плавится, перед нами вся жизнь: рождение, первый выход в мир, пожар, уход и возвращение. Готовый колокол висит на башне и говорит за всех.","734":"Дракон опустошает Родос, и рыцарь идёт на бой — но сперва очищает сердце от греха, без гордости. Он возвращается победителем: он сражался не только с драконом, но и с собой.","735":"Герой носит в груди целый мир скорби: горы не обнять руками, но их вес в каждом ударе сердца. Как Атлант, он держит небо из слёз и не просит замены.","736":"Герой смотрит в темноте на портрет возлюбленной, и лицо на нём оживает. Когда-то она плакала из-за его слов — теперь от его слёз темнеет картина: он плачет перед ней один.","737":"Серый берег, вода без волн, туман на крышах — город за заливом мёртв, как любовь, которую не вернуть. Герой смотрит издалека и слышит, как это молчание стучит в грудь.","738":"В рыбацком доме у моря любимая рассказывает сказки о подводных призраках, пока туман идёт от волн. Он видит её полные тоски глаза — и этот вечер остаётся с ним навсегда.","739":"Из больших болей герой делает маленькие песни: они летят на тысячах крыльев к той, что далеко. Песни найдут её двор, постучат в окно и споют то, чего он не смог сказать при встрече.","740":"Через сердце героя тихо проходит нежная любовь, и он просит соловья над её балконом стеречь её сон всю ночь. Пусть птица бережёт её дремоту: та же песня стережёт и его сердце.","741":"Валтасар пирует в сияющем зале — и вдруг на стене загораются огненные буквы, которых никто не хочет читать. Веселье обрывается: царь бледнеет, а той же ночью падают его город и власть.","742":"Два старых гренадера возвращаются из плена и узнают: император пал, дело кончено. Один плачет о ранах, другой о жене — а верный клянётся лечь в могилу с мечом и встать, когда освободят.","743":"Первая половина жизни героя — грушевое дерево, розовые ограды, лебеди под ясным небом. Вторая — зимняя стена: голые ветки, и не с кем идти через снег. Он один стоит посреди белого поля.","744":"В пустеющем вечернем городе герой спрашивает у неба, зачем поэты, когда время голодает. Ночь — как чужая страна: храмы закрыты, священники молчат, но слово хранится — поэт бдит, пока всё спят.","745":"Деревня зовёт всадника на помощь: за горой занялся огонь у чёрной башни. Он мчится ночью через лес, поднимается к призрачному пламени — и не возвращается. Наутро на башне находят только след.","746":"Рыцарь спрашивает у пастушки с золотой косой, чья корова. Её, смеётся она, — и смех её, и сердце тоже её, и оно не для рынка. Рыцарь сажает её на коня и увозит в свой замок.","747":"Двое молча едут в карете в сумерках — вдруг с холма доносится охотничий рог, и всё в них просыпается. Карета мчится за звон вниз, в долину огней, к жизни, о которой они забыли.","748":"Ночь опускается на долину: леса темнеют, всё утихает, и лишь один цветок поднимает голову к небу и ждёт. Так и в человеке есть тайна, что просыпается, когда весь мир спит.","749":"Вечером у моря герой слышит голоса над глубиной: тонкий звук идёт из бродящего ила ваттов. Он стоит на границе сна и яви — вечер говорит с ним голосами, которых не понять.","750":"Ночной поезд везёт людей с праздника домой по мосту через большую реку — смех в вагоне не смолкает. Вдруг мост рушится, вагоны падают в тёмную воду: веселье оборвано взмахом реки.","751":"Седой граф Дуглас возвращается из изгнания и падает на колени перед королём, прося вернуть имя и место. Король смотрит долго — и поднимает старика: верность снова встала у короны.","752":"Пантера ходит кругами по клетке: взгляд устал от тысяч одинаковых прутьев. Иногда сквозь тишину проходит образ зверя и умирает в сердце — сила жива, ходит кругами и помнит степь.","753":"Герой просит лето не кончаться, но осень уже созрела: виноград и яблоки в руках. Кто одинок — будет одинок: читать, писать письма, бродить по аллеям среди кружащихся листьев, ничего не обещая.","754":"Герой живёт с Богом за одной стеной: ночью слышит шаги, стук и молитву соседа — и прячет дыхание. Стена тонка, и он надеется, что однажды сосед постучит и найдёт его маленькую тёплую комнату.","755":"Юный корнет везёт письмо через осеннюю страну, а ночью в чужом замке видит сон о ней. Утром гремит атака — он бросается вперёд со знаменем. Письмо так и не дойдёт: его песня кончилась огнём.","756":"Под буком герой встречает трёх цыган: один ест, другой играет на скрипке, третий курит — все блаженно спокойны. Его вопросы о горестях мира тонут в их улыбке: груз спадает, песня остаётся.","757":"В бою пуля настигает героя, и верный товарищ закрывает его телом и держит руку. Раненый просит не плакать и обещает быть рядом всегда: они — один бой, пока бьётся сердце.","758":"Зимой, среди белого сна, одна цветочная звезда пробивается из-под снега и цветёт, не дожидаясь весны. Рядом с ней в сердце героя что-то оттаивает: чудо происходит сейчас.","759":"Граф Эберхард возвращается из Святой земли не с золотом, а с побегом боярышника, и сажает его у замка. Каждый год он приходит к дереву на память о пути: верность возвращается, как весна.","760":"Девушка отшатывается: прочь, страшный костлявый, я молода! А Смерть отвечает тихо: я не палач, а друг — дай руку, уложу мягко. Страх становится усталостью, усталость — сном.","761":"Кораблекрушение выбрасывает матроса на скалу посреди океана: ни воды, ни еды — только тысячи морских птиц. Он живёт их яйцами и царапает ракушкой слова на камне; шлюпка находит угасающего старика.","762":"Герой сидит на холме за живой изгородью, и потому сердце слышит бесконечное пространство. Он страшится и любит эту безбрежность — и тонет в ней, как в родном шуме.","763":"Герой вспоминает Сильвию: смех на окне, полуденное пение — юность обещала ей всё, но болезнь её унесла. Он спрашивает у весны, где её смех, — в ответ лишь чистое окно и тишина.","764":"Вечер субботы в деревне: девушка вышивает на пороге под дальний звон, пчёлы спешат к лугам, сердце ждёт праздника. Герой понимает: в ожидании радости больше счастья, чем в самой радости.","765":"Тихий вечер возвращает герою юность: солнце за холмом, корабль на горизонте, сад родного дома. Он бродит по памяти, как по опустевшей комнате, — ветер в листве отвечает за тех, кого нет.","766":"Весна гремит хором, а герой слушает одинокого дрозда на ветке и узнаёт в нём себя. Птица поёт не для праздника, а от собственной боли — и такая песня честнее всего весеннего хора.","767":"Над Адриатикой стоит замок Мирамар: отсюда Максимилиан отплыл за чужим троном, который обернулся расстрелом. Поэт читает море как книгу судьбы — и волны повторяют имя того, кто не вернулся.","768":"Летняя ночь над пшеницами, крик птицы в темноте — юноша с девушкой уходят из дома по тропе. Стук сердца, луна над полями: утро вернёт дом, но ночь останется их тайной.","769":"После смерти родителей братья остались одни, и на кувшин с водой садится оса — у неё тоже нет матери. Брат видит в ней себя: тоже сирота у кувшина — и с того дня они держатся друг за друга.","770":"Ночь в долине: всё спит, и лишь невидимый жасмин цветёт в темноте, посылая запах через поле к окну спящей девушки. То, чего никто не видит, всё равно дойдёт до её окна.","771":"Двое идут под летний дождь в сосновый лес: капли барабанят по коре и ветвям — лес поёт тысячу голосов. Они слушают, и то, что было укрытием, становится песней на двоих.","772":"Вечер опускается на холмы Фьезоле: закат красит оливы, террасы и далёкий город, каждое мгновение кажется последним золотым. Герой стоит на террасе: такие вечера можно только прожить целиком.","773":"В бою за Иерусалим Танкред смертельно ранит закованного рыцаря — доспех падает: это Клоринда, которую он любит. Он крестит её водой из шлема и остаётся с виной на всю жизнь.","774":"В тёмном углу покинутого зала висит забытая арфа — вошедшая девушка трогает струны, и та поёт, как молитва о прощении. Потом струны рвутся: только пыль помнит последний аккорд.","775":"Герой отдал бы мир за один её взгляд, небо — за улыбку, всё, что есть, — за поцелуй. Между первым взглядом и первым словом живёт вся любовь, какую человек способен вынести.","776":"Ласточки вернутся на балкон, пчёлы — к цветам, вернутся и слова любви. Но тот, ради кого всё это возвращалось, не вернётся: всё повторяется в мире, кроме одного человека.","777":"Пират с мачты слышит зов берега к богатству и покою — но под ним море, над ним звёзды. Он смеётся: его корабль — удача и свобода, и лучше погибнуть в шторм свободным, чем пленником на троне.","778":"Сердцеед Дон Феликс ночью идёт за призраком сквозь Саламанку — к склепу, где лежит Эльвира, которую он довёл до могилы. Рядом стоит его собственный труп: он мёртв давно, с тех самых пор.","779":"Сколько можно грустить, смеётся герой: жизнь коротка, следующий вдох не гарантирован. Кубок до края — не от отчаяния, а от ясности: сегодня пей, люби и пой.","780":"Поэт говорит людям: все мы — как одно тело, и чужая боль отзывается в каждом. Когда одному плохо, остальные не могут покоиться: равнодушный к чужой беде не заслуживает имени человека.","781":"Купец спрашивает у попугая, что привезти из Индии, и тот просит передать привет вольным птицам садов. Услышав ответ, попугай падает мёртвым — а затем вспархивает: смерть открыла клетку.","782":"Трое ощупывают слона в темноте: один держит хобот и видит водосток, второй — ухо и опахало, третий — ногу и колонну; все правы и спорят всю ночь. Утро покажет слона тому, кто перестанет кричать.","783":"Султан велел расписать зал: китайцы три года красят стены золотом, а греки просто полируют одну стену до зеркала. На смотре китайское великолепие отражается в зеркале и становится вдвое богаче.","784":"Кравчий, налей вино — весна вернулась. Ради чёрной родинки любимой герой готов отдать Самарканд и Бухару: пусть везир считает — хлеб с той, кого любишь, дороже трона без её взгляда.","785":"Юный Сохраб, выросший без отца, выходит на поединок с Рустамом — и не знает, кто перед ним. Рустам ранит его насмерть, и умирающий называет себя: это сын. Победа стала виной.","786":"Каменотёс Фархад влюблён в Ширин и ночами режет скалу — молот вместо слов о любви. Царь посылает ему ложную весть о её смерти, и Фархад умирает у горы: ложь убила верное сердце.","787":"Бахрам строит семь дворцов для семи красавиц: купол каждого — цвета своей планеты, и у каждой своя история. Царь слушает семь жизней и учится смотреть на мир не через корону, а чужими глазами.","788":"Страннику пора плакать над стёртыми следами стоянки: здесь стояли её шатры, здесь начиналась любовь. Дождь и ветер стёрли письмена на камне, но память о ней герой хранит — её время не берёт.","789":"Герой идёт, мечтая о дорогах, которых никогда не было: вот смогу — сверну туда. Но дорога откатывается назад, за спиной лишь следы следов и тропы троп — жизнь уносит следы его снов.","790":"Герою снится родник в сердце: во втором сне вода золотая, в третьем — звучит горькой жалобой. Он просыпается в слезах: страдание тоже течёт в нём, и даже сон не знает, что делать с этой водой.","791":"Поля Сории — серые края и зелёные холмы, суровая земля, которая не утешает, а просто стоит рядом. Герой видит в ней свою судьбу и любит выгоревший край без надежды и без отступления.","792":"Дона Инес умерла юной, простив Дона Жуана, который её погубил. В час смерти бретёра за душой приходит сатана — но приходит и её призрак: свет прощения вырывает душу грешника из тьмы.","793":"Любовь — буря в теле: обмирать, отваживаться, неистовствовать и замирать разом, терять себя и находить. Всё это в герое от одного взгляда на неё: она делает его ветром, огнём и землёй сразу.","794":"После бури корабль идёт к песчаному берегу: закат красит парус золотом, рыбаки встречают юношу у костра. Здесь жизнь проста, как дыхание, — счастье начинается там, где кончается корабль.","795":"За героем всюду ходит чёрная тень: у воды, в лунном свете, на дороге. Он зовёт — молчит, уходит — следует. Может, это потерянная любимая, а может, тоска, научившаяся ходить, — не уйти.","796":"Юный Тарафа едет через пустыню, зная: судьба несёт его к раннему концу. Он дерзко просит дожить до часа, когда скажет миру своё слово: лучше остаться в стихе, чем состариться в тишине.","797":"Старик Зухайр обходит враждующие племена и говорит вождям: за кровь заплачено — пора дать детям расти без страха. Его слова собирают врагов у одного огня — впервые за годы долина спит без оружия.","798":"Герой стоит у опустевшей стоянки: костры остыли, палатки ушли, краска на камнях выцвела. Он спрашивает время, всё ли проходит, — и слышит суровый ответ: всё, кроме того, что держит мир.","799":"Амр ибн Кульсум поёт за племя, чьего вождя убили: его щит не дрогнет, а конница — как наводнение. Он идёт мстить за отца с песней: правда на стороне тех, кто держит своё слово.","800":"Поэт-изгнанник перечисляет без ложной скромности: его знают конь под седлом, ночь в пустыне и перо — враги слышат его голос во сне. Изгнание его не сломало: гордость — дом, который носят с собой.","801":"На упрёк проповедника Абу Нувас отвечает смехом: вино — живой сок винограда, подарок земли, а у ханжи лицо черно от зависти. Лучше честное веселье, чем набожность напоказ: поэт занят жизнью.","802":"Антара — сын рабыни, и род не признавал его, но он поёт о Абле и дерётся так, что враги отступают. Пусть род клянётся кровью — он отвечает смелостью и возвращает себе имя, любовь и место у огня.","803":"Герой смотрит на луну и звёзды и спрашивает: что такое человек, что о нём помнят небеса? Над ним — дело рук Твоих, и всё же он увенчан славой: малый и увенчанный — вот и весь ответ.","804":"Господь — Пастырь героя: он лежит на зелёных травах и не боится зла даже в долине смертной тени. Стол накрыт перед врагами, чаша переполнена — доброта и милость следуют за ним все дни.","805":"Живущий под кровом Всевышнего не боится ни ночной стрелы, ни яда полудня, хоть тысячи падают рядом с ним. Ангелы хранят на всех путях — страх отступает, когда знаешь, чьи крылья над головой.","806":"Изгнанники плачут у рек Вавилона: хозяева просят песню, но как петь песнь Господню на чужой земле? Арфа висит на иве — пальцы не забудут игру, и песня ждёт возвращения домой.","807":"Герой поднимает очи к горам: откуда придёт помощь? Она от Того, кто создал небо и землю, — Тот не дремлет и хранит душу на всех дорогах. Путь не страшен тому, кто смотрит в горы.","808":"Ночью героиня встаёт с ложа и обходит пустой город, спрашивая у стражей на стенах о том, кого любит её душа. Чуть нашла — и не отпустила, пока не привела в дом матери.","809":"Положи меня печатью на сердце твоё, — просит героиня: любовь сильна, как смерть, и воды не зальют её пламя. Запечатанное на сердце не обменять на всё богатство дома.","810":"Иов требует у неба ответа за беды — и ответ приходит из бури: где был ты, когда земля основана? Небо не оправдывается — оно показывает величие, и вопросы человека растворяются: он замирает и молчит.","811":"Всему своё время: рождаться и умирать, разбрасывать и собирать камни, молчать и говорить. Герой находит в этом перечне покой: всё прекрасно в своё время — проживи своё честно.","812":"Герой видит Господа в храме: серафимы кричат о святости, а он ужасается нечистоты уст — серафим касается губ углём с жертвенника. Когда слышит вопрос, кого послать, первым отвечает: пошли меня.","813":"Изгнанный герой просит облако стать гонцом: пронести весть к любимой, что ждёт у окна на далёкой горе. Скажи ей, диктует он, что я жив, что помню — счёт разлуки ведётся до встречи.","814":"Царь Душьянта забыл Шакунталу из-за проклятия: когда она пришла во дворец, он не узнал её, и она ушла. Спустя годы рыбак находит в рыбе кольцо — память вспыхивает, и царь ищет её с раскаянием.","815":"Арджуна просит колесницу въехать между двумя войсками — и видит по ту сторону дедов, учителей и братьев. Лук падает из рук: убивать своих он не может — и опускается на дно колесницы в отчаянии.","816":"Арджуна видит истинную форму: тысячи лиц и глаз, воины обеих армий уходят в этот рот. Голос отвечает: он — время, рушащее миры; без него они лежали бы мёртвыми. Встань и сражайся.","817":"До Ланки — сотня йоджан воды, и Сита ждёт спасения: Хануман растёт в размерах, шагает на вершину горы и делает шаг в небо. Волны расступаются — он перелетает океан и достигает Ланки.","818":"Армия обезьян строит мост до Ланки: миллионы несут камни от гор к морю, и вода держит их, выстраивая дорогу. То, что тонет у одиночек, держится у всех вместе — след общего дела сильнее океана.","819":"Кунти приходит к Карне и раскрывает тайну: он её сын и старший брат тех пятерых, против кого он воюет. Карна прощает мать, но верен слову: обещает щадить её сыновей, кроме главного противника.","820":"Царь влюбился в дочь рыбака, и её отец требует трон для её детей. Принц Деваврата отрекается от трона и клянётся не жениться ради счастья отца — боги зовут его Бхишмой, страшной клятвой.","821":"Герой говорит ей: мы — как красная земля и проливной дождь. Дождь бьёт в рыжую землю, земля пьёт его до дна — и никто не скажет, где была граница: два стали одним.","822":"Герой оставляет пение в храме: если прятаться в святом углу, Бога там нет. Он у пахаря и каменщика — в солнце, в пыли, в одежде, пропахшей потом: соединиться с ним можно только в работе.","823":"Ребёнок пускает по реке бумажные кораблики, написав на каждом своё имя и название деревни: пусть кто-то далеко узнает его. Он грузит в них цветы и мечты: детство — вера, что мечту подберут далеко.","824":"У дома героини растёт старая казуарина: под её ветвями играли две сестры, которых больше нет. Дерево помнит их игры и раздаёт тень — героиня говорит с ним, как с друзьями детства.","825":"Сита слышит крик Рамы из чащи и требует от Лакшмана идти на помощь. Он знает, что кричит демон, но её упрёки заставляют уйти — и он возвращается на пустое место: оба были правы и оба проиграли.","826":"Лунный свет перед кроватью герой принимает за иней: поднимет голову — луна, опустит — и вспоминает дом. Та же луна, что и в детстве, но под ней чужая земля — тоска приходит тихо, как иней.","827":"Герой поднимает среди цветов чашку вина и приглашает луну с тенью: пусть нас будет трое. Луна не пьёт, тень пуста, но песня и танец делают их компанией — а прощаются до встречи в Млечном пути.","828":"На Жёлтой журавлиной башне герой весной прощается с другом, отплывающим вниз по реке. Одинокий парус уходит за горизонт — остаётся только вода, текущая к небу, и взгляд, что тянется следом.","829":"Столица разрушена и заросла травой: цветы вызывают слёзы, птицы пугают сердце. Вестей от семьи нет три месяца, волосы седеют быстрее тревоги — весна приходит и на руины, и это больнее всего.","830":"Герой смотрит на луну и знает: в Фучжоу жена смотрит на неё одна — дети не понимают, почему мама молчит. Он помнит её волосы в ночном тумане и мечтает: когда-нибудь луна высушит наши слёзы вместе.","831":"Повозки скрипят, солдаты уходят на границу, родные бегут за ними по мосту в пыли. Старый солдат помнит: его отправили на войну в пятнадцать; дома мужей не осталось, и поля пустеют без сыновей.","832":"На пустой горе никого нет — лишь где-то в глубине слышны голоса. Возвращённый свет падает в тёмный лес и озаряет зелёный мох: мир есть, но он не мешает одиночеству.","833":"После дождя в пустых горах луна озаряет сосны, ручей течёт по камням, бамбук шумит от прачек, лотосы качаются под лодкой. Пусть весна уходит — я останусь в этих горах, где всё на своих местах.","834":"Герой отдыхает на пустой горе весной: цветы корицы падают сами, луна встаёт над хребтом — и птицы с криками несутся к ручью. От их голосов тишина становится глубже: покой не ломается.","835":"Ночью на реке герой слышит из соседней лодки звук пипы: музыкантша была звездой столицы, а теперь стареет на лодке с купцом. Два изгнанника плачут вместе — чужая боль стала общей через музыку.","836":"Император посылает даоса искать душу умершей любимой — находит её на бессмертном острове, и она отдаёт половину сломанной шпильки. Дворец пуст, но клятва жива — печаль не кончится даже у неба.","837":"Герой пьёт до утра и спрашивает луну: с каких пор ты такая ясная? Брата не видел семь лет — люди встречаются и расходятся, как луна. Его пожелание: обоим жить и смотреть на одну луну за тысячи миль.","838":"Вдовец выходит к морю и поднимается на холм, где они жили: всё место говорит её именем. Она была драгоценным зеркалом его дней — теперь в доме холодно, и он плачет на берегу так, что море слышит.","839":"Старый поэт записывает два монолога бедности: в одном дом ещё держится, в другом — дырявая крыша, голодные дети просят риса, и отцу нечего дать. Поэзия нужна там, где ребёнок просит есть.","840":"После её ухода герой смотрит на весеннюю луну и сомневается: та ли это луна, та ли весна? Небо кажется прежним, а мир изменился — лишь он остался прежним в мире, где всё на месте, а ничего нет.","841":"Старая женщина у окна видит, как дождь оставляет последние капли на отцветших цветах, и узнаёт в этом свою старость: годы прошли мимо тихо, как смена сезона. Краска ушла с лепестков — и с её лет.","842":"Путник у старого пруда, где тишина без дна: лягушка прыгает в воду, один звук на миг рвёт покой, и тишина после него глубже прежней. Вся жизнь — один звук, после которого слышно всё остальное.","843":"Путник идёт по полю прошлых битв, где травы выше шлемов выросли там, где мечтали и гибли солдаты. Сто лет поле зеленеет, будто ничего не было, — память прячет земля, и остаётся она только в его стихе.","844":"Наблюдатель у жёлтого поля рапса в сумерках, где луна встаёт с востока, а солнце уходит на запад. День и ночь на мгновение висят над одним полем, и в этот час можно не спешить.","845":"На летнем поле сходятся в поединке две лягушки, и худой лягушонок проигрывает толстому. Но рядом есть поэт, который громко болеет за слабого: в мире, где всё решает сила, маленький боец не один.","846":"Толстая улитка ползёт на Фудзи смешно медленно, но поэт не смеётся, а подбадривает: гора велика, путь честен. У каждого своя скорость до вершины, и даже самая медленная доберётся, если не бросит.","847":"Поэт на дороге предупреждает пичугу, как ребёнка: большая лошадь близко, отойди на шаг. От такой мелочи мир становится добрее — забота звучит даже о воробье.","848":"Человек среди руин и в изгнании на самой глубине скорби вспоминает: Господне милосердие не кончилось — с каждым утром оно приходит снова, как манна в пустыне. Этого хватает, чтобы встать и ждать.","849":"Человек весь день носит чужую улыбку — на работе, в толпе, дома, а под ней заплаканные глаза. Ночью маска сползает, и он признаёт её цену; с рассветом она вернётся, но слушатель уже видел изнанку.","850":"Проповедник в эпоху рабства читает о Моисее и фараоне так, что надзиратель слышит благочестие, а свои — план освобождения. Заметив соглядатая, он тихо отходит назад, и о главном остаётся молчание.","851":"Странник бродит по затонувшему тронному городу: башни, купола, статуи, копившие свет, — ни ветра, ни волн, только лунная тишина. Весь город глядит на гостя и выжидает: море однажды поднимет его.","852":"Ночной житель чувствует душу города над крышами — гиганта из фабрик и дыма, питающегося железом и потом. Город венчает себя богом из света, и герой остаётся: поклоняться и бояться раствориться.","853":"Муж в полночь мчится домой и у старой церкви видит пляшущих ведьм под скрипку покойника; крик гасит свет, нечисть несётся следом. Спасает мост, но конь лишается хвоста: за любопытство выставляют счёт.","854":"Влюблённый будит Коринну в майский рассвет: весь город ушёл в зелень, у всех цветы и ветки. Но лепестки осыплются, роса высохнет, юность умрёт, — они уходят в праздник и берут его целиком.","855":"Повешенные говорят с виселицы к живым: мы не святые, и мир прав, что нас устранил, — только не смейтесь над мольбой. Просим не справедливости — а памяти: вдруг Тот, кто судит всех, мягче людей.","856":"Аристократка едет к мужу на каторгу; губернатор пугает её зимой, требует отречения — она принимает всё и не плачет. Старик признаётся: лишь испытывал её, и плачет сам — запрягать, три дня до мужа.","857":"Ночью из башни в горах зовёт женский голос, обещающий тепло; откликнувшиеся гибнут, утром река несёт их тела. Последний всадник мчится на зов и гибнет, не доезжая, — и голос навсегда затихает.","858":"Поэт обещает переполненному залу: через час вы выйдете к деньгам, а я расточил слова впустую. Сытая толпа топчется по его хрупкому, как бабочка, сердцу — и в финале хохочет ей в лицо.","859":"Газета с утра — окно в чужое горе: кражи, пожары, письма обманутых, смерть безымянных. За сводками горожанин слышит голоса тех, кого никто не спас, и любопытство становится гневом на глухой город.","860":"Когда город затихает, рассеивается самообман дня: совесть поднимает из темноты забытое — разговор, от которого не отмолчаться. Утро не приносит оправдания — герой остаётся наедине с приговором.","861":"Муж после ссоры признаёт жене: оба вспыльчивы — давайте не копить обиды, а ругаться открыто и до конца. После честной бури любовь возвращается горячее прежнего, и рассвет застал их примирёнными.","862":"Вдова с дочерью нанимают кухарку — подозрительно дешёвую. В воскресенье из церкви хозяйка застаёт «кухарку» за бритьём у зеркала дочери: под платьем мужчина. Тайна сбегает, не взяв платы.","863":"На ночном балу в саду маркиза Эулалия кружит двух соперников сразу — виконта и юного аббата — и непрерывно смеётся. Но победит не виконт и не аббат: ночью её обнимет невидимый паж, ставший её поэтом.","864":"Поэт стоит с девочкой Маргаритой у моря и говорит несказанную нежность через сказку: принцесса летит срезать звезду с неба. Сказка оказывается признанием — остаётся хранить добрую мысль о сказочнике.","865":"Пастух молится Богу по-домашнему — вычесать, принести молока, — и Моисей обрывает: недостойные слова. Бог упрекает: каждому я дал свой язык, мне был дороже живой лепет — простоту уже не вернуть.","866":"Женщина в разлуке осенней ночью поднимается в лодку и спрашивает: кто пришлёт письмо через облака и когда вернутся гуси-вестники. Тоска одна на двоих, и печаль лишь перекочёвывает с лица в сердце.","867":"Спасённый человеком медведь ходит за ним тенью и, потеряв терпение от мух над спящим, мечет в них большой камень: мухи улетают, а он падает на лицо. Благодарность без понимания оказалась опасной.","868":"Человек видит, как река течёт в море без возврата, а в зеркале утром чёрные волосы, к вечеру — снег. Жизнь коротка: звать гостей, талант не пропадёт. В финале он с другом топит тоску в вине.","869":"Крошечный корабль окружает 53 испанских вымпелов с приказом сдаться — капитан отказывается и весь день бьётся: палуба в огне, командир дважды поднят с ранами. К ночи корабль уходит на дно несдавшимся.","870":"Граф привязывает юного пажа к необъезженной дикой лошади и пускает её в степь. Сквозь реки, лес и грозу, за ними волки — но казаки подбирают измученного наездника, и жертва вырастает в гетмана.","871":"Найденный в земле латунный доспех начинает рассказ: юный воин бежал с любимой на ладье сквозь шторма и абордажи до берега, где поставил башню. То, что отец хотел разделить, смерть соединила навсегда.","872":"Трое гуляк клянутся найти и убить Смерть, а старик у дороги показывает дуб — под ним гора золота. Двое решают убить третьего, третий несёт им яд — и к утру у дуба три тела: они нашли то, что искали.","873":"Монах ненавидит кроткого соседа по келье и составляет список подлостей — от порчи сада до подловлённых фраз. А тот невозмутимо молится и подрезает цветы: ссоры нет — война идёт в одной голове.","874":"Патруль ловит монаха-живописца после загула, и тот откупается исповедью: сирота, наказанный за живые лица вместо условных святых. Искусство и есть его молитва — герой уходит к незаконченной фреске.","875":"Рыцарь и жена старика встречаются глазами через площадь и молчат: он по чести, она по долгу. «Завтра» откладывается годами, пока седые не бегут вдвоём — но страсть умерла, и Бог обращает их в камень.","876":"Двое из ночного танца замирают у окна злачного дома: скелетообразные пары кружат вальс заводных кукол. Спутница заворожена — на рассвете праздник осыпается прахом, и любимая остаётся в пустоте.","877":"В переполненном клубе девушке кричат и кидают деньги. Но улыбка фальшивая, взгляд уходит сквозь толпу: она исполняет восторг, которого не чувствует, — овации скупают всё, кроме неё самой.","878":"Скиталец по отчаянным морям рассказывает, что привело его домой: не корабль и не ветер, а ясное лицо одной женщины и свет в окне, ждущем странника. Вся одиссея умещается в этом взгляде.","879":"Спустя годы после смерти жены вдовец слышит ночью в саду её голос — тёплой и слегка недовольной интонацией. Он выбегает в мокрую ночь, но образ дрожит и расходится: остаются ветер и падающие листья.","880":"Ночная река проплывает тело женщины, и толпа готова к насмешкам — голос останавливает их: она чья-то дочь, её прогнал дом. Последнее слово может быть добротой или ударом — выбрать должен стоящий.","881":"Царь попытался сдвинуть гору танцующего бога — и был прижат к скале пальцем. Запертый под ней, он тысячу лет поёт гимн самому танцу, который его сокрушил, — пока бог не пляшет в такт побеждённому.","882":"Человек разбит — сердце расколото, как кувшин, — но голос говорит: трещина — не дыра, а проход для звука. Он встаёт и танцует не вопреки боли, а сквозь неё — и кружение возвращает ему тело.","883":"Крепость держит последнюю ночь осады: туча врага давит стены, знамёна окаменели от холода. Гонец несёт табличку — помощь обещана; его посылают не за спасением, а чтобы знали: крепость стоит.","884":"Героиня плачет: любовник обманул и бросил её. Подруга даёт жёсткий совет: не трать слёзы на того, кто отдал ласки за пустые слова, — купи платье. И та, кого жалели, поднимает голову выше обидчика.","885":"Жена мудреца превращена проклятием мужа в камень и тысячу лет стоит в выгоревшем лесу. Юный принц узнаёт её историю и касается камня — тот распадается, и она впервые за века вдыхает воздух.","886":"После победы и долгого изгнания царь летит домой на колеснице в ночь безлунья — и город зажигает лампады в каждом окне. Его встречают не победителем, а светом: каждый дом утверждает, что ждал.","887":"Воин просит подвести колесницу между двух армий — по обе стороны одни и те же люди: дедов, учителей, друзей. Лук опускается, но возничий говорит как никто прежде — и к рассвету воин берёт оружие.","888":"Нищий друг детства царя идёт к нему с даром: горстью риса. Царь срывается с трона, моет гостю ноги и сам ест его рис; гость ничего не просит — а дома вместо хижины ждёт дворец.","889":"Поэт не может уснуть после известия о ссылке друга. Во сне тот приходит и говорит о слёзах, — и поэт просыпается с холодной кожей: вдруг это было прощание? За окном река и осенние листья.","890":"Ребёнок предлагает матери игру: стать цветком чампы и падать ей на колени в час молитв. А когда он снова станет мальчиком, она спросит, где он пропадал, — и он знает ответ, которого не скажет.","891":"Бедуин предан псу так, что весь квартал знал об этом, — но пёс умер от голода: у хозяина была сумка с едой, которую он не делил без платы. На вопрос соседа: слёзы ничего не стоят, вот и плачу обильно.","892":"Горец, спасаясь с поля битвы, стучится в дом старика, — но тот отвечает о сыне, погибшем в том же бою, погибшем стоя. Приюта нет: беглец уходит в ледяную ночь, и метель замыкает его след.","893":"Ночной стан после боя: усталые солдаты у костров, и певец поднимает голос — хвалит живых, павших, славу отцов и землю. Песня собирает разбитый стан в единый хор — толпа на миг становится братством.","894":"Ермак и вольная казачья дружина в боях, зиме и голоде отбирают у хана Сибирь — а после победы измотанные казаки засыпают. Враг бьёт ночью: атаман тонет в ледяной реке — сердце дружины ушло под лёд.","895":"Вражеский отряд врывается в дом и требует провести к правителю — крестьянин соглашается и заводит солдат в глухую топь. Те понимают обман, когда трясина сомкнулась: выхода нет ни для них, ни для него.","896":"Через двадцать лет поэт возвращается в места ссылки: тот же холм и роща, но между знакомыми соснами — поросль самосева. Он не увидит, как чаща станет лесом, — но другие будут жить в её тени.","897":"Годы назад поэт сидел в ссылке, и единственный друг приехал через снег — вечер спас ему рассудок. Теперь тот на каторге, и поэт посылает ему в Сибирь голос дружбы — сквозь кандалы и вёрсты.","898":"В темнице сидят человек и приручённый орёл. Птица подступает, смотрит в глаза и машет крылом, как оклик, — и узник договаривается с ней о побеге вдвоём: свобода приходит через союз двух пленников.","899":"Дети с малых лет уходят на фабрику: вместо школы и песен — станки, смена и ночной цех, детство украдено до последней колыбельной. Взрослому миру брошен без ответа вопрос, кто вернёт отнятое.","900":"Человек прощается с любимой и просит не помнить его тёмных дней — тоску, злобу, ревность, — а оставить себе только светлое. Он отпускает её налегке: вся тяжесть их истории остаётся при нём.","901":"Помещик уезжает на охоту, оставив мечтательную жену, а застрявший в деревне франт весь вечер показывает ей столичный шарм и ночью пробирается в спальню — вместо романтики получает звонкую пощёчину.","902":"За окном бушует метель, а в доме кот мурлычет у печи и мальчик дремлет на ковре. Мать будит его — пора идти спать; ребёнок послушно уходит, а кот даже не двигается: у дома есть свой страж уюта.","903":"Летний вечер: из поля — топот, коней гонят в ночное. Пастушата едут верхом со стадом: ночь при звёздах, бабушкины сказки и вахта до утра — впервые ребёнок чувствует себя хозяином целого табуна.","904":"Охотник гонит оленя, пока тот не падает издохшим у источника, — и называет ключ «Оленьим родником». Но пастух: трава тут чахнет, овцы обходят место, птицы не поют — и герой отрекается от охоты.","905":"Два пса — кесарь богача и лохматый Дугалд у бедняка — толкуют о хозяевах: у богача сытость, но за фасадом скука и расчёт; у бедняка работа до пота, зато дом, где смех. Рослый завидует лохматому.","906":"Фермеры Киллингворта решают истребить всех птиц, ворующих зерно, — поэта-заступника высмеивают. Весной тишина, а следом — полчища гусениц: поля гибнут под корень, и город выкупает птиц обратно.","907":"У пиктов — секрет верескового напитка; короли берут живыми отца-пивовара и сына — за рецепт жизнь. Король убивает сына на глазах отца — тот отвечает: сын мог дрогнуть, он нет — тайна уходит в землю.","908":"Королева созывает племена к мести: за разграбленную страну, за поруганных дочерей, за чужие храмы. Мятеж кончается смертью королевы накануне победы — свобода достанется тем, кто её не увидит.","909":"Апрельская ночь: всадник ждёт сигнала — один огонь или два. Огни зажглись — он мчится по деревням, будит фермеров, к рассвету ополчение стоит у моста с ружьями: один человек перевернул утро.","910":"Голос к молодым: цветы осыпаются сразу после рассвета — лучшая пора жизни коротка, не откладывать ни танцы, ни признания, брать всё за сегодня. Срок — не враг, а стимул: ведь всё на время.","911":"Бешеная стая травит племя в углу, и голос оттуда поднимает своих: умереть — стоя, падать — лицом к врагу, с открытыми глазами. Даже в самой гибели есть выбор — он отнимает у палача главное.","912":"Красавица бросает перчатку в львиную яму, проверяя рыцаря. Тот прыгает, забирает её меж львиных лап и живым выходит наверх — затем швыряет её даме в лицо и уходит: любовь, требующая смерти, не любовь.","913":"Воина привозят мёртвым — жена не плачет, стоит камнем над телом; подружки боятся: не выплачешь горе — убьёт. Слова о славе не работают — пока служанка не подносит к коленям малыша: слёзы прорываются.","914":"Зритель полуночного спектакля: невидимая труппа ангелов играет пьесу «Человек», а в зале молча сидят черви. В финале героя пожирает червь-чума; занавес в крови, свет гаснет — черви довольны.","915":"Солдат Бен возвращается героем — но без ноги, и Нелли взглянула на культи и передумала: она любила целого красавца. Он отвечает остротой и уходит с прямой спиной: она потеряла больше, чем он.","916":"Ветер срывает с хижины старика соломенную крышу; вечером дождь, ночь без сна. И среди этой беды герой мечтает возвести тысячи крыш для всех бедняков — пусть сам остаётся под открытым небом.","917":"Осеннее полнолуние: флейта плывёт над посёлком, и каждая девушка бросает дом — насквозь в дождь. Пастух-бог отсылает их к долгу, но в лунном лесу танцует с каждой так, что никто не замечает соседки.","918":"Ткач не выбирает между храмом и мечетью: божество живёт не в Камне и не в Каабе — там, где разбито сердце и стёрты ладони. Обе толпы давят, но он отказывается от обоих и остаётся у станка.","919":"Жена двадцати лет ожидания пишет мужу: двор полон женихов, едящих её хлеб; сын почти перестал спрашивать про отца. Она ткёт и распускает ткань каждую ночь — и просит не подвига, а ответа.","920":"Ласточки свили гнездо на балке дома: всё лето родители носят им еду. Но крылья крепнут, и птенцы улетают, не повернув головы, — а рядом плачет старик: его сын тоже уехал и не вернулся.","921":"Человек возвращается с войны и плена: жена замирает, будто пришёл призрак; дети не узнают отца. Ночью хозяева зажигают свечу, и двое сидят в её пламени — только с утра страх отпускает.","922":"Старый поэт видит танец с мечом ученицы Гунсунь — и вспоминает детство: полвека назад сама госпожа танцевала так, что о чуде говорили во дворцах. Империя разорена — поэту некому рассказать.","923":"Царь, не умеющий отказать в приглашении, играет в кости с шулером: уходят богатства, города, братья, свобода. Под насмешки зала он ставит жену — и теряет её; величайшая добродетель остаётся нищей.","924":"Герой и дочь враждебного царя видят друг друга через окно чужой крепости; путь между ними — её косы с башни. Она говорит: пусть лучше посмеют меня, чем отдать любовь страху, — и отцы идут на мир.","925":"Человек видит свою жизнь как ткань, сотканную мастером, — никто не знает, в какой миг кончится нить. Ткань пачкается и изнашивается, но герой не ропщет: обещает вернуть мастеру её целой и чистой.","926":"У стены — зелёные горы, вокруг — белая вода: здесь расходятся друзья, один — за десять тысяч ли. На прощание — взмахи рук, и лошади ржут: сдержанный человек не плачет — плачут его кони.","927":"Всю зиму деревня сидела взаперти: сугробы, тишина, старики у очага. Утром снега уходят — улицы взрываются: детвора высыпает на дворы, крик и бег. Клетка снега сдалась за одну ночь и проиграла без боя.","928":"Две собаки клянутся друг другу в верности до гроба — окрестные говорят, такой дружбы не бывало. Но при первом дележе брошенной кости клятвы рушатся: ласка сменяется огрызанием и дракой.","929":"У старой коровы утром увезли телёнка — последнюю её привязанность; она всю ночь не ест, скребётся в стойле и ждёт у двери, как ждёт мать, думая, что ребёнок ушёл на траву. Люди не открывают ей правды.","930":"Обезьяна весело смеётся в зеркале над «чужим» зверем, а медведь тихо объясняет: зверь в стекле — она сама. Насмешка оборачивается на неё: чужие недостатки видны издалека, свои — никогда.","931":"Щука — хозяйка реки — из честолюбия берётся ловить мышей в амбаре, как кот: кот отговаривает, но она гордо идёт в чужое ремесло и оказывается беспомощной и смешной. Своё дело лучше чужой славы.","932":"Артист любит ночной театр больше будней — занавес, свет, маски, чужие судьбы за три часа подмостков; реальность бледна, а правда ярче только на сцене. Он выбирает игру, а не подлинник.","933":"Брат пишет сестре: вокруг полно учителей, доказывающих, что жизнь уродлива, — не слушай их, она прекрасна, и я приеду показать сам. Обожжённый судьбой человек становится защитником её чистоты.","934":"Герой пишет любимой в чужой город: не торгуется, не унижается, письмо в грубом насмешливом тоне. Но за маской силы тоска — он ищет её глазами в каждой встречной: отказ просить выдаёт ожидание.","935":"После каторги в семью возвращается дед, о котором взрослые молчат, — но внучка расспрашивает, и через рассказы о молодости и мятеже он оживает, а тайна становится наследством.","936":"Над колыбелью звучат две песни-судьбы: одна учит кротости и благодарности за любую долю, другая зовёт к борьбе с неправдой. Взрослый решает, какая останется, — выбор делается до первых слов младенца.","937":"Поэт говорит с грядущими разрушителями его культуры: не запирает дверей — готовит пир, зажигает свечи и встречает бурю как гостью, последний из уходящих. Он уверен: за разгромом придёт жизнь.","938":"Герой ждёт любимую — она выходит замуж за обеспеченного, и его крушение вырастает в бунт против бога, денег, купивших её выбор, и власти. Брошенный становится судом над миром.","939":"Весенняя ночь: соловьи поют бесплатно для всего мира, но в темноте их ждут ловцы, и песня, что дарила радость всему лесу, становится товаром в клетке. Воля не должна продаваться за чужое удовольствие.","940":"Над озером — стены старой тюрьмы, но взгляд поэта поднимается выше камня: бессмертный дух живёт в темнице ярче, чем на воле. Годы и замки рушатся, а свободная мысль всё так же летит над водой.","941":"Герцогиня гаснет в замке мужа-тирана. Приезжает старая царица цыган, видит клетку и шепчет: «уезжай». Ночью та уходит со станом — учиться свободной жизни у тех, у кого только дорога.","942":"Влюблённые пьют вино — и на его крыльях взмывают над миром: день и чужие глаза внизу, впереди страна вечного вечера, где всё молодо и их. Утро отберёт полёт — но ночь уже подарила его.","943":"Чёрные полки встали под знамя, хотя страна не верила: они шли в атаки, умирали за свободу, победили вместе со всеми. Поэт требует отдать им место в строю — и права, за которые они платили кровью.","944":"Гимн телу: мужское, женское, стареющее — всё свято, в нём душа. В сердце — аукцион: плоть чернокожего на продаже, и поэт кричит: это не мясо на вес, а вселенная. Кто презирает тело, презирает душу.","945":"Поэт вырос умом в одном мире, а кровью принадлежит другому, и ни один не принял его целиком. Он не выбирает между мирами — признаёт боль двойного рождения своей правдой, а не дефектом.","946":"На «святой» праздник сирот богатейшей страны ведут в собор: их пение — дрожь от холода. Поэт судит: свят ли это, когда дети голодают? Там, где таковы с детьми, не бывает лета — там вечная зима.","947":"Приговорённый поэт пишет завещание и раздаёт себя: матери — молитвы, возлюбленной — юность, врагам — желчь, палачу — гордость. В каждой строке шутка и нежность: прощание стало отмщением смехом.","948":"Усопшую навещает единственная гостья — посмертная совесть. Она сядет над гробом и начнёт допрос: во что превратила красоту? как потратила молодость? — ответить некому: клад растратан.","949":"Старая плантация пуста, поле заросло. Свидетель помнит: банджо, танцы до темноты, смех на весь квартал — всё ушло с людьми. Теперь на месте танцпола трава — музыку заменяет ветер.","950":"Поэт пишет надгробие псу: красота без тщеславия, сила без дерзости — добродетели человека без порока. Пёс был единственным другом, ни разу не предал, — похороны становятся тихим упрёком обществу.","951":"Петуху снится вещий сон, но жена высмеивает: сны от переедания. После спора сон забыт — наутро лис крадёт петуха, сыпя комплименты. В зубах петух просит крикнуть победу — и взлетает из открытой пасти.","952":"Жена умоляет поймать золотую лань; муж уходит, охраняет брат. Из лесу — крик голосом мужа; она в панике отталкивает защитника: ты рад моей гибели. Брат уходит — враг приходит к открытой двери.","953":"Десять лет пиров: танцовщицы, вино, бессонные ночи. Проснувшись, он видит: это был один сон — молодость потрачена, за спиной только слух о легкомысленном госте, чужая насмешка вместо имени.","954":"Сын уходит в дальние края; ночь перед дорогой мать шьёт ему одежду — стежок к стежку, боясь, что вернётся не скоро. Он — травинка, она — солнце: чем благодарить за весну? Ответ один — помнить.","955":"Владыка окружён на последнем берегу: враги поют ему поражение, рядом конь и любимая. Он отказывается от плена — последний прорыв: единственное, что не отняли, — право выбрать свой конец.","956":"Уехал юношей — вернулся седым стариком. Дети на родной улице с любопытством смеются: дедушка, откуда вы? Он был здесь всю жизнь, но дом его не узнал — и отвечает шуткой, чтобы не заплакать.","957":"Радха ждёт любимого — он приходит с другой; она уходит в ночной лес, он ищет её и просит простить. Она открывает дверь с условием: пусть восхищённый миром завяжет ей сандалии.","958":"Праздник на вершине — а герой в чужом городе. Он знает: братья сейчас взойдут на гору, наложат ветки и заметят — одного не хватает. Дома его ждали, и тоска идёт в обе стороны одновременно.","959":"Слон зашёл в озеро — крокодил схватил за ногу, и тысячу лет они борются, не сдаваясь. Отчаявшись, тот зовёт на помощь — бог спускается с неба, убивает хищника и милует его: высшая сила не мстит.","960":"Воин умирает — спасение в траве с одной горы; обезьяна не может выбрать нужную среди склонов и несёт через небо всю гору целиком. Вместо одной травинки приносят весь мир, где она растёт.","961":"В белой пустыне под серпом луны ждёт конь чистой породы: сила не доказывает себя, пока её не позвали честно. Дождётся золотой узды — и по осенней дороге покажет, кто он.","962":"Под окнами проснувшегося бьют в барабан: весна рвёт узлы, сбрасывает тяжёлые одежды и тащит душу танцевать. Праздник уже идёт без него — осталось выскочить и влиться.","963":"Отплывающего поэта останавливает с берега песня: друг Ван Лун пришёл прощаться с сотней товарищей и весельем. Тысячу футов глубины пруда дружба перекрывает без остатка.","964":"Ночной патруль видит, как просыпаются фабрики: печи дышат огнём, колоссы гнут металл, стеклянные крыши светятся. Спящий город превращается в дымящееся божество, которому невольно служат все вокруг.","965":"Любовь пришла — и героиня строит алтарь из шёлка, перьев, золота и плодов, потому что обычный мир мал для её радости. Счастье обслуживают, как храм.","966":"На балах новый вальс обнимает пары вплотную: матери в ужасе, дочери в восторге, и запрет становится лучшей рекламой. Танец, который проклинали, побеждает свет без единого аргумента.","967":"Ревнивый старик, хитрая жена и два воздыхателя разыгрывают фарс с притворным потопом и лодками под потолком. Обманщик обманут обманщиком — позор, травма и смех деревни достаются каждому.","968":"Певчую птичку ослепили ради песни, а она поёт без злобы, будто благословляет. Поэт не может оправдать людей — птица прощает то, в чём он бессилен, и её песня громче его обвинения.","969":"Влюблённый теряет любовь того лета и прощается не с ней, а с собой прежним. Годы спустя он предвидит тот же разговор о цветах с внуком — и улыбается сквозь осень.","970":"Двое бегут от наёмников сквозь весеннее половодье: кони тонут, возлюбленную казнят — жизнь предложили за измену сердцу, она выбрала смерть. Любимый выживает и остаётся свидетелем её выбора.","971":"Пастух зовёт возлюбленную жить среди долин: розы, овечки, песня соловья — весь мир к её ногам, если останется. Взамен золота он предлагает весь свой мир, и это звучит как достаток.","972":"Застенчивый парень провожает девушку до порога, а дома под банджо снова ждёт её — сердце поёт раньше признания. Завтра он уже «случайно» назначит ей встречу.","973":"Герой возвращается в старый дом, где скамейка и стул на местах, — но ребёнок, мать и танцы давно умерли. Он стоял в раю и не разглядел счастья; теперь перед ним только пустые стулья.","974":"Самодеятельные актёры играют трагедию о любви перед знатным двором, а зрители посмеиваются. Провал оборачивается подарком: смех зала оказывается тем единственным, чем спектакль можно спасти.","975":"В темнице тело цепляется за жизнь, сердце просит покоя — человек разделён на двух подсудимых, и проигравшим в их споре будет он сам. Остаётся ждать суд, который выше обоих.","976":"Мать всю жизнь носила повязку на глазах, чтобы не видеть мир, где слеп её муж, — война отнимает у неё всех сто сыновей. Над полем трупов она снимает повязку и первым взглядом судит бога.","977":"Изгнаннику сообщают: война кончилась — слёзы на книгах сменяются смехом жены и детей, вино и песни. За одну ночь радость пролистывает весь обратный путь: весна, вода, ущелья, родной город.","978":"Город встречает возвращающиеся войска: трубы ревут с крыш, барабаны дробят шаг, дети сидят на плечах отцов. Парад оказывается не про победу — это единственный способ сказать вернувшимся: вы живы.","979":"У героя две родины: Куба с болями её рассветов и старая Испания с пышной смертью. Выбор не между хорошим и плохим, а между жизнью и смертью — он выбирает жизнь и берёт её цену на себя.","980":"Жена спрашивает в письме, когда он вернётся, — он честно отвечает, что даты нет, и описывает ночную влагу над прудом. Разлука обещает стать воспоминанием: тот же дождь у свечи, но вдвоём.","981":"Старую дорогу через поле выжигали дотла, а трава вернулась зелёной и провожает уходящего друга. Огонь не убивает то, что растёт изнутри: сожжённое первым встречает весну.","982":"Дождь прибрал утреннюю пыль у хижины, и друг наливает ещё кубок: за горами его ждёт чужой край без единого знакомого. Вместо слов «не уходи» — поддержка одним кубком перед пустотой.","983":"Она спасла героя нитью и мечом, а проснулась одна на чужом берегу — без отца, дома и имени. Письмо-обвинение уплывает за ним: она не просит вернуться, она требует, чтобы её гнев прочли.","984":"Жена узнаёт из знамения, что муж умрёт через год, и в назначенный день идёт за ним в лес. За богом смерти она шагает до конца мира и говорит с ним, пока смерть не уступает, — муж остаётся жив.","985":"Ребёнок родился седым, отец счёл это позором и оставил на вершине — гигантская белая птица унесла младенца в гнездо и вырастила как сына. Из выброшенного людьми вырос великий герой.","986":"Мальчишку ловят по всему посёлку с украденным маслом, и мать требует показать рот: губы в масле, а в раскрытом рте сияет вселенная. За наглым враньём обнаруживается целый мир.","987":"Поэт пишет другу из скучного города: вино не радует, песни не поднимают, и мысли о друге текут рекой без края. Всё здесь пусто без него — работает только сам факт этого письма.","988":"В обычном саду встречают придворного певца минувшей эпохи: он пел императору, теперь странствует среди чужих цветов. Оба без единого слова прощаются с целой эпохой, которой больше не будет.","989":"Голос, под который останавливались пиры, годы спустя разливает вино за стойкой: судьба продала певицу. Он записывает её историю — дважды встретил и дважды не узнал мира.","990":"Девушка сбежала с любимым через стену — семья прокляла её, и дорога домой закрылась. Годы спустя она признаёт: колодец даёт серебро, а любовь дала стыд, и побег обернулся изгнанием на всю жизнь.","991":"Ради любимого она предала отца и дом, а он уже готовит свадьбу с другой. Она пишет ему: на торжество придут её боги — спасай их обоих, пока вина не превратила её в то, чего он боится.","992":"Единственное его имущество — чистое сердце: двор предлагал лгать ради карьеры, он выбрал изгнание и путь через бурю и реки, где смерть в воде — победа, а не поражение.","993":"Пока зима правит империями, у героя вернулась личная весна: воздух сияет, в душе распахнуты окна, на каждом балконе поют. Праздник начинается с одного пробудившегося — спящим остаётся зима.","994":"Подруги зовут героиню на праздник фонарей, но в старой столице он был другим — теперь чужой. Она остаётся в темноте без света и слушает барабаны за стеной: участница стала слушательницей.","995":"Герой не поменяет свою разбитую корону на чужой трон: царство его — собственное сердце, а царь — тот, кто знает себя. Никто не даст ему больше, чем он уже имеет.","996":"Ночью герой разговаривает с тенью любимой — и она отвечает, поэтому он просит её остаться тенью навсегда. С рассветом тень замолкает, комната пуста: с ним говорил уже не она.","997":"Музыкант играет и поёт в бамбуковой роще — единственная гостья, которая приходит посветить, это луна. Его незаметность оказывается не потерей, а свободой: он сам себе достаточно.","998":"Царь тысячу лет молит небесную реку спуститься и спасти предков от огня — поток рухнул бы на землю, но великий йог ловит его волосами и отпускает мягко. Разрушительная вода становится спасением.","999":"Путник подходит к небу с псом, но боги заявляют: небо не для собак. Он отказывается входить без друга — и верность оказывается пропуском: небо принимает обоих.","1000":"Двое друзей в одной тюрьме влюбляются в одну женщину, и любовь ломает клятву братства. Умирающий последней просьбой просит её за друга — дружба сильнее зависти лишь перед смертью.","1001":"Ученики несут гроб учителя выше облаков: он выбрал не жизнь, а знание и умер, не закончив главного. Похоронен на вершине, до которой другим ещё ползти, — но теперь все пойдут его дорогой.","1002":"Голосу того, кто гребёт против всех ветров, отвечает наставник: стучи, греби, держись и не снимай рук. Чудес не обещают — упорство в конце всё равно побеждает невзгоды.","1003":"Оборванец пьёт под красным фонарём, и вино обещает ему величие: в пьяной мечте он штурмует особняки богачей. Утром об этом штурме мечтает уже целый квартал нищих.","1004":"Поэт шлёт письмо целому миру, который ни разу ему не ответил, и единственный нежный судья находится в природе. Мир не оценит строк, но его письмо уже прочитано и принято.","1005":"В рождественскую полночь скот, по преданию, встаёт на колени — взрослый герой давно не верит, но всё равно выходит в темноту с газовым рожком. Вера умерла, привычка надеяться жива: он стоит у хлева.","1006":"Весенний парк, липы, робкий поцелуй и смех над скучными взрослыми: в семнадцать жизнь кажется бесконечным праздником. Несерьёзность — не легкомыслие, а единственная честная форма юности.","1007":"Весна гонит зиму по земле, как гончие лису: любовь расцветает на бегу, лето мчится следом. У погони нет победителя — время меняет все полюса, и вместе с весной всегда бежит смерть.","1008":"Поэт выращивает белую розу в июне и в январе для честного друга, а тому, кто вырвал ему сердце, не сажает колючек. Лучший ответ предателю — вырастить и ему такой же цветок.","1009":"Мама ставит кукурузный хлеб в печь — и дом преображается: с поля торопится отец, сбегается вся округа, пока хлеб горяч. Никакая проповедь не мешает голоду: семейный очаг сильнее обстоятельств.","1010":"Он возвращается к берегам Дуна, где пела их любовь: птицы и розы как прежде, только её нет. Природа вернулась к жизни, а его история — нет; место помнит счастье, которое было только его.","1011":"Рождественские колокола поют о мире посреди войны, и поэт теряет веру — тогда колокола гремят громче: ночь победит лишь на время. Это не наивность, а план — песня о мире сильнее канонады.","1012":"Успешному выходцу из степи дед присылает кулёк полыни — один вдох запаха выбивает из-под него всю выстроенную жизнь. Он сдаёт наёмную квартиру и уезжает к корням, оставив чужую славу.","1013":"Семья всю зиму жила при закрытых окнах, и воздух стал тяжёлым от обид. В первый тёплый день кто-то распахивает раму — с запахом весны приходит давно избегаемый разговор, и к вечеру дом снова дышит.","1014":"Жена по воскресеньям играет королеву при муже, живущем в своей сказке: там он счастлив, а правда рождает вину. На вопросе о васильках она впервые не спорит — уходит, полюбив даже его короля.","1015":"Ночной таксист проезжает её старый район, и ревность рисует ему чужие окна и чужую жизнь. На красном свете он меняет вопрос «с кем она» на пожелание ей дня без печали — и отпускает по-настоящему.","1016":"Ветеран просит в клубе слова не о победах, а об обороне: о смене без поддержки и разных людях в одном окопе. К последнему куплету зал встаёт — непобедная песня признаётся равной победным.","1017":"Волны выстроились полками перед наступлением, и посёлок не выходит на воду — сын ждёт с берега отцовскую лодку, ушедшую к горизонту. К вечеру тьма спадает, и из тумана выходит знакомый силуэт — живой.","1018":"После пожара он собирает команду из таких же погорельцев и идёт против корпорации, сожгшей их город. Даже враг признаёт: против таких выигрывать нечестно, — делу дают имя, живущее дольше победы.","1019":"Гость в квартире уехавшего друга три дня гордо греет руки об кружку, не признаваясь, что мёрзнет. В конце он всё-таки звонит — не за дровами, а услышать голос, и тепло приходит раньше сантехника.","1020":"Обыватель с карьерой и ипотекой ночью выезжает на старый мотоцикл юности: бездорожье уносит его вверх, без правил и чужих ожиданий. Утром он не снимает шлем — мир впервые зовёт не по должности.","1021":"Укротительнице отдают жеребца, которого уже сдавали назад, — вместо битвы она неделями разговаривает с ним через дверцу. Однажды утром он сам подставляет бок: настоящая власть не подавляет.","1022":"Старый ученик астронома ходит на пустырь, где стоял гараж с самодельной трубой, открывшей ему небо. Там он встречает подростка с биноклем и впервые вслух говорит: храм учителя переехал на небо.","1023":"Семья третий час стоит в заторе — вместо ссоры папа разворачивает свой пантеон дорожных бед, и дети с заднего сиденья подхватывают рефрен. К заправке они едут хором: у дороги появился свой жанр.","1024":"Она возвращается через годы готовая начать заново — переписки, ресторан, старые шутки. Он помнит, чем кончается повторение, и остаётся другом: отказ без горечи, дверь в прошлое закрыта.","1025":"Обманутая когда-то женщина остаётся единственной, кто приезжает проводить умершего в чужом городе лжеца. У ручья она впервые произносит вслух «простила» — не оправдывая его, — и уходит свободной.","1026":"Капитан не защищает любимую пассажирку от команды, требующей снять её с борта: верность своему кругу оказывается сильнее. Её куплет теперь поют вопреки ему — и он до конца жизни молчит в нём.","1027":"Девушка из передвижного цирка уезжает в четыре утра — городской любимый честно признаётся, что не поедет. Вместо кольца она просит узел на шали, завязанный его руками, и увозит любовь с собой.","1028":"Самоучка с гитарой пишет для девушки, которая смеётся над его «деревенским» звуком и уходит под чужой лаунж. Когда с ней случается беда, он отвечает не «я был прав», а лучшей своей песней.","1029":"В баре у вокзала он признаётся другу, что полюбил дочь владельца квартала: съёмная комната против фамильных квартир. Он пишет ей сообщение, не отправляет, платит за двоих и выходит — чек как приговор.","1030":"В общежитии она ночами шьёт заказ, оплачивающий зиму всей комнате: соседки ворчат — и она гасит лампу, продолжая наощупь. Под утро готовая куртка ложится на общий стол, и она впервые спит как дома.","1031":"Ночной автобус везёт его по детским местам: закрытые клубы, бывший лагерь, за каждым поворотом чья-то история. К рассвету он записывает первую строчку песни — обида на время стала летописью.","1032":"Он шутил «умру первым», а авария унесла компанию — в ту ночь он вернулся за подарком. Десять лет спустя за тем же столом он один и, поднимая тост, впервые признаётся вслух, что очень скучает.","1033":"Солдат после госпиталя идёт к дому на попутках, в ночлежном дворе чужие водители делятся с ним пледом и пирогом. Их доброта возвращает веру — утром последние вёрсты он проходит пешком, не боясь.","1034":"Два восьмидесятилетних друга по субботам судят вина в гараже: эта — сейчас, эта — на свадьбу внуков. В финале они ставят на полку бутылку «на похороны» — она переживёт обоих, как и дружба.","1035":"Шторм отрезает пловца от сопровождения — вместо паники он поёт вслух всю жизнь: дороги, ночёвки, ни одного чужого счёта. На рассвете его находят у буя с целой песней, дошедшей до берега раньше лодки.","1036":"Отец-военный отдаёт сыну нож и семейное «надо», и парень проходит путь до медали. Годы спустя он приводит своего сына к руинам дедовского дома — вместо ножа учит его читать руны и выбирать своё.","1037":"На вокзале они прощаются на три шага дальше положенного: сплетни назначили им роман, и любая теплота станет доказательством. Поезд уходит — она улыбается: всё сказанное до платформы засчитано.","1038":"После полугода ссор они впервые гуляют до утра: заготовленные речи не подходят к такой тихой ночи. К первому трамваю молча берутся за руки — без единого «прости», которое больше не нужно.","1039":"Сын жестянщика правит жесть двадцать лет, пока его собственная песня не признаётся лучшей в городе. Он ставит первую пластинку в витрину рядом с отцовскими вёдрами — и впервые смотрит на двор сверху.","1040":"Не умея говорить о чувствах, он каждую весну выкладывает в сеть песню без названия — она узнаёт её по перебору. Теперь под её окном играет уличный музыкант с его мелодией, и она выходит на балкон.","1041":"Ему подарили копию мотоцикла юности: дети просят продать, соседи смеются, а он тайком учится заводить заново. На рассвете он выезжает за город — не за прошлым, а за ощущением, что время ещё его.","1042":"Старший брат даёт младшему одну песню для объяснений: кончится трек — кончится место за столом. Вместо оправданий младший поёт о братьях с одной кухни, и рука с приговором замирает над столом.","1043":"Ночью он покидает родной город навсегда, но перед электричкой впервые поднимается на смотровую: огни лежат шёлковым покрывалом, и он едет прочь влюблённым. Отменять поздно — этот вид забирает с собой.","1044":"На улице экскурсовода особняки сменили бары и лавки, а ласточки вернулись на старый фасад, будто ничего не случилось. Она записывает голосом имена исчезнувших домов — телефон полон имён.","1045":"В пустой квартире выходного дня героиня делает полный ритуал — стрелки, локоны, никому не показанные правила. Впервые за месяц ей нравится отражение: она выходит на улицу без цели, красивая для себя.","1046":"Звукорежиссёр ночью перебирает плёнки, как струны: каждая открывает десятилетие — любовь, чужая свадьба, забытый дебют. Он не помнит, была ли та ночь наяву, — плёнка остаётся играть в пустой студии.","1047":"Невестка не знает правил кухни семьи мужа и зовёт его сестрёнку «проверить борщ по-нашему»: за дегустацией они впервые хихикают как свои. Свекровь пробует острый суп, молчит — и просит вторую тарелку.","1048":"Всё потеряв, он не спит у ночного моста: луна садится, над водой кричат птицы. В четыре утра долетает колокол — единственный звук, который ни о чём не спрашивает, — и он остаётся дослушивать до утра.","1049":"Весь день в наушниках, а вечером на скальном берегу они разряжаются — и впервые за годы он слышит, как тонкое насекомое прошивает тишину своим голосом. Домой он идёт без музыки, слушая дорогу.","1050":"Он останавливается у звонницы доесть хурму, и в шесть колокола ложатся точно в паузу между укусами: будний вечер становится праздником. Мама впервые не ругает опоздавшего, а пересаживает его к себе.","1051":"За ночь из съёмной однушки унесли всё, даже чайник, — а утром в пустой квартире распахнутое окно и луна над гаражами. Он садится на подоконник пить вид и вечером пишет матери: потерял всё, кроме окна.","1052":"Ведро во дворе оказывается в цветах: лоза, с которой отец воевал как с сорняком, обвила ручку и распустилась. Она оставляет ведро вьюнку и просит воды у соседки, а лозу больше не трогают весь сезон.","1053":"На собеседовании тридцатилетний курьер впервые не врёт: цели на пять лет нет — есть желание видеть всё своими глазами, даже с руками в ссадинах. Вечером он берёт новую смену, не оправдываясь.","1054":"Ему предлагают безопасный проект за экраном, но артист выбирает тёмный зал с одним живым прожектором: мёртвый свет не греет. Круг сужается, зал гудит — он кружит в нём до последнего витка.","1055":"Основатель империи пишет из больницы маме: извиняется за пропущенные праздники и признаётся, что уходит с пустыми руками. К утру письмо читает вся палата — страница становится главным наследством.","1056":"Отец с тяжёлым диагнозом собирает сыновей на длинный ужин: каждому честно называет, чем та мечта ранит, и просит беречь друг друга. К десерту тост — не за наследство, а за то, что все ещё здесь.","1057":"После дедлайна он всю ночь спорит со вторым голосом: один тащит наверх, второй спрашивает, хватит ли того, что есть. К утру он переносит совещание и впервые завтракает не по звонку, а по голоду.","1058":"Он возвращается инкогнито, а она ставит его кресло в круг и хранит его место. Под чужим именем на вечеринке он слышит про «одного знакомого» всё то же — маска падает, и вместо объяснений они танцуют.","1059":"После пожара у него остаются конспекты и голова на плечах — он объясняет соседям и собирает ребят с улицы. Через месяц на кухне первый класс: сокровище, которое можно тратить, не уменьшая.","1060":"Городской внук смеётся над отцовским полем, пока скачки цен не заставляют считать тонны еды. Отец молча отдаёт ему руль трактора — и он снимает не себя, а всходы, впервые кормя по-настоящему.","1061":"Она объездила города в поисках своего воздуха, а на кухне матери во время сборов вдруг слышит собственный голос, который искала годами. Утренний поезд уходит без неё — она дописывает дома свою песню.","1062":"Пока на планёрке всё решают «пока», его проект лежит в «когда-нибудь»: он впервые берёт слово, ставит имя в «ответственные» и держит удар насмешек. Вечером в календаре появляется новая дата.","1063":"После отпевания соседа он считает из автобуса окна, где горит свет, и видит: у его списка «когда-нибудь» нет номера страницы. Он набирает брата, с которым молчал год, — и говорит с ним до утра.","1064":"Пятый год он рисует в заметках дачу мечты и откладывает «на потом», а жена давно не спрашивает. Теперь на балконе появляется ящик земли — она молча ставит рядом вторую лейку, и ужин переезжает туда.","1065":"После её короткого «прощай» он идёт ночью по их кварталу и вслух уговаривает себя: хватит стучать в закрытую дверь. К рассвету голос выравнивается — он сворачивает на свою улицу, не глядя на её окно.","1066":"После очередного «мне не до тебя» она на крыше просит вслух: пусть оттолкнувшее сердце развернётся само. Через неделю та самая пишет ей первой — и она впервые отвечает неторопливо, не бежит навстречу.","1067":"После решающей победы капитан вдруг понимает, что через год состав разойдётся, — и зовёт команду на общее фото посреди арены. Когда свет уже гасят, они выходят под крик трибун: этот час настоящий.","1068":"Перед выселением сосед молча держит второй конец шкафа, а после ужина у костра выселяемый отдаёт ему ключи и своё поле. На рассвете фургон уходит — сосед стоит у ворот, пока дорога не опустеет.","1069":"После неё он клялся, что сердце сварено насквозь, но с первым смехом новой знакомой оно снова на наковальне. Друг молча разжигает горн сильнее — а он кладёт руку на металл и принимает перековку.","1070":"Ради возвращения украденного он приходит на помолвку под фатой и терпит тосты в чужую честь. Когда «невесте» кладут похищенное, хватка выдаёт его — фата летит на пол, и праздник обрывается.","1071":"Ночами доделывая диплом, он присматривает за котом уехавшей соседки. В три ночи тот засыпает на тетрадях, и он аккуратно отодвигает его, не закрывая ноутбук: впервые за месяц никуда не спешит.","1072":"Двое встречались письмами, пока слова не написались, — теперь протянутая страница онемела. Всю ночь они заново учатся говорить голосом, и к рассвету самое дорогое письмо — разговор за одним столом.","1073":"Умирая, старшая сестра за вечер отодвигает пяльцы и признаётся, что их дом стоял на её тайной любви к жениху младшей. Никого не обвиняя, она благословляет чужое счастье и гасит лампу с чистой душой.","1074":"Путник идёт вверх по пыльной дороге и спрашивает у голоса: долго ли, не закроют ли двери перед ним. Ответ твёрд: путь весь в гору, но там ночлег для каждого дошедшего — к закату свет в окнах двора.","1075":"В самую глухую ночь зимы люди несут к дому золото и шерсть, а у неё — обмёрзшие ладони и огонёк в груди. В ответ на вопрос, чем платить, звучит: тем же, чем живы все нищие мира, — сердцем.","1076":"Работяга прожил день как работу, до мозолей, и просит ночь не спешить — дать допеть птице над крышами и ему под ней. Он не торгуется и не боится: хочет уйти с песней, как уходит хорошо сделанный день.","1077":"Переживший своих друзей слышит их смех там, где они стояли: весна приходит как всегда, только на его месте никого нет. Он несёт их в себе, как носят тяжёлое, — не роняя, не бросая, благодарно.","1078":"Безымянных наёмников никто не ждал домой, но когда всё рушилось, встали они: небо висело на их плечах до утра, земля под городами не сдвинулась. Надпись на камне короткая: с ними всё продолжилось.","1079":"Разбитый король с одной арфой поёт в лагере врага, пока подвыпившие враги не перестают считать его угрозой. Он слушает их больше, чем поёт, — и уходит до рассвета с песней, знающей врага наизусть.","1080":"Два семени узнают, что одному быть маком, а другому подсолнухом, — расстаться с самого старта. Тогда одно обещает слать другому пчёл через всё поле: письма по воздуху, даже если корни не сойдутся.","1081":"Днём имя его любимой под запретом — вся округа смотрит в рот. Ночью он кричит ей в лицо бурям, обещая переплыть моря и выйти из любой тюрьмы, а на рассвете снова молчит.","1082":"Метель за ночь отрезала дом от мира, но вместо страха — война варежек, старые истории за ужином и смех через стол. Ребёнок к утру впервые не хочет, чтобы снег таял.","1083":"Она толкнула ему книгу, не сказав ни слова, а разговор не случился: годы разъехали их, весть пришла слишком поздно. Теперь в звоне школьного колокола он слышит её имя и садится на ту же скамью.","1084":"Взрослые видят в нём потрёпанного работника с сеном в волосах, а дети — волшебника: катает на тачке, придумывает войны с сорняками. Ребята взрослеют — и первым, кого вспоминают добром, остаётся он.","1085":"Сирота Энни днём просто прислуга, а вечерами пугает детей сказками про гоблина — дом вздрагивает и хохочет. Грозная рассказчица тушит свечу: чужая девочка стала душой всех вечеров в этом доме.","1086":"Пёс в клетчатой рубашке и кошка в цветочек не поделили место у окна — и ночью ушли на дуэль. Под утро от обоих не осталось ни клочка, и с тех пор за столом никто не спорит вслух.","1087":"Собачка под одеялом, солдатик у подушки — а мальчик не просыпается. Игрушки стоят на посту, как обещали никого не подпускать, и двое караулят пустую комнату, пока сами держатся.","1088":"Пятнадцать зим она училась дышать без него и поймала себя: живёт ради горя. В последний разговор она просит прощения за счастье — отпустить оказалось труднее, чем умереть.","1089":"Ночью в окно входит ветер, звавший её с колыбели, и обещает лёгкий мир без здешних бед. Она отказывает в лицо: оставь сердце земному. Ветер обещает вернуться — он умеет ждать.","1090":"Ей было девятнадцать, когда она уехала и умерла там, куда не доехали письма. Раз в год он отдаёт ей целую ночь у окна — все несостоявшиеся разговоры — и к рассвету живёт дальше.","1091":"Весенний вечер, руки в руках — и весть с дороги: за холмом людям не хватает хлеба, но зерно надежды взошло под снегом. Завтра они выйдут из тепла к людям — взявшись за руки, но уже в толпу.","1092":"Глашатай жил на краю и крикнул первым, чтобы разбудить дорогу для тех, кто шёл следом: ни трона, ни имени в песнях ему не обещали. Он выбрал быть предисловием — и заплатил за это всем.","1093":"Умирающий Сэм просил сжечь его в топке — хоть раз согреться. Приятель всю зиму вёз сани через пустыню и сдержал клятву: Сэм сидел тёплый и весёлый и просил прикрыть дверцу, чтобы не выстудить.","1094":"Клерк разбирает чужие почерки, а в голове Кланси умывается росой и гонит скот через всё небо Австралии. Сквозь стену конторы — песня погонщика, и к вечеру он пакует вещмешок: одна нога уже в сёдле.","1095":"Громилу округа бьют в драке и позорят на охоте — ночью он впервые честно остаётся один со своей пустотой. Он плачет и просит прощения у запуганных, а утром встаёт на защиту слабых.","1096":"Его зовут мазилой: он рисует море, какое оно есть, и молча терпит насмешки команды. У мыса Горн ледяная волна достаёт его на последнем подъёме — после этого имя впервые произносят без смеха.","1097":"Осенью он снова считает лебедей на тихой воде — те же пятьдесят девять: птицы не стареют, пока он считал свои зимы. Юность посмотрела с воды и улетела, и однажды стая прокричит уже без него.","1098":"У него нет золота — вся собственность в голове, и он раскладывает сны у ног любимой вместо дорожки. Просит одного: идти осторожно, ведь под тяжёлым шагом мечты трескаются, как тонкий лёд.","1099":"Каждую весну два соседа заново складывают каменную стену: один несёт камни в шутку и спрашивает — кого я загоняю? Стена вырастает снова, и годовая сходка у неё — их способ оставаться соседями.","1100":"Вечерний снег на чужом лесе завораживает путника — тишина, в которой можно остаться навсегда. Конь дёргает упряжью, встряска возвращает к обещаниям: он щёлкает языком и едет дальше.","1101":"На поле между крестами рядами цветут алые маки — посадили их солдаты, любившие чужие рассветные лица. Мёртвые держат факел в воздухе, пока живой не возьмёт: уронят — маки завянут даже здесь.","1102":"Уволившийся дизайнер каждую ночь у круглосуточной лавки пишет список планов: студия, выставка, переезд. Однажды в конце появляется «начать сегодня» — но список утром всё тот же, без единого действия.","1103":"Перед первым штормом дед-капитан спрашивает команду шхуны: за что мы платим морю? Все молчат — впервые отвечает шестнадцатилетняя внучка: за всё, что нам даёт жить.","1104":"Инженер-технооптимист в ночь запуска линии произносит тост конвейеру — хвалит роботов, скорость и свет. К трём ночи он вдруг слышит тишину между ударами и впервые за год никуда не спешит.","1105":"Уволившись, он вывешивает объявление «поход без маршрута» — первой подписывается дочь-подросток. Утром семья выходит в поле без указателей и оставляет тропу со своими именами.","1106":"Семья решила снести дачу вместе с полумёртвым вязом, но бабушка молча поливает его и вешает кормушку. В апреле на сухой ветке зелёный лист — и внуки голосуют отложить снос на год.","1107":"Она ждёт парня, который возит тёмные грузы и обещал, что последний рейс заберёт её в море. Когда его лодку видят у чужого берега, она снимает кулон с якорем и больше не выходит к воде.","1108":"Отец в СИЗО каждый вечер записывает двухлетнему сыну сказки. Приходит фото: сын держит луковицу вместо игрушки — и отец записывает колыбельную, полный список весны: лягушки, автобус, каша, папа.","1109":"Бывший моряк курьером в сухом большом городе по средам слушает в наушниках цепи и чаек. Однажды он ставит запись моря через колонку во дворе — и соседи приходят слушать море бесплатно.","1110":"Ночная смена семейной пекарни, пекарь сочиняет куплеты по ходу работы — его слышно через окно. К рассвету очередь подхватывает припев, а первый батон достаётся девочке с последнего этажа.","1111":"Три подруги ставят на ужин фото четвёртой, которой нет, и по кругу говорят, где нашлось королевство: за стойкой, в подписях, на кухне в шесть утра. Тоска уходит с первым смехом.","1112":"Столяр теряет партнёра и мастерскую за один месяц, но собирает руки заново. Он уносит последнюю дверь, которую делали вдвоём, и вешает её на крошечный новый сарай — так начинается дом.","1113":"Она уезжает с добровольцами тушить чужие пожары — зять зовёт это бегством от семьи. Там она учит подростков держать шланг, а обратно автобус встречает зять с табличкой «спасибо».","1114":"После пожара старшеклассники решают прогнать змею — общий страх выгоревших улиц. Барабанщица задаёт ритм, и каждый вечер команда проходит единым танцем через квартал, пока страх не замирает.","1115":"Жених объявляет невесте «правила честного прошлого» — она подаёт такой же список с графой про него и просит заполнить до пятницы. Папа роняет вилку, а свадьба остаётся под вопросом.","1116":"Мама-фрилансер собирает посылки, а муравей с подоконника будто инспектор: ты всё время дома. Она устраивает ему экскурсию по невидимому дню — счета, школа, лекарства, — и муравей впервые молчит.","1117":"В деревне его зовут странным: каждую безлунную ночь он ловит в озеро фонарь, чтобы вода училась светиться. Приезжая фотографша гасит камеру и держит фонарь рядом — озеро впервые светится вдвоём.","1118":"Слепой настройщик играет на школьном органе, а уборщица год слушает его из-за двери, боясь помешать. Однажды она просит ещё раз — и они вдвоём сидят в пустом зале, слушая темноту как оркестр.","1119":"Его жена не вернулась с гонки, и каждую неделю он ведёт их лодку до буйка — говорит вслух про дочку, новую мачту, сад. В конце он читает письмо дочери к маме и сгибает его в кораблик.","1120":"Руководителю в 39 ставят выгорание после панической атаки в переговорке. Ночной волонтёр знает дороги из леса, но не ведёт за руку — лишь показывает холм со светом, и первый шаг герой делает сам.","1121":"Отставной капитан в 70 собирает старую команду в рейс за горизонт. Дети блокируют документы, но команда тихо поднимает паруса в ночь, а утром сын машет с пирса — впервые без спорного письма.","1122":"После развода, где её вина была больше, она приезжает в лагерь на реке без телефонов. Ведущая учит петь на берегу, где вода забирает только лишнее, — к вечеру вся группа пляшет босиком по мелководью.","1123":"После смерти наставника и развода он впервые ведёт жизнь без чужих карт: старая яхта, море, ни штурмана. Волны сносят маршрут, но решает он сам — к рассвету парус на своём курсе.","1124":"Он не даёт в любви гарантий на пять лет и чужих сценариев в календаре. Она месяц злится, но соглашается на выходные без плана — и впервые они молчат спокойно.","1125":"Звезда стриминга неделю живёт обычной жизнью: квартира, будни. Любимая не узнаёт его простым — уходит к образу из чата. Он возвращается на сцену с билетом на свой концерт — просто зрителем.","1126":"После похорон отца он возвращается к родне, молчавшей десять лет, и заводит воскресный круг. Сначала выходят трое — пока враждующие тётка и дядя не берутся за руки, и круг смыкается до забора.","1127":"Больной винодел не пишет завещание — готовит свадьбу: зовёт друзей на гору, ставит стол и тостует, что женился на небе. Обманщиков с виноградниками тоже позвал: праздник сильнее рассказа о болезнях.","1128":"Основатель стартапа оставляет команде видео-завещание: три конкретных дела доделать и запрет на траурные плейлисты. В его день рождения команда заканчивает первое дело и впервые на созвоне без слёз.","1129":"Бабушку с краю посёлка пугали, пока девочка не узнала: у неё погибли оба сына-спасателя. Она рисует сову с двумя птенцами и вешает на забор — и посёлок впервые видит её историю, а не свой страх.","1130":"У витрины с престижными кроссовками они встречают новенькую с дырявыми ботинками — и дочь просит купить такую же пару для неё. Мама впервые соглашается: на празднике девочки танцуют весь вечер.","1131":"Брат после увольнения запирается в комнате — сестра ведёт его к морю смотреть смену волн, по бабушкиному правилу, что всё проходит. Он идёт на первое собеседование с камешком в кармане.","1132":"После громкого разрыва он говорит одно: не сержусь. Ночью снится змея на её сердце — её яд не его дело. Вместо мести он хоронит чувство целиком — и наутро свободен, почти жестоко.","1133":"Он ушёл в другую жизнь и шлёт жене письмо с ночными птицами: просит прощения — и тут же упрекает, будто её нетерпение снимает половину вины. Она закрывает ставни: ответа не будет.","1134":"Год на чужбине выучил его молчать: он спускается с гор в свою долину с мешком несказанных слов. У ворот узнают без вопросов, и за свечой дом переводит его тишину простыми словами.","1135":"Мир зовёт его подарками, а он просит оставить его в тайной комнате, где радость и боль — только его. Когда совсем тяжко, он выйдет, обнимет мир, как потерянного брата, и снова закроет дверь.","1136":"Гость свадьбы замечает на скале замок: рыцарь с бородой, вросшей в камень, всё держит пост. Внизу гремит чужое веселье и проезжает мимо его окна — над каждым праздником стоит чей-то несбывшийся.","1137":"В полночь озеро распахивает зелёные двери, и водяные девы кружат без единой ряби. Юноша засмотрелся слишком близко — бал замирает, духи уходят под воду: тайное празднично, пока не раскрыто.","1138":"Взрослый смотрит за оградой, как дети взлетают на пёстрой карусели, — круг никуда не едет, и в этом всё счастье. Музыка обрывается, и он, помня, как его самого выпускали, просит закружить ещё раз.","1139":"Он включает старый мотив и садится у окна: за звуком отворяется вечер детства — под сиренью он ждёт любовь на закате, ту, что не пришла. То ожидание оказалось длиннее всей его взрослой жизни.","1140":"Солдаты привязывают дочь трактирщика к спусковому крючку: пусть разбойник приедет — и попадёт в ловушку. На рассвете она жмёт курок: выстрел предупреждает его, и конь уходит в темноту.","1141":"Старые корабли идут мимо деревни спящими лебедями: пережили пиратов и смену богов, а теперь уходят к скрытому солнцу. Никто их не хоронит — они плывут в последний рейс с достоинством осадки.","1142":"Молодой солдат просит не оплакивать его: где бы ни упал, тот клочок земли станет его — кусочком дома. Всё, что дала жизнь, — свет рек и улыбки родных — он отдаёт полю: умереть значит вернуться.","1143":"Он перечисляет всё, чем жил: тарелки в синих полосках, вишни, корицу, дождь по крыше. Список длиннее биографии — так он узнаёт, что жизнь была великой любовью, и завещает его тем, кто не начал свой.","1144":"Солдат смотрит на румяных тыловиков: они гонят хмурых героев на смерть и скорбно читают списки потерь. Когда война кончится, майор умрёт в своей постели — и ни один окоп его не коснётся.","1145":"Старик кладёт сына на вязанку — ремни стягивают ребёнка вместо барана. Ангел кричит заколоть гордыню вместо мальчика, но отец верит своему праву больше неба: на вязанку ложится всё молодое поколение.","1146":"На рассвете на руку солдату прыгает крыса — единственная, кто ходит между линиями: зверь не знает, что это война. Он кормит её хлебом и втыкает красный мак за ухо — живое красное среди серого дня.","1147":"Безногий ветеран в кресле у парка: год назад собирал стадионы, теперь ради взгляда Мэг он в парадной колонне. Девушки скользят мимо, и лишь один человек приносит ему фрукты и спрашивает о душе.","1148":"Он женился на девочке, которая не поняла, что её спрашивают, — через три недели она ушла через окно, и её догнали с фонарями. Теперь она живёт диким зверьком, а фермер ждёт тепла, которого не будет.","1149":"Четыре стены у всех одинаковы, а дома разные: годы чаёв на плите, голоса на лестнице, рисунки на холодильнике. Надо уехать и голодать по нему издалека — дом есть там, куда вложил жизнь.","1150":"Ему сказали, что это невозможно, — он усмехнулся и начал сам, и хохоток его был громче всех предостережений. Взялся за дело с песней: «нельзя» осталось на месте, а дело — сделано.","1151":"В полночь над спящим Спрингфилдом житель видит фигуру в старом пальто: Линкольн ходит пустыми улицами, и шаги его тяжелее колоколов. Городок засыпает под эти шаги — и обещает себе проснуться лучше.","1152":"Город засыпает, когда туман скользит на кошачьих лапах: садится над портом, глядит на молчащий город и уходит дальше. Никто не слышал ни входа, ни выхода — только здания на минуту стали мягче.","1153":"Ему приносят список грехов города — он соглашается со всем: видел и это, и это. Но видел и как город поднимает голову и поёт, гордый, что живой и сильный, — и предлагает показать второй такой.","1154":"Безымянный работяга пашет, строит и кормит мир: все великие дела сделаны через него, а его забывают между войнами и праздниками. Однажды масса набухнет под землёй и заговорит сама.","1155":"Она говорит ему наперёд: когда апрель раскинет надо мной дождь, наклоняйся с разбитым сердцем — мне будет всё равно. Это не месть, а последняя ступень остывания, где нечего прощать.","1156":"В холодной хижине мать и сын голодают, и вся утварь — арфа на стене. Ночью арфа ткёт из светящихся нитей платье за платьем, мать работает рядом до последней силы — к утру она навсегда тихая в кресле.","1157":"Она не помнит имён — только губы, целовавшие её губы, и руки под головой до утра. Ночью прилетают призраки летних ночей, но в ней теперь зимнее дерево: птицы пели в нём, а тишина полная.","1158":"Она идёт по садовым дорожкам в парчовом платье, чей узор повторяет клумбы. В письме — что он не вернётся: впервые она чувствует, как туго затянуты узоры её жизни, и хочет идти прямо.","1159":"Он приходит в один и тот же сон: там ждёт женщина, которая понимает его без слов, и рядом с ней он — тот, кем не был ни дня наяву. Просыпаясь, находит пустую комнату, где никто не ждёт этой нежности.","1160":"Он тащится по жизни, как лебедь по земле: тяжело, через всё несделанное. Но приходит час, когда вода наконец принимает его — и всё выходит лёгким и красивым, как у человека, вошедшего в свой час.","1161":"Солдаты выносят погибшего друга на снег к солнцу — бережно, как когда-то будила его мать. Дома солнце растапливало усталость, теперь не двигает даже лицо: последняя забота, которой некому отдаться.","1162":"Сын возвращается на лодку отца после провала в городе — тот учит сезонам и песне на каждую примету. В первую бурю сын затягивает песню раньше отца — и море впервые считает его своим.","1163":"Проект разделили без него, чат смолк — дизайнер уезжает к реке и заводит друзей: вода, валун, сосна, луна. В лунную ночь он находит шестого друга — себя — и впервые за год смеётся.","1164":"Он уезжает ночным поездом, и любой разговор превратит прощание в суд. Вместо разборок она приносит на перрон букет азалий и голосом просит не оборачиваться — и он впервые едет с её разрешения.","1165":"В последнюю летнюю ночь брат показывает сестре огни барж и врёт, что это корабли в дальние гавани. Через год письмо из чужого аэропорта: огни такие же — значит, луна у нас общая.","1166":"Она отвечает на его молчание красным цветком в волосах. Он месяцами репетирует признание в зеркале проходной, а решившись — находит лишь лепесток на подоконнике. Он берёт его и впервые говорит вслух.","1167":"Разбирая квартиру матери, дочь находит тетрадь: мама писала о мечте, которую семье было удобнее не замечать. Дочь читает всю ночь — и плачет впервые не от потери, а от того, что не прочла раньше.","1168":"Невесту свадьбы по расчёту учат безупречности: белая кофта, тихий голос. У торговки она слышит про шарик в воде — белый снаружи, сладкий внутри, — и в момент «да» шепчет: пусть тает, но по своей воде.","1169":"Пять лет они экономили друг друга: вежливый ужин, уборка по графику. Она достаёт велосипеды и тащит его на перевал — он ворчит до первого поворота, а на вершине они впервые за годы говорят правду.","1170":"Браконьеры выходят на старика у костра — их собаки бросают след и ложатся к огню. Он поёт про отцов, бывших детьми в этих горах, и к утру ружья стоят у сосны, а четверо остаются слушать вторую песню.","1171":"Он едет в родной город мстить — вместо дома дыра, о сестре никто не слышал. Вечером на фундаменте он начинает петь, и к третьему куплету план мести сгорает быстрее пепелища.","1172":"Мать пробивает дочь на надёжное место: апрель — грязь и ни одного гаранта. Дочь покупает билет до прослушивания и выходит из дома в самый мокрый апрель — правильное время то, которое выбираешь сама.","1173":"Он уезжает за океан и всю ночь гадает, что за кромкой гор, — дед говорил: только снег. В самолёте под крылом — бесконечные снега, и вместо тоски он смеётся, шлёт деду фото: за горой тоже есть горы.","1174":"После похорон жены капитан не может спать в тишине: тикают часы, давит пустота. Он возвращается на берег детства и слушает, как вода укачивает причалы, — первые настоящие сны приходят на лавке у дюн.","1175":"Тихую девочку, три года не званную в компанию, выбирают нести венец свечей. Всю ночь она репетирует в тёмной кухне, боясь огня и чужих глаз, — а утром зал скандирует её имя.","1176":"Портной пишет рифмы между заказами, и бригада делает из этого шоу: у нас свой поэт. На открытом микрофоне к третьей строфе зал перестаёт смеяться — насмешка становится гордостью квартала.","1177":"У неё всё правильно: дом, муж, дети — и звонок из прошлого будит ночь голосом былой свободы. Она идёт ночью к реке, но детский крик «мама» возвращает её в дом — впервые честно назвав свою цену.","1178":"Ночью перед свадьбой незнакомка зовёт жениха к лёгкости без последствий. Он отказывается в лицо — и получает удар под сердце, а невеста переносит праздник к его койке: её танец будет только его.","1179":"Дальнобойщик просыпается после двенадцати дней сна: во сне явились дети, которым он годами не звонил, и отец, ждущий один звонок. Он находит в телефоне список и звонит, не вставая с кровати.","1180":"Десять лет стёрли «любимый» до бытового «эй». На мостике она говорит «милый» трижды — как пароль их первой зимы, — и к полуночи слова возвращаются новыми: по строке правды за каждый повтор.","1181":"Команда тральщика во льдах, капитан решает: строим. Из обломков они поднимают хижину, заводят свои часы — дежурство, сказки, последняя плитка. Прилетает вертолёт: каждый обнимает хижину на прощание.","1182":"Она — из общежития, он — сын владельца, и кампус знает, кто кому не подходит. Они встречаются шёпотом под липой — пока она не берёт его за руку и не ведёт напоказ, платя за радость только смелостью.","1183":"Старый прораб с салфеткой, где три вещи не помещаются в одну жизнь: приличие, свобода, любовь. Комбинации он честно не находит — встаёт с бетонного блока и чинит первую попавшуюся лавку во дворе.","1184":"В чужом городе он теряет работу и три дня не отвечает маме — голосовые копятся, как дождь. На третьи сутки он засыпает под её записи, слышит её кухню, а утром покупает билет и записывает ей песню.","1185":"Сын приезжает в деревню матери после похорон — костюм, телефон, спешка. На берегу её реки он снимает всё до последнего ключа и говорит воде вслух всё, что не успел: она не поднимает волну, а держит.","1186":"Дед смотрит музей своего квартала, где его юность под стеклом с подписями для туристов. Внук снимает клип в залах — и дед записывает голосом то, чего нет ни на табличке: музей меняет экспозицию.","1187":"В их чате нельзя говорить о чувствах: вместо признания он шлёт картинки дождя, она отвечает метафорой про фрукт у корня. Вся любовь живёт намёками — пока он не шлёт пантун без второй части.","1188":"Свадьба детей семей, двадцать лет судящихся за дорогу: дяди обмениваются у микрофона четверостишиями, гости веселеют с каждым раундом. К пятому острота уже смешит — договор подписывают под общий смех.","1189":"После похорон бабушки он не спит: в ржи под окном кричит коростель, будто зовёт по имени. В три ночи он ложится в рожь, говорит вслух с тем, кого больше нет, — к рассвету засыпает на сеновале.","1190":"Брат проиграл дуэль, и свадьба сестры стала платой — жених вдвое старше. Она прощает всех, кроме самой сделки, и уезжает к морю: оттуда прилетает фото пустого берега и строка «я не долг».","1191":"У музыканта крадут отцовскую гитару — будто забрали право играть. Из кастрюль, расстроенного пианино и петель отцовской куртки он собирает сет: к вечеру вся улица слушает, а соседский пёс воёт в ноту.","1192":"Он давно один и не снимает с полки портрет ушедшей любимой: её лицо в памяти бледнеет, улыбку уже не вспомнить. Ночью она приходит в сон прежней — и он впервые за годы просит сон не заканчиваться.","1193":"В тяжёлое время он решает не экономить себя: будить всех, любить без полутонов. Он знает цену сгоревшим, но выбирает жар — и каждый день повторяет себе клятву, выходя в мрак улиц с огнём в груди.","1194":"В городе, где гаснут театры, голодный поэт приходит к старому дому поэта, как к последнему родственнику: книги, портреты, неугасимый огонь. Он уходит в мрак с обещанием носить это тепло до конца.","1195":"Она узнаёт новость утром и не может произнести вслух — муж завтракает, дом требует обычности. Ночью, поя колыбельную, она впервые смотрит ребёнку в глаза: там он — тайная любовь получает продолжение.","1196":"Молодая мать провожает мужа и брата одним поездом — женщины договорились не плакать. Когда поезд трогается, гул перрона превращает прощание в присягу: она впервые чувствует себя частью огромного.","1197":"Героиня собирает всех, кто говорит на одном языке, и ставит задачу: не дать родной речи сгинуть. Слово передают из рук в руки — бабушка, ребёнок, солдат, учитель, — язык становится их общим младшим.","1198":"Женщина держит приговор, которого ждала семнадцать месяцев. Память кричит, что мир кончился, тело отвечает: ты жива — она выходит из зала под дождь, у неё ещё есть, кому жить.","1199":"Пара живёт на расстоянии: чужие города, видеозвонки. Героиня отказывается называть это разлукой — пробел между ними знак, который она сама ставит и снимает, — и пишет ночью, будто они дышат в такт.","1200":"Девушка живёт в наполовину вымышленном прошлом: фильмы, письма, — а живые молодые люди кажутся скучными. Она ловит себя: чужую эпоху повторить можно, свою прожить ещё нет — и снимает мундир мечты.","1201":"Каждый вечер женщина проходит мимо почты: её счастье — квадрат бумаги с парой слов от него. Война забирает всё вокруг, но новое письмо приходит — и она у ящика смеётся и плачет сразу.","1202":"Эмигрант разучился верить в рощи и соловьёв. Под дождём уличная музыкантша фальшиво играет его детство — и он впервые не поправляет её, а просит играть громче, пока дождь не подпевает шарманке.","1203":"Застрявший в рутине взрослый вспоминает двор детства: гармоника, коронация из занавесок. Вечером он находит похожий двор у соседских детей и садится на бордюр — снова свой.","1204":"Пара без гроша каждый вечер отстраивает на кухне своё государство: примус, хлеб, смех над громкой жизнью за окном. Погасив примус, они остаются самыми богатыми — дом держится на этих вечерах.","1205":"Пожилой эмигрант находит в чемодане засушенные розы той весны — весь багаж оставленной страны. Он ставит их в воду в чужом окне: пусть мёртвое цветёт, пока он ищет дорогу назад.","1206":"Отец везёт сына в лес своего детства и боится, что место его не признает. Но бор встречает жаром смолы и птичьим гулом — и отец отдаёт сыну тропинки, как передают двор: теперь они общие.","1207":"Осенью, после громкого провала, в квартиру героя залетает замерзающий шмель. Он греет гостя в ладонях — оба на последнем тепле — и, отпустив его на цветок, впервые за сезон чувствует, что сам ещё жив.","1208":"Команда строит башню вечности для владельца, платящего рабством. Кладя камни, они втайне собирают в верхушке летучий шар — в ночь сдачи вся команда взлетает, оставляя заказчику башню без людей.","1209":"Пенсионер, за год потерявший жену и работу, в апреле просит скворца пустить его в скворечник хотя бы углом. Птица молчит, но поёт — старик уносит песню домой и впервые за зиму записывает свои строки.","1210":"После удара судьбы герой заперся дома, пока гроза не согнула старый клён. Тот не ропщет — ждёт росы и встаёт. Герой кормит во дворе воробьёв и понемногу выпрямляется вместе с клёном.","1211":"Мальчишка с золотыми руками уверен: вещи живут тайной жизнью, и ужин на тарелке моргает сигналами. Родители смеются, пока он не переводит семье разговор селёдки — и за столом впервые не ругаются.","1212":"Разлука длится дольше прогнозов: письма редеют, друзья советуют ей жить дальше. Но она каждый вечер светит в окно — и он, пройдя то, чего не выжил никто из его отделения, возвращается на этот свет.","1213":"Под ливнем на трассе героя подбирает дальнобойщик Алёша — всю ночь они говорят не о неудачах, а о людях, пропускавших их по-доброму. К утру он решает не сдаваться: с такой землёй проигрывать стыдно.","1214":"Ветеранка годами молчит о ночном кошмаре. От красивых слов о войне она срывается и говорит, как страшно было один раз наяву, — и честная тишина после этого впервые оставляет её спокойной.","1215":"Молодые фронтовики пьют на кухне трофейный ром, и один молчит уже четвёртый час. Друзья не дожимают, и к ночи он сам спрашивает, что тут было без них, — с этого вопроса комната оживает.","1216":"Танкист ищет у места гибели друга хоть знак могилы, но товарища положили прямо в землю, без списка. Он насыпает на выходе горсть земли в коробку из-под гильз — друг теперь в каждом облаке и грозе.","1217":"Команда вечных проигравших идёт через поражения и чужие города, неся своё «не постоим». К финальной битве голоса впервые звучат в унисон — ракета взлетает: победа досталась тем, кто остался вместе.","1218":"По осаждённому городу идёт трамвай-семья: санитарка делится сладким с мальчиком, старушка везёт подарок внуку. Кондуктор объявляет не улицы, а дела — завод, госпиталь, застава, — и все выходят к цели.","1219":"Девушка уходит на опасное задание под вымышленным именем, чтобы при провале семья осталась чиста. Мать годами отвечает «незнакомке», а потом впервые пишет: я всё знаю — приходи под своим именем.","1220":"Отец пишет сыну на старый номер и однажды на вокзале узнаёт в чужом парне его манеру пожимать плечами. Он отдаёт парню куртку сына — и впервые улыбается: сын вернулся в мир через всех молодых.","1221":"Три друга за прощальным ужином: один едет на север, другой уходит из отношений, третий бросил музыку. Тост за непохожих возвращает им дух флибустьеров — и бригантина их мечты снова поднимает паруса.","1222":"За ночь обвал рынка развалил его проект: инвесторы исчезли, сотрудники разбегаются. Без зонта он идёт пешком сквозь дождь и понимает: крах и «потом блеснёт» — одно небо, лишь бы идти своим шагом.","1223":"Десять лет вдовец не говорит о жене вслух — пока во сне она не появляется у окна, и он не выговаривает всё сразу. Просыпается до последнего слова и до утра держит за подушкой телефон с её голосовыми.","1224":"Два брата через семь лет снова ночуют в мотеле, где писали на стене планы: ремонт съел надписи, хозяин умер. Они не грустят вслух — брат шлёт фото гусиных следов на снегу: и следы наши, и полёт.","1225":"В девятнадцать их развела его мать: она мешала экзаменам. Через десять лет они встречаются во дворе, ночью он выкладывает песню о том дне без имён — а утром в комментариях её ответ той же строфой.","1226":"Отец-слесарь, у которого долги отняли мастерскую, завещал: когда дом снова заработает — придите на могилу и скажите. Годы спустя сыновья возвращают её и докладывают по видео работающего станка.","1227":"Лётчица и смотритель маяка вместо квартиры выбрали одну встречу в год в одном порту. Уговоры жить нормально почти губят их в быту — и они возвращаются к годовому ритму — им больше ничего не нужно.","1228":"Она двадцать лет жила в его городке и уезжает одним чемоданом без ссор. Утром он читает её строку: река не уходит от горы — река идёт к морю, — и впервые отпускает, глядя на воду.","1229":"Контрактник едет из рейда домой: уезжал в апрель с шумом ив, возвращается в январский снег, не звоня — хочет с порога. Никто не встречает, и у подъезда в снегу он находит сына, выросшего на голову.","1230":"Парень каждый рассвет бродит у тростника: на другом берегу она, и мост он не решается перейти. Однажды в тумане на середине моста он видит её силуэт — и она, заметив его мокрые кеды, шагает первой.","1231":"Уезжая по вахте, слесарь каждый вечер снимает стакан воды на видео и говорит дочке, что её тень была в воде. Через год он возвращается с двенадцатью месяцами видео — дочка смотрит их вместо сказки.","1232":"Через год после краха всё выровнялось, но в тихий весенний день у него дрожат руки, как лепестки без ветра. Он перестаёт бороться: идёт по аллее под лепестками и разрешает себе дрожать в их ритме.","1233":"Разорившийся герой пишет любимой: пусть его делают тростником в чужой воде, он всё равно хочет встречи. Ответ приходит одной строкой — адресом рынка Нанивы, — и он впервые за год выходит из дома.","1234":"Оператор, пять лет снимающий чужие беды, уверен: вместо сердца — чек-лист. Но когда на закате бекасы поднимаются из камыша, он плачет в кадре — и оставляет этот дубль в ролике без комментариев.","1235":"После тяжёлого диагноза герой живёт оставленный врачами год как ход до цветения: сажает сакуру, доходит до моря. Под собственной вишней он впервые хочет не умереть вовремя, а увидеть следующую весну.","1236":"Мужчина устраивает сердцу разбор на скамейке: смерть случается однажды, а ты болишь каждый день. Он меняет лекцию на прогулку — парк, рынок, крыша — и замечает: меньше всего сердце болит в движении.","1237":"После панической атаки мужчина заводит тетрадь тысячи желаний: трамвайный круг, свист, море в будний день. На открытом микрофоне зал дописывает его список — и тысяча не кончается, что только радует.","1238":"Родня двадцать лет стыдит её на застольях, но на микрофоне она вместо оправданий выводит литанию без страха — зал перестаёт хихикать и подхватывает рефрен, а в последнем ряду встают родные.","1239":"Вокалист, обожжённый индустрией, мечтает стать просто птицей без имени. Уличная певица в сквере поёт о его ушедшей славе — и он впервые за годы поёт честную песню в подземке, где она первая в зале.","1240":"На мраморный храм собирает приход, а дворник, моющий залы годами, в долю не входит: у богатых камень, у него ноги. Через год град ломает недостроенную башню, а дворник всё так же ходит по этажам.","1241":"Сельский чат месяц воюет из-за размытой дороги — сотни сообщений, ноль действий. Старый ювелир предлагает каждой стороне по одной фразе, как бусине на общей нити, — и за вечер дорога вычищена.","1242":"Он находит в шестьдесят женщину, которую любил в двадцать: она седая, с садом, выращенным вместо него. На вопрос о былой красоте он отвечает: красота теперь стоит во дворе и пахнет яблоками.","1243":"Глаз героя после разрыва — шпион: находит бывшую в сториз и похожих куртках, а сердце-архив всё хранит. Он уезжает и сносит аккаунты, пока не заключает перемирие: глазу — новое, сердцу — старое.","1244":"Он сорок лет жил по инструкции и не знал слова «любовь». На перроне он встречает лицо и за одну зиму отдаёт квартиру и пенсию — все зовут его безумцем, но теперь он знает значение слова.","1245":"Их двор с лавром и белой лестницей снесли под парковку, она молчит два года. На фото руин она впервые отвечает строкой о приснившемся лавре — и парк в его сердце снесён окончательно.","1246":"Шеф-повар готовит безвкусные для себя блюда: его сердце сорок лет пахнет улицей, которой нет рядом. В шестьдесят пять он закрывает ресторан и плывёт на Восток — и в гавани впервые чувствует вкус.","1247":"В баре ночного поэта два клана — вина и дымки — спорят, кому он принадлежит. Поэт выносит вердикт песней: оба братья, но ночь его, и с этого вечера его будильник звенит в половине одиннадцатого.","1248":"Он продал квартиру, переехал на другой континент и выучил её язык в сорок — весь город зовёт его безумцем. Но на её балконе он называет вещи именами: это была любовь, и он бы повторил ещё раз.","1249":"Хитрец, всю жизнь уходивший от ответственности, в шестьдесят три сидит в гараже без телефона и впервые честно пересчитывает долги и несделанные звонки. Утром он выходит навестить всех, кого обыграл.","1250":"Двадцать лет живя по отелям, мужчина на чужом дне рождения понимает, что не помнит цвета стен своей квартиры. Он оставляет чемодан и впервые за годы спрашивает семью, что приготовить к ужину.","1251":"Восемь лет на тридцатом этаже не дали ему увидеть компанию целиком: с каждого квартала она выглядит по-разному. Он обходит здание пешком — с базара, с моста, из парка — и впервые пишет правдивый пост.","1252":"В вымершем осеннем поле герой находит синюю горечавку, распустившуюся под заморозками, будто не знавшую, что время прошло. Он просит у цветка манеры: расцветать в последний час спокойно, не паникуя.","1253":"Певчая птица Роберт с утра до вечера поёт своё имя на каждом суку — песня у него одна, и она хорошая. Осень срывает золотые листья, и он улетает петь в другое небо, оставляя лугу свой мотив.","1254":"Родные холмы просят реку остаться — они так долго её любили. Но река отвечает одной песней: её долг — бежать, разбиваться о пороги и добежать до моря, ведь любовь без пути была бы стоячей водой.","1255":"В городе, где всё куплено, оркестр выходит на сцену: струны — о любви, ставшей товаром, медь — о глушащем бедных золоте, флейта — имена списанных в расход. Скрипки говорят за всех: мы всё за любовь.","1256":"Мужчина возвращается на марши — травяную полосу между морем и землёй: вечер приносит прибой и золотые травы, ночь зажигает звёзды, как свечи. Он не ищет ответов — простор отвечает за него.","1257":"Старый корабль, чьи доски помнят настоящие залпы, приговорён к слому — поэт встаёт у причала против бумаг. Лучше вернуть гордость морю под грозу, как воина: людской голос отменяет слом.","1258":"Разбитый наутилус показывает всю жизнь: камера за камерой, каждая шире прежней. Поэт берёт с раковины обещание: не жить в отжившей камере, а строить палаты шире и уходить без вздоха.","1259":"Один зов летит через горы и долины, и каждый откликается по-своему: лесник бросает топор, пастух оставляет стадо, кузнец гасит горн. Никого не заставляют — дома за спиной, и вся долина встаёт в ряд.","1260":"За окном тянется ряд холмиков — солдаты без имён, и никто не знает, кого оплакивать. Житель рядом не вернёт им адреса, но приносит цветы и ухоженную траву — память, которой не нужна фамилия.","1261":"Первый снег идёт с заката: дочь на коленях у отца хлопает в ладоши, а он знает — снег укрывает и маленький холмик, где его Мейбл. Снег ложится и на неё, мягко, как прощение.","1262":"Рыцарь собирается за дальним Граалем, а у его ворот нищий просит воды. Он бросает золото, но нищему нужен хлеб — и, протянув свой ломоть, рыцарь в грязном лице узнаёт то, ради чего ехал через мир.","1263":"В полночь свора выкуривает барсука из норы, и весь день он дерётся отчаянно и без злобы, пока круг смеётся. Один в этом кругу молчит и не находит голоса крикнуть «хватит» — и его молчание хуже собак.","1264":"Проводник ведёт друга той самой тропой и просит идти тише: в ежевике у соловья гнездо — весь концерт мира в этой колючей тени. Они стоят не дыша, и тайное счастье живёт, пока его охраняют молчанием.","1265":"Пристань помнит, сколько учеников ушло с Граймсом в море и сколько вернулось без него. Город шепчется за спиной, но стучится лишь за рыбой — и однажды старик остаётся совсем один, с лодкой и собой.","1266":"Почта приносит сыну портрет матери, умершей в его детстве, — рамка распахивается, как дверь в старую кухню. Он хочет поцеловать её, как мамины ладони, но пальцы встречают только прохладу холста.","1267":"Хозяин хоронит домашнего зайца и пишет надгробие, как человеку: ни одной гончей за всю жизнь, ни одного утра с росой на лапах. Тини кусал пальцы без злобы, требовал салат и правил ковром у камина.","1268":"Он на одном острове, она на другом: её голос доносится через пролив так близко, что слышно дыхание, и так далеко, что не достать рукой. Закон моря не отменить — и любовь звучит через пролив всю ночь.","1269":"Друг возвращается на старые холмы, где они пели и спорили о песнях, — а тот уехал и умер вдали. Кукушка кричит их общим мотивом: пусть птица поёт за двоих, пока он может ходить по этим холмам.","1270":"Студент двести лет назад оставил книги и ушёл учиться к цыганам — за знанием, которого не выдают дипломы. Пастухи видят его на холмах не стареющим, и поэт не зовёт: наш век устал и отравлен сомнением.","1271":"Последний менестрель отказывается от платы: песни не продаются, они вспоминаются. Он играет для тех, кто помнит старую доблесть, — и в песне строка про человека, ни разу не сказавшего «это моя земля».","1272":"Каждый канун Иванова дня к окну башни приходит рыцарь, которого дама давно похоронила. Призрак называет своего убийцу — её мужа, — оставляет на её запястье клеймо-ожог, и она уходит в монастырь.","1273":"Ночью через границу идёт рейд: чужие копыта на склоне, вдовы плачут в дверях. Но родня с соседних долин слышит клич и берёт холм раньше врага — рёв встаёт над Ларистоном, и рейд ломается о общий крик.","1274":"Корабль уходит от пристани, как птица: ветер гнёт крепкую мачту, и в солёном ветре песня честнее разговоров на суше. Пусть берег зовёт уютом — у моря свой зов, и это расставание не грустит.","1275":"Странник далеко от своего края и знает одно слово, которое не стареет: домой. Он просит жаворонка спеть этот зов через холмы до родной долины, где цветок ещё в бутоне и лист ещё на дереве — всё ждёт.","1276":"Пусть о небе спорят богословы — он честно признаёт «не знаю». Но через все бури держится одного: доброта есть и не обманет, и этого достаточно, чтобы идти и делать доброе, не боясь последнего берега.","1277":"Полночный шум поднимает деревню: мужики с вилами крадутся через луг — а врагов нет, только пустой луг под луной. Домой возвращаются, посмеиваясь друг над другом, но по первому крику придут снова.","1278":"Двадцать лет спустя он пишет Мэри дрожащей рукой: старость стучится к обоим. Но в прожитых годах он не находит в любви ни усталости, ни убывания — она растёт с ними, как дерево с домом.","1279":"Город горюет о певцах — их песни остались, им аплодируют посмертно, — но рядом те, кто нёс крест молча, без песни и имени. Он решает спеть за них: это сцена, которую им не дали при жизни.","1280":"Весь дом выходит сажать яблоню — яма, корни, первый полив — и каждый знает: это не для себя. Дерево переживёт посадивших, их споры и праздники: птицы сядут на ветви, а яблоки созреют уже при внуках.","1281":"Он зовёт спутника в долину глубокой тени, где путь потерян, а сам не знает даже своего имени. Одному в такой темноте нельзя: он протягивает руку, не обещая ничего, кроме того, что рядом будет кто-то.","1282":"Старый проводник уходит с последнего маршрута: возраст и равнина требуют покоя. Горы провожают его молча, как старые друзья, которым обещают вернуться, — он уезжает, зная, что перевал будет ждать.","1283":"После разрыва он годами пишет неотправленные письма с придуманными датами. Найдя стопку на антресолях, он понимает, что писал не ей, а себе, — и последнее письмо всё-таки опускает в ящик без адреса.","1284":"После её ухода хозяин и старый пёс каждый вечер ходят к одной двери, деля ожидание пополам. Однажды пёс первым отходит и ложится у ног человека — и тот решает: завтра откроет дверь не для неё.","1285":"После громкого разрыва она хранит его номер как последнюю дверь: каждый вечер палец доходит до кнопки вызова и убирается. Она стирает номер с благодарностью — и в ту же ночь впервые звонит он.","1286":"Путешественник с сотнями маршрутов раздаёт слово «самый» всем экспедициям — пока однажды не произнесёт его вслух один раз, про неё. Она смеётся: из всех путешествий это самое короткое — до её окна.","1287":"Солдат пишет жене при слабом огне в домике из четырёх досок: смерть за спиной ближе, чем она, но он с ней не соглашается. В финале он впервые измеряет расстояние до любимой не вёрстами, а днями.","1288":"Двадцатилетняя так поёт главную песню лета, что весь двор замирает: пусть голос долетит до того, кого она ждёт. Когда он возвращается и спрашивает, что это была за песня, она отвечает: это была ты.","1289":"Портовый живописец продаёт дом и мастерскую, чтобы повторить красками голос певицы, — и выкладывает перед её окном миллион алых роз. Корабль уплывает с ней, а он остаётся закрашивать свою боль синим.","1290":"Воскресеньями Иван и Зиновий ссорятся у экрана из-за всего: судьи, зарплаты, порядок. Жёны не вмешиваются — так держится их союз, и когда матч кончается, они уже договорились на следующую перепалку.","1291":"Пара годами спит рядом чужими — пока петухи во дворе не кричат всю ночь так, что оба не спят и слушают. Утром она впервые за годы спрашивает, не спалось ли ему, и вопрос растёт в длинный разговор.","1292":"Удачливый обыватель весь вечер объясняет себе, что всё по закону, а совесть молчит напротив. От этого молчания весёлый монолог трещит по швам — к ночи он впервые отвечает вслух за неё и теряет сон.","1293":"Когда руководитель зависает над обрывом, старший спрашивает команду: был он своим — пойдёшь? Двое молчат, один разматывает верёвку — и на дне он получает не награду, а имя «друг» на всю жизнь.","1294":"Ветеран называет у карты своих дорог имена погибших. Внучка доказывает, что он не виноват, он соглашается — и всё равно трижды произносит «всё же», пока она однажды не повторяет это слово за ним.","1295":"Пять лет друзья не разговаривают, разойдясь по лагерям, — пока ему не снится старая лестница и друг, кричащий на общий призрак. Проснувшись, он набирает знакомый номер и не знает, снимут ли трубку.","1296":"После похорон последнего из их костра ветеран заводит тетрадь, записывая за каждым ушедшим песню, шутку и слово. На рассветное построение он выходит один, но не один: за спиной стоит вся его часть.","1297":"В любимом дворе встали заборы и краны, объявили новое название, но каждый вечер он приходит к забору рассказывать, какие были окна и голоса. Табличку вешают — а двор отвечает сиренью из-под бетона.","1298":"Ночной троллейбус приходит на конечную как добрый зверь: здесь плачут в кулак и выходят на рассвете человечнее. У двери водитель оставляет место для потерпевших крушенье — и оно всегда занято.","1299":"Герой годами ездит в командировки в город Нет, где диваны из фальши, а семья его живёт в городе Да. Однажды он сдаёт обратный билет без объяснений и впервые поёт в вагоне во весь голос.","1300":"Старик перебирает на скамейке всё, что сшилось с городом: первый шёпот, первый бой, кровь друзей. Он мог бы уехать к сыну в комфорт, но остаётся и здоровается с каждым углом по имени.","1301":"Пара на грани развода оставляет каждому по одной комнате тайны — не ложь, а берег, — потому что полная понятность убила бы нежность. Утром они впервые за год завтракают молча и легко.","1302":"Мужчина уезжает искать страну, где всё готово и ждать никого не надо, — а настоящими новостями остаются письма жены. Он возвращается на свой двор и понимает: та страна построена его руками.","1303":"Жизнь несётся галопом — сделки, смерти друзей, любимые станции мимо, — и всадник умоляет скакунов о скорости чуть меньше максимальной. Кони впервые слушают: он едет шагом и наконец видит лица.","1304":"Переезжая в дом, где не проживёт и десятилетия, мужчина сажает у порога виноградную косточку — сосед смеётся. Через годы к дому приезжают взрослые дети и едят виноград, не зная, кто его посадил.","1305":"На ночном пароме кто-то включает старый вальс — и вместо прощальных слёз палуба переселенцев танцует в бахилах и кедах. Двое незнакомых договариваются о встрече на новом берегу: вальс стал их домом.","1306":"На юбилее взрослые солидны, пока старая пластинка не ставит мелодию детства: дядя с усами первым выходит в круг, за ним весь зал. В конце самый серьёзный гость просит тостом вернуть мальчишество.","1307":"На выпускном объявляют медленный вальс, и робевшая пара решает не слышать гудок: их танец дольше положенного, сторож гасит не свет. Утром у обоих свечи на подоконнике и правило — сейчас значит сейчас.","1308":"Тревожный человек расписывает запреты — не выходить, не звонить — и комната становится крепостью: он король и пленник. Когда авария гасит свет, он открывает дверь — во дворе годами ждали живые соседи.","1309":"После ссоры внук приезжает к бабушке и не находит слов о важном — просто моет посуду, пока она рассказывает про соседей. К ночи ссора растворяется сама: всё святое здесь, на кухне с запахом супа.","1310":"Моряку предлагают подводное царство — только без неё. Он перебирает чудеса и в каждом слышит отсутствие её голоса, отдаёт царство морю и строит дом, где самое богатое — её шаги на лестнице.","1311":"Изгнанник пишет домой письма с одной темой — когда вернусь, — и просит не смеяться над съеденными городами и привычками. На пороге никто не смеётся: дверь открывают до стука, и он входит молча.","1312":"Вернувшись на родную площадь, он не находит никого: золото соседних усадеб выдавило деревню за море. Остались танцы в его памяти — пары под дубом, кружившие до темноты, — живые, пока их кто-то помнит.","1313":"Потеряв любовь, он ушёл отшельником в чащу, пока хижину не находит странница с бедой о пропавшем женихе. Она отталкивает обнявшего незнакомца — и узнаёт голос: двое отчаяний выходят из чащи вместе.","1314":"Кошка — любимица дома Селима — тянется за блеском золотых рыбок, и скользкий край ванны её топит: она восемь раз поднимает лапы и тонет, не позвав на помощь. Гордые не кричат о спасении.","1315":"На утёсе завоёванной долины последний бард Уэльса поёт в лицо королю: песня зовёт духов древних вождей и предрекает захватчикам позор. Договорив, он шагает с утёса в реку — песня остаётся над страной.","1316":"Утро сияет — жаворонки поют, поля цветут, — но для него всё глухо: друг умер молодым. Радости мира перестали с ним разговаривать, и слёзы — единственный дар памяти, который он приносит без стыда.","1317":"С холма взрослый смотрит на мальчиков у реки: они смеются, гоняют мяч, не зная, что за каждой забавой поджидает взрослая боль. Он не хочет предупреждать — пусть неведение продлится, скорби подождут.","1318":"В её лице разбит сад: розы на щеках, белые лилии, вишни на губах. Ни ангелы, ни смельчаки не войдут, пока вишни не крикнут, что поспели, — и он готов ждать у ограды, ведь ключ один, у неё.","1319":"Когда Коринна поёт о радости, лютня оживает, но горькая песня лопает струны. Сердце слушателя настроено в тон её лютни и рвётся вместе с ними, — он просит петь о добром, чтобы оба зазвучали целыми.","1320":"Зимние ночи длиннее, буря бьёт в башни, по стране гаснут окна — а в его доме пылают камины, переполнены чаши, и он объявляет танец. Пусть ночь тянет свои часы: они растянут веселье до рассвета.","1321":"Хозяин скромного ужина зовёт друга на оливки, сыр и канарское вино, обещая вечер без скандалов, а за столом — Вергилия вслух. Чтобы друг точно пришёл, он признаётся: про блюда он немножко соврёт.","1322":"Отец хоронит семилетнего сына — лучшее, что он создал в жизни, — и прощается, как прощаются с лучшим произведением. Он клянётся: больше никогда не любить так сильно, чтобы потеря рвала пополам.","1323":"Мальчик — самый маленький в труппе королевы — играл стариков лучше стариков, но умер до первой большой роли. Занавес закрылся сам: сцене не хватило одного человека, а его голос зал знал раньше имён.","1324":"Поэт, добиваясь её внимания, гоняет рифмы по учебнику — но строки выходят мёртвыми. Отчаявшись, он слышит голос музы: вся техника не стоит одной правды из груди — пиши сердцем, остальное приложится.","1325":"Он прощается с любовью как с гостем, чья власть кончилась: она дошла лишь до праха, а он вырос за её границами. Уму он велит копить то, что не ржавеет, и отпустить всё, что увядает, — и идти выше.","1326":"Двое расстаются по-взрослому: рукопожатие навсегда, обеты отменены, любовь лежит при смерти. Но он оставляет дверь: последним поцелуем у её одра любовь ещё можно поднять из смерти в жизнь.","1327":"Он провожает флот к земле, где ещё нет ни дорог, ни имён: ваше имя — ваша работа, а работа — океан. Прощание — как благословение: пусть ветер наполнит паруса и донесёт вас целыми до другого берега.","1328":"Он долго гонялся за ней глазами, словами и надеждами — и зверь сдался: она возвращается к нему сама, как загнанный олень к охотнику. Он опускает оружие: война кончилась не победой, а её приходом.","1329":"Шторм за штормом несёт его корабль по океану, звёзды спрятались за облаками — и только её взгляд светит сквозь мрак. Корабль трещит, но не сворачивает с курса: за штормом обещана тихая радость.","1330":"Сирена поёт Улиссу про покой: оставь вёсла, любовь без труда. Он отвечает без верёвок: без труда радость ничего не стоит, а нечестный мир хуже честной войны — и сирена сдаётся, чтобы быть завоёванной.","1331":"Безответно любящий просит ночь усыпить его горе: приди, брат смерти, закрой мои глаза и не буди днём. Сон — единственный, кто не задаёт вопросов: он уводит туда, где не стыдно жить без ответа.","1332":"Раз в год деревня делает девушку королевой на сутки: венок, ленты, хоровод от площади до леса. Завтра она снова станет простой девчонкой, но сегодня танцы и смех не кончаются до темноты.","1333":"В полночь морские девы уходят домой — в тихие гроты, где нет ни ветра, ни людей: они подражают умирающим волнам, и море закрывается над ними, как дверь. Их песня остаётся на поверхности.","1334":"Он смотрит с упавшего вяза, как пахарь ведёт упряжку в блестящем ярме: их друг убит во Франции два дня спустя после прибытия. Влюблённые идут из лесу, а плуг при любых вестях заканчивает борозду.","1335":"Каждое утро молодая медсестра появляется в палате, и та светлеет от её ясного лица. Но ночи, смены и чужие боли тают в ней по капле, как закат, — и никто не спрашивает, во что ей обходится этот свет.","1336":"Он слушает город как орган: колокола Сент-Маргарет наигрывают старые мотеты, под ними гудит лавка и течёт река людей. Город играют тысячи рук сразу — надо только встать и слушать его музыку.","1337":"Узник смотрит через решётку на птиц: те порхают, строят, поют и любят без спроса — их день устроен без разрешения. У него осталась одна воля — смотреть, и он запоминает, как устроена свобода.","1338":"Четверо вспоминают, как впятером на одного, ночью и без суда, убили рыцаря — у того есть братья, не прощающие позорных смертей. Месть приходит той же дорогой, что убийство: по двое, по трое, молча.","1339":"Не открывая глаз, он просит её подумать о нём одной мыслью под звёздами. Летняя ночь тает с каждым вдохом, утро скользит в окно — темнота, позволявшая им быть близкими, отпустит их в разные миры дня.","1340":"На границе сумерек двое поймали настроение и крикнули: останься. Оно остановилось — и умерло у них в руках, как птица в клетке. Радость живёт только на воле: отпусти — и она вернётся летать.","1341":"Жених поёт свой свадебный день от рассвета до ночи: муза будит невесту, девки поют, нимфы рвут цветы, толпа ведёт её к венцу с песней. Ночь благословляет молодых и просит у неба детей.","1342":"Офисный человек на сеансе терапии «вспоминает» пышную жизнь в Александрии: море, ночная пляска, запахи портовых улиц. Пусть она была сном — жить он теперь будет по её правилам, то есть красиво.","1343":"На похоронах основателя оратор называет тиранию заботой, и молодая сотрудница записывает, что говорилось на самом деле. Через год её список читают вслух — хвалитель аплодирует, не узнав своей речи.","1344":"Канатоходец год не выходил на канат — страховка стала его тюрьмой. В ночь бенефиса он снимает её ради света над собой и бездны под собой и танцует медленнее всех: зал замирает от красоты.","1345":"Два певца спорят дуэтом: один поёт о любви как главном деле жизни, второй — о служении дороже свиданий. В финальном куплете оба поют чужую строфу по своим нотам — и спор становится общим голосом.","1346":"Сын боится не конца умирающей мамы, а своей паники: в её разговорах о тихих волнах он слышит покой и в последнюю ночь просто держит её руку. После ухода он заводит черепаху — и горе перестаёт кричать.","1347":"После обвала года — работа, здоровье, отношения — он уезжает в осеннюю деревню и вместо тоски находит порядок: всё увядает по расписанию. Он перестаёт чинить свою осень и слышит в ней новый круг.","1348":"Больной устроил в квартире «красивую смерть» — свечи, музыку. Ночной лай собаки говорит: конец будет бытовым, и это почти утешение. Наутро он отменяет режиссуру и просит завтракать при открытом окне.","1349":"Братья, не говорившие после дележа наследства, сходятся на реставрации иконы матери и ссорятся из-за кистей. Закончив, выносят её на свет: руки трёх ангелов образуют круг — и пьют чай из одной чашки.","1350":"Спивающийся друг шлёт ночью: «всё лучшее было тогда». Тот отвечает не речами, а списком на сегодня — звонок, рыбалка, общий анекдот — и приезжает с удочками: друг впервые за год смеётся раньше него.","1351":"Два друга-начальника месяц «тренируются» с KPI и разбором ошибок, потом сжигают план: раз в неделю — в старый ботанический сад просто дышать. Лучшие решения года оба принимают там, а не на планёрках.","1352":"Лидер, одиночка и новичок строят город из песка — каждый свою улицу, город не сходится. После «наводнения» из лейки улицы соединяют в один и подписывают всеми тремя именами по алфавиту.","1353":"Два коллеги спасаются от казённой скуки рифмованными колкостями на служебных бумагах. Перехваченная записка грозит объяснительной — они приносят начальнику оду и получают отдел, где можно смеяться.","1354":"Она встречает его только в темноте, пока подруги не убеждают: любить вслепую — терять жизнь. Включённый ночью фонарь стоит ей его навсегда — новый союз она строит вслепую, а фонарь остаётся на полке.","1355":"Ей предлагают многолюбие как свободу, но знакомства не случаются: сердце второй раз не откликается. Бывший приходит проверить «свободу» и застывает у двери, услышав за ней ту же старую пластинку.","1356":"На даче два соседних домика: она готовится к свиданию с бывшим, он — с новой знакомой, и оба не видят друг друга через смежный забор. Обе встречи отменяются — и следующую они назначают друг другу.","1357":"Праправнук находит в прадедовском дневнике: снегирь запел марш в день гибели командира. Скептик проверяет: попугай молчит, а снегирь за окном подхватывает марш — и он впервые плачет от попадания.","1358":"После потери друга разговоры о нём обрываются раньше слов. Он слушает соловья в саду их общего детства — птица поёт невыговоренное, — и отправляет запись родным друга со строкой «здесь он ещё поёт».","1359":"Молодой поэт делает вирусную верлибру и получает от мастера письмо: «приманная лёгкость». Он идёт разоблачать зависть, но мастер заставляет сто раз читать её вслух — до границы между твигом и стихом.","1360":"Из шкафа погибшей дочери выпадает балалайка. Отец, не умея играть, учится по памяти её фальшивых аккордов, а на годовщину выходит к школьному двору и играет фальшиво нарочно — так же, как играла она.","1361":"Астроном-любитель поднимается на крышу посчитать жизнь до конца — счёт рушится на первой звезде, дна нет. Зато крах рядом с бездной становится правильного размера: утром он разберёт завал по одному.","1362":"Три одноклассника возвращаются в ущелье, где клялись славой: один почти известен, второй при деньгах, третий живёт у водопада. Гул глотает имена одинаково — и оставшийся помнит всех троих наизусть.","1363":"Уволенный идёт через парк и видит лягушачью дорожку, по которой торопился на работу каждый день, — впервые обходит её. Месяц спустя водит детей: смотрите под ноги, здесь чьи-то дорожки.","1364":"Малыш, боящийся темноты, придумывает с папой сказку: ночь — чёрный кот, день — серенькая мышь, которую кот отпускает поутру. В детском саду правило записывают на доске — и вся группа засыпает.","1365":"Хирург, вчера потерявший пациента, а сегодня спасший человека, не спит: для спасённого он бог, для неспасённого — червь. В операционной он вывешивает обе таблички и учит интернов держать обе правды.","1366":"Уволенный топ-менеджер спрашивает на крыльце, зачем живут отец, брат и сосед. Ответы про обед, рыбалку и честное «не ведаю» оказываются честнее миссии на визитке — и он переписывает резюме их словами.","1367":"Агент обещает певице «кухни-стадионы» за отказ от репертуара — она отвечает словами басни: ворона знает себя. Через год его новые звёзды растворяются, а её районный зал полон тех, кто пришёл за своим.","1368":"Художник-самоучка после отказа галереи год строит свой мир на стенах квартиры — без школы и кумиров. Когда галерея сама стучится, он соглашается продать стены, но никому не открывает их природу.","1369":"Потомок крепостных находит оду предка, которую тот сорок лет боялся печатать, и снимает истории земляков. На премьере потомки кандалов и вольности аплодируют стоя — ода допета чужими голосами.","1370":"Влюблённых разводят на два года — каждый строит клетку, чтобы пережить разлуку, и бережёт по одному крылу. Весной они встречаются у будки с ключами и открывают клетку не друг другу — а своему страху.","1371":"Ночь после ссоры тянется до пяти утра. В пять оба возвращаются: он на крышу, она на балкон — и молча встречают рассвет, одновременно сказав: «как легко дышать». Ночь впервые становится их общей.","1372":"Певец на ужине уехавших земляков поёт не о деньгах, а о запахе речки, где все выросли. Зал замолкает, половина звонит мамам, а хозяин вечера платит и уезжает первым — не в офис, а в родной город.","1373":"Сварщик теряет зрение и стесняется трости — внучка вешает на неё провод, превращая в стойку для караоке. Он выходит с ней к гостям как с инструментом и поёт впервые за двадцать лет: стыд кончился.","1374":"Отец не звонит сыну и шлёт ящик винограда с инструкцией: дави, запирай, жди. Вино готово к дню, когда отца не стало: на дегустации сын читает письмо и поднимает кубок в сторону отцовского сада.","1375":"Выгоревший до ощущения собственной смерти, он пишет себе некролог и вешает в рамку. Каждое утро он проверяет его на правду — через год дописывает внизу: ошибся, этот жив. Рамка становится дверью.","1376":"Незрячий с детства парень сводит треки соседским группам на слух, не выходя из дома. Когда один выстреливает, студия зовёт его к себе: то, чего зрячие проглядели, выходит с пометкой «сведено на слух».","1377":"Над умершим другом один рыдает все сорок дней, второй держится. В четыре утра на дежурстве терпеливый ломается — и рыдающий обнимает его первым: сорок дней кончаются общим завтраком, а не графиком.","1378":"Рэпер пишет заказной хвалебный трек для свадьбы медиамагната, но в бридже вставляет честную строку про девушку из охраны. Через год цитируют только бридж — и она первой пишет ему спасибо.","1379":"Он первым пел в подъезде с гитарой — теперь там лейбл и тридцать клонов его стиля, а его забыли. На юбилее он выходит последним и играет куплет, по которому зал вспоминает, чьи это аккорды.","1380":"Девушка в чужом доме невидима: стирка, посуда, тишина. Подъездный певец выпускает песню с её смехом в сэмпле — и район впервые зовёт её по имени. Она снимает первый сторис — себя, лицом к камере.","1381":"Она отпускает любимого искать пропавшего на вахте друга и остаётся править их общим делом. Третья зима она встречает паромы — и в тумане узнаёт его по чайкам, вставшим над водой.","1382":"Запертая роднёй в пансионе за наследство, она выучивает отливы. В отлив она проходит мимо сторожа с чемоданом, как соседка на рассвете, и садится в лодку друзей — побег не тайный, а при людях.","1383":"Новичок с визиткой — лейблы, курсы, регалии — скучен залу, а молчаливая девушка без представления заставляет его встать. Ведущий отменяет баллы: представляться не нужно — и новичок рвёт визитку.","1384":"Вокалиста клуба увольняют за любовь к дочери владельца. Он уходит в церковный хор — впервые поёт без чаевых, а летом возвращается на клубную сцену гостем так, что хозяин встаёт: не победа, а мир.","1385":"Имя казнённого поэта вычищено из программы, книги изъяты. Учительница читает его строфы в подземном переходе, к ней присоединяются бывшие ученики — вечера идут, пока книгу не возвращают в печать.","1386":"Три враждующих квартала собирает внук старого двора: песни прадеда на трёх языках, по куплету без перевода. К третьему подпевают все, не разбирая букв, а ссора о воде кончается общим ремонтом.","1387":"Разорившийся наследник фонда работает курьером и ночами пишет списки несправедливости — без имён. Вместо сети он читает их на кухне общежития, и злые столбцы превращаются в общую кассу взаимопомощи.","1388":"В юности он писал весёлые песни о любви, после краха не может их слушать. На свадьбе сестры он дописывает старой песне куплет про радость без денег — и две половины жизни складываются в одну.","1389":"Он уехал без отпуска проститься с умирающим учителем — и попал в камеру. Там он составляет список того, что не отняли: слух, память, рука. На допросе вместо оправдания он читает его — дело закрывают.","1390":"Экскурсовод водит школьников по руинам завода и показывает не плакаты, а скворечники в цехах: скворцы гнездятся, берёза проросла сквозь кассу. На вопрос, что пережило империю, он отвечает пением птиц.","1391":"Тридцать лет стекольщик полировал чужие витрины — весь город видит себя в его работу. После смерти матери он чистит её мутное зеркальце и впервые долго смотрит на своё лицо, не брезгуя морщинами.","1392":"Ресторан шефа лопнул в долгах — он печёт хлеб в отцовской печи и раздаёт соседям, беря и «потом». Очередь за хлебом длиннее былой за устрицами, а сосед-должник возвращает старый долг дровами для печи.","1393":"Тридцать незнакомцев идут искать легендарного тренера, который собирает человека. Через год дорог и ссор на адресе пусто — только зеркало: в нём тридцать их, и наставник собран из самих искателей.","1394":"Инженер строит дамбу и полосу против лесного огня, посёлок смеётся: здесь не горело никогда. Летом огонь приходит ровно по прогнозу и встаёт на краю посёлка — вечером насмешники приносят ему лопаты.","1395":"Тенора десять лет терзали за старомодный голос — ушёл в аранжировки. На юбилее учителя он выходит и поёт ту же газель, ни на йоту не уступив: зал встаёт с критиками, и он записывает альбом под себя.","1396":"После драки двух половин двора тихий старик сеет цветы на месте драки. Через лето пятачок цветёт и драться негде: мальчишки поливают, обе половины ставят общую скамейку, турник возвращают на клумбу.","1397":"Два брата не говорили десять лет. Младший возвращается ночью, когда паром ушёл, и идёт по дамбе с одним фонарём — навстречу выходит старший со своим: он тоже не спал. Остаток пути они проходят вместе.","1398":"Братья делят дом до отмены общего обеда. Средний пишет дворовые песни про турник, кувшин и чинилку крыши — на сходе вместо суда он поёт их, и братья спорят, кто в какой песне был первым куплетом.","1399":"На пароходе бабушкиного юбилея гости плачут заранее — вдруг последний раз. Арфист вместо траурных песен играет плясовую: оплакивать наперёд — значит терять день. К вечеру плачущие танцуют с бабушкой.","1400":"Ночь на мосту: он перебирает причины, а душа спорит — кто будет пить твой чай, кто прочитает твои бумажки? Рядом не улетает птица. К рассвету он пьёт чай в круглосуточной, и она перелетает следом.","1401":"Год на привозной воде — по радио: паводок пошёл. Ночью половина города выходит на берег, как выходили деды: воду встречают стоя. Утром город умывается той водой и мирится с соседями через мост."}$cj$::jsonb)) AS payload(data),
     jsonb_each_text(payload.data) AS v(sort_key, brief)
WHERE i.sort_order = (v.sort_key)::int AND i.is_published AND i.generator_story IS DISTINCT FROM v.brief;
